window.MH_TR["ch00"]={"t":"\u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05db\u05d7\u05d5\u05d6\u05d4","l":[[1.0,"\u05e2\u05dc \u05d4\u05e9\u05d5\u05dc\u05d7\u05df \u05de\u05d5\u05e0\u05d7 \u05e9\u05e8\u05d8\u05d5\u05d8 \u05e9\u05dc \u05d7\u05dc\u05e7 \u05d0\u05d7\u05d3: \u05db\u05de\u05d4 \u05d4\u05d9\u05d8\u05dc\u05d9\u05dd, \u05e2\u05e9\u05e8\u05d5\u05ea \u05de\u05d9\u05d3\u05d5\u05ea, \u05e1\u05de\u05dc\u05d9\u05dd, \u05d4\u05e2\u05e8\u05d5\u05ea \u05d5\u05d0\u05d6\u05d5\u05e8 \u05db\u05d5\u05ea\u05e8\u05ea."],[11.0,"\u05e8\u05d5\u05d1 \u05d4\u05d0\u05e0\u05e9\u05d9\u05dd \u05e8\u05d5\u05d0\u05d9\u05dd \u05d1\u05d5 \u05e6\u05d9\u05d5\u05e8 \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7."],[14.0,"\u05de\u05d9 \u05e9\u05e7\u05d5\u05e8\u05d0 \u05e9\u05e8\u05d8\u05d5\u05d8 \u05d1\u05e8\u05de\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4 \u05e8\u05d5\u05d0\u05d4 \u05d1\u05d5 \u05de\u05e9\u05d4\u05d5 \u05d0\u05d7\u05e8 \u05dc\u05d2\u05de\u05e8\u05d9: \u05d7\u05d5\u05d6\u05d4."],[20.0,"\u05d1\u05e7\u05d5\u05e8\u05e1 \u05d4\u05d6\u05d4 \u05e0\u05dc\u05de\u05d3 \u05dc\u05e7\u05e8\u05d5\u05d0 \u05d0\u05ea \u05d4\u05d7\u05d5\u05d6\u05d4 \u05d4\u05d6\u05d4 \u05e2\u05d3 \u05d4\u05e1\u05d5\u05e3: \u05de\u05d4 \u05d4\u05d5\u05d0 \u05de\u05d7\u05d9\u05d9\u05d1, \u05de\u05d4 \u05d4\u05d5\u05d0 \u05de\u05ea\u05d9\u05e8, \u05d5\u05de\u05d4 \u05d4\u05d5\u05d0 \u05d1\u05db\u05dc\u05dc \u05dc\u05d0 \u05d0\u05d5\u05de\u05e8."],[30.0,"\u05dc\u05db\u05dc \u05e9\u05e8\u05d8\u05d5\u05d8 \u05d9\u05e9 \u05dc\u05e4\u05d7\u05d5\u05ea \u05e9\u05dc\u05d5\u05e9\u05d4 \u05e6\u05d3\u05d3\u05d9\u05dd \u05e9\u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5."],[34.0,"\u05d4\u05de\u05ea\u05db\u05e0\u05df \u05db\u05d5\u05ea\u05d1 \u05d1\u05d5 \u05de\u05d4 \u05d4\u05d7\u05dc\u05e7 \u05e6\u05e8\u05d9\u05da \u05dc\u05e2\u05e9\u05d5\u05ea."],[38.0,"\u05d4\u05d9\u05e6\u05e8\u05df \u05e7\u05d5\u05e8\u05d0 \u05d1\u05d5 \u05de\u05d4 \u05de\u05d5\u05ea\u05e8 \u05dc\u05d5 \u05dc\u05d9\u05d9\u05e6\u05e8."],[41.0,"\u05d5\u05d4\u05d1\u05d5\u05d3\u05e7 \u05e7\u05d5\u05e8\u05d0 \u05d1\u05d5 \u05dc\u05e4\u05d9 \u05de\u05d4 \u05dc\u05e7\u05d1\u05dc \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05d0\u05d5 \u05dc\u05e4\u05e1\u05d5\u05dc \u05d0\u05d5\u05ea\u05d5."],[47.0,"\u05d0\u05dd \u05e9\u05dc\u05d5\u05e9\u05ea\u05dd \u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05d0\u05ea \u05d0\u05d5\u05ea\u05d5 \u05e9\u05e8\u05d8\u05d5\u05d8 \u05d5\u05de\u05d1\u05d9\u05e0\u05d9\u05dd \u05de\u05de\u05e0\u05d5 \u05d0\u05d5\u05ea\u05d5 \u05d3\u05d1\u05d4 \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05e2\u05e9\u05d4 \u05d0\u05ea \u05e2\u05d1\u05d5\u05d3\u05ea\u05d5."],[54.0,"\u05d0\u05dd \u05db\u05dc \u05d0\u05d7\u05d3 \u05de\u05d1\u05d9\u05df \u05de\u05e9\u05d4\u05d5 \u05d0\u05d7\u05e8, \u05d4\u05d5\u05d5\u05d9\u05db\u05d5\u05d7 \u05d9\u05d2\u05d9\u05e2 \u05d1\u05e1\u05d5\u05e3, \u05d5\u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05db\u05e9\u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05db\u05d1\u05e8 \u05de\u05d5\u05db\u05e0\u05d9\u05dd."],[62.0,"\u05d7\u05dc\u05e7 \u05e9\u05e2\u05d5\u05de\u05d3 \u05d1\u05db\u05dc \u05d3\u05e8\u05d9\u05e9\u05d5\u05ea \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d4\u05d5\u05d0 \u05d7\u05dc\u05e7 \u05ea\u05e7\u05d9\u05df, \u05d2\u05dd \u05d0\u05dd \u05d1\u05d4\u05e8\u05db\u05d1\u05d4 \u05d4\u05d5\u05d0 \u05dc\u05d0 \u05e2\u05d5\u05d1\u05d3."],[69.0,"\u05d5\u05d7\u05dc\u05e7 \u05e9\u05d7\u05d5\u05e8\u05d2 \u05de\u05d3\u05e8\u05d9\u05e9\u05d4 \u05d0\u05d7\u05ea, \u05d0\u05e4\u05d9\u05dc\u05d5 \u05d1\u05de\u05d0\u05d9\u05ea \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8, \u05d4\u05d5\u05d0 \u05d7\u05dc\u05e7 \u05e4\u05e1\u05d5\u05dc, \u05d2\u05dd \u05d0\u05dd \u05d4\u05d5\u05d0 \u05e2\u05d5\u05d1\u05d3 \u05de\u05e6\u05d5\u05d9\u05df."],[77.0,"\u05d6\u05d4 \u05e0\u05e9\u05de\u05e2 \u05e7\u05e9\u05d5\u05d7, \u05d0\u05d1\u05dc \u05d6\u05d4 \u05d4\u05e2\u05d9\u05e7\u05e8\u05d5\u05df \u05e9\u05de\u05d0\u05e4\u05e9\u05e8 \u05dc\u05d9\u05e6\u05e8\u05df \u05d1\u05e6\u05d3 \u05d0\u05d7\u05d3 \u05e9\u05dc \u05d4\u05e2\u05d5\u05dc\u05dd \u05dc\u05d9\u05d9\u05e6\u05e8 \u05d7\u05dc\u05e7 \u05e9\u05d9\u05d5\u05e8\u05db\u05d1 \u05d1\u05e6\u05d3 \u05d4\u05e9\u05e0\u05d9."],[86.0,"\u05dc\u05db\u05df \u05db\u05e9\u05d7\u05dc\u05e7 \u05ea\u05e7\u05d9\u05df \u05dc\u05d0 \u05e2\u05d5\u05d1\u05d3, \u05d4\u05d1\u05e2\u05d9\u05d4 \u05d4\u05d9\u05d0 \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8, \u05d5\u05de\u05ea\u05e7\u05e0\u05d9\u05dd \u05d0\u05ea \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8."],[92.0,"\u05d4\u05d7\u05dc\u05d8\u05d4 \u05e8\u05e9\u05de\u05d9\u05ea \u05e9\u05dc \u05de\u05d9 \u05e9\u05d0\u05d7\u05e8\u05d0\u05d9 \u05e2\u05dc \u05d4\u05ea\u05db\u05e0\u05d5\u05df, \u05d5\u05dc\u05d0 \u05d4\u05d7\u05dc\u05d8\u05d4 \u05e9\u05dc \u05e8\u05e6\u05e4\u05ea \u05d4\u05d9\u05d9\u05e6\u05d5\u05e8."],[103.0,"\u05d0\u05d7\u05d3 \u05d4\u05db\u05dc\u05dc\u05d9\u05dd \u05d4\u05d1\u05e1\u05d9\u05e1\u05d9\u05d9\u05dd \u05d1\u05ea\u05e7\u05df ASME Y14.5 \u05d4\u05d5\u05d0 \u05e9\u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05de\u05d2\u05d3\u05d9\u05e8 \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7, \u05d1\u05dc\u05d9 \u05dc\u05e7\u05d1\u05d5\u05e2 \u05d0\u05d9\u05da \u05dc\u05d9\u05d9\u05e6\u05e8 \u05d0\u05d5\u05ea\u05d5."],[114.0,"\u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d0\u05d5\u05de\u05e8 \u05e9\u05e7\u05d3\u05d7 \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d9\u05d5\u05ea \u05d1\u05e7\u05d5\u05d8\u05e8 \u05e2\u05e9\u05e8\u05d4 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8, \u05d1\u05e1\u05d1\u05d5\u05dc\u05ea \u05de\u05e1\u05d5\u05d9\u05de\u05ea \u05d5\u05d1\u05de\u05d9\u05e7\u05d5\u05dd \u05de\u05e1\u05d5\u05d9\u05dd."],[122.0,"\u05d4\u05d5\u05d0 \u05dc\u05d0 \u05d0\u05d5\u05de\u05e8 \u05d0\u05dd \u05dc\u05e7\u05d3\u05d5\u05d7 \u05d0\u05d5\u05ea\u05d5, \u05dc\u05db\u05e8\u05e1\u05dd \u05d0\u05d5\u05ea\u05d5 \u05d0\u05d5 \u05dc\u05e2\u05d1\u05d3 \u05d0\u05d5\u05ea\u05d5 \u05d1\u05e8\u05d9\u05de\u05e8."],[127.0,"\u05dc\u05d1\u05d7\u05d5\u05e8 \u05d0\u05ea \u05d4\u05ea\u05d4\u05dc\u05d9\u05da \u05d4\u05d6\u05d5\u05dc \u05d5\u05d4\u05de\u05d4\u05d9\u05e8 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05e9\u05e2\u05d3\u05d9\u05d9\u05df \u05e2\u05d5\u05de\u05d3 \u05d1\u05d3\u05e8\u05d9\u05e9\u05d5\u05ea."],[137.0,"\u05d4\u05d7\u05dc\u05e7, \u05db\u05de\u05d5 \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd, \u05e6\u05d9\u05e4\u05d5\u05d9 \u05d0\u05d5 \u05e8\u05d9\u05ea\u05d5\u05da, \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05de\u05e1\u05e0\u05d4 \u05dc\u05de\u05e4\u05e8\u05d8 \u05e9\u05de\u05d2\u05d3\u05d9\u05e8 \u05d0\u05d5\u05ea\u05d5."],[149.0,"\u05e7\u05d5\u05e8\u05d0 \u05e9\u05e8\u05d8\u05d5\u05d8 \u05d8\u05d5\u05d1 \u05e9\u05d5\u05d0\u05dc \u05e2\u05dc \u05db\u05dc \u05d3\u05e8\u05d9\u05e9\u05d4: \u05d4\u05d0\u05dd \u05d4\u05d9\u05d0 \u05de\u05d2\u05d3\u05d9\u05e8\u05d4 \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7, \u05d0\u05d5 \u05e9\u05d4\u05d9\u05d0 \u05de\u05db\u05ea\u05d9\u05d1\u05d4 \u05dc\u05d9 \u05e9\u05d9\u05d8\u05d4?"],[157.0,"\u05d5\u05e9\u05d9\u05d8\u05d4 \u05de\u05d7\u05d9\u05d9\u05d1\u05ea \u05d0\u05d5\u05ea\u05d5 \u05e8\u05e7 \u05db\u05e9\u05d4\u05d9\u05d0 \u05db\u05ea\u05d5\u05d1\u05d4 \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d1\u05de\u05e4\u05d5\u05e8\u05e9."],[162.0,"\u05d0\u05d7\u05d3 \u05d4\u05d3\u05d1\u05e8\u05d9\u05dd \u05e9\u05de\u05d1\u05d3\u05d9\u05dc\u05d9\u05dd \u05e7\u05d5\u05e8\u05d0 \u05de\u05ea\u05e7\u05d3\u05dd \u05d4\u05d5\u05d0 \u05e9\u05d4\u05d5\u05d0 \u05e7\u05d5\u05e8\u05d0 \u05d2\u05dd \u05d0\u05ea \u05de\u05d4 \u05e9\u05dc\u05d0 \u05db\u05ea\u05d5\u05d1."],[168.0,"\u05de\u05e7\u05d1\u05dc\u05ea \u05d0\u05ea \u05d4\u05e1\u05d1\u05d5\u05dc\u05ea \u05d4\u05db\u05dc\u05dc\u05d9\u05ea \u05de\u05d0\u05d6\u05d5\u05e8 \u05d4\u05db\u05d5\u05ea\u05e8\u05ea \u05d0\u05d5 \u05de\u05d4\u05e2\u05e8\u05d4 \u05db\u05dc\u05dc\u05d9\u05ea."],[178.0,"\u05db\u05dc \u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d7\u05dc\u05d5\u05ea \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e9\u05dc \u05e2\u05e9\u05e8\u05d9\u05dd \u05de\u05e2\u05dc\u05d5\u05ea \u05e6\u05dc\u05d6\u05d9\u05d5\u05e1, \u05d2\u05dd \u05d0\u05dd \u05d6\u05d4 \u05dc\u05d0 \u05db\u05ea\u05d5\u05d1 \u05d1\u05e9\u05d5\u05dd \u05de\u05e7\u05d5\u05dd."],[186.0,"\u05d4\u05df \u05d7\u05dc\u05d5\u05ea \u05e2\u05dc \u05d4\u05d7\u05dc\u05e7 \u05d1\u05de\u05e6\u05d1 \u05d7\u05d5\u05e4\u05e9\u05d9, \u05d1\u05dc\u05d9 \u05e9\u05de\u05d4\u05d3\u05e7\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5, \u05d0\u05dc\u05d0 \u05d0\u05dd \u05db\u05ea\u05d5\u05d1 \u05d0\u05d7\u05e8\u05ea."],[192.0,"\u05d5\u05d4\u05ea\u05e7\u05df \u05e9\u05de\u05d5\u05e4\u05d9\u05e2 \u05d1\u05d0\u05d6\u05d5\u05e8 \u05d4\u05db\u05d5\u05ea\u05e8\u05ea \u05de\u05d2\u05d3\u05d9\u05e8 \u05e2\u05e9\u05e8\u05d5\u05ea \u05db\u05dc\u05dc\u05d9\u05dd \u05e9\u05d0\u05d9\u05e0\u05dd \u05de\u05e6\u05d5\u05d9\u05e8\u05d9\u05dd, \u05d5\u05d4\u05db\u05dc\u05dc\u05d9\u05dd \u05d4\u05d0\u05dc\u05d4 \u05e9\u05d5\u05e0\u05d9\u05dd \u05de\u05ea\u05e7\u05df \u05dc\u05ea\u05e7\u05df."],[202.0,"\u05dc\u05db\u05df \u05d0\u05d5\u05ea\u05d5 \u05e9\u05e8\u05d8\u05d5\u05d8 \u05d1\u05d3\u05d9\u05d5\u05e7 \u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05ea\u05e4\u05e8\u05e9 \u05d0\u05d7\u05e8\u05ea \u05dc\u05e1\u05d9 ASME \u05d5\u05dc\u05e4\u05d9 50\u05d5, \u05d5\u05e0\u05e8\u05d0\u05d4 \u05d0\u05ea \u05d6\u05d4 \u05d1\u05e4\u05d9\u05e8\u05d5\u05d8 \u05d1\u05d4\u05de\u05e9\u05da \u05d4\u05e7\u05d5\u05e8\u05e1."],[213.0,"\u05e2\u05d5\u05d3 \u05db\u05dc\u05dc \u05d9\u05e1\u05d5\u05d3: \u05dc\u05d0 \u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05de\u05d9\u05d3\u05d5\u05ea \u05de\u05d4\u05e6\u05d9\u05d5\u05e8 \u05e2\u05e6\u05de\u05d5."],[217.0,"\u05d2\u05dd \u05db\u05e9\u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05e0\u05e8\u05d0\u05d4 \u05d1\u05e7\u05e0\u05d4 \u05de\u05d9\u05d3\u05d4 \u05de\u05d3\u05d5\u05d9\u05e7, \u05de\u05d9\u05d3\u05d4 \u05e9\u05dc\u05d0 \u05db\u05ea\u05d5\u05d1\u05d4 \u05d1\u05d5 \u05d0\u05d9\u05e0\u05e0\u05d4 \u05de\u05d5\u05d2\u05d3\u05e8\u05ea, \u05d5\u05d0\u05e1\u05d5\u05e8 \u05dc\u05d4\u05e9\u05dc\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4 \u05d1\u05e1\u05e8\u05d2\u05dc."],[225.0,"\u05d5\u05d0\u05dd \u05d7\u05e1\u05e8\u05d4 \u05de\u05d9\u05d3\u05d4 \u05e9\u05e0\u05d7\u05d5\u05e6\u05d4 \u05dc\u05d9\u05d9\u05e6\u05d5\u05e8, \u05d6\u05d5 \u05dc\u05d0 \u05d4\u05d6\u05de\u05e0\u05d4 \u05dc\u05e0\u05d7\u05e9.. \u05d6\u05d5 \u05e9\u05d0\u05dc\u05d4 \u05dc\u05de\u05ea\u05db\u05e0\u05df."],[233.0,"\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d8\u05d5\u05d1 \u05de\u05d2\u05d3\u05d9\u05e8 \u05db\u05dc \u05de\u05d0\u05e4\u05d9\u05d9\u05df \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7 \u05e4\u05e2\u05dd \u05d0\u05d7\u05ea, \u05d1\u05d0\u05d5\u05e4\u05df \u05d0\u05d7\u05d3, \u05d5\u05d1\u05dc\u05d9 \u05e1\u05ea\u05d9\u05e8\u05d5\u05ea."],[240.0,"\u05dc\u05e2\u05d9\u05ea\u05d9\u05dd \u05e7\u05e8\u05d5\u05d1\u05d5\u05ea \u05d4\u05d5\u05d0 \u05e9\u05e8\u05d8\u05d5\u05d8 \u05e9\u05d0\u05e4\u05e9\u05e8 \u05dc\u05e7\u05e8\u05d5\u05d0 \u05d1\u05e9\u05d5\u05ea\u05d9 \u05d3\u05e8\u05db\u05d9\u05dd."],[249.0,"\u05d0\u05d5 \u05e1\u05d1\u05d5\u05dc\u05ea \u05e9\u05d0\u05d9 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05de\u05d3\u05d5\u05d3: \u05db\u05dc \u05d0\u05d7\u05ea \u05de\u05d4\u05df \u05d4\u05d9\u05d0 \u05e4\u05ea\u05d7 \u05dc\u05d5\u05d5\u05d9\u05db\u05d5\u05d7."],[260.0,"\u05d7\u05dc\u05e7 \u05d2\u05d3\u05d5\u05dc \u05de\u05d4\u05e7\u05d5\u05e8\u05e1 \u05e0\u05d5\u05e2\u05d3 \u05d1\u05d3\u05d9\u05d5\u05e7 \u05dc\u05d6\u05d4: \u05dc\u05d6\u05d4\u05d5\u05ea \u05d0\u05ea \u05d4\u05e4\u05ea\u05d7\u05d9\u05dd \u05d4\u05d0\u05dc\u05d4 \u05dc\u05e4\u05e0\u05d9 \u05e9\u05d4\u05dd \u05e2\u05d5\u05dc\u05d9\u05dd \u05db\u05e1\u05e3."],[268.0,"\u05d4\u05e7\u05d5\u05e8\u05e1 \u05d1\u05e0\u05d5\u05d9 \u05de\u05e9\u05d9\u05e9\u05d4 \u05d7\u05dc\u05e7\u05d9\u05dd."],[271.0,"\u05d1\u05d7\u05dc\u05e7 \u05d4\u05e8\u05d0\u05e9\u05d5\u05df \u05e0\u05d7\u05d6\u05d5\u05e8 \u05e2\u05dc \u05d4\u05d9\u05d9\u05e6\u05d5\u05d2 \u05e2\u05e6\u05de\u05d5 \u05d1\u05e8\u05de\u05d4 \u05de\u05ea\u05e7\u05d3\u05de\u05ea: \u05de\u05e2\u05e8\u05db\u05d5\u05ea \u05d4\u05d9\u05d8\u05dc, \u05d7\u05ea\u05db\u05d9\u05dd, \u05de\u05d5\u05e1\u05db\u05de\u05d5\u05ea \u05d5\u05d7\u05e9\u05d9\u05d1\u05d4 \u05de\u05e8\u05d7\u05d1\u05d9\u05ea."],[280.0,"\u05d4\u05de\u05d9\u05d3\u05d5\u05ea, \u05e1\u05d1\u05d5\u05dc\u05d5\u05ea \u05db\u05dc\u05dc\u05d9\u05d5\u05ea, \u05e2\u05e7\u05e8\u05d5\u05df \u05d4\u05de\u05e2\u05d8\u05e4\u05ea \u05de\u05d5\u05dc \u05e2\u05e7\u05e8\u05d5\u05df \u05d4\u05e2\u05e6\u05de\u05d0\u05d5\u05ea, \u05d4\u05ea\u05d0\u05de\u05d5\u05ea \u05d5\u05e9\u05e8\u05e9\u05d5\u05e8\u05d0\u05d5\u05ea \u05e1\u05d1\u05d5\u05dc\u05d5\u05ea."],[294.0,"\u05d1\u05d7\u05dc\u05e7 \u05d4\u05e9\u05dc\u05d9\u05e9\u05d9 \u05e0\u05e7\u05e8\u05d0 \u05e1\u05d1\u05d5\u05dc\u05d5\u05ea \u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05d5\u05ea \u05d1\u05ea\u05d5\u05da \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d4\u05e9\u05dc\u05dd, \u05d3\u05e8\u05da \u05e2\u05d9\u05e0\u05d9 \u05de\u05e2\u05e8\u05db\u05ea \u05d4\u05de\u05e9\u05d8\u05d7\u05d9\u05dd."],[302.0,"\u05de\u05e8\u05e7\u05dd \u05e4\u05e0\u05d9 \u05e9\u05d8\u05d7, \u05e8\u05d9\u05ea\u05d5\u05da, \u05d7\u05d5\u05de\u05e8, \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd, \u05e6\u05d9\u05e4\u05d5\u05d9, \u05d4\u05d1\u05e8\u05d2\u05d5\u05ea \u05d5\u05d0\u05dc\u05de\u05e0\u05d8\u05d9\u05dd \u05de\u05d9\u05d5\u05d7\u05d3\u05d9\u05dd."],[315.0,"\u05d4\u05db\u05d5\u05ea\u05e8\u05ea \u05d5\u05d4\u05d4\u05e2\u05e8\u05d5\u05ea, \u05e9\u05e8\u05d8\u05d5\u05d8\u05d9 \u05d4\u05e8\u05db\u05d1\u05d4, \u05de\u05d0\u05e4\u05d9\u05d9\u05e0\u05d9\u05dd \u05e7\u05e8\u05d9\u05d8\u05d9\u05d9\u05dd, \u05d4\u05d2\u05d3\u05e8\u05d4 \u05de\u05d1\u05d5\u05e1\u05e1\u05ea \u05de\u05d5\u05d3\u05dc \u05d5\u05e0\u05d9\u05d4\u05d5\u05dc \u05e9\u05d9\u05e0\u05d5\u05d9\u05d9\u05dd."],[328.0,"\u05d5\u05d1\u05d7\u05dc\u05e7 \u05d4\u05e9\u05d9\u05e9\u05d9 \u05e0\u05d7\u05d1\u05e8 \u05d4\u05db\u05d5\u05dc: \u05e0\u05e7\u05e8\u05d0 \u05e9\u05e8\u05d8\u05d5\u05d8\u05d9\u05dd \u05d1\u05e2\u05d9\u05e0\u05d9 \u05d4\u05d9\u05e6\u05e8\u05df, \u05e0\u05d0\u05ea\u05e8 \u05e9\u05d2\u05d9\u05d0\u05d5\u05ea, \u05d5\u05e0\u05d1\u05e0\u05d4 \u05e9\u05d9\u05d8\u05ea \u05e7\u05e8\u05d9\u05d0\u05d4 \u05e7\u05d1\u05d5\u05e2\u05d4 \u05dc\u05db\u05dc \u05e9\u05e8\u05d8\u05d5\u05d8."],[340.0,"\u05d4\u05d1\u05e1\u05d9\u05e1 \u05e9\u05dc \u05d4\u05e7\u05d5\u05e8\u05e1 \u05d4\u05d5\u05d0 \u05ea\u05e7\u05df ASME Y14.5 \u05de\u05e9\u05e0\u05ea 2018, \u05d4\u05ea\u05e7\u05df \u05d4\u05e0\u05e4\u05d5\u05e5 \u05d1\u05ea\u05e2\u05e9\u05d9\u05d9\u05d4."],[351.0,"\u05d0\u05ea \u05d4\u05d4\u05d1\u05d3\u05dc, \u05db\u05d9 \u05d1\u05e2\u05d1\u05d5\u05d3\u05d4 \u05d0\u05de\u05d9\u05ea\u05d9\u05ea \u05de\u05d2\u05d9\u05e2\u05d9\u05dd \u05e9\u05e8\u05d8\u05d5\u05d8\u05d9\u05dd \u05dc\u05e4\u05d9 \u05e9\u05e0\u05d9 \u05d4\u05ea\u05e7\u05e0\u05d9\u05dd."],[362.0,"\u05e0\u05db\u05d5\u05e0\u05d9\u05dd \u05de\u05d1\u05d7\u05d9\u05e0\u05d4 \u05d4\u05e0\u05d3\u05e1\u05d9\u05ea, \u05d0\u05d1\u05dc \u05d0\u05d9\u05e0\u05dd \u05e9\u05d9\u05d9\u05db\u05d9\u05dd \u05dc\u05e9\u05d5\u05dd \u05de\u05d5\u05e6\u05e8 \u05d0\u05d5 \u05d7\u05d1\u05e8\u05d4."],[372.0,"\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d4\u05d5\u05d0 \u05d7\u05d7\u05d4 \u05d1\u05d9\u05df \u05d4\u05de\u05ea\u05db\u05e0\u05df, \u05d4\u05d9\u05e6\u05e8\u05df \u05d5\u05d4\u05d1\u05d5\u05d3\u05e7."],[377.0,"\u05d4\u05d5\u05d0 \u05de\u05d2\u05d3\u05d9\u05e8 \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05d5\u05dc\u05d0 \u05d0\u05ea \u05d4\u05ea\u05d4\u05dc\u05d9\u05da, \u05d4\u05d5\u05d0 \u05de\u05d7\u05d9\u05d9\u05d1 \u05d2\u05dd \u05d1\u05de\u05d4 \u05e9\u05dc\u05d0 \u05db\u05ea\u05d5\u05d1 \u05d1\u05d5, \u05d5\u05dc\u05d0 \u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05de\u05de\u05e0\u05d5 \u05d1\u05e1\u05e8\u05d2\u05dc."],[386.0,"\u05de\u05e2\u05d1\u05d9\u05e8\u05d9\u05dd \u05d2\u05d5\u05e3 \u05ea\u05dc\u05ea \u05de\u05de\u05d3\u05d9 \u05dc\u05d3\u05e3 \u05e9\u05d8\u05d5\u05d7, \u05d5\u05dc\u05de\u05d4 \u05d1\u05dc\u05d1\u05d5\u05dc \u05d1\u05d6\u05d5\u05d5\u05d9\u05ea \u05d4\u05d4\u05d9\u05d8\u05dc \u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05e4\u05d5\u05da \u05d7\u05dc\u05e7 \u05e9\u05dc\u05dd \u05dc\u05ea\u05de\u05d5\u05e0\u05ea \u05e8\u05d0\u05d9."],[399.0,"\u05e0\u05ea\u05e8\u05d0\u05d4 \u05d1\u05e4\u05e8\u05e7 \u05d0\u05d7\u05d3."]]};
window.MH_TR["ch01"]={"t":"\u05de\u05e2\u05e8\u05db\u05d5\u05ea \u05d4\u05d9\u05d8\u05dc","l":[[1.0,"\u05d2\u05d5\u05e3 \u05de\u05db\u05e0\u05d9 \u05d4\u05d5\u05d0 \u05ea\u05dc\u05ea \u05de\u05de\u05d3\u05d9, \u05d5\u05d4\u05d3\u05e3 \u05e9\u05d8\u05d5\u05d7."],[5.0,"\u05db\u05dc \u05e9\u05e8\u05d8\u05d5\u05d8 \u05de\u05ea\u05d7\u05d9\u05dc \u05d1\u05e9\u05d0\u05dc\u05d4 \u05d0\u05d7\u05ea: \u05d0\u05d9\u05da \u05de\u05e2\u05d1\u05d9\u05e8\u05d9\u05dd \u05d0\u05ea \u05d4\u05d2\u05d5\u05e3 \u05dc\u05d3\u05e3, \u05d1\u05dc\u05d9 \u05dc\u05d0\u05d1\u05d3 \u05d0\u05e3 \u05de\u05d9\u05d3\u05e2."],[13.0,"\u05d4\u05ea\u05e9\u05d5\u05d1\u05d4 \u05d4\u05d9\u05d0 \u05d4\u05d9\u05d8\u05dc \u05e0\u05d9\u05e6\u05d1, \u05d5\u05e9\u05ea\u05d9 \u05de\u05e2\u05e8\u05db\u05d5\u05ea \u05e9\u05d5\u05e0\u05d5\u05ea \u05dc\u05e1\u05d3\u05e8 \u05d1\u05d4\u05df \u05d0\u05ea \u05d4\u05de\u05d1\u05d8\u05d9\u05dd."],[19.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05d1\u05d9\u05df \u05d0\u05ea \u05e9\u05ea\u05d9\u05d4\u05df \u05dc\u05e2\u05d5\u05de\u05e7, \u05d5\u05e0\u05e8\u05d0\u05d4 \u05d0\u05d9\u05da \u05d1\u05dc\u05d1\u05d5\u05dc \u05d1\u05d9\u05e0\u05d9\u05d4\u05df \u05de\u05d9\u05d9\u05e6\u05e8 \u05d7\u05dc\u05e7 \u05e9\u05d4\u05d5\u05d0 \u05ea\u05de\u05d5\u05e0\u05ea \u05e8\u05d0\u05d9 \u05e9\u05dc \u05de\u05d4 \u05e9\u05ea\u05d5\u05db\u05e0\u05df."],[29.0,"\u05d1\u05d4\u05d9\u05d8\u05dc \u05e0\u05d9\u05e6\u05d1, \u05e7\u05e8\u05e0\u05d9 \u05d4\u05de\u05d1\u05d8 \u05de\u05e7\u05d1\u05d9\u05dc\u05d5\u05ea \u05d6\u05d5 \u05dc\u05d6\u05d5 \u05d5\u05de\u05d0\u05d5\u05e0\u05db\u05d5\u05ea \u05dc\u05de\u05d9\u05e9\u05d5\u05e8 \u05d4\u05d4\u05d9\u05d8\u05dc."],[36.0,"\u05dc\u05db\u05df \u05db\u05dc \u05de\u05d1\u05d8 \u05de\u05e8\u05d0\u05d4 \u05e8\u05e7 \u05e9\u05e0\u05d9 \u05de\u05de\u05d3\u05d9\u05dd: \u05e8\u05d5\u05d7\u05d1 \u05d5\u05d2\u05d5\u05d1\u05d4, \u05d0\u05d5 \u05e8\u05d5\u05d7\u05d1 \u05d5\u05e2\u05d5\u05de\u05e7, \u05d5\u05d0\u05e3 \u05e4\u05e2\u05dd \u05dc\u05d0 \u05e9\u05dc\u05d5\u05e9\u05ea\u05dd."],[45.0,"\u05de\u05e9\u05d8\u05d7 \u05e9\u05de\u05e7\u05d1\u05d9\u05dc \u05dc\u05de\u05d9\u05e9\u05d5\u05e8 \u05d4\u05d4\u05d9\u05d8\u05dc \u05de\u05d5\u05e4\u05d9\u05e2 \u05d1\u05d2\u05d5\u05d3\u05dc\u05d5 \u05d5\u05d1\u05e6\u05d5\u05e8\u05ea\u05d5 \u05d4\u05d0\u05de\u05d9\u05ea\u05d9\u05d9\u05dd."],[51.0,"\u05de\u05e9\u05d8\u05d7 \u05e9\u05de\u05d0\u05d5\u05e0\u05da \u05dc\u05de\u05d9\u05e9\u05d5\u05e8 \u05de\u05d5\u05e4\u05d9\u05e2 \u05db\u05e7\u05d5 \u05d1\u05dc\u05d1\u05d3."],[56.0,"\u05d5\u05de\u05e9\u05d8\u05d7 \u05de\u05e9\u05d5\u05e4\u05e2 \u05de\u05d5\u05e4\u05d9\u05e2 \u05de\u05e7\u05d5\u05e6\u05e8: \u05d4\u05d5\u05d0 \u05e0\u05e8\u05d0\u05d4 \u05e7\u05d8\u05df \u05d9\u05d5\u05ea\u05e8\u05de\u05de\u05d4 \u05e9\u05d4\u05d5\u05d0 \u05d1\u05d0\u05de\u05ea."],[62.0,"\u05d6\u05d5 \u05e2\u05d5\u05d3 \u05e1\u05d9\u05d1\u05d4 \u05dc\u05d0 \u05dc\u05de\u05d3\u05d5\u05d3 \u05de\u05d4\u05e6\u05d9\u05d5\u05e8: \u05d0\u05d5\u05e8\u05da \u05e9\u05e0\u05e8\u05d0\u05d4 \u05e2\u05dc \u05d4\u05d3\u05e3 \u05d0\u05d9\u05e0\u05d5 \u05d1\u05d4\u05db\u05e8\u05d7 \u05d4\u05d0\u05d5\u05e8\u05da \u05d4\u05d0\u05de\u05d9\u05ea\u05d9."],[70.0,"\u05d3\u05de\u05d9\u05d9\u05e0\u05d5 \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05d1\u05ea\u05d5\u05da \u05e7\u05d5\u05e4\u05e1\u05d4, \u05d5\u05e2\u05dc \u05db\u05dc \u05d0\u05d7\u05ea \u05de\u05e9\u05d5\u05e2\u05d5 \u05d4\u05d3\u05e4\u05e0\u05d5\u05ea \u05de\u05d5\u05d8\u05dc \u05de\u05d1\u05d8 \u05d0\u05d7\u05d3."],[76.0,"\u05db\u05e9\u05e4\u05d5\u05e8\u05e9\u05d9\u05dd \u05d0\u05ea \u05d4\u05e7\u05d5\u05e4\u05e1\u05d4 \u05dc\u05d3\u05e3, \u05d9\u05e9 \u05e9\u05ea\u05d9 \u05d3\u05e8\u05db\u05d9\u05dd \u05dc\u05e1\u05d3\u05e8 \u05d0\u05ea \u05d4\u05de\u05d1\u05d8\u05d9\u05dd, \u05d5\u05d6\u05d4 \u05db\u05dc \u05d4\u05d4\u05d1\u05d3\u05dc \u05d1\u05d9\u05df \u05e9\u05ea\u05d9 \u05d4\u05de\u05e2\u05e8\u05db\u05d5\u05ea."],[84.0,"\u05d1\u05d6\u05d5\u05d5\u05d9\u05ea \u05e9\u05dc\u05d9\u05e9\u05d9\u05ea, \u05d4\u05e0\u05e4\u05d5\u05e6\u05d4 \u05d1\u05d0\u05e8\u05e6\u05d5\u05ea \u05d4\u05d1\u05e8\u05d9\u05ea \u05d5\u05d1\u05ea\u05e7\u05e0\u05d9 ASME \u05de\u05d9\u05e9\u05d5\u05e8 \u05d4\u05d4\u05d9\u05d8\u05dc \u05e0\u05de\u05e6\u05d0 \u05d1\u05d9\u05df \u05d4\u05e2\u05d9\u05df \u05dc\u05d1\u05d9\u05df \u05d4\u05d7\u05dc\u05e7."],[94.0,"\u05dc\u05db\u05df \u05db\u05dc \u05de\u05d1\u05d8 \u05de\u05e6\u05d5\u05d9\u05e8 \u05d1\u05e6\u05d3 \u05e9\u05de\u05de\u05e0\u05d5 \u05de\u05e1\u05ea\u05db\u05dc\u05d9\u05dd: \u05d4\u05de\u05d1\u05d8 \u05de\u05dc\u05de\u05e2\u05dc\u05d4 \u05de\u05e2\u05dc \u05d4\u05de\u05d1\u05d8 \u05d4\u05e7\u05d3\u05de\u05d9, \u05d5\u05d4\u05de\u05d1\u05d8 \u05de\u05e6\u05d3 \u05d9\u05de\u05d9\u05df \u05de\u05d9\u05de\u05d9\u05df \u05dc\u05d5."],[105.0,"\u05d1\u05d6\u05d5\u05d5\u05d9\u05ea \u05e8\u05d0\u05e9\u05d5\u05e0\u05d4, \u05d4\u05e0\u05e4\u05d5\u05e6\u05d4 \u05d1\u05d0\u05d9\u05e8\u05d5\u05e4\u05d4 \u05d5\u05d1\u05ea\u05e7\u05e0\u05d9 ISO \u05d4\u05d7\u05dc\u05e7 \u05e0\u05de\u05e6\u05d0 \u05d1\u05d9\u05df \u05d4\u05e2\u05d9\u05df \u05dc\u05d1\u05d9\u05df \u05de\u05d9\u05e9\u05d5\u05e8 \u05d4\u05d4\u05d9\u05d8\u05dc."],[113.0,"\u05d5\u05d0\u05d6 \u05db\u05dc \u05de\u05d1\u05d8 \u05de\u05e6\u05d5\u05d9\u05e8 \u05d1\u05e6\u05d3 \u05d4\u05e0\u05d2\u05d3\u05d9: \u05d4\u05de\u05d1\u05d8 \u05de\u05dc\u05de\u05e2\u05dc\u05d4 \u05de\u05ea\u05d7\u05ea \u05dc\u05de\u05d1\u05d8 \u05d4\u05e7\u05d3\u05de\u05d9, \u05d5\u05d4\u05de\u05d1\u05d8 \u05de\u05e6\u05d3 \u05d9\u05de\u05d9\u05df \u05de\u05e9\u05de\u05d0\u05dc \u05dc\u05d5."],[123.0,"\u05d4\u05de\u05d1\u05d8\u05d9\u05dd \u05e2\u05e6\u05de\u05dd \u05d6\u05d4\u05d9\u05dd \u05d1\u05e9\u05ea\u05d9 \u05d4\u05de\u05e2\u05e8\u05db\u05d5\u05ea. \u05e8\u05e7 \u05d4\u05de\u05d9\u05e7\u05d5\u05dd \u05e9\u05dc\u05d4\u05dd \u05e2\u05dc \u05d4\u05d3\u05e3 \u05e9\u05d5\u05e0\u05d4."],[129.0,"\u05d5\u05de\u05d9 \u05e9\u05de\u05db\u05d9\u05e8 \u05e8\u05e7 \u05de\u05e2\u05e8\u05db\u05ea \u05d0\u05d7\u05ea \u05d9\u05e7\u05e8\u05d0 \u05d0\u05ea \u05d4\u05e9\u05e0\u05d9\u05d9\u05d4 \u05d4\u05e4\u05d5\u05da, \u05d1\u05dc\u05d9 \u05dc\u05e9\u05d9\u05dd \u05dc\u05d1."],[135.0,"\u05db\u05d3\u05d9 \u05e9\u05dc\u05d0 \u05d9\u05d4\u05d9\u05d4 \u05e1\u05e4\u05e7, \u05d0\u05d6\u05d5\u05e8 \u05d4\u05db\u05d5\u05ea\u05e8\u05ea \u05db\u05d5\u05dc\u05dc \u05e1\u05de\u05dc \u05e9\u05de\u05d2\u05d3\u05d9\u05e8 \u05d0\u05ea \u05d4\u05de\u05e2\u05e8\u05db\u05ea."],[140.0,"\u05d4\u05e1\u05de\u05dc \u05d4\u05d5\u05d0 \u05d7\u05e8\u05d5\u05d8 \u05e7\u05d8\u05d5\u05e2 \u05d1\u05e9\u05e0\u05d9 \u05de\u05d1\u05d8\u05d9\u05dd: \u05de\u05d1\u05d8 \u05de\u05d4\u05e6\u05d3, \u05e9\u05e0\u05e8\u05d0\u05d4 \u05db\u05de\u05d5 \u05d8\u05e8\u05e4\u05d6, \u05d5\u05de\u05d1\u05d8 \u05de\u05d4\u05e7\u05e6\u05d4, \u05e9\u05e0\u05e8\u05d0\u05d4 \u05db\u05e9\u05e0\u05d9 \u05e2\u05d9\u05d2\u05d5\u05dc\u05d9\u05dd."],[150.0,"\u05e9\u05e0\u05d9 \u05d4\u05e2\u05d9\u05d2\u05d5\u05dc\u05d9\u05dd \u05d4\u05dd \u05d4\u05de\u05d1\u05d8 \u05de\u05d4\u05e7\u05e6\u05d4 \u05d4\u05e6\u05e8 \u05e9\u05dc \u05d4\u05d7\u05e8\u05d5\u05d8."],[155.0,"\u05d1\u05d6\u05d5\u05d5\u05d9\u05ea \u05e9\u05dc\u05d9\u05e9\u05d9\u05ea, \u05d4\u05e2\u05d9\u05d2\u05d5\u05dc\u05d9\u05dd \u05de\u05e6\u05d5\u05d9\u05e8\u05d9\u05dd \u05dc\u05d9\u05d3 \u05d4\u05e7\u05e6\u05d4 \u05d4\u05e6\u05e8, \u05d5\u05d4\u05d8\u05e8\u05e4\u05d6 \u05de\u05e6\u05d1\u05d9\u05e2 \u05d0\u05dc\u05d9\u05d4\u05dd."],[162.0,"\u05d1\u05d6\u05d5\u05d5\u05d9\u05ea \u05e8\u05d0\u05e9\u05d5\u05e0\u05d4, \u05d4\u05e2\u05d9\u05d2\u05d5\u05dc\u05d9\u05dd \u05de\u05e6\u05d5\u05d9\u05e8\u05d9\u05dd \u05d1\u05e6\u05d3 \u05e9\u05dc \u05d4\u05e7\u05e6\u05d4 \u05d4\u05e8\u05d7\u05d1, \u05d5\u05d4\u05d8\u05e8\u05e4\u05d6 \u05de\u05e6\u05d1\u05d9\u05e2 \u05d4\u05e8\u05d7\u05e7 \u05de\u05d4\u05dd."],[169.0,"\u05db\u05da \u05de\u05d6\u05d4\u05d9\u05dd \u05d0\u05ea \u05d4\u05de\u05e2\u05e8\u05db\u05ea \u05e0\u05db\u05d5\u05df, \u05d2\u05dd \u05d0\u05dd \u05d4\u05e1\u05de\u05dc \u05e6\u05d5\u05d9\u05e8 \u05d4\u05e4\u05d5\u05da \u05d0\u05d5 \u05d1\u05de\u05e7\u05d5\u05dd \u05dc\u05d0 \u05e6\u05e4\u05d5\u05d9."],[176.0,"\u05dc\u05e4\u05e2\u05de\u05d9\u05dd, \u05d1\u05de\u05e7\u05d5\u05dd \u05e1\u05de\u05dc, \u05db\u05ea\u05d5\u05d1 \u05d1\u05de\u05d9\u05dc\u05d9\u05dd \u05d1\u05d0\u05e0\u05d2\u05dc\u05d9\u05ea \u05d0\u05d9\u05d6\u05d5 \u05de\u05e2\u05e8\u05db\u05ea \u05d4\u05d9\u05d0."],[182.0,"\u05e0\u05e0\u05d9\u05d7 \u05e9\u05de\u05d2\u05d9\u05e2 \u05e9\u05e8\u05d8\u05d5\u05d8 \u05d1\u05d6\u05d5\u05d5\u05d9\u05ea \u05e8\u05d0\u05e9\u05d5\u05e0\u05d4, \u05d5\u05e7\u05d5\u05e8\u05d0 \u05d0\u05d5\u05ea\u05d5 \u05de\u05d9 \u05e9\u05e8\u05d2\u05d9\u05dc \u05dc\u05d6\u05d5\u05d5\u05d9\u05ea \u05e9\u05dc\u05d9\u05e9\u05d9\u05ea."],[188.0,"\u05d4\u05d7\u05dc\u05e7 \u05d4\u05d5\u05d0 \u05e4\u05dc\u05d8\u05d4 \u05e2\u05dd \u05d3\u05d5\u05e4\u05df \u05d2\u05d1\u05d5\u05d4\u05d4 \u05d1\u05e6\u05d3 \u05d4\u05d0\u05d7\u05d5\u05e8\u05d9, \u05d5\u05e7\u05d3\u05d7 \u05dc\u05d9\u05d3 \u05d4\u05e4\u05d9\u05e0\u05d4 \u05d4\u05e7\u05d3\u05de\u05d9\u05ea \u05d4\u05d9\u05de\u05e0\u05d9\u05ea."],[195.0,"\u05d1\u05d6\u05d5\u05d5\u05d9\u05ea \u05e8\u05d0\u05e9\u05d5\u05e0\u05d4, \u05d4\u05de\u05d1\u05d8 \u05de\u05dc\u05de\u05e2\u05dc\u05d4 \u05de\u05e6\u05d5\u05d9\u05e8 \u05de\u05ea\u05d7\u05ea \u05dc\u05de\u05d1\u05d8 \u05d4\u05e7\u05d3\u05de\u05d9, \u05d5\u05d4\u05e6\u05d3 \u05d4\u05e7\u05e8\u05d5\u05d1 \u05dc\u05de\u05d1\u05d8 \u05d4\u05e7\u05d3\u05de\u05d9 \u05d4\u05d5\u05d0 \u05d4\u05d2\u05d1 \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7."],[205.0,"\u05de\u05d9 \u05e9\u05e7\u05d5\u05e8\u05d0 \u05d1\u05d6\u05d5\u05d5\u05d9\u05ea \u05e9\u05dc\u05d9\u05e9\u05d9\u05ea \u05d7\u05d5\u05e9\u05d1 \u05e9\u05d6\u05d4 \u05de\u05d1\u05d8 \u05de\u05dc\u05de\u05d8\u05d4, \u05d5\u05de\u05d1\u05d9\u05df \u05e9\u05d4\u05e6\u05d3 \u05d4\u05e7\u05e8\u05d5\u05d1 \u05d4\u05d5\u05d0 \u05d4\u05d7\u05d6\u05d9\u05ea."],[213.0,"\u05d4\u05ea\u05d5\u05e6\u05d0\u05d4: \u05d4\u05d3\u05d5\u05e4\u05df \u05e2\u05d5\u05d1\u05e8\u05ea \u05dc\u05d7\u05d6\u05d9\u05ea, \u05d5\u05d4\u05e7\u05d3\u05d7 \u05e2\u05d5\u05d1\u05e8 \u05dc\u05d2\u05d1. \u05d4\u05d7\u05dc\u05e7 \u05e9\u05d9\u05d5\u05e6\u05e8 \u05d4\u05d5\u05d0 \u05ea\u05de\u05d5\u05e0\u05ea \u05e8\u05d0\u05d9 \u05e9\u05dc \u05de\u05d4 \u05e9\u05ea\u05d5\u05db\u05e0\u05df."],[222.0,"\u05d5\u05d4\u05d7\u05dc\u05e7 \u05d4\u05de\u05e1\u05d5\u05db\u05df: \u05d4\u05de\u05d1\u05d8\u05d9\u05dd \u05e0\u05e9\u05d0\u05e8\u05d9\u05dd \u05e2\u05e7\u05d1\u05d9\u05d9\u05dd \u05d6\u05d4 \u05e2\u05dd \u05d6\u05d4, \u05d5\u05dc\u05db\u05df \u05e9\u05d5\u05dd \u05d3\u05d1\u05e8 \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05dc\u05d0 \u05e0\u05e8\u05d0\u05d4 \u05e9\u05d2\u05d5\u05d9."],[230.0,"\u05d1\u05d7\u05dc\u05e7 \u05e1\u05d9\u05de\u05d8\u05e8\u05d9 \u05d4\u05d8\u05e2\u05d5\u05ea \u05dc\u05d0 \u05de\u05e9\u05e0\u05d4 \u05db\u05dc\u05d5\u05dd. \u05d1\u05d7\u05dc\u05e7 \u05dc\u05d0 \u05e1\u05d9\u05de\u05d8\u05e8\u05d9 \u05d4\u05d9\u05d0 \u05e4\u05d5\u05e1\u05dc\u05ea \u05d0\u05ea \u05db\u05dc \u05d4\u05e1\u05d3\u05e8\u05d4."],[238.0,"\u05de\u05d4 \u05e2\u05d5\u05e9\u05d9\u05dd \u05db\u05e9\u05e9\u05e8\u05d8\u05d5\u05d8 \u05de\u05d2\u05d9\u05e2 \u05d1\u05dc\u05d9 \u05e1\u05de\u05dc \u05d5\u05d1\u05dc\u05d9 \u05d4\u05e2\u05e8\u05d4?"],[242.0,"\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d4\u05de\u05e2\u05e8\u05db\u05ea \u05de\u05d5\u05d2\u05d3\u05e8\u05ea \u05e9\u05dd, \u05d0\u05d5 \u05d1\u05ea\u05e7\u05df \u05e9\u05d0\u05dc\u05d9\u05d5 \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05de\u05e4\u05e0\u05d4."],[252.0,"\u05d0\u05d7\u05e8 \u05db\u05da \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d0\u05dd \u05de\u05e6\u05d5\u05e8\u05e3 \u05dc\u05e9\u05e8\u05d8\u05d5\u05d8 \u05de\u05d5\u05d3\u05dc \u05ea\u05dc\u05ea \u05de\u05de\u05d3\u05d9, \u05d5\u05de\u05e9\u05d5\u05d5\u05d9\u05dd \u05d0\u05dc\u05d9\u05d5."],[258.0,"\u05d0\u05d1\u05dc \u05d0\u05dc \u05ea\u05e1\u05de\u05db\u05d5 \u05e2\u05dc \u05db\u05da \u05e9\u05d4\u05de\u05d1\u05d8\u05d9\u05dd \u05d9\u05d9\u05e8\u05d0\u05d5 \u05dc\u05d0 \u05d4\u05d2\u05d9\u05d5\u05e0\u05d9\u05d9\u05dd. \u05db\u05de\u05d5 \u05e9\u05e8\u05d0\u05d9\u05e0\u05d5, \u05d4\u05e4\u05e8\u05e9\u05d5\u05e0\u05d5\u05ea \u05d4\u05d4\u05e4\u05d5\u05db\u05d4 \u05e2\u05e7\u05d1\u05d9\u05ea \u05dc\u05d2\u05de\u05e8\u05d9."],[266.0,"\u05d5\u05d0\u05dd \u05e2\u05d3\u05d9\u05d9\u05df \u05d9\u05e9 \u05e1\u05e4\u05e7, \u05e9\u05d5\u05d0\u05dc\u05d9\u05dd \u05d0\u05ea \u05d4\u05de\u05ea\u05db\u05e0\u05df. \u05d1\u05d7\u05dc\u05e7 \u05dc\u05d0 \u05e1\u05d9\u05de\u05d8\u05e8\u05d9, \u05e0\u05d9\u05d7\u05d5\u05e9 \u05d4\u05d5\u05d0 \u05d4\u05d9\u05de\u05d5\u05e8 \u05e2\u05dc \u05db\u05dc \u05d4\u05e1\u05d3\u05e8\u05d4."],[275.0,"\u05d4\u05de\u05d1\u05d8 \u05d4\u05e7\u05d3\u05de\u05d9 \u05dc\u05d0 \u05d7\u05d9\u05d9\u05d1 \u05dc\u05d4\u05d9\u05d5\u05ea \u05d4\u05d7\u05d6\u05d9\u05ea \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7. \u05d4\u05d5\u05d0 \u05d4\u05de\u05d1\u05d8 \u05e9\u05de\u05ea\u05d0\u05e8 \u05d0\u05ea \u05d4\u05e6\u05d5\u05e8\u05d4 \u05d4\u05db\u05d9 \u05d8\u05d5\u05d1."],[283.0,"\u05d1\u05d5\u05d7\u05e8\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05db\u05da \u05e9\u05d9\u05d4\u05d9\u05d5 \u05d1\u05d5 \u05d4\u05db\u05d9 \u05de\u05e2\u05d8 \u05e7\u05d5\u05d5\u05d9\u05dd \u05e0\u05e1\u05ea\u05e8\u05d9\u05dd, \u05d5\u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05de\u05e6\u05d1 \u05e9\u05d1\u05d5 \u05d4\u05d7\u05dc\u05e7 \u05de\u05d5\u05e8\u05db\u05d1 \u05d0\u05d5 \u05de\u05e2\u05d5\u05d1\u05d3."],[292.0,"\u05de\u05e1\u05e4\u05e8 \u05d4\u05de\u05d1\u05d8\u05d9\u05dd \u05d4\u05d5\u05d0 \u05d4\u05de\u05d9\u05e0\u05d9\u05de\u05d5\u05dd \u05e9\u05de\u05d2\u05d3\u05d9\u05e8 \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05d1\u05de\u05dc\u05d5\u05d0\u05d5."],[296.0,"\u05d7\u05dc\u05e7 \u05de\u05e1\u05d5\u05d1\u05d1, \u05dc\u05db\u05de\u05d5 \u05e6\u05d9\u05e8, \u05de\u05d5\u05d2\u05d3\u05e8 \u05dc\u05e2\u05d9\u05ea\u05d9\u05dd \u05e7\u05e8\u05d5\u05d1\u05d5\u05ea \u05d1\u05de\u05d1\u05d8 \u05d0\u05d7\u05d3 \u05d1\u05dc\u05d1\u05d3, \u05d5\u05e1\u05d9\u05de\u05df \u05d4\u05e7\u05d5\u05d8\u05e8 \u05de\u05d7\u05dc\u05d9\u05e3 \u05d0\u05ea \u05d4\u05de\u05d1\u05d8 \u05de\u05d4\u05e7\u05e6\u05d4."],[306.0,"\u05de\u05d1\u05d8 \u05de\u05d9\u05d5\u05ea\u05e8 \u05d4\u05d5\u05d0 \u05dc\u05d0 \u05e8\u05e7 \u05d1\u05d6\u05d1\u05d5\u05d6 \u05de\u05e7\u05d5\u05dd. \u05d4\u05d5\u05d0 \u05e2\u05d5\u05d3 \u05de\u05e7\u05d5\u05dd \u05e9\u05d1\u05d5 \u05de\u05d9\u05d3\u05d5\u05ea \u05d9\u05db\u05d5\u05dc\u05d5\u05ea \u05dc\u05e1\u05ea\u05d5\u05e8 \u05d6\u05d5 \u05d0\u05ea \u05d6\u05d5."],[313.0,"\u05de\u05d4 \u05e7\u05d5\u05e8\u05d4 \u05db\u05e9\u05d1\u05d7\u05dc\u05e7 \u05d9\u05e9 \u05de\u05e9\u05d8\u05d7 \u05de\u05e9\u05d5\u05e4\u05e2, \u05e9\u05dc\u05d0 \u05de\u05e7\u05d1\u05d9\u05dc \u05dc\u05d0\u05e3 \u05d0\u05d7\u05d3 \u05de\u05e9\u05dc\u05d5\u05e9\u05ea \u05d4\u05de\u05d9\u05e9\u05d5\u05e8\u05d9\u05dd \u05d4\u05e8\u05d0\u05e9\u05d9\u05d9\u05dd?"],[320.0,"\u05d1\u05db\u05dc \u05d4\u05de\u05d1\u05d8\u05d9\u05dd \u05d4\u05e8\u05d2\u05d9\u05dc\u05d9\u05dd \u05d4\u05d5\u05d0 \u05de\u05d5\u05e4\u05d9\u05e2 \u05de\u05e7\u05d5\u05e6\u05e8, \u05d5\u05e7\u05d3\u05d7 \u05e9\u05e2\u05dc\u05d9\u05d5 \u05e0\u05e8\u05d0\u05d4 \u05db\u05d0\u05dc\u05d9\u05e4\u05e1\u05d4."],[327.0,"\u05db\u05d0\u05df \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05de\u05d1\u05d8 \u05e2\u05d6\u05e8: \u05de\u05d1\u05d8 \u05e9\u05de\u05d5\u05d8\u05dc \u05e2\u05dc \u05de\u05d9\u05e9\u05d5\u05e8 \u05de\u05e7\u05d1\u05d9\u05dc \u05dc\u05de\u05e9\u05d8\u05d7 \u05d4\u05de\u05e9\u05d5\u05e4\u05e2."],[333.0,"\u05d1\u05de\u05d1\u05d8 \u05d4\u05e2\u05d6\u05e8 \u05d4\u05de\u05e9\u05d8\u05d7 \u05de\u05d5\u05e4\u05d9\u05e2 \u05d1\u05d2\u05d5\u05d3\u05dc\u05d5 \u05d5\u05d1\u05e6\u05d5\u05e8\u05ea\u05d5 \u05d4\u05d0\u05de\u05d9\u05ea\u05d9\u05d9\u05dd, \u05d5\u05d4\u05e7\u05d3\u05d7 \u05e0\u05e8\u05d0\u05d4 \u05e2\u05d2\u05d5\u05dc."],[341.0,"\u05de\u05d1\u05d8 \u05d4\u05e2\u05d6\u05e8 \u05de\u05e6\u05d5\u05d9\u05e8 \u05d1\u05d4\u05de\u05e9\u05da \u05db\u05d9\u05d5\u05d5\u05df \u05d4\u05d4\u05e1\u05ea\u05db\u05dc\u05d5\u05ea \u05e2\u05dc \u05d4\u05de\u05e9\u05d8\u05d7, \u05de\u05d4\u05de\u05d1\u05d8 \u05e9\u05d1\u05d5 \u05d4\u05de\u05e9\u05d8\u05d7 \u05e0\u05e8\u05d0\u05d4 \u05db\u05e7\u05d5."],[349.0,"\u05d5\u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05de\u05e6\u05d9\u05d9\u05e8\u05d9\u05dd \u05e8\u05e7 \u05d0\u05ea \u05d4\u05de\u05e9\u05d5\u05d8\u05d7 \u05d4\u05de\u05e9\u05d5\u05e4\u05e2, \u05db\u05de\u05d1\u05d8 \u05e2\u05d6\u05e8 \u05d7\u05dc\u05e7\u05d9, \u05db\u05d3\u05d9 \u05dc\u05d0 \u05dc\u05d4\u05e2\u05de\u05d9\u05e1 \u05d0\u05ea \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8."],[357.0,"\u05db\u05e9\u05d0\u05d9\u05df \u05e6\u05d5\u05e8\u05da \u05d1\u05de\u05d1\u05d8 \u05e9\u05dc\u05dd, \u05de\u05e6\u05d9\u05d9\u05e8\u05d9\u05dd \u05de\u05d1\u05d8 \u05d7\u05dc\u05e7\u05d9, \u05e9\u05e0\u05e7\u05d8\u05e2 \u05d1\u05e7\u05d5 \u05e9\u05d1\u05d9\u05e8\u05d4."],[363.0,"\u05de\u05d1\u05d8 \u05de\u05e7\u05d5\u05de\u05d9 \u05de\u05e8\u05d0\u05d4 \u05e8\u05e7 \u05d0\u05dc\u05de\u05e0\u05d8 \u05d0\u05d7\u05d3, \u05db\u05de\u05d5 \u05e9\u05d2\u05dd \u05d0\u05d5 \u05d7\u05e8\u05d9\u05e5, \u05d1\u05dc\u05d9 \u05dc\u05e6\u05d9\u05d9\u05e8 \u05d0\u05ea \u05db\u05dc \u05d4\u05d7\u05dc\u05e7."],[371.0,"\u05e4\u05e8\u05d8 \u05de\u05d5\u05d2\u05d3\u05dc \u05de\u05e1\u05de\u05df \u05d0\u05d6\u05d5\u05e8 \u05e7\u05d8\u05df \u05d1\u05e2\u05d9\u05d2\u05d5\u05dc \u05d5\u05d1\u05d0\u05d5\u05ea, \u05d5\u05de\u05e6\u05d9\u05d9\u05e8 \u05d0\u05d5\u05ea\u05d5 \u05d1\u05e0\u05e4\u05e8\u05d3 \u05d1\u05e7\u05e0\u05d4 \u05de\u05d9\u05d3\u05d4 \u05d2\u05d3\u05d5\u05dc \u05d9\u05d5\u05ea\u05e8, \u05dc\u05de\u05e9\u05dc \u05e9\u05ea\u05d9\u05d9\u05dd \u05dc\u05d0\u05d7\u05ea."],[381.0,"\u05d5\u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05e4\u05e8\u05d8 \u05d4\u05de\u05d5\u05d2\u05d3\u05dc \u05d4\u05df \u05e2\u05d3\u05d9\u05d9\u05df \u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05d4\u05d0\u05de\u05d9\u05ea\u05d9\u05d5\u05ea, \u05dc\u05d0 \u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05d4\u05de\u05d5\u05d2\u05d3\u05dc\u05d5\u05ea."],[387.0,"\u05d0\u05d5\u05ea \u05e9\u05de\u05e8\u05d0\u05d4 \u05d0\u05ea \u05db\u05d9\u05d5\u05d5\u05df \u05d4\u05de\u05d1\u05d8, \u05d5\u05d0\u05d5\u05ea\u05d4 \u05d0\u05d5\u05ea \u05dc\u05d9\u05d3 \u05d4\u05de\u05d1\u05d8 \u05e2\u05e6\u05de\u05d5."],[398.0,"\u05de\u05d1\u05d8 \u05e9\u05d4\u05d5\u05d6\u05d6 \u05d1\u05dc\u05d9 \u05e1\u05d9\u05de\u05d5\u05df \u05d4\u05d5\u05d0 \u05e9\u05d2\u05d9\u05d0\u05d4 \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8, \u05db\u05d9 \u05d4\u05d5\u05d0 \u05de\u05d1\u05d8\u05dc \u05d0\u05ea \u05d7\u05d5\u05e7\u05d9 \u05d4\u05d4\u05d9\u05d8\u05dc."],[405.0,"\u05d4\u05d9\u05d8\u05dc \u05e0\u05d9\u05e6\u05d1 \u05de\u05e8\u05d0\u05d4 \u05d1\u05db\u05dc \u05de\u05d1\u05d8 \u05e9\u05e0\u05d9 \u05de\u05de\u05d3\u05d9\u05dd, \u05d5\u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05de\u05e9\u05d5\u05e4\u05e2\u05d9\u05dd \u05de\u05d5\u05e4\u05d9\u05e2\u05d9\u05dd \u05d1\u05d5 \u05de\u05e7\u05d5\u05e6\u05e8\u05d9\u05dd."],[413.0,"\u05d1\u05d6\u05d5\u05d5\u05d9\u05ea \u05e9\u05dc\u05d9\u05e9\u05d9\u05ea \u05d4\u05de\u05d1\u05d8 \u05de\u05e6\u05d5\u05d9\u05e8 \u05d1\u05e6\u05d3 \u05e9\u05de\u05de\u05e0\u05d5 \u05de\u05e1\u05ea\u05db\u05dc\u05d9\u05dd. \u05d1\u05d6\u05d5\u05d5\u05d9\u05ea \u05e8\u05d0\u05e9\u05d5\u05e0\u05d4, \u05d1\u05e6\u05d3 \u05d4\u05e0\u05d2\u05d3\u05d9."],[420.0,"\u05dc\u05e4\u05e0\u05d9 \u05e9\u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05de\u05d1\u05d8 \u05d0\u05d7\u05d3, \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d0\u05ea \u05e1\u05de\u05dc \u05d4\u05d4\u05d9\u05d8\u05dc, \u05d5\u05d0\u05dd \u05d0\u05d9\u05df \u05e1\u05de\u05dc, \u05e9\u05d5\u05d0\u05dc\u05d9\u05dd."],[428.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05d7\u05ea\u05d5\u05da \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7: \u05d7\u05ea\u05db\u05d9\u05dd \u05de\u05ea\u05e7\u05d3\u05de\u05d9\u05dd, \u05d5\u05de\u05d4 \u05db\u05dc \u05e1\u05d5\u05d2 \u05d7\u05ea\u05da \u05de\u05d2\u05dc\u05d4 \u05d5\u05de\u05e1\u05ea\u05d9\u05e8."],[436.0,"\u05e0\u05ea\u05e8\u05d0\u05d4 \u05d1\u05e4\u05e8\u05e7 \u05e9\u05ea\u05d9\u05d9\u05dd."]]};
window.MH_TR["ch02"]={"t":"\u05d7\u05ea\u05db\u05d9\u05dd \u05de\u05ea\u05e7\u05d3\u05de\u05d9\u05dd","l":[[1.0,"\u05de\u05d1\u05d8 \u05e8\u05d2\u05d9\u05dc \u05de\u05e8\u05d0\u05d4 \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05de\u05d1\u05d7\u05d5\u05e5. \u05db\u05dc \u05de\u05d4 \u05e9\u05d1\u05e4\u05e0\u05d9\u05dd \u05de\u05d5\u05e4\u05d9\u05e2 \u05d1\u05e7\u05d5\u05d5\u05d9\u05dd \u05e0\u05e1\u05ea\u05e8\u05d9\u05dd."],[8.0,"\u05d1\u05d7\u05dc\u05e7 \u05de\u05d5\u05e8\u05db\u05d1, \u05d4\u05e7\u05d5\u05d5\u05d9\u05dd \u05d4\u05e0\u05e1\u05ea\u05e8\u05d9\u05dd \u05e0\u05e2\u05e8\u05de\u05d9\u05dd \u05d6\u05d4 \u05e2\u05dc \u05d6\u05d4, \u05d5\u05d0\u05d9 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05e7\u05e8\u05d5\u05d0 \u05d0\u05d5\u05ea\u05dd."],[14.0,"\u05d4\u05d7\u05ea\u05da \u05e4\u05d5\u05ea\u05e8 \u05d0\u05ea \u05d6\u05d4: \u05d7\u05d5\u05ea\u05db\u05d9\u05dd \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05d1\u05de\u05d9\u05e9\u05d5\u05e8 \u05d3\u05de\u05d9\u05d5\u05e0\u05d9, \u05de\u05e1\u05d9\u05e8\u05d9\u05dd \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05d4\u05e7\u05e8\u05d5\u05d1, \u05d5\u05de\u05e1\u05ea\u05db\u05dc\u05d9\u05dd \u05e4\u05e0\u05d9\u05de\u05d4."],[22.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05db\u05d9\u05e8 \u05d0\u05ea \u05e1\u05d5\u05d2\u05d9 \u05d4\u05d7\u05ea\u05db\u05d9\u05dd, \u05d0\u05ea \u05d4\u05de\u05d5\u05e1\u05db\u05de\u05d5\u05ea \u05e9\u05dc\u05d4\u05dd, \u05d5\u05d0\u05ea \u05de\u05d4 \u05e9\u05db\u05dc \u05d7\u05ea\u05da \u05de\u05d2\u05dc\u05d4 \u05d5\u05de\u05d4 \u05e9\u05d4\u05d5\u05d0 \u05de\u05e1\u05ea\u05d9\u05e8."],[32.0,"\u05db\u05dc \u05d7\u05ea\u05da \u05de\u05ea\u05d7\u05d9\u05dc \u05d1\u05e7\u05d5 \u05d4\u05d7\u05ea\u05da, \u05e9\u05de\u05e6\u05d5\u05d9\u05e8 \u05d1\u05de\u05d1\u05d8 \u05d4\u05e1\u05de\u05d5\u05da."],[37.0,"\u05d4\u05d5\u05d0 \u05de\u05e8\u05d0\u05d4 \u05d0\u05d9\u05e4\u05d4 \u05e2\u05d5\u05d1\u05e8 \u05de\u05d9\u05e9\u05d5\u05e8 \u05d4\u05d7\u05ea\u05da, \u05d5\u05d4\u05d7\u05e6\u05d9\u05dd \u05d1\u05e7\u05e6\u05d5\u05ea\u05d9\u05d5 \u05de\u05e8\u05d0\u05d9\u05dd \u05dc\u05d0\u05d9\u05d6\u05d4 \u05db\u05d9\u05d5\u05d5\u05df \u05de\u05e1\u05ea\u05db\u05dc\u05d9\u05dd."],[44.0,"\u05d4\u05d0\u05d5\u05ea\u05d9\u05d5\u05ea \u05d1\u05e7\u05e6\u05d5\u05d5\u05ea \u05de\u05d6\u05d4\u05d5\u05ea \u05d0\u05ea \u05d4\u05d7\u05ea\u05da, \u05dc\u05de\u05e9\u05dc \u05d0, \u05d5\u05d4\u05d7\u05ea\u05da \u05e2\u05e6\u05de\u05d5 \u05e0\u05e7\u05e8\u05d0 \u05d7\u05ea\u05da A-A"],[52.0,"\u05dc\u05e4\u05e0\u05d9 \u05e9\u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05d7\u05ea\u05da, \u05de\u05d5\u05e6\u05d0\u05d9\u05dd \u05d0\u05ea \u05e7\u05d5 \u05d4\u05d7\u05ea\u05da \u05e9\u05dc\u05d5. \u05d1\u05dc\u05d9 \u05d6\u05d4 \u05dc\u05d0 \u05d9\u05d5\u05d3\u05e2\u05d9\u05dd \u05de\u05d4 \u05e8\u05d5\u05d0\u05d9\u05dd."],[58.0,"\u05db\u05d9\u05d5\u05d5\u05df \u05d4\u05d7\u05e6\u05d9\u05dd \u05e7\u05d5\u05d1\u05e2 \u05de\u05d4 \u05e0\u05e9\u05d0\u05e8 \u05d1\u05de\u05d1\u05d8: \u05d4\u05d7\u05dc\u05e7 \u05e9\u05d4\u05e2\u05d9\u05df \u05e8\u05d5\u05d0\u05d4, \u05dc\u05d0 \u05d4\u05d7\u05dc\u05e7 \u05e9\u05d4\u05d5\u05e1\u05e8."],[66.0,"\u05de\u05e9\u05d8\u05d7 \u05e9\u05e0\u05d7\u05ea\u05da \u05de\u05e1\u05d5\u05de\u05df \u05d1\u05e7\u05d9\u05d5\u05d5\u05e7\u05d5\u05d5: \u05e7\u05d5\u05d5\u05d9\u05dd \u05d3\u05e7\u05d9\u05dd \u05d5\u05de\u05e7\u05d1\u05d9\u05dc\u05d9\u05dd, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05d6\u05d5\u05d5\u05d9\u05ea \u05e9\u05dc 45 \u05de\u05e2\u05dc\u05d5\u05ea."],[75.0,"\u05de\u05d4 \u05e9\u05de\u05d0\u05d7\u05d5\u05e8\u05d9 \u05de\u05d9\u05e9\u05d5\u05e8 \u05d4\u05d7\u05ea\u05da \u05de\u05e6\u05d5\u05d9\u05e8 \u05d1\u05e7\u05d5\u05d5\u05d9\u05dd \u05e8\u05d2\u05d9\u05dc\u05d9\u05dd, \u05d5\u05de\u05d4 \u05e9\u05e0\u05e1\u05ea\u05e8 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05dc\u05d0 \u05de\u05e6\u05d5\u05d9\u05e8 \u05d1\u05db\u05dc\u05dc."],[83.0,"\u05dc\u05d7\u05dc\u05e7 \u05d0\u05d7\u05d3 \u05d9\u05e9 \u05d0\u05d5\u05ea\u05d5 \u05e7\u05d9\u05d5\u05d5\u05e7\u05d5\u05d5 \u05d1\u05db\u05dc \u05d4\u05d7\u05ea\u05db\u05d9\u05dd \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8."],[88.0,"\u05d0\u05d5 \u05d1\u05e6\u05e4\u05d9\u05e4\u05d5\u05ea \u05e9\u05d5\u05e0\u05d4, \u05db\u05d3\u05d9 \u05e9\u05d9\u05d4\u05d9\u05d4 \u05d1\u05e8\u05d5\u05e8 \u05d0\u05d9\u05e4\u05d4 \u05e0\u05d2\u05de\u05e8 \u05d7\u05dc\u05e7 \u05d0\u05d7\u05d3\u05d5\u05de\u05ea\u05d7\u05d9\u05dc \u05d4\u05e9\u05e0\u05d9."],[99.0,"\u05d3\u05d5\u05d2\u05de\u05ea \u05d4\u05e7\u05d9\u05d5\u05d5\u05e7\u05e8 \u05d0\u05d9\u05e0\u05d4 \u05de\u05d2\u05d3\u05d9\u05e8\u05d4 \u05d0\u05ea \u05d4\u05d7\u05d5\u05de\u05e8. \u05d4\u05d7\u05d5\u05de\u05e8 \u05de\u05d5\u05d2\u05d3\u05e8 \u05d1\u05d0\u05d6\u05d5\u05e8 \u05d4\u05db\u05d5\u05ea\u05e8\u05ea \u05d0\u05d5 \u05d1\u05e8\u05e9\u05d9\u05de\u05ea \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd."],[107.0,"\u05d5\u05d7\u05dc\u05e7 \u05d3\u05e7 \u05de\u05d0\u05d5\u05d3, \u05db\u05de\u05d5 \u05d0\u05d8\u05dd \u05d0\u05d5 \u05e4\u05d7, \u05de\u05e1\u05d5\u05de\u05df \u05dc\u05e2\u05d9\u05ea\u05d9\u05dd \u05d1\u05de\u05d9\u05dc\u05d5\u05d9 \u05de\u05dc\u05d0, \u05d5\u05dc\u05d0 \u05d1\u05e7\u05d9\u05d5\u05d5\u05e7\u05d5\u05d5."],[115.0,"\u05d1\u05d7\u05ea\u05da \u05de\u05dc\u05d0, \u05d4\u05de\u05d9\u05e9\u05d5\u05e8 \u05e2\u05d5\u05d1\u05e8 \u05dc\u05d0\u05d5\u05e8\u05da \u05db\u05dc \u05d4\u05d7\u05dc\u05e7, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05e6\u05d9\u05e8 \u05d4\u05e1\u05d9\u05de\u05d8\u05e8\u05d9\u05d4."],[122.0,"\u05d1\u05d7\u05dc\u05e7 \u05e1\u05d9\u05de\u05d8\u05e8\u05d9 \u05d0\u05e4\u05e9\u05d5\u05e8 \u05dc\u05d7\u05e1\u05d5\u05da: \u05d7\u05e6\u05d9 \u05d7\u05ea\u05da \u05de\u05e1\u05d9\u05e8 \u05e8\u05e7 \u05e8\u05d1\u05e2 \u05de\u05d4\u05d7\u05dc\u05e7, \u05d5\u05d1\u05de\u05d1\u05d8 \u05de\u05d5\u05e4\u05d9\u05e2 \u05d7\u05e6\u05d9 \u05d7\u05ea\u05d5\u05da \u05d5\u05d7\u05e6\u05d9 \u05de\u05d1\u05d7\u05d5\u05e5."],[132.0,"\u05db\u05da \u05d4\u05d0\u05d9\u05dd \u05d1\u05ea\u05de\u05d5\u05e0\u05d4 \u05d0\u05d7\u05ea \u05d2\u05dd \u05d0\u05ea \u05d4\u05e6\u05d5\u05e8\u05d4 \u05d4\u05d7\u05d9\u05e6\u05d5\u05e0\u05d9\u05ea \u05d5\u05d2\u05dd \u05d0\u05ea \u05d4\u05e4\u05e0\u05d9\u05de\u05d9\u05ea."],[137.0,"\u05d4\u05d2\u05d1\u05d5\u05dc \u05d1\u05d9\u05df \u05e9\u05e0\u05d9 \u05d4\u05d7\u05e6\u05d0\u05d9\u05dd \u05d4\u05d5\u05d0 \u05e7\u05d5 \u05de\u05e8\u05db\u05d6, \u05d5\u05dc\u05d0 \u05e7\u05d5 \u05de\u05dc\u05d0, \u05db\u05d9 \u05e9\u05dd \u05d0\u05d9\u05df \u05d1\u05d0\u05de\u05ea \u05e7\u05e6\u05d4."],[144.0,"\u05d5\u05d1\u05e6\u05d3 \u05e9\u05d0\u05d9\u05e0\u05d5 \u05d7\u05ea\u05d5\u05da \u05dc\u05d0 \u05de\u05e6\u05d9\u05d9\u05e8\u05d9\u05dd \u05e7\u05d5\u05d5\u05d9\u05dd \u05e0\u05e1\u05ea\u05e8\u05d9\u05dd, \u05db\u05d9 \u05d4\u05e6\u05d3 \u05d4\u05d7\u05ea\u05d5\u05da \u05db\u05d1\u05e8 \u05de\u05e8\u05d0\u05d4 \u05d0\u05d5\u05ea\u05dd."],[151.0,"\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d4\u05d0\u05dc\u05de\u05e0\u05d8\u05d9\u05dd \u05d4\u05d7\u05e9\u05d5\u05d1\u05d9\u05dd \u05dc\u05d0 \u05e0\u05de\u05e6\u05d0\u05d9\u05dd \u05d1\u05d0\u05d5\u05ea\u05d5 \u05de\u05d9\u05e9\u05d5\u05e8."],[156.0,"\u05d1\u05d7\u05ea\u05da \u05de\u05d3\u05d5\u05e8\u05d2, \u05e7\u05d5 \u05d4\u05d7\u05ea\u05da \u05de\u05e9\u05e0\u05d4 \u05db\u05d9\u05d5\u05d5\u05df \u05d1\u05d6\u05d5\u05d5\u05d9\u05d5\u05ea \u05d9\u05e9\u05e8\u05d5\u05ea, \u05d5\u05e2\u05d5\u05d1\u05e8 \u05d3\u05e8\u05da \u05db\u05dc \u05d4\u05d0\u05dc\u05de\u05e0\u05d8\u05d9\u05dd."],[163.0,"\u05d1\u05d7\u05ea\u05da \u05e2\u05e6\u05de\u05d5 \u05de\u05e6\u05d9\u05d9\u05e8\u05d9\u05dd \u05d4\u05db\u05d5\u05dc \u05db\u05d0\u05d9\u05dc\u05d5 \u05e0\u05d7\u05ea\u05da \u05d1\u05de\u05d9\u05e9\u05d5\u05e8 \u05d0\u05d7\u05d3, \u05d5\u05d0\u05ea \u05e0\u05e7\u05d5\u05d3\u05d5\u05ea \u05d4\u05e9\u05d1\u05d9\u05e8\u05d4 \u05e9\u05dc \u05e7\u05d5 \u05d4\u05d7\u05ea\u05da \u05dc\u05d0 \u05de\u05e8\u05d0\u05d9\u05dd."],[172.0,"\u05dc\u05db\u05df \u05de\u05d9 \u05e9\u05e7\u05d5\u05e8\u05d0 \u05d0\u05ea \u05d4\u05d7\u05ea\u05da \u05d1\u05dc\u05d9 \u05dc\u05d1\u05d3\u05d5\u05e7 \u05d0\u05ea \u05e7\u05d5 \u05d4\u05d7\u05ea\u05da, \u05e2\u05dc\u05d5\u05dc \u05dc\u05d7\u05e9\u05d5\u05d1 \u05e9\u05db\u05dc \u05d4\u05d0\u05dc\u05de\u05e0\u05d8\u05d9\u05dd \u05e0\u05de\u05e6\u05d0\u05d9\u05dd \u05d1\u05e9\u05d5\u05e8\u05d4 \u05d0\u05d7\u05ea."],[181.0,"\u05d1\u05d7\u05dc\u05e7 \u05e2\u05d2\u05d5\u05dc, \u05db\u05de\u05d5 \u05d0\u05d5\u05d2\u05df, \u05d4\u05e7\u05d3\u05d7\u05d9\u05dd \u05d9\u05d5\u05e9\u05d1\u05d9\u05dd \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05e2\u05dc \u05de\u05e2\u05d2\u05dc, \u05d5\u05dc\u05d0 \u05d6\u05d4 \u05de\u05d5\u05dc \u05d6\u05d4."],[188.0,"\u05d1\u05d7\u05ea\u05da \u05de\u05d9\u05d5\u05e9\u05e8, \u05e7\u05d5 \u05d4\u05d7\u05ea\u05da \u05e2\u05d5\u05d1\u05e8 \u05d3\u05e8\u05da \u05d4\u05e7\u05d3\u05d7\u05d9\u05dd \u05d1\u05d6\u05d5\u05d5\u05d9\u05ea, \u05d5\u05d0\u05d6 \u05d4\u05d7\u05dc\u05e7 \u05d4\u05e0\u05d8\u05d5\u05d9 \u05de\u05e1\u05d5\u05d1\u05d1 \u05d0\u05dc \u05d4\u05de\u05d9\u05e9\u05d5\u05e8."],[197.0,"\u05db\u05da \u05d4\u05e7\u05d3\u05d7\u05d9\u05dd \u05de\u05d5\u05e4\u05d9\u05e2\u05d9\u05dd \u05d1\u05d7\u05ea\u05da \u05d1\u05de\u05e8\u05d7\u05e7 \u05d4\u05d0\u05de\u05d9\u05ea\u05d9 \u05e9\u05dc\u05d4\u05dd \u05de\u05d4\u05de\u05e8\u05db\u05d6."],[202.0,"\u05d5\u05d6\u05d5 \u05e0\u05e7\u05d5\u05d3\u05d4 \u05d7\u05e9\u05d5\u05d1\u05d4: \u05d7\u05ea\u05da \u05db\u05d6\u05d4 \u05d0\u05d9\u05e0\u05d5 \u05d4\u05d9\u05d8\u05dc \u05d0\u05de\u05d9\u05ea\u05d9. \u05d4\u05d5\u05d0 \u05e1\u05d5\u05d8\u05d4 \u05d1\u05db\u05d5\u05d5\u05e0\u05d4 \u05de\u05d7\u05d5\u05e7\u05d9 \u05d4\u05d4\u05d9\u05d8\u05dc, \u05db\u05d3\u05d9 \u05dc\u05d4\u05e8\u05d0\u05d5\u05ea \u05d0\u05ea \u05de\u05d4 \u05e9\u05d7\u05e9\u05d5\u05d1."],[212.0,"\u05d0\u05d5\u05d2\u05df \u05e2\u05dd \u05e9\u05dc\u05d5\u05e9\u05d4 \u05e7\u05d3\u05d7\u05d9\u05dd, \u05d1\u05de\u05e8\u05d7\u05e7 120 \u05de\u05e2\u05dc\u05d5\u05ea \u05d6\u05d4 \u05de\u05d6\u05d4, \u05d9\u05d9\u05e8\u05d0\u05d4 \u05d1\u05d7\u05ea\u05da \u05db\u05d0\u05d9\u05dc\u05d5 \u05d9\u05e9 \u05dc\u05d5 \u05e7\u05d3\u05d7\u05d9\u05dd \u05de\u05e9\u05d5\u05e0\u05d9 \u05e6\u05d3\u05d9 \u05d4\u05de\u05e8\u05db\u05d6."],[222.0,"\u05d0\u05ea \u05de\u05e1\u05e4\u05e8 \u05d4\u05e7\u05d3\u05d7\u05d9\u05dd \u05d5\u05d0\u05ea \u05d4\u05de\u05d9\u05e7\u05d5\u05dd \u05d4\u05d6\u05d5\u05d5\u05d9\u05ea\u05d9 \u05e9\u05dc\u05d4\u05dd \u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05d1\u05de\u05d1\u05d8 \u05d4\u05e7\u05d3\u05de\u05d9, \u05dc\u05d0 \u05d1\u05d7\u05ea\u05da."],[229.0,"\u05d9\u05e9 \u05d3\u05d1\u05e8\u05d9\u05dd \u05e9\u05dc\u05d0 \u05de\u05e7\u05d5\u05d5\u05e7\u05d5\u05d5\u05d9\u05dd \u05d2\u05dd \u05db\u05e9\u05d4\u05de\u05d9\u05e9\u05d5\u05e8 \u05e2\u05d5\u05d1\u05e8 \u05d3\u05e8\u05db\u05dd."],[233.0,"\u05e6\u05dc\u05e2 \u05d0\u05d5 \u05d3\u05d5\u05e4\u05df \u05d3\u05e7\u05d4 \u05e9\u05e0\u05d7\u05ea\u05db\u05ea \u05dc\u05d0\u05d5\u05e8\u05db\u05d4 \u05dc\u05d0 \u05de\u05e7\u05d5\u05d5\u05e7\u05d5\u05d5\u05ea, \u05db\u05d9 \u05e7\u05d9\u05d5\u05d5\u05e7\u05d5\u05d5 \u05d4\u05d9\u05d4 \u05e0\u05d5\u05ea\u05df \u05e8\u05d5\u05e8\u05e9\u05dd \u05e9\u05dc \u05d7\u05dc\u05e7 \u05de\u05dc\u05d0 \u05d5\u05db\u05d1\u05d3."],[243.0,"\u05d1\u05d0\u05d5\u05ea\u05d5 \u05d0\u05d5\u05e4\u05df, \u05d1\u05d4\u05e8\u05db\u05d1\u05d4 \u05dc\u05d0 \u05d7\u05d5\u05ea\u05db\u05d9\u05dd \u05dc\u05d0\u05d5\u05e8\u05db\u05dd \u05e6\u05d9\u05e8\u05d9\u05dd, \u05d1\u05e8\u05d2\u05d9\u05dd, \u05d0\u05d5\u05de\u05d9\u05dd, \u05e4\u05d9\u05e0\u05d9\u05dd, \u05e9\u05d2\u05de\u05d9\u05dd \u05d5\u05db\u05d3\u05d5\u05e8\u05d9\u05dd."],[252.0,"\u05d4\u05dd \u05de\u05e6\u05d5\u05d9\u05e8\u05d9\u05dd \u05e9\u05dc\u05de\u05d9\u05dd, \u05d2\u05dd \u05db\u05e9\u05d4\u05de\u05d9\u05e9\u05d5\u05e8 \u05e2\u05d5\u05d1\u05e8 \u05d1\u05d3\u05d9\u05d5\u05e7 \u05d1\u05e6\u05d9\u05e8 \u05e9\u05dc\u05d4\u05dd."],[257.0,"\u05de\u05d9 \u05e9\u05dc\u05d0 \u05de\u05db\u05d9\u05e8 \u05d0\u05ea \u05d4\u05de\u05d5\u05e1\u05db\u05de\u05d4 \u05d4\u05d6\u05d5, \u05e2\u05dc\u05d5\u05dc \u05dc\u05d7\u05e9\u05d5\u05d1 \u05e9\u05d4\u05d1\u05d5\u05e8\u05d2 \u05d1\u05db\u05dc\u05dc \u05dc\u05d0 \u05e0\u05d7\u05ea\u05da, \u05d0\u05d5 \u05e9\u05d4\u05e6\u05dc\u05e2 \u05dc\u05d0 \u05e7\u05d9\u05d9\u05de\u05ea."],[265.0,"\u05d5\u05d1\u05d7\u05dc\u05e7 \u05e2\u05dd \u05e6\u05dc\u05e2\u05d5\u05ea \u05d0\u05d5 \u05d7\u05d9\u05e9\u05d5\u05e8\u05d9\u05dd \u05e9\u05d0\u05d9\u05e0\u05dd \u05d1\u05e7\u05d5 \u05d4\u05d7\u05ea\u05da, \u05de\u05e1\u05d5\u05d1\u05d1\u05d9\u05dd \u05d2\u05dd \u05d0\u05d5\u05ea\u05dd \u05d0\u05dc \u05d4\u05de\u05d9\u05e9\u05d5\u05e8, \u05db\u05de\u05d5 \u05d1\u05d7\u05ea\u05da \u05de\u05d9\u05d5\u05e9\u05e8."],[273.0,"\u05db\u05e9\u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05e8\u05d0\u05d5\u05ea \u05e8\u05e7 \u05d0\u05d6\u05d5\u05e8 \u05e7\u05d8\u05df \u05d1\u05e4\u05e0\u05d9\u05dd, \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05d7\u05ea\u05da \u05de\u05e7\u05d5\u05de\u05d9."],[279.0,"\u05de\u05e1\u05d9\u05e8\u05d9\u05dd \u05d7\u05dc\u05e7 \u05e7\u05d8\u05df \u05de\u05d4\u05de\u05d1\u05d8, \u05d5\u05ea\u05d5\u05d7\u05de\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05d1\u05e7\u05d5 \u05e9\u05d1\u05d9\u05e8\u05d4 \u05d1\u05d9\u05d3 \u05d7\u05d5\u05e4\u05e9\u05d9\u05ea."],[285.0,"\u05d0\u05e8\u05d5\u05da, \u05db\u05de\u05d5 \u05d7\u05d9\u05e9\u05d5\u05e8 \u05d0\u05d5 \u05d6\u05e8\u05d5\u05e2. \u05d4\u05d5\u05d0 \u05de\u05e1\u05d5\u05d1\u05d1 \u05d1\u05ea\u05e9\u05e2\u05d9\u05dd \u05de\u05e2\u05dc\u05d5\u05ea \u05d5\u05de\u05e6\u05d5\u05d9\u05e8 \u05e2\u05dc \u05d4\u05de\u05d1\u05d8 \u05e2\u05e6\u05de\u05d5."],[297.0,"\u05d7\u05ea\u05da \u05de\u05d5\u05d6\u05d6 \u05d4\u05d5\u05d0 \u05d0\u05d5\u05ea\u05d5 \u05e8\u05e2\u05d9\u05d5\u05df, \u05d0\u05d1\u05dc \u05d4\u05d5\u05d0 \u05de\u05e6\u05d5\u05d9\u05e8 \u05de\u05d7\u05d5\u05e5 \u05dc\u05de\u05d1\u05d8, \u05de\u05e1\u05d5\u05de\u05df \u05d1\u05d0\u05d5\u05ea\u05d9\u05d5\u05ea, \u05d5\u05dc\u05e2\u05d9\u05ea\u05d9\u05dd \u05d1\u05e7\u05e0\u05d4 \u05de\u05d9\u05d3\u05d4 \u05d2\u05d3\u05d5\u05dc \u05d9\u05d5\u05ea\u05e8."],[306.0,"\u05d7\u05ea\u05da \u05de\u05d2\u05dc\u05d4 \u05d0\u05ea \u05d4\u05e4\u05e0\u05d9\u05dd, \u05d0\u05d1\u05dc \u05e8\u05e7 \u05d1\u05de\u05e7\u05d5\u05dd \u05e9\u05d1\u05d5 \u05e2\u05d1\u05e8 \u05d4\u05de\u05d9\u05e9\u05d5\u05e8."],[311.0,"\u05e9\u05e7\u05d5\u05d5\u05d9\u05dd \u05e0\u05e1\u05ea\u05e8\u05d9\u05dd \u05dc\u05d0 \u05de\u05e6\u05d5\u05d9\u05e8\u05d9\u05dd, \u05d4\u05d5\u05d0 \u05d2\u05dd \u05dc\u05d0 \u05d9\u05d5\u05e4\u05d9\u05e2 \u05db\u05e7\u05d5 \u05e0\u05e1\u05ea\u05e8."],[321.0,"\u05dc\u05db\u05df \u05d7\u05ea\u05da \u05d4\u05d5\u05d0 \u05d0\u05e3 \u05e4\u05e2\u05dd \u05dc\u05d0 \u05ea\u05de\u05d5\u05e0\u05d4 \u05e9\u05dc\u05de\u05d4. \u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05d9\u05d7\u05d3 \u05e2\u05dd \u05d4\u05de\u05d1\u05d8\u05d9\u05dd \u05d4\u05d0\u05d7\u05e8\u05d9\u05dd."],[328.0,"\u05d5\u05db\u05e9\u05e0\u05e8\u05d0\u05d4 \u05e9\u05d0\u05dc\u05de\u05e0\u05d8 \u05d7\u05e1\u05e8, \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05e7\u05d5\u05d3\u05dd \u05d0\u05dd \u05d4\u05d5\u05d0 \u05e4\u05e9\u05d5\u05d8 \u05dc\u05d0 \u05e0\u05de\u05e6\u05d0 \u05d1\u05de\u05d9\u05e9\u05d5\u05e8 \u05d4\u05d7\u05ea\u05da, \u05dc\u05e4\u05e0\u05d9 \u05e9\u05de\u05e0\u05d9\u05d7\u05d9\u05dd \u05e9\u05d4\u05d5\u05d0 \u05dc\u05d0 \u05e7\u05d9\u05d9\u05dd."],[337.0,"\u05dc\u05e4\u05e0\u05d9 \u05db\u05dc \u05d7\u05ea\u05da: \u05de\u05d5\u05e6\u05d0\u05d9\u05dd \u05d0\u05ea \u05e7\u05d5 \u05d4\u05d7\u05ea\u05da \u05d5\u05d0\u05ea \u05db\u05d9\u05d5\u05d5\u05df \u05d4\u05d7\u05e6\u05d9\u05dd."],[342.0,"\u05d7\u05ea\u05da \u05de\u05d3\u05d5\u05e8\u05d2 \u05d5\u05d7\u05ea\u05da \u05de\u05d9\u05d5\u05e9\u05e8 \u05de\u05e6\u05d9\u05d2\u05d9\u05dd \u05d0\u05dc\u05de\u05e0\u05d8\u05d9\u05dd \u05db\u05d0\u05d9\u05dc\u05d5 \u05d4\u05dd \u05d1\u05d0\u05d5\u05ea\u05d5 \u05de\u05d9\u05e9\u05d5\u05e8, \u05d2\u05dd \u05db\u05e9\u05d4\u05dd \u05dc\u05d0."],[350.0,"\u05e6\u05dc\u05e2\u05d5\u05ea, \u05e6\u05d9\u05e8\u05d9\u05dd \u05d5\u05d1\u05e8\u05d2\u05d9\u05dd \u05e9\u05e0\u05d7\u05ea\u05db\u05d9\u05dd \u05dc\u05d0\u05d5\u05e8\u05db\u05dd \u05dc\u05d0 \u05de\u05e7\u05d5\u05d5\u05e7\u05d5\u05d5\u05d9\u05dd, \u05d5\u05d6\u05d5 \u05de\u05d5\u05e1\u05db\u05de\u05d4, \u05dc\u05d0 \u05d8\u05e2\u05d5\u05ea."],[357.0,"\u05d5\u05de\u05d4 \u05e9\u05dc\u05d0 \u05e0\u05de\u05e6\u05d0 \u05d1\u05de\u05d9\u05e9\u05d5\u05e8 \u05dc\u05d0 \u05de\u05d5\u05e4\u05d9\u05e2 \u05d1\u05d7\u05ea\u05da. \u05d4\u05d7\u05ea\u05da \u05de\u05e9\u05dc\u05d9\u05dd \u05d0\u05ea \u05d4\u05de\u05d1\u05d8\u05d9\u05dd, \u05d5\u05dc\u05d0 \u05de\u05d7\u05dc\u05d9\u05e3 \u05d0\u05d5\u05ea\u05dd."],[365.0,"\u05d4\u05e9\u05e8\u05d8\u05d5\u05d8: \u05d4\u05d1\u05e8\u05d2\u05d5\u05ea, \u05d2\u05dc\u05d2\u05dc\u05d9 \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd, \u05e7\u05e4\u05d9\u05e6\u05d9\u05dd, \u05de\u05d1\u05e0\u05d9\u05dd \u05d7\u05d5\u05d6\u05e8\u05d9\u05dd, \u05d5\u05d0\u05d9\u05e4\u05d4 \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05de\u05e4\u05e9\u05d8 \u05d1\u05db\u05d5\u05d5\u05e0\u05d4."],[378.0,"\u05e0\u05ea\u05e8\u05d0\u05d4 \u05d1\u05e4\u05e8\u05e7 \u05e9\u05dc\u05d5\u05e9."]]};
window.MH_TR["ch03"]={"t":"\u05de\u05d5\u05e1\u05db\u05de\u05d5\u05ea \u05d5\u05e4\u05d9\u05e9\u05d5\u05d8\u05d9\u05dd","l":[[1.0,"\u05e9\u05e8\u05d8\u05d5\u05d8 \u05dc\u05d0 \u05de\u05e0\u05e1\u05d4 \u05dc\u05d4\u05d9\u05d5\u05ea \u05ea\u05de\u05d5\u05e0\u05d4 \u05de\u05d3\u05d5\u05d9\u05e7\u05ea \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7."],[5.0,"\u05d0\u05d5 \u05e9\u05dc \u05db\u05dc \u05dc\u05d9\u05e4\u05d5\u05e3 \u05d1\u05e7\u05e4\u05d9\u05e5 \u05d4\u05d9\u05d4 \u05dc\u05d5\u05e7\u05d7 \u05e9\u05e2\u05d5\u05ea, \u05d5\u05dc\u05d0 \u05d4\u05d9\u05d4 \u05de\u05d5\u05e1\u05d9\u05e3 \u05de\u05d9\u05d3\u05e2."],[16.0,"\u05dc\u05db\u05df \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05de\u05e9\u05ea\u05de\u05e9 \u05d1\u05de\u05d5\u05e1\u05db\u05de\u05d5\u05ea: \u05d9\u05d9\u05e6\u05d5\u05d2 \u05de\u05e7\u05d5\u05e6\u05e8 \u05d5\u05de\u05d5\u05e1\u05db\u05dd, \u05e9\u05de\u05ea\u05d0\u05e8 \u05d0\u05ea \u05d4\u05d0\u05dc\u05de\u05e0\u05d8 \u05d1\u05dc\u05d9 \u05dc\u05e6\u05d9\u05d9\u05e8 \u05d0\u05d5\u05ea\u05d5."],[25.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05db\u05d9\u05e8 \u05d0\u05ea \u05d4\u05de\u05d5\u05e1\u05db\u05de\u05d5\u05ea \u05d4\u05d7\u05e9\u05d5\u05d1\u05d5\u05ea, \u05d5\u05d0\u05ea \u05d4\u05e2\u05d9\u05e7\u05e8\u05d5\u05df \u05e9\u05de\u05d0\u05d7\u05d5\u05e8\u05d9 \u05db\u05d5\u05dc\u05df: \u05db\u05e9\u05d4\u05e6\u05d9\u05d5\u05e8 \u05de\u05e4\u05d5\u05e9\u05d8, \u05d4\u05de\u05d9\u05d3\u05e2 \u05e0\u05de\u05e6\u05d0 \u05d1\u05db\u05d9\u05ea\u05d5\u05d1."],[35.0,"\u05d1\u05d4\u05d1\u05e8\u05d2\u05d4 \u05d7\u05d9\u05e6\u05d5\u05e0\u05d9\u05ea, \u05dc\u05e4\u05d9 ISO \u05d4\u05e7\u05d5\u05d8\u05e8 \u05d4\u05d7\u05d9\u05e6\u05d5\u05e0\u05d9 \u05de\u05e6\u05d5\u05d9\u05e8 \u05d1\u05e7\u05d5 \u05e2\u05d1\u05d4, \u05d5\u05e7\u05d5\u05d8\u05e8 \u05d4\u05e9\u05d5\u05d5\u05e8\u05e9\u05d5 \u05d1\u05e7\u05d5 \u05d3\u05e7."],[44.0,"\u05d1\u05de\u05d1\u05d8 \u05de\u05d4\u05e7\u05e6\u05d4, \u05e7\u05d5\u05d8\u05e8 \u05d4\u05e9\u05d5\u05e8\u05e9\u05d5 \u05de\u05e6\u05d5\u05d9\u05e8 \u05db\u05e9\u05dc\u05d5\u05e9\u05d4 \u05e8\u05d1\u05e2\u05d9\u05dd \u05e9\u05dc \u05e2\u05d9\u05d2\u05d5\u05dc \u05d3\u05e7, \u05db\u05d3\u05d9 \u05e9\u05dc\u05d0 \u05d9\u05ea\u05d1\u05dc\u05d1\u05dc \u05e2\u05dd \u05e7\u05d3\u05d7 \u05d0\u05d5 \u05e2\u05dd \u05e9\u05e4\u05d4."],[53.0,"\u05e7\u05d5 \u05e2\u05d1\u05d4 \u05de\u05e1\u05de\u05df \u05d0\u05ea \u05e1\u05d5\u05e3 \u05d4\u05d4\u05d1\u05e8\u05d2\u05d4 \u05d4\u05de\u05dc\u05d0\u05d4."],[57.0,"\u05dc\u05e2\u05d9\u05ea\u05d9\u05dd \u05d1\u05e7\u05d5 \u05e0\u05e1\u05ea\u05e8, \u05d5\u05dc\u05db\u05df \u05e6\u05e8\u05d9\u05da \u05dc\u05d3\u05e2\u05ea \u05dc\u05e4\u05d9 \u05d0\u05d9\u05d6\u05d4 \u05ea\u05e7\u05df \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8."],[69.0,"\u05d1\u05db\u05dc \u05d4\u05de\u05e7\u05e8\u05d9\u05dd, \u05d4\u05e6\u05d9\u05d5\u05e8 \u05dc\u05d0 \u05de\u05d2\u05d3\u05d9\u05e8 \u05d0\u05ea \u05d4\u05d4\u05d1\u05e8\u05d2\u05d4. \u05d4\u05db\u05d9\u05ea\u05d5\u05d1 \u05de\u05d2\u05d3\u05d9\u05e8 \u05d0\u05d5\u05ea\u05d4: \u05e1\u05d5\u05d2, \u05e7\u05d5\u05d8\u05e8, \u05e4\u05e1\u05d9\u05e2\u05d4 \u05d5\u05d3\u05e8\u05d2\u05ea \u05d4\u05ea\u05d0\u05de\u05d4."],[79.0,"\u05d1\u05d4\u05d1\u05e8\u05d2\u05d4 \u05e4\u05e0\u05d9\u05de\u05d9\u05ea \u05d4\u05ea\u05de\u05d5\u05e0\u05d4 \u05de\u05ea\u05d4\u05e4\u05db\u05ea: \u05e7\u05d5\u05d8\u05e8 \u05d4\u05e7\u05d3\u05d7, \u05e9\u05d4\u05d5\u05d0 \u05e7\u05d5\u05d8\u05e8 \u05d4\u05e9\u05d5\u05e8\u05e9, \u05de\u05e6\u05d5\u05d9\u05e8 \u05d1\u05e7\u05d5 \u05e2\u05d1\u05d4, \u05d5\u05d4\u05e7\u05d5\u05d8\u05e8 \u05d4\u05d7\u05d9\u05e6\u05d5\u05e0\u05d9 \u05d1\u05e7\u05d5\u05d3\u05e7."],[91.0,"\u05d1\u05d7\u05ea\u05da, \u05d4\u05e7\u05d9\u05d5\u05d5\u05e7\u05d5\u05d5 \u05de\u05d2\u05d9\u05e2 \u05e2\u05d3 \u05d4\u05e7\u05d5 \u05d4\u05e2\u05d1\u05d4, \u05db\u05dc\u05d5\u05de\u05e8 \u05e2\u05d3 \u05d3\u05d5\u05e4\u05df \u05d4\u05e7\u05d3\u05d7."],[97.0,"\u05d1\u05e7\u05d3\u05d7 \u05e2\u05d9\u05d5\u05d5\u05e8 \u05de\u05e6\u05d9\u05d9\u05e8\u05d9\u05dd \u05d2\u05dd \u05d0\u05ea \u05e2\u05d5\u05de\u05e7 \u05d4\u05d4\u05d1\u05e8\u05d2\u05d4 \u05d5\u05d2\u05dd \u05d0\u05ea \u05e2\u05d5\u05de\u05e7 \u05d4\u05e7\u05d9\u05d3\u05d5\u05d7, \u05e9\u05d4\u05d5\u05d0 \u05ea\u05de\u05d9\u05d3 \u05e2\u05de\u05d5\u05e7 \u05d9\u05d5\u05ea\u05e8."],[105.0,"\u05d5\u05e7\u05e6\u05d4 \u05d4\u05de\u05e7\u05d3\u05d7 \u05de\u05e6\u05d5\u05d9\u05e8 \u05db\u05d7\u05e8\u05d5\u05d8 \u05d1\u05d6\u05d5\u05d5\u05d9\u05ea \u05e9\u05dc 120 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d2\u05dd \u05d0\u05dd \u05d6\u05d5\u05d5\u05d9\u05ea \u05d4\u05de\u05e7\u05d3\u05d7 \u05d1\u05e4\u05d5\u05e2\u05dc \u05d4\u05d9\u05d0 118."],[114.0,"\u05e2\u05d5\u05de\u05e7 \u05d4\u05e7\u05d3\u05d7 \u05e0\u05de\u05d3\u05d3 \u05e2\u05d3 \u05e1\u05d5\u05e3 \u05d4\u05e7\u05d5\u05d8\u05e8 \u05d4\u05de\u05dc\u05d0, \u05d5\u05dc\u05d0 \u05e2\u05d3 \u05e7\u05e6\u05d4 \u05d4\u05d7\u05e8\u05d5\u05d8."],[120.0,"\u05db\u05e9\u05d1\u05d5\u05e8\u05d2 \u05de\u05d5\u05d1\u05e8\u05d2 \u05dc\u05ea\u05d5\u05da \u05e7\u05d3\u05d7 \u05de\u05d5\u05d1\u05e8\u05d2, \u05d5\u05d1\u05d4\u05e8\u05db\u05d1\u05d4 \u05de\u05e6\u05d9\u05d9\u05e8\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05d1\u05d7\u05ea\u05da, \u05e9\u05ea\u05d9 \u05d4\u05d4\u05d1\u05e8\u05d2\u05d5\u05ea \u05e0\u05e4\u05d2\u05e9\u05d5\u05ea."],[128.0,"\u05d4\u05de\u05d5\u05e1\u05db\u05de\u05d4 \u05d4\u05d9\u05d0 \u05e9\u05d4\u05d4\u05d1\u05e8\u05d2\u05d4 \u05d4\u05d7\u05d9\u05e6\u05d5\u05e0\u05d9\u05ea \u05d2\u05d5\u05d1\u05e8\u05ea: \u05de\u05e6\u05d9\u05d9\u05e8\u05d9\u05dd \u05d0\u05ea \u05d4\u05d1\u05d5\u05e8\u05d2 \u05d1\u05de\u05dc\u05d5\u05d0\u05d5, \u05d5\u05d4\u05d5\u05d0 \u05de\u05e1\u05ea\u05d9\u05e8 \u05d0\u05ea \u05d4\u05d4\u05d1\u05e8\u05d2\u05d4 \u05d4\u05e4\u05e0\u05d9\u05de\u05d9\u05ea."],[137.0,"\u05d4\u05d4\u05d1\u05e8\u05d2\u05d4 \u05d4\u05e4\u05e0\u05d9\u05de\u05d9\u05ea \u05de\u05d5\u05e4\u05d9\u05e2\u05d4 \u05e8\u05e7 \u05d1\u05d7\u05dc\u05e7 \u05e9\u05dc \u05d4\u05e7\u05d3\u05d7 \u05e9\u05d1\u05d5 \u05d0\u05d9\u05df \u05d1\u05d5\u05e8\u05d2, \u05d5\u05e9\u05dd \u05d4\u05e7\u05d9\u05d5\u05d5\u05e7\u05d5\u05d5 \u05de\u05d2\u05d9\u05e2 \u05e9\u05d5\u05d1 \u05e2\u05d3 \u05d4\u05e7\u05d5 \u05d4\u05e2\u05d1\u05d4."],[146.0,"\u05de\u05d9\u05e9\u05dc\u05d0 \u05de\u05db\u05d9\u05e8 \u05d0\u05ea \u05d6\u05d4 \u05e2\u05dc\u05d5\u05dc \u05dc\u05d7\u05e9\u05d5\u05d1 \u05e9\u05d4\u05e7\u05d3\u05d7 \u05dc\u05d0 \u05de\u05d5\u05d1\u05e8\u05d2 \u05dc\u05db\u05dc \u05e2\u05d5\u05de\u05e7\u05d5."],[151.0,"\u05d1\u05d9\u05d9\u05e6\u05d5\u05d2 \u05d4\u05de\u05d5\u05e1\u05db\u05dd, \u05d2\u05dc\u05d2\u05dc \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd \u05de\u05e6\u05d5\u05d9\u05e8 \u05d1\u05dc\u05d9 \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd: \u05de\u05e2\u05d2\u05dc \u05d4\u05e8\u05d0\u05e9 \u05d1\u05e7\u05d5 \u05e2\u05d1\u05d4, \u05d5\u05de\u05e2\u05d2\u05dc \u05d4\u05d7\u05dc\u05d5\u05e7\u05d4 \u05d1\u05e7\u05d5 \u05de\u05e8\u05db\u05d6 \u05d3\u05e7."],[162.0,"\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05de\u05e6\u05d9\u05d9\u05e8\u05d9\u05dd \u05e9\u05df \u05d0\u05d7\u05ea \u05d0\u05d5 \u05e9\u05ea\u05d9\u05d9\u05dd, \u05db\u05e9\u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05e8\u05d0\u05d5\u05ea \u05d0\u05ea \u05de\u05d9\u05e7\u05d5\u05dd \u05d4\u05e9\u05d5\u05df \u05d1\u05d9\u05d7\u05e1 \u05dc\u05d0\u05dc\u05de\u05e0\u05d8 \u05d0\u05d7\u05e8, \u05db\u05de\u05d5 \u05e9\u05d2\u05dd \u05d0\u05d5 \u05e7\u05d3\u05d7."],[172.0,"\u05d5\u05d1\u05e9\u05e8\u05d8\u05d5\u05d8\u05d9\u05dd \u05e9\u05de\u05d5\u05e4\u05e7\u05d9\u05dd \u05de\u05de\u05e2\u05e8\u05db\u05d5\u05ea CAD, \u05d4\u05e8\u05d1\u05d4 \u05e4\u05e2\u05de\u05d9\u05dd \u05db\u05dc \u05d4\u05e9\u05d9\u05e0\u05d9\u05d9\u05dd \u05de\u05e6\u05d5\u05d9\u05e8\u05d5\u05ea."],[178.0,"\u05d0\u05d1\u05dc \u05d2\u05dd \u05d0\u05d6, \u05e6\u05d5\u05e8\u05ea \u05d4\u05e2\u05d5\u05df \u05d1\u05e6\u05d9\u05d5\u05e8 \u05d4\u05d9\u05d0 \u05e8\u05e7 \u05ea\u05de\u05d5\u05e0\u05d4. \u05dc\u05d0 \u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05de\u05de\u05e0\u05d4, \u05d5\u05d4\u05d9\u05d0 \u05dc\u05d0 \u05de\u05d2\u05d3\u05d9\u05e8\u05d4 \u05d0\u05ea \u05d4\u05e9\u05df."],[186.0,"\u05de\u05d5\u05d3\u05d5\u05dc, \u05de\u05e1\u05e4\u05e8 \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd, \u05d6\u05d5\u05d5\u05d9\u05ea \u05dc\u05d7\u05e5, \u05d3\u05e8\u05d2\u05ea \u05d3\u05d9\u05d5\u05e7 \u05d5\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05d3\u05d9\u05e7\u05d4."],[197.0,"\u05d0\u05dd \u05d4\u05d8\u05d1\u05dc\u05d4 \u05d7\u05e1\u05e8\u05d4, \u05d0\u05d9 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d9\u05d9\u05e6\u05e8 \u05d0\u05ea \u05d4\u05d2\u05dc\u05d2\u05dc \u05de\u05d4\u05e9\u05e8\u05d8\u05d5\u05d8, \u05d2\u05dd \u05d0\u05dd \u05d4\u05e6\u05d9\u05d5\u05e8 \u05e0\u05e8\u05d0\u05d4 \u05e9\u05dc\u05dd."],[204.0,"\u05e9\u05d9\u05e0\u05d9\u05d9\u05dd, \u05d5\u05d4\u05e0\u05ea\u05d5\u05e0\u05d9\u05dd \u05e9\u05dc\u05d4\u05dd \u05de\u05d5\u05e4\u05d9\u05e2\u05d9\u05dd \u05d1\u05d8\u05d1\u05dc\u05d4 \u05d0\u05d5 \u05d1\u05db\u05d9\u05ea\u05d5\u05d1 \u05dc\u05e4\u05d9 \u05d4\u05ea\u05e7\u05df, \u05dc\u05de\u05e9\u05dc 4156 ASO"],[220.0,"\u05de\u05e1\u05d1\u05d9\u05dd \u05de\u05ea\u05d2\u05dc\u05d2\u05dc\u05d9\u05dd \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d4\u05e8\u05db\u05d1\u05d4 \u05de\u05e6\u05d5\u05d9\u05e8\u05d9\u05dd \u05dc\u05e2\u05d9\u05ea\u05d9\u05dd \u05db\u05de\u05dc\u05d1\u05df \u05e2\u05dd \u05e6\u05dc\u05d1 \u05d1\u05ea\u05d5\u05db\u05d5, \u05dc\u05e4\u05d9 8826 ASO"],[231.0,"\u05d4\u05de\u05e1\u05d1 \u05e2\u05e6\u05de\u05d5 \u05de\u05d5\u05d2\u05d3\u05e8 \u05d1\u05de\u05e1\u05e4\u05e8 \u05d4\u05e7\u05d8\u05dc\u05d5\u05d2\u05d9 \u05e9\u05dc\u05d5 \u05d1\u05e8\u05e9\u05d9\u05de\u05ea \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd, \u05d5\u05dc\u05d0 \u05d1\u05e6\u05d9\u05d5\u05e8."],[238.0,"\u05d2\u05dd \u05e7\u05e4\u05d9\u05e5 \u05de\u05e6\u05d5\u05d9\u05e8 \u05de\u05e4\u05d5\u05e9\u05d8: \u05db\u05de\u05d4 \u05dc\u05d9\u05e4\u05d5\u05e4\u05d9\u05dd \u05d1\u05e7\u05e6\u05d5\u05d5\u05ea, \u05d5\u05d4\u05e9\u05d0\u05e8 \u2026."],[245.0,"\u05d4\u05e7\u05e4\u05d9\u05e5 \u05de\u05d5\u05d2\u05d3\u05e8 \u05d1\u05d8\u05d1\u05dc\u05d4: \u05e7\u05d5\u05d8\u05e8 \u05ea\u05d9\u05dc, \u05e7\u05d5\u05d8\u05e8 \u05de\u05de\u05d5\u05e6\u05e2, \u05de\u05e1\u05e4\u05e8 \u05dc\u05d9\u05e4\u05d5\u05e4\u05d9\u05dd, \u05d0\u05d5\u05e8\u05da \u05d7\u05d5\u05e4\u05e9\u05d5\u05d9, \u05d5\u05dc\u05e2\u05d9\u05ea\u05d9\u05dd \u05db\u05d5\u05d7 \u05d1\u05d0\u05d5\u05e8\u05da \u05de\u05e1\u05d5\u05d9\u05dd."],[256.0,"\u05d1\u05e7\u05e4\u05d9\u05e5, \u05d4\u05db\u05d5\u05d7 \u05d1\u05d0\u05d5\u05e8\u05da \u05e0\u05ea\u05d5\u05df \u05d7\u05e9\u05d5\u05d5\u05d1 \u05dc\u05e2\u05d9\u05ea\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8 \u05de\u05db\u05dc \u05de\u05d9\u05d3\u05d4 \u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05ea."],[262.0,"\u05db\u05e9\u05d0\u05d5\u05ea\u05d5 \u05d0\u05dc\u05de\u05e0\u05d8 \u05d7\u05d5\u05d6\u05e8 \u05db\u05de\u05d4 \u05e4\u05e2\u05de\u05d9\u05dd, \u05de\u05e6\u05d9\u05d9\u05e8\u05d9\u05dd \u05d5\u05de\u05d2\u05d3\u05d9\u05e8\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05e4\u05e2\u05dd \u05d0\u05d7\u05ea."],[268.0,"\u05db\u05d9\u05ea\u05d5\u05d1 \u05db\u05de\u05d5 010 \u05d06 \u05d0\u05d5\u05de\u05e8 \u05e9\u05d9\u05e9 \u05e9\u05d9\u05e9\u05d4 \u05e7\u05d3\u05d7\u05d9\u05dd \u05d6\u05d4\u05d9\u05dd."],[274.0,"\u05d1\u05e9\u05d0\u05e8 \u05d4\u05de\u05d9\u05e7\u05d5\u05de\u05d9\u05dd \u05de\u05e6\u05d9\u05d9\u05e8\u05d9\u05dd \u05e8\u05e7 \u05e7\u05d5\u05d5\u05d9 \u05de\u05e8\u05db\u05d6, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d0\u05e4\u05d9\u05dc\u05d5 \u05dc\u05d0 \u05d0\u05ea \u05d4\u05e7\u05d3\u05d7\u05d9\u05dd \u05e2\u05e6\u05de\u05dd."],[281.0,"\u05d7\u05de\u05d9\u05e9\u05d4 \u05de\u05e8\u05db\u05d6\u05d9\u05dd \u05d5\u05d4\u05db\u05d9\u05ea\u05d5\u05d1 \u05d0\u05d5\u05de\u05e8 \u05e9\u05d9\u05e9\u05d4, \u05d9\u05e9 \u05e1\u05ea\u05d9\u05e8\u05d4, \u05d5\u05e9\u05d5\u05d0\u05dc\u05d9\u05dd."],[292.0,"\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05de\u05ea\u05d5\u05d5\u05e1\u05e3 \u05dc\u05db\u05d9\u05ea\u05d5\u05d1 05\u05dd, \u05d0\u05d5 SP 0\u05dd, \u05e9\u05e4\u05d9\u05e8\u05d5\u05e9\u05d5 \u05de\u05e8\u05d5\u05d5\u05d7\u05d9\u05dd \u05e9\u05d5\u05d5\u05d9\u05dd."],[301.0,"\u05e7\u05d3\u05d7. \u05d1\u05dc\u05e2\u05d3\u05d9\u05d5, \u05d4\u05d6\u05d5\u05d5\u05d9\u05ea \u05d1\u05d9\u05df \u05d4\u05e7\u05d3\u05d7\u05d9\u05dd \u05e6\u05e8\u05d9\u05db\u05d4 \u05dc\u05d4\u05d9\u05d5\u05ea \u05de\u05d5\u05d2\u05d3\u05e8\u05ea \u05d1\u05de\u05d9\u05d3\u05d4."],[311.0,"\u05d1\u05d7\u05dc\u05e7 \u05e1\u05d9\u05de\u05d8\u05e8\u05d9 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05e6\u05d9\u05d9\u05e8 \u05e8\u05e7 \u05d7\u05e6\u05d9, \u05d0\u05d5 \u05d0\u05e4\u05d9\u05dc\u05d5 \u05e8\u05d1\u05e2."],[316.0,"\u05dc\u05e4\u05d9 ISO \u05e9\u05e0\u05d9 \u05e7\u05d5\u05d5\u05d9\u05dd \u05e7\u05e6\u05e8\u05d9\u05dd \u05d5\u05de\u05e7\u05d1\u05d9\u05dc\u05d9\u05dd \u05d1\u05e7\u05e6\u05d5\u05ea \u05e7\u05d5 \u05d4\u05de\u05e8\u05db\u05d6 \u05de\u05e1\u05de\u05e0\u05d9\u05dd \u05e9\u05d4\u05d7\u05dc\u05e7 \u05e1\u05d9\u05de\u05d8\u05e8\u05d9 \u05e1\u05d1\u05d9\u05d1\u05d5."],[324.0,"\u05d7\u05dc\u05e7 \u05d0\u05e8\u05d5\u05da \u05e2\u05dd \u05d7\u05ea\u05da \u05e7\u05d1\u05d5\u05e2, \u05dc\u05db\u05de\u05d5 \u05e6\u05d9\u05e8 \u05d0\u05d5 \u05e4\u05e8\u05d5\u05e4\u05d9\u05dc, \u05de\u05e6\u05d5\u05d9\u05e8 \u05de\u05e7\u05d5\u05e6\u05e8 \u05d1\u05e2\u05d6\u05e8\u05ea \u05e7\u05d5\u05d5\u05d9 \u05e9\u05d1\u05d9\u05e8\u05d4."],[332.0,"\u05d4\u05de\u05d9\u05d3\u05d4 \u05e9\u05e8\u05e9\u05d5\u05de\u05d4 \u05e2\u05dc\u05d9\u05d5 \u05d4\u05d9\u05d0 \u05d4\u05d0\u05d5\u05e8\u05da \u05d4\u05d0\u05de\u05d9\u05ea\u05d9, \u05dc\u05d0 \u05d4\u05d0\u05d5\u05e8\u05da \u05d4\u05de\u05e6\u05d5\u05d9\u05e8."],[337.0,"\u05d6\u05d4 \u05e2\u05d5\u05d3 \u05de\u05e7\u05d5\u05dd \u05e9\u05d1\u05d5 \u05de\u05d9 \u05e9\u05de\u05d5\u05d3\u05d3 \u05de\u05d4\u05e6\u05d9\u05d5\u05e8 \u05d9\u05e7\u05d1\u05dc \u05de\u05e1\u05e4\u05e8 \u05e9\u05d2\u05d5\u05d9 \u05dc\u05d2\u05de\u05e8\u05d9."],[343.0,"\u05de\u05e9\u05d8\u05d7 \u05e9\u05d8\u05d5\u05d7 \u05e2\u05dc \u05e6\u05d9\u05e8 \u05e2\u05d2\u05d5\u05dc \u05de\u05e1\u05d5\u05de\u05df \u05d1\u05e9\u05e0\u05d9 \u05e7\u05d5\u05d5\u05d9\u05dd \u05d3\u05e7\u05d9\u05dd \u05de\u05e6\u05d8\u05dc\u05d1\u05d9\u05dd, \u05db\u05d3\u05d9 \u05dc\u05d4\u05d1\u05d3\u05d9\u05dc \u05d0\u05d5\u05ea\u05d5 \u05de\u05de\u05e9\u05d8\u05d7 \u05e2\u05d2\u05d5\u05dc."],[351.0,"Knurling \u05de\u05e6\u05d5\u05d9\u05e8 \u05e8\u05e7 \u05e2\u05dc \u05d7\u05dc\u05e7 \u05e7\u05d8\u05df \u05de\u05d4\u05e9\u05d8\u05d7, \u05d5\u05d4\u05e1\u05d5\u05d2 \u05d5\u05d4\u05e4\u05e1\u05d9\u05e2\u05d4 \u05de\u05d5\u05d2\u05d3\u05e8\u05d9\u05dd \u05d1\u05db\u05d9\u05ea\u05d5\u05d1."],[358.0,"\u05dc\u05e6\u05d9\u05e8, \u05de\u05e6\u05d5\u05d9\u05e8 \u05dc\u05e2\u05d9\u05ea\u05d9\u05dd \u05d1\u05e7\u05d5\u05d5\u05d9\u05dd \u05d9\u05e9\u05e8\u05d9\u05dd \u05d1\u05de\u05e7\u05d5\u05dd \u05d1\u05e2\u05e7\u05d5\u05de\u05d4 \u05d4\u05de\u05d3\u05d5\u05d9\u05e7\u05ea."],[368.0,"\u05e4\u05d9\u05e0\u05d5\u05ea \u05de\u05e2\u05d5\u05d2\u05dc\u05d5\u05ea \u05d9\u05d5\u05e6\u05e8\u05d5\u05ea \u05e7\u05d5\u05d5\u05d9 \u05de\u05e2\u05d1\u05e8, \u05e9\u05de\u05e6\u05d5\u05d9\u05e8\u05d9\u05dd \u05dc\u05e2\u05d9\u05ea\u05d9\u05dd \u05d1\u05e7\u05d5 \u05d3\u05e7 \u05d0\u05d5\u05dc\u05d0 \u05de\u05e6\u05d5\u05d9\u05e8\u05d9\u05dd \u05d1\u05db\u05dc\u05dc."],[376.0,"\u05d5\u05d1\u05ea\u05e7\u05e0\u05d9 ASME, \u05e7\u05d5\u05d5\u05d9\u05dd \u05e0\u05e1\u05ea\u05e8\u05d9\u05dd \u05de\u05e6\u05d5\u05d9\u05e8\u05d9\u05dd \u05e8\u05e7 \u05db\u05e9\u05d4\u05dd \u05e0\u05d7\u05d5\u05e6\u05d9\u05dd. \u05d4\u05d9\u05e2\u05d3\u05e8 \u05e7\u05d5 \u05e0\u05e1\u05ea\u05e8 \u05dc\u05d0 \u05de\u05d5\u05db\u05d9\u05d7 \u05e9\u05d0\u05d9\u05df \u05e9\u05dd \u05db\u05dc\u05d5\u05dd."],[386.0,"\u05e7\u05d5 \u05e9\u05dc \u05e7\u05d5\u05d5\u05e9\u05ea\u05d9 \u05e0\u05e7\u05d5\u05d3\u05d5\u05ea, phantom, \u05de\u05e8\u05d0\u05d4 \u05de\u05d9\u05e7\u05d5\u05dd \u05d7\u05dc\u05d5\u05e1\u05d9 \u05e9\u05dc \u05d7\u05dc\u05e7 \u05e0\u05e2, \u05d0\u05d5 \u05d7\u05dc\u05e7 \u05e1\u05de\u05d5\u05da \u05e9\u05d0\u05d9\u05e0\u05d5 \u05e9\u05d9\u05d9\u05da \u05dc\u05e9\u05e8\u05d8\u05d5\u05d8."],[395.0,"\u05d4\u05d5\u05d0 \u05e0\u05d5\u05ea\u05df \u05d4\u05e7\u05e9\u05e8 \u05d1\u05dc\u05d1\u05d3, \u05d5\u05d4\u05d5\u05d0 \u05dc\u05d0 \u05d7\u05dc\u05e7 \u05de\u05d4\u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05d4 \u05e9\u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05de\u05d2\u05d3\u05d9\u05e8."],[402.0,"\u05d1\u05db\u05dc \u05d4\u05de\u05d5\u05e1\u05db\u05de\u05d5\u05ea \u05d4\u05d0\u05dc\u05d4 \u05d9\u05e9 \u05e2\u05d9\u05e7\u05e8\u05d5\u05df \u05d0\u05d7\u05d3 \u05de\u05e9\u05d5\u05ea\u05e3."],[406.0,"\u05d4\u05e6\u05d9\u05d5\u05e8 \u05de\u05e8\u05d0\u05d4 \u05d0\u05d9\u05e4\u05d4 \u05d4\u05d0\u05dc\u05de\u05e0\u05d8 \u05e0\u05de\u05e6\u05d0 \u05d5\u05d0\u05d9\u05da \u05d4\u05d5\u05d0 \u05e0\u05e8\u05d0\u05d4 \u05d1\u05e2\u05e8\u05da. \u05d4\u05db\u05d9\u05ea\u05d5\u05d1, \u05d4\u05d8\u05d1\u05dc\u05d4 \u05d5\u05d4\u05d4\u05e2\u05e8\u05d4 \u05de\u05d2\u05d3\u05d9\u05e8\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05d1\u05d3\u05d9\u05d5\u05e7."],[416.0,"\u05dc\u05db\u05df \u05db\u05e9\u05d9\u05e9 \u05e4\u05e2\u05e8 \u05d1\u05d9\u05df \u05d4\u05e6\u05d9\u05d5\u05e8 \u05dc\u05db\u05d9\u05ea\u05d5\u05d1, \u05d4\u05db\u05d9\u05ea\u05d5\u05d1 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d2\u05d5\u05d1\u05e8, \u05d0\u05d1\u05dc \u05e4\u05e2\u05e8 \u05db\u05d6\u05d4 \u05d4\u05d5\u05d0 \u05ea\u05de\u05d9\u05d3 \u05e1\u05d9\u05d1\u05d4 \u05dc\u05e9\u05d0\u05d5\u05dc."],[425.0,"\u05d5\u05de\u05d9 \u05e9\u05dc\u05d0 \u05de\u05db\u05d9\u05e8 \u05de\u05d5\u05e1\u05db\u05de\u05d4 \u05d9\u05e8\u05d0\u05d4 \u05d1\u05d4 \u05d8\u05e2\u05d5\u05ea \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8, \u05d0\u05d5 \u05d2\u05e8\u05d5\u05e2 \u05de\u05d6\u05d4, \u05d9\u05e4\u05e8\u05e9 \u05d0\u05d5\u05ea\u05d4 \u05db\u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05d4 \u05d0\u05de\u05d9\u05ea\u05d9\u05ea."],[434.0,"\u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05de\u05e4\u05e9\u05d8 \u05d1\u05db\u05d5\u05d5\u05e0\u05d4: \u05d4\u05d1\u05e8\u05d2\u05d5\u05ea, \u05d2\u05dc\u05d2\u05dc\u05d9 \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd, \u05e7\u05e4\u05d9\u05e6\u05d9\u05dd, \u05d0\u05dc\u05de\u05e0\u05d8\u05d9\u05dd \u05d7\u05d5\u05d6\u05e8\u05d9\u05dd \u05d5\u05d7\u05dc\u05e7\u05d9\u05dd \u05d0\u05e8\u05d5\u05db\u05d9\u05dd."],[443.0,"\u05d1\u05d4\u05d1\u05e8\u05d2\u05d4 \u05d7\u05d9\u05e6\u05d5\u05e0\u05d9\u05ea \u05d4\u05e7\u05d5\u05d8\u05e8 \u05d4\u05d7\u05d9\u05e6\u05d5\u05e0\u05d9 \u05e2\u05d1\u05d4, \u05d5\u05d1\u05d4\u05d1\u05e8\u05d2\u05d4 \u05e4\u05e0\u05d9\u05de\u05d9\u05ea \u05e7\u05d5\u05d8\u05e8 \u05d4\u05e7\u05d3\u05d7 \u05e2\u05d1\u05d4."],[450.0,"\u05d2\u05dc\u05d2\u05dc\u05d9 \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd \u05d5\u05e7\u05e4\u05d9\u05e6\u05d9\u05dd \u05de\u05d5\u05d2\u05d3\u05e8\u05d9\u05dd \u05d1\u05d8\u05d1\u05dc\u05d4, \u05d5\u05d0\u05dc\u05de\u05e0\u05d8\u05d9\u05dd \u05d7\u05d5\u05d6\u05e8\u05d9\u05dd \u05de\u05d5\u05d2\u05d3\u05e8\u05d9\u05dd \u05d1\u05de\u05e1\u05e4\u05e8 \u05e9\u05d1\u05db\u05d9\u05ea\u05d5\u05d1."],[458.0,"\u05d5\u05d1\u05db\u05dc \u05de\u05e7\u05d5\u05dd \u05e9\u05d4\u05e6\u05d9\u05d5\u05e8 \u05de\u05e4\u05d5\u05e9\u05d8, \u05d4\u05de\u05d9\u05d3\u05e2 \u05e0\u05de\u05e6\u05d0 \u05d1\u05db\u05d9\u05ea\u05d5\u05d1, \u05d5\u05dc\u05d0 \u05d1\u05e6\u05d9\u05d5\u05e8."],[464.0,"\u05d4\u05de\u05d9\u05d3\u05d5\u05ea, \u05d5\u05e0\u05e8\u05d0\u05d4 \u05dc\u05de\u05d4 \u05de\u05d9\u05d3\u05d4 \u05d8\u05d5\u05d1\u05d4 \u05d4\u05d9\u05d0 \u05e7\u05d5\u05d3\u05dd \u05db\u05d5\u05dc \u05d4\u05d7\u05dc\u05d8\u05d4 \u05d4\u05e0\u05d3\u05e1\u05d9\u05ea."],[475.0,"\u05e0\u05ea\u05e8\u05d0\u05d4 \u05d1\u05e4\u05e8\u05e7 \u05d0\u05e8\u05d1\u05e2."]]};
window.MH_TR["ch04"]={"t":"\u05e4\u05d9\u05dc\u05d5\u05e1\u05d5\u05e4\u05d9\u05d9\u05ea \u05d4\u05de\u05d9\u05d3\u05d5\u05ea","l":[[1.0,"\u05de\u05d9\u05d3\u05d4 \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d4\u05d9\u05d0 \u05dc\u05d0 \u05e8\u05e7 \u05de\u05e1\u05e4\u05e8. \u05d4\u05d9\u05d0 \u05d4\u05d7\u05dc\u05d8\u05d4 \u05d4\u05e0\u05d3\u05e1\u05d9\u05ea."],[6.0,"\u05db\u05dc \u05de\u05d9\u05d3\u05d4 \u05d0\u05d5\u05de\u05e8\u05ea \u05de\u05d4 \u05d7\u05e9\u05d5\u05d1: \u05d0\u05d9\u05d6\u05d4 \u05de\u05e8\u05d7\u05e7, \u05de\u05d0\u05d9\u05d6\u05d5 \u05e0\u05e7\u05d5\u05d3\u05d4, \u05d5\u05d1\u05d0\u05d9\u05d6\u05d5 \u05e1\u05d1\u05d5\u05dc\u05ea."],[13.0,"\u05d0\u05d5\u05ea\u05d5 \u05d7\u05dc\u05e7 \u05d1\u05d3\u05d9\u05d5\u05e7 \u05d9\u05db\u05d5\u05dc \u05dc\u05e7\u05d1\u05dc \u05e9\u05ea\u05d9 \u05de\u05e2\u05e8\u05db\u05d5\u05ea \u05de\u05d9\u05d3\u05d5\u05ea \u05e9\u05d5\u05e0\u05d5\u05ea, \u05d5\u05dc\u05e6\u05d0\u05ea \u05e9\u05e0\u05d9 \u05d7\u05dc\u05e7\u05d9\u05dd \u05e9\u05de\u05ea\u05e4\u05e7\u05d3\u05d9\u05dd \u05d0\u05d7\u05e8\u05ea."],[21.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05dc\u05de\u05d3 \u05dc\u05e7\u05e8\u05d5\u05d0 \u05d0\u05ea \u05d4\u05db\u05d5\u05d5\u05e0\u05d4 \u05e9\u05de\u05d0\u05d7\u05d5\u05e8\u05d9 \u05d4\u05de\u05d9\u05d3\u05d5\u05ea, \u05d5\u05dc\u05d0 \u05e8\u05e7 \u05d0\u05ea \u05d4\u05de\u05e1\u05e4\u05e8\u05d9\u05dd."],[27.0,"\u05de\u05d9\u05d3\u05d4 \u05e4\u05d5\u05e0\u05e7\u05e6\u05d9\u05d5\u05e0\u05dc\u05d9\u05ea \u05de\u05d2\u05d3\u05d9\u05e8\u05d4 \u05d9\u05e9\u05d9\u05e8\u05d5\u05ea \u05d0\u05ea \u05de\u05d4 \u05e9\u05d7\u05e9\u05d5\u05d1 \u05dc\u05ea\u05e4\u05e7\u05d5\u05d3 \u05d4\u05d7\u05dc\u05e7."],[33.0,"\u05d0\u05dd \u05e9\u05e0\u05d9 \u05e7\u05d3\u05d7\u05d9\u05dd \u05e6\u05e8\u05d9\u05db\u05d9\u05dd \u05dc\u05d4\u05ea\u05d0\u05d9\u05dd \u05dc\u05e9\u05e0\u05d9 \u05e4\u05d9\u05e0\u05d9\u05dd \u05d1\u05d7\u05dc\u05e7 \u05d0\u05d7\u05e8, \u05d4\u05de\u05e8\u05d7\u05e7 \u05d4\u05d7\u05e9\u05d5\u05d1 \u05d4\u05d5\u05d0 \u05d4\u05de\u05e8\u05d7\u05e7 \u05d1\u05d9\u05e0\u05d9\u05d4\u05dd."],[40.0,"\u05dc\u05db\u05df \u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05d9\u05e9\u05d9\u05e8\u05d5\u05ea, \u05de\u05e7\u05d3\u05d7 \u05dc\u05e7\u05d3\u05d7, \u05d5\u05dc\u05d0 \u05db\u05dc \u05e7\u05d3\u05d7 \u05d1\u05e0\u05e4\u05e8\u05d3 \u05de\u05d4\u05e7\u05e6\u05d4."],[47.0,"\u05de\u05d9\u05d3\u05d4 \u05e9\u05e0\u05e7\u05d1\u05e2\u05ea \u05dc\u05e4\u05d9 \u05e0\u05d5\u05d7\u05d5\u05ea \u05d4\u05d9\u05d9\u05e6\u05d5\u05e8 \u05e2\u05dc\u05d5\u05dc\u05d4 \u05dc\u05e4\u05d2\u05d5\u05e2 \u05d1\u05e4\u05d5\u05e0\u05e7\u05e6\u05d9\u05d4, \u05d2\u05dd \u05db\u05e9\u05db\u05dc \u05d4\u05de\u05e1\u05e4\u05e8\u05d9\u05dd \u05d1\u05e1\u05d1\u05d5\u05dc\u05ea."],[55.0,"\u05d4\u05ea\u05e7\u05df \u05de\u05db\u05d5\u05d5\u05df \u05dc\u05de\u05d9\u05d3\u05d5\u05ea \u05e4\u05d5\u05e0\u05e7\u05e6\u05d9\u05d5\u05e0\u05dc\u05d9\u05d5\u05ea. \u05d0\u05ea \u05e9\u05d9\u05d8\u05ea \u05d4\u05d9\u05d9\u05e6\u05d5\u05e8 \u05d1\u05d5\u05d7\u05e8 \u05d4\u05d9\u05e6\u05e8\u05df \u05d0\u05d7\u05e8 \u05db\u05df."],[62.0,"\u05d9\u05e9 \u05e9\u05ea\u05d9 \u05d3\u05e8\u05db\u05d9\u05dd \u05e2\u05d9\u05e7\u05e8\u05d9\u05d5\u05ea \u05dc\u05e1\u05d3\u05e8 \u05de\u05d9\u05d3\u05d5\u05ea: \u05d1\u05e9\u05e8\u05e9\u05e8\u05ea, \u05d0\u05d5 \u05de\u05d1\u05e1\u05d9\u05e1 \u05d0\u05d7\u05d3."],[68.0,"\u05d1\u05e9\u05e8\u05e9\u05e8\u05ea, \u05db\u05dc \u05de\u05d9\u05d3\u05d4 \u05de\u05ea\u05d7\u05d9\u05dc\u05d4 \u05d0\u05d9\u05e4\u05d4 \u05e9\u05d4\u05e7\u05d5\u05d3\u05de\u05ea \u05e0\u05d2\u05de\u05e8\u05d4."],[73.0,"\u05e2\u05e9\u05d9\u05e8\u05d9\u05ea, \u05d4\u05de\u05d9\u05e7\u05d5\u05dd \u05e9\u05dc \u05d4\u05d0\u05dc\u05de\u05e0\u05d8 \u05d4\u05d0\u05d7\u05e8\u05d5\u05df \u05d9\u05db\u05d5\u05dc \u05dc\u05e1\u05d8\u05d5\u05ea \u05e2\u05d3 \u05d0\u05e8\u05d1\u05e2 \u05e2\u05e9\u05d9\u05e8\u05d9\u05d5\u05ea."],[83.0,"\u05d1\u05de\u05d9\u05d3\u05d5\u05ea \u05de\u05d1\u05e1\u05d9\u05e1, \u05db\u05dc \u05d0\u05dc\u05de\u05e0\u05d8 \u05e0\u05de\u05d3\u05d3 \u05de\u05d0\u05d5\u05ea\u05d5 \u05e7\u05e6\u05d4, \u05d5\u05d4\u05e1\u05d1\u05d5\u05dc\u05ea \u05dc\u05d0 \u05de\u05e6\u05d8\u05d1\u05e8\u05ea."],[90.0,"\u05d0\u05d1\u05dc \u05d9\u05e9 \u05de\u05d7\u05d9\u05e8: \u05d4\u05de\u05e8\u05d7\u05e7 \u05d1\u05d9\u05df \u05e9\u05e0\u05d9 \u05d0\u05dc\u05de\u05e0\u05d8\u05d9\u05dd \u05e1\u05de\u05d5\u05db\u05d9\u05dd \u05db\u05d1\u05e8 \u05dc\u05d0 \u05e0\u05e9\u05dc\u05d8 \u05d9\u05e9\u05d9\u05e8\u05d5\u05ea, \u05d5\u05d4\u05d5\u05d0 \u05d9\u05db\u05d5\u05dc \u05dc\u05e1\u05d8\u05d5\u05ea \u05e2\u05d3 \u05e9\u05ea\u05d9 \u05e2\u05e9\u05d9\u05e8\u05d9\u05d5\u05ea."],[99.0,"\u05d0\u05d9\u05df \u05d3\u05e8\u05da \u05d0\u05d7\u05ea \u05e0\u05db\u05d5\u05e0\u05d4. \u05d4\u05d1\u05d7\u05d9\u05e8\u05d4 \u05d0\u05d5\u05de\u05e8\u05ea \u05dc\u05e7\u05d5\u05e8\u05d0 \u05d0\u05d9\u05d6\u05d4 \u05de\u05e8\u05d7\u05e7 \u05d4\u05de\u05ea\u05db\u05e0\u05df \u05e8\u05e6\u05d4 \u05dc\u05e9\u05de\u05d5\u05e8 \u05d4\u05d3\u05d5\u05e7."],[107.0,"\u05e7\u05d5\u05d0\u05d5\u05e8\u05d3\u05d9\u05e0\u05d8\u05d5\u05ea: \u05e0\u05e7\u05d5\u05d3\u05ea \u05d0\u05e4\u05e1 \u05d0\u05d7\u05ea, \u05d5\u05db\u05dc \u05d0\u05dc\u05de\u05e0\u05d8 \u05de\u05e7\u05d1\u05dc \u05de\u05e1\u05e4\u05e8 \u05d0\u05d7\u05d3 \u05d1\u05db\u05dc \u05e6\u05d9\u05e8."],[118.0,"\u05de\u05d4\u05d1\u05e1\u05d9\u05e1, \u05d0\u05d1\u05dc \u05d4\u05de\u05e8\u05d7\u05e7 \u05d1\u05d9\u05df \u05e9\u05e0\u05d9 \u05d0\u05dc\u05de\u05e0\u05d8\u05d9\u05dd \u05dc\u05d0 \u05e0\u05e9\u05dc\u05d8 \u05d9\u05e9\u05d9\u05e8\u05d5\u05ea."],[128.0,"\u05d1\u05d7\u05dc\u05e7 \u05e2\u05dd \u05d4\u05e8\u05d1\u05d4 \u05e7\u05d3\u05d7\u05d9\u05dd, \u05d4\u05de\u05d9\u05e7\u05d5\u05de\u05d9\u05dd \u05de\u05d5\u05e4\u05d9\u05e2\u05d9\u05dd \u05d1\u05d8\u05d1\u05dc\u05ea \u05e7\u05d3\u05d7\u05d9\u05dd, \u05e2\u05dd \u05d0\u05d5\u05ea \u05d0\u05d5 \u05de\u05e1\u05e4\u05e8 \u05dc\u05db\u05dc \u05e7\u05d3\u05d7."],[136.0,"\u05d4\u05d8\u05d1\u05dc\u05d4 \u05d4\u05d9\u05d0 \u05d7\u05dc\u05e7 \u05de\u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05dc\u05db\u05dc \u05d3\u05d1\u05e8, \u05d5\u05d4\u05e1\u05d1\u05d5\u05dc\u05d5\u05ea \u05d7\u05dc\u05d5\u05ea \u05e2\u05dc\u05d9\u05d4 \u05db\u05de\u05d5 \u05e2\u05dc \u05db\u05dc \u05de\u05d9\u05d3\u05d4 \u05d0\u05d7\u05e8\u05ea."],[144.0,"\u05de\u05d9\u05d3\u05ea \u05d9\u05ea\u05e8 \u05d4\u05d9\u05d0 \u05de\u05d9\u05d3\u05d4 \u05e9\u05d0\u05e4\u05e9\u05e8 \u05dc\u05d7\u05e9\u05d5\u05d1 \u05de\u05de\u05d9\u05d3\u05d5\u05ea \u05d0\u05d7\u05e8\u05d5\u05ea \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8."],[149.0,"\u05e9\u05e8\u05e9\u05e8\u05ea \u05e1\u05d2\u05d5\u05e8\u05d4 \u05d4\u05d9\u05d0 \u05d4\u05d3\u05d5\u05d2\u05de\u05d4 \u05d4\u05e7\u05dc\u05d0\u05e1\u05d9\u05ea: \u05e9\u05dc\u05d5\u05e9 \u05de\u05d9\u05d3\u05d5\u05ea \u05d7\u05dc\u05e7\u05d9\u05d5\u05ea, \u05d5\u05e2\u05d5\u05d3 \u05de\u05d9\u05d3\u05d4 \u05db\u05d5\u05dc\u05dc\u05ea \u05e9\u05de\u05db\u05e1\u05d4 \u05d0\u05ea \u05e9\u05dc\u05d5\u05e9\u05ea\u05df."],[157.0,"\u05d7\u05dc\u05e7 \u05d9\u05db\u05d5\u05dc \u05dc\u05e2\u05de\u05d5\u05d3 \u05d1\u05e9\u05dc\u05d5\u05e9 \u05de\u05d4\u05df \u05d5\u05dc\u05d7\u05e8\u05d5\u05d2 \u05d1\u05e8\u05d1\u05d9\u05e2\u05d9\u05ea, \u05d5\u05d0\u05d6 \u05dc\u05d0 \u05d1\u05e8\u05d5\u05e8 \u05d0\u05d9\u05d6\u05d5 \u05de\u05d9\u05d3\u05d4 \u05e7\u05d5\u05d1\u05e2\u05ea."],[164.0,"\u05dc\u05db\u05df \u05e9\u05e8\u05e9\u05d5\u05e8\u05ea \u05e0\u05db\u05d5\u05e0\u05d4 \u05de\u05e9\u05d0\u05d9\u05e8\u05d4 \u05de\u05e7\u05d8\u05e2 \u05d0\u05d7\u05d3 \u05d1\u05dc\u05d9 \u05de\u05d9\u05d3\u05d4, \u05d0\u05d5 \u05de\u05e1\u05de\u05e0\u05ea \u05d0\u05ea \u05d0\u05d7\u05ea \u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05db\u05de\u05d9\u05d3\u05ea \u05d9\u05d9\u05d7\u05d5\u05e1."],[172.0,"\u05d5\u05d4\u05de\u05e7\u05d8\u05e2 \u05e9\u05e0\u05e9\u05d0\u05e8 \u05d1\u05dc\u05d9 \u05de\u05d9\u05d3\u05d4 \u05d4\u05d5\u05d0 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d4\u05e4\u05d7\u05d5\u05ea \u05d7\u05e9\u05d5\u05d1. \u05d2\u05dd \u05d6\u05d5 \u05d4\u05e6\u05d4\u05e8\u05d4 \u05e9\u05dc \u05d4\u05de\u05ea\u05db\u05e0\u05df."],[180.0,"\u05de\u05d9\u05d3\u05ea \u05d9\u05d9\u05d7\u05d5\u05e1 \u05de\u05d5\u05e4\u05d9\u05e2\u05d4 \u05d1\u05e1\u05d5\u05d2\u05e8\u05d9\u05d9\u05dd, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05e2\u05dd \u05d4\u05db\u05d9\u05ea\u05d5\u05d1 \u05e7\u05dd\u05d7."],[186.0,"\u05d4\u05d9\u05d0 \u05e0\u05d5\u05ea\u05e0\u05ea \u05de\u05d9\u05d3\u05e2 \u05d1\u05dc\u05d1\u05d3: \u05d0\u05d9\u05df \u05dc\u05d4 \u05e1\u05d1\u05d5\u05dc\u05ea, \u05d5\u05d4\u05d9\u05d0 \u05dc\u05d0 \u05e0\u05d1\u05d3\u05e7\u05ea \u05dc\u05e7\u05d1\u05dc\u05ea \u05d4\u05d7\u05dc\u05e7."],[192.0,"\u05d4\u05d9\u05d0 \u05e9\u05dd \u05db\u05d3\u05d9 \u05dc\u05d7\u05e1\u05d5\u05da \u05dc\u05e7\u05d5\u05e8\u05d0 \u05d7\u05d9\u05e9\u05d5\u05d1, \u05dc\u05de\u05e9\u05dc \u05d0\u05d5\u05e8\u05da \u05db\u05d5\u05dc\u05dc."],[196.0,"\u05d8\u05e2\u05d5\u05ea \u05e0\u05e4\u05d5\u05e6\u05d4 \u05d4\u05d9\u05d0 \u05dc\u05d1\u05d3\u05d5\u05e7 \u05de\u05d9\u05d3\u05ea \u05d9\u05d9\u05d7\u05d5\u05e1 \u05d5\u05dc\u05e4\u05e1\u05d5\u05dc \u05d7\u05dc\u05e7 \u05d1\u05d2\u05dc\u05dc\u05d4. \u05d4\u05d7\u05dc\u05e7 \u05e0\u05d1\u05d7\u05df \u05dc\u05e4\u05d9 \u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05e9\u05de\u05d2\u05d3\u05d9\u05e8\u05d5\u05ea \u05d0\u05d5\u05ea\u05d5."],[205.0,"\u05de\u05d9\u05d3\u05d4 \u05d1\u05e1\u05d9\u05e1\u05d9\u05ea \u05de\u05d5\u05e7\u05e4\u05ea \u05d1\u05de\u05e1\u05d2\u05e8\u05ea."],[208.0,"\u05d4\u05d9\u05d0 \u05de\u05d9\u05d3\u05d4 \u05de\u05d3\u05d5\u05d9\u05e7\u05ea \u05ea\u05d0\u05d5\u05e8\u05d8\u05d9\u05ea: \u05d0\u05d9\u05df \u05dc\u05d4 \u05e1\u05d1\u05d5\u05dc\u05ea \u05de\u05e9\u05dc\u05d4, \u05d5\u05dc\u05d0 \u05d7\u05dc\u05d4 \u05e2\u05dc\u05d9\u05d4 \u05d4\u05e1\u05d1\u05d5\u05dc\u05ea \u05d4\u05db\u05dc\u05dc\u05d9\u05ea."],[215.0,"\u05d4\u05e1\u05d1\u05d5\u05dc\u05ea \u05e9\u05dc \u05d4\u05d0\u05dc\u05de\u05e0\u05d8 \u05de\u05d2\u05d9\u05e2\u05d4 \u05de\u05de\u05e1\u05d2\u05e8\u05ea \u05d4\u05e1\u05d1\u05d5\u05dc\u05ea \u05d4\u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05ea \u05e9\u05dc\u05d5, \u05dc\u05de\u05e9\u05dc \u05e1\u05d1\u05d5\u05dc\u05ea \u05de\u05d9\u05e7\u05d5\u05dd."],[222.0,"\u05de\u05d9 \u05e9\u05de\u05d7\u05d9\u05dc \u05e2\u05dc \u05de\u05d9\u05d3\u05d4 \u05d1\u05e1\u05d9\u05e1\u05d9\u05ea \u05d0\u05ea \u05d4\u05e1\u05d1\u05d5\u05dc\u05ea \u05d4\u05db\u05dc\u05dc\u05d9\u05ea \u05de\u05d0\u05d6\u05d5\u05e8 \u05d4\u05db\u05d5\u05ea\u05e8\u05ea, \u05d1\u05d5\u05d3\u05e7 \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05dc\u05e4\u05d9 \u05d3\u05e8\u05d9\u05e9\u05d4 \u05e9\u05dc\u05d0 \u05e7\u05d9\u05d9\u05de\u05ea."],[230.0,"\u05d5\u05de\u05d9\u05d3\u05d4 \u05d1\u05e1\u05d9\u05e1\u05d9\u05ea \u05d1\u05dc\u05d9 \u05e1\u05d1\u05d5\u05dc\u05ea \u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05ea \u05e9\u05de\u05ea\u05d9\u05d9\u05d7\u05e1\u05ea \u05d0\u05dc\u05d9\u05d4 \u05d4\u05d9\u05d0 \u05e9\u05d2\u05d9\u05d0\u05d4 \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8, \u05db\u05d9 \u05d0\u05d6 \u05dc\u05d0\u05dc\u05de\u05e0\u05d8 \u05d0\u05d9\u05df \u05e1\u05d1\u05d5\u05dc\u05ea \u05d1\u05db\u05dc\u05dc."],[240.0,"\u05d1\u05de\u05e7\u05d5\u05dd \u05de\u05d9\u05d3\u05d4 \u05d5\u05e1\u05d1\u05d5\u05dc\u05ea, \u05d0\u05e4\u05e9\u05e8 \u05dc\u05db\u05ea\u05d5\u05d1 \u05d0\u05ea \u05e9\u05e0\u05d9 \u05d4\u05d2\u05d1\u05d5\u05dc\u05d5\u05ea \u05d9\u05e9\u05d9\u05e8\u05d5\u05ea, \u05dc\u05de\u05e9\u05dc \u05e2\u05e9\u05e8\u05d9\u05dd \u05d5\u05e2\u05e9\u05e8\u05d9\u05dd \u05e0\u05e7\u05d5\u05d3\u05d4 \u05d0\u05e4\u05e1 \u05d7\u05de\u05e9."],[249.0,"\u05d6\u05d4 \u05e0\u05d5\u05d7 \u05dc\u05d9\u05d9\u05e6\u05d5\u05e8 \u05d5\u05dc\u05d1\u05d3\u05d9\u05e7\u05d4, \u05db\u05d9 \u05d0\u05d9\u05df \u05e6\u05d5\u05e8\u05da \u05dc\u05d7\u05e9\u05d1."],[253.0,"\u05d0)\u05d5\u05d0, \u05dc\u05de\u05e9\u05dc \u05e8\u05d3\u05d9\u05d5\u05e1 \u05e4\u05d9\u05e0\u05d4 \u05de\u05e7\u05e1\u05d9\u05de\u05dc\u05d9, \u05d0\u05d5 \u05e2\u05d5\u05de\u05e7 \u05d4\u05d1\u05e8\u05d2\u05d4 \u05de\u05d9\u05e0\u05d9\u05de\u05dc\u05d9."],[264.0,"\u05d1\u05d2\u05d1\u05d5\u05dc \u05d0\u05d7\u05d3, \u05d4\u05e6\u05d3 \u05d4\u05e9\u05e0\u05d9 \u05e4\u05ea\u05d5\u05d7, \u05d5\u05d4\u05d5\u05d0 \u05e0\u05e7\u05d1\u05e2 \u05e2\u05dc \u05d9\u05d3\u05d9 \u05d4\u05e4\u05d5\u05e0\u05e7\u05e6\u05d9\u05d4 \u05d0\u05d5 \u05e2\u05dc \u05d9\u05d3\u05d9 \u05de\u05d9\u05d3\u05d5\u05ea \u05d0\u05d7\u05e8\u05d5\u05ea."],[272.0,"\u05d1\u05ea\u05e7\u05df ASME \u05d9\u05e9 \u05e1\u05de\u05dc \u05e9\u05e0\u05e7\u05e8\u05d0 \u05e1\u05de\u05dc \u05de\u05e7\u05d5\u05e8 \u05d4\u05de\u05d9\u05d3\u05d4: \u05e2\u05d9\u05d2\u05d5\u05dc \u05e7\u05d8\u05df \u05d1\u05e7\u05e6\u05d4 \u05e7\u05d5 \u05d4\u05de\u05d9\u05d3\u05d4, \u05d1\u05de\u05e7\u05d5\u05dd \u05d7\u05e5."],[281.0,"\u05d4\u05d5\u05d0 \u05d0\u05d5\u05de\u05e8 \u05de\u05d0\u05d9\u05d6\u05d4 \u05d0\u05dc\u05de\u05e0\u05d8 \u05de\u05ea\u05d7\u05d9\u05dc\u05d9\u05dd \u05dc\u05de\u05d3\u05d5\u05d3, \u05d5\u05d6\u05d4 \u05de\u05e9\u05e0\u05d4 \u05d0\u05ea \u05d4\u05ea\u05d5\u05e6\u05d0\u05d4 \u05db\u05e9\u05d4\u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05dc\u05d0 \u05de\u05e7\u05d1\u05d9\u05dc\u05d9\u05dd \u05dc\u05d2\u05de\u05e8\u05d9."],[289.0,"\u05de\u05d3\u05d9\u05d3\u05d4 \u05de\u05d4\u05e6\u05d3 \u05d4\u05dc\u05d0 \u05e0\u05db\u05d5\u05df \u05d9\u05db\u05d5\u05dc\u05d4 \u05dc\u05e7\u05d1\u05dc \u05d7\u05dc\u05e7 \u05e9\u05d4\u05d9\u05d4 \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d9\u05e4\u05e1\u05dc, \u05d0\u05d5 \u05dc\u05e4\u05e1\u05d5\u05dc \u05d7\u05dc\u05e7 \u05ea\u05e7\u05d9\u05df."],[297.0,"\u05db\u05e9\u05de\u05e9\u05e0\u05d9\u05dd \u05de\u05d9\u05d3\u05d4 \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d1\u05dc\u05d9 \u05dc\u05e2\u05d3\u05db\u05df \u05d0\u05ea \u05d4\u05e6\u05d9\u05d5\u05e8, \u05de\u05e1\u05de\u05e0\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4 \u05d1\u05e7\u05d5 \u05de\u05ea\u05d7\u05ea \u05dc\u05de\u05e1\u05e4\u05e8."],[304.0,"\u05d4\u05e7\u05d5 \u05d0\u05d5\u05de\u05e8: \u05d4\u05e6\u05d9\u05d5\u05e8 \u05db\u05d0\u05df \u05dc\u05d0 \u05ea\u05d5\u05d0\u05dd \u05d0\u05ea \u05d4\u05de\u05e1\u05e4\u05e8, \u05d5\u05d4\u05de\u05e1\u05e4\u05e8 \u05d4\u05d5\u05d0 \u05e9\u05e7\u05d5\u05d1\u05e2."],[310.0,"\u05d5\u05d6\u05d5 \u05e2\u05d5\u05d3 \u05ea\u05d6\u05db\u05d5\u05e8\u05ea \u05dc\u05db\u05dc\u05dc \u05de\u05e4\u05e8\u05e7 \u05d0\u05e4\u05e1: \u05dc\u05d0 \u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05de\u05d4\u05e6\u05d9\u05d5\u05e8."],[316.0,"\u05de\u05e2\u05e8\u05db\u05ea \u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05d4\u05d9\u05d0 \u05d4\u05de\u05e7\u05d5\u05dd \u05e9\u05d1\u05d5 \u05d4\u05de\u05ea\u05db\u05e0\u05df \u05d0\u05d5\u05de\u05e8 \u05de\u05d4 \u05d7\u05e9\u05d5\u05d1 \u05dc\u05d5."],[321.0,"\u05de\u05d9\u05d3\u05d4 \u05d9\u05e9\u05d9\u05e8\u05d4 \u05d1\u05d9\u05df \u05e9\u05e0\u05d9 \u05d0\u05dc\u05de\u05e0\u05d8\u05d9\u05dd \u05d0\u05d5\u05de\u05e8\u05ea: \u05d4\u05de\u05e8\u05d7\u05e7 \u05d4\u05d6\u05d4 \u05e7\u05e8\u05d9\u05d8\u05d9."],[327.0,"\u05de\u05d9\u05d3\u05d5\u05ea \u05de\u05d1\u05e1\u05d9\u05e1 \u05d0\u05d7\u05d3 \u05d0\u05d5\u05de\u05e8\u05d5\u05ea: \u05d4\u05e7\u05e6\u05d4 \u05d4\u05d6\u05d4 \u05d4\u05d5\u05d0 \u05e0\u05e7\u05d5\u05d3\u05ea \u05d4\u05d9\u05d9\u05d7\u05d5\u05e1 \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7."],[332.0,"\u05d5\u05de\u05d9\u05d3\u05d4 \u05d1\u05e1\u05d1\u05d5\u05dc\u05ea \u05d4\u05d3\u05d5\u05e7\u05d4 \u05d1\u05de\u05d9\u05d5\u05d7\u05d3 \u05d0\u05d5\u05de\u05e8\u05ea: \u05db\u05d0\u05df \u05d4\u05e4\u05d5\u05e0\u05e7\u05e6\u05d9\u05d4 \u05e8\u05d2\u05d9\u05e9\u05d4, \u05d5\u05db\u05d0\u05df \u05d2\u05dd \u05d4\u05e2\u05dc\u05d5\u05ea."],[340.0,"\u05de\u05d9 \u05e9\u05e7\u05d5\u05e8\u05d0 \u05d0\u05ea \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05db\u05da \u05d9\u05db\u05d5\u05dc \u05dc\u05ea\u05db\u05e0\u05df \u05d9\u05d9\u05e6\u05d5\u05e8 \u05d5\u05d1\u05d3\u05d9\u05e7\u05d4 \u05e9\u05de\u05d2\u05d9\u05e0\u05d9\u05dd \u05e2\u05dc \u05de\u05d4 \u05e9\u05d7\u05e9\u05d5\u05d1 \u05d1\u05d0\u05de\u05ea."],[347.0,"\u05e0\u05d9\u05e7\u05d7 \u05d3\u05d5\u05d2\u05de\u05d4: \u05e4\u05dc\u05d8\u05d4 \u05e2\u05dd \u05e7\u05d3\u05d7 \u05de\u05e8\u05db\u05d6\u05d9 \u05dc\u05e6\u05d9\u05e8, \u05d5\u05e9\u05e0\u05d9 \u05e7\u05d3\u05d7\u05d9\u05dd \u05dc\u05d1\u05e8\u05d2\u05d9\u05dd."],[354.0,"\u05d4\u05de\u05ea\u05db\u05e0\u05df \u05de\u05d9\u05d3\u05d3 \u05d0\u05ea \u05e7\u05d3\u05d7\u05d9 \u05d4\u05d1\u05e8\u05d2\u05d9\u05dd \u05de\u05d4\u05e7\u05d3\u05d7 \u05d4\u05de\u05e8\u05db\u05d6\u05d9, \u05db\u05d9 \u05d4\u05dd \u05e6\u05e8\u05d9\u05db\u05d9\u05dd \u05dc\u05d4\u05ea\u05d0\u05d9\u05dd \u05dc\u05d0\u05d5\u05d2\u05df \u05e9\u05d9\u05d5\u05e9\u05d1 \u05e2\u05dc \u05d4\u05e6\u05d9\u05e8."],[362.0,"\u05d4\u05d9\u05e6\u05e8\u05df \u05d4\u05d9\u05d4 \u05de\u05e2\u05d3\u05d9\u05e3 \u05de\u05d9\u05d3\u05d5\u05ea \u05de\u05d4\u05e7\u05e6\u05d4, \u05db\u05d9 \u05de\u05e9\u05dd \u05e0\u05d5\u05d7 \u05dc\u05d5 \u05dc\u05e7\u05d1\u05e2 \u05d5\u05dc\u05de\u05d3\u05d5\u05d3."],[367.0,"\u05d4\u05e1\u05d1\u05d5\u05dc\u05d5\u05ea \u05de\u05e6\u05d8\u05d1\u05e8\u05d5\u05ea, \u05d5\u05d4\u05de\u05e8\u05d7\u05e7 \u05dc\u05e7\u05d3\u05d7 \u05d4\u05de\u05e8\u05db\u05d6\u05d9 \u05d9\u05db\u05d5\u05dc \u05dc\u05d7\u05e8\u05d5\u05d2 \u05d2\u05dd \u05db\u05e9\u05db\u05dc \u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05e9\u05dc\u05d5 \u05d1\u05e1\u05d1\u05d5\u05dc\u05ea."],[379.0,"\u05dc\u05e6\u05de\u05e6\u05dd \u05d0\u05ea \u05d4\u05e1\u05d1\u05d5\u05dc\u05d5\u05ea \u05e9\u05dc\u05d5, \u05db\u05da \u05e9\u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05d4\u05de\u05e7\u05d5\u05e8\u05d9\u05d5\u05ea \u05e9\u05dc \u05d4\u05de\u05ea\u05db\u05e0\u05df\u05d9\u05d9\u05e9\u05de\u05e8\u05d5."],[388.0,"\u05d6\u05d4 \u05d4\u05e2\u05d9\u05e7\u05e8\u05d5\u05df: \u05de\u05d5\u05ea\u05e8 \u05dc\u05d9\u05d9\u05e6\u05e8 \u05d1\u05db\u05dc \u05d3\u05e8\u05da, \u05d0\u05d1\u05dc \u05d4\u05d1\u05d3\u05d9\u05e7\u05d4 \u05e0\u05e2\u05e9\u05d5\u05d9\u05ea \u05dc\u05e4\u05d9\u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05e9\u05d1\u05e9\u05e8\u05d8\u05d5\u05d8."],[396.0,"\u05de\u05d9\u05d3\u05d4 \u05d4\u05d9\u05d0 \u05d4\u05d7\u05dc\u05d8\u05d4 \u05d4\u05e0\u05d3\u05e1\u05d9\u05ea, \u05dc\u05d0 \u05e8\u05e7 \u05de\u05e1\u05e4\u05e8."],[400.0,"\u05e9\u05e8\u05e9\u05e8\u05ea \u05de\u05e6\u05d1\u05d9\u05e8\u05d4 \u05e1\u05d1\u05d5\u05dc\u05d5\u05ea, \u05d1\u05e1\u05d9\u05e1 \u05e9\u05d5\u05de\u05e8 \u05e2\u05dc \u05db\u05dc \u05d0\u05dc\u05de\u05e0\u05d8 \u05de\u05d5\u05dc \u05d4\u05e7\u05e6\u05d4, \u05d5\u05de\u05d9\u05d3\u05d4 \u05d9\u05e9\u05d9\u05e8\u05d4 \u05e9\u05d5\u05de\u05e8\u05ea \u05e2\u05dc \u05d4\u05de\u05e8\u05d7\u05e7 \u05d1\u05d9\u05df \u05e9\u05e0\u05d9\u05d9\u05dd."],[410.0,"\u05de\u05d9\u05d3\u05ea \u05d9\u05ea\u05e8 \u05d9\u05d5\u05e6\u05e8\u05ea \u05e1\u05ea\u05d9\u05e8\u05d4, \u05de\u05d9\u05d3\u05ea \u05d9\u05d9\u05d7\u05d5\u05e1 \u05dc\u05d0 \u05e0\u05d1\u05d3\u05e7\u05ea, \u05d5\u05de\u05d9\u05d3\u05d4 \u05d1\u05e1\u05d9\u05e1\u05d9\u05ea \u05de\u05e7\u05d1\u05dc\u05ea \u05e1\u05d1\u05d5\u05dc\u05ea \u05e8\u05e7 \u05de\u05de\u05e1\u05d2\u05e8\u05ea \u05d4\u05e1\u05d1\u05d5\u05dc\u05ea."],[419.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05d3\u05d1\u05e8 \u05e2\u05dc \u05d4\u05e1\u05d1\u05d5\u05dc\u05d5\u05ea \u05e9\u05dc\u05d0 \u05e8\u05d5\u05d0\u05d9\u05dd: \u05e1\u05d1\u05d5\u05dc\u05d5\u05ea \u05db\u05dc\u05dc\u05d9\u05d5\u05ea, \u05d5\u05de\u05d4 \u05d4\u05df \u05e7\u05d5\u05d1\u05e2\u05d5\u05ea \u05db\u05e9\u05dc\u05d9\u05d3 \u05de\u05d9\u05d3\u05d4 \u05d0\u05d9\u05df \u05e1\u05d1\u05d5\u05dc\u05ea \u05d1\u05db\u05dc\u05dc."],[429.0,"\u05e0\u05ea\u05e8\u05d0\u05d4 \u05d1\u05e4\u05e8\u05e7 \u05d7\u05de\u05e9."]]};
window.MH_TR["ch05"]={"t":"\u05e1\u05d1\u05d5\u05dc\u05d5\u05ea \u05d1\u05e8\u05d9\u05e8\u05ea \u05de\u05d7\u05d3\u05dc","l":[[1.0,"\u05e8\u05d5\u05d1 \u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05db\u05ea\u05d5\u05d1\u05d5\u05ea \u05d1\u05dc\u05d9 \u05e1\u05d1\u05d5\u05dc\u05ea \u05dc\u05d9\u05d3\u05df."],[5.0,"\u05d6\u05d4 \u05dc\u05d0 \u05d0\u05d5\u05de\u05e8 \u05e9\u05d0\u05d9\u05df \u05dc\u05d4\u05df \u05e1\u05d1\u05d5\u05dc\u05ea. \u05d6\u05d4 \u05d0\u05d5\u05de\u05e8 \u05e9\u05d4\u05e1\u05d1\u05d5\u05dc\u05ea \u05db\u05ea\u05d5\u05d1\u05d4 \u05d1\u05de\u05e7\u05d5\u05dd \u05d0\u05d7\u05e8."],[11.0,"\u05e1\u05d1\u05d5\u05dc\u05d5\u05ea \u05d1\u05e8\u05d9\u05e8\u05ea \u05d4\u05de\u05d7\u05d3\u05dc \u05e7\u05d5\u05d1\u05e2\u05d5\u05ea \u05d0\u05ea \u05e8\u05d5\u05d1 \u05d4\u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05d4 \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7, \u05d5\u05e8\u05d5\u05d1 \u05d4\u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05dc\u05d0 \u05de\u05e1\u05ea\u05db\u05dc\u05d9\u05dd \u05e2\u05dc\u05d9\u05d4\u05df \u05d1\u05db\u05dc\u05dc."],[19.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05dc\u05de\u05d3 \u05d0\u05d9\u05e4\u05d4 \u05d4\u05df \u05de\u05d5\u05d2\u05d3\u05e8\u05d5\u05ea, \u05d0\u05d9\u05da \u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05d0\u05d5\u05ea\u05df, \u05d5\u05de\u05d4 \u05d4\u05df \u05dc\u05d0 \u05de\u05db\u05e1\u05d5\u05ea."],[26.0,"\u05d1\u05d4\u05e2\u05e8\u05d4 \u05db\u05dc\u05dc\u05d9\u05ea, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05e2\u05dd \u05d4\u05de\u05d9\u05dc\u05d9\u05dd \"\u05d0\u05dc\u05d0 \u05d0\u05dd \u05e6\u05d5\u05d9\u05df \u05d0\u05d7\u05e8\u05ea\"."],[36.0,"\u05d4\u05df \u05d7\u05dc\u05d5\u05ea \u05e2\u05dc \u05db\u05dc \u05de\u05d9\u05d3\u05d4 \u05e9\u05d0\u05d9\u05df \u05dc\u05d9\u05d3\u05d4 \u05e1\u05d1\u05d5\u05dc\u05ea \u05de\u05e9\u05dc\u05d4."],[40.0,"\u05de\u05d9\u05d3\u05d4 \u05e2\u05dd \u05e1\u05d1\u05d5\u05dc\u05ea \u05de\u05e9\u05dc\u05d4, \u05de\u05d9\u05d3\u05ea \u05d9\u05d9\u05d7\u05d5\u05e1 \u05d5\u05de\u05d9\u05d3\u05d4 \u05d1\u05e1\u05d9\u05e1\u05d9\u05ea \u05dc\u05d0 \u05de\u05e7\u05d1\u05dc\u05d5\u05ea \u05d0\u05ea \u05d4\u05e1\u05d1\u05d5\u05dc\u05ea \u05d4\u05db\u05dc\u05dc\u05d9\u05ea."],[47.0,"\u05d5\u05d0\u05dd \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d0\u05d9\u05df \u05e9\u05d5\u05dd \u05e1\u05d1\u05d5\u05dc\u05ea \u05db\u05dc\u05dc\u05d9\u05ea, \u05dc\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05dc\u05d9 \u05e1\u05d1\u05d5\u05dc\u05ea \u05d0\u05d9\u05df \u05d4\u05d2\u05d3\u05e8\u05d4, \u05d5\u05d6\u05d5 \u05e9\u05d0\u05dc\u05d4 \u05dc\u05de\u05ea\u05db\u05e0\u05df."],[55.0,"\u05d1\u05e9\u05e8\u05d8\u05d5\u05d8\u05d9\u05dd \u05dc\u05e4\u05d9 50\u05d5, \u05d4\u05e1\u05d1\u05d5\u05dc\u05ea \u05d4\u05db\u05dc\u05dc\u05d9\u05ea \u05de\u05d5\u05d2\u05d3\u05e8\u05ea \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05d4\u05e4\u05e0\u05d9\u05d4 \u05dc\u05ea\u05e7\u05df 2768 50!."],[64.0,"\u05d5\u05dc\u05d6\u05d5\u05d5\u05d9\u05d5\u05ea, \u05d1\u05d0\u05e8\u05d1\u05e2 \u05d3\u05e8\u05d2\u05d5\u05ea: \u05e2\u05d3\u05d9\u05e0\u05d4, \u05d1\u05d9\u05e0\u05d5\u05e0\u05d9\u05ea, \u05d2\u05e1\u05d4, \u05d5\u05d2\u05e1\u05d4 \u05de\u05d0\u05d5\u05d3, \u05e9\u05de\u05e1\u05d5\u05de\u05e0\u05d5\u05ea \u05e6"],[80.0,"\u05d4\u05e1\u05d1\u05d5\u05dc\u05ea \u05dc\u05d0 \u05e7\u05d1\u05d5\u05e2\u05d4. \u05d4\u05d9\u05d0 \u05d2\u05d3\u05dc\u05d4 \u05e2\u05dd \u05d4\u05de\u05d9\u05d3\u05d4."],[84.0,"\u05d1\u05d3\u05e8\u05d2\u05d4 \u05d1\u05d9\u05e0\u05d5\u05e0\u05d9\u05ea, \u05de\u05d9\u05d3\u05d4 \u05e9\u05dc 20 \u05de\"\u05de \u05de\u05e7\u05d1\u05dc\u05ea 30.2, \u05d5\u05de\u05d9\u05d3\u05d4 \u05e9\u05dc 200 \u05de\"\u05de \u05de\u05e7\u05d1\u05dc\u05ea 50.5."],[95.0,"\u05dc\u05db\u05df \u05d0\u05d9 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d3\u05e2\u05ea \u05d0\u05ea \u05d4\u05e1\u05d1\u05d5\u05dc\u05ea \u05e9\u05dc \u05de\u05d9\u05d3\u05d4 \u05d1\u05dc\u05d9 \u05dc\u05d1\u05d3\u05d5\u05e7 \u05d1\u05d0\u05d9\u05d6\u05d4 \u05ea\u05d7\u05d5\u05dd \u05d4\u05d9\u05d0 \u05e0\u05de\u05e6\u05d0\u05ea \u05d1\u05d8\u05d1\u05dc\u05d4."],[101.0,"\u05d6\u05d5\u05d5\u05d9\u05d5\u05ea \u05de\u05e7\u05d1\u05dc\u05d5\u05ea \u05e1\u05d1\u05d5\u05dc\u05ea \u05dc\u05e4\u05d9 \u05d0\u05d5\u05e8\u05da \u05d4\u05e6\u05dc\u05e2 \u05d4\u05e7\u05e6\u05e8\u05d4, \u05d5\u05dc\u05d0 \u05dc\u05e4\u05d9 \u05d2\u05d5\u05d3\u05dc \u05d4\u05d6\u05d5\u05d5\u05d9\u05ea."],[108.0,"\u05e9\u05dc \u05e9\u05d9\u05e4\u05d5\u05e2\u05d9\u05dd: \u05d1\u05d3\u05e8\u05d2\u05d4 \u05d1\u05d9\u05e0\u05d5\u05e0\u05d9\u05ea, \u05e2\u05d3 3 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8 0.2+, \u05d5\u05de\u05e2\u05dc 6\u05d7\u05d9\u05dc\u05d9\u05de\u05d8\u05e81+ \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8."],[125.0,"\u05db\u05da \u05d2\u05dd \u05e4\u05d9\u05e0\u05d4 \u05e9\u05d1\u05d5\u05e8\u05d4, \u05d0\u05d5 \u05e8\u05d3\u05d9\u05d5\u05e1 \u05e7\u05d8\u05df \u05e9\u05de\u05e6\u05d5\u05d9\u05e8 \u05d1\u05dc\u05d9 \u05e1\u05d1\u05d5\u05dc\u05ea, \u05de\u05d5\u05d2\u05d3\u05e8\u05d9\u05dd."],[131.0,"\u05db\u05dc\u05dc\u05d9\u05d5\u05ea: \u05d9\u05e9\u05e8\u05d5\u05ea, \u05e9\u05d8\u05d9\u05d7\u05d5\u05ea, \u05e0\u05d9\u05e6\u05d1\u05d5\u05ea \u05d5\u05e1\u05d9\u05de\u05d8\u05e8\u05d9\u05d4, \u05d1\u05e9\u05dc\u05d5\u05e9 \u05d3\u05e8\u05d2\u05d5\u05ea: L ,> ,\u05d7."],[146.0,"\u05e1\u05d9\u05de\u05d5\u05df \u05db\u05de\u05d5 \u05d0\u05d7\u05d6-2768 ISO \u05d0\u05d5\u05de\u05e8: \u05d3\u05e8\u05d2\u05d4 \u05d1\u05d9\u05e0\u05d5\u05e0\u05d9\u05ea \u05dc\u05de\u05d9\u05d3\u05d5\u05ea, \u05d5\u05d3\u05e8\u05d2\u05d4 K \u05dc\u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05d4."],[156.0,"1, \u05d5\u05dc\u05db\u05df \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8\u05d9\u05dd \u05d0\u05e4\u05e9\u05e8 \u05dc\u05e4\u05d2\u05d5\u05e9 \u05d0\u05ea \u05e9\u05e0\u05d9 \u05d4\u05e1\u05d9\u05de\u05d5\u05e0\u05d9\u05dd."],[170.0,"\u05de\u05d9 \u05e9\u05de\u05e7\u05d1\u05dc \u05e9\u05e8\u05d8\u05d5\u05d8 \u05e2\u05dd \u05d0\u05d7\u05d6 \u05e6\u05e8\u05d9\u05da \u05dc\u05d3\u05e2\u05ea \u05e9\u05d2\u05dd \u05d4\u05e0\u05d9\u05e6\u05d1\u05d5\u05ea \u05d5\u05d4\u05e9\u05d8\u05d9\u05d7\u05d5\u05ea \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7 \u05de\u05d5\u05d2\u05d1\u05dc\u05d5\u05ea, \u05d0\u05e3 \u05e9\u05d0\u05d9\u05df \u05e2\u05dc\u05d9\u05d4\u05df \u05e1\u05d9\u05de\u05d5\u05df."],[180.0,"1 ISO \u05e2\u05d5\u05d1\u05d3 \u05d0\u05d7\u05e8\u05ea \u05de\u05d4\u05d7\u05dc\u05e7 \u05d4\u05e9\u05e0\u05d9 \u05e9\u05dc 2768 50!."],[189.0,"\u05e1\u05d1\u05d5\u05dc\u05ea \u05e4\u05e8\u05d5\u05e4\u05d9\u05dc \u05de\u05e9\u05d8\u05d7 \u05db\u05dc\u05dc\u05d9\u05ea, \u05d1\u05d9\u05d7\u05e1 \u05dc\u05de\u05e2\u05e8\u05db\u05ea \u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05e9\u05de\u05d5\u05e4\u05d9\u05e2\u05d4 \u05d1\u05d0\u05d6\u05d5\u05e8 \u05d4\u05db\u05d5\u05ea\u05e8\u05ea."],[200.0,"\u05d4\u05db\u05d5\u05ea\u05e8\u05ea \u05d2\u05dd \u05d0\u05ea \u05e2\u05e8\u05da \u05d4\u05e1\u05d1\u05d5\u05dc\u05ea \u05d5\u05d2\u05dd \u05d0\u05ea \u05d4\u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05e9\u05d4\u05d9\u05d0 \u05de\u05ea\u05d9\u05d9\u05d7\u05e1\u05ea \u05d0\u05dc\u05d9\u05d4\u05dd."],[214.0,"\u05d1\u05e9\u05e8\u05d8\u05d5\u05d8\u05d9\u05dd \u05dc\u05e4\u05d9 ASME, \u05d5\u05d1\u05de\u05d9\u05d5\u05d7\u05d3 \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8\u05d9 \u05d0\u05d9\u05e0\u05e5, \u05d9\u05e9 \u05de\u05d5\u05e1\u05db\u05de\u05d4 \u05d0\u05d7\u05e8\u05ea."],[220.0,"\u05d4\u05e0\u05e7\u05d5\u05d3\u05d4. \u05dc\u05de\u05e9\u05dc, \u05e1\u05e4\u05e8\u05d4 \u05d0\u05d7\u05ea: 0.1+. \u05e9\u05ea\u05d9 \u05e1\u05e4\u05e8\u05d5\u05ea: 50.01. \u05d5\u05e9\u05dc\u05d5\u05e9 \u05e1\u05e4\u05e8\u05d5\u05ea: t0.005."],[238.0,"\u05d5\u05d0\u05d6 \u05d0\u05d5\u05ea\u05d5 \u05de\u05e1\u05e4\u05e8, \u05db\u05ea\u05d5\u05d1 \u05d1\u05e9\u05ea\u05d9 \u05e6\u05d5\u05e8\u05d5\u05ea, \u05de\u05e7\u05d1\u05dc \u05e9\u05ea\u05d9 \u05e1\u05d1\u05d5\u05dc\u05d5\u05ea \u05e9\u05d5\u05e0\u05d5\u05ea: 1.5 \u05dc\u05e2\u05d5\u05de\u05ea 1.500 \u05d4\u05df \u05dc\u05d0 \u05d0\u05d5\u05ea\u05d4 \u05d3\u05e8\u05d9\u05e9\u05d4."],[250.0,"\u05e7\u05d5\u05d1\u05e2\u05ea \u05d0\u05d5\u05ea\u05dd \u05d1\u05d0\u05d6\u05d5\u05e8 \u05d4\u05db\u05d5\u05ea\u05e8\u05ea \u05e9\u05dc\u05d4, \u05d5\u05dc\u05db\u05df \u05ea\u05de\u05d9\u05d3 \u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05d0\u05ea \u05d0\u05d6\u05d5\u05e8 \u05d4\u05db\u05d5\u05ea\u05e8\u05ea \u05e9\u05dc \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d4\u05e1\u05e4\u05e6\u05d9\u05e4\u05d9."],[262.0,"\u05d5\u05de\u05d9 \u05e9\u05de\u05d5\u05e1\u05d9\u05e3 \u05d0\u05d5 \u05de\u05d5\u05d7\u05e7 \u05d0\u05e4\u05e1 \u05d1\u05e1\u05d5\u05e3 \u05de\u05d9\u05d3\u05d4, \u05de\u05e9\u05e0\u05d4 \u05d0\u05ea \u05d4\u05e1\u05d1\u05d5\u05dc\u05ea \u05e9\u05dc\u05d4."],[268.0,"\u05dc\u05d6\u05d5\u05d5\u05d9\u05d5\u05ea, \u05dc\u05de\u05e9\u05dc 0.5\u00b0+, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d4\u05e2\u05e8\u05d4 \u05e2\u05dc \u05e9\u05d1\u05d9\u05e8\u05ea \u05e4\u05d9\u05e0\u05d5\u05ea \u05d7\u05d3\u05d5\u05ea."],[281.0,"\u05d5\u05d9\u05e9 \u05de\u05dc\u05db\u05d5\u05d3\u05ea \u05de\u05d5\u05d3\u05e8\u05e0\u05d9\u05ea: \u05e9\u05e8\u05d8\u05d5\u05d8 \u05e9\u05d4\u05d5\u05e4\u05e7 \u05de\u05de\u05e2\u05e8\u05db\u05ea CAD,; \u05e2\u05dd \u05e9\u05dc\u05d5\u05e9 \u05e1\u05e4\u05e8\u05d5\u05ea \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e0\u05e7\u05d5\u05d3\u05d4 \u05d1\u05db\u05dc \u05d4\u05de\u05d9\u05d3\u05d5\u05ea."],[289.0,"\u05d0\u05dd \u05d0\u05d6\u05d5\u05e8 \u05d4\u05db\u05d5\u05ea\u05e8\u05ea \u05e7\u05d5\u05d1\u05e2 \u05e1\u05d1\u05d5\u05dc\u05ea \u05dc\u05e4\u05d9 \u05de\u05e1\u05e4\u05e8 \u05d4\u05e1\u05e4\u05e8\u05d5\u05ea, \u05db\u05dc \u05de\u05d9\u05d3\u05d4 \u05db\u05d6\u05d5 \u05de\u05e7\u05d1\u05dc\u05ea \u05e4\u05ea\u05d0\u05d5\u05dd \u05d0\u05ea \u05d4\u05e1\u05d1\u05d5\u05dc\u05ea \u05d4\u05d4\u05d3\u05d5\u05e7\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8."],[298.0,"\u05d6\u05d5 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05dc\u05d0 \u05db\u05d5\u05d5\u05e0\u05ea \u05d4\u05de\u05ea\u05db\u05e0\u05df, \u05d0\u05d1\u05dc \u05de\u05d1\u05d7\u05d9\u05e0\u05ea \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d6\u05d5 \u05d4\u05d3\u05e8\u05d9\u05e9\u05d4, \u05d5\u05dc\u05db\u05df \u05e9\u05d5\u05d0\u05dc\u05d9\u05dd."],[306.0,"\u05e1\u05d1\u05d5\u05dc\u05d5\u05ea \u05db\u05dc\u05dc\u05d9\u05d5\u05ea \u05d7\u05dc\u05d5\u05ea \u05d2\u05dd \u05e2\u05dc \u05de\u05d4 \u05e9\u05dc\u05d0 \u05de\u05de\u05d5\u05d3\u05d3 \u05d1\u05db\u05dc\u05dc."],[310.0,"\u05d6\u05d5\u05d5\u05d9\u05ea \u05d9\u05e9\u05e8\u05d4 \u05e9\u05de\u05e6\u05d5\u05d9\u05e8\u05ea \u05d1\u05dc\u05d9 \u05de\u05d9\u05d3\u05d4 \u05de\u05e7\u05d1\u05dc\u05ea \u05d0\u05ea \u05e1\u05d1\u05d5\u05dc\u05ea \u05d4\u05d6\u05d5\u05d5\u05d9\u05ea \u05d4\u05db\u05dc\u05dc\u05d9\u05ea."],[316.0,"\u05e9\u05e0\u05e8\u05d0\u05d9\u05dd \u05e1\u05d9\u05de\u05d8\u05e8\u05d9\u05d9\u05dd, \u05e0\u05de\u05e6\u05d0\u05d9\u05dd \u05d1\u05e7\u05e9\u05e8 \u05d4\u05d6\u05d4 \u05e8\u05e7 \u05d1\u05d2\u05d1\u05d5\u05dc\u05d5\u05ea \u05d4\u05e1\u05d1\u05d5\u05dc\u05d5\u05ea \u05d4\u05db\u05dc\u05dc\u05d9\u05d5\u05ea, \u05d5\u05dc\u05d0 \u05d1\u05d3\u05d9\u05d5\u05e7 \u05de\u05d5\u05d7\u05dc\u05d8."],[328.0,"\u05d1\u05de\u05d9\u05dc\u05d9\u05dd \u05d0\u05d7\u05e8\u05d5\u05ea: \u05de\u05d4 \u05e9\u05e0\u05e8\u05d0\u05d4 \u05de\u05d9\u05d5\u05e9\u05e8 \u05d0\u05d5 \u05e0\u05d9\u05e6\u05d1 \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8, \u05de\u05d9\u05d5\u05e9\u05e8 \u05d5\u05e0\u05d9\u05e6\u05d1 \u05e8\u05e7 \u05d1\u05d2\u05d1\u05d5\u05dc\u05d5\u05ea \u05d4\u05e1\u05d1\u05d5\u05dc\u05ea \u05d4\u05db\u05dc\u05dc\u05d9\u05ea."],[337.0,"\u05d1\u05ea\u05e7\u05df 2768 50! \u05d9\u05e9 \u05e2\u05d9\u05e7\u05e8\u05d5\u05df \u05e9\u05db\u05d3\u05d0\u05d9 \u05dc\u05d4\u05db\u05d9\u05e8."],[342.0,"\u05dc\u05e4\u05d9 \u05d4\u05ea\u05e7\u05df, \u05d7\u05dc\u05e7 \u05e9\u05d7\u05d5\u05e8\u05d2 \u05de\u05e1\u05d1\u05d5\u05dc\u05ea \u05db\u05dc\u05dc\u05d9\u05ea \u05dc\u05d0 \u05e0\u05e4\u05e1\u05dc \u05d1\u05d0\u05d5\u05e4\u05df \u05d0\u05d5\u05d8\u05d5\u05de\u05d8\u05d9, \u05d0\u05dd \u05d4\u05e4\u05d5\u05e0\u05e7\u05e6\u05d9\u05d4 \u05e9\u05dc\u05d5 \u05dc\u05d0 \u05e0\u05e4\u05d2\u05e2\u05ea."],[351.0,"\u05d0\u05e4\u05e1, \u05d4\u05d4\u05d7\u05dc\u05d8\u05d4 \u05e2\u05dc \u05d7\u05dc\u05e7 \u05d7\u05d5\u05e8\u05d2 \u05e9\u05d9\u05d9\u05db\u05ea \u05dc\u05de\u05d9 \u05e9\u05d0\u05d7\u05e8\u05d0\u05d9 \u05e2\u05dc \u05d4\u05ea\u05db\u05e0\u05d5\u05df."],[360.0,"\u05d1\u05ea\u05e7\u05df ASME Y14.5 \u05d0\u05d9\u05df \u05e1\u05e2\u05d9\u05e3 \u05d3\u05d5\u05de\u05d4. \u05de\u05d9\u05d3\u05d4 \u05de\u05d7\u05d5\u05e5 \u05dc\u05e1\u05d1\u05d5\u05dc\u05ea \u05d4\u05d9\u05d0 \u05de\u05d7\u05d5\u05e5 \u05dc\u05e1\u05d1\u05d5\u05dc\u05ea."],[370.0,"\u05d4\u05e1\u05d1\u05d5\u05dc\u05ea \u05d4\u05db\u05dc\u05dc\u05d9\u05ea \u05e0\u05d1\u05d7\u05e8\u05ea \u05dc\u05e4\u05d9 \u05d4\u05d3\u05d9\u05d5\u05e7 \u05d4\u05e8\u05d2\u05d9\u05dc \u05e9\u05dc \u05d1\u05d9\u05ea \u05d4\u05de\u05dc\u05d0\u05db\u05d4, \u05db\u05da \u05e9\u05e8\u05d5\u05d1 \u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05d9\u05ea\u05e7\u05d1\u05dc\u05d5 \u05d1\u05dc\u05d9 \u05de\u05d0\u05de\u05e5 \u05de\u05d9\u05d5\u05d7\u05d3."],[378.0,"\u05e1\u05d1\u05d5\u05dc\u05ea \u05db\u05dc\u05dc\u05d9\u05ea \u05d4\u05d3\u05d5\u05e7\u05d4 \u05de\u05d3\u05d9 \u05de\u05d9\u05d9\u05e7\u05e8\u05ea \u05d0\u05ea \u05db\u05dc \u05d4\u05d7\u05dc\u05e7, \u05db\u05d9 \u05db\u05dc \u05de\u05d9\u05d3\u05d4 \u05d4\u05d5\u05e4\u05db\u05ea \u05dc\u05d3\u05e8\u05d9\u05e9\u05d4."],[385.0,"\u05e9\u05e0\u05e9\u05db\u05d7\u05d4 \u05d1\u05dc\u05d9 \u05e1\u05d1\u05d5\u05dc\u05ea \u05de\u05e9\u05dc\u05d4 \u05de\u05e7\u05d1\u05dc\u05ea \u05e1\u05d1\u05d5\u05dc\u05ea \u05e9\u05dc\u05d0 \u05de\u05ea\u05d0\u05d9\u05de\u05d4 \u05dc\u05d4."],[396.0,"\u05dc\u05db\u05df \u05db\u05e9\u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05e9\u05e8\u05d8\u05d5\u05d8, \u05e9\u05d5\u05d0\u05dc\u05d9\u05dd \u05e2\u05dc \u05db\u05dc \u05de\u05d9\u05d3\u05d4 \u05d7\u05e9\u05d5\u05d1\u05d4: \u05d4\u05d0\u05dd \u05d4\u05e1\u05d1\u05d5\u05dc\u05ea \u05d4\u05db\u05dc\u05dc\u05d9\u05ea \u05d1\u05d0\u05de\u05ea \u05de\u05e1\u05e4\u05d9\u05e7\u05d4 \u05dc\u05d4?"],[405.0,"\u05de\u05d9\u05d3\u05d4 \u05d1\u05dc\u05d9 \u05e1\u05d1\u05d5\u05dc\u05ea \u05de\u05e7\u05d1\u05dc\u05ea \u05d0\u05ea \u05d4\u05e1\u05d1\u05d5\u05dc\u05ea \u05d4\u05db\u05dc\u05dc\u05d9\u05ea \u05de\u05d0\u05d6\u05d5\u05e8 \u05d4\u05db\u05d5\u05ea\u05e8\u05ea."],[410.0,"\u05d1\u05ea\u05e7\u05df 2768 ISO \u05d4\u05e1\u05d1\u05d5\u05dc\u05ea \u05ea\u05dc\u05d5\u05d9\u05d4 \u05d1\u05d2\u05d5\u05d3\u05dc \u05d4\u05de\u05d9\u05d3\u05d4, \u05d5\u05d4\u05e1\u05d9\u05de\u05d5\u05df \u05d7\u05d7 \u05de\u05d2\u05d1\u05d9\u05dc \u05d2\u05dd \u05d0\u05ea \u05d4\u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05d4."],[419.0,"\u05d1\u05e9\u05e8\u05d8\u05d5\u05d8\u05d9 \u05d0\u05d9\u05e0\u05e5, \u05de\u05e1\u05e4\u05e8 \u05d4\u05e1\u05e4\u05e8\u05d5\u05ea \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e0\u05e7\u05d5\u05d3\u05d4 \u05d4\u05d5\u05d0 \u05d7\u05dc\u05e7 \u05de\u05d4\u05d3\u05e8\u05d9\u05e9\u05d4."],[425.0,"\u05d5\u05de\u05d4 \u05e9\u05e0\u05e8\u05d0\u05d4 \u05e0\u05d9\u05e6\u05d1 \u05d0\u05d5 \u05de\u05d9\u05d5\u05e9\u05e8 \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8, \u05de\u05d5\u05d2\u05d1\u05dc \u05e8\u05e7 \u05d1\u05e1\u05d1\u05d5\u05dc\u05ea \u05d4\u05db\u05dc\u05dc\u05d9\u05ea."],[431.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05d2\u05d9\u05e2 \u05dc\u05d0\u05d7\u05d3 \u05d4\u05d4\u05d1\u05d3\u05dc\u05d9\u05dd \u05d4\u05e2\u05de\u05d5\u05e7\u05d9\u05dd \u05d1\u05d9\u05df ASME \u05dc\u05d1\u05d9\u05df 50\u05d5: \u05e2\u05e7\u05e8\u05d5\u05df \u05d4\u05de\u05e2\u05d8\u05e4\u05ea \u05de\u05d5\u05dc \u05e2\u05e7\u05e8\u05d5\u05df \u05d4\u05e2\u05e6\u05de\u05d0\u05d5\u05ea."],[441.0,"\u05e0\u05ea\u05e8\u05d0\u05d4 \u05d1\u05e4\u05e8\u05e7 \u05e9\u05e9."]]};
window.MH_TR["ch06"]={"t":"\u05e2\u05e7\u05e8\u05d5\u05df \u05d4\u05de\u05e2\u05d8\u05e4\u05ea \u05de\u05d5\u05dc \u05e2\u05e7\u05e8\u05d5\u05df \u05d4\u05e2\u05e6\u05de\u05d0\u05d5\u05ea","l":[[1.0,"\u05e0\u05e0\u05d9\u05d7 \u05e9\u05e2\u05dc \u05e6\u05d9\u05e8 \u05db\u05ea\u05d5\u05d1 \u05e7\u05d5\u05d8\u05e8 \u05e2\u05e9\u05e8\u05d9\u05dd, \u05e4\u05dc\u05d5\u05e1 \u05de\u05d9\u05e0\u05d5\u05e1 \u05d7\u05de\u05e2\u05d5 \u05de\u05d0\u05d9\u05d5\u05ea."],[6.0,"\u05d4\u05e6\u05d9\u05e8 \u05e0\u05d1\u05d3\u05e7, \u05d5\u05db\u05dc \u05d4\u05de\u05d3\u05d9\u05d3\u05d5\u05ea \u05d1\u05d9\u05df \u05e2\u05e9\u05e8\u05d9\u05dd \u05e4\u05d7\u05d5\u05ea \u05d7\u05de\u05e9 \u05de\u05d0\u05d9\u05d5\u05ea \u05dc\u05e2\u05e9\u05e8\u05d9\u05dd \u05d5\u05e2\u05d5\u05d3 \u05d7\u05de\u05e9 \u05de\u05d0\u05d9\u05d5\u05ea. \u05d0\u05d1\u05dc \u05d4\u05e6\u05d9\u05e8 \u05de\u05e2\u05d8 \u05e2\u05e7\u05d5\u05dd."],[16.0,"\u05d4\u05d0\u05dd \u05d4\u05d5\u05d0 \u05ea\u05e7\u05d9\u05df? \u05d4\u05ea\u05e9\u05d5\u05d1\u05d4 \u05ea\u05dc\u05d5\u05d9\u05d4 \u05d1\u05ea\u05e7\u05df \u05e9\u05d1\u05d0\u05d6\u05d5\u05e8 \u05d4\u05db\u05d5\u05ea\u05e8\u05ea."],[21.0,"\u05dc\u05d4\u05ea\u05e7\u05d1\u05dc. \u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05d1\u05d9\u05df \u05dc\u05de\u05d4, \u05d5\u05de\u05d4 \u05d6\u05d4 \u05de\u05e9\u05e0\u05d4 \u05d1\u05d1\u05d3\u05d9\u05e7\u05d4 \u05d5\u05d1\u05d4\u05e8\u05db\u05d1\u05d4."],[34.0,"\u05d1\u05ea\u05e7\u05df 14.5\" ASME \u05d9\u05e9 \u05db\u05dc\u05dc \u05e9\u05e0\u05e7\u05e8\u05d0 1\u05d0 Rule: \u05e2\u05e7\u05e8\u05d5\u05df \u05d4\u05de\u05e2\u05d8\u05e4\u05ea."],[43.0,"\u05d4\u05db\u05dc\u05dc \u05d0\u05d5\u05de\u05e8 \u05e9\u05d2\u05d1\u05d5\u05dc\u05d5\u05ea \u05d4\u05de\u05d9\u05d3\u05d4 \u05e9\u05dc \u05d0\u05dc\u05de\u05e0\u05d8 \u05e7\u05d5\u05d1\u05e2\u05d9\u05dd \u05dc\u05d0 \u05e8\u05e7 \u05d0\u05ea \u05d4\u05d2\u05d5\u05d3\u05dc \u05e9\u05dc\u05d5, \u05d0\u05dc\u05d0 \u05d2\u05dd \u05db\u05de\u05d4 \u05d4\u05e6\u05d5\u05e8\u05d4 \u05e9\u05dc\u05d5 \u05d9\u05db\u05d5\u05dc\u05d4 \u05dc\u05e1\u05d8\u05d5\u05ea."],[52.0,"\u05d1\u05de\u05e6\u05d1 \u05d7\u05d5\u05de\u05e8 \u05de\u05e7\u05e1\u05d9\u05de\u05dc\u05d9, MMC, \u05d4\u05d0\u05dc\u05de\u05e0\u05d8 \u05d7\u05d9\u05d9\u05d1 \u05dc\u05d4\u05d9\u05d5\u05ea \u05d1\u05e6\u05d5\u05e8\u05d4 \u05de\u05d5\u05e9\u05dc\u05de\u05ea."],[59.0,"\u05d1\u05e6\u05d9\u05e8, \u05d6\u05d4 \u05d0\u05d5\u05de\u05e8 \u05e9\u05db\u05dc \u05d4\u05e6\u05d9\u05e8 \u05d7\u05d9\u05d9\u05d1 \u05dc\u05e2\u05d1\u05d5\u05e8 \u05d3\u05e8\u05da \u05d2\u05dc\u05d9\u05dc \u05de\u05d5\u05e9\u05dc\u05dd \u05d1\u05e7\u05d5\u05d8\u05e8 \u05e2\u05e9\u05e8\u05d9\u05dd \u05d5\u05e2\u05d5\u05d3 \u05d7\u05de\u05e9\u05d5 \u05de\u05d0\u05d9\u05d5\u05ea."],[68.0,"\u05db\u05db\u05dc \u05e9\u05d4\u05e6\u05d9\u05e8 \u05d3\u05e7 \u05d9\u05d5\u05ea\u05e8, \u05d9\u05e9 \u05dc\u05d5 \u05d9\u05d5\u05ea\u05e8 \u05de\u05e7\u05d5\u05dd \u05dc\u05d4\u05ea\u05e2\u05e7\u05dd. \u05d6\u05d4 \u05de\u05d5\u05ea\u05e8, \u05db\u05dc \u05e2\u05d5\u05d3 \u05d4\u05d5\u05d0 \u05e0\u05e9\u05d0\u05e8 \u05d1\u05ea\u05d5\u05da \u05d4\u05de\u05e2\u05d8\u05e4\u05ea."],[77.0,"\u05dc\u05db\u05df ASME-2 \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d0\u05dc\u05de\u05e0\u05d8 \u05e2\u05dd \u05de\u05d9\u05d3\u05d4 \u05d1\u05e9\u05ea\u05d9 \u05d3\u05e8\u05db\u05d9\u05dd."],[82.0,"\u05d1\u05d3\u05d9\u05e7\u05d4 \u05d0\u05d7\u05ea \u05d4\u05d9\u05d0 \u05e9\u05dc \u05d4\u05de\u05e2\u05d8\u05e4\u05ea: \u05d4\u05d0\u05dd \u05d4\u05d7\u05dc\u05e7 \u05db\u05d5\u05dc\u05d5 \u05e0\u05db\u05e0\u05e1 \u05dc\u05d2\u05dc\u05d9\u05dc \u05d4\u05de\u05d5\u05e9\u05dc\u05dd, \u05d0\u05d5, \u05d1\u05e7\u05d3\u05d7, \u05d4\u05d0\u05dd \u05e4\u05d9\u05df \u05de\u05d5\u05e9\u05dc\u05dd \u05e0\u05db\u05e0\u05e1 \u05d0\u05dc\u05d9\u05d5."],[92.0,"\u05dc\u05d0\u05d5\u05e8\u05da \u05d4\u05d7\u05dc\u05e7, \u05d4\u05de\u05d9\u05d3\u05d4 \u05d1\u05d9\u05df \u05e9\u05ea\u05d9 \u05e0\u05e7\u05d5\u05d3\u05d5\u05ea \u05dc\u05d0 \u05d9\u05d5\u05e6\u05d0\u05ea \u05de\u05d4\u05d2\u05d1\u05d5\u05dc \u05d4\u05e9\u05e0\u05d9."],[102.0,"\u05d6\u05d4 \u05d4\u05e2\u05d9\u05e7\u05e8\u05d5\u05df \u05d4\u05d5\u05d5\u05ea\u05d9\u05e7 \u05e9\u05dc \u05d6\u05e1\u05d5\u05e54\u05d3: \u05de\u05d3 \"\u05e2\u05d5\u05d1\u05e8\" \u05d1\u05e6\u05d5\u05e8\u05d4 \u05de\u05dc\u05d0\u05d4, \u05d5\u05de\u05d3 \"\u05dc\u05d0 \u05e2\u05d5\u05d1\u05e8\" \u05d1\u05e9\u05ea\u05d9 \u05e0\u05e7\u05d5\u05d3\u05d5\u05ea."],[109.0,"\u05e6\u05d9\u05e8 \u05e2\u05e7\u05d5\u05dd \u05d9\u05db\u05d5\u05dc \u05dc\u05e2\u05d1\u05d5\u05e8 \u05d0\u05ea \u05d4\u05de\u05d3\u05d9\u05d3\u05d4 \u05d4\u05de\u05e7\u05d5\u05de\u05d9\u05ea \u05d1\u05db\u05dc \u05e0\u05e7\u05d5\u05d3\u05d4, \u05d5\u05e2\u05d3\u05d9\u05d9\u05df \u05dc\u05d4\u05d9\u05e4\u05e1\u05dc \u05d1\u05d1\u05d3\u05d9\u05e7\u05ea \u05d4\u05de\u05e2\u05d8\u05e4\u05ea."],[117.0,"\u05e0\u05d9\u05e7\u05d7 \u05e4\u05d9\u05df \u05d1\u05e7\u05d5\u05d8\u05e8 10, \u05d1\u05e1\u05d1\u05d5\u05dc\u05ea \u05e9\u05dc \u05de\u05d9\u05e0\u05d5\u05e1 0.04, \u05d5\u05e7\u05d3\u05d7 \u05d1\u05e7\u05d5\u05d8\u05e8 10, \u05d1\u05e1\u05d1\u05d5\u05dc\u05ea \u05e9\u05dc \u05e4\u05dc\u05d5\u05e1 0.05."],[127.0,"\u05dc\u05e1\u05d9 \u05e2\u05e7\u05e8\u05d5\u05df \u05d4\u05de\u05e2\u05d8\u05e4\u05dc\u05ea, \u05d4\u05e4\u05d9\u05df \u05d4\u05d2\u05d3\u05d5\u05dc \u05d1\u05d9\u05d5\u05ea\u05e8, \u05d1\u05e7\u05d5\u05d8\u05e8 \u05e2\u05e9\u05e8\u05d4 \u05d1\u05d3\u05d9\u05d5\u05e7, \u05d7\u05d9\u05d9\u05d1 \u05dc\u05d4\u05d9\u05d5\u05ea \u05d9\u05e9\u05e8 \u05dc\u05d7\u05dc\u05d5\u05d8\u05d9\u05df."],[136.0,"\u05e4\u05d9\u05df \u05d1\u05e7\u05d5\u05d8\u05e8 9.96 \u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05ea\u05e2\u05e7\u05dd \u05e2\u05d3 \u05d0\u05e8\u05d1\u05e2 \u05de\u05d0\u05d9\u05d5\u05ea, \u05d5\u05e2\u05d3\u05d9\u05d9\u05df \u05dc\u05d4\u05d9\u05e9\u05d0\u05e8 \u05d1\u05ea\u05d5\u05da \u05de\u05e2\u05d8\u05e4\u05ea \u05e9\u05dc \u05e2\u05e9\u05e8\u05d4."],[145.0,"\u05d2\u05dd \u05d4\u05e7\u05d3\u05d7, \u05d1\u05e7\u05d5\u05d8\u05e8 \u05d4\u05de\u05d9\u05e0\u05d9\u05de\u05dc\u05d9 \u05e9\u05dc\u05d5, \u05d7\u05d9\u05d9\u05d1 \u05dc\u05e7\u05d1\u05dc \u05e4\u05d9\u05df \u05de\u05d5\u05e9\u05dc\u05dd \u05d1\u05e7\u05d5\u05d8\u05e8 \u05e2\u05e9\u05e8\u05d4."],[151.0,"\u05d4\u05ea\u05d5\u05e6\u05d0\u05d4: \u05db\u05dc \u05e4\u05d9\u05df \u05ea\u05e7\u05d9\u05df \u05e0\u05db\u05e0\u05e1 \u05dc\u05db\u05dc \u05e7\u05d3\u05d7 \u05ea\u05e7\u05d9\u05df, \u05ea\u05de\u05d9\u05d3. \u05d6\u05d4 \u05de\u05d4 \u05e9\u05e2\u05e7\u05e8\u05d5\u05df \u05d4\u05de\u05e2\u05d8\u05e4\u05ea \u05de\u05d1\u05d8\u05d9\u05d7."],[160.0,"\u05e0\u05e7\u05d5\u05d3\u05d4 \u05d5\u05dc\u05d4\u05d9\u05d5\u05ea \u05e2\u05e7\u05d5\u05dd \u05d1\u05e9\u05dc\u05d5\u05e9 \u05de\u05d0\u05d9\u05d5\u05ea. \u05d0\u05d6 \u05d4\u05d5\u05d0 \u05ea\u05d5\u05e4\u05e1 \u05de\u05e7\u05d5\u05dd \u05e9\u05dc 10.03, \u05d5\u05e2\u05dc\u05d5\u05dc \u05dc\u05d0 \u05dc\u05d4\u05d9\u05db\u05e0\u05e1 \u05dc\u05e7\u05d3\u05d7 \u05d1\u05e7\u05d5\u05d8\u05e8 \u05e2\u05e9\u05e8\u05d4."],[176.0,"\u05d1\u05ea\u05e7\u05e0\u05d9 ISO \u05d1\u05e8\u05d9\u05e8\u05ea \u05d4\u05de\u05d7\u05d3\u05dc \u05d4\u05e4\u05d5\u05db\u05d4."],[179.0,"\u05dc\u05e1\u05d9 8015 50\u05d5, \u05db\u05dc \u05d3\u05e8\u05d9\u05e9\u05d4 \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05e2\u05d5\u05de\u05d3\u05ea \u05d1\u05e4\u05e0\u05d9 \u05e2\u05e6\u05de\u05d4. \u05e1\u05d1\u05d5\u05dc\u05ea \u05de\u05d9\u05d3\u05d4 \u05e9\u05d5\u05dc\u05d8\u05ea \u05e8\u05e7 \u05d1\u05de\u05d9\u05d3\u05d4, \u05d5\u05dc\u05d0 \u05d1\u05e6\u05d5\u05e8\u05d4."],[190.0,"\u05d5\u05de\u05d9\u05d3\u05d4 \u05d1\u05ea\u05e7\u05e0\u05d9 ISO \u05e0\u05d1\u05d3\u05e7\u05ea \u05db\u05d1\u05e8\u05d9\u05e8\u05ea \u05de\u05d7\u05d3\u05dc \u05d1\u05d9\u05df \u05e9\u05ea\u05d9 \u05e0\u05e7\u05d5\u05d3\u05d5\u05ea, \u05dc\u05e4\u05d9 14405 ASO"],[199.0,"\u05d0\u05d6 \u05d4\u05e6\u05d9\u05e8 \u05d4\u05e2\u05e7\u05d5\u05dd \u05e9\u05dc\u05e0\u05d5 \u05e2\u05d5\u05de\u05d3 \u05d1\u05d3\u05e8\u05d9\u05e9\u05ea \u05d4\u05de\u05d9\u05d3\u05d4, \u05db\u05d9 \u05db\u05dc \u05de\u05d3\u05d9\u05d3\u05d4 \u05d1\u05d9\u05df \u05e9\u05ea\u05d9 \u05e0\u05e7\u05d5\u05d3\u05d5\u05ea \u05e0\u05de\u05e6\u05d0\u05ea \u05d1\u05ea\u05d5\u05da \u05d4\u05d2\u05d1\u05d5\u05dc\u05d5\u05ea."],[207.0,"\u05d0\u05ea \u05d4\u05e2\u05e7\u05de\u05d5\u05de\u05d9\u05d5\u05ea \u05e9\u05dc\u05d5 \u05de\u05d2\u05d1\u05d9\u05dc\u05d4 \u05e8\u05e7 \u05e1\u05d1\u05d5\u05dc\u05ea \u05d9\u05e9\u05e8\u05d5\u05ea, \u05d0\u05dd \u05d9\u05e9 \u05db\u05d6\u05d5 \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8, \u05d0\u05d5 \u05d4\u05e1\u05d1\u05d5\u05dc\u05ea \u05d4\u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05ea \u05d4\u05db\u05dc\u05dc\u05d9\u05ea."],[216.0,"5 ISO \u05dc\u05d0 \u05de\u05e1\u05ea\u05e4\u05e7 \u05d1\u05e9\u05ea\u05d9 \u05e0\u05e7\u05d5\u05d3\u05d5\u05ea. \u05d4\u05d5\u05d0 \u05de\u05d2\u05d3\u05d9\u05e8 \u05db\u05de\u05d4 \u05d3\u05e8\u05db\u05d9\u05dd \u05dc\u05de\u05d3\u05d5\u05d3 \u05de\u05d9\u05d3\u05d4, \u05d5\u05dc\u05db\u05dc \u05d0\u05d7\u05ea \u05d9\u05e9 \u05e1\u05d9\u05de\u05df."],[226.0,"\u05dd \u05d4\u05d9\u05d0 \u05de\u05d9\u05d3\u05d4 \u05d1\u05d9\u05df \u05e9\u05ea\u05d9 \u05e0\u05e7\u05d5\u05d3\u05d5\u05ea, \u05d5\u05d6\u05d5 \u05d1\u05e8\u05d9\u05e8\u05ea \u05d4\u05de\u05d7\u05d3\u05dc."],[231.0,"GG \u05d4\u05d9\u05d0 \u05de\u05d9\u05d3\u05d4 \u05de\u05d7\u05d5\u05e9\u05d1\u05ea \u05d1\u05e9\u05d9\u05d8\u05ea \u05d4\u05e8\u05d9\u05d1\u05d5\u05e2\u05d9\u05dd \u05d4\u05e7\u05d8\u05e0\u05d9\u05dd, \u05db\u05de\u05d5 \u05e9\u05e8\u05d5\u05d1 \u05de\u05db\u05d5\u05e0\u05d5\u05ea \u05d4\u05de\u05d3\u05d9\u05d3\u05d4 \u05de\u05d7\u05e9\u05d1\u05d5\u05ea."],[238.0,"\u05d0\u05e1 \u05d4\u05d5\u05d0 \u05d4\u05d2\u05dc\u05d9\u05dc \u05d4\u05e7\u05d8\u05df \u05d1\u05d9\u05d5\u05ea\u05e8 \u05e9\u05de\u05e7\u05d9\u05e3 \u05e6\u05d9\u05e8, GX-1 \u05d4\u05d5\u05d0 \u05d4\u05d2\u05dc\u05d9\u05dc \u05d4\u05d2\u05d3\u05d5\u05dc \u05d1\u05d9\u05d5\u05ea\u05e8 \u05e9\u05e0\u05db\u05e0\u05e1 \u05dc\u05e7\u05d3\u05d7."],[247.0,"\u05e1\u05d9\u05de\u05df E \u05d4\u05d5\u05d0 \u05dc\u05de\u05e2\u05e9\u05d4 \u05e9\u05d9\u05dc\u05d5\u05d1: \u05d0\u05e1 \u05d0\u05d5 \u05d0\u05e1 \u05d1\u05d2\u05d1\u05d5\u05dc \u05e9\u05dc \u05d4\u05d7\u05d5\u05de\u05e8 \u05d4\u05de\u05e7\u05e1\u05d9\u05de\u05dc\u05d9, \u05d5-\u05dd ! \u05d1\u05d2\u05d1\u05d5\u05dc \u05d4\u05e9\u05e0\u05d9."],[257.0,"\u05d1\u05e9\u05d9\u05d8\u05ea \u05d4\u05e8\u05d9\u05d1\u05d5\u05e2\u05d9\u05dd \u05d4\u05e7\u05d8\u05e0\u05d9\u05dd \u05de\u05d5\u05d3\u05d3\u05ea \u05d3\u05d1\u05e8 \u05d0\u05d7\u05e8 \u05de\u05de\u05d4 \u05e9\u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d1\u05d9\u05e7\u05e9, \u05d0\u05dd \u05dc\u05d0 \u05db\u05ea\u05d5\u05d1 GG."],[269.0,"\u05db\u05e9\u05d4\u05e4\u05d5\u05e0\u05e7\u05e6\u05d9\u05d4 \u05d3\u05d5\u05e8\u05e9\u05d5\u05ea \u05de\u05e2\u05d8\u05e4\u05ea, \u05dc\u05de\u05e9\u05dc \u05e6\u05d9\u05e8 \u05e9\u05d7\u05d9\u05d9\u05d1 \u05dc\u05d4\u05d9\u05db\u05e0\u05e1 \u05dc\u05e7\u05d3\u05d7, \u05e6\u05e8\u05d9\u05da \u05dc\u05d1\u05e7\u05e9 \u05d0\u05d5\u05ea\u05d4 \u05d1\u05de\u05e4\u05d5\u05e8\u05e9."],[278.0,"\u05e2\u05d5\u05e9\u05d9\u05dd \u05d0\u05ea \u05d6\u05d4 \u05d1\u05e1\u05d9\u05de\u05df 5 \u05d1\u05ea\u05d5\u05da \u05e2\u05d9\u05d2\u05d5\u05dc, \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e1\u05d1\u05d5\u05dc\u05ea, \u05dc\u05de\u05e9\u05dc \u00a9 7\u05d7 020."],[286.0,"\u05d0\u05d5 \u05d1\u05d4\u05e2\u05e8\u05d4 \u05db\u05dc\u05dc\u05d9\u05ea, \u05db\u05de\u05d5 4-6 \u05d7\u05d7-2768 50\u05d5, \u05e9\u05de\u05e4\u05e2\u05d9\u05dc\u05d4 \u05d0\u05ea \u05d4\u05de\u05e2\u05d8\u05e4\u05ea \u05e2\u05dc \u05db\u05dc \u05d4\u05d0\u05dc\u05de\u05e0\u05d8\u05d9\u05dd \u05e2\u05dd \u05de\u05d9\u05d3\u05d4 \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8."],[297.0,"\u05d1\u05dc\u05d9 \u05d4\u05e1\u05d9\u05de\u05df, \u05d2\u05dd \u05d4\u05ea\u05d0\u05de\u05d4 \u05d4\u05d3\u05d5\u05e7\u05d4 \u05e9\u05dc 286 ISO \u05dc\u05d0 \u05de\u05d1\u05d8\u05d9\u05d7\u05d4 \u05d4\u05e8\u05db\u05d1\u05d4, \u05d0\u05dd \u05d4\u05d7\u05dc\u05e7 \u05e2\u05e7\u05d5\u05dd."],[306.0,"\u05d2\u05dd \u05d1\u05ea\u05e7\u05df ASME \u05d0\u05e4\u05e9\u05e8 \u05dc\u05dc\u05db\u05ea \u05d1\u05db\u05d9\u05d5\u05d5\u05df \u05d4\u05d4\u05e4\u05d5\u05da."],[310.0,"\u05d1\u05d2\u05e8\u05e1\u05ea 2018 \u05e0\u05d5\u05e1\u05e3 \u05e1\u05d9\u05de\u05df ! \u05d1\u05ea\u05d5\u05da \u05e2\u05d9\u05d2\u05d5\u05dc, \u05e9\u05de\u05d1\u05d8\u05dc \u05d0\u05ea \u05e2\u05e7\u05e8\u05d5\u05df \u05d4\u05de\u05e2\u05d8\u05e4\u05ea \u05dc\u05d0\u05dc\u05de\u05e0\u05d8 \u05de\u05e1\u05d5\u05d9\u05dd."],[318.0,"\u05d1\u05e9\u05e8\u05d8\u05d5\u05d8\u05d9\u05dd \u05d9\u05e9\u05e0\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8 \u05ea\u05de\u05e6\u05d0\u05d5 \u05d1\u05de\u05e7\u05d5\u05de\u05d5 \u05d4\u05e2\u05e8\u05d4 \u05db\u05de\u05d5 \u2026 \u05d3\u05e1\u05d0 MMC \u05d6\u05d4 \u2026 ."],[327.0,"\u05d7\u05d5\u05de\u05e8 \u05d2\u05dc\u05dd, \u05db\u05de\u05d5 \u05de\u05d5\u05d8\u05d5\u05ea \u05d5\u05e4\u05d7\u05d9\u05dd, \u05d5\u05d7\u05dc\u05e7\u05d9\u05dd \u05d2\u05de\u05d9\u05e9\u05d9\u05dd \u05e9\u05e0\u05de\u05d3\u05d3\u05d9\u05dd \u05d1\u05de\u05e6\u05d1 \u05d7\u05d5\u05e4\u05e9\u05d9."],[338.0,"\u05d7\u05e9\u05d5\u05d1 \u05dc\u05d4\u05d1\u05d9\u05df \u05d2\u05dd \u05d0\u05ea \u05d4\u05d2\u05d1\u05d5\u05dc \u05e9\u05dc \u05e2\u05e7\u05e8\u05d5\u05df \u05d4\u05de\u05e2\u05d8\u05e4\u05ea."],[342.0,"\u05d4\u05d5\u05d0 \u05e9\u05d5\u05dc\u05d8 \u05d1\u05e6\u05d5\u05e8\u05d4 \u05e9\u05dc \u05d0\u05dc\u05de\u05e0\u05d8 \u05d0\u05d7\u05d3, \u05d0\u05d1\u05dc \u05dc\u05d0 \u05d1\u05e7\u05e9\u05e8 \u05d1\u05d9\u05df \u05e9\u05e0\u05d9 \u05d0\u05dc\u05de\u05e0\u05d8\u05d9\u05dd."],[347.0,"\u05dc\u05e7\u05e6\u05d4, \u05dc\u05d0 \u05e0\u05e9\u05dc\u05d8\u05d9\u05dd \u05e2\u05dc \u05d9\u05d3\u05d9 \u05e2\u05e7\u05e8\u05d5\u05df \u05d4\u05de\u05e2\u05d8\u05e4\u05ea. \u05dc\u05e9\u05dd \u05e6\u05e8\u05d9\u05da \u05e1\u05d1\u05d5\u05dc\u05d5\u05ea \u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05d5\u05ea."],[360.0,"\u05de\u05d9 \u05e9\u05d7\u05d5\u05e9\u05d1 \u05e9\u05d2\u05d1\u05d5\u05dc\u05d5\u05ea \u05d4\u05de\u05d9\u05d3\u05d4 \u05de\u05d1\u05d8\u05d9\u05d7\u05d9\u05dd \u05e9\u05e9\u05e0\u05d9 \u05e7\u05d8\u05e8\u05d9\u05dd \u05d9\u05d4\u05d9\u05d5 \u05e2\u05dc \u05d0\u05d5\u05ea\u05d5 \u05e6\u05d9\u05e8, \u05d8\u05d5\u05e2\u05d4 \u05d1\u05e9\u05e0\u05d9 \u05d4\u05ea\u05e7\u05e0\u05d9\u05dd."],[367.0,"\u05e9\u05e8\u05d8\u05d5\u05d8 ISO \u05e9\u05e0\u05e7\u05e8\u05d0 \u05d1\u05e2\u05d9\u05e0\u05d9\u05d9\u05dd \u05e9\u05dc ASME \u05d9\u05d2\u05e8\u05d5\u05dd \u05dc\u05e4\u05e1\u05d5\u05dc \u05d7\u05dc\u05e7\u05d9\u05dd \u05d8\u05d5\u05d1\u05d9\u05dd, \u05d0\u05d5 \u05dc\u05d1\u05d6\u05d1\u05d6 \u05d6\u05de\u05df \u05e2\u05dc \u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05e9\u05dc\u05d0 \u05e0\u05d3\u05e8\u05e9\u05d5."],[377.0,"\u05d5\u05e9\u05e8\u05d8\u05d5\u05d8 ASME \u05e9\u05e0\u05e7\u05e8\u05d0 \u05d1\u05e2\u05d9\u05e0\u05d9\u05d9\u05dd \u05e9\u05dc 50! \u05d9\u05d2\u05e8\u05d5\u05dd \u05dc\u05e7\u05d1\u05dc \u05d7\u05dc\u05e7\u05d9\u05dd \u05e9\u05dc\u05d0 \u05d9\u05d9\u05db\u05e0\u05e1\u05d5 \u05d1\u05d4\u05e8\u05db\u05d1\u05d4."],[386.0,"\u05dc\u05db\u05df \u05dc\u05e4\u05e0\u05d9 \u05e9\u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d0\u05dc\u05de\u05e0\u05d8 \u05e2\u05dd \u05de\u05d9\u05d3\u05d4, \u05de\u05d5\u05e6\u05d0\u05d9\u05dd \u05d1\u05d0\u05d6\u05d5\u05e8 \u05d4\u05db\u05d5\u05ea\u05e8\u05ea \u05dc\u05e4\u05d9 \u05d0\u05d9\u05d6\u05d4 \u05ea\u05e7\u05df \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8."],[393.0,"\u05d5\u05d0\u05dd \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05dc\u05e4\u05d9 ISO \u05d5\u05d4\u05d7\u05dc\u05e7 \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d9\u05db\u05e0\u05e1 \u05dc\u05d7\u05dc\u05e7 \u05d0\u05d7\u05e8, \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d0\u05dd \u05d9\u05e9 \u05e1\u05d9\u05de\u05df\u05dd. \u05d0\u05dd \u05d0\u05d9\u05df, \u05d6\u05d5 \u05e9\u05d0\u05dc\u05d4 \u05dc\u05de\u05ea\u05db\u05e0\u05df."],[405.0,"\u05d1\u05ea\u05e7\u05df ASME, \u05d1\u05e8\u05d9\u05e8\u05ea \u05d4\u05de\u05d7\u05d3\u05dc \u05d4\u05d9\u05d0 \u05e2\u05e7\u05e8\u05d5\u05df \u05d4\u05de\u05e2\u05d8\u05e4\u05ea: \u05d1\u05de\u05e6\u05d1 \u05d7\u05d5\u05de\u05e8 \u05de\u05e7\u05e1\u05d9\u05de\u05dc\u05d9, \u05e6\u05d5\u05e8\u05d4 \u05de\u05d5\u05e9\u05dc\u05de\u05ea."],[413.0,"\u05d1\u05ea\u05e7\u05e0\u05d9 50!, \u05d1\u05e8\u05d9\u05e8\u05ea \u05d4\u05de\u05d7\u05d3\u05dc \u05d4\u05d9\u05d0 \u05e2\u05e7\u05e8\u05d5\u05df \u05d4\u05e2\u05e6\u05de\u05d0\u05d5\u05ea: \u05d4\u05de\u05d9\u05d3\u05d4 \u05e0\u05d1\u05d3\u05e7\u05ea \u05d1\u05d9\u05df \u05e9\u05ea\u05d9 \u05e0\u05e7\u05d5\u05d3\u05d5\u05ea, \u05d5\u05d4\u05e6\u05d5\u05e8\u05d4 \u05e0\u05e9\u05dc\u05d8\u05ea \u05d1\u05e0\u05e4\u05e8\u05d3."],[422.0,"\u05e1\u05d9\u05de\u05df 6 \u05de\u05e4\u05e2\u05d9\u05dc \u05de\u05e2\u05d8\u05e4\u05ea \u05d1\u05ea\u05e7\u05e0\u05d9 50\u05d5, \u05d5\u05e1\u05d9\u05de\u05df! \u05de\u05d1\u05d8\u05dc \u05d0\u05d5\u05ea\u05d4 \u05d1\u05ea\u05e7\u05df ASME"],[429.0,"\u05d5\u05d1\u05e9\u05e0\u05d9 \u05d4\u05ea\u05e7\u05e0\u05d9\u05dd, \u05d4\u05de\u05e2\u05d8\u05e4\u05ea \u05dc\u05d0 \u05e9\u05d5\u05dc\u05d8\u05ea \u05d1\u05e7\u05e9\u05e8 \u05d1\u05d9\u05df \u05d0\u05dc\u05de\u05e0\u05d8\u05d9\u05dd."],[434.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05db\u05d9\u05e8 \u05d0\u05ea \u05de\u05e2\u05e8\u05db\u05ea \u05d4\u05d4\u05ea\u05d0\u05de\u05d5\u05ea \u05e9\u05dc 286 50\u05d5: \u05de\u05d4 \u05d0\u05d5\u05de\u05e8\u05d9\u05dd 7\u05d7 \u05d5 6\u05dd, \u05d5\u05d0\u05d9\u05da \u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05d4\u05ea\u05d0\u05de\u05d4."],[445.0,"\u05e0\u05ea\u05e8\u05d0\u05d4 \u05d1\u05e4\u05e8\u05e7 \u05e9\u05d1\u05e2."]]};
window.MH_TR["ch07"]={"t":"\u05d4\u05ea\u05d0\u05de\u05d5\u05ea ISO 286","l":[[1.0,"\u05db\u05e9\u05e6\u05d9\u05e8 \u05e0\u05db\u05e0\u05e1 \u05dc\u05e7\u05d3\u05d7, \u05d4\u05e9\u05d0\u05dc\u05d4 \u05d4\u05d7\u05e9\u05d5\u05d1\u05d4 \u05d4\u05d9\u05d0 \u05dc\u05d0 \u05e8\u05e7 \u05de\u05d4 \u05d4\u05e7\u05d5\u05d8\u05e8 \u05e9\u05dc\u05d4\u05dd, \u05d0\u05dc\u05d0 \u05d0\u05d9\u05da \u05d4\u05dd \u05d9\u05ea\u05e0\u05d4\u05d2\u05d5 \u05d9\u05d7\u05d3."],[9.0,"\u05d4\u05d0\u05dd \u05d4\u05e6\u05d9\u05e8 \u05d9\u05e1\u05ea\u05d5\u05d1\u05d1 \u05d1\u05d7\u05d5\u05e4\u05e9\u05d9\u05d5\u05ea, 1 \u05d9\u05de\u05d5\u05e7\u05dd | \u05d1\u05de\u05d3\u05d5\u05d9\u05e7, \u05d0\u05d5\u05d9\u05d9\u05d3\u05d7 \u05e4\u05e0\u05d9\u05ea\u05d4 \u05d5\u05dc\u05d0 \u05d9\u05d6\u05d7 \u05dc\u05e2\u05d5\u05dc\u05dd?"],[16.0,"\u05de\u05e2\u05e8\u05db\u05ea \u05d4\u05d4\u05ea\u05d0\u05de\u05d5\u05ea \u05e9\u05dc 286 50\u05d5 \u05e2\u05d5\u05e0\u05d4 \u05e2\u05dc \u05d4\u05e9\u05d0\u05dc\u05d4 \u05d4\u05d6\u05d5 \u05d1\u05e9\u05e0\u05d9 \u05e1\u05d9\u05de\u05e0\u05d9\u05dd \u05e7\u05e6\u05e8\u05d9\u05dd, \u05db\u05de\u05d5 7\u05d7 \u05d5-06."],[26.0,"\u05d0\u05ea \u05d4\u05de\u05e8\u05d5\u05d5\u05d7 \u05d0\u05d5 \u05d0\u05ea \u05d4\u05d7\u05e4\u05d9\u05e4\u05d4, \u05d5\u05dc\u05d4\u05d1\u05d9\u05df \u05de\u05d4 \u05d4\u05dd \u05d3\u05d5\u05e8\u05e9\u05d9\u05dd \u05de\u05d4\u05d9\u05d9\u05e6\u05d5\u05e8\u05d5\u05de\u05d4\u05d1\u05d3\u05d9\u05e7\u05d4."],[37.0,"\u05db\u05dc \u05e1\u05d9\u05de\u05d5\u05df \u05d4\u05ea\u05d0\u05de\u05d4 \u05d1\u05e0\u05d5\u05d9 \u05de\u05d0\u05d5\u05ea \u05d5\u05de\u05e1\u05e4\u05e8."],[41.0,"\u05d4\u05d0\u05d5\u05ea \u05e7\u05d5\u05d1\u05e2\u05ea \u05d0\u05d9\u05e4\u05d4 \u05e0\u05de\u05e6\u05d0 \u05e9\u05d3\u05d4 \u05d4\u05e1\u05d1\u05d5\u05dc\u05ea \u05d1\u05d9\u05d7\u05e1 \u05dc\u05de\u05d9\u05d3\u05d4 \u05d4\u05e0\u05d5\u05de\u05d9\u05e0\u05dc\u05d9\u05ea: \u05de\u05e2\u05dc\u05d9\u05d4, \u05de\u05ea\u05d7\u05ea\u05d9\u05d4, \u05d0\u05d5 \u05e1\u05d1\u05d9\u05d1\u05d4."],[50.0,"\u05d4\u05de\u05e1\u05e4\u05e8 \u05d4\u05d5\u05d0 \u05d3\u05e8\u05d2\u05ea \u05d4\u05d3\u05d9\u05d5\u05e7, \u05d3\u05d5, \u05d5\u05d4\u05d5\u05d0 \u05e7\u05d5\u05d1\u05e2 \u05db\u05de\u05d4 \u05e8\u05d7\u05d1 \u05e9\u05d3\u05d4 \u05d4\u05e1\u05d1\u05d5\u05dc\u05ea."],[56.0,"\u05d0\u05d5\u05ea \u05d2\u05d3\u05d5\u05dc\u05d4 \u05de\u05e1\u05de\u05e0\u05ea \u05e7\u05d3\u05d7, \u05d5\u05d0\u05d5\u05ea \u05e7\u05d8\u05e0\u05d4 \u05de\u05e1\u05de\u05e0\u05ea \u05e6\u05d9\u05e8."],[61.0,"\u05dc\u05db\u05df 7\u05d7 \u05d4\u05d9\u05d0 \u05e1\u05d1\u05d5\u05dc\u05ea \u05e9\u05dc \u05e7\u05d3\u05d7, \u05d5-06 \u05d4\u05d9\u05d0 \u05e1\u05d1\u05d5\u05dc\u05ea \u05e9\u05dc \u05e6\u05d9\u05e8."],[68.0,"\u05d5\u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d4\u05e8\u05db\u05d1\u05d4 \u05db\u05d5\u05ea\u05d1\u05d9\u05dd \u05d0\u05ea \u05e9\u05ea\u05d9\u05d4\u05df \u05d9\u05d7\u05d3, \u05e2\u05dd \u05e7\u05d5 \u05e0\u05d8\u05d5\u05d9: H7/g6."],[76.0,"\u05d3\u05e8\u05d2\u05d5\u05ea \u05d4\u05d3\u05d9\u05d5\u05e7 \u05e0\u05e2\u05d5\u05ea \u2026, \u05d4\u05d3\u05d9\u05d5\u05e7 \u05d4\u05d2\u05d1\u05d5\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8, \u05d5\u05e2\u05d3 8."],[84.0,"\u05e8\u05d5\u05d7\u05d1 \u05d4\u05e9\u05d3\u05d4 \u05ea\u05dc\u05d5\u05d9 \u05d1\u05d3\u05e8\u05d2\u05d4 \u05d5\u05d2\u05dd \u05d1\u05d2\u05d5\u05d3\u05dc \u05d4\u05de\u05d9\u05d3\u05d4: \u05d0\u05d5\u05ea\u05d4 \u05d3\u05e8\u05d2\u05d4 \u05de\u05e7\u05d1\u05dc\u05ea \u05e9\u05d3\u05d4 \u05e8\u05d7\u05d1 \u05d9\u05d5\u05ea\u05e8 \u05d1\u05e7\u05d5\u05d8\u05e8 \u05d2\u05d3\u05d5\u05dc \u05d9\u05d5\u05ea\u05e8."],[93.0,"\u05d4\u05d5\u05d0 \u05e9\u05dc\u05d5\u05e9\u05d4 \u05e2\u05e9\u05e8 \u05d5 \u05de\u05d9\u05e7\u05e8\u05d5\u05df, 7 \u05d6\u05d5 \u05d4\u05d5\u05d0 \u05e2\u05e9\u05e8\u05d9\u05dd \u05d5\u05d0\u05d7\u05d3 \u05d5 \u05de\u05d9\u05e7\u05e8\u05d5\u05df, \u05d5-8\u05d6\u05d5 \u05d4\u05d5\u05d0 \u05e9\u05dc\u05d5\u05e9\u05d9\u05dd \u05d5\u05e9\u05dc\u05d5\u05e9\u05d4 \u05de\u05d9\u05e7\u05e8\u05d5\u05df."],[107.0,"\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e2\u05d3\u05d9\u05df \u05de\u05d0\u05d5\u05d3, 7 \u05d6\u05d5 \u05de\u05ea\u05d0\u05d9\u05dd \u05dc\u05e8\u05d9\u05de\u05e8 \u05d0\u05d5 \u05dc\u05db\u05e8\u05e1\u05d5\u05dd \u05de\u05d3\u05d5\u05d9\u05e7, \u05d5\u05e88 \u05d6\u05d5 \u05e2\u05d3 9\u05d6\u05d5 \u05dc\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e8\u05d2\u05d9\u05dc."],[122.0,"\u05db\u05dc \u05d3\u05e8\u05d2\u05d4 \u05e9\u05de\u05e9\u05e4\u05e8\u05d9\u05dd \u05de\u05e2\u05dc\u05d4 \u05d0\u05ea \u05d4\u05de\u05d7\u05d9\u05e8. \u05d6\u05d5 \u05d4\u05d4\u05d7\u05dc\u05d8\u05d4 \u05d4\u05db\u05dc\u05db\u05dc\u05d9\u05ea \u05e9\u05d1\u05ea\u05d5\u05da \u05d4\u05de\u05e1\u05e4\u05e8 \u05d4\u05e7\u05d8\u05df."],[130.0,"\u05d4\u05d0\u05d5\u05ea \u05e7\u05d5\u05d1\u05e2\u05ea \u05d0\u05ea \u05d4\u05e1\u05d8\u05d9\u05d9\u05d4 \u05d4\u05d9\u05e1\u05d5\u05d3\u05d9\u05ea: \u05d4\u05d2\u05d1\u05d5\u05dc \u05e9\u05dc \u05e9\u05d3\u05d4 \u05d4\u05e1\u05d1\u05d5\u05dc\u05ea \u05e9\u05d4\u05db\u05d9 \u05e7\u05e8\u05d5\u05d1 \u05dc\u05e7\u05d5 \u05d4\u05d0\u05e4\u05e1."],[137.0,"\u05d1\u05e7\u05d3\u05d7 \u05d4, \u05d4\u05d2\u05d1\u05d5\u05dc \u05d4\u05ea\u05d7\u05ea\u05d5\u05df \u05d4\u05d5\u05d0 \u05d1\u05d3\u05d9\u05d5\u05e7 \u05d4\u05de\u05d9\u05d3\u05d4 \u05d4\u05e0\u05d5\u05de\u05d9\u05e0\u05dc\u05d9\u05ea. \u05d4\u05e7\u05d3\u05d7 \u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05d9\u05d5\u05ea \u05e8\u05e7 \u05d2\u05d3\u05d5\u05dc \u05de\u05de\u05e0\u05d4."],[154.0,"\u05d0\u05d5\u05ea\u05d9\u05d5\u05ea \u05de\u05d5\u05e7\u05d3\u05de\u05d5\u05ea \u05d9\u05d5\u05ea\u05e8 \u05d1\u05d0\u05dc\u05e3-\u05d1\u05d9\u05ea, \u05db\u05de\u05d5 f \u05d0\u05d5 g, \u05de\u05e8\u05d7\u05d9\u05e7\u05d5\u05ea \u05d0\u05ea \u05d4\u05e6\u05d9\u05e8 \u05de\u05ea\u05d7\u05ea \u05dc\u05e0\u05d5\u05de\u05d9\u05e0\u05dc\u05d9, \u05d5\u05e0\u05d5\u05ea\u05e0\u05d5\u05ea \u05de\u05e8\u05d5\u05d5\u05d7."],[163.0,"\u05d0\u05d5\u05ea\u05d9\u05d5\u05ea \u05de\u05d0\u05d5\u05d7\u05e8\u05d5\u05ea \u05d9\u05d5\u05ea\u05e8, \u05db\u05de\u05d5 \u05dd \u05d0\u05d5 5, \u05de\u05e2\u05dc\u05d5\u05ea \u05d0\u05ea \u05d4\u05e6\u05d9\u05e8 \u05de\u05e2\u05dc \u05d4\u05e0\u05d5\u05de\u05d9\u05e0\u05dc\u05d9, \u05d5\u05e0\u05d5\u05ea\u05e0\u05d5\u05ea \u05d7\u05e4\u05d9\u05e4\u05d4."],[171.0,"\u05d5\u05db\u05da, \u05d1\u05dc\u05d9 \u05dc\u05d7\u05e9\u05d1 \u05d0\u05e3 \u05de\u05e1\u05e4\u05e8, \u05d4\u05d0\u05d5\u05ea \u05db\u05d1\u05e8 \u05d0\u05d5\u05de\u05e8\u05ea \u05dc\u05e7\u05d5\u05e8\u05d0 \u05d0\u05d9\u05d6\u05d4 \u05e1\u05d5\u05d2 \u05d4\u05ea\u05d0\u05de\u05d4 \u05de\u05ea\u05d5\u05db\u05e0\u05df."],[178.0,"\u05d1\u05e8\u05d5\u05d1 \u05d4\u05ea\u05e2\u05e9\u05d9\u05d9\u05d4 \u05e2\u05d5\u05d1\u05d3\u05d9\u05dd \u05d1\u05de\u05e2\u05e8\u05db\u05ea \u05e7\u05d3\u05d7 \u05d1\u05e1\u05d9\u05e1: \u05d4\u05e7\u05d3\u05d7 \u05d4\u05d5\u05d0 \u05ea\u05de\u05d9\u05d3 \u05d4, \u05d5\u05de\u05e9\u05e0\u05d9\u05dd \u05e8\u05e7 \u05d0\u05ea \u05d4\u05e6\u05d9\u05e8."],[187.0,"\u05db\u05de\u05d5 \u05e8\u05d9\u05de\u05e8, \u05d5\u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d1\u05de\u05d3 \u05e7\u05d1\u05d5\u05e2. \u05e7\u05dc \u05d9\u05d5\u05ea\u05e8 \u05dc\u05d4\u05d7\u05d6\u05d9\u05e7 \u05db\u05dc\u05d9\u05dd \u05db\u05d0\u05dc\u05d4 \u05e8\u05e7 \u05dc\u05de\u05d9\u05d3\u05d5\u05ea \u05d5\u05d6."],[199.0,"\u05d0\u05ea \u05d4\u05e6\u05d9\u05e8 \u05e7\u05dc \u05d9\u05d5\u05ea\u05e8 \u05dc\u05d9\u05d9\u05e6\u05e8 \u05d5\u05dc\u05de\u05d3\u05d5\u05d3 \u05d1\u05db\u05dc \u05de\u05d9\u05d3\u05d4, \u05d1\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d7\u05d9\u05e6\u05d5\u05e0\u05d9."],[204.0,"\u05d1\u05d4 \u05db\u05e9\u05e6\u05d9\u05e8 \u05d0\u05d7\u05d3 \u05d0\u05e8\u05d5\u05da \u05e0\u05d5\u05e9\u05d0 \u05db\u05de\u05d4 \u05d7\u05dc\u05e7\u05d9\u05dd \u05d1\u05d4\u05ea\u05d0\u05de\u05d5\u05ea \u05e9\u05d5\u05e0\u05d5\u05ea."],[214.0,"\u05de\u05d9 \u05e9\u05e8\u05d5\u05d0\u05d4 \u05d4\u05d7 \u05d1\u05db\u05dc \u05d4\u05e7\u05d3\u05d7\u05d9\u05dd \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8, \u05d9\u05d5\u05d3\u05e2 \u05e9\u05d4\u05d5\u05d0 \u05de\u05e1\u05ea\u05db\u05dc \u05e2\u05dc \u05de\u05e2\u05e8\u05db\u05ea \u05e7\u05d3\u05d7 \u05d1\u05e1\u05d9\u05e1."],[221.0,"\u05e0\u05d9\u05e7\u05d7 \u05e7\u05d3\u05d7 \u05d1\u05e7\u05d5\u05d8\u05e8 \u05e2\u05e9\u05e8\u05d9\u05dd \u05d5\u05d7\u05de\u05e9 7\u05d4: \u05de\u05e2\u05e9\u05e8\u05d9\u05dd \u05d5\u05d7\u05de\u05e9 \u05d1\u05d3\u05d9\u05d5\u05e7, \u05d5\u05e2\u05d3 \u05e2\u05e9\u05e8\u05d9\u05dd \u05d5\u05d7\u05de\u05e9 \u05e0\u05e7\u05d5\u05d3\u05d4 \u05d0\u05e4\u05e1 \u05e9\u05ea\u05d9\u05d9\u05dd \u05d0\u05d7\u05ea."],[232.0,"\u05dc\u05e2\u05e9\u05e8\u05d9\u05dd \u05d5\u05d0\u05e8\u05d1\u05e2 \u05e0\u05e7\u05d5\u05d3\u05d4 \u05ea\u05e9\u05e2 \u05ea\u05e9\u05e2 \u05e9\u05dc\u05d5\u05e9, \u05de\u05ea\u05e7\u05d1\u05dc\u05ea \u05d4\u05ea\u05d0\u05de\u05d4 \u05d7\u05d5\u05e4\u05e9\u05d9\u05ea."],[243.0,"\u05d4\u05de\u05e8\u05d5\u05d5\u05d7 \u05d4\u05e7\u05d8\u05df \u05d1\u05d9\u05d5\u05ea\u05e8 \u05d4\u05d5\u05d0 \u05e9\u05d1\u05e2\u05d4 \u05de\u05d9\u05e7\u05e8\u05d5\u05df, \u05d5\u05d4\u05d2\u05d3\u05d5\u05dc \u05d1\u05d9\u05d5\u05ea\u05e8 \u05d0\u05e8\u05d1\u05e2\u05d9\u05dd \u05d5\u05d0\u05d7\u05d3 \u05de\u05d9\u05e7\u05e8\u05d5\u05df. \u05d4\u05e6\u05d9\u05e8 \u05ea\u05de\u05d9\u05d3 \u05d9\u05e0\u05d5\u05e2 \u05d1\u05ea\u05d5\u05da \u05d4\u05e7\u05d3\u05d7."],[252.0,"\u05dc\u05e2\u05e9\u05e8\u05d9\u05dd \u05d5\u05d7\u05de\u05e9 \u05e0\u05e7\u05d5\u05d3\u05d4 \u05d0\u05e4\u05e1 \u05d0\u05d7\u05ea \u05d7\u05de\u05e2\u05d5, \u05de\u05ea\u05e7\u05d1\u05dc\u05ea \u05d4\u05ea\u05d0\u05de\u05ea \u05de\u05e2\u05d1\u05e8."],[263.0,"\u05e9\u05dc \u05e2\u05d3 \u05ea\u05e9\u05e2\u05d4 \u05e2\u05e9\u05e8 \u05de\u05d9\u05e7\u05e8\u05d5\u05df, \u05d0\u05d5 \u05d7\u05e4\u05d9\u05e4\u05d4 \u05e9\u05dc \u05e2\u05d3 \u05d7\u05de\u05d9\u05e9\u05d4 \u05e2\u05e9\u05d5\u05e8 \u05de\u05d9\u05e7\u05e8\u05d5\u05df."],[274.0,"\u05d4\u05ea\u05d0\u05de\u05d4 \u05db\u05d6\u05d5 \u05e0\u05d1\u05d7\u05e8\u05ea \u05dc\u05de\u05d9\u05e7\u05d5\u05dd \u05de\u05d3\u05d5\u05d9\u05e7, \u05db\u05e9\u05d4\u05d7\u05dc\u05e7 \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d9\u05d5\u05ea \u05de\u05d5\u05e8\u05db\u05d1 \u05d1\u05dc\u05d7\u05d9\u05e6\u05d4 \u05e7\u05dc\u05d4 \u05d5\u05dc\u05d4\u05ea\u05e4\u05e8\u05e7 \u05db\u05e9\u05e6\u05e8\u05d9\u05da."],[282.0,"\u05dc\u05e2\u05e9\u05d5\u05e8\u05d9\u05dd \u05d5\u05d7\u05de\u05e9 \u05e0\u05e7\u05d5\u05d3\u05d4 \u05d0\u05e4\u05e1 \u05e9\u05dc\u05d5\u05e9 \u05d7\u05de\u05e9, \u05de\u05ea\u05e7\u05d1\u05dc\u05ea \u05d4\u05ea\u05d0\u05de\u05ea \u05dc\u05d7\u05e5."],[293.0,"\u05d4\u05d7\u05e4\u05d9\u05e4\u05d4 \u05d4\u05e7\u05d8\u05e0\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05d4\u05d9\u05d0 \u05de\u05d9\u05e7\u05e8\u05d5\u05df \u05d0\u05d7\u05d3, \u05d5\u05d4\u05d2\u05d3\u05d5\u05dc\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05e9\u05dc\u05d5\u05e9\u05d9\u05dd \u05d5\u05d7\u05de\u05d9\u05e9\u05d4 \u05de\u05d9\u05e7\u05e8\u05d5\u05df. \u05d4\u05e6\u05d9\u05e8 \u05ea\u05de\u05d9\u05d3 \u05d2\u05d3\u05d5\u05dc \u05de\u05d4\u05e7\u05d3\u05d7."],[303.0,"\u05e4\u05d7\u05d5\u05ea \u05d4\u05e6\u05d9\u05e8 \u05d4\u05e7\u05d8\u05df, \u05d5\u05de\u05e8\u05d5\u05d5\u05d7 \u05de\u05d9\u05e0\u05d9\u05de\u05dc\u05d9 \u05d4\u05d5\u05d0 \u05d4\u05e7\u05d3\u05d7 \u05d4\u05e7\u05d8\u05df \u05e4\u05d7\u05d5\u05ea \u05d4\u05e6\u05d9\u05e8 \u05d4\u05d2\u05d3\u05d5\u05dc."],[315.0,"\u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d7\u05dc\u05e7, \u05d4\u05e1\u05d9\u05de\u05d5\u05df \u05de\u05d5\u05e4\u05d9\u05e2 \u05dc\u05d9\u05d3 \u05d4\u05e7\u05d5\u05d8\u05e8, \u05dc\u05de\u05e9\u05dc \u05e7\u05d5\u05d8\u05e8 \u05e2\u05e9\u05e8\u05d9\u05dd \u05d5\u05d7\u05de\u05e9 7\u05d5."],[323.0,"\u05d4\u05e8\u05d1\u05d4 \u05e9\u05e8\u05d8\u05d5\u05d8\u05d9\u05dd \u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05d1\u05e1\u05d5\u05d2\u05e8\u05d9\u05d9\u05dd \u05d2\u05dd \u05d0\u05ea \u05d4\u05d2\u05d1\u05d5\u05dc\u05d5\u05ea \u05e2\u05e6\u05de\u05dd, \u05db\u05d3\u05d9 \u05e9\u05dc\u05d0 \u05d9\u05e6\u05d8\u05e8\u05db\u05d5 \u05dc\u05d7\u05e4\u05e9\u05d5 \u05d1\u05d8\u05d1\u05dc\u05d4."],[330.0,"\u05d0\u05dd \u05de\u05d5\u05e4\u05d9\u05e2\u05d9\u05dd \u05d2\u05dd \u05d4\u05e1\u05d9\u05de\u05d5\u05df \u05d5\u05d2\u05dd \u05d4\u05d2\u05d1\u05d5\u05dc\u05d5\u05ea, \u05d5\u05d4\u05dd \u05dc\u05d0 \u05de\u05ea\u05d0\u05d9\u05de\u05d9\u05dd \u05d6\u05d4 \u05dc\u05d6\u05d4, \u05d6\u05d5 \u05e1\u05ea\u05d9\u05e8\u05d4, \u05d5\u05e9\u05d5\u05d0\u05dc\u05d9\u05dd."],[337.0,"\u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d4\u05e8\u05db\u05d1\u05d4 \u05de\u05d5\u05e4\u05d9\u05e2 \u05d4\u05e6\u05d9\u05e8\u05d5\u05e3, 7/06\u05d5, \u05db\u05d3\u05d9 \u05dc\u05d4\u05e8\u05d0\u05d5\u05ea \u05d0\u05ea \u05d4\u05db\u05d5\u05d5\u05e0\u05d4 \u05e9\u05dc \u05d4\u05d4\u05ea\u05d0\u05de\u05d4."],[345.0,"\u05de\u05e1\u05d5\u05d2 \u05d0\u05d7\u05e8, \u05db\u05de\u05d5 RC \u05d0\u05d5 \u05d0\u05d7, \u05dc\u05e4\u05d9 \u05ea\u05e7\u05df B4.1 \u2026). \u05d4\u05e8\u05e2\u05d9\u05d5\u05df \u05d6\u05d4\u05d4, \u05d5\u05d4\u05d8\u05d1\u05dc\u05d0\u05d5\u05ea \u05e9\u05d5\u05e0\u05d5\u05ea."],[362.0,"\u05e7\u05d3\u05d7 H7 \u05e0\u05d1\u05d3\u05e7 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05de\u05d3 \u05e4\u05e7\u05e7: \u05e6\u05d3 \u05e2\u05d5\u05d1\u05e8 \u05d1\u05d2\u05d1\u05d5\u05dc \u05d4\u05ea\u05d7\u05ea\u05d5\u05df, \u05d5\u05e6\u05d3 \u05dc\u05d0 \u05e2\u05d5\u05d1\u05e8 \u05d1\u05d2\u05d1\u05d5\u05dc \u05d4\u05e2\u05dc\u05d9\u05d5\u05df."],[371.0,"\u05e6\u05d9\u05e8 \u05e0\u05d1\u05d3\u05e7 \u05d1\u05de\u05d3 \u05d8\u05d1\u05e2\u05ea \u05d0\u05d5 \u05d1\u05de\u05d3 \u05de\u05dc\u05e7\u05d7\u05d9\u05d9\u05dd, \u05d1\u05d0\u05d5\u05ea\u05d5 \u05e2\u05d9\u05e7\u05e8\u05d5\u05df."],[376.0,"\u05de\u05d3\u05d9\u05d3\u05d4 \u05d1\u05e7\u05dc\u05d9\u05d1\u05e8 \u05e8\u05d2\u05d9\u05dc \u05d1\u05d3\u05e8\u05d2\u05d4 \u05db\u05d6\u05d5 \u05db\u05de\u05e2\u05d8 \u05dc\u05d0 \u05de\u05e1\u05e4\u05d9\u05e7\u05d4, \u05db\u05d9 \u05e9\u05d3\u05d4 \u05e9\u05dc \u05e2\u05e9\u05e8\u05d9\u05dd \u05de\u05d9\u05e7\u05e8\u05d5\u05df \u05e7\u05e8\u05d5\u05d1 \u05dc\u05d3\u05d9\u05d5\u05e7 \u05e9\u05dc \u05d4\u05db\u05dc\u05d9 \u05e2\u05e6\u05de\u05d5."],[385.0,"\u05d5\u05d1\u05d4\u05ea\u05d0\u05de\u05ea \u05dc\u05d7\u05e5, \u05d4\u05d4\u05e8\u05db\u05d1\u05d4 \u05e2\u05e6\u05de\u05d4 \u05d4\u05d9\u05d0 \u05d7\u05dc\u05e7 \u05de\u05d4\u05ea\u05d4\u05dc\u05d9\u05da: \u05dc\u05d7\u05d9\u05e6\u05d4, \u05d7\u05d9\u05de\u05d5\u05dd \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7 \u05d4\u05d7\u05d9\u05e6\u05d5\u05e0\u05d9 \u05d0\u05d5 \u05e7\u05d9\u05e8\u05d5\u05e8 \u05e9\u05dc \u05d4\u05e6\u05d9\u05e8."],[395.0,"\u05dc\u05db\u05df \u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05d4\u05ea\u05d0\u05de\u05d4 \u05d2\u05dd \u05db\u05d4\u05d5\u05e8\u05d0\u05d4 \u05e2\u05e7\u05d9\u05e4\u05d4 \u05dc\u05d9\u05d9\u05e6\u05d5\u05e8: \u05d0\u05d9\u05d6\u05d4 \u05ea\u05d4\u05dc\u05d9\u05da \u05d2\u05d9\u05de\u05d5\u05e8, \u05d0\u05d9\u05d6\u05d4 \u05de\u05d3, \u05d5\u05d0\u05d9\u05d6\u05d4 \u05e9\u05dc\u05d1 \u05d4\u05e8\u05db\u05d1\u05d4 \u05d9\u05d9\u05d3\u05e8\u05e9\u05d5."],[405.0,"\u05e1\u05d9\u05de\u05df 6 \u05dc\u05d0 \u05de\u05d1\u05d8\u05d9\u05d7\u05d4 \u05e9\u05d7\u05dc\u05e7 \u05e2\u05e7\u05d5\u05dd \u05d9\u05d9\u05db\u05e0\u05e1, \u05db\u05de\u05d5 \u05e9\u05e8\u05d0\u05d9\u05e0\u05d5 \u05d1\u05e4\u05e8\u05e7 \u05d4\u05e7\u05d5\u05d3\u05dd."],[418.0,"\u05e9\u05e0\u05d9\u05ea, \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4: \u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05d7\u05dc\u05d5\u05ea \u05d1\u05e2\u05e9\u05d5\u05e8\u05d9\u05dd \u05de\u05e2\u05dc\u05d5\u05ea. \u05e6\u05d9\u05e8 \u05e9\u05e0\u05de\u05d3\u05d3 \u05de\u05d9\u05d3 \u05d0\u05d7\u05e8\u05d9 \u05e2\u05d9\u05d1\u05d5\u05d3, \u05db\u05e9\u05d4\u05d5\u05d0 \u05d7\u05dd, \u05e0\u05de\u05d3\u05d3 \u05d2\u05d3\u05d5\u05dc \u05de\u05d3\u05d9."],[428.0,"\u05e9\u05dc \u05e2\u05e9\u05e8\u05d4 \u05de\u05d9\u05e7\u05e8\u05d5\u05df \u05d1\u05db\u05dc \u05e6\u05d3 \u05d9\u05db\u05d5\u05dc\u05d4 \u05dc\u05d4\u05e4\u05d5\u05da \u05d4\u05ea\u05d0\u05de\u05d4 \u05d7\u05d5\u05e4\u05e9\u05d9\u05ea \u05dc\u05d4\u05ea\u05d0\u05de\u05ea \u05dc\u05d7\u05e5."],[445.0,"\u05d1\u05de\u05d9\u05e7\u05e8\u05d5\u05e0\u05d9\u05dd, \u05d5\u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d1\u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8\u05d9\u05dd. \u05d8\u05e2\u05d5\u05ea \u05d1\u05d4\u05de\u05e8\u05d4 \u05d4\u05d9\u05d0 \u05d8\u05e2\u05d5\u05ea \u05e9\u05dc \u05e4\u05d9 \u05d0\u05dc\u05e3."],[459.0,"\u05e1\u05d9\u05de\u05d5\u05df \u05d4\u05ea\u05d0\u05de\u05d4 \u05d4\u05d5\u05d0 \u05d0\u05d5\u05ea \u05d5\u05de\u05e1\u05e4\u05e8 \u05d4\u05d0\u05d5\u05ea \u05e7\u05d5\u05d1\u05e2\u05ea \u05d0\u05ea \u05d4\u05de\u05d9\u05e7\u05d5\u05dd, \u05d5\u05d4\u05de\u05e1\u05e4\u05e8 \u05d0\u05ea \u05e8\u05d5\u05d7\u05d1 \u05d4\u05e9\u05d3\u05d4."],[466.0,"\u05d0\u05d5\u05ea \u05d2\u05d3\u05d5\u05dc\u05d4 \u05dc\u05e7\u05d3\u05d7, \u05d0\u05d5\u05ea \u05e7\u05d8\u05e0\u05d4 \u05dc\u05e6\u05d9\u05e8, H-1 \u05e4\u05d9\u05e8\u05d5\u05e9\u05d5 \u05e7\u05d3\u05d7 \u05e9\u05de\u05ea\u05d7\u05d9\u05dc \u05d1\u05d3\u05d9\u05d5\u05e7 \u05d1\u05e0\u05d5\u05de\u05d9\u05e0\u05dc\u05d9."],[474.0,"\u05d1\u05de\u05e2\u05e8\u05db\u05ea \u05e7\u05d3\u05d7 \u05d1\u05e1\u05d9\u05e1, \u05d4\u05d0\u05d5\u05ea \u05e9\u05dc \u05d4\u05e6\u05d9\u05e8 \u05d0\u05d5\u05de\u05e8\u05ea \u05de\u05d9\u05d3 \u05d0\u05dd \u05d4\u05d4\u05ea\u05d0\u05de\u05d4 \u05d7\u05d5\u05e4\u05e9\u05d9\u05ea, \u05de\u05e2\u05d1\u05e8 \u05d0\u05d5 \u05dc\u05d7\u05e5."],[482.0,"\u05de\u05e8\u05d5\u05d5\u05d7 \u05de\u05e7\u05e1\u05d9\u05de\u05dc\u05d9 \u05d4\u05d5\u05d0 \u05e7\u05d3\u05d7 \u05d2\u05d3\u05d5\u05dc \u05e4\u05d7\u05d5\u05ea \u05e6\u05d9\u05e8 \u05e7\u05d8\u05df, \u05d5\u05de\u05e8\u05d5\u05d5\u05d7 \u05de\u05d9\u05e0\u05d9\u05de\u05dc\u05d9 \u05d4\u05d5\u05d0 \u05e7\u05d3\u05d7 \u05e7\u05d8\u05df \u05e4\u05d7\u05d5\u05ea \u05e6\u05d9\u05e8 \u05d2\u05d3\u05d5\u05dc."],[492.0,"\u05d5\u05d1\u05db\u05dc \u05d4\u05ea\u05d0\u05de\u05d4 \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d2\u05dd \u05de\u05e2\u05d8\u05e4\u05ea, \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d5\u05e6\u05d9\u05e4\u05d5\u05d9."],[497.0,"RSS-1 Worst Case, \u05d5\u05d0\u05d9\u05da \u05de\u05d6\u05d4\u05d9\u05dd \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d0\u05ea \u05d4\u05de\u05d9\u05d3\u05d4 \u05e9\u05d1\u05d0\u05de\u05ea \u05e7\u05d5\u05d1\u05e2\u05ea."],[509.0,"\u05e0\u05ea\u05e8\u05d0\u05d4 \u05d1\u05e4\u05e8\u05e7 \u05e9\u05de\u05d5\u05e0\u05d4."]]};
window.MH_TR["ch08"]={"t":"\u05e9\u05e8\u05e9\u05e8\u05ea \u05e1\u05d1\u05d5\u05dc\u05d5\u05ea","l":[[1.0,"\u05db\u05dc \u05de\u05d9\u05d3\u05d4 \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05e0\u05d1\u05d3\u05e7\u05ea \u05dc\u05d1\u05d3. \u05d0\u05d1\u05dc \u05d1\u05d4\u05e8\u05db\u05d1\u05d4, \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05e4\u05d5\u05d2\u05e9\u05d9\u05dd \u05d6\u05d4 \u05d0\u05ea \u05d6\u05d4."],[8.0,"\u05d5\u05d9\u05d5\u05e6\u05e8\u05d5\u05ea \u05de\u05e8\u05d5\u05d5\u05d7, \u05d7\u05e4\u05d9\u05e4\u05d4 \u05d0\u05d5 \u05de\u05d9\u05e7\u05d5\u05dd, \u05e9\u05d0\u05e3 \u05d0\u05d7\u05ea \u05de\u05d4\u05df \u05dc\u05d0 \u05de\u05d2\u05d3\u05d9\u05e8\u05d4 \u05dc\u05d1\u05d3."],[18.0,"\u05d6\u05d5 \u05e9\u05e8\u05e9\u05d5\u05e8\u05ea \u05e1\u05d1\u05d5\u05dc\u05d5\u05ea, \u05d5\u05db\u05d0\u05df \u05e0\u05e7\u05d1\u05e2 \u05d0\u05dd \u05d4\u05d4\u05e8\u05db\u05d1\u05d4 \u05ea\u05e2\u05d1\u05d5\u05d3."],[23.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05dc\u05de\u05d3 \u05dc\u05d1\u05e0\u05d5\u05ea \u05e9\u05e8\u05e9\u05e8\u05ea, \u2026 \u05d0\u05d5\u05ea\u05d4 \u05d1\u05e9\u05d5\u05ea\u05d9 \u05e9\u05d9\u05d8\u05d5\u05ea, \u05d5\u05dc\u05d6\u05d4\u05d5\u05ea \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d0\u05ea \u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05e9\u05d1\u05d0\u05de\u05ea \u05e7\u05d5\u05d1\u05e2\u05d5\u05ea."],[33.0,"\u05e9\u05e8\u05e9\u05e8\u05ea \u05e1\u05d1\u05d5\u05dc\u05d5\u05ea \u05d4\u05d9\u05d0 \u05dc\u05d5\u05dc\u05d0\u05d4 \u05e1\u05d2\u05d5\u05e8\u05d4 \u05e9\u05dc \u05de\u05d9\u05d3\u05d5\u05ea, \u05e9\u05de\u05ea\u05d7\u05d9\u05dc\u05d4 \u05d5\u05e0\u05d2\u05de\u05e8\u05ea \u05d1\u05d0\u05d5\u05ea\u05d5 \u05de\u05e7\u05d5\u05dd."],[39.0,"\u05d1\u05de\u05e8\u05db\u05d6 \u05d4\u05dc\u05d5\u05dc\u05d0\u05d4 \u05d9\u05e9 \u05d3\u05e8\u05d9\u05e9\u05d4 \u05d0\u05d7\u05ea: \u05de\u05e8\u05d5\u05d5\u05d7, \u05e2\u05d5\u05d1\u05d9, \u05d0\u05d5 \u05de\u05e8\u05d7\u05e7 \u05e9\u05d7\u05d9\u05d9\u05d1 \u05dc\u05d4\u05d9\u05e9\u05d0\u05e8 \u05d1\u05d2\u05d1\u05d5\u05dc\u05d5\u05ea \u05de\u05e1\u05d5\u05d9\u05de\u05d9\u05dd."],[48.0,"\u05d0\u05ea \u05d4\u05d3\u05e8\u05d9\u05e9\u05d4 \u05d4\u05d6\u05d5 \u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05d4\u05d7\u05d5\u05dc\u05d9\u05d4 \u05d4\u05e1\u05d5\u05d2\u05e8\u05ea. \u05d4\u05d9\u05d0 \u05dc\u05d0 \u05de\u05de\u05d5\u05d3\u05d3\u05ea \u05d9\u05e9\u05d9\u05e8\u05d5\u05ea, \u05d5\u05d4\u05d9\u05d0 \u05ea\u05d5\u05e6\u05d0\u05d4 \u05e9\u05dc \u05db\u05dc \u05d4\u05e9\u05d0\u05e8."],[57.0,"\u05d4\u05d3\u05e8\u05d9\u05e9\u05d4 \u05d4\u05d9\u05d0 \u05d7\u05d9\u05d5\u05d1\u05d9\u05ea, \u05d5\u05de\u05d9\u05d3\u05d4 \u05e9\u05de\u05e7\u05d8\u05d9\u05e0\u05d4 \u05d0\u05d5\u05ea\u05d4 \u05d4\u05d9\u05d0 \u05e9\u05dc\u05d9\u05dc\u05d9\u05ea."],[66.0,"\u05de\u05d9\u05d3\u05d5\u05ea \u05e9\u05dc\u05d0 \u05e0\u05de\u05e6\u05d0\u05d5\u05ea \u05d1\u05dc\u05d5\u05dc\u05d0\u05d4 \u05dc\u05d0 \u05de\u05e9\u05e4\u05d9\u05e2\u05d5\u05ea \u05e2\u05dc \u05d4\u05d3\u05e8\u05d9\u05e9\u05d4, \u05d2\u05dd \u05d0\u05dd \u05d4\u05df \u05d4\u05d3\u05d5\u05e7\u05d5\u05ea \u05de\u05d0\u05d5\u05d3."],[73.0,"\u05dc\u05db\u05df \u05d4\u05e6\u05e2\u05d3 \u05d4\u05e8\u05d0\u05e9\u05d5\u05df \u05d4\u05d5\u05d0 \u05ea\u05de\u05d9\u05d3 \u05dc\u05e6\u05d9\u05d9\u05e8 \u05d0\u05ea \u05d4\u05dc\u05d5\u05dc\u05d0\u05d4, \u05d5\u05dc\u05d0 \u05dc\u05d7\u05e9\u05d1."],[79.0,"\u05e0\u05d1\u05e0\u05d4 \u05d3\u05d5\u05d2\u05de\u05d4: \u05d1\u05d9\u05ea \u05de\u05e1\u05d1 \u05e2\u05dd \u05d7\u05dc\u05dc \u05d1\u05e2\u05d5\u05de\u05e7 \u05d7\u05de\u05d9\u05e9\u05d9\u05dd, \u05d1\u05e1\u05d1\u05d5\u05dc\u05ea \u05e9\u05dc \u05e4\u05dc\u05d5\u05e1 \u05de\u05d9\u05e0\u05d5\u05e1 \u05e2\u05e9\u05d9\u05e8\u05d9\u05ea."],[87.0,"\u05e2\u05e9\u05e8\u05d9\u05dd \u05d5\u05d7\u05de\u05e9, \u05d5\u05d3\u05d9\u05e1\u05e7\u05d9\u05ea \u05d1\u05e2\u05d5\u05d1\u05d9 \u05d0\u05e8\u05d1\u05e2 \u05d5\u05d7\u05e6\u05d9, \u05db\u05dc \u05d0\u05d7\u05d3 \u05d1\u05e1\u05d1\u05d5\u05dc\u05ea \u05e9\u05dc \u05e4\u05dc\u05d5\u05e1 \u05de\u05d9\u05e0\u05d5\u05e1 \u05d7\u05de\u05e9 \u05de\u05d0\u05d9\u05d5\u05ea."],[99.0,"\u05d4\u05d3\u05e8\u05d9\u05e9\u05d4 \u05d4\u05d9\u05d0 \u05de\u05e8\u05d5\u05d5\u05d7 \u05e6\u05d9\u05e8\u05d9 \u05d1\u05d9\u05df \u05d4\u05d3\u05d9\u05e1\u05e7\u05d9\u05ea \u05dc\u05de\u05db\u05e1\u05d4, \u05e9\u05d7\u05d9\u05d9\u05d1 \u05dc\u05d4\u05d9\u05d5\u05ea \u05d1\u05d9\u05df \u05e9\u05ea\u05d9 \u05e2\u05e9\u05d9\u05e8\u05d9\u05d5\u05ea \u05dc\u05e9\u05de\u05d5\u05e0\u05d4 \u05e2\u05e9\u05d9\u05e8\u05d9\u05d5\u05ea."],[108.0,"\u05e2\u05d5\u05de\u05e7 \u05d4\u05d7\u05dc\u05dc \u05de\u05d2\u05d3\u05d9\u05dc \u05d0\u05ea \u05d4\u05de\u05e8\u05d5\u05d5\u05d7, \u05d5\u05dc\u05db\u05df \u05d4\u05d5\u05d0 \u05d7\u05d9\u05d5\u05d1\u05d9."],[112.0,"\u05d4\u05de\u05e1\u05d1, \u05d4\u05ea\u05d5\u05ea\u05d1 \u05d5\u05d4\u05d3\u05d9\u05e1\u05e7\u05d9\u05ea \u05de\u05de\u05dc\u05d0\u05d9\u05dd \u05d0\u05ea \u05d4\u05d7\u05dc\u05dc, \u05d5\u05dc\u05db\u05df \u05d4\u05dd \u05e9\u05dc\u05d9\u05dc\u05d9\u05d9\u05dd."],[119.0,"\u05d4\u05de\u05e8\u05d5\u05d5\u05d7 \u05d4\u05e0\u05d5\u05de\u05d9\u05e0\u05dc\u05d9 \u05d4\u05d5\u05d0 \u05d7\u05de\u05d9\u05e9\u05d9\u05dd, \u05e4\u05d7\u05d5\u05ea \u05e2\u05e9\u05d5\u05e8\u05d9\u05dd, \u05e4\u05d7\u05d5\u05ea \u05e2\u05e9\u05e8\u05d9\u05dd \u05d5\u05d7\u05de\u05e9, \u05e4\u05d7\u05d5\u05ea \u05d0\u05e8\u05d1\u05e2 \u05d5\u05d7\u05e6\u05d9: \u05d7\u05e6\u05d9 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8."],[128.0,"\u05d4\u05e9\u05d0\u05dc\u05d4 \u05d4\u05d9\u05d0 \u05de\u05d4 \u05e7\u05d5\u05e8\u05d4 \u05db\u05e9\u05d5\u05db\u05dc \u05de\u05d9\u05d3\u05d4 \u05d6\u05d6\u05d4 \u05d1\u05ea\u05d5\u05da \u05d4\u05e1\u05d1\u05d5\u05dc\u05ea \u05e9\u05dc\u05d4."],[138.0,"\u05d4\u05e9\u05d9\u05d8\u05d4 \u05d4\u05e8\u05d0\u05e9\u05d5\u05e0\u05d4 \u05d4\u05d9\u05d0 Worst Case: \u05de\u05e0\u05d9\u05d7\u05d9\u05dd \u05e9\u05db\u05dc \u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05e0\u05de\u05e6\u05d0\u05d5\u05ea \u05d1\u05d1\u05ea \u05d0\u05d7\u05ea \u05d1\u05e7\u05e6\u05d4 \u05d4\u05d2\u05e8\u05d5\u05e2 \u05d1\u05d9\u05d5\u05ea\u05e8."],[146.0,"\u05d4\u05e1\u05d1\u05d5\u05dc\u05ea \u05e9\u05dc \u05d4\u05de\u05e8\u05d5\u05d5\u05d7 \u05d4\u05d9\u05d0 \u05e4\u05e9\u05d5\u05d8 \u05e1\u05db\u05d5\u05dd \u05db\u05dc \u05d4\u05e1\u05d1\u05d5\u05dc\u05d5\u05ea."],[150.0,"\u05e2\u05e9\u05d9\u05e8\u05d9\u05ea, \u05d5\u05e2\u05d5\u05d3 \u05e9\u05dc\u05d5\u05e9 \u05e4\u05e2\u05de\u05d9\u05dd \u05d7\u05de\u05e9 \u05de\u05d0\u05d9\u05d5\u05ea, \u05d4\u05df \u05e2\u05e9\u05e8\u05d9\u05dd \u05d5\u05d7\u05de\u05e9 \u05de\u05d0\u05d9\u05d5\u05ea."],[156.0,"\u05dc\u05db\u05df \u05d4\u05de\u05e8\u05d5\u05d5\u05d7 \u05d9\u05db\u05d5\u05dc \u05dc\u05e0\u05d5\u05e2 \u05d1\u05d9\u05df \u05e2\u05e9\u05e8\u05d9\u05dd \u05d5\u05d7\u05de\u05e9 \u05de\u05d0\u05d9\u05d5\u05ea \u05dc\u05e9\u05d1\u05e2\u05d9\u05dd \u05d5\u05d7\u05de\u05e9 \u05de\u05d0\u05d9\u05d5\u05ea."],[163.0,"\u05e9\u05ea\u05d9 \u05d4\u05ea\u05d5\u05e6\u05d0\u05d5\u05ea \u05d1\u05ea\u05d5\u05da \u05d4\u05d3\u05e8\u05d9\u05e9\u05d4, \u05d5\u05dc\u05db\u05df \u05d4\u05d4\u05e8\u05db\u05d1\u05d4 \u05ea\u05e2\u05d1\u05d5\u05d3 \u05ea\u05de\u05d9\u05d3, \u05d1\u05db\u05dc \u05e6\u05d9\u05e8\u05d5\u05e3 \u05e9\u05dc \u05d7\u05dc\u05e7\u05d9\u05dd \u05ea\u05e7\u05d9\u05e0\u05d9\u05dd."],[171.0,"\u05d6\u05d5 \u05d4\u05e9\u05d9\u05d8\u05d4 \u05d4\u05d1\u05d8\u05d5\u05d7\u05d4, \u05d5\u05d4\u05d9\u05d0 \u05de\u05ea\u05d0\u05d9\u05de\u05d4 \u05db\u05e9\u05d9\u05e9 \u05de\u05e2\u05d8 \u05d7\u05dc\u05e7\u05d9\u05dd, \u05d0\u05d5 \u05db\u05e9\u05db\u05e9\u05dc \u05d0\u05d9\u05e0\u05d5 \u05de\u05e7\u05d5\u05d1\u05dc \u05d1\u05e9\u05d5\u05dd \u05de\u05e7\u05e8\u05d4."],[179.0,"\u05d4\u05e9\u05d9\u05d8\u05d4 \u05d4\u05e9\u05e0\u05d9\u05d9\u05d4 \u05d4\u05d9\u05d0 55\u05d7, \u05e9\u05d5\u05e8\u05e9 \u05e1\u05db\u05d5\u05dd \u05d4\u05e8\u05d9\u05d1\u05d5\u05e2\u05d9\u05dd."],[184.0,"\u05d4\u05d9\u05d0 \u05de\u05d1\u05d5\u05e1\u05e1\u05ea \u05e2\u05dc \u05e2\u05d5\u05d1\u05d3\u05d4 \u05e1\u05d8\u05d8\u05d9\u05e1\u05d8\u05d9\u05ea: \u05d4\u05e1\u05d9\u05db\u05d5\u05d9 \u05e9\u05db\u05dc \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05d9\u05d2\u05d9\u05e2\u05d5 \u05dc\u05e7\u05e6\u05d4 \u05d4\u05d2\u05e8\u05d5\u05e2 \u05d1\u05d1\u05ea \u05d0\u05d7\u05ea \u05d4\u05d5\u05d0 \u05db\u05de\u05e2\u05d8 \u05d0\u05e4\u05e1."],[193.0,"\u05d1\u05de\u05e7\u05d5\u05dd \u05dc\u05d7\u05d1\u05e8 \u05d0\u05ea \u05d4\u05e1\u05d1\u05d5\u05dc\u05d5\u05ea, \u05de\u05d7\u05d1\u05e8\u05d9\u05dd \u05d0\u05ea \u05d4\u05e8\u05d9\u05d1\u05d5\u05e2\u05d9\u05dd \u05e9\u05dc\u05d4\u05df, \u05d5\u05de\u05d5\u05e6\u05d9\u05d0\u05d9\u05dd \u05e9\u05d5\u05e8\u05e9\u05d5."],[199.0,"\u05e4\u05e2\u05de\u05d9\u05dd \u05d7\u05de\u05e9 \u05de\u05d0\u05d9\u05d5\u05ea \u05d1\u05e8\u05d9\u05d1\u05d5\u05e2, \u05d9\u05d5\u05e6\u05d0 \u05d1\u05e2\u05e8\u05da \u05e9\u05dc\u05d5\u05e9 \u05e2\u05e9\u05e8\u05d4 \u05de\u05d0\u05d9\u05d5\u05ea."],[209.0,"\u05dc\u05e9\u05d9\u05e9\u05d9\u05dd \u05d5\u05e9\u05dc\u05d5\u05e9 \u05de\u05d0\u05d9\u05d5\u05ea, \u05e6\u05e8 \u05d1\u05d4\u05e8\u05d1\u05d4 \u05de\u05ea\u05d5\u05e6\u05d0\u05ea Worst Case."],[218.0,"\u05db\u05db\u05dc \u05e9\u05d9\u05e9 \u05d9\u05d5\u05ea\u05e8 \u05d7\u05dc\u05e7\u05d9\u05dd \u05d1\u05e9\u05e8\u05e9\u05e8\u05ea, \u05d4\u05d9\u05ea\u05e8\u05d5\u05df \u05e9\u05dc 855 \u05d2\u05d3\u05dc."],[224.0,"\u05de\u05ea\u05e4\u05dc\u05d2\u05ea \u05e1\u05d1\u05d9\u05d1 \u05d4\u05d0\u05de\u05e6\u05e2, \u05d5\u05e9\u05d4\u05ea\u05d4\u05dc\u05d9\u05db\u05d9\u05dd \u05d9\u05e6\u05d9\u05d1\u05d9\u05dd \u05d5\u05d1\u05dc\u05ea\u05d9 \u05ea\u05dc\u05d5\u05d9\u05d9\u05dd \u05d6\u05d4 \u05d1\u05d6\u05d4."],[234.0,"\u05d0\u05dd \u05d9\u05e6\u05e8\u05df \u05de\u05db\u05d5\u05d5\u05df \u05d1\u05e9\u05d9\u05d8\u05ea\u05d9\u05d5\u05ea \u05dc\u05e7\u05e6\u05d4 \u05d4\u05e1\u05d1\u05d5\u05dc\u05ea, \u05d4\u05d4\u05e0\u05d7\u05d4 \u05e0\u05e9\u05d1\u05e8\u05ea, \u05d5-\u20aa55 \u05e0\u05d5\u05ea\u05df \u05ea\u05de\u05d5\u05e0\u05d4 \u05d0\u05d5\u05e4\u05d8\u05d9\u05de\u05d9\u05ea \u05de\u05d3\u05d9."],[243.0,"5 \u05de\u05ea\u05d0\u05d9\u05dd \u05dc\u05d9\u05d9\u05e6\u05d5\u05e8 \u05e1\u05d3\u05e8\u05ea\u05d9, \u05e2\u05dd \u05d4\u05e8\u05d1\u05d4 \u05d7\u05dc\u05e7\u05d9\u05dd \u05d5\u05ea\u05d4\u05dc\u05d9\u05db\u05d9\u05dd \u05d1\u05e9\u05dc\u05d9\u05d8\u05d4 \u05e1\u05d8\u05d8\u05d9\u05e1\u05d8\u05d9\u05ea."],[249.0,"\u05db\u05e9\u05de\u05ea\u05db\u05e0\u05df \u05e0\u05e9\u05e2\u05df \u05e2\u05dc RSS, ASME \u05de\u05d0\u05e4\u05e9\u05e8 \u05dc\u05e1\u05de\u05df \u05d0\u05ea \u05d4\u05e1\u05d1\u05d5\u05dc\u05ea \u05d1\u05e1\u05d9\u05de\u05df 51, \u05e1\u05d1\u05d5\u05dc\u05ea \u05e1\u05d8\u05d8\u05d9\u05e1\u05d8\u05d9\u05ea."],[259.0,"\u05dc\u05e6\u05d3 \u05d4\u05e1\u05d9\u05de\u05df \u05de\u05d5\u05e4\u05d9\u05e2\u05d4 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d4\u05e2\u05e8\u05d4 \u05e9\u05d3\u05d5\u05e8\u05e9\u05d5\u05ea \u05d1\u05e7\u05e8\u05ea \u05ea\u05d4\u05dc\u05d9\u05da \u05e1\u05d8\u05d8\u05d9\u05e1\u05d8\u05d9\u05ea \u05d1\u05d9\u05d9\u05e6\u05d5\u05e8."],[266.0,"\u05dc\u05d0 \u05de\u05e1\u05e4\u05d9\u05e7\u05d4. \u05d2\u05dd \u05d4\u05d4\u05ea\u05e4\u05dc\u05d2\u05d5\u05ea \u05e9\u05dc \u05d4\u05ea\u05d4\u05dc\u05d9\u05da \u05d4\u05d9\u05d0 \u05d7\u05dc\u05e7 \u05de\u05d4\u05d3\u05e8\u05d9\u05e9\u05d4."],[277.0,"\u05d5\u05d1\u05d7\u05dc\u05e7 \u05d1\u05d5\u05d3\u05d3, \u05d0\u05d5 \u05d1\u05e1\u05d3\u05e8\u05d4 \u05e7\u05d8\u05e0\u05d4, RSS \u05d4\u05d5\u05d0 \u05d4\u05d9\u05de\u05d5\u05e8, \u2026)\\ Case \u05d4\u05d5\u05d0 \u05d4\u05d1\u05d7\u05d9\u05e8\u05d4 \u05d4\u05e0\u05db\u05d5\u05e0\u05d4."],[286.0,"\u05dc\u05d0 \u05e8\u05e7 \u05de\u05d9\u05d3\u05d5\u05ea \u05e0\u05db\u05e0\u05e1\u05d5\u05ea \u05dc\u05e9\u05e8\u05e9\u05e8\u05ea."],[288.0,"\u05d2\u05dd \u05e1\u05d1\u05d5\u05dc\u05d5\u05ea \u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05d5\u05ea, \u05db\u05de\u05d5 \u05de\u05d9\u05e7\u05d5\u05dd, \u05e0\u05d9\u05e6\u05d1\u05d5\u05ea \u05d0\u05d5 \u05e8\u05d9\u05e6\u05d4, \u05de\u05d6\u05d9\u05d6\u05d5\u05ea \u05de\u05e9\u05d8\u05d7\u05d9\u05dd, \u05d5\u05dc\u05db\u05df \u05d4\u05df \u05d7\u05d5\u05dc\u05d9\u05d5\u05ea \u05d1\u05dc\u05d5\u05dc\u05d0\u05d4."],[298.0,"\u05e1\u05d1\u05d5\u05dc\u05ea \u05de\u05d9\u05e7\u05d5\u05dd \u05d1\u05e7\u05d5\u05d8\u05e8 \u05e2\u05e9\u05d9\u05e8\u05d9\u05ea, \u05dc\u05de\u05e9\u05dc, \u05ea\u05d5\u05e8\u05de\u05ea \u05dc\u05e9\u05e8\u05e9\u05d5\u05e8\u05ea \u05e4\u05dc\u05d5\u05e1 \u05de\u05d9\u05e0\u05d5\u05e1 \u05d7\u05de\u05e9\u05d5 \u05de\u05d0\u05d9\u05d5\u05ea."],[304.0,"\u05de\u05d9 \u05e9\u05de\u05d7\u05e9\u05d1 \u05e9\u05e8\u05e9\u05e8\u05ea \u05e8\u05e7 \u05de\u05d4\u05de\u05d9\u05d3\u05d5\u05ea, \u05d5\u05de\u05d3\u05dc\u05d2 \u05e2\u05dc \u05d4\u05e1\u05d1\u05d5\u05dc\u05d5\u05ea \u05d4\u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05d5\u05ea, \u05de\u05e7\u05d1\u05dc \u05ea\u05d5\u05e6\u05d0\u05d4 \u05d8\u05d5\u05d1\u05d4 \u05de\u05d4\u05de\u05e6\u05d9\u05d0\u05d5\u05ea."],[313.0,"\u05db\u05d0\u05df \u05d7\u05d5\u05d6\u05e8\u05d9\u05dd \u05dc\u05e4\u05e8\u05e7 \u05d0\u05e8\u05d1\u05e2: \u05d4\u05d3\u05e8\u05da \u05e9\u05d1\u05d4 \u05d7\u05dc\u05e7 \u05de\u05de\u05d5\u05d3\u05d3 \u05e7\u05d5\u05d1\u05e2\u05ea \u05db\u05de\u05d4 \u05d7\u05d5\u05dc\u05d9\u05d5\u05ea \u05d4\u05d5\u05d0 \u05de\u05db\u05e0\u05d9\u05e1 \u05dc\u05e9\u05d5\u05e8\u05e9\u05e8\u05ea."],[321.0,"\u05d1\u05ea\u05db\u05e0\u05d5\u05df \u05d8\u05d5\u05d1, \u05db\u05dc \u05d7\u05dc\u05e7 \u05ea\u05d5\u05e8\u05dd \u05dc\u05e9\u05e8\u05e9\u05e8\u05ea \u05de\u05d9\u05d3\u05d4 \u05d0\u05d7\u05ea \u05d1\u05dc\u05d1\u05d3, \u05d4\u05de\u05d9\u05d3\u05d4 \u05e9\u05e0\u05d5\u05d2\u05e2\u05ea \u05d9\u05e9\u05d9\u05e8\u05d5\u05ea \u05d1\u05d3\u05e8\u05d9\u05e9\u05d4."],[329.0,"\u05d0\u05dd \u05d4\u05d7\u05dc\u05e7 \u05de\u05de\u05d5\u05d3\u05d3 \u05d1\u05e9\u05e8\u05e9\u05e8\u05ea \u05e4\u05e0\u05d9\u05de\u05d9\u05ea, \u05e9\u05ea\u05d9\u05d9\u05dd \u05d0\u05d5 \u05e9\u05dc\u05d5\u05e9 \u05de\u05d9\u05d3\u05d5\u05ea \u05e9\u05dc\u05d5 \u05e0\u05db\u05e0\u05e1\u05d5\u05ea \u05dc\u05dc\u05d5\u05dc\u05d0\u05d4, \u05d5\u05d4\u05e1\u05d1\u05d5\u05dc\u05ea \u05d4\u05db\u05d5\u05dc\u05dc\u05ea \u05d2\u05d3\u05dc\u05d4."],[339.0,"\u05d7\u05dc\u05e7 \u05de\u05d4\u05dc\u05d5\u05dc\u05d0\u05d4, \u05d6\u05d5 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05dc\u05d0 \u05de\u05e7\u05e8\u05d9\u05d5\u05ea. \u05d6\u05d5 \u05d4\u05de\u05d9\u05d3\u05d4 \u05d4\u05e7\u05e8\u05d9\u05d8\u05d9\u05ea."],[350.0,"\u05d5\u05d9\u05e6\u05e8\u05df \u05e9\u05de\u05de\u05d9\u05e8 \u05de\u05d9\u05d3\u05d5\u05ea \u05db\u05d0\u05dc\u05d4 \u05e2\u05dc \u05d3\u05e2\u05ea \u05e2\u05e6\u05de\u05d5, \u05de\u05e9\u05e0\u05d4 \u05d0\u05ea \u05d4\u05e9\u05e8\u05e9\u05e8\u05ea \u05e9\u05d4\u05de\u05ea\u05db\u05e0\u05df \u05d7\u05d9\u05e9\u05d1."],[357.0,"\u05de\u05d4 \u05e2\u05d5\u05e9\u05d9\u05dd \u05db\u05e9\u05d4\u05d7\u05d9\u05e9\u05d5\u05d1 \u05de\u05e8\u05d0\u05d4 \u05e9\u05d4\u05d3\u05e8\u05d9\u05e9\u05d4 \u05dc\u05d0 \u05de\u05ea\u05e7\u05d9\u05d9\u05de\u05ea?"],[361.0,"\u05d0\u05e4\u05e9\u05e8 \u05dc\u05e6\u05de\u05e6\u05dd \u05e1\u05d1\u05d5\u05dc\u05d5\u05ea, \u05d0\u05d1\u05dc \u05d6\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05db\u05dc \u05d7\u05dc\u05e7 \u05d1\u05e9\u05e8\u05e9\u05e8\u05ea."],[366.0,"\u05d0\u05e4\u05e9\u05e8 \u05dc\u05d4\u05d5\u05e1\u05d9\u05e3 \u05e8\u05db\u05d9\u05d1 \u05db\u05d9\u05d5\u05d5\u05e0\u05d5\u05df, \u05db\u05de\u05d5 \u05e4\u05d7\u05d9\u05ea \u05de\u05d9\u05dc\u05d5\u05d9 \u05d0\u05d5 \u05d3\u05d9\u05e1\u05e7\u05d9\u05ea \u05d1\u05e2\u05d5\u05d1\u05d9 \u05e0\u05d1\u05d7\u05e8, \u05e9\u05e1\u05d5\u05d2\u05e8 \u05d0\u05ea \u05d4\u05de\u05e8\u05d5\u05d5\u05d7 \u05d1\u05d4\u05e8\u05db\u05d1\u05d4."],[374.0,"\u05d5\u05d0\u05e4\u05e9\u05e8 \u05dc\u05d4\u05e9\u05ea\u05de\u05e9 \u05d1\u05d4\u05e8\u05db\u05d1\u05d4 \u05e1\u05dc\u05e7\u05d8\u05d9\u05d1\u05d9\u05ea: \u05dc\u05de\u05d9\u05d9\u05df \u05d7\u05dc\u05e7\u05d9\u05dd \u05dc\u05e1\u05d9 \u05de\u05d9\u05d3\u05d4, \u05d5\u05dc\u05d4\u05e8\u05db\u05d9\u05d1 \u05d9\u05d7\u05d3 \u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05ea\u05d0\u05d9\u05de\u05d9\u05dd."],[382.0,"\u05db\u05dc \u05e4\u05ea\u05e8\u05d5\u05df \u05db\u05d6\u05d4 \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d5\u05e4\u05d9\u05e2 \u05d1\u05de\u05e1\u05de\u05db\u05d9\u05dd, \u05db\u05d9 \u05de\u05d9 \u05e9\u05de\u05e8\u05db\u05d9\u05d1 \u05e6\u05e8\u05d9\u05da \u05dc\u05d3\u05e2\u05ea \u05e9\u05d4\u05d5\u05d0 \u05d7\u05dc\u05e7 \u05de\u05d4\u05ea\u05d4\u05dc\u05d9\u05da."],[390.0,"\u05e9\u05e8\u05e9\u05e8\u05ea \u05e1\u05d1\u05d5\u05dc\u05d5\u05ea \u05d4\u05d9\u05d0 \u05dc\u05d5\u05dc\u05d0\u05d4 \u05e1\u05d2\u05d5\u05e8\u05d4 \u05e9\u05dc \u05de\u05d9\u05d3\u05d5\u05ea \u05e1\u05d1\u05d9\u05d1 \u05d3\u05e8\u05d9\u05e9\u05d4 \u05d0\u05d7\u05ea, \u05d4\u05d7\u05d5\u05dc\u05d9\u05d4 \u05d4\u05e1\u05d5\u05d2\u05e8\u05ea."],[397.0,"Worst Case \u05de\u05d7\u05d1\u05e8 \u05d0\u05ea \u05db\u05dc \u05d4\u05e1\u05d1\u05d5\u05dc\u05d5\u05ea, \u05d5\u05de\u05d1\u05d8\u05d9\u05d7 \u05d4\u05e8\u05db\u05d1\u05d4 \u05d1\u05db\u05dc \u05e6\u05d9\u05e8\u05d5\u05e3."],[402.0,"5 \u05de\u05d7\u05d1\u05e8 \u05d0\u05ea \u05d4\u05e8\u05d9\u05d1\u05d5\u05e2\u05d9\u05dd, \u05e0\u05d5\u05ea\u05df \u05ea\u05d5\u05e6\u05d0\u05d4 \u05e6\u05e8\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05d5\u05d3\u05d5\u05e8\u05e9 \u05ea\u05d4\u05dc\u05d9\u05db\u05d9\u05dd \u05d9\u05e6\u05d9\u05d1\u05d9\u05dd, \u05d5\u05dc\u05db\u05df \u05de\u05e1\u05d5\u05de\u05df \u05d1-51."],[412.0,"\u05e1\u05d1\u05d5\u05dc\u05d5\u05ea \u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05d5\u05ea \u05d4\u05df \u05d7\u05dc\u05e7 \u05de\u05d4\u05e9\u05d5\u05e8\u05e9\u05e8\u05ea, \u05d5\u05d4\u05de\u05d9\u05d3\u05d4 \u05d4\u05d9\u05e9\u05d9\u05e8\u05d4 \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d4\u05d9\u05d0 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d4\u05de\u05d9\u05d3\u05d4 \u05d4\u05e7\u05e8\u05d9\u05d8\u05d9\u05ea."],[420.0,"\u05d4\u05d7\u05dc\u05e7 \u05d4\u05e9\u05dc\u05d9\u05e9\u05d9: \u05e1\u05d1\u05d5\u05dc\u05d5\u05ea \u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05d5\u05ea \u05d1\u05ea\u05d5\u05da \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8, \u05d3\u05e8\u05da \u05de\u05e2\u05e8\u05db\u05ea \u05d4\u05de\u05e9\u05d8\u05d7\u05d9\u05dd. \u05e0\u05ea\u05e8\u05d0\u05d4 \u05d1\u05e4\u05e8\u05e7 \u05ea\u05e9\u05e2."]]};
window.MH_TR["ch09"]={"t":"\u05de\u05e2\u05e8\u05db\u05ea \u05d4\u05de\u05e9\u05d8\u05d7\u05d9\u05dd","l":[[1.0,"\u05d1\u05d7\u05dc\u05e7 \u05d4\u05e9\u05dc\u05d9\u05e9\u05d9 \u05e9\u05dc \u05d4\u05e7\u05d5\u05e8\u05e1 \u05e0\u05e7\u05e8\u05d0 \u05e1\u05d1\u05d5\u05dc\u05d5\u05ea \u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05d5\u05ea \u05d1\u05ea\u05d5\u05da \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8, \u05d5\u05dc\u05d0 \u05db\u05dc \u05e1\u05de\u05dc \u05dc\u05d1\u05d3."],[9.0,"\u05d5\u05d0\u05ea \u05d6\u05d4 \u05de\u05ea\u05d7\u05d9\u05dc\u05d9\u05dd \u05de\u05de\u05e2\u05e8\u05db\u05ea \u05d4\u05de\u05e9\u05d8\u05d7\u05d9\u05dd, \u05db\u05d9 \u05db\u05dc \u05e1\u05d1\u05d5\u05dc\u05ea \u05de\u05d9\u05e7\u05d5\u05dd \u05d0\u05d5 \u05db\u05d9\u05d5\u05d5\u05df \u05e0\u05de\u05d3\u05d3\u05ea \u05d1\u05d9\u05d7\u05e1 \u05d0\u05dc\u05d9\u05d4."],[17.0,"\u05db\u05e9\u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5, \u05d5\u05d4\u05d9\u05d0 \u05d2\u05dd \u05d4\u05d4\u05e6\u05d4\u05e8\u05d4 \u05e9\u05dc \u05d4\u05de\u05ea\u05db\u05e0\u05df \u05d0\u05d9\u05da \u05d4\u05d7\u05dc\u05e7 \u05d9\u05d5\u05e9\u05d1 \u05d1\u05d4\u05e8\u05db\u05d1\u05d4."],[27.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05dc\u05de\u05d3 \u05dc\u05e7\u05e8\u05d5\u05d0 \u05d0\u05d5\u05ea\u05d4: \u05de\u05d4 \u05db\u05dc \u05d0\u05d5\u05ea \u05d0\u05d5\u05de\u05e8\u05ea, \u05dc\u05de\u05d4 \u05d4\u05e1\u05d3\u05e8 \u05d7\u05e9\u05d5\u05d1, \u05d5\u05de\u05d4 \u05d4\u05d9\u05d0 \u05de\u05d2\u05dc\u05d4 \u05e2\u05dc \u05d4\u05e4\u05d5\u05e0\u05e7\u05e6\u05d9\u05d4."],[36.0,"\u05d7\u05dc\u05e7 \u05e9\u05de\u05d5\u05e0\u05d7 \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8 \u05d9\u05db\u05d5\u05dc \u05dc\u05d6\u05d5\u05d6 \u05d1\u05e9\u05e9 \u05d3\u05e8\u05db\u05d9\u05dd: \u05e9\u05dc\u05d5\u05e9 \u05ea\u05e0\u05d5\u05e2\u05d5\u05ea \u05dc\u05d0\u05d5\u05e8\u05da \u05d4\u05e6\u05d9\u05e8\u05d9\u05dd, \u05d5\u05e9\u05dc\u05d5\u05e9\u05d4 \u05e1\u05d9\u05d1\u05d5\u05d1\u05d9\u05dd \u05e1\u05d1\u05d9\u05d1\u05dd."],[45.0,"\u05d0\u05dc\u05d4 \u05e9\u05e9 \u05d3\u05e8\u05d2\u05d5\u05ea \u05d4\u05d7\u05d5\u05e4\u05e9\u05d5 \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7."],[48.0,"\u05db\u05da \u05e9\u05d0\u05e3 \u05d0\u05d7\u05ea \u05de\u05d4\u05d3\u05e8\u05d2\u05d5\u05ea \u05d4\u05d0\u05dc\u05d4 \u05dc\u05d0 \u05ea\u05e9\u05d5\u05ea\u05e0\u05d4 \u05d1\u05d6\u05de\u05df \u05d4\u05de\u05d3\u05d9\u05d3\u05d4."],[57.0,"\u05de\u05e2\u05e8\u05db\u05ea \u05d4\u05de\u05e9\u05d5\u05d8\u05d7\u05d9\u05dd \u05e2\u05d5\u05e9\u05d4 \u05d1\u05d3\u05d9\u05d5\u05e7 \u05d0\u05ea \u05d6\u05d4: \u05d4\u05d9\u05d0 \u05e7\u05d5\u05d1\u05e2\u05ea \u05d0\u05d9\u05dc\u05d5 \u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05d1\u05d7\u05dc\u05e7 \u05e0\u05d5\u05e2\u05dc\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5, \u05d5\u05d1\u05d0\u05d9\u05d6\u05d4 \u05e1\u05d3\u05e8."],[65.0,"\u05d1\u05dc\u05d9 \u05de\u05e2\u05e8\u05db\u05ea \u05de\u05e9\u05d8\u05d7\u05d9\u05dd, \u05e1\u05d1\u05d5\u05dc\u05ea \u05de\u05d9\u05e7\u05d5\u05dd \u05d4\u05d9\u05d0 \u05de\u05e1\u05e4\u05e8 \u05d1\u05dc\u05d9 \u05e0\u05e7\u05d5\u05d3\u05ea \u05d4\u05ea\u05d7\u05dc\u05d4."],[71.0,"\u05d5\u05dc\u05db\u05df \u05de\u05e1\u05d2\u05e8\u05ea \u05e1\u05d1\u05d5\u05dc\u05ea \u05e9\u05d0\u05d9\u05df \u05d1\u05d4 \u05d0\u05d5\u05ea\u05d9\u05d5\u05ea \u05e9\u05dc \u05de\u05e9\u05d8\u05d7\u05d9\u05dd, \u05de\u05d2\u05d1\u05d9\u05dc\u05d4 \u05e8\u05e7 \u05e6\u05d5\u05e8\u05d4, \u05d5\u05dc\u05d0 \u05de\u05d9\u05e7\u05d5\u05dd."],[79.0,"\u05d4\u05d0\u05d5\u05ea \u05d4\u05e8\u05d0\u05e9\u05d5\u05e0\u05d4 \u05d1\u05de\u05e1\u05d2\u05e8\u05ea \u05d4\u05d9\u05d0 \u05d4\u05de\u05e9\u05d8\u05d7 \u05d4\u05e8\u05d0\u05e9\u05d9."],[83.0,"\u05d4\u05d7\u05dc\u05e7 \u05de\u05d5\u05e0\u05d7 \u05e2\u05dc\u05d9\u05d5, \u05d5\u05d4\u05d5\u05d0 \u05e0\u05d5\u05d2\u05e2 \u05dc\u05e4\u05d7\u05d5\u05ea \u05d1\u05e9\u05dc\u05d5\u05e9 \u05e0\u05e7\u05d5\u05d3\u05d5\u05ea. \u05db\u05da \u05e0\u05e0\u05e2\u05dc\u05d5\u05ea \u05e9\u05dc\u05d5\u05e9 \u05d3\u05e8\u05d2\u05d5\u05ea \u05d7\u05d5\u05e4\u05e9\u05d5: \u05ea\u05e0\u05d5\u05e2\u05d4 \u05d0\u05d7\u05ea \u05d5\u05e9\u05e0\u05d9 \u05e1\u05d9\u05d1\u05d5\u05d1\u05d9\u05dd."],[93.0,"\u05d4\u05d0\u05d5\u05ea \u05d4\u05e9\u05d5\u05e0\u05d9\u05d9\u05d4 \u05d4\u05d9\u05d0 \u05d4\u05de\u05e9\u05d8\u05d7 \u05d4\u05de\u05e9\u05e0\u05d9. \u05d4\u05d7\u05dc\u05e7 \u05e0\u05e6\u05de\u05d3 \u05d0\u05dc\u05d9\u05d5 \u05d1\u05e9\u05ea\u05d9 \u05e0\u05e7\u05d5\u05d3\u05d5\u05ea \u05dc\u05e4\u05d7\u05d5\u05ea, \u05d5\u05e2\u05d5\u05d3 \u05e9\u05ea\u05d9 \u05d3\u05e8\u05d2\u05d5\u05ea \u05e0\u05e0\u05e2\u05dc\u05d5\u05ea."],[102.0,"\u05d4\u05d0\u05d5\u05ea \u05d4\u05e9\u05dc\u05d9\u05e9\u05d9\u05ea \u05d4\u05d9\u05d0 \u05d4\u05de\u05e9\u05d8\u05d7 \u05d4\u05e9\u05dc\u05d9\u05e9\u05d5\u05e0\u05d9. \u05e0\u05e7\u05d5\u05d3\u05d4 \u05d0\u05d7\u05ea \u05de\u05e1\u05e4\u05d9\u05e7\u05d4, \u05d5\u05d4\u05d9\u05d0 \u05e0\u05d5\u05e2\u05dc\u05ea \u05d0\u05ea \u05d4\u05d3\u05e8\u05d2\u05d4 \u05d4\u05d0\u05d7\u05e8\u05d5\u05e0\u05d4."],[110.0,"\u05e9\u05dc\u05d5\u05e9, \u05e9\u05ea\u05d9\u05d9\u05dd, \u05d0\u05d7\u05ea: \u05d6\u05d4 \u05d4\u05e2\u05d9\u05e7\u05e8\u05d5\u05df \u05e9\u05e2\u05dc\u05d9\u05d5 \u05d1\u05e0\u05d5\u05d9\u05d4 \u05db\u05dc \u05de\u05e2\u05e8\u05db\u05ea \u05de\u05e9\u05d8\u05d7\u05d9\u05dd."],[117.0,"\u05d1\u05d1\u05d3\u05d9\u05e7\u05d4 \u05d6\u05d4 \u05e0\u05e8\u05d0\u05d4 \u05db\u05da: \u05de\u05e0\u05d9\u05d7\u05d9\u05dd \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05e2\u05dc \u05e9\u05d5\u05dc\u05d7\u05df \u05d4\u05de\u05d3\u05d9\u05d3\u05d4, \u05de\u05e6\u05de\u05d9\u05d3\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05dc\u05d6\u05d5\u05d5\u05d9\u05ea, \u05d5\u05dc\u05d5\u05d7\u05e6\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05dc\u05e2\u05e6\u05d9\u05e8\u05d4."],[126.0,"\u05d5\u05d4\u05de\u05d3\u05d9\u05d3\u05d4 \u05e2\u05e6\u05de\u05d4 \u05e0\u05e2\u05e9\u05d9\u05ea \u05de\u05de\u05e2\u05e8\u05db\u05ea \u05d4\u05e6\u05d9\u05e8\u05d9\u05dd \u05e9\u05e0\u05d5\u05e6\u05e8\u05d4, \u05d5\u05dc\u05d0 \u05de\u05d4\u05e7\u05e6\u05d5\u05d5\u05ea \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7."],[133.0,"\u05d4\u05e1\u05d3\u05e8 \u05e9\u05dc \u05d4\u05d0\u05d5\u05ea\u05d9\u05d5\u05ea \u05d4\u05d5\u05d0 \u05dc\u05d0 \u05e2\u05e0\u05d9\u05d9\u05df \u05e9\u05dc \u05e0\u05d5\u05d7\u05d5\u05ea."],[137.0,"\u05d0\u05dd \u05d4\u05de\u05e9\u05d8\u05d7 \u05d4\u05e8\u05d0\u05e9\u05d9 \u05d4\u05d5\u05d0 A, \u05d4\u05d7\u05dc\u05e7 \u05d9\u05d5\u05e9\u05d1 \u05e2\u05dc / \u05d1\u05de\u05dc\u05d5\u05d0\u05d5, \u05d5\u05e8\u05e7 \u05d0\u05d7\u05e8 \u05db\u05da \u05e0\u05e6\u05de\u05d3 B-7."],[144.0,"\u05d0\u05dd \u05d4\u05de\u05e9\u05d8\u05d7 \u05d4\u05e8\u05d0\u05e9\u05d9 \u05d4\u05d5\u05d0 \u05dd, \u05d4\u05d7\u05dc\u05e7 \u05d9\u05d5\u05e9\u05d1 \u05e2\u05dc \u05dd, \u05d5\u05de\u05e9\u05d8\u05d7 \u05d0 \u05de\u05ea\u05d9\u05d9\u05e9\u05e8\u05e8\u05e7 \u05db\u05de\u05d4 \u05e9\u05d0\u05e4\u05e9\u05e8."],[152.0,"\u05e9\u05e0\u05d9 \u05d4\u05e1\u05d3\u05e8\u05d9\u05dd \u05e0\u05d5\u05ea\u05e0\u05d9\u05dd \u05de\u05e2\u05e8\u05db\u05d5\u05ea \u05e6\u05d9\u05e8\u05d9\u05dd \u05e9\u05d5\u05e0\u05d5\u05ea, \u05d5\u05dc\u05db\u05df \u05ea\u05d5\u05e6\u05d0\u05d5\u05ea \u05e9\u05d5\u05e0\u05d5\u05ea."],[162.0,"\u05e7\u05d3\u05d7 \u05d9\u05db\u05d5\u05dc \u05dc\u05e2\u05d1\u05d5\u05e8 \u05d0\u05ea \u05d4\u05d1\u05d3\u05d9\u05e7\u05d4 \u05d1\u05e1\u05d3\u05e8 \u05d0\u05d7\u05d3, \u05d5\u05dc\u05d4\u05d9\u05db\u05e9\u05dc \u05d1\u05e1\u05d3\u05e8 \u05d4\u05e9\u05e0\u05d9."],[167.0,"\u05dc\u05db\u05df \u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05d0\u05ea \u05d4\u05d0\u05d5\u05ea\u05d9\u05d5\u05ea \u05de\u05e9\u05de\u05d0\u05dc \u05dc\u05d9\u05de\u05d9\u05df, \u05d1\u05d3\u05d9\u05d5\u05e7 \u05d1\u05e1\u05d3\u05e8 \u05e9\u05d1\u05d5 \u05d4\u05df \u05db\u05ea\u05d5\u05d1\u05d5\u05ea, \u05d5\u05dc\u05d0 \u05de\u05e9\u05e0\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5."],[175.0,"\u05d9\u05e9 \u05e9\u05dc\u05d5\u05e9\u05d4 \u05de\u05d5\u05e9\u05d2\u05d9\u05dd \u05e9\u05db\u05d3\u05d0\u05d9 \u05dc\u05d4\u05e4\u05e8\u05d9\u05d3 \u05d1\u05d9\u05e0\u05d9\u05d4\u05dd."],[178.0,"\u05d4\u05de\u05e9\u05d8\u05d7 \u05d1\u05d7\u05dc\u05e7 \u05d4\u05d5\u05d0 \u05d4\u05de\u05e9\u05d8\u05d7 \u05d4\u05d0\u05de\u05d9\u05ea\u05d9, \u05e2\u05dd \u05db\u05dc \u05d4\u05d0\u05d9 \u05e1\u05d3\u05d9\u05e8\u05d5\u05ea \u05e9\u05dc\u05d5. \u05e2\u05dc\u05d9\u05d5 \u05de\u05e1\u05d5\u05de\u05df \u05de\u05e9\u05d5\u05dc\u05e9 \u05e2\u05dd \u05d4\u05d0\u05d5\u05ea."],[187.0,"\u05d4\u05de\u05e9\u05d8\u05d7 \u05d4\u05ea\u05d0\u05d5\u05e8\u05d8\u05d9 \u05d4\u05d5\u05d0 \u05de\u05d9\u05e9\u05d5\u05e8 \u05de\u05d5\u05e9\u05dc\u05dd, \u05d0\u05d5 \u05e6\u05d9\u05e8 \u05de\u05d5\u05e9\u05dc\u05dd, \u05e9\u05de\u05de\u05e0\u05d5 \u05de\u05d5\u05d3\u05d3\u05d9\u05dd."],[193.0,"\u05d5\u05d1\u05d9\u05df \u05e9\u05e0\u05d9\u05d4\u05dd \u05e2\u05d5\u05de\u05d3 \u05d4\u05de\u05d3\u05de\u05d4: \u05e9\u05d5\u05dc\u05d7\u05df \u05d4\u05de\u05d3\u05d9\u05d3\u05d4, \u05d4\u05d6\u05d5\u05d5\u05d9\u05ea \u05d0\u05d5 \u05d4\u05e4\u05d9\u05df \u05d4\u05de\u05d3\u05d5\u05d9\u05e7, \u05e9\u05e0\u05d5\u05d2\u05e2\u05d9\u05dd \u05d1\u05d7\u05dc\u05e7 \u05d1\u05e4\u05d5\u05e2\u05dc."],[202.0,"\u05d4\u05de\u05d3\u05d9\u05d3\u05d4 \u05e0\u05e2\u05e9\u05d9\u05ea \u05de\u05d4\u05de\u05d3\u05de\u05d4, \u05db\u05d9 \u05d4\u05d5\u05d0 \u05de\u05d4 \u05e9\u05d4\u05d7\u05dc\u05e7 \u05e4\u05d5\u05d2\u05e9 \u05d1\u05d0\u05de\u05ea, \u05d2\u05dd \u05d1\u05d1\u05d3\u05d9\u05e7\u05d4 \u05d5\u05d2\u05dd \u05d1\u05d4\u05e8\u05db\u05d1\u05d4."],[210.0,"\u05d5\u05dc\u05db\u05df \u05de\u05e9\u05d8\u05d7 \u05de\u05d7\u05d5\u05e1\u05e4\u05e1 \u05d0\u05d5 \u05dc\u05d0 \u05d9\u05e6\u05d9\u05d1, \u05e9\u05e0\u05d1\u05d7\u05e8 \u05db\u05de\u05e9\u05d8\u05d7 \u05e8\u05d0\u05e9\u05d9 \u05d9\u05d1\u05d9\u05d0 \u05dc\u05ea\u05d5\u05e6\u05d0\u05d5\u05ea \u05e9\u05de\u05e9\u05ea\u05e0\u05d5\u05ea \u05de\u05d1\u05d3\u05d9\u05e7\u05d4 \u05dc\u05d1\u05d3\u05d9\u05e7\u05d4."],[219.0,"\u05de\u05e2\u05e8\u05db\u05ea \u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05d8\u05d5\u05d1\u05d4 \u05de\u05e9\u05e7\u05e4\u05ea \u05d0\u05ea \u05d4\u05d4\u05e8\u05db\u05d1\u05d4."],[223.0,"\u05d4\u05de\u05e9\u05d8\u05d7 \u05d4\u05e8\u05d0\u05e9\u05d9 \u05d4\u05d5\u05d0 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d4\u05de\u05e9\u05d8\u05d7 \u05e9\u05d4\u05d7\u05dc\u05e7 \u05d9\u05d5\u05e9\u05d1 \u05e2\u05dc\u05d9\u05d5 \u05d1\u05d4\u05e8\u05db\u05d1\u05d4, \u05d4\u05de\u05e9\u05d8\u05d7 \u05d4\u05d2\u05d3\u05d5\u05dc \u05d5\u05d4\u05d9\u05e6\u05d9\u05d1 \u05d1\u05d9\u05d5\u05ea\u05e8."],[232.0,"\u05d4\u05de\u05e9\u05e0\u05d9 \u05d5\u05d4\u05e9\u05dc\u05d9\u05e9\u05d5\u05e0\u05d9 \u05d4\u05dd \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d4\u05d0\u05dc\u05de\u05e0\u05d8\u05d9\u05dd \u05e9\u05de\u05de\u05e7\u05de\u05d9\u05dd \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7: \u05e7\u05d3\u05d7 \u05de\u05e8\u05db\u05d6\u05d9, \u05e4\u05d9\u05df, \u05d0\u05d5 \u05d3\u05d5\u05e4\u05df \u05e9\u05e0\u05e6\u05de\u05d3\u05ea."],[242.0,"\u05db\u05e9\u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05e9\u05e8\u05d8\u05d5\u05d8, \u05e9\u05d5\u05d0\u05dc\u05d9\u05dd: \u05d4\u05d0\u05dd \u05d4\u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05e9\u05e0\u05d1\u05d7\u05e8\u05d5 \u05d4\u05dd \u05d4\u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05e9\u05d1\u05d0\u05de\u05ea \u05e0\u05d5\u05d2\u05e2\u05d9\u05dd \u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05d4\u05d0\u05d7\u05e8\u05d9\u05dd?"],[250.0,"\u05d0\u05dd \u05db\u05df, \u05d4\u05d1\u05d3\u05d9\u05e7\u05d4 \u05ea\u05d3\u05de\u05d4 \u05d0\u05ea \u05d4\u05d4\u05e8\u05db\u05d1\u05d4. \u05d0\u05dd \u05dc\u05d0, \u05d7\u05dc\u05e7 \u05e9\u05e2\u05d5\u05d1\u05e8 \u05d1\u05d3\u05d9\u05e7\u05d4 \u05e2\u05dc\u05d5\u05dc \u05dc\u05d0 \u05dc\u05d4\u05ea\u05d0\u05d9\u05dd \u05d1\u05d4\u05e8\u05db\u05d1\u05d4."],[258.0,"\u05d5\u05db\u05e9\u05de\u05e2\u05e8\u05db\u05ea \u05d4\u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05dc\u05d0 \u05e0\u05e8\u05d0\u05d9\u05ea \u05e4\u05d5\u05e0\u05e7\u05e6\u05d9\u05d5\u05e0\u05dc\u05d9\u05ea, \u05d6\u05d5 \u05e1\u05d9\u05d1\u05d4 \u05dc\u05e9\u05d0\u05d5\u05dc \u05d0\u05ea \u05d4\u05de\u05ea\u05db\u05e0\u05df, \u05d5\u05dc\u05d0 \u05dc\u05e9\u05e0\u05d5\u05ea \u05d0\u05d5\u05ea\u05d4."],[265.0,"\u05d1\u05d7\u05dc\u05e7 \u05d9\u05e6\u05d5\u05e7 \u05d0\u05d5 \u05de\u05d7\u05d5\u05e9\u05dc, \u05d4\u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05d4\u05d2\u05d5\u05dc\u05de\u05d9\u05d9\u05dd \u05dc\u05d0 \u05de\u05e1\u05e4\u05d9\u05e7 \u05d9\u05e9\u05e8\u05d9\u05dd \u05db\u05d3\u05d9 \u05dc\u05e9\u05de\u05e9 \u05de\u05e9\u05d8\u05d7 \u05e9\u05dc\u05dd."],[273.0,"\u05dc\u05db\u05df \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05e0\u05e7\u05d5\u05d3\u05d5\u05ea \u05d9\u05d9\u05d7\u05d5\u05e1: \u05e0\u05e7\u05d5\u05d3\u05d5\u05ea, \u05e7\u05d5\u05d5\u05d9\u05dd \u05d0\u05d5 \u05d0\u05d6\u05d5\u05e8\u05d9\u05dd \u05e7\u05d8\u05e0\u05d9\u05dd, \u05e9\u05de\u05d5\u05d2\u05d3\u05e8\u05d9\u05dd \u05e2\u05dc \u05d4\u05de\u05e9\u05d8\u05d7."],[281.0,"\u05d4\u05df \u05de\u05e1\u05d5\u05de\u05e0\u05d5\u05ea \u05d1\u05e2\u05d9\u05d2\u05d5\u05dc \u05e9\u05de\u05d7\u05d5\u05dc\u05e7 \u05dc\u05e9\u05e0\u05d9\u05d9\u05dd: \u05dc\u05de\u05e2\u05dc\u05d4 \u05d2\u05d5\u05d3\u05dc \u05d4\u05d0\u05d6\u05d5\u05e8, \u05d5\u05dc\u05de\u05d8\u05d4 \u05d4\u05d0\u05d5\u05ea \u05d5\u05d4\u05de\u05e1\u05e4\u05e8, \u05dc\u05de\u05e9\u05dc Al"],[292.0,"\u05e9\u05dc\u05d5\u05e9 \u05e0\u05e7\u05d5\u05d3\u05d5\u05ea \u05de\u05d2\u05d3\u05d9\u05e8\u05d5\u05ea \u05d0\u05ea \u05d4\u05de\u05e9\u05d8\u05d7 \u05d4\u05e8\u05d0\u05e9\u05d9, \u05e9\u05ea\u05d9\u05d9\u05dd \u05d0\u05ea \u05d4\u05de\u05e9\u05e0\u05d9, \u05d5\u05d0\u05d7\u05ea \u05d0\u05ea \u05d4\u05e9\u05dc\u05d9\u05e9\u05d5\u05e0\u05d9, \u05d1\u05d3\u05d9\u05d5\u05e7 \u05db\u05de\u05d5 \u05e7\u05d5\u05d3\u05dd."],[301.0,"\u05d5\u05db\u05da \u05d2\u05dd \u05d4\u05d7\u05dc\u05e7 \u05d4\u05d2\u05d5\u05dc\u05de\u05d9 \u05d4\u05e8\u05d0\u05e9\u05d5\u05df \u05d5\u05d2\u05dd \u05d4\u05d7\u05dc\u05e7 \u05d4\u05de\u05e2\u05d5\u05d1\u05d3 \u05e0\u05d1\u05d3\u05e7\u05d9\u05dd \u05de\u05d0\u05d5\u05ea\u05df \u05e0\u05e7\u05d5\u05d3\u05d5\u05ea, \u05d5\u05d4\u05de\u05e2\u05d1\u05e8 \u05d1\u05d9\u05df \u05d4\u05ea\u05d4\u05dc\u05d9\u05db\u05d9\u05dd \u05e0\u05e9\u05de\u05e8."],[311.0,"\u05de\u05e9\u05d8\u05d7 \u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05d9\u05d5\u05ea \u05d2\u05dd \u05d0\u05dc\u05de\u05e0\u05d8 \u05e2\u05dd \u05de\u05d9\u05d3\u05d4, \u05db\u05de\u05d5 \u05e7\u05d3\u05d7 \u05d0\u05d5 \u05e6\u05d9\u05e8."],[317.0,"\u05d0\u05d6 \u05d4\u05de\u05d3\u05de\u05d4 \u05d4\u05d5\u05d0 \u05e4\u05d9\u05df \u05d0\u05d5 \u05d8\u05d1\u05e2\u05ea, \u05d5\u05d4\u05de\u05e9\u05d8\u05d7 \u05d4\u05ea\u05d0\u05d5\u05e8\u05d8\u05d9 \u05d4\u05d5\u05d0 \u05d4\u05e6\u05d9\u05e8 \u05e9\u05dc\u05d4\u05dd."],[323.0,"\u05db\u05e9\u05dc\u05d9\u05d3 \u05d4\u05d0\u05d5\u05ea \u05d1\u05de\u05e1\u05d2\u05e8\u05ea \u05d0\u05d9\u05df \u05e1\u05d9\u05de\u05df, \u05d4\u05de\u05d3\u05de\u05d4 \u05de\u05ea\u05d0\u05d9\u05dd \u05d0\u05ea \u05e2\u05e6\u05de\u05d5 \u05dc\u05d2\u05d5\u05d3\u05dc \u05d4\u05e7\u05d3\u05d7 \u05d1\u05e4\u05d5\u05e2\u05dc, \u05d5\u05d0\u05d9\u05df \u05de\u05e9\u05d7\u05e7."],[331.0,"\u05db\u05e9\u05dc\u05d9\u05d3 \u05d4\u05d0\u05d5\u05ea \u05de\u05d5\u05e4\u05d9\u05e2 \u05d5\u05d0 \u05d1\u05e2\u05d9\u05d2\u05d5\u05dc, \u05d4\u05de\u05d3\u05de\u05d4 \u05d4\u05d5\u05d0 \u05e4\u05d9\u05df \u05d1\u05d2\u05d5\u05d3\u05dc \u05e7\u05d1\u05d5\u05e2, \u05dc\u05e4\u05d9 \u05d4\u05d2\u05d1\u05d5\u05dc \u05d4\u05de\u05e7\u05e1\u05d9\u05de\u05dc\u05d9 \u05e9\u05dc \u05d4\u05d7\u05d5\u05de\u05e8."],[339.0,"\u05e7\u05d3\u05d7 \u05e9\u05d2\u05d3\u05d5\u05dc \u05de\u05d4\u05d2\u05d1\u05d5\u05dc \u05d4\u05d6\u05d4 \u05de\u05e9\u05d0\u05d9\u05e8 \u05de\u05e9\u05d7\u05e7, \u05d5\u05d4\u05d7\u05dc\u05e7 \u05d9\u05db\u05d5\u05dc \u05dc\u05d6\u05d5\u05d6 \u05de\u05e2\u05d8 \u05e2\u05dc \u05d4\u05e4\u05d9\u05df. \u05d6\u05d4 \u05e0\u05e7\u05e8\u05d0 \u05d4\u05d6\u05d6\u05ea \u05de\u05e9\u05d8\u05d7, \u05d5\u05d4\u05d9\u05d0 \u05de\u05d5\u05ea\u05e8\u05ea."],[349.0,"\u05d6\u05d4 \u05d1\u05d3\u05d9\u05d5\u05e7 \u05de\u05d4 \u05e9\u05e7\u05d5\u05e8\u05d4 \u05d1\u05d4\u05e8\u05db\u05d1\u05d4 \u05e2\u05dd \u05e4\u05d9\u05df, \u05d5\u05dc\u05db\u05df \u05d6\u05d4 \u05d2\u05dd \u05de\u05e7\u05dc \u05e2\u05dc \u05d4\u05d9\u05d9\u05e6\u05d5\u05e8, \u05d1\u05dc\u05d9 \u05dc\u05e4\u05d2\u05d5\u05e2 \u05d1\u05e4\u05d5\u05e0\u05e7\u05e6\u05d9\u05d4."],[357.0,"\u05db\u05e9\u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05de\u05e1\u05d2\u05e8\u05ea \u05e1\u05d1\u05d5\u05dc\u05ea, \u05d0\u05e4\u05e9\u05e8 \u05dc\u05e9\u05d7\u05d6\u05e8 \u05de\u05de\u05e0\u05d4 \u05d0\u05ea \u05db\u05dc \u05d4\u05d1\u05d3\u05d9\u05e7\u05d4."],[362.0,"\u05d4\u05d0\u05d5\u05ea\u05d9\u05d5\u05ea \u05d0\u05d5\u05de\u05e8\u05d5\u05ea \u05e2\u05dc \u05de\u05d4 \u05de\u05e0\u05d9\u05d7\u05d9\u05dd \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05d5\u05d1\u05d0\u05d9\u05d6\u05d4 \u05e1\u05d3\u05e8, \u05d5\u05d4\u05de\u05d5\u05d3\u05d9\u05e4\u05d9\u05d9\u05e8\u05d9\u05dd \u05d0\u05d5\u05de\u05e8\u05d9\u05dd \u05d0\u05dd\u05d9\u05e9 \u05de\u05e9\u05d7\u05e7."],[369.0,"\u05de\u05e2\u05e8\u05db\u05ea, \u05db\u05e9\u05de\u05e1\u05d2\u05e8\u05d5\u05ea \u05e9\u05e9\u05d5\u05e0\u05d5\u05ea \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05de\u05e4\u05e0\u05d5\u05ea \u05dc\u05de\u05e2\u05e8\u05db\u05d5\u05ea \u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05e9\u05d5\u05e0\u05d5\u05ea."],[379.0,"\u05de\u05dc\u05db\u05d5\u05d3\u05ea \u05d0\u05d7\u05e8\u05ea \u05d4\u05d9\u05d0 \u05dc\u05e7\u05d1\u05e2 \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05dc\u05d9\u05d9\u05e6\u05d5\u05e8 \u05dc\u05e4\u05d9 \u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05d0\u05d7\u05e8\u05d9\u05dd, \u05d5\u05d0\u05d6 \u05dc\u05d4\u05e4\u05ea\u05d9\u05e2 \u05d1\u05d1\u05d3\u05d9\u05e7\u05d4."],[386.0,"\u05de\u05d5\u05ea\u05e8 \u05dc\u05d9\u05d9\u05e6\u05e8 \u05d1\u05db\u05dc \u05e7\u05d9\u05d1\u05d5\u05e2, \u05d0\u05d1\u05dc \u05de\u05d9 \u05e9\u05de\u05e7\u05d1\u05e2 \u05dc\u05e4\u05d9 \u05de\u05e2\u05e8\u05db\u05ea \u05d4\u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05e9\u05dc \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8, \u05de\u05e7\u05d8\u05d9\u05df \u05d0\u05ea \u05d4\u05e1\u05d9\u05db\u05d5\u05df \u05de\u05e8\u05d0\u05e9."],[395.0,"\u05de\u05e2\u05e8\u05db\u05ea \u05d4\u05de\u05e9\u05d5\u05d8\u05d7\u05d9\u05dd \u05e0\u05d5\u05e2\u05dc\u05ea \u05d0\u05ea \u05e9\u05e9 \u05d3\u05e8\u05d2\u05d5\u05ea \u05d4\u05d7\u05d5\u05e4\u05e2\u05d5, \u05d1\u05e9\u05d9\u05d8\u05ea \u05e9\u05dc\u05d5\u05e9, \u05e9\u05ea\u05d9\u05d9\u05dd, \u05d0\u05d7\u05ea."],[402.0,"\u05d4\u05e1\u05d3\u05e8 \u05e9\u05dc \u05d4\u05d0\u05d5\u05ea\u05d9\u05d5\u05ea \u05e7\u05d5\u05d1\u05e2 \u05d0\u05ea \u05d4\u05ea\u05d5\u05e6\u05d0\u05d4, \u05d5\u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05d1\u05d3\u05d9\u05d5\u05e7 \u05db\u05e4\u05d9 \u05e9\u05d4\u05d5\u05d0 \u05db\u05ea\u05d5\u05d1."],[408.0,"\u05d4\u05de\u05d3\u05d9\u05d3\u05d4 \u05e0\u05e2\u05e9\u05e9\u05d5\u05d9\u05ea \u05de\u05d4\u05de\u05d3\u05de\u05d4, \u05d5\u05dc\u05db\u05df \u05de\u05e9\u05d8\u05d7 \u05e8\u05d0\u05e9\u05d9 \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d9\u05d5\u05ea \u05d9\u05e6\u05d9\u05d1 \u05d5\u05e4\u05d5\u05e0\u05e7\u05e6\u05d9\u05d5\u05e0\u05dc\u05d9."],[415.0,"\u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05d2\u05d5\u05dc\u05de\u05d9\u05d9\u05dd \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05e0\u05e7\u05d5\u05d3\u05d5\u05ea \u05d9\u05d9\u05d7\u05d5\u05e1, \u05d5\u05d0\u05d5\u05ea \u05e2\u05dd \u05d5\u05d0 \u05d1\u05e2\u05d9\u05d2\u05d5\u05dc \u05de\u05d0\u05e4\u05e9\u05e8\u05ea \u05d4\u05d6\u05d6\u05ea \u05de\u05e9\u05d8\u05d7."],[423.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05e9\u05dc\u05d1 \u05d0\u05ea \u05d4\u05e1\u05d1\u05d5\u05dc\u05d5\u05ea \u05d4\u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05d5\u05ea \u05e2\u05dd \u05d4\u05de\u05d9\u05d3\u05d5\u05ea, \u05d5\u05e0\u05d6\u05d4\u05d4 \u05e1\u05ea\u05d9\u05e8\u05d5\u05ea \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05e9\u05dc\u05dd. \u05e0\u05ea\u05e8\u05d0\u05d4 \u05d1\u05e4\u05e8\u05e7 \u05e2\u05e9\u05e8."]]};
window.MH_TR["ch10"]={"t":"\u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05d4 \u05d5\u05de\u05d9\u05d3\u05d5\u05ea \u05d9\u05d7\u05d3","l":[[1.0,"\u05e0\u05e7\u05e8\u05d0 \u05d0\u05d9\u05da \u05d4\u05e1\u05d1\u05d5\u05dc\u05d5\u05ea \u05d4\u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05d5\u05ea \u05d5\u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05e2\u05d5\u05d1\u05d3\u05d5\u05ea \u05d9\u05d7\u05d3, \u05d1\u05d0\u05d5\u05ea\u05d5 \u05d0\u05dc\u05de\u05e0\u05d8."],[11.0,"\u05d0\u05dc\u05de\u05e0\u05d8 \u05d0\u05d7\u05d3 \u05d9\u05db\u05d5\u05dc \u05dc\u05e7\u05d1\u05dc \u05de\u05d9\u05d3\u05d4, \u05e1\u05d1\u05d5\u05dc\u05ea \u05e6\u05d5\u05e8\u05d4, \u05e1\u05d1\u05d5\u05dc\u05ea \u05db\u05d9\u05d5\u05d5\u05df \u05d5\u05e1\u05d1\u05d5\u05dc\u05ea \u05de\u05d9\u05e7\u05d5\u05dd, \u05d5\u05db\u05d5\u05dc\u05df \u05d7\u05d9\u05d9\u05d1\u05d5\u05ea \u05dc\u05d4\u05ea\u05d0\u05d9\u05dd \u05d6\u05d5 \u05dc\u05d6\u05d5."],[21.0,"\u05db\u05e9\u05d4\u05df \u05dc\u05d0 \u05de\u05ea\u05d0\u05d9\u05de\u05d5\u05ea, \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05e1\u05d5\u05ea\u05e8 \u05d0\u05ea \u05e2\u05e6\u05de\u05d5, \u05d5\u05d0\u05d9\u05df \u05d3\u05e8\u05da \u05dc\u05d1\u05d3\u05d5\u05e7 \u05d0\u05d5\u05ea\u05d5."],[26.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05dc\u05de\u05d3 \u05dc\u05d6\u05d4\u05d5\u05ea \u05e1\u05ea\u05d9\u05e8\u05d5\u05ea \u05db\u05d0\u05dc\u05d4, \u05dc\u05e7\u05e8\u05d5\u05d0 \u05d1\u05d5\u05e0\u05d5\u05e1 \u05e9\u05dc \u05de\u05e6\u05d1 \u05d7\u05d5\u05de\u05e8, \u05d5\u05dc\u05d4\u05d1\u05d9\u05df \u05e1\u05d1\u05d5\u05dc\u05d5\u05ea \u05e9\u05dc \u05e7\u05d1\u05d5\u05e6\u05d5\u05ea \u05e7\u05d3\u05d7\u05d9\u05dd."],[36.0,"\u05dc\u05e1\u05d1\u05d5\u05dc\u05d5\u05ea \u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05d5\u05ea \u05d9\u05e9 \u05e1\u05d3\u05e8 \u05d8\u05d1\u05e2\u05d9: \u05de\u05d9\u05e7\u05d5\u05dd \u05e9\u05d5\u05dc\u05d8 \u05d2\u05dd \u05d1\u05db\u05d9\u05d5\u05d5\u05df \u05d5\u05d1\u05e6\u05d5\u05e8\u05d4, \u05d5\u05db\u05d9\u05d5\u05d5\u05df \u05e9\u05d5\u05dc\u05d8 \u05d2\u05dd \u05d1\u05e6\u05d5\u05e8\u05d4."],[45.0,"\u05e9\u05dc\u05d5, \u05d5\u05e1\u05d1\u05d5\u05dc\u05ea \u05de\u05e7\u05d1\u05d9\u05dc\u05d5\u05ea \u05e9\u05dc \u05de\u05e9\u05d8\u05d7 \u05db\u05d1\u05e8 \u05de\u05d2\u05d1\u05d9\u05dc\u05d4 \u05d0\u05ea \u05d4\u05e9\u05d8\u05d9\u05d7\u05d5\u05ea \u05e9\u05dc\u05d5."],[55.0,"\u05e1\u05d1\u05d5\u05dc\u05ea \u05e0\u05d5\u05e1\u05e4\u05ea \u05de\u05ea\u05d7\u05ea \u05dc\u05e1\u05d1\u05d5\u05dc\u05ea \u05e8\u05d7\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05e0\u05e7\u05e8\u05d0\u05ea \u05e2\u05d9\u05d3\u05d5\u05df. \u05d4\u05d9\u05d0 \u05d4\u05d2\u05d9\u05d5\u05e0\u05d9\u05ea \u05e8\u05e7 \u05d0\u05dd \u05d4\u05d9\u05d0 \u05e7\u05d8\u05e0\u05d4 \u05d9\u05d5\u05ea\u05e8."],[63.0,"\u05de\u05d0\u05d9\u05d5\u05ea \u05e2\u05dc \u05d0\u05d5\u05ea\u05d5 \u05de\u05e9\u05d8\u05d7: \u05d4\u05d2\u05d9\u05d5\u05e0\u05d9. \u05d4\u05e9\u05d8\u05d9\u05d7\u05d5\u05ea \u05de\u05d4\u05d5\u05d3\u05e7\u05ea \u05d1\u05ea\u05d5\u05da \u05d4\u05de\u05e7\u05d1\u05d9\u05dc\u05d5\u05ea."],[74.0,"\u05d7\u05de\u05e9 \u05de\u05d0\u05d9\u05d5\u05ea \u05dc\u05d0 \u05de\u05d5\u05e1\u05d9\u05e4\u05d4 \u05db\u05dc\u05d5\u05dd, \u05d5\u05d6\u05d4 \u05e1\u05d9\u05de\u05df \u05e9\u05de\u05e9\u05d4\u05d5 \u05dc\u05d0 \u05e0\u05d7\u05e9\u05d1."],[83.0,"\u05d5\u05db\u05da \u05d2\u05dd \u05d1\u05d2\u05d5\u05d3\u05dc: \u05dc\u05e4\u05d9 \u05e2\u05e7\u05e8\u05d5\u05df \u05d4\u05de\u05e2\u05d8\u05e4\u05ea, \u05e9\u05d8\u05d9\u05d7\u05d5\u05ea \u05d2\u05d3\u05d5\u05dc\u05d4 \u05de\u05e1\u05d1\u05d5\u05dc\u05ea \u05d4\u05e2\u05d5\u05d1\u05d9 \u05e9\u05dc \u05d0\u05d5\u05ea\u05d5 \u05d7\u05dc\u05e7 \u05d4\u05d9\u05d0 \u05d7\u05e1\u05e8\u05ea \u05de\u05e9\u05d5\u05de\u05e2\u05d5\u05ea."],[92.0,"\u05d4\u05e1\u05ea\u05d9\u05e8\u05d4 \u05d4\u05e0\u05e4\u05d5\u05e6\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8: \u05e7\u05d3\u05d7 \u05e9\u05de\u05de\u05d5\u05e7\u05dd \u05d2\u05dd \u05d1\u05de\u05d9\u05d3\u05d4 \u05e2\u05dd \u05e4\u05dc\u05d5\u05e1 \u05de\u05d9\u05e0\u05d5\u05e1, \u05d5\u05d2\u05dd \u05d1\u05e1\u05d1\u05d5\u05dc\u05ea \u05de\u05d9\u05e7\u05d5\u05dd."],[100.0,"\u05d0\u05d6 \u05d9\u05e9 \u05dc\u05d5 \u05e9\u05ea\u05d9 \u05d4\u05d2\u05d3\u05e8\u05d5\u05ea \u05de\u05d9\u05e7\u05d5\u05dd \u05e9\u05d5\u05e0\u05d5\u05ea, \u05d5\u05d0\u05d9 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d3\u05e2\u05ea \u05dc\u05e4\u05d9 \u05d0\u05d9\u05d6\u05d5 \u05dc\u05d1\u05d3\u05d5\u05e7."],[106.0,"\u05db\u05e9\u05d9\u05e9 \u05e1\u05d1\u05d5\u05dc\u05ea \u05de\u05d9\u05e7\u05d5\u05dd, \u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05e9\u05de\u05de\u05e7\u05de\u05d5\u05ea \u05d0\u05ea \u05d4\u05e7\u05d3\u05d7 \u05e6\u05e8\u05d9\u05db\u05d5\u05ea \u05dc\u05d4\u05d9\u05d5\u05ea \u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05e1\u05d9\u05e1\u05d9\u05d5\u05ea, \u05d1\u05de\u05e1\u05d2\u05e8\u05ea."],[114.0,"\u05e1\u05ea\u05d9\u05e8\u05d4 \u05d0\u05d7\u05e8\u05ea \u05d4\u05d9\u05d0 \u05e1\u05d1\u05d5\u05dc\u05ea \u05db\u05d9\u05d5\u05d5\u05df \u05d0\u05d5 \u05de\u05d9\u05e7\u05d5\u05dd \u05e9\u05de\u05e1\u05e0\u05d4 \u05dc\u05de\u05e9\u05d8\u05d7 \u05e9\u05dc\u05d0 \u05e1\u05d5\u05de\u05df \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d1\u05db\u05dc\u05dc."],[121.0,"\u05d5\u05e2\u05d5\u05d3 \u05d0\u05d7\u05ea: \u05e1\u05d1\u05d5\u05dc\u05ea \u05e9\u05de\u05e4\u05e0\u05d4 \u05dc\u05d0\u05d5\u05ea\u05d5 \u05d0\u05dc\u05de\u05e0\u05d8 \u05e9\u05d4\u05d9\u05d0 \u05d7\u05dc\u05d4 \u05e2\u05dc\u05d9\u05d5, \u05db\u05d0\u05d9\u05dc\u05d5 \u05d4\u05e7\u05d3\u05d7 \u05e0\u05de\u05d3\u05d3 \u05d1\u05d9\u05d7\u05e1 \u05dc\u05e2\u05e6\u05de\u05d5."],[130.0,"\u05d1\u05db\u05dc \u05d4\u05de\u05e7\u05e8\u05d9\u05dd \u05d4\u05d0\u05dc\u05d4 \u05dc\u05d0 \u05d1\u05d5\u05d7\u05e8\u05d9\u05dd \u05e4\u05e8\u05e9\u05e0\u05d5\u05ea. \u05e8\u05d5\u05e9\u05de\u05d9\u05dd \u05d0\u05ea \u05d4\u05e1\u05ea\u05d9\u05e8\u05d4 \u05d5\u05e9\u05d5\u05d0\u05dc\u05d9\u05dd \u05d0\u05ea \u05d4\u05de\u05ea\u05db\u05e0\u05df."],[137.0,"\u05db\u05e9\u05d4\u05e7\u05d3\u05d7 \u05d1\u05de\u05e6\u05d1 \u05d7\u05d5\u05de\u05e8 \u05de\u05e7\u05e1\u05d9\u05de\u05dc\u05d9, \u05db\u05dc\u05d5\u05de\u05e8 \u05d1\u05e7\u05d5\u05d8\u05e8 \u05d4\u05e7\u05d8\u05df \u05d1\u05d9\u05d5\u05ea\u05e8."],[148.0,"\u05db\u05db\u05dc \u05e9\u05d4\u05e7\u05d3\u05d7 \u05d1\u05e4\u05d5\u05e2\u05dc \u05d2\u05d3\u05d5\u05dc \u05d9\u05d5\u05ea\u05e8, \u05d4\u05d5\u05d0 \u05de\u05e7\u05d1\u05dc \u05ea\u05d5\u05e1\u05e4\u05ea \u05dc\u05e1\u05d1\u05d5\u05dc\u05ea, \u05d1\u05d2\u05d5\u05d3\u05dc \u05d4\u05d4\u05e4\u05e8\u05e9. \u05d6\u05d4 \u05d4\u05d1\u05d5\u05e0\u05d5\u05e1."],[156.0,"\u05e0\u05d9\u05e7\u05d7 \u05e7\u05d3\u05d7 \u05d1\u05e7\u05d5\u05d8\u05e8 \u05e2\u05e9\u05e8\u05d4, \u05d1\u05e1\u05d1\u05d5\u05dc\u05ea \u05e9\u05dc \u05e4\u05dc\u05d5\u05e1 \u05e2\u05e9\u05d9\u05e8\u05d9\u05ea, \u05e2\u05dd \u05e1\u05d1\u05d5\u05dc\u05ea \u05de\u05d9\u05e7\u05d5\u05dd \u05e9\u05dc \u05e2\u05e9\u05d9\u05e8\u05d9\u05ea \u05d5-\u05d5\u05d0 \u05d1\u05e2\u05d9\u05d2\u05d5\u05dc."],[165.0,"\u05e7\u05d3\u05d7 \u05d1\u05e7\u05d5\u05d8\u05e8 \u05e2\u05e9\u05e8\u05d4 \u05d1\u05d3\u05d9\u05d5\u05e7 \u05de\u05e7\u05d1\u05dc \u05e1\u05d1\u05d5\u05dc\u05ea \u05de\u05d9\u05e7\u05d5\u05dd \u05e9\u05dc \u05e2\u05e9\u05d9\u05e8\u05d9\u05ea. \u05e7\u05d3\u05d7 \u05d1\u05e7\u05d5\u05d8\u05e8 10.1 \u05de\u05e7\u05d1\u05dc \u05e9\u05ea\u05d9 \u05e2\u05e9\u05d9\u05e8\u05d9\u05d5\u05ea."],[175.0,"\u05dc\u05d1\u05d5\u05e8\u05d2, \u05d5\u05dc\u05db\u05df \u05d4\u05d5\u05d0 \u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05d9\u05d5\u05ea \u05e4\u05d7\u05d5\u05ea \u05de\u05d3\u05d5\u05d9\u05e7 \u05d1\u05de\u05d9\u05e7\u05d5\u05dd \u05d5\u05e2\u05d3\u05d9\u05d9\u05df \u05dc\u05d4\u05ea\u05d0\u05d9\u05dd."],[186.0,"\u05d4\u05de\u05e6\u05d1 \u05d4\u05d2\u05e8\u05d5\u05e2 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05e0\u05e7\u05e8\u05d0 \u05d4\u05de\u05e6\u05d1 \u05d4\u05d5\u05d5\u05d9\u05e8\u05d8\u05d5\u05d0\u05dc\u05d9: \u05e7\u05d5\u05d8\u05e8 \u05d4\u05e7\u05d3\u05d7 \u05d4\u05e7\u05d8\u05df \u05e4\u05d7\u05d5\u05ea \u05e1\u05d1\u05d5\u05dc\u05ea \u05d4\u05de\u05d9\u05e7\u05d5\u05dd. \u05db\u05d0\u05df \u05d6\u05d4 9.9."],[197.0,"\u05d5\u05d6\u05d4 \u05d1\u05d3\u05d9\u05d5\u05e7 \u05d4\u05e7\u05d5\u05d8\u05e8 \u05e9\u05dc \u05e4\u05d9\u05df \u05d4\u05de\u05d3 \u05d4\u05e4\u05d5\u05e0\u05e7\u05e6\u05d9\u05d5\u05e0\u05dc\u05d9. \u05d0\u05dd \u05d4\u05e4\u05d9\u05df \u05e0\u05db\u05e0\u05e1 \u05d1\u05db\u05dc \u05d4\u05e7\u05d3\u05d7\u05d9\u05dd, \u05d4\u05d7\u05dc\u05e7 \u05ea\u05e7\u05d9\u05df."],[205.0,"L \u05d1\u05e2\u05d9\u05d2\u05d5\u05dc \u05e2\u05d5\u05d1\u05d3 \u05d1\u05d0\u05d5\u05ea\u05d5 \u05d0\u05d5\u05e4\u05df, \u05d0\u05d1\u05dc \u05d4\u05e4\u05d5\u05da: \u05d4\u05e1\u05d1\u05d5\u05dc\u05ea \u05d7\u05dc\u05d4 \u05db\u05e9\u05d4\u05d7\u05d5\u05de\u05e8 \u05de\u05d9\u05e0\u05d9\u05de\u05dc\u05d9, \u05d5\u05d4\u05d1\u05d5\u05e0\u05d5\u05e1 \u05d2\u05d3\u05dc \u05db\u05db\u05dc \u05e9\u05d9\u05e9 \u05d9\u05d5\u05ea\u05e8 \u05d7\u05d5\u05de\u05e8."],[215.0,"\u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05d5 \u05db\u05e9\u05d4\u05d3\u05d0\u05d2\u05d4 \u05d4\u05d9\u05d0 \u05d3\u05d5\u05e4\u05df \u05d3\u05e7\u05d4, \u05d5\u05dc\u05d0 \u05d4\u05e8\u05db\u05d1\u05d4."],[220.0,"\u05e7\u05d3\u05d7 \u05e7\u05e8\u05d5\u05d1 \u05dc\u05e7\u05e6\u05d4, \u05dc\u05de\u05e9\u05dc, \u05e2\u05dc\u05d5\u05dc \u05dc\u05d4\u05e9\u05d0\u05d9\u05e8 \u05d3\u05d5\u05e4\u05df \u05d7\u05dc\u05e9\u05d4. | \u05d1\u05e2\u05d9\u05d2\u05d5\u05dc \u05de\u05d1\u05d8\u05d9\u05d7 \u05e2\u05d5\u05d1\u05d9 \u05d3\u05d5\u05e4\u05df \u05de\u05d9\u05e0\u05d9\u05de\u05dc\u05d9."],[228.0,"\u05db\u05e9\u05d0\u05d9\u05df \u05e1\u05d9\u05de\u05df \u05d1\u05db\u05dc\u05dc, \u05d4\u05e1\u05d1\u05d5\u05dc\u05ea \u05e7\u05d1\u05d5\u05e2\u05d4 \u05dc\u05db\u05dc \u05d2\u05d5\u05d3\u05dc \u05e9\u05dc \u05d4\u05e7\u05d3\u05d7, \u05d5\u05d0\u05d9\u05df \u05d1\u05d5\u05e0\u05d5\u05e1."],[235.0,"\u05d5\u05d4\u05d1\u05d7\u05d9\u05e8\u05d4 \u05d1\u05d9\u05df \u05e9\u05dc\u05d5\u05e9 \u05d4\u05d0\u05e4\u05e9\u05e8\u05d5\u05d9\u05d5\u05ea \u05d0\u05d5\u05de\u05e8\u05ea \u05dc\u05e7\u05d5\u05e8\u05d0 \u05de\u05d4 \u05d4\u05de\u05ea\u05db\u05e0\u05df \u05e0\u05d9\u05e1\u05d4 \u05dc\u05d4\u05d2\u05df \u05e2\u05dc\u05d9\u05d5: \u05d4\u05e8\u05db\u05d1\u05d4, \u05d7\u05d5\u05d6\u05e7, \u05d0\u05d5 \u05de\u05d9\u05e7\u05d5\u05dd \u05de\u05d3\u05d5\u05d9\u05e7."],[245.0,"\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05e8\u05d5\u05d0\u05d9\u05dd \u05e1\u05d1\u05d5\u05dc\u05ea \u05de\u05d9\u05e7\u05d5\u05dd \u05e9\u05dc \u05d0\u05e4\u05e1, \u05e2\u05dd \u05d5\u05d0 \u05d1\u05e2\u05d9\u05d2\u05d5\u05dc."],[250.0,"\u05d6\u05d4 \u05dc\u05d0 \u05d0\u05d5\u05de\u05e8 \u05e9\u05d4\u05e7\u05d3\u05d7 \u05d7\u05d9\u05d9\u05d1 \u05dc\u05d4\u05d9\u05d5\u05ea \u05d1\u05de\u05d9\u05e7\u05d5\u05dd \u05de\u05d5\u05e9\u05dc\u05dd."],[254.0,"\u05de\u05e7\u05e1\u05d9\u05de\u05dc\u05d9 \u05d7\u05d9\u05d9\u05d1 \u05dc\u05d4\u05d9\u05d5\u05ea \u05d1\u05de\u05e7\u05d5\u05dd \u05d4\u05de\u05d3\u05d5\u05d9\u05e7, \u05d5\u05db\u05dc \u05ea\u05d5\u05e1\u05e4\u05ea \u05dc\u05e7\u05d5\u05d8\u05e8 \u05d4\u05d9\u05d0 \u05e1\u05d1\u05d5\u05dc\u05ea \u05de\u05d9\u05e7\u05d5\u05dd."],[266.0,"\u05db\u05da \u05d4\u05d9\u05e6\u05e8\u05df \u05de\u05d7\u05dc\u05d9\u05d8 \u05d1\u05e2\u05e6\u05de\u05d5 \u05d0\u05d9\u05da \u05dc\u05d7\u05dc\u05e7 \u05d0\u05ea \u05d4\u05e1\u05d1\u05d5\u05dc\u05ea \u05d1\u05d9\u05df \u05d2\u05d5\u05d3\u05dc \u05dc\u05de\u05d9\u05e7\u05d5\u05dd, \u05d5\u05d4\u05e4\u05d5\u05e0\u05e7\u05e6\u05d9\u05d4 \u05e0\u05e9\u05de\u05e8\u05ea."],[274.0,"\u05de\u05e1\u05d2\u05e8\u05ea \u05d0\u05d7\u05ea \u05d9\u05db\u05d5\u05dc\u05d4 \u05dc\u05d7\u05d5\u05dc \u05e2\u05dc \u05db\u05de\u05d4 \u05e7\u05d3\u05d7\u05d9\u05dd \u05d9\u05d7\u05d3, \u05dc\u05de\u05e9\u05dc \u05d0\u05e8\u05d1\u05e2\u05d4 \u05e7\u05d3\u05d7\u05d9\u05dd, \u05e2\u05dd \u05d4\u05db\u05d9\u05ea\u05d5\u05d1 \u05d0\u05e8\u05d1\u05e2 \u05e4\u05e2\u05de\u05d9\u05dd \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e7\u05d5\u05d8\u05e8."],[284.0,"\u05d0\u05d6 \u05d4\u05e7\u05d3\u05d7\u05d9\u05dd \u05e0\u05d1\u05d3\u05e7\u05d9\u05dd \u05db\u05e7\u05d1\u05d5\u05e6\u05d4: \u05d2\u05dd \u05d4\u05de\u05d9\u05e7\u05d5\u05dd \u05e9\u05dc \u05db\u05dc \u05d0\u05d7\u05d3 \u05de\u05d4\u05dd, \u05d5\u05d2\u05dd \u05d4\u05de\u05e8\u05d7\u05e7\u05d9\u05dd \u05d1\u05d9\u05e0\u05d9\u05d4\u05dd."],[291.0,"\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d4\u05de\u05e1\u05d2\u05e8\u05ea \u05d1\u05e0\u05d5\u05d9\u05d4 \u05de\u05e9\u05ea\u05d9 \u05e9\u05d5\u05e8\u05d5\u05ea, \u05e2\u05dd \u05e1\u05de\u05dc \u05de\u05d9\u05e7\u05d5\u05dd \u05d0\u05d7\u05d3 \u05de\u05e9\u05d5\u05ea\u05e3. \u05d6\u05d5 \u05e1\u05d1\u05d5\u05dc\u05ea \u05de\u05d9\u05e7\u05d5\u05dd \u05de\u05d5\u05e8\u05db\u05d1\u05ea."],[299.0,"\u05d4\u05e9\u05d5\u05e8\u05d4 \u05d4\u05e2\u05dc\u05d9\u05d5\u05e0\u05d4, \u05d4\u05e8\u05d7\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05de\u05de\u05e7\u05de\u05ea \u05d0\u05ea \u05d4\u05e7\u05d1\u05d5\u05e6\u05d4 \u05db\u05d5\u05dc\u05d4 \u05d1\u05d9\u05d7\u05e1 \u05dc\u05de\u05e9\u05d8\u05d7\u05d9\u05dd."],[306.0,"\u05d4\u05e9\u05d5\u05e8\u05d4 \u05d4\u05ea\u05d7\u05ea\u05d5\u05e0\u05d4, \u05d4\u05d4\u05d3\u05d5\u05e7\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05e9\u05d5\u05dc\u05d8\u05ea \u05e8\u05e7 \u05d1\u05de\u05e8\u05d7\u05e7\u05d9\u05dd \u05d1\u05d9\u05df \u05d4\u05e7\u05d3\u05d7\u05d9\u05dd \u05d5\u05d1\u05db\u05d9\u05d5\u05d5\u05df \u05e9\u05dc\u05d4\u05dd, \u05d5\u05dc\u05d0 \u05d1\u05de\u05d9\u05e7\u05d5\u05dd \u05d4\u05e7\u05d1\u05d5\u05e6\u05d4."],[315.0,"\u05d0\u05d1\u05dc \u05d4\u05e7\u05d3\u05d7\u05d9\u05dd \u05e6\u05e8\u05d9\u05db\u05d9\u05dd \u05dc\u05e9\u05de\u05d5\u05e8 \u05d6\u05d4 \u05e2\u05dc \u05d6\u05d4 \u05d1\u05ea\u05d5\u05da \u05d4\u05e1\u05d1\u05d5\u05dc\u05ea \u05d4\u05d4\u05d3\u05d5\u05e7\u05d4."],[326.0,"\u05d7\u05e9\u05d5\u05d1 \u05e9\u05d4\u05e7\u05d3\u05d7\u05d9\u05dd \u05d9\u05ea\u05d0\u05d9\u05de\u05d5 \u05d6\u05d4 \u05dc\u05d6\u05d4, \u05d9\u05d5\u05ea\u05e8 \u05de\u05d4\u05de\u05e7\u05d5\u05dd \u05d4\u05de\u05d3\u05d5\u05d9\u05e7 \u05e9\u05dc \u05d4\u05e7\u05d1\u05d5\u05e6\u05d4."],[336.0,"\u05d1\u05d0\u05d5\u05ea\u05d5 \u05e1\u05d3\u05e8\u05d5\u05e2\u05dd \u05d0\u05d5\u05ea\u05dd \u05de\u05d5\u05d3\u05d9\u05e4\u05d9\u05d9\u05e8\u05d9\u05dd, \u05d4\u05df \u05e0\u05d1\u05d3\u05e7\u05d5\u05ea \u05db\u05e7\u05d1\u05d5\u05e6\u05d4 \u05d0\u05d7\u05ea, \u05d1\u05d1\u05ea \u05d0\u05d7\u05ea."],[348.0,"\u05db\u05d3\u05d9 \u05dc\u05d4\u05e4\u05e8\u05d9\u05d3 \u05d1\u05d9\u05e0\u05d9\u05d4\u05df \u05db\u05d5\u05ea\u05d1\u05d9\u05dd 2WNT,SEP REQT \u05d3\u05e8\u05d9\u05e9\u05d4 \u05e0\u05e4\u05e8\u05d3\u05ea."],[356.0,"\u05d1\u05ea\u05e7\u05e0\u05d9 ISO \u05d1\u05e8\u05d9\u05e8\u05ea \u05d4\u05de\u05d7\u05d3\u05dc \u05d4\u05e4\u05d5\u05db\u05d4: \u05db\u05dc \u05e7\u05d1\u05d5\u05e6\u05d4 \u05e0\u05d1\u05d3\u05e7\u05ea \u05dc\u05d1\u05d3, \u05d5\u05db\u05d3\u05d9 \u05dc\u05d7\u05d1\u05e8 \u05e6\u05e8\u05d9\u05da \u05dc\u05db\u05ea\u05d5\u05d1 \u05d5\u05d0\u05d5\u05e4, \u05d0\u05d5 CZ \u05dc\u05d0\u05d6\u05d5\u05e8 \u05de\u05e9\u05d5\u05ea\u05e3."],[367.0,"\u05dc\u05db\u05df \u05d0\u05d5\u05ea\u05d5 \u05e9\u05e8\u05d8\u05d5\u05d8 \u05d1\u05d3\u05d9\u05d5\u05e7 \u05d9\u05db\u05d5\u05dc \u05dc\u05d3\u05e8\u05d5\u05e9 \u05d1\u05d3\u05d9\u05e7\u05d4 \u05d0\u05d7\u05ea \u05d0\u05d5 \u05db\u05de\u05d4, \u05dc\u05e4\u05d9 \u05d4\u05ea\u05e7\u05df."],[375.0,"\u05d9\u05e9 \u05e2\u05d5\u05d3 \u05db\u05de\u05d4 \u05d4\u05d1\u05d3\u05dc\u05d9\u05dd \u05e9\u05db\u05d3\u05d0\u05d9 \u05dc\u05d4\u05db\u05d9\u05e8 \u05db\u05e9\u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05e9\u05e8\u05d8\u05d5\u05d8 \u05d1\u05ea\u05e7\u05df \u05d0\u05d7\u05e8 \u05de\u05d6\u05d4 \u05e9\u05e8\u05d2\u05d9\u05dc\u05d9\u05dd \u05d0\u05dc\u05d9\u05d5."],[381.0,"\u05d5\u05e9\u05dc \u05e1\u05d9\u05de\u05d8\u05e8\u05d9\u05d4. \u05d1\u05de\u05e7\u05d5\u05de\u05dd \u05de\u05e9\u05d5\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05e1\u05d1\u05d5\u05dc\u05ea \u05de\u05d9\u05e7\u05d5\u05dd, \u05e4\u05e8\u05d5\u05e4\u05d9\u05dc \u05d0\u05d5 \u05e8\u05d9\u05e6\u05d4."],[394.0,"\u05d1\u05ea\u05e7\u05e0\u05d9 ISO \u05e9\u05e0\u05d9 \u05d4\u05e1\u05de\u05dc\u05d9\u05dd \u05e2\u05d3\u05d9\u05d9\u05df \u05e7\u05d9\u05d9\u05de\u05d9\u05dd, \u05d5\u05d2\u05dd \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8\u05d9 ASME \u05d9\u05e9\u05e0\u05d9\u05dd \u05ea\u05de\u05e6\u05d0\u05d5 \u05d0\u05d5\u05ea\u05dd."],[402.0,"\u05d4\u05e2\u05e8\u05da. \u05d1\u05dc\u05d9 \u05d4\u05e1\u05d9\u05de\u05df, \u05d4\u05d0\u05d6\u05d5\u05e8 \u05d4\u05d5\u05d0 \u05d1\u05d9\u05df \u05e9\u05e0\u05d9 \u05de\u05d9\u05e9\u05d5\u05e8\u05d9\u05dd, \u05d5\u05d6\u05d5 \u05d3\u05e8\u05d9\u05e9\u05d4 \u05d0\u05d7\u05e8\u05ea \u05dc\u05d2\u05de\u05e8\u05d9."],[415.0,"\u05db\u05d3\u05d9 \u05dc\u05d0 \u05dc\u05e4\u05e1\u05e4\u05e1, \u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05db\u05dc \u05d0\u05dc\u05de\u05e0\u05d8 \u05d1\u05d0\u05d5\u05ea\u05d5 \u05e1\u05d3\u05e8."],[420.0,"\u05e7\u05d5\u05d3\u05dd \u05d2\u05d5\u05d3\u05dc: \u05de\u05d4 \u05d4\u05de\u05d9\u05d3\u05d4, \u05d5\u05d4\u05d0\u05dd \u05d7\u05dc \u05e2\u05e7\u05e8\u05d5\u05df \u05d4\u05de\u05e2\u05d8\u05e4\u05ea."],[425.0,"\u05d0\u05d7\u05e8 \u05db\u05da \u05e6\u05d5\u05e8\u05d4, \u05db\u05d9\u05d5\u05d5\u05df \u05d5\u05de\u05d9\u05e7\u05d5\u05dd, \u05d5\u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05e9\u05db\u05dc \u05d0\u05d7\u05d3 \u05e7\u05d8\u05df \u05de\u05d6\u05d4 \u05e9\u05de\u05e2\u05dc\u05d9\u05d5."],[431.0,"\u05d0\u05d7\u05e8 \u05db\u05da \u05d4\u05de\u05e9\u05d8\u05d7\u05d9\u05dd: \u05d4\u05d0\u05dd \u05d4\u05dd \u05e7\u05d9\u05d9\u05de\u05d9\u05dd, \u05d5\u05d4\u05d0\u05dd \u05d4\u05dd \u05d1\u05e1\u05d3\u05e8 \u05d4\u05e0\u05db\u05d5\u05df."],[437.0,"\u05d5\u05dc\u05d1\u05e1\u05d5\u05e3 \u05d4\u05de\u05d5\u05d3\u05d9\u05e4\u05d9\u05d9\u05e8\u05d9\u05dd: ,\u05d5\u05d0 \u05d0\u05d5 \u05db\u05dc\u05d5\u05dd, \u05d5\u05d4\u05d0\u05dd \u05d9\u05e9 \u05d1\u05d5\u05e0\u05d5\u05e1 \u05d0\u05d5 \u05d4\u05d6\u05ea \u05de\u05e9\u05d8\u05d7."],[445.0,"\u05d0\u05dd \u05de\u05e9\u05d4\u05d5 \u05d1\u05e9\u05e8\u05e9\u05e8\u05ea \u05d4\u05d6\u05d5 \u05dc\u05d0 \u05de\u05e1\u05ea\u05d3\u05e8, \u05d6\u05d5 \u05e9\u05d0\u05dc\u05d4 \u05dc\u05de\u05ea\u05db\u05e0\u05df, \u05d5\u05dc\u05d0 \u05d4\u05d7\u05dc\u05d8\u05d4 \u05e9\u05dc \u05de\u05d9 \u05e9\u05de\u05d5\u05d3\u05d3."],[453.0,"\u05de\u05d4\u05e1\u05d1\u05d5\u05dc\u05ea \u05e9\u05de\u05e2\u05dc\u05d9\u05d5, \u05d5\u05de\u05d9\u05e7\u05d5\u05dd \u05d1\u05e1\u05d1\u05d5\u05dc\u05ea \u05e8\u05e7 \u05d1\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05e1\u05d9\u05e1\u05d9\u05d5\u05ea."],[463.0,"\u05d5\u05d1\u05e7\u05d1\u05d5\u05e6\u05d5\u05ea \u05e7\u05d3\u05d7\u05d9\u05dd \u05e1\u05d1\u05d5\u05dc\u05ea \u05de\u05d5\u05e8\u05db\u05d1\u05ea \u05de\u05e4\u05e8\u05d9\u05d3\u05d4 \u05d1\u05d9\u05df \u05de\u05d9\u05e7\u05d5\u05dd \u05d4\u05e7\u05d1\u05d5\u05e6\u05d4 \u05dc\u05e7\u05e9\u05d5\u05e8 \u05d1\u05d9\u05df \u05d4\u05e7\u05d3\u05d7\u05d9\u05dd."],[475.0,"\u05d5\u05de\u05d7\u05d4 Ra \u05d0\u05d5\u05de\u05e8 \u05d5\u05de\u05d4 \u05d4\u05d5\u05d0 \u05dc\u05d0 \u05d0\u05d5\u05de\u05e8. \u05e0\u05ea\u05e8\u05d0\u05d4 \u05d1\u05e4\u05e8\u05e7 \u05d0\u05d7\u05ea \u05e2\u05e9\u05e8\u05d4."]]};
window.MH_TR["ch11"]={"t":"\u05de\u05e8\u05e7\u05dd \u05e4\u05e0\u05d9 \u05e9\u05d8\u05d7","l":[[1.0,"\u05e9\u05e0\u05d9 \u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05d9\u05db\u05d5\u05dc\u05d9\u05dd \u05dc\u05d4\u05d9\u05d5\u05ea \u05d1\u05d0\u05d5\u05ea\u05d4 \u05de\u05d9\u05d3\u05d4 \u05d1\u05d3\u05d9\u05d5\u05e7, \u05d5\u05e2\u05d3\u05d9\u05d9\u05df \u05dc\u05d4\u05ea\u05e0\u05d4\u05d2 \u05d0\u05d7\u05e8\u05ea \u05dc\u05d2\u05de\u05e8\u05d9."],[7.0,"\u05d4\u05d0\u05d7\u05d3 \u05d0\u05d5\u05d8\u05dd, \u05d5\u05d4\u05e9\u05e0\u05d9 \u05d3\u05d5\u05dc\u05e3. \u05d4\u05d0\u05d7\u05d3 \u05e0\u05e9\u05d7\u05e7 \u05dc\u05d0\u05d8, \u05d5\u05d4\u05e9\u05e0\u05d9 \u05e0\u05e9\u05d1\u05e8 \u05de\u05e2\u05d9\u05d9\u05e4\u05d5\u05ea."],[15.0,"\u05d4\u05d4\u05d1\u05d3\u05dc \u05e0\u05de\u05e6\u05d0 \u05d1\u05de\u05e8\u05e7\u05dd \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7: \u05d4\u05d2\u05d1\u05e2\u05d5\u05ea \u05d5\u05d4\u05e2\u05de\u05e7\u05d9\u05dd \u05d4\u05e7\u05d8\u05e0\u05d9\u05dd \u05e9\u05d4\u05db\u05dc\u05d9 \u05de\u05e9\u05d0\u05d9\u05e8."],[22.0,"\u05dc\u05e7\u05e8\u05d5\u05d0 \u05d0\u05ea \u05e1\u05d9\u05de\u05d5\u05df \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7, \u05d5\u05de\u05d4 Ra \u05d0\u05d5\u05de\u05e8 \u05d5\u05de\u05d4 \u05d4\u05d5\u05d0 \u05dc\u05d0 \u05d0\u05d5\u05de\u05d5."],[33.0,"\u05db\u05e9\u05de\u05d2\u05d3\u05d9\u05dc\u05d9\u05dd \u05d7\u05ea\u05da \u05e9\u05dc \u05de\u05e9\u05d8\u05d7 \u05de\u05e2\u05d5\u05d1\u05d3, \u05e8\u05d5\u05d0\u05d9\u05dd \u05e9\u05dc\u05d5\u05e9 \u05e9\u05db\u05d1\u05d5\u05ea \u05e9\u05dc \u05e1\u05d8\u05d9\u05d9\u05d4."],[38.0,"\u05d4\u05e6\u05d5\u05e8\u05d4 \u05d4\u05db\u05dc\u05dc\u05d9\u05ea, \u05db\u05de\u05d5 \u05e7\u05e9\u05d5\u05ea \u05d0\u05d5 \u05e9\u05d9\u05e4\u05d5\u05e2, \u05e0\u05e9\u05dc\u05d8\u05ea \u05e2\u05dc \u05d9\u05d3\u05d9 \u05e1\u05d1\u05d5\u05dc\u05d5\u05ea \u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05d5\u05ea."],[45.0,"\u05d4\u05d2\u05dc\u05d9\u05d5\u05ea \u05d4\u05d9\u05d0 \u05e1\u05d8\u05d9\u05d9\u05d4 \u05d1\u05d2\u05dc \u05d0\u05e8\u05d5\u05da, \u05e9\u05e0\u05d5\u05e6\u05e8\u05ea \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05de\u05e8\u05e2\u05d9\u05d3\u05d5\u05ea \u05d0\u05d5 \u05de\u05db\u05d9\u05e4\u05d5\u05e3 \u05e9\u05dc \u05d4\u05db\u05dc\u05d9."],[52.0,"\u05d5\u05d4\u05d7\u05e1\u05e4\u05d5\u05e1 \u05d4\u05d5\u05d0 \u05d4\u05d2\u05dc \u05d4\u05e7\u05e6\u05e8, \u05d4\u05e1\u05d9\u05de\u05e0\u05d9\u05dd \u05e9\u05dc \u05d4\u05db\u05dc\u05d9 \u05e2\u05e6\u05de\u05d5. \u05d1\u05d5 \u05e2\u05d5\u05e1\u05e7 \u05e8\u05d5\u05d1 \u05d4\u05e1\u05d9\u05de\u05d5\u05df \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8."],[59.0,"\u05d4\u05e1\u05d9\u05de\u05e0\u05d9\u05dd \u05e9\u05dc \u05d4\u05db\u05dc\u05d9 \u05e0\u05de\u05e9\u05db\u05d9\u05dd \u05d2\u05dd \u05d1\u05db\u05d9\u05d5\u05d5\u05df \u05de\u05e1\u05d5\u05d9\u05dd, \u05d5\u05d6\u05d4 \u05e0\u05e7\u05e8\u05d0 \u05db\u05d9\u05d5\u05d5\u05df \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3."],[66.0,"\u05d4\u05e4\u05e8\u05de\u05d8\u05e8 \u05d4\u05e0\u05e4\u05d5\u05e5 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05d4\u05d5\u05d0 Ra: \u05d4\u05de\u05de\u05d5\u05e6\u05e2 \u05e9\u05dc \u05d4\u05e1\u05d8\u05d9\u05d5\u05ea \u05de\u05e7\u05d5 \u05d4\u05d0\u05de\u05e6\u05e2 \u05e9\u05dc \u05d4\u05e4\u05e8\u05d5\u05e4\u05d9\u05dc, \u05d1\u05de\u05d9\u05e7\u05e8\u05d5\u05e0\u05d9\u05dd."],[74.0,"Ra \u05d4\u05d5\u05d0 \u05de\u05e1\u05e4\u05e8 \u05d9\u05e6\u05d9\u05d1 \u05d5\u05e0\u05d5\u05d7 \u05dc\u05de\u05d3\u05d9\u05d3\u05d4, \u05d5\u05dc\u05db\u05df \u05d4\u05d5\u05d0 \u05de\u05d5\u05e4\u05d9\u05e2 \u05d1\u05e8\u05d5\u05d1 \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8\u05d9\u05dd."],[81.0,"\u05d0\u05d1\u05dc\u05d9\u05e9 \u05dc\u05d5 \u05d7\u05d5\u05dc\u05e9\u05d4: \u05e9\u05e0\u05d9 \u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05e9\u05d5\u05e0\u05d9\u05dd \u05dc\u05d2\u05de\u05e8\u05d9 \u05d9\u05db\u05d5\u05dc\u05d9\u05dd \u05dc\u05e7\u05d1\u05dc \u05d0\u05d5\u05ea\u05d5 Ra."],[87.0,"\u05d0\u05ea \u05d0\u05d5\u05ea\u05d5 \u05de\u05de\u05d5\u05e6\u05e2, \u05d0\u05e3 \u05e9\u05d4\u05dd \u05de\u05ea\u05e0\u05d4\u05d2\u05d9\u05dd \u05d4\u05e4\u05d5\u05da \u05d1\u05d0\u05d8\u05d9\u05de\u05d4 \u05d5\u05d1\u05e9\u05d7\u05d9\u05e7\u05d4."],[97.0,"\u05d5\u05e9\u05e8\u05d9\u05d8\u05d4 \u05d1\u05d5\u05d3\u05d3\u05ea \u05db\u05de\u05e2\u05d8 \u05dc\u05d0 \u05de\u05e9\u05e0\u05d4 \u05d0\u05ea 8\u05d7, \u05db\u05d9 \u05d4\u05d9\u05d0 \u05e0\u05d1\u05dc\u05e2\u05ea \u05d1\u05de\u05de\u05d5\u05e6\u05e2."],[104.0,"7 \u05de\u05d5\u05d3\u05d3 \u05d0\u05ea \u05d4\u05d2\u05d5\u05d1\u05d4 \u05d1\u05d9\u05df \u05d4\u05e4\u05e1\u05d2\u05d4 \u05d4\u05d2\u05d1\u05d5\u05d4\u05d4 \u05dc\u05e2\u05de\u05e7 \u05d4\u05e2\u05de\u05d5\u05e7, \u05d1\u05db\u05dc \u05e7\u05d8\u05e2 \u05de\u05d3\u05d9\u05d3\u05d4, \u05d5\u05de\u05d7\u05e9\u05d1 \u05d0\u05ea \u05d4\u05de\u05de\u05d5\u05e6\u05e2."],[112.0,"\u05dc\u05db\u05df \u20aa7 \u05e8\u05d2\u05d9\u05e9 \u05d4\u05e8\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05dc\u05e4\u05e1\u05d2\u05d5\u05ea \u05d5\u05dc\u05e9\u05e8\u05d9\u05d8\u05d5\u05ea \u05d1\u05d5\u05d3\u05d3\u05d5\u05ea."],[117.0,"\u05d0\u05d9\u05df \u05d9\u05d7\u05e1 \u05e7\u05d1\u05d5\u05e2 \u05d1\u05d9\u05df Ra \u05dc\u05d1\u05d9\u05df RZ. \u05d4\u05d9\u05d7\u05e1 \u05ea\u05dc\u05d5\u05d9 \u05d1\u05ea\u05d4\u05dc\u05d9\u05da, \u05d5\u05dc\u05db\u05df \u05d0\u05d9 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d4\u05de\u05d9\u05e8 \u05d1\u05d9\u05e0\u05d9\u05d4\u05dd \u05d1\u05e0\u05d5\u05e1\u05d7\u05d4."],[127.0,"\u05de\u05d9 \u05e9\u05de\u05d7\u05dc\u05d9\u05e3 RZ \u2026 \u05dc\u05e4\u05d9 \u05d8\u05d1\u05dc\u05ea \u05d4\u05de\u05e8\u05d4, \u05de\u05e9\u05e0\u05d4 \u05d0\u05ea \u05d4\u05d3\u05e8\u05d9\u05e9\u05d4 \u05e9\u05dc \u05d4\u05de\u05ea\u05db\u05e0\u05df."],[134.0,"\u05e9\u05dc\u05d5\u05e9\u05d9\u05dd \u05d5\u05e9\u05e0\u05d9\u05d9\u05dd \u05de\u05d9\u05e7\u05e8\u05d5 \u05d0\u05d9\u05e0\u05e5' \u05d4\u05d5\u05d0 \u05d1\u05e2\u05e8\u05da \u05e9\u05de\u05d5\u05e0\u05d4 \u05e2\u05e9\u05d9\u05e8\u05d9\u05d5\u05ea \u05de\u05d9\u05e7\u05e8\u05d5\u05df."],[144.0,"\u05d4\u05e1\u05d9\u05de\u05d5\u05df \u05d4\u05d1\u05e1\u05d9\u05e1\u05d9 \u05d4\u05d5\u05d0 \u05e7\u05d5\u05e9\u05d1\u05d5\u05d4 \u05db\u05de\u05d5\u05d5\u05d9 \u2026 \u05d0\u05e8\u05d5\u05db\u05d4 \u05d0\u05d7\u05ea, \u05e9\u05e0\u05d5\u05d2\u05e2 \u05d1\u05de\u05e9\u05d8\u05d7."],[152.0,"\u05e7\u05d5 \u05d0\u05d5\u05e4\u05e7\u05d9 \u05e9\u05e1\u05d5\u05d2\u05e8 \u05d0\u05ea \u05d4\u05d5\u05d5\u05d9 \u05d0\u05d5\u05de\u05e8: \u05d7\u05d5\u05d1\u05d4 \u05dc\u05d4\u05e1\u05d9\u05e8 \u05d7\u05d5\u05de\u05e8, \u05db\u05dc\u05d5\u05de\u05e8 \u05dc\u05e2\u05d1\u05d3 \u05d0\u05ea \u05d4\u05de\u05e9\u05d8\u05d7."],[159.0,"\u05e2\u05d9\u05d2\u05d5\u05dc \u05d1\u05ea\u05d5\u05da \u05d4\u05d5\u05d5\u05d9 \u05d0\u05d5\u05de\u05e8 \u05d4\u05e4\u05d5\u05da: \u05d0\u05e1\u05d5\u05e8 \u05dc\u05d4\u05e1\u05d9\u05e8 \u05d7\u05d5\u05de\u05e8. \u05d4\u05de\u05e9\u05d8\u05d7 \u05e0\u05e9\u05d0\u05e8 \u05db\u05de\u05d5 \u05e9\u05d4\u05d5\u05d0 \u05d0\u05d7\u05e8\u05d9 \u05d9\u05e6\u05d9\u05e7\u05d4, \u05d7\u05d9\u05e9\u05d5\u05dc \u05d0\u05d5 \u05db\u05d1\u05d9\u05e9\u05d4."],[169.0,"\u05d5\u05d4\u05e1\u05d9\u05de\u05d5\u05df \u05d1\u05dc\u05d9 \u05ea\u05d5\u05e1\u05e4\u05d5\u05ea \u05d0\u05d5\u05de\u05e8: \u05db\u05dc \u05ea\u05d4\u05dc\u05d9\u05da \u05de\u05d5\u05ea\u05e8, \u05db\u05dc \u05e2\u05d5\u05d3 \u05d4\u05de\u05e8\u05e7\u05dd \u05de\u05ea\u05e7\u05d1\u05dc."],[175.0,"\u05e2\u05dc \u05d4\u05d6\u05e8\u05d5\u05e2 \u05d4\u05d0\u05e8\u05d5\u05db\u05d4 \u05db\u05d5\u05ea\u05d1\u05d9\u05dd \u05d0\u05ea \u05d4\u05e4\u05e8\u05de\u05d8\u05e8 \u05d5\u05d0\u05ea \u05d4\u05e2\u05e8\u05da, \u05dc\u05de\u05e9\u05dc Ra \u05e9\u05de\u05d5\u05e0\u05d4 \u05e2\u05e9\u05d9\u05e8\u05d9\u05d5\u05ea."],[183.0,"\u05d0\u05e4\u05e9\u05e8 \u05dc\u05d4\u05d5\u05e1\u05d9\u05e3 \u05d2\u05dd \u05ea\u05d4\u05dc\u05d9\u05da \u05d9\u05d9\u05e6\u05d5\u05e8 \u05de\u05d7\u05d9\u05d9\u05d1, \u05ea\u05d5\u05e1\u05e4\u05ea \u05dc\u05e2\u05d9\u05d1\u05d5\u05d3, \u05d5\u05e1\u05d9\u05de\u05df \u05dc\u05db\u05d9\u05d5\u05d5\u05df \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3."],[191.0,"\u05e1\u05d9\u05de\u05e0\u05d9 \u05db\u05d9\u05d5\u05d5\u05df \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d0\u05d5\u05de\u05e8\u05d9\u05dd \u05dc\u05d0\u05df \u05d4\u05e1\u05d9\u05de\u05e0\u05d9\u05dd \u05e9\u05dc \u05d4\u05db\u05dc\u05d9 \u05e6\u05e8\u05d9\u05db\u05d9\u05dd \u05dc\u05e8\u05d5\u05e5 \u05d1\u05d9\u05d7\u05e1 \u05dc\u05e7\u05d5 \u05e9\u05d1\u05d5 \u05de\u05e6\u05d5\u05d9\u05e8 \u05d4\u05e1\u05d9\u05de\u05d5\u05df."],[199.0,"\u05e4\u05d9\u05e8\u05d5\u05e9\u05d5 \u05de\u05e6\u05d8\u05dc\u05d1, 6 \u05e4\u05d9\u05e8\u05d5\u05e9\u05d5 \u05de\u05e2\u05d2\u05dc\u05d9, \u05d5-\u05d5\u05d0 \u05e4\u05d9\u05e8\u05d5\u05e9\u05d5 \u05d1\u05db\u05de\u05d4 \u05db\u05d9\u05d5\u05d5\u05e0\u05d9\u05dd."],[213.0,"\u05db\u05d9 \u05d4\u05d5\u05d0 \u05e7\u05d5\u05d1\u05e2 \u05d0\u05dd \u05e0\u05d5\u05d6\u05dc \u05d9\u05d6\u05e8\u05d5\u05dd \u05dc\u05d0\u05d5\u05e8\u05da \u05d4\u05e1\u05d9\u05de\u05e0\u05d9\u05dd \u05d0\u05d5 \u05d9\u05d9\u05e2\u05e6\u05e8 \u05d1\u05d4\u05dd."],[223.0,"\u05d5\u05d2\u05dd \u05d4\u05de\u05d3\u05d9\u05d3\u05d4 \u05ea\u05dc\u05d5\u05d9\u05d4 \u05d1\u05d5: Ra \u05e0\u05de\u05d3\u05d3 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05e0\u05d9\u05e6\u05d1 \u05dc\u05db\u05d9\u05d5\u05d5\u05df \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3. \u05de\u05d3\u05d9\u05d3\u05d4 \u05d1\u05de\u05e7\u05d1\u05d9\u05dc \u05e0\u05d5\u05ea\u05e0\u05ea \u05de\u05e1\u05e4\u05e8 \u05e0\u05de\u05d5\u05da \u05de\u05d3\u05d9."],[234.0,"\u2026, \u05d4\u05e1\u05d9\u05de\u05d5\u05df \u05de\u05d5\u05d2\u05d3\u05e8 \u05d4\u05d9\u05d5\u05dd \u05d1-21920 50\u05d5, \u05e9\u05d4\u05d7\u05dc\u05d9\u05e3 \u05d0\u05ea 2 ISO \u05d1\u05e9\u05e0\u05ea 2021."],[245.0,"ASME-3, \u05d4\u05e1\u05d9\u05de\u05d5\u05df \u05de\u05d5\u05d2\u05d3\u05e8 \u2026 ASME, \u05d5\u05d4\u05e6\u05d5\u05e8\u05d4 \u05d3\u05d5\u05de\u05d4 \u05de\u05d0\u05d5\u05d3."],[254.0,"\u05d1\u05e9\u05e8\u05d8\u05d5\u05d8\u05d9 ASME \u05d9\u05e9\u05e0\u05d9\u05dd, \u05de\u05e1\u05e4\u05e8 \u05e9\u05db\u05ea\u05d5\u05d1 \u05dc\u05d9\u05d3 \u05d4\u05e1\u05d9\u05de\u05d5\u05df \u05d1\u05dc\u05d9 \u05e9\u05dd \u05e4\u05e8\u05de\u05d8\u05e8 \u05d4\u05d5\u05d0 Ra."],[262.0,"\u05d5\u05d1-50\u05d5 \u05d9\u05e9 \u05db\u05dc\u05dc \u05d7\u05e9\u05d5\u05d1: \u05db\u05d1\u05e8\u05d9\u05e8\u05ea \u05de\u05d7\u05d3\u05dc, \u05e2\u05d3 \u05e9\u05d9\u05e9\u05d4 \u05e2\u05e9\u05e8 \u05d0\u05d7\u05d5\u05d6 \u05de\u05d4\u05de\u05d3\u05d9\u05d3\u05d5\u05ea \u05de\u05d5\u05ea\u05e8 \u05e9\u05d9\u05d7\u05e8\u05d2\u05d5 \u05de\u05d4\u05e2\u05e8\u05da."],[271.0,"\u05db\u05e9\u05db\u05ea\u05d5\u05d1 \u2026 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e4\u05e8\u05de\u05d8\u05e8, \u05d0\u05e3 \u05de\u05d3\u05d9\u05d3\u05d4 \u05dc\u05d0 \u05de\u05d5\u05ea\u05e8 \u05e9\u05ea\u05d7\u05e8\u05d5\u05d2."],[276.0,"\u05dc\u05e9\u05ea\u05d9 \u05de\u05d9\u05e7\u05e8\u05d5\u05df, \u05d0\u05d5\u05e8\u05da \u05d4\u05d3\u05d2\u05d9\u05de\u05d4 \u05d4\u05d5\u05d0 \u05e9\u05de\u05d5\u05e0\u05d4 \u05e2\u05e9\u05d9\u05e8\u05d9\u05d5\u05ea \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8."],[288.0,"\u05d1\u05e8\u05d5\u05d1 \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8\u05d9\u05dd \u05dc\u05d0 \u05de\u05e1\u05de\u05e0\u05d9\u05dd \u05db\u05dc \u05de\u05e9\u05d8\u05d7 \u05d1\u05e0\u05e4\u05e8\u05d3."],[292.0,"\u05dc\u05d9\u05d3 \u05d0\u05d6\u05d5\u05e8 \u05d4\u05db\u05d5\u05ea\u05e8\u05ea \u05de\u05d5\u05e4\u05d9\u05e2 \u05e1\u05d9\u05de\u05d5\u05df \u05db\u05dc\u05dc\u05d9, \u05dc\u05de\u05e9\u05dc \u20aa4 \u05e9\u05dc\u05d5\u05e9 \u05e0\u05e7\u05d5\u05d3\u05d4 \u05e9\u05ea\u05d9\u05d9\u05dd, \u05d5\u05d0\u05d7\u05e8\u05d9\u05d5 \u05e1\u05d9\u05de\u05df \u05d1\u05e1\u05d5\u05d2\u05e8\u05d9\u05d9\u05dd."],[301.0,"\u05d6\u05d4 \u05d0\u05d5\u05de\u05e8: \u05db\u05dc \u05d4\u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05d1\u05e9\u05dc\u05d5\u05e9 \u05e0\u05e7\u05d5\u05d3\u05d4 \u05e9\u05ea\u05d9\u05d9\u05dd, \u05d7\u05d5\u05e5 \u05de\u05d0\u05dc\u05d4 \u05e9\u05de\u05e1\u05d5\u05de\u05e0\u05d9\u05dd \u05d0\u05d7\u05e8\u05ea \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8."],[309.0,"\u05dc\u05db\u05df \u05db\u05e9\u05de\u05e9\u05d8\u05d7 \u05de\u05e1\u05d5\u05d9\u05dd \u05dc\u05d0 \u05de\u05e1\u05d5\u05de\u05df, \u05d4\u05d5\u05d0 \u05e2\u05d3\u05d9\u05d9\u05df \u05dc\u05d0 \u05d7\u05d5\u05e4\u05e9\u05d9. \u05d4\u05d5\u05d0 \u05de\u05e7\u05d1\u05dc \u05d0\u05ea \u05d4\u05e1\u05d9\u05de\u05d5\u05df \u05d4\u05db\u05dc\u05dc\u05d9."],[316.0,"\u05dc\u05db\u05dc \u05ea\u05d4\u05dc\u05d9\u05da \u05d9\u05e9 \u05d8\u05d5\u05d5\u05d7 \u05d8\u05d1\u05e2\u05d9 \u05e9\u05dc \u05d7\u05e1\u05e4\u05d5\u05e1."],[320.0,"\u05e2\u05e9\u05d9\u05e8\u05d9\u05d5\u05ea \u05dc\u05e9\u05e9 \u05de\u05d9\u05e7\u05e8\u05d5\u05df. \u05e8\u05d9\u05de\u05e8 \u05e0\u05d5\u05ea\u05df \u05d1\u05e2\u05e8\u05da \u05de\u05d0\u05e8\u05d1\u05e2 \u05e2\u05e9\u05d9\u05e8\u05d9\u05d5\u05ea \u05dc\u05e9\u05dc\u05d5\u05e9 \u05de\u05d9\u05e7\u05e8\u05d5\u05df."],[331.0,"\u05d4\u05e9\u05d7\u05d6\u05d4 \u05de\u05d2\u05d9\u05e2\u05d4 \u05dc\u05e8\u05d5\u05d1 \u05dc\u05e2\u05e9\u05d9\u05e8\u05d9\u05ea \u05e2\u05d3 \u05de\u05d9\u05e7\u05e8\u05d5\u05df \u05d5\u05d7\u05e6\u05d9, \u05d5\u05dc\u05d9\u05d8\u05d5\u05e9 \u05d0\u05d5 \u05dc\u05e4\u05d9\u05e0\u05d2 \u05dc\u05e4\u05d7\u05d5\u05ea \u05de\u05d7\u05e6\u05d9 \u05de\u05d9\u05e7\u05e8\u05d5\u05df."],[339.0,"\u05dc\u05ea\u05d4\u05dc\u05d9\u05da. Ra \u05e9\u05dc \u05e9\u05ea\u05d9 \u05e2\u05e9\u05d9\u05e8\u05d9\u05d5\u05ea \u05db\u05de\u05e2\u05d8 \u05ea\u05de\u05d9\u05d3 \u05d3\u05d5\u05e8\u05e2\u05d5 \u05d4\u05e9\u05d7\u05d6\u05d4."],[348.0,"\u05d5\u05db\u05dc \u05e6\u05e2\u05d3 \u05dc\u05d7\u05e1\u05e4\u05d5\u05e1 \u05e0\u05de\u05d5\u05da \u05d9\u05d5\u05ea\u05e8 \u05de\u05d5\u05e1\u05d9\u05e3 \u05e4\u05e2\u05d5\u05dc\u05d4, \u05d6\u05de\u05df \u05d5\u05e2\u05dc\u05d5\u05ea."],[355.0,"\u05d9\u05e9 \u05db\u05de\u05d4 \u05de\u05dc\u05db\u05d5\u05d3\u05d5\u05ea \u05e9\u05db\u05d3\u05d0\u05d9 \u05dc\u05d4\u05db\u05d9\u05e8."],[358.0,"\u05d1\u05d7\u05dc\u05e7 \u05de\u05e6\u05d5\u05e4\u05d4, \u05e6\u05e8\u05d9\u05da \u05dc\u05d3\u05e2\u05ea \u05d0\u05dd \u05d4\u05d7\u05e1\u05e4\u05d5\u05e1 \u05d7\u05dc \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e6\u05d9\u05e4\u05d5\u05d9 \u05d0\u05d5 \u05d0\u05d7\u05e8\u05d9\u05d5, \u05db\u05d9 \u05e6\u05d9\u05e4\u05d5\u05d9 \u05d9\u05db\u05d5\u05dc \u05dc\u05e9\u05e0\u05d5\u05ea \u05d0\u05d5\u05ea\u05d5 \u05d1\u05d4\u05e8\u05d1\u05d4."],[367.0,"\u05de\u05e9\u05d0\u05d9\u05e8\u05d4 \u05e1\u05d9\u05de\u05e0\u05d9\u05dd \u05d1\u05e6\u05d5\u05e8\u05ea \u05e1\u05dc\u05d9\u05dc, \u05e9\u05d9\u05db\u05d5\u05dc\u05d9\u05dd \u05dc\u05e9\u05d0\u05d5\u05d1 \u05e0\u05d5\u05d6\u05dc \u05d4\u05d7\u05d5\u05e6\u05d4."],[377.0,"\u05d5\u05e9\u05e8\u05d9\u05d8\u05d4 \u05e2\u05de\u05d5\u05e7\u05d4 \u05d0\u05d7\u05ea \u05d9\u05db\u05d5\u05dc\u05d4 \u05dc\u05d2\u05e8\u05d5\u05dd \u05dc\u05d3\u05dc\u05d9\u05e4\u05d4 \u05d0\u05d5 \u05dc\u05e1\u05d3\u05e7, \u05d5\u05e2\u05d3\u05d9\u05d9\u05df \u05dc\u05d0 \u05dc\u05e9\u05e0\u05d5\u05ea \u05d0\u05ea Ra"],[384.0,"\u05db\u05e9\u05d4\u05e4\u05d5\u05e0\u05e7\u05e6\u05d9\u05d4 \u05e8\u05d2\u05d9\u05e9\u05d4 \u05dc\u05d6\u05d4, \u05d4\u05de\u05ea\u05db\u05e0\u05df \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d5\u05e1\u05d9\u05e3 \u05e4\u05e8\u05de\u05d8\u05e8 \u05db\u05de\u05d5 Rz, \u05d0\u05d5 \u05d3\u05e8\u05d9\u05e9\u05d4 \u05de\u05e4\u05d5\u05e8\u05e9\u05ea. \u05d5\u05d0\u05dd \u05d4\u05d9\u05d0 \u05d7\u05e1\u05e8\u05d4, \u05e9\u05d5\u05d0\u05dc\u05d9\u05dd."],[395.0,"\u05de\u05e8\u05e7\u05dd \u05e4\u05e0\u05d9 \u05e9\u05d8\u05d7 \u05d4\u05d5\u05d0 \u05d7\u05e1\u05e4\u05d5\u05e1, \u05d2\u05dc\u05d9\u05d5\u05ea \u05d5\u05db\u05d9\u05d5\u05d5\u05df \u05e2\u05d9\u05d1\u05d5\u05d3, \u05d5\u05db\u05dc \u05d0\u05d7\u05d3 \u05de\u05d4\u05dd \u05de\u05e9\u05e4\u05d9\u05e2 \u05e2\u05dc \u05d4\u05e4\u05d5\u05e0\u05e7\u05e6\u05d9\u05d4."],[402.0,"Ra \u05d4\u05d5\u05d0 \u05de\u05de\u05d5\u05e6\u05e2 \u05d9\u05e6\u05d9\u05d1, \u05d0\u05d1\u05dc \u05e2\u05d9\u05d5\u05d5\u05e8 \u05dc\u05e4\u05e1\u05d2\u05d5\u05ea \u05d5\u05dc\u05e9\u05d5\u05e8\u05d9\u05d8\u05d5\u05ea. RZ \u05e8\u05d2\u05d9\u05e9 \u05dc\u05d4\u05df \u05d9\u05d5\u05ea\u05e8, \u05d5\u05d0\u05d9\u05df \u05d1\u05d9\u05e0\u05d9\u05d4\u05dd \u05d4\u05de\u05e8\u05d4 \u05e7\u05d1\u05d5\u05e2\u05d4."],[412.0,"\u05d4\u05e1\u05d9\u05de\u05d5\u05df \u05d0\u05d5\u05de\u05e8 \u05d0\u05dd \u05d7\u05d5\u05d1\u05d4 \u05dc\u05d4\u05e1\u05d9\u05e8 \u05d7\u05d5\u05de\u05e8, \u05d0\u05e1\u05d5\u05e8, \u05d0\u05d5 \u05de\u05d5\u05ea\u05e8, \u05d5\u05d1\u05e1\u05d5\u05d2\u05e8\u05d9\u05d9\u05dd \u05dc\u05d9\u05d3 \u05d0\u05d6\u05d5\u05e8 \u05d4\u05db\u05d5\u05ea\u05e8\u05ea \u05de\u05d5\u05e4\u05d9\u05e2 \u05d4\u05e1\u05d9\u05de\u05d5\u05df \u05d4\u05db\u05dc\u05dc\u05d9."],[422.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05db\u05d9\u05e8 \u05d0\u05ea \u05e1\u05d9\u05de\u05d5\u05e0\u05d9 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da, \u05d5\u05d0\u05ea \u05d4\u05d4\u05d1\u05d3\u05dc\u05d9\u05dd \u05d1\u05d9\u05df \u05d4\u05ea\u05e7\u05df \u05d4\u05d0\u05de\u05e8\u05d9\u05e7\u05d0\u05d9 \u05dc\u05d1\u05d9\u05df 50\u05d5. \u05e0\u05ea\u05e8\u05d0\u05d4 \u05d1\u05e4\u05e8\u05e7 \u05e9\u05ea\u05d9\u05dd \u05e2\u05e9\u05e8\u05d4."]]};
window.MH_TR["ch12"]={"t":"\u05e1\u05d9\u05de\u05d5\u05e0\u05d9 \u05e8\u05d9\u05ea\u05d5\u05da","l":[[1.0,"\u05e1\u05d9\u05de\u05d5\u05df \u05e8\u05d9\u05ea\u05d5\u05da \u05d4\u05d5\u05d0 \u05d0\u05d7\u05d3 \u05d4\u05e1\u05d9\u05de\u05d5\u05e0\u05d9\u05dd \u05d4\u05e6\u05e4\u05d5\u05e4\u05d9\u05dd \u05d1\u05d9\u05d5\u05ea\u05e8 \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8."],[6.0,"\u05d1\u05e7\u05d5 \u05d0\u05d7\u05d3 \u05e7\u05d8\u05df \u05de\u05e7\u05d5\u05d3\u05d3\u05d9\u05dd \u05e1\u05d5\u05d2 \u05e8\u05d9\u05ea\u05d5\u05da, \u05d2\u05d5\u05d3\u05dc, \u05d0\u05d5\u05e8\u05da, \u05e6\u05d3 \u05d5\u05ea\u05d4\u05dc\u05d9\u05da."],[13.0,"\u05e9\u05e0\u05d9 \u05ea\u05e7\u05e0\u05d9\u05dd \u05e2\u05d9\u05e7\u05e8\u05d9\u05d9\u05dd, \u05d5\u05d4\u05dd \u05dc\u05d0 \u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05d0\u05ea \u05d4\u05e6\u05d3 \u05d1\u05d0\u05d5\u05ea\u05d4 \u05d3\u05e8\u05da."],[22.0,"\u05d1\u05ea\u05e7\u05df \u05d4\u05d0\u05de\u05e8\u05d9\u05e7\u05d0\u05d9, 2.4 5\u05d5/\\\\), \u05d5\u05d1\u05ea\u05e7\u05df \u05d4\u05d1\u05d9\u05e0\u05dc\u05d0\u05d5\u05de\u05d9, ISO 3, \u05d9\u05e9\u05d5 \u05d2\u05dd \u05d4\u05d1\u05d3\u05dc \u05d1\u05de\u05e9\u05de\u05e2\u05d5\u05ea \u05e9\u05dc \u05d4\u05de\u05e1\u05e4\u05e8\u05d9\u05dd."],[36.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05e4\u05e8\u05e7 \u05d0\u05ea \u05d4\u05e1\u05d9\u05de\u05d5\u05df \u05dc\u05d7\u05dc\u05e7\u05d9\u05dd, \u05d5\u05e0\u05e8\u05d0\u05d4 \u05d0\u05d9\u05e4\u05d4 \u05d1\u05d3\u05d9\u05d5\u05e7 \u05e0\u05de\u05e6\u05d0\u05d5\u05ea \u05d4\u05de\u05dc\u05dc\u05d5\u05d3\u05d5\u05ea."],[43.0,"\u05d4\u05d1\u05e1\u05d9\u05e1 \u05d4\u05d5\u05d0 \u05e7\u05d5 \u05d9\u05d9\u05d7\u05d5\u05e1 \u05d0\u05d5\u05e4\u05e7\u05d9, \u05d5\u05de\u05de\u05e0\u05d5 \u05d9\u05d5\u05e6\u05d0 \u05d7\u05e5 \u05d0\u05dc \u05d4\u05de\u05e4\u05e8\u05e7."],[48.0,"\u05e2\u05dc \u05e7\u05d5\u05d4\u05d9\u05d9\u05d7\u05d5\u05e1 \u05de\u05e6\u05d5\u05d9\u05e8 \u05d4\u05e1\u05de\u05dc \u05e9\u05dc \u05e1\u05d5\u05d2 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da, \u05d5\u05dc\u05d9\u05d3\u05d5 \u05d4\u05de\u05d9\u05d3\u05d5\u05ea."],[54.0,"\u05d1\u05e7\u05e6\u05d4 \u05d4\u05e9\u05e0\u05d9 \u05e9\u05dc \u05d4\u05e7\u05d5 \u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05d5\u05e4\u05d9\u05e2 \u05d6\u05e0\u05d1, \u05de\u05d6\u05dc\u05d2 \u05e7\u05d8\u05df. \u05d1\u05ea\u05d5\u05db\u05d5 \u05db\u05d5\u05ea\u05d1\u05d9\u05dd \u05d0\u05ea \u05d4\u05ea\u05d4\u05dc\u05d9\u05da \u05d0\u05d5 \u05d0\u05ea \u05d4\u05de\u05e4\u05e8\u05d8."],[63.0,"\u05d5\u05dc\u05d9\u05d3 \u05d4\u05d7\u05d9\u05d1\u05d5\u05e8 \u05e9\u05dc \u05d4\u05d7\u05e5 \u05dc\u05e7\u05d5 \u05d9\u05e9 \u05de\u05e7\u05d5\u05dd \u05dc\u05e9\u05e0\u05d9 \u05e1\u05d9\u05de\u05e0\u05d9\u05dd \u05de\u05d9\u05d5\u05d7\u05d3\u05d9\u05dd: \u05e2\u05d9\u05d2\u05d5\u05dc,"],[69.0,"\u05e9\u05e4\u05d9\u05e8\u05d5\u05e9\u05d5 \u05e8\u05d9\u05ea\u05d5\u05da \u05de\u05e1\u05d1\u05d9\u05d1, \u05d5\u05d3\u05d2\u05dc\u05d5\u05df, \u05e9\u05e4\u05d9\u05e8\u05d5\u05e9\u05d5 \u05e8\u05d9\u05ea\u05d5\u05da \u05d1\u05e9\u05d8\u05d7, \u05d1\u05d6\u05de\u05df \u05d4\u05d4\u05e8\u05db\u05d1\u05d4."],[77.0,"\u05de\u05e9\u05d5\u05dc\u05e9 \u05d4\u05d5\u05d0 \u05e8\u05d9\u05ea\u05d5\u05da \u05e4\u05d9\u05e0\u05d4, \u05d4\u05e0\u05e4\u05d5\u05e5 \u05d1\u05d9\u05d5\u05ea\u05e8."],[81.0,"\u05e1\u05de\u05dc \u05d1\u05e6\u05d5\u05e8\u05ea \u05d5\u05d9 \u05d4\u05d5\u05d0 \u05e8\u05d9\u05ea\u05d5\u05da \u05d7\u05e8\u05d9\u05e5 \u05e2\u05dd \u05e9\u05e0\u05d9 \u05e9\u05d9\u05e4\u05d5\u05e2\u05d9\u05dd. \u05e7\u05d5 \u05d9\u05e9\u05e8\u05d5\u05d7\u05e6\u05d9\u05d5\u05d9\u05d4\u05dd \u05d7\u05e8\u05d9\u05e5 \u05e2\u05dd \u05e9\u05d9\u05e4\u05d5\u05e2 \u05d0\u05d7\u05d3."],[90.0,"\u05e9\u05e0\u05d9 \u05e7\u05d5\u05d5\u05d9\u05dd \u05de\u05e7\u05d1\u05d9\u05dc\u05d9\u05dd \u05d4\u05dd \u05e8\u05d9\u05ea\u05d5\u05da \u05e7\u05e6\u05d4 \u05d9\u05e9\u05e8, \u05d1\u05dc\u05d9 \u05d4\u05db\u05e0\u05d4."],[95.0,"\u05d9\u05e9 \u05d2\u05dd \u05e1\u05de\u05dc\u05d9\u05dd \u05dc\u05d7\u05e8\u05d9\u05e5 \u05d1\u05e6\u05d5\u05e8\u05ea U \u05d5-\u05e0, \u05dc\u05e8\u05d9\u05ea\u05d5\u05da \u05e4\u05e7\u05e7, \u05dc\u05e8\u05d9\u05ea\u05d5\u05da \u05e0\u05e7\u05d5\u05d3\u05d4 \u05d5\u05dc\u05e8\u05d9\u05ea\u05d5\u05da \u05ea\u05e4\u05e8."],[103.0,"\u05d5\u05e1\u05d9\u05de\u05e0\u05d9\u05dd \u05e0\u05d5\u05e1\u05e4\u05d9\u05dd \u05de\u05e2\u05dc \u05d4\u05e1\u05de\u05dc \u05e7\u05d5\u05d1\u05e2\u05d9\u05dd \u05d0\u05ea \u05e6\u05d5\u05e8\u05ea \u05d4\u05e1\u05e0\u05d9\u05dd \u05e9\u05dc \u05d4\u05e8\u05d9\u05ea\u05d5\u05da: \u05e9\u05d8\u05d5\u05d7,"],[110.0,"\u05e7\u05de\u05d5\u05e8 \u05d0\u05d5 \u05e7\u05e2\u05d5\u05e8, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d0\u05d5\u05ea \u05e9\u05d0\u05d5\u05de\u05e8\u05ea \u05d0\u05d9\u05da \u05dc\u05d2\u05de\u05d5\u05e8 \u05d0\u05d5\u05ea\u05d5, \u05dc\u05de\u05e9\u05dc 6 \u05dc\u05d4\u05e9\u05d7\u05d6\u05d4."],[118.0,"\u05db\u05d0\u05df \u05e0\u05de\u05e6\u05d0\u05ea \u05d4\u05de\u05dc\u05db\u05d5\u05d3\u05ea \u05d4\u05d2\u05d3\u05d5\u05dc\u05d4. \u05d4\u05d7\u05e5 \u05de\u05e6\u05d1\u05d9\u05e2 \u05e2\u05dc \u05de\u05e4\u05e8\u05e7, \u05d5\u05dc\u05de\u05e4\u05e8\u05e7\u05d9\u05e9 \u05e9\u05e0\u05d9 \u05e6\u05d3\u05d3\u05d9\u05dd."],[126.0,"\u05d1\u05ea\u05e7\u05df \u05d4\u05d0\u05de\u05e8\u05d9\u05e7\u05d0\u05d9: \u05e1\u05de\u05dc \u05e9\u05de\u05e6\u05d5\u05d9\u05e8 \u05de\u05ea\u05d7\u05ea \u05dc\u05e7\u05d5 \u05d4\u05d9\u05d9\u05d7\u05d5\u05e1 \u05d4\u05d5\u05d0 \u05d1\u05e6\u05d3 \u05e9\u05d4\u05d7\u05e5 \u05de\u05e6\u05d1\u05d9\u05e2 \u05e2\u05dc\u05d9\u05d5. \u05e1\u05de\u05dc \u05de\u05e2\u05dc \u05d4\u05e7\u05d5 \u05d4\u05d5\u05d0 \u05d1\u05e6\u05d3 \u05d4\u05e9\u05e0\u05d9."],[137.0,"\u05e1\u05de\u05dc \u05de\u05e9\u05e0\u05d9 \u05e6\u05d3\u05d9 \u05d4\u05e7\u05d5 \u05e4\u05d9\u05e8\u05d5\u05e9\u05d5 \u05e8\u05d9\u05ea\u05d5\u05da \u05de\u05e9\u05e0\u05d9 \u05d4\u05e6\u05d3\u05d3\u05d9\u05dd."],[142.0,"\u05d1\u05ea\u05e7\u05df ISO \u05d9\u05e9 \u05e9\u05ea\u05d9 \u05e9\u05d9\u05d8\u05d5\u05ea. \u05e9\u05d9\u05d8\u05d4 \u05de\u05e9\u05ea\u05de\u05e9\u05d5\u05ea \u05d1\u05e7\u05d5 \u05d9\u05d9\u05d7\u05d5\u05e1 \u05db\u05e4\u05d5\u05dc: \u05e7\u05d5 \u05de\u05dc\u05d0 \u05d5\u05e7\u05d5 \u05de\u05e7\u05d5\u05d5\u05e7\u05d5 \u05de\u05ea\u05d7\u05ea\u05d9\u05d5."],[151.0,"\u05d1\u05e9\u05d9\u05d8\u05d4 \u05d2), \u05e1\u05de\u05dc \u05e2\u05dc \u05d4\u05e7\u05d5 \u05d4\u05de\u05dc\u05d0 \u05d4\u05d5\u05d0 \u05d1\u05e6\u05d3 \u05d4\u05d7\u05e5, \u05d5\u05e1\u05de\u05dc \u05e2\u05dc \u05d4\u05e7\u05d5 \u05d4\u05de\u05e7\u05d5\u05d5\u05e7\u05d5 \u05d4\u05d5\u05d0 \u05d1\u05e6\u05d3 \u05d4\u05e9\u05e0\u05d9."],[160.0,"\u05e9\u05d9\u05d8\u05d4 8 \u05e9\u05dc ISO \u05e2\u05d5\u05d1\u05d3\u05ea \u05e2\u05dd \u05e7\u05d5 \u05d0\u05d7\u05d3, \u05db\u05de\u05d5 \u05d4\u05ea\u05e7\u05df \u05d4\u05d0\u05de\u05e8\u05d9\u05e7\u05d0\u05d9."],[166.0,"\u05dc\u05db\u05df \u05db\u05e9\u05e8\u05d5\u05d0\u05d9\u05dd \u05e7\u05d5 \u05db\u05e4\u05d5\u05dc, \u05d6\u05d4 \u05e9\u05e8\u05d8\u05d5\u05d8 ISO \u05d1\u05e9\u05d9\u05d8\u05d4 \u05d2\u05d0, \u05d5\u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05dc\u05e4\u05d9 \u05d4\u05e7\u05d5 \u05d4\u05de\u05dc\u05d0, \u05d5\u05dc\u05d0 \u05dc\u05e4\u05d9 \u05dc\u05de\u05e2\u05dc\u05d4 \u05d5\u05dc\u05de\u05d8\u05d4."],[175.0,"\u05de\u05d9 \u05e9\u05e7\u05d5\u05e8\u05d0 \u05e9\u05e8\u05d8\u05d5\u05d8 \u05db\u05d6\u05d4 \u05d1\u05e2\u05d9\u05e0\u05d9\u05d9\u05dd \u05d0\u05de\u05e8\u05d9\u05e7\u05d0\u05d9\u05d5\u05ea, \u05d9\u05e8\u05ea\u05da \u05d1\u05e6\u05d3 \u05d4\u05dc\u05d0 \u05e0\u05db\u05d5\u05df."],[182.0,"\u05d1\u05ea\u05e7\u05df \u05d4\u05d0\u05de\u05e8\u05d9\u05e7\u05d0\u05d9, \u05d4\u05de\u05e1\u05e4\u05e8 \u05de\u05e9\u05de\u05d0\u05dc \u05dc\u05de\u05e9\u05d5\u05dc\u05e9 \u05d4\u05d5\u05d0 \u05d0\u05d5\u05e8\u05da \u05d4\u05e8\u05d2\u05dc \u05e9\u05dc \u05e8\u05d9\u05ea\u05d5\u05da \u05d4\u05e4\u05d9\u05e0\u05d4."],[188.0,"\u05d1\u05ea\u05e7\u05df ISO \u05d7\u05d9\u05d9\u05d1\u05ea \u05dc\u05d4\u05d5\u05e4\u05d9\u05e2 \u05d0\u05d5\u05ea \u05dc\u05e4\u05e0\u05d9 \u05d4\u05de\u05e1\u05e4\u05e8: 8 \u05dc\u05e2\u05d5\u05d1\u05d9 \u05d4\u05d2\u05e8\u05d5\u05df, \u05d0\u05d5 2 \u05dc\u05d0\u05d5\u05e8\u05da \u05d4\u05e8\u05d2\u05dc."],[197.0,"\u05d5\u05d4\u05d4\u05d1\u05d3\u05dc \u05d2\u05d3\u05d5\u05dc: 45 \u05e4\u05d9\u05e8\u05d5\u05e9\u05d5 \u05e2\u05d5\u05d1\u05d9 \u05d2\u05e8\u05d5\u05df \u05e9\u05dc \u05d7\u05de\u05d9\u05e9\u05d4 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8, \u05d5\u05e8\u05d2\u05dc \u05e9\u05dc \u05d1\u05e2\u05e8\u05da \u05e9\u05d1\u05e2\u05d4 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8."],[207.0,"\u05de\u05d9 \u05e9\u05de\u05e8\u05ea\u05da \u05e8\u05d2\u05dc \u05e9\u05dc \u05d7\u05de\u05d9\u05e9\u05d4 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8 \u05db\u05e9\u05db\u05ea\u05d5\u05d1 \u05e484, \u05de\u05d9\u05d9\u05e6\u05e8 \u05e8\u05d9\u05ea\u05d5\u05da \u05d7\u05dc\u05e9 \u05d1\u05e2\u05e8\u05da \u05d1\u05e9\u05dc\u05d5\u05e9\u05d9\u05dd \u05d0\u05d7\u05d5\u05d6 \u05de\u05de\u05d4 \u05e9\u05ea\u05d5\u05db\u05e0\u05df."],[217.0,"\u05d5\u05de\u05e1\u05e4\u05e8 \u05d1\u05dc\u05d9 \u05d0\u05d5\u05ea \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 ISO \u05d4\u05d5\u05d0 \u05e9\u05d0\u05dc\u05d4 \u05dc\u05de\u05ea\u05db\u05e0\u05df, \u05d5\u05dc\u05d0 \u05e0\u05d9\u05d7\u05d5\u05e9."],[223.0,"\u05de\u05d9\u05de\u05d9\u05df \u05dc\u05e1\u05de\u05dc \u05db\u05d5\u05ea\u05d1\u05d9\u05dd \u05d0\u05ea \u05d0\u05d5\u05e8\u05da \u05d4\u05e8\u05d9\u05ea\u05d5\u05da. \u05d1\u05dc\u05d9 \u05d0\u05d5\u05e8\u05da, \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05d4\u05d5\u05d0 \u05dc\u05db\u05dc \u05d0\u05d5\u05e8\u05da \u05d4\u05de\u05e4\u05e8\u05e7."],[231.0,"\u05d1\u05e8\u05d9\u05ea\u05d5\u05da \u05dc\u05e1\u05d9\u05e8\u05d5\u05d2\u05d9\u05df, \u05d1\u05ea\u05e7\u05df \u05d4\u05d0\u05de\u05e8\u05d9\u05e7\u05d0\u05d9, \u05db\u05d5\u05ea\u05d1\u05d9\u05dd \u05d0\u05d5\u05e8\u05da \u05d5\u05e4\u05e1\u05d9\u05e2\u05d4: 50-150,"],[239.0,"\u05db\u05dc\u05d5\u05de\u05e8 \u05e7\u05d8\u05e2\u05d9\u05dd \u05e9\u05dc \u05d7\u05de\u05d9\u05e9\u05d9\u05dd \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8, \u05db\u05dc \u05de\u05d0\u05d4 \u05d5\u05d7\u05de\u05d9\u05e9\u05d9\u05dd, \u05de\u05e8\u05db\u05d6 \u05dc\u05de\u05e8\u05db\u05d6."],[246.0,"\u05d1\u05ea\u05e7\u05df ISO \u05d4\u05db\u05ea\u05d9\u05d1\u05d4 \u05e9\u05d5\u05e0\u05d4: \u05de\u05e1\u05e4\u05e8 \u05d4\u05e7\u05d8\u05e2\u05d9\u05dd, \u05db\u05e4\u05d5\u05dc \u05d4\u05d0\u05d5\u05e8\u05da, \u05d5\u05d1\u05e1\u05d5\u05d2\u05e8\u05d9\u05d9\u05dd \u05d4\u05de\u05e8\u05d5\u05d7\u05d5\u05d7 \u05d1\u05d9\u05df \u05d4\u05e7\u05d8\u05e2\u05d9\u05dd."],[256.0,"\u05db\u05dc\u05d5\u05de\u05e8, \u05d4\u05de\u05e1\u05e4\u05e8 \u05d1\u05e1\u05d5\u05d2\u05e8\u05d9\u05d9\u05dd \u05d1\u05ea\u05e7\u05df ISO \u05d4\u05d5\u05d0 \u05d4\u05de\u05e8\u05d5\u05d5\u05d7 \u05d1\u05d9\u05df \u05e7\u05e6\u05d4 \u05dc\u05e7\u05e6\u05d4, \u05d5\u05dc\u05d0 \u05de\u05e8\u05db\u05d6 \u05dc\u05de\u05e8\u05db\u05d6."],[264.0,"\u05de\u05d9 \u05e9\u05de\u05ea\u05d1\u05dc\u05d1\u05dc \u05d1\u05d9\u05df \u05d4\u05e9\u05e0\u05d9\u05d9\u05dd, \u05de\u05e7\u05d1\u05dc \u05de\u05e1\u05e4\u05e8 \u05d0\u05d7\u05e8 \u05e9\u05dc \u05e7\u05d8\u05e2\u05d9\u05dd, \u05d5\u05d0\u05d5\u05e8\u05da \u05e8\u05d9\u05ea\u05d5\u05da \u05db\u05d5\u05dc\u05dc \u05d0\u05d7\u05e8."],[271.0,"\u05d1\u05e8\u05d9\u05ea\u05d5\u05da \u05d7\u05e8\u05d9\u05e5, \u05d4\u05de\u05e1\u05e4\u05e8\u05d9\u05dd \u05de\u05ea\u05d0\u05e8\u05d9\u05dd \u05d0\u05ea \u05d4\u05d4\u05db\u05e0\u05d4 \u05d5\u05d0\u05ea \u05d4\u05d7\u05d3\u05d9\u05e8\u05d4."],[276.0,"\u05dc\u05d9\u05d3\u05d5 \u05e2\u05d5\u05d1\u05d9 \u05d4\u05d2\u05e8\u05d5\u05df \u05d4\u05d0\u05e4\u05e7\u05d8\u05d9\u05d1\u05d9, \u05db\u05dc\u05d5\u05de\u05e8 \u05e2\u05d3 \u05db\u05de\u05d4 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05d7\u05d5\u05d3\u05e8."],[287.0,"\u05d1\u05ea\u05d5\u05da \u05d4\u05e1\u05de\u05dc \u05dc\u05db\u05d5\u05ea\u05d1\u05d9\u05dd \u05d0\u05ea \u05e4\u05ea\u05d7 \u05d4\u05e2\u05d5\u05d5\u05e8\u05e2\u05d5, \u05d5\u05de\u05e2\u05dc\u05d9\u05d5 \u05d0\u05ea \u05d6\u05d5\u05d5\u05d9\u05ea \u05d4\u05d7\u05e8\u05d9\u05e5."],[293.0,"\u05d5\u05db\u05e9\u05d7\u05e1\u05e8\u05d4 \u05d3\u05e8\u05d9\u05e9\u05ea \u05d7\u05d3\u05d9\u05e8\u05d4, \u05dc\u05d0 \u05d1\u05e8\u05d5\u05e8 \u05d0\u05dd \u05e0\u05d3\u05e8\u05e9\u05d5\u05ea \u05d7\u05d3\u05d9\u05e8\u05d4 \u05de\u05dc\u05d0\u05d4 \u05d0\u05d5 \u05d7\u05dc\u05e7\u05d9\u05ea, \u05d5\u05d6\u05d4 \u05d4\u05d1\u05d3\u05dc \u05e2\u05e6\u05d5\u05dd \u05d1\u05d7\u05d5\u05d6\u05e7 \u05d5\u05d1\u05e2\u05dc\u05d5\u05ea."],[302.0,"\u05d1\u05d6\u05e0\u05d1 \u05db\u05d5\u05ea\u05d1\u05d9\u05dd \u05d0\u05ea \u05ea\u05d4\u05dc\u05d9\u05da \u05d4\u05e8\u05d9\u05ea\u05d5\u05da, \u05dc\u05de\u05e9\u05dc \u05e1\u05d5\u05d3 \u05d0\u05d5 MIG, \u05d0\u05d5 \u05de\u05e1\u05e4\u05e8 \u05ea\u05d4\u05dc\u05d9\u05da \u05dc\u05e4\u05d9 ISO, \u05db\u05de\u05d5 141 \u05dc-\u05e1\u05d51."],[316.0,"\u05dc\u05e2\u05d9\u05ea\u05d9\u05dd \u05e7\u05e8\u05d5\u05d1\u05d5\u05ea \u05d4\u05d6\u05e0\u05d1 \u05de\u05e4\u05e0\u05d4 \u05dc\u05de\u05e4\u05e8\u05d8 \u05e8\u05d9\u05ea\u05d5\u05da, 5\u05dd!), \u05e9\u05de\u05d2\u05d3\u05d9\u05e8 \u05d0\u05ea \u05db\u05dc \u05d4\u05e4\u05e8\u05de\u05d8\u05e8\u05d9\u05dd."],[324.0,"\u05e7\u05d5\u05d1\u05e2 \u05ea\u05e7\u05df \u05d0\u05d9\u05db\u05d5\u05ea, \u05db\u05de\u05d5 5817 50\u05d5, \u05e2\u05dd \u05e8\u05de\u05d5\u05ea \u05d0\u05d9\u05db\u05d5\u05ea 6 ,\u05dd \u05d5- \u05dd."],[337.0,"\u05d5\u05d0\u05dd \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05dc\u05d0 \u05de\u05e4\u05e0\u05d4 \u05dc\u05ea\u05e7\u05df \u05d0\u05d9\u05db\u05d5\u05ea, \u05d0\u05d9\u05df \u05d4\u05d2\u05d3\u05e8\u05d4 \u05dc\u05e7\u05d1\u05dc\u05ea \u05d4\u05e8\u05d9\u05ea\u05d5\u05da, \u05d5\u05e6\u05e8\u05d9\u05da \u05dc\u05e9\u05d0\u05d5\u05dc."],[344.0,"\u05d1\u05ea\u05e7\u05df \u05d4\u05d0\u05de\u05e8\u05d9\u05e7\u05d0\u05d9 \u05d9\u05e9 \u05d2\u05dd \u05e1\u05d9\u05de\u05d5\u05df \u05dc\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05dc\u05d0 \u05d4\u05d5\u05e8\u05e1\u05d5\u05ea, \u05d1\u05d0\u05d5\u05ea\u05d5 \u05de\u05d1\u05e0\u05d4 \u05e9\u05dc \u05e7\u05d5 \u05d5\u05d7\u05e5."],[351.0,"\u05e8\u05d0\u05e9\u05d9\u05ea\u05d9\u05d1\u05d5\u05ea \u05db\u05de\u05d5 \u05d68 \u05dc\u05e8\u05d3\u05d9\u05d5\u05d2\u05e8\u05e4\u05d9\u05d4, \u05d3\u05d8 \u05dc\u05d0\u05d5\u05dc\u05d8\u05e8\u05e1\u05d5\u05e0\u05d9\u05e7,"],[357.0,"\u05d6\u05d5\u05d0 \u05dc\u05d7\u05dc\u05e7\u05d9\u05e7\u05d9\u05dd \u05de\u05d2\u05e0\u05d8\u05d9\u05d9\u05dd, \u05d3\u05dd \u05dc\u05d7\u05d5\u05de\u05e8 \u05d7\u05d5\u05d3\u05e8 \u05d5-\u05d3\u05e5 \u05dc\u05d1\u05d3\u05d9\u05e7\u05d4 \u05d7\u05d6\u05d5\u05ea\u05d9\u05ea."],[365.0,"\u05d4\u05e1\u05d9\u05de\u05d5\u05df \u05d4\u05d6\u05d4 \u05d0\u05d5\u05de\u05e8 \u05de\u05d4 \u05dc\u05d1\u05d3\u05d5\u05e7 \u05d5\u05d0\u05d9\u05e4\u05d4, \u05d5\u05dc\u05d0 \u05d0\u05d9\u05da \u05dc\u05d4\u05d7\u05dc\u05d9\u05d8 \u05d0\u05dd \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05ea\u05e7\u05d9\u05df."],[371.0,"\u05d2\u05dd \u05d0\u05ea \u05d6\u05d4 \u05e7\u05d5\u05d1\u05e2 \u05d4\u05ea\u05e7\u05df \u05e9\u05d0\u05dc\u05d9\u05d5 \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05de\u05e4\u05e0\u05d4."],[375.0,"\u05e8\u05d9\u05db\u05d5\u05d6 \u05d4\u05de\u05dc\u05db\u05d5\u05d3\u05d5\u05ea \u05d1\u05e1\u05d9\u05de\u05d5\u05df \u05e8\u05d9\u05ea\u05d5\u05da."],[378.0,"\u05e8\u05d0\u05e9\u05d5\u05e0\u05d4: \u05e6\u05d3 \u05d4\u05d7\u05e5. \u05e7\u05d5\u05d3\u05dd \u05de\u05d6\u05d4\u05d9\u05dd \u05d0\u05dd \u05d6\u05d4 \u05e9\u05e8\u05d8\u05d5\u05d8 \u05d0\u05de\u05e8\u05d9\u05e7\u05d0\u05d9 \u05d0\u05d5 50\u05d5, \u05d5\u05d0\u05dd \u05d9\u05e9 \u05e7\u05d5 \u05db\u05e4\u05d5\u05dc."],[387.0,"\u05e9\u05e0\u05d9\u05d9\u05d4: \u05d2\u05d5\u05d3\u05dc \u05e8\u05d9\u05ea\u05d5\u05da \u05d4\u05e4\u05d9\u05e0\u05d4. \u05d1\u05ea\u05e7\u05df ISO \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d0\u05dd \u05db\u05ea\u05d5\u05d1 8 \u05d0\u05d5 7."],[394.0,"\u05e9\u05dc\u05d9\u05e9\u05d9\u05ea: \u05e8\u05d9\u05ea\u05d5\u05da \u05dc\u05e1\u05d9\u05e8\u05d5\u05d2\u05d9\u05df. \u05e4\u05e1\u05d9\u05e2\u05d4 \u05de\u05e8\u05db\u05d6 \u05dc\u05de\u05e8\u05db\u05d6, \u05de\u05d5\u05dc \u05de\u05e8\u05d5\u05d5\u05d7 \u05d1\u05d9\u05df \u05e7\u05d8\u05e2\u05d9\u05dd."],[401.0,"\u05e8\u05d1\u05d9\u05e2\u05d9\u05ea: \u05e2\u05d9\u05d2\u05d5\u05dc \u05d5\u05d3\u05d2\u05dc\u05d5\u05df \u05e7\u05d8\u05e0\u05d9\u05dd, \u05e9\u05e7\u05dc \u05dc\u05e4\u05e1\u05e4\u05e1, \u05d5\u05de\u05e9\u05e0\u05d9\u05dd \u05d0\u05ea \u05d4\u05d9\u05e7\u05e3 \u05d4\u05e2\u05d1\u05d5\u05d3\u05d4."],[408.0,"\u05d5\u05d7\u05de\u05d9\u05e9\u05d9\u05ea: \u05e9\u05e8\u05d8\u05d5\u05d8 \u05e8\u05d9\u05ea\u05d5\u05da \u05d4\u05d5\u05d0 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05e9\u05e8\u05d8\u05d5\u05d8 \u05d4\u05e8\u05db\u05d1\u05d4, \u05d5\u05db\u05dc \u05e8\u05d9\u05ea\u05d5\u05da \u05de\u05ea\u05d9\u05d9\u05d7\u05e1 \u05dc\u05e9\u05e0\u05d9 \u05d7\u05dc\u05e7\u05d9\u05dd \u05e9\u05e6\u05e8\u05d9\u05da \u05dc\u05d6\u05d4\u05d5\u05ea."],[418.0,"\u05e1\u05d9\u05de\u05d5\u05df \u05e8\u05d9\u05ea\u05d5\u05da \u05d1\u05e0\u05d5\u05d9 \u05de\u05e7\u05d5 \u05d9\u05d9\u05d7\u05d5\u05e1, \u05d7\u05e5, \u05e1\u05de\u05dc, \u05de\u05d9\u05d3\u05d5\u05ea \u05d5\u05d6\u05e0\u05d1."],[424.0,"\u05d1\u05ea\u05e7\u05df \u05d4\u05d0\u05de\u05e8\u05d9\u05e7\u05d0\u05d9, \u05de\u05ea\u05d7\u05ea \u05dc\u05e7\u05d5 \u05d6\u05d4 \u05e6\u05d3 \u05d4\u05d7\u05e5. \u05d1\u05ea\u05e7\u05df ISO \u05d1\u05e9\u05d9\u05d8\u05d4 \\), \u05d4\u05e7\u05d5 \u05d4\u05de\u05dc\u05d0 \u05d4\u05d5\u05d0 \u05e6\u05d3 \u05d4\u05d7\u05e5."],[435.0,"\u05d1\u05ea\u05e7\u05df ISO, \u05d4\u05d5\u05d0 \u05e2\u05d5\u05d1\u05d9 \u05d2\u05e8\u05d5\u05df \u05d5-2 \u05d4\u05d5\u05d0 \u05d0\u05d5\u05e8\u05da \u05e8\u05d2\u05dc, \u05d5-85 \u05e9\u05d5\u05d5\u05d4 \u05dc\u05e8\u05d2\u05dc \u05e9\u05dc \u05d1\u05e2\u05e8\u05da \u05e9\u05d1\u05e2\u05d4."],[444.0,"\u05d1\u05e8\u05d9\u05ea\u05d5\u05da \u05dc\u05e1\u05d9\u05e8\u05d5\u05d2\u05d9\u05df, \u05e4\u05e1\u05d9\u05e2\u05d4 \u05d0\u05de\u05e8\u05d9\u05e7\u05d0\u05d9\u05ea \u05d4\u05d9\u05d0 \u05de\u05e8\u05db\u05d6 \u05dc\u05de\u05e8\u05db\u05d6, \u05d5\u05d4\u05de\u05e1\u05e4\u05e8 \u05d1\u05e1\u05d5\u05d2\u05e8\u05d9\u05d9\u05dd \u05d1\u05ea\u05e7\u05df ISO \u05d4\u05d5\u05d0 \u05de\u05e8\u05d5\u05d5\u05d7 \u05d1\u05d9\u05df \u05e7\u05d8\u05e2\u05d9\u05dd."],[454.0,"\u05d5\u05d4\u05d0\u05d9\u05db\u05d5\u05ea \u05e0\u05e7\u05d1\u05e2\u05ea \u05d1\u05ea\u05e7\u05df \u05e0\u05e4\u05e8\u05d3, \u05dc\u05d0 \u05d1\u05e1\u05d9\u05de\u05d5\u05df."],[458.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05e7\u05e8\u05d0 \u05d0\u05ea \u05d4\u05d7\u05d5\u05de\u05e8, \u05d8\u05d9\u05e4\u05d5\u05dc \u05d4\u05d7\u05d5\u05dd \u05d5\u05d4\u05e6\u05d9\u05e4\u05d5\u05d9 \u05e9\u05d1\u05e9\u05e8\u05d8\u05d5\u05d8. \u05e0\u05ea\u05e8\u05d0\u05d4 \u05d1\u05e4\u05e8\u05e7 \u05e9\u05dc\u05d5\u05e9 \u05e2\u05e9\u05e8\u05d4."]]};
window.MH_TR["ch13"]={"t":"\u05d7\u05d5\u05de\u05e8, \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05d5\u05e6\u05d9\u05e4\u05d5\u05d9","l":[[1.0,"\u05e9\u05e0\u05d9 \u05d7\u05dc\u05e7\u05d9\u05dd \u05d9\u05db\u05d5\u05dc\u05d9\u05dd \u05dc\u05d4\u05d9\u05d5\u05ea \u05d6\u05d4\u05d9\u05dd \u05d1\u05de\u05d9\u05d3\u05d5\u05ea, \u05d5\u05e9\u05d5\u05e0\u05d9\u05dd \u05dc\u05d2\u05de\u05e8\u05d9 \u05d1\u05d7\u05d5\u05d6\u05e7, \u05d1\u05e7\u05e9\u05d9\u05d5\u05ea \u05d5\u05d1\u05e2\u05de\u05d9\u05d3\u05d5\u05ea."],[9.0,"\u05d4\u05d4\u05d1\u05d3\u05dc \u05db\u05ea\u05d5\u05d1 \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8, \u05d0\u05d1\u05dc \u05dc\u05d0 \u05d1\u05e6\u05d9\u05d5\u05e8: \u05d1\u05d0\u05d6\u05d5\u05e8 \u05d4\u05db\u05d5\u05ea\u05e8\u05ea \u05d5\u05d1\u05d4\u05e2\u05e8\u05d5\u05ea."],[15.0,"\u05d4\u05d7\u05d5\u05de\u05e8, \u05d4\u05de\u05e6\u05d1 \u05e9\u05dc\u05d5, \u05d8\u05d9\u05e4\u05d5\u05dc \u05d4\u05d7\u05d5\u05dd \u05d5\u05d4\u05e6\u05d9\u05e4\u05d5\u05d9 \u05d4\u05dd \u05d7\u05dc\u05e7 \u05de\u05d4\u05d4\u05d2\u05d3\u05e8\u05d4 \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7, \u05d1\u05d3\u05d9\u05d5\u05e7 \u05db\u05de\u05d5 \u05d4\u05de\u05d9\u05d3\u05d5\u05ea."],[24.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05dc\u05de\u05d3 \u05dc\u05e7\u05e8\u05d5\u05d0 \u05d0\u05ea \u05db\u05dc \u05d4\u05d4\u05d2\u05d3\u05e8\u05d5\u05ea \u05d4\u05d0\u05dc\u05d4, \u05d5\u05d1\u05d0\u05d9\u05d6\u05d4 \u05e1\u05d3\u05e8 \u05d4\u05df \u05d7\u05dc\u05d5\u05ea."],[31.0,"\u05d4\u05d7\u05d5\u05de\u05e8 \u05de\u05d5\u05e4\u05d9\u05e2 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05d0\u05d6\u05d5\u05e8 \u05d4\u05db\u05d5\u05ea\u05e8\u05ea, \u05d1\u05e9\u05d5\u05e8\u05d4 \u05e9\u05dc \u05d7\u05d5\u05de\u05e8."],[36.0,"\u05d4\u05d5\u05d0 \u05db\u05ea\u05d5\u05d1 \u05dc\u05e4\u05d9 \u05ea\u05e7\u05df \u05de\u05e1\u05d5\u05d9\u05dd: \u05dc\u05de\u05e9\u05dc 1.4404 \u05dc\u05e4\u05d9 \u05d4\u05ea\u05e7\u05df \u05d4\u05d0\u05d9\u05e8\u05d5\u05e4\u05d9, \u05d0\u05d5 !316 \u05dc\u05e4\u05d9 \u05d4\u05e9\u05d9\u05d8\u05d4 \u05d4\u05d0\u05de\u05e8\u05d9\u05e7\u05d0\u05d9\u05ea."],[50.0,"\u05dc\u05e2\u05d9\u05ea\u05d9\u05dd \u05e7\u05e8\u05d5\u05d1\u05d5\u05ea \u05de\u05d5\u05e4\u05d9\u05e2 \u05d2\u05dd \u05ea\u05e7\u05df \u05de\u05d5\u05e6\u05e8, \u05e9\u05de\u05d2\u05d3\u05d9\u05e8 \u05d0\u05ea \u05e6\u05d5\u05e8\u05ea \u05d4\u05d7\u05d5\u05de\u05e8 \u05d5\u05d0\u05ea \u05d4\u05ea\u05db\u05d5\u05e0\u05d5\u05ea \u05e9\u05dc\u05d5, \u05dc\u05de\u05e9\u05dc \u05dc\u05d5\u05d7, \u05de\u05d5\u05d8 \u05d0\u05d5 \u05e6\u05d9\u05e0\u05d5\u05e8."],[60.0,"\u05d1\u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05e8\u05d1\u05d5\u05ea, \u05d4\u05de\u05e6\u05d1 \u05d4\u05d5\u05d0 \u05d7\u05dc\u05e7 \u05de\u05d4\u05d7\u05d5\u05de\u05e8. \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd 1 \u05d1\u05de\u05e6\u05d1 16 \u05e9\u05d5\u05e0\u05d4 \u05de\u05d0\u05d5\u05d3 \u05de\u05d0\u05d5\u05ea\u05d5 \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d1\u05de\u05e6\u05d1 \u05e8\u05da."],[72.0,"\u05d5-1651 \u05d0\u05d5\u05de\u05e8 \u05de\u05e9\u05d4\u05d5 \u05e0\u05d5\u05e1\u05e3: \u05d4\u05d7\u05d5\u05de\u05e8 \u05e2\u05d1\u05e8 \u05de\u05ea\u05d9\u05d7\u05d4 \u05dc\u05d4\u05e4\u05d7\u05ea\u05ea \u05de\u05d0\u05de\u05e6\u05d9\u05dd, \u05d5\u05d6\u05d4 \u05de\u05e9\u05e4\u05d9\u05e2 \u05e2\u05dc \u05d4\u05e2\u05d9\u05d5\u05d5\u05ea \u05d1\u05e2\u05d9\u05d1\u05d5\u05d3."],[82.0,"\u05de\u05d9 \u05e9\u05de\u05d7\u05dc\u05d9\u05e3 \u05d7\u05d5\u05de\u05e8 \u05d1\u05d7\u05d5\u05de\u05e8 \u05e9\u05e0\u05e8\u05d0\u05d4 \u05dc\u05d5 \u05e9\u05d5\u05d5\u05d4 \u05e2\u05e8\u05da, \u05d1\u05dc\u05d9 \u05d0\u05d9\u05e9\u05d5\u05e8,"],[87.0,"\u05de\u05e9\u05e0\u05d4 \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7. \u05e9\u05d5\u05d5\u05d4 \u05e2\u05e8\u05da \u05d1\u05d9\u05df \u05ea\u05e7\u05e0\u05d9\u05dd \u05d4\u05d5\u05d0 \u05e7\u05e8\u05d5\u05d1, \u05dc\u05d0 \u05d6\u05d4\u05d4."],[92.0,"\u05d5\u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05e0\u05d3\u05e8\u05e9\u05d5\u05ea \u05d2\u05dd \u05ea\u05e2\u05d5\u05d3\u05ea \u05d7\u05d5\u05de\u05e8, \u05dc\u05de\u05e9\u05dc \u05dc\u05e4\u05d9 \u05d0\u05dd 4 \u05e1\u05d5\u05d2 3.1,"],[101.0,"\u05e9\u05de\u05d5\u05db\u05d9\u05d7\u05d4 \u05e9\u05d4\u05d7\u05d5\u05de\u05e8 \u05d1\u05e4\u05d5\u05e2\u05dc \u05d4\u05d5\u05d0 \u05d4\u05d7\u05d5\u05de\u05e8 \u05e9\u05d1\u05e9\u05e8\u05d8\u05d5\u05d8."],[107.0,"\u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05de\u05d5\u05e4\u05d9\u05e2 \u05d1\u05d4\u05e2\u05e8\u05d4, \u05d5\u05de\u05d2\u05d3\u05d9\u05e8 \u05de\u05d4 \u05d4\u05d7\u05dc\u05e7 \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d9\u05d5\u05ea \u05d0\u05d7\u05e8\u05d9 \u05d4\u05d8\u05d9\u05e4\u05d5\u05dc, \u05d5\u05dc\u05d0 \u05e8\u05e7 \u05d0\u05d9\u05d6\u05d4 \u05d8\u05d9\u05e4\u05d5\u05dc \u05dc\u05e2\u05e9\u05d5\u05ea."],[116.0,"\u05d4\u05d3\u05e8\u05d9\u05e9\u05d4 \u05d4\u05e0\u05e4\u05d5\u05e6\u05d4 \u05d4\u05d9\u05d0 \u05e7\u05e9\u05d9\u05d5\u05ea \u05d1\u05ea\u05d7\u05d5\u05dd, \u05dc\u05de\u05e9\u05dc \u05d0\u05e8\u05d1\u05e2\u05d9\u05dd \u05e2\u05d3 \u05d0\u05e8\u05d1\u05e2\u05d9\u05dd \u05d5\u05d7\u05de\u05e9 \u05d1\u05e1\u05e7\u05d0\u05dc\u05ea \u05e8\u05d5\u05e7\u05d5\u05d5\u05dc C."],[125.0,"\u05e2\u05d5\u05de\u05e7 \u05d4\u05e9\u05db\u05d1\u05d4 \u05d4\u05de\u05d5\u05e7\u05e9\u05d9\u05ea, \u05d5\u05d1\u05d0\u05e1\u05d5\u05e7\u05e9\u05d9\u05d5\u05ea \u05e0\u05de\u05d3\u05d3 \u05d4\u05e2\u05d5\u05de\u05e7 \u05d4\u05d6\u05d4."],[135.0,"\u05db\u05e9\u05e8\u05e7 \u05d7\u05dc\u05e7 \u05de\u05d4\u05de\u05e9\u05d8\u05d7 \u05de\u05d5\u05e7\u05e9\u05d4, \u05d4\u05d0\u05d6\u05d5\u05e8 \u05de\u05e1\u05d5\u05de\u05df \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d1\u05e7\u05d5 \u05e2\u05d1\u05d4 \u05e9\u05dc \u05e7\u05d5 \u05d5\u05e0\u05e7\u05d5\u05d3\u05d4, \u05dc\u05e4\u05d9 15787 50!."],[147.0,"\u05d5\u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05de\u05e1\u05d5\u05de\u05df \u05d2\u05dd \u05d4\u05de\u05e7\u05d5\u05dd \u05e9\u05d1\u05d5 \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d0\u05ea \u05d4\u05e7\u05e9\u05d9\u05d5\u05ea, \u05db\u05d9 \u05d1\u05d7\u05dc\u05e7 \u05d2\u05d3\u05d5\u05dc \u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05dc\u05d0 \u05d0\u05d7\u05d9\u05d3\u05d4."],[155.0,"\u05d3\u05e8\u05d9\u05e9\u05ea \u05e7\u05e9\u05d9\u05d5\u05ea \u05d1\u05dc\u05d9 \u05de\u05e7\u05d5\u05dd \u05d1\u05d3\u05d9\u05e7\u05d4 \u05d4\u05d9\u05d0 \u05d7\u05e1\u05e8\u05d4, \u05db\u05d9 \u05db\u05dc \u05e0\u05e7\u05d5\u05d3\u05d4 \u05d1\u05d7\u05dc\u05e7 \u05d9\u05db\u05d5\u05dc\u05d4 \u05dc\u05ea\u05ea \u05ea\u05d5\u05e6\u05d0\u05d4 \u05d0\u05d7\u05e8\u05ea."],[163.0,"\u05d9\u05e9 \u05db\u05de\u05d4 \u05e1\u05e7\u05d0\u05dc\u05d5\u05ea \u05e7\u05e9\u05d9\u05d5\u05ea, \u05d5\u05db\u05dc \u05d0\u05d7\u05ea \u05e0\u05de\u05d3\u05d3\u05ea \u05d1\u05e9\u05d9\u05d8\u05d4 \u05d0\u05d7\u05e8\u05ea."],[168.0,"\u05e8\u05d5\u05e7\u05d5\u05d5\u05dc 6 \u05dc\u05e4\u05dc\u05d3\u05d5\u05ea \u05e7\u05e9\u05d5\u05ea, \u05d1\u05e8\u05d9\u05e0\u05dc \u05dc\u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05e8\u05db\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8 \u05d5\u05dc\u05d9\u05e6\u05d9\u05e7\u05d5\u05ea, \u05d5\u05d5\u05d9\u05e7\u05e8\u05e1 \u05dc\u05e9\u05db\u05d1\u05d5\u05ea \u05d3\u05e7\u05d5\u05ea \u05d5\u05dc\u05de\u05d3\u05d9\u05d3\u05d5\u05ea \u05d1\u05de\u05e2\u05d1\u05d3\u05d4."],[178.0,"\u05d9\u05e9 \u05d8\u05d1\u05dc\u05d0\u05d5\u05ea \u05d4\u05de\u05e8\u05d4 \u05d1\u05d9\u05df \u05d4\u05e1\u05e7\u05d0\u05dc\u05d5\u05ea, \u05d0\u05d1\u05dc \u05d4\u05d4\u05de\u05e8\u05d4 \u05de\u05e9\u05d5\u05e2\u05e8\u05ea."],[183.0,"\u05dc\u05db\u05df \u05db\u05e9\u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d3\u05d5\u05e8\u05e9\u05d5 \u05e1\u05e7\u05d0\u05dc\u05d4 \u05de\u05e1\u05d5\u05d9\u05de\u05ea, \u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05d1\u05d0\u05d5\u05ea\u05d4 \u05e1\u05e7\u05d0\u05dc\u05d4."],[188.0,"\u05de\u05d3\u05d9\u05d3\u05d4 \u05d1\u05e1\u05e7\u05d0\u05dc\u05d4 \u05d0\u05d7\u05e8\u05ea \u05d5\u05d4\u05de\u05e8\u05d4 \u05dc\u05d0 \u05de\u05e1\u05e4\u05d9\u05e7\u05d5\u05ea \u05dc\u05e7\u05d1\u05dc\u05d4, \u05d0\u05dc\u05d0 \u05d0\u05dd \u05d0\u05d5\u05e9\u05e8 \u05d0\u05d7\u05e8\u05ea."],[195.0,"\u05d2\u05dd \u05d4\u05e6\u05d9\u05e4\u05d5\u05d9 \u05de\u05d5\u05d2\u05d3\u05e8 \u05dc\u05e4\u05d9 \u05de\u05e4\u05e8\u05d8, \u05d5\u05dc\u05d0 \u05e8\u05e7 \u05dc\u05e4\u05d9 \u05e9\u05dd."],[199.0,"\u05d0\u05e0\u05d5\u05d3\u05d9\u05d9\u05d6, \u05dc\u05de\u05e9\u05dc, \u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05d9\u05d5\u05ea \u05d3\u05e7\u05d5\u05e8\u05d8\u05d9\u05d1\u05d9 \u05d0\u05d5 \u05e7\u05e9\u05d4, \u05e6\u05d1\u05d5\u05e2 \u05d0\u05d5 \u05e9\u05e7\u05d5\u05e3, \u05d5\u05dc\u05db\u05dc \u05d0\u05d7\u05d3 \u05d9\u05e9 \u05e2\u05d5\u05d1\u05d9 \u05d5\u05ea\u05db\u05d5\u05e0\u05d5\u05ea \u05d0\u05d7\u05e8\u05d9\u05dd."],[209.0,"\u05dc\u05db\u05df \u05d4\u05d4\u05e2\u05e8\u05d4 \u05db\u05d5\u05dc\u05dc\u05ea \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d0\u05ea \u05d4\u05ea\u05e7\u05df, \u05d0\u05ea \u05d4\u05e1\u05d5\u05d2, \u05d0\u05ea \u05d4\u05de\u05d7\u05dc\u05e7\u05d4 \u05d5\u05d0\u05ea \u05d4\u05e2\u05d5\u05d1\u05d9."],[216.0,"\u05d1\u05e6\u05d9\u05e4\u05d5\u05d9 \u05d0\u05d1\u05e5 \u05dc\u05e4\u05d9 2081 50\u05d5, \u05dc\u05de\u05e9\u05dc, \u05d4\u05d4\u05d2\u05d3\u05e8\u05d4 \u05db\u05d5\u05dc\u05dc\u05ea \u05d0\u05ea \u05e2\u05d5\u05d1\u05d9 \u05d4\u05e9\u05db\u05d1\u05d4 \u05d5\u05d0\u05ea \u05e1\u05d5\u05d2 \u05d4\u05d8\u05d9\u05e4\u05d5\u05dc \u05e9\u05d0\u05d7\u05e8\u05d9\u05d5."],[226.0,"\u05d5\u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05d4, \u05d4\u05e2\u05e8\u05d4 \u05e9\u05dc \u05e4\u05e1\u05d9\u05d1\u05e6\u05d9\u05d4 \u05de\u05e4\u05e0\u05d4 \u05dc\u05ea\u05e7\u05df \u05db\u05de\u05d5 ASTM 7"],[233.0,"\u05d6\u05d4 \u05dc\u05d0 \u05e6\u05d9\u05e4\u05d5\u05d9, \u05d0\u05dc\u05d0 \u05d8\u05d9\u05e4\u05d5\u05dc \u05db\u05d9\u05de\u05d9 \u05dc\u05e9\u05db\u05d1\u05ea \u05d4\u05de\u05d2\u05df \u05d4\u05d8\u05d1\u05e2\u05d9\u05ea."],[240.0,"\u05e6\u05d9\u05e4\u05d5\u05d9 \u05de\u05d5\u05e1\u05d9\u05e3 \u05d7\u05d5\u05de\u05e8, \u05d5\u05dc\u05db\u05df \u05d4\u05d5\u05d0 \u05de\u05e9\u05e0\u05d4 \u05de\u05d9\u05d3\u05d5\u05ea."],[244.0,"\u05e9\u05db\u05d1\u05d4 \u05e9\u05dc \u05e2\u05e9\u05e8\u05d4 \u05de\u05d9\u05e7\u05e8\u05d5\u05df \u05d1\u05db\u05dc \u05e6\u05d3 \u05de\u05d2\u05d3\u05d9\u05dc\u05d4 \u05e6\u05d9\u05e8 \u05d1\u05e2\u05e9\u05d5\u05e8\u05d9\u05dd \u05de\u05d9\u05e7\u05e8\u05d5\u05df, \u05d5\u05de\u05e7\u05d8\u05d9\u05e0\u05d4 \u05e7\u05d3\u05d7 \u05d1\u05e2\u05e9\u05d5\u05e8\u05d9\u05dd \u05de\u05d9\u05e7\u05e8\u05d5\u05df."],[252.0,"\u05d1\u05d0\u05e0\u05d5\u05d3\u05d9\u05d9\u05d6 \u05e7\u05e9\u05d4, \u05d1\u05e2\u05e8\u05da \u05de\u05d7\u05e6\u05d9\u05ea \u05de\u05d4\u05e9\u05db\u05d1\u05d4 \u05d7\u05d5\u05d3\u05e8\u05ea \u05dc\u05ea\u05d5\u05da \u05d4\u05d7\u05d5\u05de\u05e8, \u05d5\u05de\u05d7\u05e6\u05d9\u05ea \u05d1\u05d5\u05e0\u05d4 \u05de\u05e2\u05dc\u05d9\u05d5."],[259.0,"\u05dc\u05db\u05df \u05d7\u05e9\u05d5\u05d1 \u05dc\u05d3\u05e2\u05ea \u05d0\u05dd \u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d7\u05dc\u05d5\u05ea \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e6\u05d9\u05e4\u05d5\u05d9 \u05d0\u05d5 \u05d0\u05d7\u05e8\u05d9\u05d5."],[265.0,"\u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d6\u05d4 \u05db\u05ea\u05d5\u05d1 \u05d1\u05d4\u05e2\u05e8\u05d4, \u05d5\u05db\u05e9\u05d6\u05d4 \u05dc\u05d0 \u05db\u05ea\u05d5\u05d1, \u05e9\u05d5\u05d0\u05dc\u05d9\u05dd."],[270.0,"\u05de\u05e1\u05d5\u05de\u05e0\u05d9\u05dd \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05db\u05db\u05d0\u05dc\u05d4 \u05e9\u05d9\u05e9 \u05dc\u05d4\u05d2\u05df \u05e2\u05dc\u05d9\u05d4\u05dd \u05d1\u05d6\u05de\u05df \u05d4\u05e6\u05d9\u05e4\u05d5\u05d9."],[280.0,"\u05d4\u05d1\u05e8\u05d2\u05d4 \u05de\u05e6\u05d5\u05e4\u05d4 \u05d1\u05dc\u05d9 \u05d4\u05db\u05e0\u05d4 \u05de\u05e8\u05d0\u05e9 \u05e2\u05dc\u05d5\u05dc\u05d4 \u05dc\u05d0 \u05dc\u05d4\u05ea\u05d1\u05e8\u05d2, \u05d5\u05e7\u05d3\u05d7 \u05d1\u05d4\u05ea\u05d0\u05de\u05d4 \u05d4\u05d3\u05d5\u05e7\u05d4 \u05e2\u05dc\u05d5\u05dc \u05dc\u05d0 \u05dc\u05e7\u05d1\u05dc \u05d0\u05ea \u05d4\u05e6\u05d9\u05e8."],[289.0,"\u05d9\u05e9 \u05de\u05dc\u05db\u05d5\u05d3\u05ea \u05d0\u05d7\u05ea \u05e9\u05d4\u05d9\u05d0 \u05dc\u05d0 \u05e8\u05e7 \u05e2\u05e0\u05d9\u05d9\u05df \u05e9\u05dc \u05de\u05d9\u05d3\u05d4."],[293.0,"\u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05d1\u05d7\u05d5\u05d6\u05e7 \u05d2\u05d1\u05d5\u05d4, \u05e6\u05d9\u05e4\u05d5\u05d9 \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05dc\u05d9\u05d8\u05d9 \u05e2\u05dc\u05d5\u05dc \u05dc\u05d4\u05db\u05e0\u05d9\u05e1 \u05de\u05d9\u05de\u05df \u05dc\u05d7\u05d5\u05de\u05e8."],[299.0,"\u05d4\u05de\u05d9\u05de\u05df \u05d2\u05d5\u05e8\u05dd \u05dc\u05e9\u05d1\u05d9\u05e8\u05d5\u05ea, \u05d5\u05d4\u05d7\u05dc\u05e7 \u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05d9\u05e9\u05d1\u05e8 \u05d1\u05dc\u05d9 \u05d0\u05d6\u05d4\u05e8\u05d4, \u05e9\u05e2\u05d5\u05ea \u05d0\u05d5\u05d9\u05de\u05d9\u05dd \u05d0\u05d7\u05e8\u05d9 \u05d4\u05d4\u05e8\u05db\u05d1\u05d4."],[307.0,"\u05dc\u05db\u05df \u05d4\u05de\u05e4\u05e8\u05d8 \u05d3\u05d5\u05e8\u05e9 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d0\u05e4\u05d9\u05d9\u05d4 \u05dc\u05d4\u05e4\u05d7\u05ea\u05ea \u05e9\u05d1\u05d9\u05e8\u05d5\u05ea \u05de\u05d9\u05de\u05df, \u05d6\u05de\u05df \u05e7\u05e6\u05e8 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e6\u05d9\u05e4\u05d5\u05d9."],[315.0,"\u05db\u05e9\u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05de\u05d2\u05d3\u05d9\u05e8 \u05e4\u05dc\u05d3\u05d4 \u05e7\u05e9\u05d4 \u05d5\u05e6\u05d9\u05e4\u05d5\u05d9 \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05dc\u05d9\u05d8\u05d9, \u05d5\u05d0\u05d9\u05df \u05d3\u05e8\u05d9\u05e9\u05ea \u05d0\u05e4\u05d9\u05d9\u05d4, \u05d6\u05d5 \u05e9\u05d0\u05dc\u05d4 \u05d3\u05d7\u05d5\u05e4\u05d4 \u05dc\u05de\u05ea\u05db\u05e0\u05df."],[324.0,"\u05d4\u05d4\u05e2\u05e8\u05d5\u05ea \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05de\u05d2\u05d3\u05d9\u05e8\u05d5\u05ea \u05d2\u05dd, \u05d1\u05de\u05e4\u05d5\u05e8\u05e9 \u05d0\u05d5 \u05d1\u05de\u05e9\u05ea\u05de\u05e2, \u05e1\u05d3\u05e8 \u05e4\u05e2\u05d5\u05dc\u05d5\u05ea."],[330.0,"\u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc: \u05d7\u05d5\u05de\u05e8 \u05d1\u05de\u05e6\u05d1 \u05de\u05e1\u05d5\u05d9\u05dd, \u05e2\u05d9\u05d1\u05d5\u05d3 \u05d2\u05e1, \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd, \u05e2\u05d9\u05d1\u05d5\u05d3 \u05d2\u05de\u05e8, \u05d5\u05e8\u05e7 \u05d1\u05e1\u05d5\u05e3 \u05e6\u05d9\u05e4\u05d5\u05d9."],[340.0,"\u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05d0\u05d7\u05e8\u05d9 \u05e2\u05d9\u05d1\u05d5\u05d3 \u05d2\u05de\u05e8 \u05e2\u05dc\u05d5\u05dc \u05dc\u05e2\u05d5\u05d5\u05ea \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7, \u05d5\u05dc\u05db\u05df \u05de\u05e9\u05d0\u05d9\u05e8\u05d9\u05dd \u05ea\u05d5\u05e1\u05e4\u05ea \u05e2\u05d9\u05d1\u05d5\u05d3 \u05dc\u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05d4\u05de\u05d3\u05d5\u05d9\u05e7\u05d9\u05dd."],[348.0,"\u05d5\u05db\u05e9\u05d4\u05d4\u05e2\u05e8\u05d4 \u05d0\u05d5\u05de\u05e8\u05ea \u05e9\u05d5\u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05d7\u05dc\u05d5\u05ea \u05d0\u05d7\u05e8\u05d9 \u05d8\u05d9\u05e4\u05d5\u05dc \u05d4\u05d7\u05d5\u05dd, \u05d4\u05d9\u05e6\u05e8\u05df \u05e6\u05e8\u05d9\u05da \u05dc\u05ea\u05db\u05e0\u05df \u05d0\u05ea \u05d4\u05ea\u05d5\u05e1\u05e4\u05ea \u05d1\u05e2\u05e6\u05de\u05d5."],[356.0,"\u05de\u05d9 \u05e9\u05e7\u05d5\u05e8\u05d0 \u05d0\u05ea \u05d4\u05d4\u05e2\u05e8\u05d5\u05ea \u05db\u05e8\u05e9\u05d9\u05de\u05d4 \u05d5\u05dc\u05d0 \u05db\u05ea\u05d4\u05dc\u05d9\u05da, \u05e2\u05dc\u05d5\u05dc \u05dc\u05d1\u05e6\u05e2 \u05d0\u05d5\u05ea\u05df \u05d1\u05e1\u05d3\u05e8 \u05d4\u05dc\u05d0 \u05e0\u05db\u05d5\u05df."],[364.0,"\u05d4\u05e8\u05d1\u05d4 \u05e9\u05e8\u05d8\u05d5\u05d8\u05d9\u05dd \u05db\u05d5\u05dc\u05dc\u05d9\u05dd \u05d2\u05dd \u05d4\u05e2\u05e8\u05d4 \u05e2\u05dc \u05e1\u05d9\u05de\u05d5\u05df \u05d4\u05d7\u05dc\u05e7: \u05de\u05d4 \u05dc\u05e1\u05de\u05df, \u05d0\u05d9\u05e4\u05d4, \u05d5\u05d1\u05d0\u05d9\u05d6\u05d5 \u05e9\u05d9\u05d8\u05d4."],[372.0,"\u05d4\u05e9\u05d9\u05d8\u05d4 \u05d7\u05e9\u05d5\u05d1\u05d4: \u05d7\u05e8\u05d9\u05d8\u05d4 \u05d0\u05d5 \u05d4\u05d8\u05d1\u05e2\u05d4 \u05e2\u05dc \u05de\u05e9\u05d8\u05d7 \u05e2\u05de\u05d5\u05e1 \u05e2\u05dc\u05d5\u05dc\u05d5\u05ea \u05dc\u05d9\u05e6\u05d5\u05e8 \u05e0\u05e7\u05d5\u05d3\u05ea \u05ea\u05d7\u05d9\u05dc\u05ea \u05e1\u05d3\u05e7."],[379.0,"\u05d5\u05dc\u05db\u05df \u05d4\u05de\u05d9\u05e7\u05d5\u05dd \u05de\u05d5\u05d2\u05d3\u05e8 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05d0\u05d6\u05d5\u05e8 \u05e9\u05d0\u05d9\u05e0\u05d5 \u05e2\u05de\u05d5\u05e1 \u05d5\u05d0\u05d9\u05e0\u05d5 \u05e4\u05d5\u05e0\u05e7\u05e6\u05d9\u05d5\u05e0\u05dc\u05d9."],[386.0,"\u05d7\u05d5\u05de\u05e8 \u05e9\u05d5\u05d5\u05d4 \u05e2\u05e8\u05da \u05d1\u05dc\u05d9 \u05d0\u05d9\u05e9\u05d5\u05e8."],[389.0,"\u05de\u05e6\u05d1 \u05d7\u05d5\u05de\u05e8 \u05d7\u05e1\u05e8, \u05d0\u05d5 \u05de\u05e6\u05d1 \u05e9\u05e0\u05e7\u05e8\u05d0 \u05dc\u05d0 \u05e0\u05db\u05d5\u05df."],[393.0,"\u05e7\u05e9\u05d9\u05d5\u05ea \u05d1\u05dc\u05d9 \u05de\u05e7\u05d5\u05dd \u05d1\u05d3\u05d9\u05e7\u05d4, \u05d0\u05d5 \u05de\u05d3\u05d9\u05d3\u05d4 \u05d1\u05e1\u05e7\u05d0\u05dc\u05d4 \u05d0\u05d7\u05e8\u05ea."],[398.0,"\u05e6\u05d9\u05e4\u05d5\u05d9 \u05e9\u05dc\u05d0 \u05e0\u05dc\u05e7\u05d7 \u05d1\u05d7\u05e9\u05d5\u05d1\u05d5\u05df \u05d1\u05e1\u05d1\u05d5\u05dc\u05ea \u05e9\u05dc \u05d4\u05ea\u05d0\u05de\u05d4 \u05d0\u05d5 \u05e9\u05dc \u05d4\u05d1\u05e8\u05d2\u05d4."],[403.0,"\u05d5\u05e4\u05dc\u05d3\u05d4 \u05e7\u05e9\u05d4 \u05e2\u05dd \u05e6\u05d9\u05e4\u05d5\u05d9 \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05dc\u05d9\u05d8\u05d9, \u05d1\u05dc\u05d9 \u05d0\u05e4\u05d9\u05d9\u05d4."],[408.0,"\u05d4\u05d7\u05d5\u05de\u05e8 \u05d5\u05d4\u05de\u05e6\u05d1 \u05e9\u05dc\u05d5 \u05d4\u05dd \u05d7\u05dc\u05e7 \u05de\u05d4\u05d2\u05d3\u05e8\u05ea \u05d4\u05d7\u05dc\u05e7, \u05d5\u05dc\u05d0 \u05de\u05d7\u05dc\u05d9\u05e4\u05d9\u05dd \u05d0\u05d5\u05ea\u05dd \u05d1\u05dc\u05d9 \u05d0\u05d9\u05e9\u05d5\u05e8."],[415.0,"\u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05de\u05d5\u05d2\u05d3\u05e8 \u05d1\u05ea\u05d5\u05e6\u05d0\u05d4: \u05e7\u05e9\u05d9\u05d5\u05ea \u05d1\u05ea\u05d7\u05d5\u05dd, \u05e2\u05d5\u05de\u05e7 \u05e9\u05db\u05d1\u05d4 \u05d5\u05d7\u05e7\u05d5\u05dd \u05d1\u05d3\u05d9\u05e7\u05d4."],[422.0,"\u05e6\u05d9\u05e4\u05d5\u05d9 \u05de\u05d5\u05d2\u05d3\u05e8 \u05d1\u05de\u05e4\u05e8\u05d8, \u05de\u05e9\u05e0\u05d4 \u05de\u05d9\u05d3\u05d5\u05ea, \u05d5\u05d3\u05d5\u05e8\u05e9 \u05dc\u05d3\u05e2\u05ea \u05d0\u05dd \u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e6\u05d9\u05e4\u05d5\u05d9 \u05d0\u05d5 \u05d0\u05d7\u05e8\u05d9\u05d5."],[429.0,"\u05d5\u05db\u05dc \u05d4\u05d4\u05e2\u05e8\u05d5\u05ea \u05d9\u05d7\u05d3 \u05de\u05d2\u05d3\u05d9\u05e8\u05d5\u05ea \u05e1\u05d3\u05e8 \u05e4\u05e2\u05d5\u05dc\u05d5\u05ea, \u05e9\u05e6\u05e8\u05d9\u05da \u05dc\u05e7\u05e8\u05d5\u05d0 \u05db\u05ea\u05d4\u05dc\u05d9\u05da."],[435.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05e2\u05de\u05d9\u05e7 \u05d1\u05d4\u05d1\u05e8\u05d2\u05d5\u05ea: \u05de\u05d8\u05e8\u05d9, \u05d0\u05d9\u05e0\u05e5', \u05d4\u05d1\u05e8\u05d2\u05d5\u05ea \u05e6\u05e0\u05e8\u05ea \u05d5\u05d4\u05dc\u05d9\u05e7\u05d5\u05d9\u05dc. \u05e0\u05ea\u05e8\u05d0\u05d4 \u05d1\u05e4\u05e8\u05e7 \u05d0\u05e8\u05d1\u05e2 \u05e2\u05e9\u05e8\u05d4."]]};
window.MH_TR["ch14"]={"t":"\u05d4\u05d1\u05e8\u05d2\u05d5\u05ea \u05dc\u05e2\u05d5\u05de\u05e7","l":[[1.0,"\u05d1\u05e4\u05e8\u05e7 \u05e9\u05dc\u05d5\u05e9 \u05dc\u05de\u05d3\u05e0\u05d5 \u05d0\u05d9\u05da \u05de\u05e6\u05d9\u05d9\u05e8\u05d9\u05dd \u05d4\u05d1\u05e8\u05d2\u05d4. \u05e2\u05db\u05e9\u05d9\u05d5 \u05e0\u05dc\u05de\u05d3 \u05dc\u05e7\u05e8\u05d5\u05d0 \u05d0\u05ea \u05d4\u05db\u05d9\u05ea\u05d5\u05d1 \u05e9\u05dc\u05d4, \u05d5\u05e9\u05dd \u05e0\u05de\u05e6\u05d0 \u05e8\u05d5\u05d1 \u05d4\u05de\u05d9\u05d3\u05e2."],[10.0,"\u05db\u05d9\u05ea\u05d5\u05d1 \u05d4\u05d1\u05e8\u05d2\u05d4 \u05d0\u05d7\u05d3 \u05d0\u05d5\u05de\u05e8 \u05d0\u05ea \u05d4\u05e7\u05d5\u05d8\u05e8, \u05d0\u05ea \u05d4\u05e4\u05e1\u05d9\u05e2\u05d4, \u05d0\u05ea \u05d4\u05e1\u05d1\u05d5\u05dc\u05ea,"],[15.0,"\u05d0\u05ea \u05d4\u05e2\u05d5\u05de\u05e7, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d2\u05dd \u05d0\u05ea \u05db\u05d9\u05d5\u05d5\u05df \u05d4\u05e1\u05d9\u05d1\u05d5\u05d1 \u05d5\u05d0\u05ea \u05de\u05e1\u05e4\u05e8 \u05d4\u05d4\u05ea\u05d7\u05dc\u05d5\u05ea."],[21.0,"\u05d5\u05db\u05e9\u05de\u05d7\u05dc\u05d9\u05e4\u05d9\u05dd \u05d4\u05d1\u05e8\u05d2\u05d4 \u05de\u05d8\u05e8\u05d9\u05ea \u05d1\u05d0\u05d9\u05e0\u05e6'\u05d9\u05ea, \u05d0\u05d5 \u05d4\u05d1\u05e8\u05d2\u05ea \u05e6\u05e0\u05e8\u05ea \u05d0\u05d7\u05ea \u05d1\u05e9\u05e0\u05d9\u05d9\u05d4, \u05d4\u05d1\u05d5\u05e8\u05d2 \u05e0\u05db\u05e0\u05e1 \u05d7\u05e6\u05d9 \u05e1\u05d9\u05d1\u05d5\u05d1 \u05d5\u05e0\u05ea\u05e7\u05e2."],[30.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05e2\u05d1\u05d5\u05e8 \u05e2\u05dc \u05d4\u05d1\u05e8\u05d2\u05d5\u05ea \u05de\u05d8\u05e8\u05d9\u05d5\u05ea, \u05d0\u05d9\u05e0\u05e6'\u05d9\u05d5\u05ea, \u05d4\u05d1\u05e8\u05d2\u05d5\u05ea \u05e6\u05e0\u05e8\u05ea \u05d5\u05e7\u05d3\u05d7\u05d9 \u05d4\u05dc\u05d9\u05e7\u05d5\u05d9\u05dc."],[39.0,"\u05db\u05d9\u05ea\u05d5\u05d1 \u05de\u05d8\u05e8\u05d9 \u05de\u05ea\u05d7\u05d9\u05dc \u05d1\u05d0\u05d5\u05ea \u05d5\u05d0 \u05d5\u05d1\u05e7\u05d5\u05d8\u05e8 \u05d4\u05e0\u05d5\u05de\u05d9\u05e0\u05dc\u05d9, \u05dc\u05de\u05e9\u05dc 0\u05e8\u05d5\u05d0."],[45.0,"\u05db\u05e9\u05dc\u05d0 \u05db\u05ea\u05d5\u05d1\u05d4 \u05e4\u05e1\u05d9\u05e2\u05d4, \u05d6\u05d5 \u05d4\u05e4\u05e1\u05d9\u05e2\u05d4 \u05d4\u05d2\u05e1\u05d4 \u05d4\u05e1\u05d8\u05e0\u05d3\u05e8\u05d8\u05d9\u05ea. \u05d1- \u05d5\u05d5 \u05d4\u05d9\u05d0 \u05d0\u05d7\u05ea \u05d5\u05d7\u05e6\u05d9 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8."],[53.0,"\u05e4\u05e1\u05d9\u05e2\u05d4 \u05e2\u05d3\u05d9\u05e0\u05d4 \u05ea\u05de\u05d9\u05d3 \u05db\u05ea\u05d5\u05d1\u05d4 \u05d1\u05de\u05e4\u05d5\u05e8\u05e9, \u05dc\u05de\u05e9\u05dc \u2026."],[61.0,"\u05d0\u05d7\u05e8\u05d9 \u05de\u05e7\u05e3 \u05de\u05d5\u05e4\u05d9\u05e2\u05d4 \u05e1\u05d1\u05d5\u05dc\u05ea \u05d4\u05d4\u05d1\u05e8\u05d2\u05d4, \u05d5\u05d0\u05d7\u05e8 \u05db\u05da \u05d4\u05e2\u05d5\u05de\u05e7."],[66.0,"\u05d1\u05e7\u05d3\u05d7 \u05de\u05d5\u05d1\u05e8\u05d2 \u05d9\u05e9 \u05e9\u05e0\u05d9 \u05e2\u05d5\u05de\u05e7\u05d9\u05dd: \u05e2\u05d5\u05de\u05e7 \u05d4\u05d4\u05d1\u05e8\u05d2\u05d4 \u05d4\u05de\u05dc\u05d0\u05d4, \u05d5\u05e2\u05d5\u05de\u05e7 \u05d4\u05e7\u05d3\u05d7 \u05d4\u05de\u05e7\u05d3\u05d9\u05dd, \u05e9\u05d4\u05d5\u05d0 \u05ea\u05de\u05d9\u05d3 \u05d0\u05e8\u05d5\u05da \u05d9\u05d5\u05ea\u05e8."],[75.0,"\u05d1\u05e7\u05d3\u05d7 \u05e2\u05d9\u05d5\u05d5\u05e8 \u05e9\u05dc 8\u05d5\u05d0, \u05dc\u05de\u05e9\u05dc, \u05e7\u05d5\u05d3\u05d7\u05d9\u05dd \u05d1\u05e7\u05d5\u05d8\u05e8 6.8 \u05dc\u05e2\u05d5\u05de\u05e7 0, \u05d5\u05de\u05d1\u05e8\u05d9\u05d2\u05d9\u05dd \u05dc\u05e2\u05d5\u05de\u05e7 16."],[85.0,"\u05de\u05d9 \u05e9\u05e7\u05d5\u05d3\u05d7 \u05e8\u05e7 \u05e2\u05d3 \u05e2\u05d5\u05de\u05e7 \u05d4\u05d4\u05d1\u05e8\u05d2\u05d4, \u05dc\u05d0 \u05d9\u05e9\u05d0\u05d9\u05e8 \u05de\u05e7\u05d5\u05dd \u05dc\u05e7\u05e6\u05d4 \u05d4\u05de\u05d1\u05e8\u05d6, \u05d5\u05dc\u05d0 \u05d9\u05e7\u05d1\u05dc \u05d4\u05d1\u05e8\u05d2\u05d4 \u05de\u05dc\u05d0\u05d4 \u05e2\u05d3 \u05d4\u05e2\u05d5\u05de\u05e7 \u05d4\u05e0\u05d3\u05e8\u05e9\u05d5."],[95.0,"\u05e1\u05d1\u05d5\u05dc\u05ea \u05d4\u05d1\u05e8\u05d2\u05d4 \u05d1\u05e0\u05d5\u05d9\u05d4 \u05db\u05de\u05d5 \u05d1\u05d4\u05ea\u05d0\u05de\u05d5\u05ea 286 ISO: \u05de\u05e1\u05e4\u05e8 \u05dc\u05d3\u05e8\u05d2\u05ea \u05d4\u05d3\u05d9\u05d5\u05e7, \u05d5\u05d0\u05d5\u05ea \u05dc\u05de\u05d9\u05e7\u05d5\u05dd."],[104.0,"\u05d0\u05d5\u05ea \u05d2\u05d3\u05d5\u05dc\u05d4 \u05dc\u05d4\u05d1\u05e8\u05d2\u05d4 \u05e4\u05e0\u05d9\u05de\u05d9\u05ea, \u05d5\u05d0\u05d5\u05ea \u05e7\u05d8\u05e0\u05d4 \u05dc\u05d4\u05d1\u05e8\u05d2\u05d4 \u05d7\u05d9\u05e6\u05d5\u05e0\u05d9\u05ea."],[109.0,"6H \u05d5-60 \u05d4\u05df \u05d4\u05e6\u05d9\u05e8\u05d5\u05e3 \u05d4\u05e0\u05e4\u05d5\u05e5 \u05d1\u05d9\u05d5\u05ea\u05e8, \u05d5\u05d4\u05d5\u05d0 \u05de\u05ea\u05d0\u05d9\u05dd \u05dc\u05e8\u05d5\u05d1 \u05d4\u05d1\u05e8\u05d2\u05d9\u05dd \u05d5\u05d4\u05d0\u05d5\u05de\u05d9\u05dd."],[116.0,"\u05d74 \u05d4\u05d9\u05d0 \u05d4\u05d1\u05e8\u05d2\u05d4 \u05de\u05d3\u05d5\u05d9\u05e7\u05ea \u05d9\u05d5\u05ea\u05e8, \u05d5-66 \u05de\u05e9\u05d0\u05d9\u05e8\u05d4 \u05de\u05e8\u05d5\u05d5\u05d7 \u05d2\u05d3\u05d5\u05dc \u05d9\u05d5\u05ea\u05e8, \u05dc\u05de\u05e9\u05dc \u05de\u05e7\u05d5\u05dd \u05dc\u05e6\u05d9\u05e4\u05d5\u05d9."],[125.0,"\u05db\u05e9\u05d4\u05d7\u05dc\u05e7 \u05de\u05e6\u05d5\u05e4\u05d4 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05d4\u05d1\u05e8\u05d2\u05d4, \u05e6\u05e8\u05d9\u05da \u05dc\u05d1\u05d3\u05d5\u05e7 \u05e9\u05d4\u05e1\u05d1\u05d5\u05dc\u05ea \u05de\u05ea\u05d0\u05d9\u05de\u05d4 \u05dc\u05e2\u05d5\u05d1\u05d9 \u05d4\u05e6\u05d9\u05e4\u05d5\u05d9, \u05d0\u05d7\u05e8\u05ea \u05d4\u05d1\u05d5\u05e8\u05d2 \u05dc\u05d0 \u05d9\u05d9\u05db\u05e0\u05e1."],[134.0,"\u05d5\u05d1\u05d1\u05d3\u05d9\u05e7\u05d4, \u05d4\u05de\u05d9\u05d3\u05d4 \u05d4\u05e7\u05d5\u05d1\u05e2\u05ea \u05d4\u05d9\u05d0 \u05d4\u05e7\u05d5\u05d8\u05e8 \u05d4\u05d0\u05e4\u05e7\u05d8\u05d9\u05d1\u05d9, \u05d7\u05e1\u05d6\u05d5\u05e7 diameter, \u05d5\u05dc\u05d0 \u05d4\u05e7\u05d5\u05d8\u05e8 \u05d4\u05d7\u05d9\u05e6\u05d5\u05e0\u05d9."],[142.0,"\u05d4\u05d1\u05e8\u05d2\u05d5\u05ea \u05d0\u05d9\u05e0\u05e6'\u05d9\u05d5\u05ea \u05e0\u05db\u05ea\u05d1\u05d5\u05ea \u05d0\u05d7\u05e8\u05ea: \u05e7\u05d5\u05d8\u05e8, \u05de\u05e1\u05e4\u05e8 \u05db\u05e8\u05d9\u05db\u05d5\u05ea \u05dc\u05d0\u05d9\u05e0\u05e5', \u05e1\u05d3\u05e8\u05d4 \u05d5\u05de\u05d7\u05dc\u05e7\u05d4."],[150.0,"0 UNC-2A, \u05dc\u05de\u05e9\u05dc: \u05e7\u05d5\u05d8\u05e8 \u05e8\u05d1\u05e2 \u05d0\u05d9\u05e0\u05e5, \u05e2\u05e9\u05e8\u05d9\u05dd \u05db\u05e8\u05d9\u05db\u05d5\u05ea \u05dc\u05d0\u05d9\u05e0\u05e5, \u05e1\u05d3\u05e8\u05d4 \u05d2\u05e1\u05d4, \u05de\u05d7\u05dc\u05e7\u05d4 \u05e9\u05ea\u05d9\u05d9\u05dd, \u05d7\u05d9\u05e6\u05d5\u05e0\u05d9\u05ea."],[163.0,"\u05d6\u05d0\u05d8 \u05d4\u05d9\u05d0 \u05d4\u05e1\u05d3\u05e8\u05d4 \u05d4\u05e2\u05d3\u05d9\u05e0\u05d4, \u05d5\u05d1\u05d0\u05d5\u05ea\u05d5 \u05e7\u05d5\u05d8\u05e8 \u05d9\u05e9 \u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05db\u05e8\u05d9\u05db\u05d5\u05ea \u05dc\u05d0\u05d9\u05e0\u05e5'."],[169.0,")\u05d0 \u05de\u05e1\u05de\u05df \u05d4\u05d1\u05e8\u05d2\u05d4 \u05d7\u05d9\u05e6\u05d5\u05e0\u05d9\u05ea B-1 \u05e4\u05e0\u05d9\u05de\u05d9\u05ea. \u05d4\u05de\u05d7\u05dc\u05e7\u05d5\u05ea \u05d4\u05df \u05d0\u05d7\u05ea, \u05e9\u05ea\u05d9\u05d9\u05dd \u05d5\u05e9\u05dc\u05d5\u05e9, \u05d5\u05e9\u05dc\u05d5\u05e9 \u05d4\u05d9\u05d0 \u05d4\u05de\u05d3\u05d5\u05d9\u05e7\u05ea \u05d1\u05d9\u05d5\u05ea\u05e8."],[180.0,"\u05e7\u05d8\u05e8\u05d9\u05dd \u05e7\u05d8\u05e0\u05d9\u05dd \u05e0\u05db\u05ea\u05d1\u05d9\u05dd \u05d1\u05de\u05e1\u05e4\u05e8, \u05dc\u05de\u05e9\u05dc 10-32 \u05d6\u05d0\u05d8."],[189.0,"\u05d5\u05d9\u05e9 \u05de\u05dc\u05db\u05d5\u05d3\u05ea \u05de\u05d5\u05db\u05e8\u05ea: 1/4-20 \u05d5-6\u05d5\u05d0 \u05e0\u05e8\u05d0\u05d9\u05dd \u05db\u05de\u05e2\u05d8 \u05d0\u05d5\u05ea\u05d5 \u05d3\u05d1\u05e8, \u05d5\u05d1\u05d5\u05e8\u05d2 \u05d0\u05d7\u05d3 \u05d9\u05d9\u05db\u05e0\u05e1 \u05dc\u05e9\u05e0\u05d9 \u05db\u05de\u05d4 \u05e1\u05d9\u05d1\u05d5\u05d1\u05d9\u05dd \u05dc\u05e4\u05e0\u05d9 \u05e9\u05d9\u05d9\u05ea\u05e7\u05e2."],[201.0,"\u05d1\u05d4\u05d1\u05e8\u05d2\u05d5\u05ea \u05e6\u05e0\u05e8\u05ea, \u05d4\u05de\u05e1\u05e4\u05e8 \u05d1\u05db\u05d9\u05ea\u05d5\u05d1 \u05d4\u05d5\u05d0 \u05dc\u05d0 \u05d4\u05e7\u05d5\u05d8\u05e8 \u05e9\u05dc \u05d4\u05d4\u05d1\u05e8\u05d2\u05d4."],[206.0,"\u05d4\u05d1\u05e8\u05d2\u05ea \u05e6\u05e0\u05e8\u05ea \u05e9\u05dc \u05d7\u05e6\u05d9 \u05d0\u05d9\u05e0\u05e5, \u05dc\u05de\u05e9\u05dc, \u05d4\u05d9\u05d0 \u05d1\u05e7\u05d5\u05d8\u05e8 \u05d7\u05d9\u05e6\u05d5\u05e0\u05d9 \u05e9\u05dc \u05d1\u05e2\u05e8\u05da \u05e2\u05e9\u05e8\u05d9\u05dd \u05d5\u05d0\u05d7\u05d3 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8."],[214.0,"\u05d6\u05d7\u05d0 \u05d4\u05d9\u05d0 \u05d4\u05d4\u05d1\u05e8\u05d2\u05d4 \u05d4\u05d0\u05de\u05e8\u05d9\u05e7\u05d0\u05d9\u05ea: \u05e7\u05d5\u05e0\u05d9\u05ea, \u05d1\u05d6\u05d5\u05d5\u05d9\u05ea \u05e9\u05d9\u05e9\u05d9\u05dd \u05de\u05e2\u05dc\u05d5\u05ea,"],[220.0,"\u05d5\u05d4\u05d0\u05d9\u05d8\u05d5\u05dd \u05e0\u05e2\u05e9\u05d4 \u05e2\u05dc \u05d4\u05d4\u05d1\u05e8\u05d2\u05d4 \u05e2\u05e6\u05de\u05d4, \u05e2\u05dd \u05d7\u05d5\u05de\u05e8 \u05d0\u05d9\u05d8\u05d5\u05dd."],[225.0,"\u05d4\u05d9\u05d0 \u05dc\u05d0 \u05d0\u05d5\u05d8\u05de\u05ea \u05d1\u05e2\u05e6\u05de\u05d4, \u05d5\u05d4\u05d0\u05d9\u05d8\u05d5\u05dd \u05e0\u05e2\u05e9\u05d4 \u05d1\u05d0\u05d8\u05dd \u05d0\u05d5 \u05d1\u05d8\u05d1\u05e2\u05ea 0."],[237.0,"\u20aa \u05d4\u05d9\u05d0 \u05d4\u05d1\u05e8\u05d2\u05d4 \u05e7\u05d5\u05e0\u05d9\u05ea \u05d7\u05d9\u05e6\u05d5\u05e0\u05d9\u05ea, \u20aa6 \u05e7\u05d5\u05e0\u05d9\u05ea \u05e4\u05e0\u05d9\u05de\u05d9\u05ea, \u05d5-\u05e7\u05dd \u05d9\u05e9\u05e8\u05d4 \u05e4\u05e0\u05d9\u05de\u05d9\u05ea, \u05dc\u05e4\u05d9 7 ASO"],[248.0,"\u05d5\u05d4\u05d6\u05d5\u05d5\u05d9\u05ea \u05d1\u05d4\u05d1\u05e8\u05d2\u05d4 \u05d4\u05d1\u05e8\u05d9\u05d8\u05d9\u05ea \u05d4\u05d9\u05d0 \u05d7\u05de\u05d9\u05e9\u05d9\u05dd \u05d5\u05d7\u05de\u05e9 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d5\u05dc\u05db\u05df BSPT-1 NPT \u05dc\u05d0 \u05de\u05ea\u05d7\u05dc\u05e4\u05d9\u05dd, \u05d0\u05e3 \u05e9\u05d4\u05dd \u05e0\u05e8\u05d0\u05d9\u05dd \u05d3\u05d5\u05de\u05d4."],[259.0,"\u05de\u05d9 \u05e9\u05de\u05e8\u05db\u05d9\u05d1 \u05d4\u05d1\u05e8\u05d2\u05ea 6 \u05e2\u05dd \u05d7\u05d5\u05de\u05e8 \u05d0\u05d9\u05d8\u05d5\u05dd \u05e2\u05dc \u05d4\u05d4\u05d1\u05e8\u05d2\u05d4 \u05d1\u05de\u05e7\u05d5\u05dd \u05d0\u05d8\u05dd, \u05d9\u05e7\u05d1\u05dc \u05d3\u05dc\u05d9\u05e4\u05d4."],[266.0,"\u05db\u05e9\u05de\u05d1\u05e8\u05d9\u05d2\u05d9\u05dd \u05dc\u05d7\u05d5\u05de\u05e8 \u05e8\u05da, \u05db\u05de\u05d5 \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd, \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05dc\u05e2\u05d9\u05ea\u05d9\u05dd \u05e7\u05e8\u05d5\u05d1\u05d5\u05ea \u05d1\u05ea\u05d5\u05ea\u05d1 \u05d4\u05d1\u05e8\u05d2\u05d4 \u05e2\u05e9\u05d5\u05d9 \u05ea\u05d9\u05dc, \u05d4\u05dc\u05d9\u05e7\u05d5\u05d9\u05dc."],[275.0,"\u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05de\u05d5\u05e4\u05d9\u05e2\u05d4 \u05d4\u05d4\u05d1\u05e8\u05d2\u05d4 \u05d4\u05e1\u05d5\u05e4\u05d9\u05ea, \u05dc\u05de\u05e9\u05dc 8\u05d5\u05d0, \u05d5\u05d0\u05d5\u05e8\u05da \u05d4\u05ea\u05d5\u05ea\u05d1, \u05dc\u05de\u05e9\u05dc \u05e4\u05e2\u05dd \u05d5\u05d7\u05e6\u05d9 \u05d4\u05e7\u05d5\u05d8\u05e8."],[285.0,"\u05d0\u05d1\u05dc \u05d4\u05e7\u05d3\u05d7 \u05e2\u05e6\u05de\u05d5 \u05de\u05d5\u05d1\u05e8\u05d2 \u05d1\u05d4\u05d1\u05e8\u05d2\u05d4 \u05de\u05d9\u05d5\u05d7\u05d3\u05ea, \u05d2\u05d3\u05d5\u05dc\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05e9\u05e0\u05e7\u05e8\u05d0\u05ea !51, \u05d5\u05d1\u05de\u05d1\u05e8\u05d6 \u05de\u05d9\u05d5\u05d7\u05d3."],[294.0,"\u05de\u05d9 \u05e9\u05de\u05d1\u05e8\u05d9\u05d2 8\u05d5\u05d0 \u05e8\u05d2\u05d9\u05dc \u05d1\u05de\u05e7\u05d5\u05dd |51, \u05dc\u05d0 \u05d9\u05d5\u05db\u05dc \u05dc\u05d4\u05db\u05e0\u05d9\u05e1 \u05d0\u05ea \u05d4\u05ea\u05d5\u05ea\u05d1."],[301.0,"\u05dc\u05db\u05df \u05db\u05e9\u05e8\u05d5\u05d0\u05d9\u05dd \u05d4\u05dc\u05d9\u05e7\u05d5\u05d9\u05dc \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8, \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05de\u05d4 \u05d1\u05d3\u05d9\u05d5\u05e7 \u05e6\u05e8\u05d9\u05da \u05dc\u05e7\u05d3\u05d5\u05d7, \u05dc\u05d4\u05d1\u05e8\u05d9\u05d2 \u05d5\u05dc\u05d4\u05db\u05e0\u05d9\u05e1, \u05d5\u05d1\u05d0\u05d9\u05d6\u05d4 \u05e1\u05d3\u05e8."],[310.0,"\u05d4 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05db\u05d9\u05ea\u05d5\u05d1 \u05e4\u05d9\u05e8\u05d5\u05e9\u05d5 \u05d4\u05d1\u05e8\u05d2\u05d4 \u05e9\u05de\u05d0\u05dc\u05d9\u05ea. \u05d1\u05dc\u05d9 LH \u05d4\u05d4\u05d1\u05e8\u05d2\u05d4 \u05d9\u05de\u05e0\u05d9\u05ea."],[318.0,"\u05d1\u05d4\u05d1\u05e8\u05d2\u05d4 \u05e8\u05d1 \u05d4\u05ea\u05d7\u05dc\u05ea\u05d9\u05ea, \u05db\u05d5\u05ea\u05d1\u05d9\u05dd \u05d0\u05ea \u05d4\u05d4\u05ea\u05e7\u05d3\u05de\u05d5\u05ea \u05d5\u05d0\u05ea \u05d4\u05e4\u05e1\u05d9\u05e2\u05d4,"],[325.0,"\u05dc\u05de\u05e9\u05dc 1.5\u05e1 3\u05d7\u05e1, \u05db\u05dc\u05d5\u05de\u05e8 \u05d4\u05d1\u05e8\u05d2\u05d4 \u05d1\u05e9\u05d5\u05ea\u05d9 \u05d4\u05ea\u05d7\u05dc\u05d5\u05ea."],[330.0,"\u05dc\u05d9\u05d3 \u05ea\u05d7\u05d9\u05dc\u05ea \u05d4\u05d4\u05d1\u05e8\u05d2\u05d4 \u05de\u05d5\u05e4\u05d9\u05e2 \u05dc\u05e2\u05d9\u05ea\u05d9\u05dd \u05e9\u05d9\u05e4\u05d5\u05e2, \u05db\u05d3\u05d9 \u05e9\u05d4\u05d1\u05d5\u05e8\u05d2 \u05d9\u05d9\u05db\u05e0\u05e1 \u05d1\u05e7\u05dc\u05d5\u05ea."],[336.0,"\u05d5\u05d1\u05e1\u05d5\u05e3 \u05d4\u05d1\u05e8\u05d2\u05d4 \u05d7\u05d9\u05e6\u05d5\u05e0\u05d9\u05ea \u05d9\u05e9 \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05ea\u05e2\u05dc\u05ea \u05d9\u05e6\u05d9\u05d0\u05d4,"],[341.0,"\u05dc\u05e4\u05d9 \u05ea\u05e7\u05e0\u05d9\u05dd \u05db\u05de\u05d5 76 \u05d0\u05d5\u05e1, \u05db\u05d3\u05d9 \u05e9\u05d4\u05d4\u05d1\u05e8\u05d2\u05d4 \u05ea\u05d4\u05d9\u05d4 \u05de\u05dc\u05d0\u05d4 \u05e2\u05d3 \u05d4\u05db\u05ea\u05e3."],[348.0,"\u05d4\u05d1\u05e8\u05d2\u05d5\u05ea \u05e0\u05d1\u05d3\u05e7\u05d5\u05ea \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05de\u05d3\u05d9\u05dd: \u05de\u05d3 \u05e4\u05e7\u05e7 \u05dc\u05d4\u05d1\u05e8\u05d2\u05d4 \u05e4\u05e0\u05d9\u05de\u05d9\u05ea, \u05d5\u05de\u05d3 \u05d8\u05d1\u05e2\u05ea \u05dc\u05d4\u05d1\u05e8\u05d2\u05d4 \u05d7\u05d9\u05e6\u05d5\u05e0\u05d9\u05ea."],[356.0,"\u05dc\u05db\u05dc \u05de\u05d3\u05d9\u05e9 \u05e6\u05d3 \u05e2\u05d5\u05d1\u05e8 \u05d5\u05e6\u05d3 \u05dc\u05d0 \u05e2\u05d5\u05d1\u05e8."],[360.0,"\u05d4\u05e6\u05d3 \u05d4\u05e2\u05d5\u05d1\u05e8 \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d9\u05db\u05e0\u05e1 \u05dc\u05db\u05dc \u05d0\u05d5\u05e8\u05da \u05d4\u05d4\u05d1\u05e8\u05d2\u05d4 \u05d1\u05dc\u05d9 \u05db\u05d5\u05d7."],[365.0,"\u05d4\u05e6\u05d3 \u05d4\u05dc\u05d0 \u05e2\u05d5\u05d1\u05e8 \u05de\u05d5\u05ea\u05e8 \u05e9\u05d9\u05d9\u05db\u05e0\u05e1 \u05e2\u05d3 \u05db\u05e9\u05d5\u05e0\u05d9 \u05e1\u05d9\u05d1\u05d5\u05d1\u05d9\u05dd, \u05d5\u05dc\u05d0 \u05d9\u05d5\u05ea\u05e8."],[371.0,"\u05d5\u05d4\u05de\u05d3\u05d9\u05dd \u05e6\u05e8\u05d9\u05db\u05d9\u05dd \u05dc\u05d4\u05d9\u05d5\u05ea \u05d1\u05d0\u05d5\u05ea\u05d4 \u05e1\u05d1\u05d5\u05dc\u05ea \u05e9\u05d1\u05e9\u05e8\u05d8\u05d5\u05d8: \u05de\u05d3 \u05d76 \u05dc\u05d4\u05d1\u05e8\u05d2\u05d4 \u05d7\u05e1."],[379.0,"\u05d4\u05d1\u05e8\u05d2\u05d4 \u05de\u05d8\u05e8\u05d9\u05ea \u05de\u05d5\u05dc \u05d0\u05d9\u05e0\u05e6'\u05d9\u05ea \u05d1\u05e7\u05d8\u05e8\u05d9\u05dd \u05e7\u05e8\u05d5\u05d1\u05d9\u05dd."],[383.0,"NPT \u05de\u05d5\u05dc \u2026, \u05d5-6 \u05de\u05d5\u05dc 8."],[388.0,"\u05e7\u05d3\u05d7 \u05de\u05e7\u05d3\u05d9\u05dd \u05e7\u05e6\u05e8 \u05de\u05d3\u05d9 \u05d1\u05e7\u05d3\u05d7 \u05e2\u05d9\u05d5\u05d5\u05e8."],[392.0,"\u05d4\u05d1\u05e8\u05d2\u05d4 \u05de\u05e6\u05d5\u05e4\u05d4 \u05d1\u05e1\u05d1\u05d5\u05dc\u05ea \u05e9\u05dc\u05d0 \u05de\u05e9\u05d0\u05d9\u05e8\u05d4 \u05de\u05e7\u05d5\u05dd \u05dc\u05e6\u05d9\u05e4\u05d5\u05d9."],[397.0,"\u05d4\u05dc\u05d9\u05e7\u05d5\u05d9\u05dc \u05d1\u05dc\u05d9 \u05de\u05d1\u05e8\u05d6 |51."],[400.0,"\u05d5\u05d4\u05d1\u05e8\u05d2\u05d4 \u05e9\u05de\u05d0\u05dc\u05d9\u05ea \u05e9\u05dc\u05d0 \u05e9\u05de\u05d5 \u05dc\u05d1 \u05d0\u05dc\u05d9\u05d4."],[403.0,"\u05d1\u05db\u05d9\u05ea\u05d5\u05d1 \u05de\u05d8\u05e8\u05d9: \u05e7\u05d5\u05d8\u05e8, \u05e4\u05e1\u05d9\u05e2\u05d4 \u05d0\u05dd \u05d4\u05d9\u05d0 \u05e2\u05d3\u05d9\u05e0\u05d4, \u05e1\u05d1\u05d5\u05dc\u05ea \u05d5\u05e2\u05d5\u05de\u05e7."],[410.0,"\u05d1\u05db\u05d9\u05ea\u05d5\u05d1 \u05d0\u05d9\u05e0\u05e6'\u05d9: \u05e7\u05d5\u05d8\u05e8, \u05db\u05e8\u05d9\u05db\u05d5\u05ea \u05dc\u05d0\u05d9\u05e0\u05e5, \u05e1\u05d3\u05e8\u05d4, \u05de\u05d7\u05dc\u05e7\u05d4, \u05d5-\u05d0 \u05d0\u05d5 \u05dd."],[419.0,"\u05d1\u05d4\u05d1\u05e8\u05d2\u05d5\u05ea \u05e6\u05e0\u05e8\u05ea, \u05d4\u05de\u05e1\u05e4\u05e8 \u05d4\u05d5\u05d0 \u05e9\u05dd \u05d5\u05dc\u05d0 \u05e7\u05d5\u05d8\u05e8, \u05d5\u05e0\u05d1\u05d3\u05dc \u05d1\u05d9\u05df \u05e7\u05d5\u05e0\u05d9 \u05dc\u05d9\u05e9\u05e8 \u05d5\u05d1\u05d9\u05df \u05d0\u05d9\u05d8\u05d5\u05dd \u05e2\u05dc \u05d4\u05d4\u05d1\u05e8\u05d2\u05d4 \u05dc\u05d0\u05d9\u05d8\u05d5\u05dd \u05d1\u05d0\u05d8\u05dd."],[431.0,"\u05d1\u05d4\u05dc\u05d9\u05e7\u05d5\u05d9\u05dc, \u05d4\u05e7\u05d3\u05d7 \u05de\u05d5\u05d1\u05e8\u05d2 \u05d1-\u05d551, \u05d5\u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05de\u05e8\u05d0\u05d4 \u05d0\u05ea \u05d4\u05d4\u05d1\u05e8\u05d2\u05d4 \u05d4\u05e1\u05d5\u05e4\u05d9\u05ea."],[438.0,"\u05d5\u05d4\u05d1\u05d3\u05d9\u05e7\u05d4 \u05d1\u05de\u05d3 \u05e2\u05d5\u05d1\u05e8 \u05d5\u05dc\u05d0 \u05e2\u05d5\u05d1\u05e8, \u05d1\u05d0\u05d5\u05ea\u05d4 \u05e1\u05d1\u05d5\u05dc\u05ea \u05e9\u05d1\u05e9\u05e8\u05d8\u05d5\u05d8."],[443.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05db\u05d9\u05e8 \u05d0\u05dc\u05de\u05e0\u05d8\u05d9\u05dd \u05de\u05d9\u05d5\u05d7\u05d3\u05d9\u05dd: \u05e9\u05d1\u05d9\u05e8\u05ea \u05e1\u05d9\u05e0\u05d5\u05ea, \u05ea\u05e2\u05dc\u05d5\u05ea,"],[449.0,"\u05e1\u05e4\u05dc\u05d9\u05d9\u05e0\u05d9\u05dd \u05d5\u05d8\u05d1\u05dc\u05d0\u05d5\u05ea \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8. \u05e0\u05ea\u05e8\u05d0\u05d4 \u05d1\u05e4\u05e8\u05e7 \u05d7\u05de\u05e9 \u05e2\u05e9\u05e8\u05d4."]]};
window.MH_TR["ch15"]={"t":"\u05d0\u05dc\u05de\u05e0\u05d8\u05d9\u05dd \u05de\u05d9\u05d5\u05d7\u05d3\u05d9\u05dd","l":[[1.0,"\u05d9\u05e9 \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d0\u05dc\u05de\u05e0\u05d8\u05d9\u05dd \u05e7\u05d8\u05e0\u05d9\u05dd, \u05e9\u05ea\u05d5\u05e4\u05e1\u05d9\u05dd \u05de\u05e2\u05d8 \u05de\u05e7\u05d5\u05dd, \u05d0\u05d1\u05dc \u05de\u05d2\u05d3\u05d9\u05e8\u05d9\u05dd \u05d4\u05e8\u05d1\u05d4."],[7.0,"\u05e4\u05d9\u05e0\u05d4, \u05ea\u05e2\u05dc\u05d4 \u05e7\u05d8\u05e0\u05d4 \u05d1\u05e1\u05d5\u05e3 \u05e6\u05d9\u05e8, \u05e1\u05e4\u05dc\u05d9\u05d9\u05df \u05d0\u05d5 \u05d8\u05d1\u05dc\u05d4 \u05d1\u05e4\u05d9\u05e0\u05ea \u05d4\u05d2\u05d9\u05dc\u05d9\u05d5\u05df"],[13.0,"\u05d9\u05db\u05d5\u05dc\u05d9\u05dd \u05dc\u05e7\u05d1\u05d5\u05e2 \u05d0\u05dd \u05d4\u05d7\u05dc\u05e7 \u05d9\u05d5\u05e8\u05db\u05d1, \u05d9\u05d7\u05d6\u05d9\u05e7 \u05d5\u05d9\u05e2\u05d1\u05d5\u05e8 \u05d1\u05d3\u05d9\u05e7\u05d4."],[18.0,"\u05dc\u05e8\u05d5\u05d1 \u05d4\u05dd \u05de\u05d5\u05d2\u05d3\u05e8\u05d9\u05dd \u05d1\u05d4\u05e4\u05e0\u05d9\u05d4 \u05dc\u05ea\u05e7\u05df, \u05d5\u05dc\u05d0 \u05d1\u05e6\u05d9\u05d5\u05e8 \u05de\u05dc\u05d0, \u05d5\u05dc\u05db\u05df \u05e6\u05e8\u05d9\u05da \u05dc\u05d3\u05e2\u05ea \u05dc\u05e7\u05e8\u05d5\u05d0 \u05d0\u05ea \u05d4\u05d4\u05e4\u05e0\u05d9\u05d4."],[26.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05e2\u05d1\u05d5\u05e8 \u05e2\u05dc \u05e9\u05d1\u05d9\u05e8\u05ea \u05e4\u05d9\u05e0\u05d5\u05ea, \u05ea\u05e2\u05dc\u05d5\u05ea \u05d9\u05e6\u05d9\u05d0\u05d4, \u05e1\u05e4\u05dc\u05d9\u05d9\u05e0\u05d9\u05dd, \u05e9\u05d2\u05de\u05d9\u05dd, \u05e7\u05d3\u05d7\u05d9 \u05de\u05e8\u05db\u05d5\u05d6, \u05d7\u05d9\u05e8\u05d5\u05e5 \u05d5\u05d8\u05d1\u05dc\u05d0\u05d5\u05ea."],[37.0,"\u05d4\u05e2\u05e8\u05d4 \u05db\u05de\u05d5 \u05e9\u05d1\u05d5\u05e8 \u05e4\u05d9\u05e0\u05d5\u05ea \u05d7\u05d3\u05d5\u05ea \u05d4\u05d9\u05d0 \u05d0\u05d7\u05ea \u05d4\u05d4\u05e2\u05e8\u05d5\u05ea \u05d4\u05e0\u05e4\u05d5\u05e6\u05d5\u05ea \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8, \u05d5\u05d4\u05d9\u05d0 \u05d2\u05dd \u05d0\u05d7\u05ea \u05d4\u05e4\u05d7\u05d5\u05ea \u05de\u05d5\u05d2\u05d3\u05e8\u05d5\u05ea."],[45.0,"\u05db\u05de\u05d4 \u05dc\u05e9\u05d1\u05d5\u05e8? \u05d1\u05e9\u05d9\u05e4\u05d5\u05e2 \u05d0\u05d5 \u05d1\u05e8\u05d3\u05d9\u05d5\u05e1? \u05d5\u05de\u05d4 \u05de\u05d5\u05ea\u05e8 \u05dc\u05d4\u05e9\u05d0\u05d9\u05e8?"],[50.0,"\u05ea\u05e7\u05df13715 ISO \u05e0\u05d5\u05ea\u05df \u05dc\u05d6\u05d4 \u05e9\u05e4\u05d4 \u05de\u05d3\u05d5\u05d9\u05e7\u05ea: \u05e1\u05de\u05dc \u05dc\u05d9\u05d3 \u05d4\u05e4\u05d9\u05e0\u05d4, \u05d5\u05de\u05e1\u05e4\u05e8 \u05e2\u05dd \u05e1\u05d9\u05de\u05df."],[60.0,"\u05de\u05e1\u05e4\u05e8 \u05d7\u05d9\u05d5\u05d1\u05d9 \u05e4\u05d9\u05e8\u05d5\u05e9\u05d5 \u05e9\u05de\u05d5\u05ea\u05e8 \u05e9\u05d9\u05d9\u05e9\u05d0\u05e8 \u05d7\u05d5\u05de\u05e8 \u05de\u05e2\u05d1\u05e8 \u05dc\u05e4\u05d9\u05e0\u05d4 \u05d4\u05d0\u05d9\u05d3\u05d9\u05d0\u05dc\u05d9\u05ea, \u05db\u05de\u05d5 \u05d2\u05e8\u05d3, \u05e2\u05d3 \u05d4\u05e2\u05e8\u05da \u05d4\u05d6\u05d4."],[69.0,"\u05de\u05e1\u05e4\u05e8 \u05e9\u05dc\u05d9\u05dc\u05d9 \u05e4\u05d9\u05e8\u05d5\u05e9\u05d5 \u05e9\u05d4\u05e4\u05d9\u05e0\u05d4 \u05e6\u05e8\u05d9\u05db\u05d4 \u05dc\u05d4\u05d9\u05d5\u05ea \u05de\u05d5\u05e1\u05e8\u05ea, \u05d1\u05e9\u05d9\u05e4\u05d5\u05e2 \u05d0\u05d5 \u05d1\u05e8\u05d3\u05d9\u05d5\u05e1, \u05e2\u05d3 \u05d4\u05e2\u05d5\u05de\u05e7 \u05d4\u05d6\u05d4."],[76.0,"\u05d5\u05e4\u05dc\u05d5\u05e1 \u05de\u05d9\u05e0\u05d5\u05e1 \u05e4\u05d9\u05e8\u05d5\u05e9\u05d5 \u05e9\u05de\u05d5\u05ea\u05e8 \u05d2\u05dd \u05d5\u05d2\u05dd, \u05d1\u05ea\u05d5\u05da \u05d4\u05d2\u05d1\u05d5\u05dc."],[81.0,"\u05d4\u05e2\u05e8\u05d4 \u05db\u05dc\u05dc\u05d9\u05ea \u05dc\u05e1\u05d9 \u05d4\u05ea\u05e7\u05df, \u05dc\u05d9\u05d3 \u05d0\u05d6\u05d5\u05e8 \u05d4\u05db\u05d5\u05ea\u05e8\u05ea, \u05de\u05d2\u05d3\u05d9\u05e8\u05d4 \u05d0\u05ea \u05db\u05dc \u05d4\u05e4\u05d9\u05e0\u05d5\u05ea \u05e9\u05dc\u05d0 \u05e1\u05d5\u05de\u05e0\u05d5 \u05d0\u05d7\u05e8\u05ea, \u05db\u05de\u05d5 \u05e1\u05d1\u05d5\u05dc\u05ea \u05db\u05dc\u05dc\u05d9\u05ea."],[92.0,"\u05d1\u05e1\u05d5\u05e3 \u05e6\u05d9\u05e8 \u05de\u05d5\u05e9\u05d7\u05d6, \u05dc\u05d9\u05d3 \u05d4\u05db\u05ea\u05e3, \u05de\u05d5\u05e4\u05d9\u05e2\u05d4 \u05dc\u05e2\u05d9\u05ea\u05d9\u05dd \u05e7\u05e8\u05d5\u05d1\u05d5\u05ea \u05ea\u05e2\u05dc\u05ea \u05d9\u05e6\u05d9\u05d0\u05d4 \u05e7\u05d8\u05e0\u05d4."],[98.0,"\u05d1\u05dc\u05e2\u05d3\u05d9\u05d4, \u05d0\u05d1\u05df \u05d4\u05d4\u05e9\u05d7\u05d6\u05d4 \u05d0\u05d5 \u05d4\u05db\u05dc\u05d9 \u05de\u05e9\u05d0\u05d9\u05e8\u05d9\u05dd \u05e8\u05d3\u05d9\u05d5\u05e1 \u05e7\u05d8\u05df \u05d1\u05e4\u05d9\u05e0\u05d4, \u05d5\u05d4\u05d7\u05dc\u05e7 \u05d4\u05de\u05ea\u05d7\u05d1\u05e8 \u05dc\u05d0 \u05d9\u05d9\u05e9\u05d1 \u05e6\u05de\u05d5\u05d3 \u05dc\u05db\u05ea\u05e3."],[108.0,"\u05d4\u05ea\u05e2\u05dc\u05d4 \u05de\u05d5\u05d2\u05d3\u05e8\u05ea \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05d4\u05e4\u05e0\u05d9\u05d4 \u05dc\u05ea\u05e7\u05df, \u05db\u05de\u05d5 509 \u05d0\u05d5\u05e1, \u05e2\u05dd \u05e6\u05d5\u05e8\u05d4 \u05d5\u05de\u05d9\u05d3\u05d5\u05ea, \u05dc\u05de\u05e9\u05dc 6 \u05d0\u05d7\u05ea \u05e2\u05dc \u05e9\u05ea\u05d9 \u05e2\u05e9\u05d9\u05e8\u05d9\u05d5\u05ea."],[120.0,"\u05d4\u05d0\u05d5\u05ea \u05de\u05e1\u05de\u05e0\u05ea \u05d0\u05ea \u05e6\u05d5\u05e8\u05ea \u05d4\u05ea\u05e2\u05dc\u05d4, \u05d5\u05d4\u05de\u05e1\u05e4\u05e8\u05d9\u05dd \u05d0\u05ea \u05d4\u05e8\u05d3\u05d9\u05d5\u05e1 \u05d5\u05d0\u05ea \u05d4\u05e2\u05d5\u05de\u05e7."],[126.0,"\u05de\u05d9 \u05e9\u05de\u05d7\u05dc\u05d9\u05e3 \u05d0\u05ea \u05d4\u05ea\u05e2\u05dc\u05d4 \u05d1\u05e8\u05d3\u05d9\u05d5\u05e1 \u05e8\u05d2\u05d9\u05dc, \u05de\u05e9\u05e0\u05d4 \u05d0\u05ea \u05d0\u05d5\u05e8\u05da \u05d4\u05de\u05d2\u05e2 \u05d5\u05d0\u05ea \u05e8\u05d9\u05db\u05d5\u05d6 \u05d4\u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05d1\u05e4\u05d9\u05e0\u05d4."],[133.0,"\u05e1\u05e4\u05dc\u05d9\u05d9\u05df \u05d4\u05d5\u05d0 \u05e6\u05d9\u05e8 \u05e2\u05dd \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd \u05e9\u05de\u05e2\u05d1\u05d9\u05e8 \u05de\u05d5\u05de\u05e0\u05d8 \u05dc\u05e8\u05db\u05d6\u05ea."],[138.0,"\u05db\u05de\u05d5 \u05d2\u05dc\u05d2\u05dc \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd, \u05d4\u05d5\u05d0 \u05de\u05e6\u05d5\u05d9\u05e8 \u05d1\u05d9\u05d9\u05e6\u05d5\u05d2 \u05de\u05e4\u05d5\u05e9\u05d8, \u05d5\u05db\u05dc \u05d4\u05d4\u05d2\u05d3\u05e8\u05d4 \u05e0\u05de\u05e6\u05d0\u05ea \u05d1\u05d8\u05d1\u05dc\u05ea \u05e0\u05ea\u05d5\u05e0\u05d9\u05dd."],[145.0,"\u05d1\u05d8\u05d1\u05dc\u05d4 \u05de\u05d5\u05e4\u05d9\u05e2\u05d9\u05dd \u05de\u05e1\u05e4\u05e8 \u05d4\u05e9\u05d9\u05e0\u05d9\u05d9\u05dd, \u05d4\u05de\u05d5\u05d3\u05d5\u05dc, \u05d6\u05d5\u05d5\u05d9\u05ea \u05d4\u05dc\u05d7\u05e5,"],[153.0,"\u05d3\u05e8\u05d2\u05ea \u05d4\u05e1\u05d1\u05d5\u05dc\u05ea \u05d5\u05e1\u05d5\u05d2 \u05d4\u05d4\u05ea\u05d0\u05de\u05d4, \u05dc\u05e4\u05d9 \u05ea\u05e7\u05df \u05db\u05de\u05d5 4156 50! \u05d0\u05d5 DIN. 5480"],[163.0,"\u05d5\u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05de\u05d5\u05e4\u05d9\u05e2\u05d4 \u05d2\u05dd \u05de\u05d9\u05d3\u05ea \u05d1\u05d3\u05d9\u05e7\u05d4: \u05de\u05d3\u05d9\u05d3\u05d4 \u05de\u05e2\u05dc \u05e4\u05d9\u05e0\u05d9\u05dd \u05d1\u05e1\u05e4\u05dc\u05d9\u05d9\u05df \u05d7\u05d9\u05e6\u05d5\u05e0\u05d9, \u05d0\u05d5 \u05d1\u05d9\u05df \u05e4\u05d9\u05e0\u05d9\u05dd \u05d1\u05e1\u05e4\u05dc\u05d9\u05d9\u05df \u05e4\u05e0\u05d9\u05de\u05d9."],[173.0,"\u05d6\u05d5 \u05d4\u05de\u05d9\u05d3\u05d4 \u05e9\u05e0\u05d1\u05d3\u05e7\u05ea \u05d1\u05e4\u05d5\u05e2\u05dc, \u05d5\u05dc\u05db\u05df \u05d4\u05d9\u05d0 \u05d7\u05e9\u05d5\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05de\u05db\u05dc \u05de\u05d9\u05d3\u05d4 \u05d0\u05d7\u05e8\u05ea \u05d1\u05d8\u05d1\u05dc\u05d4."],[179.0,"\u05e9\u05d2\u05dd \u05d4\u05d5\u05d0 \u05ea\u05e2\u05dc\u05d4 \u05dc\u05e4\u05d9\u05df \u05de\u05e8\u05d5\u05d1\u05e2, \u05e9\u05de\u05e2\u05d1\u05d9\u05e8 \u05de\u05d5\u05de\u05e0\u05d8 \u05d1\u05d9\u05df \u05e6\u05d9\u05e8 \u05dc\u05e8\u05db\u05d6\u05ea."],[185.0,"\u05de\u05d9\u05d3\u05d5\u05ea \u05d4\u05e9\u05d2\u05dd \u05e0\u05dc\u05e7\u05d7\u05d5\u05ea \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05de\u05ea\u05e7\u05df, \u05db\u05de\u05d5 6885 \u05d0\u05d5\u05e1, \u05dc\u05e4\u05d9 \u05e7\u05d5\u05d8\u05e8 \u05d4\u05e6\u05d9\u05e8."],[195.0,"\u05e8\u05d5\u05d7\u05d1 \u05d4\u05ea\u05e2\u05dc\u05d4 \u05de\u05e7\u05d1\u05dc \u05e1\u05d1\u05d5\u05dc\u05ea \u05de\u05ea\u05e7\u05df \u05d4\u05d4\u05ea\u05d0\u05de\u05d5\u05ea, \u05db\u05de\u05d5 N9 \u05dc\u05d4\u05ea\u05d0\u05de\u05d4 \u05e8\u05d2\u05d9\u05dc\u05d4 \u05d0\u05d5 9\u05dd \u05dc\u05d4\u05ea\u05d0\u05de\u05d4 \u05d4\u05d3\u05d5\u05e7\u05d4."],[205.0,"\u05d5\u05d4\u05e2\u05d5\u05de\u05e7 \u05de\u05de\u05d5\u05d3\u05d3 \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05de\u05d4\u05e6\u05d3 \u05d4\u05e0\u05d2\u05d3\u05d9 \u05e9\u05dc \u05d4\u05e6\u05d9\u05e8, \u05d5\u05dc\u05d0 \u05de\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7, \u05db\u05d3\u05d9 \u05e9\u05d0\u05e4\u05e9\u05e8 \u05d9\u05d4\u05d9\u05d4 \u05dc\u05de\u05d3\u05d5\u05d3 \u05d0\u05d5\u05ea\u05d5 \u05d9\u05e9\u05d9\u05e8\u05d5\u05ea."],[214.0,"\u05de\u05d9 \u05e9\u05de\u05d5\u05d3\u05d3 \u05d0\u05ea \u05d4\u05e2\u05d5\u05de\u05e7 \u05de\u05e0\u05e7\u05d5\u05d3\u05d4 \u05d0\u05d7\u05e8\u05ea \u05de\u05de\u05d4 \u05e9\u05de\u05d5\u05d3\u05d3 \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8, \u05d9\u05e7\u05d1\u05dc \u05de\u05e1\u05e4\u05e8 \u05d0\u05d7\u05e8 \u05d5\u05d9\u05d8\u05e2\u05d4 \u05d1\u05e7\u05d1\u05dc\u05d4."],[223.0,"\u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05e9\u05de\u05e2\u05d5\u05d1\u05d3\u05d9\u05dd \u05d1\u05d9\u05df \u05de\u05e8\u05db\u05d6\u05d9\u05dd, \u05d4\u05e7\u05e6\u05d4 \u05e9\u05dc \u05d4\u05e6\u05d9\u05e8 \u05de\u05e7\u05d1\u05dc \u05e7\u05d3\u05d7 \u05de\u05e8\u05db\u05d5\u05d6."],[229.0,"\u05d4\u05d5\u05d0 \u05de\u05d5\u05d2\u05d3\u05e8 \u05dc\u05e4\u05d9 6411 50\u05d5, \u05e2\u05dd \u05e6\u05d5\u05e8\u05d4 \u05d5\u05e7\u05d8\u05e8\u05d9\u05dd, \u05dc\u05de\u05e9\u05dc \u05d0 \u05e9\u05ea\u05d9\u05d9\u05dd \u05d5\u05d7\u05e6\u05d9 \u05e2\u05dc \u05d7\u05de\u05e9 \u05e0\u05e7\u05d5\u05d3\u05d4 \u05e9\u05dc\u05d5\u05e9."],[239.0,"\u05d5\u05d4\u05ea\u05e7\u05df \u05e0\u05d5\u05ea\u05df \u05d2\u05dd \u05e9\u05dc\u05d5\u05e9\u05d4 \u05e1\u05d9\u05de\u05e0\u05d9\u05dd: \u05e7\u05d3\u05d7 \u05d4\u05de\u05e8\u05db\u05d5\u05d6 \u05d7\u05d9\u05d9\u05d1 \u05dc\u05d4\u05d9\u05e9\u05d0\u05e8, \u05de\u05d5\u05ea\u05e8 \u05e9\u05d9\u05d9\u05e9\u05d0\u05e8, \u05d0\u05d5 \u05d0\u05e1\u05d5\u05e8 \u05e9\u05d9\u05d9\u05e9\u05d0\u05e8."],[249.0,"\u05d6\u05d4 \u05d7\u05e9\u05d5\u05d1, \u05db\u05d9 \u05e7\u05d3\u05d7 \u05de\u05e8\u05db\u05d5\u05d6 \u05e9\u05e0\u05e9\u05d0\u05e8 \u05d9\u05db\u05d5\u05dc \u05dc\u05e9\u05de\u05e9 \u05dc\u05d1\u05d3\u05d9\u05e7\u05d4 \u05d5\u05dc\u05ea\u05d9\u05e7\u05d5\u05df \u05d1\u05e2\u05ea\u05d9\u05d3, \u05d0\u05d5 \u05dc\u05d4\u05e4\u05e8\u05d9\u05e2 \u05dc\u05d7\u05dc\u05e7 \u05d4\u05de\u05ea\u05d7\u05d1\u05e8."],[258.0,"\u05d7\u05d9\u05e8\u05d5\u05e5 \u05d4\u05d5\u05d0 \u05d3\u05d5\u05d2\u05de\u05d4 \u05e9\u05de\u05d2\u05d5\u05dc\u05d2\u05dc\u05ea \u05e2\u05dc \u05e4\u05e0\u05d9 \u05e6\u05d9\u05e8, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05db\u05d3\u05d9 \u05e9\u05d0\u05e4\u05e9\u05e8\u05d9\u05d4\u05d9\u05d4 \u05dc\u05d0\u05d7\u05d5\u05d6 \u05d1\u05d5 \u05d0\u05d5 \u05dc\u05dc\u05d7\u05d5\u05e5 \u05d0\u05d5\u05ea\u05d5 \u05dc\u05ea\u05d5\u05da \u05d7\u05dc\u05e7 \u05d0\u05d7\u05e8."],[267.0,"\u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05de\u05d5\u05e4\u05d9\u05e2\u05d9\u05dd \u05e1\u05d5\u05d2 \u05d4\u05d7\u05d9\u05e8\u05d5\u05e5, \u05d9\u05e9\u05e8 \u05d0\u05d5 \u05de\u05d5\u05e6\u05dc\u05d1, \u05d4\u05e4\u05e1\u05d9\u05e2\u05d4, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05ea\u05e7\u05df \u05db\u05de\u05d5 82 \u05d0\u05d5\u05e1."],[277.0,"\u05d7\u05d9\u05e8\u05d5\u05e5 \u05de\u05d2\u05d3\u05d9\u05dc \u05d0\u05ea \u05d4\u05e7\u05d5\u05d8\u05e8, \u05d5\u05dc\u05db\u05df \u05db\u05e9\u05d4\u05d5\u05d0 \u05de\u05e9\u05de\u05e9 \u05dc\u05d4\u05e8\u05db\u05d1\u05d4 \u05d1\u05dc\u05d7\u05d9\u05e6\u05d4, \u05d4\u05e7\u05d5\u05d8\u05e8 \u05e9\u05d0\u05d7\u05e8\u05d9\u05d5 \u05d4\u05d5\u05d0 \u05d4\u05de\u05d9\u05d3\u05d4 \u05d4\u05d7\u05e9\u05d5\u05d1\u05d4."],[286.0,"\u05d8\u05d1\u05dc\u05d0\u05d5\u05ea \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d4\u05df \u05d3\u05e8\u05da \u05dc\u05e8\u05db\u05d6 \u05d4\u05e8\u05d1\u05d4 \u05de\u05d9\u05d3\u05e2 \u05d1\u05de\u05e7\u05d5\u05dd \u05d0\u05d7\u05d3."],[291.0,"\u05d8\u05d1\u05dc\u05ea \u05d5\u05e8\u05d9\u05d0\u05e0\u05d8\u05d9\u05dd, \u05dc\u05de\u05e9\u05dc, \u05de\u05d2\u05d3\u05d9\u05e8\u05d4 \u05db\u05de\u05d4 \u05d7\u05dc\u05e7\u05d9\u05dd \u05d3\u05d5\u05de\u05d9\u05dd \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d0\u05d7\u05d3:"],[297.0,"\u05db\u05dc \u05e9\u05d5\u05e8\u05d4 \u05d4\u05d9\u05d0 \u05de\u05e7\"\u05d8, \u05d5\u05db\u05dc \u05e2\u05de\u05d5\u05d3\u05d4 \u05de\u05d9\u05d3\u05d4 \u05e2\u05dd \u05d0\u05d5\u05ea."],[302.0,"\u05d1\u05e6\u05d9\u05d5\u05e8 \u05db\u05ea\u05d5\u05d1\u05d5\u05ea \u05d4\u05d0\u05d5\u05ea\u05d9\u05d5\u05ea, \u05d5\u05d1\u05d8\u05d1\u05dc\u05d4 \u05d4\u05e2\u05e8\u05db\u05d9\u05dd \u05dc\u05db\u05dc \u05de\u05e7\"\u05d8."],[307.0,"\u05d5\u05dc\u05db\u05df \u05d4\u05e6\u05e2\u05d3 \u05d4\u05e8\u05d0\u05e9\u05d5\u05df \u05d4\u05d5\u05d0 \u05dc\u05d6\u05d4\u05d5\u05ea \u05d0\u05d9\u05d6\u05d5 \u05e9\u05d5\u05e8\u05d4 \u05e9\u05d9\u05d9\u05db\u05ea \u05dc\u05d7\u05dc\u05e7 \u05e9\u05de\u05d9\u05d9\u05e6\u05e8\u05d9\u05dd, \u05d5\u05e8\u05e7 \u05d0\u05d7\u05e8 \u05db\u05da \u05dc\u05e7\u05e8\u05d5\u05d0 \u05de\u05d9\u05d3\u05d5\u05ea."],[316.0,"\u05d8\u05e2\u05d5\u05ea \u05d1\u05e9\u05d5\u05e8\u05d4 \u05d4\u05d9\u05d0 \u05d8\u05e2\u05d5\u05ea \u05d1\u05db\u05dc \u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05d1\u05ea \u05d0\u05d7\u05ea."],[320.0,"\u05d1\u05d0\u05d5\u05ea\u05d5 \u05d0\u05d5\u05e4\u05df \u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05d8\u05d1\u05dc\u05ea \u05e7\u05d3\u05d7\u05d9\u05dd, \u05d8\u05d1\u05dc\u05ea \u05db\u05d9\u05e4\u05d5\u05e4\u05d9\u05dd \u05d1\u05e4\u05d7,"],[325.0,"\u05d0\u05d5 \u05d8\u05d1\u05dc\u05ea \u05e0\u05ea\u05d5\u05e0\u05d9 \u05e1\u05e4\u05dc\u05d9\u05d9\u05df: \u05de\u05d6\u05d4\u05d9\u05dd \u05d0\u05ea \u05d4\u05e9\u05d5\u05e8\u05d4, \u05d5\u05d0\u05d6 \u05d0\u05ea \u05d4\u05e2\u05de\u05d5\u05d3\u05d4."],[332.0,"\u05e8\u05d9\u05db\u05d5\u05d6 \u05d4\u05de\u05dc\u05db\u05d5\u05d3\u05d5\u05ea \u05d1\u05d0\u05dc\u05de\u05e0\u05d8\u05d9\u05dd \u05d4\u05de\u05d9\u05d5\u05d7\u05d3\u05d9\u05dd."],[335.0,"\u05e9\u05d1\u05d5\u05e8 \u05e4\u05d9\u05e0\u05d5\u05ea \u05d1\u05dc\u05d9 \u05e2\u05e8\u05da \u05d4\u05d5\u05d0 \u05d3\u05e8\u05d9\u05e9\u05d4 \u05dc\u05d0 \u05de\u05d5\u05d2\u05d3\u05e8\u05ea. \u05e2\u05d3\u05d9\u05e3 \u05d4\u05e4\u05e0\u05d9\u05d4 \u05dc\u05ea\u05e7\u05df \u05e2\u05dd \u05de\u05e1\u05e4\u05e8 \u05d5\u05e1\u05d9\u05de\u05df."],[342.0,"\u05ea\u05e2\u05dc\u05ea \u05d9\u05e6\u05d9\u05d0\u05d4 \u05e9\u05d4\u05d5\u05d7\u05dc\u05e4\u05d4 \u05d1\u05e8\u05d3\u05d9\u05d5\u05e1 \u05de\u05e9\u05e0\u05d4 \u05d0\u05ea \u05d4\u05d9\u05e9\u05d9\u05d1\u05d4 \u05e2\u05dc \u05d4\u05db\u05ea\u05e3."],[348.0,"\u05d1\u05e1\u05e4\u05dc\u05d9\u05d9\u05df, \u05de\u05d9\u05d3\u05ea \u05d4\u05d1\u05d3\u05d9\u05e7\u05d4 \u05de\u05e2\u05dc \u05d0\u05d5 \u05d1\u05d9\u05df \u05e4\u05d9\u05e0\u05d9\u05dd \u05d4\u05d9\u05d0 \u05d4\u05e7\u05d5\u05d1\u05e2\u05ea."],[353.0,"\u05d1\u05e9\u05d2\u05dd, \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05de\u05d0\u05d9\u05d8\u05d5 \u05e0\u05e7\u05d5\u05d3\u05d4 \u05de\u05de\u05d5\u05d3\u05d3 \u05d4\u05e2\u05d5\u05de\u05e7."],[358.0,"\u05d5\u05d1\u05e0\u05d8\u05d1\u05dc\u05d0\u05d5\u05ea, \u05de\u05d6\u05d4\u05d9\u05dd \u05e7\u05d5\u05d3\u05dd \u05d0\u05ea \u05d4\u05e9\u05d5\u05e8\u05d4 \u05d4\u05e0\u05db\u05d5\u05e0\u05d4."],[362.0,"\u05d0\u05dc\u05de\u05e0\u05d8\u05d9\u05dd \u05e7\u05d8\u05e0\u05d9\u05dd \u05de\u05d5\u05d2\u05d3\u05e8\u05d9\u05dd \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05d4\u05e4\u05e0\u05d9\u05d4 \u05dc\u05ea\u05e7\u05df, \u05d5\u05dc\u05d0 \u05d1\u05e6\u05d9\u05d5\u05e8."],[368.0,"\u05e4\u05d9\u05e0\u05d5\u05ea \u05dc\u05e4\u05d9 13715 50\u05d5: \u05d7\u05d9\u05d5\u05d1\u05d9 \u05de\u05d5\u05ea\u05e8 \u05d7\u05d5\u05de\u05e8, \u05e9\u05dc\u05d9\u05dc\u05d9 \u05d7\u05d9\u05d9\u05d1 \u05d4\u05e1\u05e8\u05d4."],[377.0,"\u05ea\u05e2\u05dc\u05d5\u05ea \u05dc\u05e4\u05d9 509 DIN, \u05e9\u05d2\u05de\u05d9\u05dd \u05dc\u05e4\u05d9 6885 \u05d0\u05d5\u05e1, \u05d5\u05e7\u05d3\u05d7\u05d9 \u05de\u05e8\u05db\u05d5\u05d6 \u05dc\u05e4\u05d9 6411 50!."],[392.0,"\u05e1\u05e4\u05dc\u05d9\u05d9\u05e0\u05d9\u05dd \u05d1\u05d8\u05d1\u05dc\u05ea \u05e0\u05ea\u05d5\u05e0\u05d9\u05dd, \u05e2\u05dd \u05de\u05d9\u05d3\u05ea \u05d1\u05d3\u05d9\u05e7\u05d4 \u05de\u05e2\u05dc \u05d0\u05d5 \u05d1\u05d9\u05df \u05e4\u05d9\u05e0\u05d9\u05dd."],[398.0,"\u05d5\u05d1\u05db\u05dc \u05d8\u05d1\u05dc\u05d4 \u05de\u05d6\u05d4\u05d9\u05dd \u05e9\u05d5\u05e8\u05d4, \u05d5\u05d0\u05d6 \u05e2\u05de\u05d5\u05d3\u05d4."],[402.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05de\u05ea\u05d7\u05d9\u05dc \u05d4\u05d7\u05dc\u05e7 \u05d4\u05d7\u05de\u05d9\u05e9\u05d9: \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05db\u05de\u05e1\u05de\u05da."],[407.0,"\u05e0\u05ea\u05d7\u05d9\u05dc \u05d1\u05d0\u05d6\u05d5\u05e8 \u05d4\u05db\u05d5\u05ea\u05e8\u05ea \u05d5\u05d1\u05d4\u05e2\u05e8\u05d5\u05ea. \u05e0\u05ea\u05e8\u05d0\u05d4 \u05d1\u05e4\u05e8\u05e7 \u05e9\u05e9\u05d5 \u05e2\u05e9\u05e8\u05d4."]]};
window.MH_TR["ch16"]={"t":"\u05d0\u05d6\u05d5\u05e8 \u05d4\u05db\u05d5\u05ea\u05e8\u05ea \u05d5\u05d4\u05d4\u05e2\u05e8\u05d5\u05ea","l":[[1.0,"\u05d4\u05d7\u05dc\u05e7 \u05d4\u05d7\u05de\u05d9\u05e9\u05d9 \u05e9\u05dc \u05d4\u05e7\u05d5\u05e8\u05e1 \u05e2\u05d5\u05e1\u05e7 \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u2026: \u05dc\u05d0 \u05e8\u05e7 \u05de\u05d4 \u05e9\u05de\u05e6\u05d5\u05d9\u05e8, \u05d0\u05dc\u05d0 \u05db\u05dc \u05de\u05d4 \u05e9\u05de\u05e1\u05d1\u05d9\u05d1."],[9.0,"\u05d5\u05d0\u05ea \u05d6\u05d4 \u05de\u05ea\u05d7\u05d9\u05dc\u05d9\u05dd \u05de\u05d0\u05d6\u05d5\u05e8 \u05d4\u05db\u05d5\u05ea\u05e8\u05ea, \u05d4\u05e4\u05d9\u05e0\u05d4 \u05d4\u05d9\u05de\u05e0\u05d9\u05ea \u05d4\u05ea\u05d7\u05ea\u05d5\u05e0\u05d4 \u05e9\u05dc \u05d4\u05d2\u05d9\u05dc\u05d9\u05d5\u05df."],[16.0,"\u05e8\u05d5\u05d1 \u05d4\u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05de\u05e1\u05ea\u05db\u05dc\u05d9\u05dd \u05d1\u05d4 \u05e8\u05e7 \u05db\u05d3\u05d9 \u05dc\u05de\u05e6\u05d5\u05d0 \u05d0\u05ea \u05d4\u05de\u05e1\u05e4\u05e8. \u05d0\u05d1\u05dc \u05d4\u05d9\u05d0 \u05de\u05d2\u05d3\u05d9\u05e8\u05d4 \u05d0\u05d9\u05da \u05dc\u05e7\u05e8\u05d5\u05d0 \u05d0\u05ea \u05db\u05dc \u05d4\u05e9\u05d0\u05e8."],[23.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05e2\u05d1\u05d5\u05e8 \u05e2\u05dc \u05d4\u05e9\u05d3\u05d5\u05ea \u05e9\u05dc \u05d0\u05d6\u05d5\u05e8 \u05d4\u05db\u05d5\u05ea\u05e8\u05ea, \u05e2\u05dc \u05d4\u05d4\u05e2\u05e8\u05d5\u05ea, \u05d5\u05e2\u05dc \u05d4\u05de\u05e1\u05de\u05db\u05d9\u05dd \u05e9\u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05de\u05e4\u05e0\u05d4 \u05d0\u05dc\u05d9\u05d4\u05dd."],[31.0,"\u05d4\u05ea\u05e7\u05df 7200 50\u05d5 \u05de\u05d2\u05d3\u05d9\u05e8 \u05d0\u05ea \u05d4\u05e9\u05d3\u05d5\u05ea \u05d4\u05d1\u05e1\u05d9\u05e1\u05d9\u05d9\u05dd: \u05db\u05d5\u05ea\u05e8\u05ea, \u05de\u05e1\u05e4\u05e8\u05d6\u05d9\u05d4\u05d5\u05d9,"],[39.0,"\u05e8\u05d5\u05d5\u05d9\u05d6\u05d9\u05d4, \u05ea\u05d0\u05e8\u05d9\u05da, \u05de\u05e1\u05e4\u05e8 \u05d2\u05d9\u05dc\u05d9\u05d5\u05df, \u05d5\u05d4\u05d1\u05e2\u05dc\u05d9\u05dd \u05e9\u05dc \u05d4\u05de\u05e1\u05de\u05da."],[45.0,"\u05d1\u05e9\u05e8\u05d8\u05d5\u05d8\u05d9\u05dd \u05dc\u05e4\u05d9 ASME \u05de\u05d5\u05e4\u05d9\u05e2\u05d9\u05dd \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d2\u05dd \u05d2\u05d5\u05d3\u05dc \u05d4\u05d2\u05d9\u05dc\u05d9\u05d5\u05df, \u05e7\u05e0\u05d4 \u05d4\u05de\u05d9\u05d3\u05d4, \u05e7\u05d5\u05d3 \u05d9\u05e6\u05e8\u05df, \u05d5\u05d1\u05dc\u05d5\u05e7 \u05d4\u05e1\u05d1\u05d5\u05dc\u05d5\u05ea \u05d4\u05db\u05dc\u05dc\u05d9\u05d5\u05ea."],[56.0,"\u05de\u05e1\u05e4\u05e8 \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d5\u05de\u05e1\u05e4\u05e8 \u05d4\u05d7\u05dc\u05e7 \u05d4\u05dd \u05dc\u05d0 \u05ea\u05de\u05d9\u05d3 \u05d0\u05d5\u05ea\u05d5 \u05de\u05e1\u05e4\u05e8."],[60.0,"\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d0\u05d7\u05d3 \u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05d2\u05d3\u05d9\u05e8 \u05db\u05de\u05d4 \u05d7\u05dc\u05e7\u05d9\u05dd, \u05db\u05de\u05d5 \u05e9\u05e8\u05d0\u05d9\u05e0\u05d5 \u05d1\u05d8\u05d1\u05dc\u05ea \u05d5\u05e8\u05d9\u05d0\u05e0\u05d8\u05d9\u05dd."],[67.0,"\u05d5\u05de\u05e1\u05e4\u05e8 \u05d4\u05d2\u05d9\u05dc\u05d9\u05d5\u05df, \u05dc\u05de\u05e9\u05dc \u05d0\u05d7\u05d3 \u05de\u05ea\u05d5\u05da \u05e9\u05dc\u05d5\u05e9\u05d4, \u05d0\u05d5\u05de\u05e8 \u05e9\u05d9\u05e9 \u05e2\u05d5\u05d3 \u05d2\u05d9\u05dc\u05d9\u05d5\u05e0\u05d5\u05ea, \u05d5\u05db\u05dc \u05d0\u05d7\u05d3 \u05de\u05d4\u05dd \u05d4\u05d5\u05d0 \u05d7\u05dc\u05e7 \u05de\u05d4\u05d4\u05d2\u05d3\u05e8\u05d4."],[76.0,"\u05de\u05d9 \u05e9\u05e2\u05d5\u05d1\u05d3 \u05de\u05d2\u05d9\u05dc\u05d9\u05d5\u05df \u05d0\u05d7\u05d3 \u05d1\u05dc\u05d1\u05d3, \u05e2\u05dc\u05d5\u05dc \u05dc\u05e4\u05e1\u05e4\u05e1 \u05de\u05d9\u05d3\u05d4, \u05d7\u05ea\u05da \u05d0\u05d5 \u05d4\u05e2\u05e8\u05d4 \u05e9\u05e0\u05de\u05e6\u05d0\u05d9\u05dd \u05d1\u05d2\u05d9\u05dc\u05d9\u05d5\u05df \u05d0\u05d7\u05e8."],[85.0,"\u05d4\u05e8\u05d5\u05d5\u05e1\u05d9\u05d4 \u05d4\u05d9\u05d0 \u05d0\u05d7\u05d3 \u05d4\u05e9\u05d3\u05d5\u05ea \u05d4\u05d7\u05e9\u05d5\u05d1\u05d9\u05dd \u05d1\u05d9\u05d5\u05ea\u05e8."],[89.0,"\u05d4\u05d9\u05d0 \u05d0\u05d5\u05de\u05e8\u05ea \u05d0\u05d9\u05d6\u05d5 \u05d2\u05e8\u05e1\u05d4 \u05e9\u05dc \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05e0\u05de\u05e6\u05d0\u05ea \u05d1\u05d9\u05d3\u05d9\u05d9\u05dd, \u05d5\u05db\u05dc \u05e9\u05d9\u05e0\u05d5\u05d9 \u05d1\u05d7\u05dc\u05e7 \u05de\u05e2\u05dc\u05d4 \u05d0\u05d5\u05ea\u05d4."],[96.0,"\u05dc\u05db\u05df \u05dc\u05e4\u05e0\u05d9 \u05e9\u05de\u05ea\u05d7\u05d9\u05dc\u05d9\u05dd \u05dc\u05e2\u05d1\u05d5\u05d3, \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05e9\u05d4\u05e8\u05d5\u05d5\u05d9\u05d6\u05d9\u05d4 \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d6\u05d4\u05d4 \u05dc\u05e8\u05d5\u05d5\u05d9\u05d6\u05d9\u05d4 \u05d1\u05d4\u05d6\u05de\u05e0\u05d4 \u05d0\u05d5 \u05d1\u05e4\u05e7\u05d5\u05d3\u05ea \u05d4\u05e2\u05d1\u05d5\u05d3\u05d4."],[105.0,"\u05d5\u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05e2\u05dd \u05db\u05de\u05d4 \u05d2\u05d9\u05dc\u05d9\u05d5\u05e0\u05d5\u05ea, \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05e9\u05db\u05dc \u05d4\u05d2\u05d9\u05dc\u05d9\u05d5\u05e0\u05d5\u05ea \u05e9\u05d1\u05d9\u05d3\u05d9\u05d9\u05dd \u05d1\u05d0\u05d5\u05ea\u05d4 \u05e8\u05d5\u05d5\u05d9\u05d6\u05d9\u05d4."],[111.0,"\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d1\u05e8\u05d5\u05d5\u05d9\u05d6\u05d9\u05d4 \u05d9\u05e9\u05e0\u05d4 \u05d4\u05d5\u05d0 \u05d0\u05d7\u05d3 \u05d4\u05de\u05e7\u05d5\u05e8\u05d5\u05ea \u05d4\u05e0\u05e4\u05d5\u05e6\u05d9\u05dd \u05d1\u05d9\u05d5\u05ea\u05e8 \u05dc\u05d7\u05dc\u05e7\u05d9\u05dd \u05e4\u05e1\u05d5\u05dc\u05d9\u05dd, \u05d0\u05e3 \u05e9\u05db\u05dc \u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05e0\u05e2\u05e9\u05d5 \u05e0\u05db\u05d5\u05df."],[121.0,"\u05e7\u05e0\u05d4 \u05d4\u05de\u05d9\u05d3\u05d4 \u05db\u05ea\u05d5\u05d1 \u05d1\u05d0\u05d6\u05d5\u05e8 \u05d4\u05db\u05d5\u05ea\u05e8\u05ea, \u05dc\u05de\u05e9\u05dc \u05d0\u05d7\u05d3 \u05dc\u05e9\u05e0\u05d9\u05d9\u05dd."],[126.0,"\u05d0\u05d1\u05dc \u05db\u05de\u05d5 \u05e9\u05e8\u05d0\u05d9\u05e0\u05d5 \u05d1\u05e4\u05e8\u05e7 \u05d0\u05e4\u05e1, \u05dc\u05d0 \u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05de\u05d4\u05e6\u05d9\u05d5\u05e8. \u05e7\u05e0\u05d4 \u05d4\u05de\u05d9\u05d3\u05d4 \u05e2\u05d5\u05d6\u05e8 \u05dc\u05d4\u05d1\u05d9\u05df \u05d0\u05ea \u05d4\u05d2\u05d5\u05d3\u05dc, \u05d5\u05dc\u05d0 \u05de\u05e9\u05de\u05e9 \u05dc\u05de\u05d3\u05d9\u05d3\u05d4."],[135.0,"\u05db\u05e9\u05de\u05d1\u05d8 \u05de\u05e1\u05d5\u05d9\u05dd \u05de\u05e6\u05d5\u05d9\u05e8 \u05d1\u05e7\u05e0\u05d4 \u05de\u05d9\u05d3\u05d4 \u05d0\u05d7\u05e8, \u05dc\u05de\u05e9\u05dc \u05e4\u05e8\u05d8 \u05de\u05d5\u05d2\u05d3\u05dc, \u05e7\u05e0\u05d4 \u05d4\u05de\u05d9\u05d3\u05d4 \u05e9\u05dc\u05d5 \u05db\u05ea\u05d5\u05d1 \u05dc\u05d9\u05d3\u05d5."],[144.0,"\u05d0\u05d6\u05d5\u05e8 \u05d4\u05db\u05d5\u05ea\u05e8\u05ea \u05de\u05d2\u05d3\u05d9\u05e8 \u05d2\u05dd \u05d0\u05ea \u05db\u05dc\u05dc\u05d9 \u05d4\u05e7\u05e8\u05d9\u05d0\u05d4 \u05e9\u05dc \u05db\u05dc \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8."],[149.0,"\u05e1\u05de\u05dc \u05d4\u05d4\u05d9\u05d8\u05dc \u05d0\u05d5\u05de\u05e8 \u05d0\u05dd \u05d4\u05de\u05d1\u05d8\u05d9\u05dd \u05d1\u05d6\u05d5\u05d5\u05d9\u05ea \u05e8\u05d0\u05e9\u05d5\u05e0\u05d4 \u05d0\u05d5 \u05e9\u05dc\u05d9\u05e9\u05d9\u05ea."],[154.0,"\u05d4\u05e4\u05e0\u05d9\u05d4 \u05dc\u05ea\u05e7\u05df \u05d4\u05e1\u05d1\u05d5\u05dc\u05d5\u05ea, \u05db\u05de\u05d5 14.5\u05e5 ASME \u05d0\u05d5 8015 50\u05d5, \u05d0\u05d5\u05de\u05e8\u05ea \u05d0\u05dd \u05d7\u05dc \u05e2\u05e7\u05e8\u05d5\u05df \u05d4\u05de\u05e2\u05d8\u05e4\u05dc\u05ea \u05d0\u05d5 \u05e2\u05e7\u05e8\u05d5\u05df \u05d4\u05e2\u05e6\u05de\u05d0\u05d5\u05ea."],[169.0,"\u05d5\u05d9\u05d7\u05d9\u05d3\u05d5\u05ea \u05d4\u05de\u05d9\u05d3\u05d4, \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8\u05d9\u05dd \u05d0\u05d5 \u05d0\u05d9\u05e0\u05e6'\u05d9\u05dd, \u05db\u05ea\u05d5\u05d1\u05d5\u05ea \u05e9\u05dd. \u05de\u05d9 \u05e9\u05de\u05e0\u05d9\u05d7 \u05d9\u05d7\u05d9\u05d3\u05d5\u05ea \u05d1\u05dc\u05d9 \u05dc\u05d1\u05d3\u05d5\u05e7,"],[177.0,"\u05e2\u05dc\u05d5\u05dc \u05dc\u05d9\u05d9\u05e6\u05e8 \u05d7\u05dc\u05e7 \u05d2\u05d3\u05d5\u05dc \u05e4\u05d9 \u05e2\u05e9\u05e8\u05d9\u05dd \u05d5\u05d7\u05de\u05d9\u05e9\u05d4, \u05d0\u05d5 \u05e7\u05d8\u05df \u05d1\u05d0\u05d5\u05ea\u05d5 \u05d9\u05d7\u05e1."],[182.0,"\u05d5\u05d2\u05dd \u05d4\u05e1\u05d1\u05d5\u05dc\u05d5\u05ea \u05d4\u05db\u05dc\u05dc\u05d9\u05d5\u05ea, \u05d7\u05e1\u05e4\u05d5\u05e1 \u05d1\u05e8\u05d9\u05e8\u05ea \u05d4\u05de\u05d7\u05d3\u05dc \u05d5\u05e9\u05d1\u05d9\u05e8\u05ea \u05d4\u05e4\u05d9\u05e0\u05d5\u05ea \u05d4\u05db\u05dc\u05dc\u05d9\u05ea \u05de\u05d5\u05e4\u05d9\u05e2\u05d9\u05dd \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05d0\u05d6\u05d5\u05e8 \u05d4\u05d6\u05d4."],[192.0,"\u05dc\u05d9\u05d3 \u05d0\u05d6\u05d5\u05e8 \u05d4\u05db\u05d5\u05ea\u05e8\u05ea \u05de\u05d5\u05e4\u05d9\u05e2\u05d5\u05ea \u05d4\u05d4\u05e2\u05e8\u05d5\u05ea \u05d4\u05db\u05dc\u05dc\u05d9\u05d5\u05ea. \u05d4\u05df \u05d7\u05dc\u05d5\u05ea \u05e2\u05dc \u05db\u05dc \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8."],[198.0,"\u05d9\u05e9 \u05d2\u05dd \u05d4\u05e2\u05e8\u05d5\u05ea \u05d3\u05d2\u05dc: \u05de\u05e1\u05e4\u05e8 \u05d1\u05ea\u05d5\u05da \u05de\u05e9\u05d5\u05dc\u05e9 \u05d0\u05d5 \u05d3\u05d2\u05dc, \u05e9\u05de\u05d5\u05e4\u05d9\u05e2 \u05dc\u05d9\u05d3 \u05d0\u05dc\u05de\u05e0\u05d8 \u05de\u05e1\u05d5\u05d9\u05dd \u05d1\u05e6\u05d9\u05d5\u05e8."],[206.0,"\u05d4\u05de\u05e1\u05e4\u05e8 \u05de\u05e4\u05e0\u05d4 \u05dc\u05d4\u05e2\u05e8\u05d4 \u05de\u05de\u05d5\u05e1\u05e4\u05e8\u05ea \u05d1\u05e8\u05e9\u05d9\u05de\u05ea \u05d4\u05d4\u05e2\u05e8\u05d5\u05ea, \u05d5\u05d4\u05d9\u05d0 \u05d7\u05dc\u05d4 \u05e8\u05e7 \u05e2\u05dc \u05d4\u05de\u05e7\u05d5\u05de\u05d5\u05ea \u05e9\u05d1\u05d4\u05dd \u05d4\u05d3\u05d2\u05dc \u05de\u05d5\u05e4\u05d9\u05e2."],[215.0,"\u05dc\u05db\u05df \u05db\u05e9\u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05d4\u05e2\u05e8\u05d4 \u05de\u05de\u05d5\u05e1\u05e4\u05e8\u05ea, \u05de\u05d7\u05e4\u05e9\u05d9\u05dd \u05d1\u05e6\u05d9\u05d5\u05e8 \u05d0\u05ea \u05db\u05dc \u05d4\u05d3\u05d2\u05dc\u05d9\u05dd \u05e2\u05dd \u05d0\u05d5\u05ea\u05d5 \u05de\u05e1\u05e4\u05e8, \u05d5\u05dc\u05d0 \u05e8\u05e7 \u05d0\u05ea \u05d4\u05e8\u05d0\u05e9\u05d5\u05df."],[224.0,"\u05de\u05d4 \u05e7\u05d5\u05e8\u05d4 \u05db\u05e9\u05d4\u05e2\u05e8\u05d5\u05ea \u05e1\u05d5\u05ea\u05e8\u05d5\u05ea \u05d6\u05d5 \u05d0\u05ea \u05d6\u05d5?"],[227.0,"\u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc, \u05d3\u05e8\u05d9\u05e9\u05d4 \u05e1\u05e4\u05e6\u05d9\u05e4\u05d9\u05ea \u05dc\u05d9\u05d3 \u05d0\u05dc\u05de\u05e0\u05d8 \u05d2\u05d5\u05d1\u05e8\u05ea \u05e2\u05dc \u05d4\u05e2\u05e8\u05d4 \u05db\u05dc\u05dc\u05d9\u05ea. \u05d6\u05d4 \u05d4\u05de\u05e9\u05de\u05e2\u05d5\u05ea \u05e9\u05dc \u05d0\u05dc\u05d0 \u05d0\u05dd \u05e6\u05d5\u05d9\u05df \u05d0\u05d7\u05e8\u05ea."],[236.0,"\u05d0\u05d1\u05dc \u05db\u05e9\u05d4\u05e1\u05ea\u05d9\u05e8\u05d4 \u05d4\u05d9\u05d0 \u05d1\u05d9\u05df \u05e9\u05ea\u05d9 \u05d3\u05e8\u05d9\u05e9\u05d5\u05ea \u05e1\u05e4\u05e6\u05d9\u05e4\u05d9\u05d5\u05ea, \u05d0\u05d5 \u05d1\u05d9\u05df \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05dc\u05de\u05e4\u05e8\u05d8, \u05d0\u05d9\u05df \u05db\u05dc\u05dc \u05d0\u05d5\u05d8\u05d5\u05de\u05d8\u05d9."],[244.0,"\u05d1\u05de\u05e7\u05e8\u05d4 \u05db\u05d6\u05d4 \u05dc\u05d0 \u05d1\u05d5\u05d7\u05e8\u05d9\u05dd \u05d0\u05ea \u05d4\u05e4\u05e8\u05e9\u05e0\u05d5\u05ea \u05d4\u05e0\u05d5\u05d7\u05d4. \u05e8\u05d5\u05e9\u05de\u05d9\u05dd \u05d0\u05ea \u05d4\u05e1\u05ea\u05d9\u05e8\u05d4, \u05d5\u05e9\u05d5\u05d0\u05dc\u05d9\u05dd."],[250.0,"\u05e9\u05e8\u05d8\u05d5\u05d8 \u05de\u05e4\u05e0\u05d4 \u05db\u05de\u05e2\u05d8 \u05ea\u05de\u05d9\u05d3 \u05dc\u05de\u05e1\u05de\u05db\u05d9\u05dd \u05d0\u05d7\u05e8\u05d9\u05dd: \u05de\u05e4\u05e8\u05d8 \u05d7\u05d5\u05de\u05e8, \u05de\u05e4\u05e8\u05d8 \u05ea\u05d4\u05dc\u05d9\u05da, \u05ea\u05e7\u05df \u05d1\u05d3\u05d9\u05e7\u05d4, \u05d0\u05d5 \u05d3\u05e8\u05d9\u05e9\u05d5\u05ea \u05dc\u05e7\u05d5\u05d7."],[260.0,"\u05d4\u05de\u05e1\u05de\u05db\u05d9\u05dd \u05d4\u05d0\u05dc\u05d4 \u05d4\u05dd \u05d7\u05dc\u05e7 \u05de\u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05dc\u05db\u05dc \u05d3\u05d1\u05e8. \u05d4\u05d3\u05e8\u05d9\u05e9\u05d5\u05ea \u05e9\u05d1\u05d4\u05dd \u05de\u05d7\u05d9\u05d9\u05d1\u05d5\u05ea \u05db\u05d0\u05d9\u05dc\u05d5 \u05e0\u05db\u05ea\u05d1\u05d5 \u05d1\u05d2\u05d9\u05dc\u05d9\u05d5\u05df."],[268.0,"\u05d5\u05d2\u05dd \u05dc\u05d4\u05dd \u05d9\u05e9 \u05d2\u05e8\u05e1\u05d4. \u05db\u05e9\u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05dc\u05d0 \u05de\u05e6\u05d9\u05d9\u05df \u05d2\u05e8\u05e1\u05d4 \u05e9\u05dc \u05de\u05e4\u05e8\u05d8,"],[274.0,"\u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d7\u05dc\u05d4 \u05d4\u05d2\u05e8\u05e1\u05d4 \u05e9\u05d1\u05ea\u05d5\u05e7\u05e3, \u05d5\u05d6\u05d4 \u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05e9\u05ea\u05e0\u05d5\u05ea."],[279.0,"\u05dc\u05db\u05df \u05de\u05d9 \u05e9\u05e2\u05d5\u05d1\u05d3 \u05dc\u05e4\u05d9 \u05de\u05e4\u05e8\u05d8 \u05e9\u05de\u05d5\u05e8 \u05d1\u05de\u05d7\u05e9\u05d1 \u05de\u05dc\u05e4\u05e0\u05d9 \u05db\u05de\u05d4 \u05e9\u05e0\u05d9\u05dd, \u05e2\u05dc\u05d5\u05dc \u05dc\u05e2\u05d1\u05d5\u05d3 \u05dc\u05e4\u05d9 \u05d3\u05e8\u05d9\u05e9\u05d5\u05ea \u05d9\u05e9\u05e0\u05d5\u05ea."],[287.0,"\u05d1\u05d0\u05d6\u05d5\u05e8 \u05d4\u05db\u05d5\u05ea\u05e8\u05ea \u05de\u05d5\u05e4\u05d9\u05e2\u05d9\u05dd \u05d2\u05dd \u05e9\u05d3\u05d5\u05ea \u05d4\u05d0\u05d9\u05e9\u05d5\u05d4\u05e8: \u05e9\u05e8\u05e1\u05d8, \u05d1\u05d5\u05d3\u05e7 \u05d5\u05de\u05d0\u05e9\u05e8."],[294.0,"\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d1\u05dc\u05d9 \u05d0\u05d9\u05e9\u05d5\u05e8 \u05d4\u05d5\u05d0 \u05d8\u05d9\u05d5\u05d8\u05d4, \u05d2\u05dd \u05d0\u05dd \u05d4\u05d5\u05d0 \u05e0\u05e8\u05d0\u05d4 \u05d2\u05de\u05d5\u05e8."],[298.0,"\u05d5\u05d1\u05d7\u05dc\u05e7 \u05de\u05d4\u05d0\u05e8\u05d2\u05d5\u05e0\u05d9\u05dd \u05de\u05d5\u05e4\u05d9\u05e2 \u05d2\u05dd \u05de\u05e2\u05de\u05d3 \u05d4\u05de\u05e1\u05de\u05da, \u05dc\u05de\u05e9\u05dc \u05dc\u05e2\u05d9\u05d5\u05df \u05d1\u05dc\u05d1\u05d3 \u05d0\u05d5 \u05de\u05e9\u05d5\u05d7\u05e8\u05e8 \u05dc\u05d9\u05d9\u05e6\u05d5\u05e8."],[307.0,"\u05d9\u05d9\u05e6\u05d5\u05e8 \u05dc\u05e4\u05d9 \u05e9\u05e8\u05d8\u05d5\u05d8 \u05e9\u05dc\u05d0 \u05e9\u05d5\u05d7\u05e8\u05e8 \u05d4\u05d5\u05d0 \u05e2\u05d1\u05d5\u05d3\u05d4 \u05e2\u05dc \u05d3\u05e8\u05d9\u05e9\u05d4 \u05e9\u05e2\u05d5\u05d3 \u05d9\u05db\u05d5\u05dc\u05d4 \u05dc\u05d4\u05e9\u05ea\u05e0\u05d5\u05ea."],[313.0,"\u05de\u05db\u05d0\u05df \u05e0\u05d5\u05d1\u05e2 \u05e1\u05d3\u05e8 \u05e7\u05e8\u05d9\u05d0\u05d4 \u05e4\u05e9\u05d5\u05d8."],[316.0,"\u05e7\u05d5\u05d3\u05dd \u05d0\u05d6\u05d5\u05e8 \u05d4\u05db\u05d5\u05ea\u05e8\u05ea: \u05de\u05e1\u05e4\u05e8, \u05e8\u05d5\u05d5\u05d9\u05d6\u05d9\u05d4, \u05d2\u05d9\u05dc\u05d9\u05d5\u05e0\u05d5\u05ea, \u05d9\u05d7\u05d9\u05d3\u05d5\u05ea, \u05ea\u05e7\u05df;\u05d5\u05e1\u05de\u05dc \u05d4\u05d9\u05d8\u05dc."],[326.0,"\u05d0\u05d7\u05e8 \u05db\u05da \u05d4\u05d4\u05e2\u05e8\u05d5\u05ea \u05d4\u05db\u05dc\u05dc\u05d9\u05d5\u05ea \u05d5\u05d4\u05e2\u05e8\u05d5\u05ea \u05d4\u05d3\u05d2\u05dc, \u05d5\u05d4\u05de\u05e1\u05de\u05db\u05d9\u05dd \u05e9\u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05de\u05e4\u05e0\u05d4 \u05d0\u05dc\u05d9\u05d4\u05dd."],[333.0,"\u05d5\u05e8\u05e7 \u05d0\u05d7\u05e8 \u05db\u05da \u05d4\u05de\u05d1\u05d8\u05d9\u05dd \u05d5\u05d4\u05de\u05d9\u05d3\u05d5\u05ea."],[336.0,"\u05de\u05d9 \u05e9\u05de\u05ea\u05d7\u05d9\u05dc \u05de\u05d4\u05de\u05d9\u05d3\u05d5\u05ea, \u05e7\u05d5\u05e8\u05d0 \u05d0\u05d5\u05ea\u05df \u05d1\u05dc\u05d9 \u05dc\u05d3\u05e2\u05ea \u05d0\u05ea \u05d4\u05db\u05dc\u05dc\u05d9\u05dd \u05e9\u05dc\u05e4\u05d9\u05d4\u05dd \u05d4\u05df \u05e0\u05db\u05ea\u05d1\u05d5."],[343.0,"\u05d0\u05d6\u05d5\u05e8 \u05d4\u05db\u05d5\u05ea\u05e8\u05ea \u05de\u05d2\u05d3\u05d9\u05e8 \u05d0\u05ea \u05d6\u05d4\u05d5\u05ea \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d5\u05d0\u05ea \u05db\u05dc\u05dc\u05d9 \u05d4\u05e7\u05e8\u05d9\u05d0\u05d4 \u05e9\u05dc\u05d5."],[348.0,"\u05d4\u05e8\u05d5\u05d5\u05d9\u05d6\u05d9\u05d4 \u05d5\u05d4\u05d2\u05d9\u05dc\u05d9\u05d5\u05e0\u05d5\u05ea \u05e7\u05d5\u05d1\u05e2\u05d9\u05dd \u05de\u05d4 \u05d1\u05d3\u05d9\u05d5\u05e7 \u05d1\u05d9\u05d3\u05d9\u05d9\u05dd."],[352.0,"\u05d4\u05e2\u05e8\u05d5\u05ea \u05d3\u05d2\u05dc \u05d7\u05dc\u05d5\u05ea \u05e8\u05e7 \u05d4\u05d9\u05db\u05df \u05e9\u05d4\u05d3\u05d2\u05dc \u05de\u05d5\u05e4\u05d9\u05e2, \u05d5\u05d3\u05e8\u05d9\u05e9\u05d4 \u05e1\u05e4\u05e6\u05d9\u05e4\u05d9\u05ea \u05d2\u05d5\u05d1\u05e8\u05ea \u05e2\u05dc \u05db\u05dc\u05dc\u05d9\u05ea."],[359.0,"\u05de\u05e1\u05de\u05db\u05d9\u05dd \u05de\u05d5\u05e4\u05e0\u05d9\u05dd \u05d4\u05dd \u05d7\u05dc\u05e7 \u05de\u05d4\u05e9\u05d5\u05e8\u05d8\u05d5\u05d8, \u05d5\u05d2\u05dd \u05dc\u05d4\u05dd \u05d9\u05e9 \u05d2\u05e8\u05e1\u05d4."],[364.0,"\u05d5\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05e7\u05e8\u05d0 \u05e9\u05e8\u05d8\u05d5\u05d8\u05d9 \u05d4\u05e8\u05db\u05d1\u05d4: \u05e8\u05e9\u05d9\u05de\u05ea \u05d7\u05dc\u05e7\u05d9\u05dd, \u05d1\u05dc\u05d5\u05e0\u05d9\u05dd, \u05d5\u05de\u05d5\u05de\u05e0\u05d8\u05d9 \u05d4\u05d9\u05d3\u05d5\u05e7. \u05e0\u05ea\u05e8\u05d0\u05d4 \u05d1\u05e4\u05e8\u05e7 \u05e9\u05d1\u05e2 \u05e2\u05e9\u05e8\u05d4."]]};
window.MH_TR["ch17"]={"t":"\u05e9\u05e8\u05d8\u05d5\u05d8\u05d9 \u05d4\u05e8\u05db\u05d1\u05d4","l":[[1.0,"\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d7\u05dc\u05e7 \u05d0\u05d5\u05de\u05e8 \u05d0\u05d9\u05da \u05e0\u05e8\u05d0\u05d4 \u05d7\u05dc\u05e7 \u05d0\u05d7\u05d3. \u05e9\u05e8\u05d8\u05d5\u05d8 \u05d4\u05e8\u05db\u05dc\u05d1\u05d4 \u05d0\u05d5\u05de\u05e8 \u05d0\u05d9\u05da \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05e0\u05e4\u05d2\u05e2\u05d5\u05d9\u05dd."],[9.0,"\u05d4\u05d5\u05d0 \u05dc\u05d0 \u05de\u05d2\u05d3\u05d9\u05e8 \u05de\u05d7\u05d3\u05e9\u05d5 \u05d0\u05ea \u05d4\u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05d4 \u05e9\u05dc \u05db\u05dc \u05d7\u05dc\u05e7. \u05d0\u05ea \u05d6\u05d4 \u05e2\u05d5\u05e9\u05d9\u05dd \u05e9\u05e8\u05d8\u05d5\u05d8\u05d9 \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd."],[16.0,"\u05d0\u05d1\u05dc \u05d4\u05d5\u05d0 \u05de\u05d2\u05d3\u05d9\u05e8 \u05de\u05d4 \u05de\u05e8\u05db\u05d9\u05d1\u05d9\u05dd, \u05db\u05de\u05d4 \u05de\u05db\u05dc \u05d3\u05d1\u05e8, \u05d1\u05d0\u05d9\u05d6\u05d4 \u05e1\u05d3\u05e8, \u05d1\u05d0\u05d9\u05d6\u05d4 \u05db\u05d5\u05d7, \u05d5\u05de\u05d4 \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05ea\u05e7\u05d1\u05dc \u05d1\u05e1\u05d5\u05e3."],[25.0,"\u05d5\u05dc\u05db\u05df \u05e7\u05e8\u05d9\u05d0\u05d4 \u05dc\u05d0 \u05e0\u05db\u05d5\u05e0\u05d4 \u05e9\u05dc \u05e9\u05e8\u05d8\u05d5\u05d8 \u05d4\u05e8\u05db\u05d1\u05d4 \u05d9\u05db\u05d5\u05dc\u05d4 \u05dc\u05e4\u05e1\u05d5\u05dc \u05de\u05db\u05dc\u05d5\u05dc \u05e9\u05dc\u05dd, \u05d2\u05dd \u05db\u05e9\u05db\u05dc \u05d7\u05dc\u05e7 \u05d1\u05e0\u05e4\u05e8\u05d3 \u05ea\u05e7\u05d9\u05df."],[34.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05e7\u05e8\u05d0 \u05d0\u05ea \u05e8\u05e9\u05d9\u05de\u05ea \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd, \u05d0\u05ea \u05d4\u05d1\u05dc\u05d5\u05e0\u05d9\u05dd, \u05d0\u05ea \u05d4\u05e2\u05e8\u05d5\u05ea \u05d4\u05d4\u05e8\u05db\u05d1\u05d4, \u05d5\u05d0\u05ea \u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05e9\u05de\u05d5\u05e4\u05d9\u05e2\u05d5\u05ea \u05e8\u05e7 \u05d1\u05d4\u05e8\u05db\u05d1\u05d4."],[44.0,"\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d4\u05e8\u05db\u05d1\u05d4 \u05db\u05d5\u05dc\u05dc \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05de\u05d1\u05d8 \u05d0\u05d5 \u05d7\u05ea\u05da \u05e9\u05de\u05e8\u05d0\u05d4 \u05d0\u05ea \u05db\u05dc \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05d1\u05de\u05e7\u05d5\u05de\u05dd."],[51.0,"\u05d1\u05d7\u05ea\u05da \u05d4\u05e8\u05db\u05d1\u05d4, \u05db\u05de\u05d5 \u05e9\u05e8\u05d0\u05d9\u05e0\u05d5 \u05d1\u05e4\u05e8\u05e7 \u05e9\u05ea\u05d9\u05d9\u05dd, \u05e6\u05d9\u05e8\u05d9\u05dd, \u05d1\u05e8\u05d2\u05d9\u05dd \u05d5\u05e4\u05d9\u05e0\u05d9\u05dd \u05dc\u05d0 \u05de\u05e7\u05d5\u05d5\u05e7\u05d5\u05d5\u05d9\u05dd,"],[58.0,"\u05d5\u05d7\u05dc\u05e7\u05d9\u05dd \u05e1\u05de\u05d5\u05db\u05d9\u05dd \u05de\u05e7\u05d1\u05dc\u05d9\u05dd \u05e7\u05d9\u05d5\u05d5\u05e7\u05d5\u05d5 \u05d1\u05d6\u05d5\u05d5\u05d9\u05d5\u05ea \u05e9\u05d5\u05e0\u05d5\u05ea."],[62.0,"\u05db\u05da \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d4\u05d1\u05d7\u05d9\u05df \u05d1\u05d2\u05d1\u05d5\u05dc \u05d1\u05d9\u05df \u05e9\u05e0\u05d9 \u05d7\u05dc\u05e7\u05d9\u05dd, \u05d2\u05dd \u05db\u05e9\u05d4\u05dd \u05e2\u05e9\u05d5\u05d9\u05d9\u05dd \u05de\u05d0\u05d5\u05ea\u05d5 \u05d7\u05d5\u05de\u05e8."],[68.0,"\u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d4\u05e8\u05db\u05d1\u05d4 \u05d4\u05df \u05de\u05e2\u05d8\u05d5\u05ea, \u05d5\u05d4\u05df \u05e9\u05d9\u05d9\u05db\u05d5\u05ea \u05dc\u05d4\u05e8\u05db\u05d1\u05d4 \u05d1\u05dc\u05d1\u05d3:"],[74.0,"\u05de\u05d9\u05d3\u05d5\u05ea \u05db\u05d5\u05dc\u05dc\u05d5\u05ea, \u05de\u05d9\u05e7\u05d5\u05de\u05d9\u05dd, \u05d0\u05d5 \u05de\u05d9\u05d3\u05d5\u05ea \u05e9\u05e6\u05e8\u05d9\u05da \u05dc\u05e7\u05d1\u05dc \u05d0\u05d7\u05e8\u05d9 \u05d4\u05d4\u05e8\u05db\u05d1\u05d4."],[80.0,"\u05e8\u05e9\u05d9\u05de\u05ea \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05d4\u05d9\u05d0 \u05d4\u05d8\u05d1\u05dc\u05d4 \u05e9\u05de\u05d2\u05d3\u05d9\u05e8\u05d4 \u05de\u05d4 \u05e0\u05db\u05e0\u05e1 \u05dc\u05de\u05db\u05dc\u05d5\u05dc."],[86.0,"\u05d4\u05d9\u05d0 \u05de\u05d5\u05d2\u05d3\u05e8\u05ea \u05d1\u05ea\u05e7\u05e0\u05d9\u05dd \u05db\u05de\u05d5 7573 ISO \u2026 ASME"],[94.0,"\u05d5\u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d9\u05e9 \u05d1\u05d4 \u05de\u05e1\u05e4\u05e8 \u05e4\u05e8\u05d9\u05d8, \u05de\u05e7\"\u05d8, \u05ea\u05d9\u05d0\u05d5\u05e8, \u05db\u05de\u05d5\u05ea, \u05d5\u05d7\u05d5\u05de\u05e8 \u05d0\u05d5 \u05ea\u05e7\u05df."],[104.0,"\u05de\u05e1\u05e4\u05e8 \u05d4\u05e4\u05e8\u05d9\u05d8 \u05d4\u05d5\u05d0 \u05d4\u05de\u05e1\u05e4\u05e8 \u05e9\u05de\u05d5\u05e4\u05d9\u05e2 \u05d1\u05d1\u05dc\u05d5\u05df, \u05d5\u05d4\u05de\u05e7\"\u05d8 \u05d4\u05d5\u05d0 \u05d4\u05de\u05e1\u05e4\u05e8 \u05e9\u05dc \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d0\u05d5 \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7 \u05d4\u05e7\u05e0\u05d5\u05d9."],[112.0,"\u05d7\u05dc\u05e7\u05d9\u05dd \u05e1\u05d8\u05e0\u05d3\u05e8\u05d8\u05d9\u05d9\u05dd \u05de\u05ea\u05d5\u05d0\u05e8\u05d9\u05dd \u05dc\u05e4\u05d9 \u05d4\u05ea\u05e7\u05df \u05e9\u05dc\u05d4\u05dd, \u05dc\u05de\u05e9\u05dc \u05d1\u05d5\u05e8\u05d2 \u2026 ,4762 50\u05d5, \u05d1\u05d3\u05e8\u05d2\u05ea \u05d7\u05d5\u05d6\u05e7 12.9."],[127.0,"\u05d5\u05d1\u05d7\u05d5\u05de\u05e8\u05d9 \u05e2\u05d6\u05e8, \u05db\u05de\u05d5 \u05d3\u05d1\u05e7, \u05d7\u05d5\u05de\u05e8 \u05d0\u05d9\u05d8\u05d5\u05dd \u05d0\u05d5 \u05e4\u05d7\u05d9\u05d5\u05ea \u05de\u05d9\u05dc\u05d5\u05d9, \u05d4\u05db\u05de\u05d5\u05ea \u05db\u05ea\u05d5\u05d1\u05d4 \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05db-8), \u05dc\u05e1\u05d9 \u05d4\u05e6\u05d5\u05e8\u05da."],[137.0,"\u05de\u05d9 \u05e9\u05de\u05d7\u05dc\u05d9\u05e3 \u05d1\u05d5\u05e8\u05d2 \u05e1\u05d8\u05e0\u05d3\u05e8\u05d8\u05d9 \u05d1\u05d1\u05d5\u05e8\u05d2 \u05e9\u05e0\u05e8\u05d0\u05d4 \u05d6\u05d4\u05d4 \u05d0\u05d1\u05dc \u05d1\u05d3\u05e8\u05d2\u05ea \u05d7\u05d5\u05d6\u05e7 \u05d0\u05d7\u05e8\u05ea, \u05de\u05e9\u05e0\u05d4 \u05d0\u05ea \u05d4\u05de\u05db\u05dc\u05d5\u05dc."],[146.0,"\u05d1\u05dc\u05d5\u05df \u05d4\u05d5\u05d0 \u05e2\u05d9\u05d2\u05d5\u05dc \u05e2\u05dd \u05de\u05e1\u05e4\u05e8 \u05e4\u05e8\u05d9\u05d8, \u05d5\u05e7\u05d5 \u05de\u05d5\u05d1\u05d9\u05dc \u05e9\u05de\u05e6\u05d1\u05d9\u05e2 \u05e2\u05dc \u05d4\u05d7\u05dc\u05e7 \u05d1\u05e6\u05d9\u05d5\u05e8."],[153.0,"\u05db\u05e9\u05d4\u05e7\u05d5 \u05de\u05e1\u05ea\u05d9\u05d9\u05dd \u05d1\u05e0\u05e7\u05d5\u05d3\u05d4, \u05d4\u05d5\u05d0 \u05de\u05e6\u05d1\u05d9\u05e2 \u05e2\u05dc \u05e4\u05e0\u05d9 \u05d4\u05d7\u05dc\u05e7. \u05db\u05e9\u05d4\u05d5\u05d0 \u05de\u05e1\u05ea\u05d9\u05d9\u05dd \u05d1\u05d7\u05e5, \u05d4\u05d5\u05d0 \u05de\u05e6\u05d1\u05d9\u05e2 \u05e2\u05dc \u05e7\u05d5 \u05d4\u05de\u05ea\u05d0\u05e8 \u05e9\u05dc\u05d5."],[162.0,"\u05db\u05dc \u05e4\u05e8\u05d9\u05d8 \u05d1\u05e8\u05e9\u05d9\u05de\u05d4 \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d5\u05e4\u05d9\u05e2 \u05d1\u05d1\u05dc\u05d5\u05df \u05dc\u05e4\u05d7\u05d5\u05ea \u05e4\u05e2\u05dd \u05d0\u05d7\u05ea."],[167.0,"\u05d7\u05dc\u05e7\u05d9\u05dd \u05d6\u05d4\u05d9\u05dd \u05e9\u05d7\u05d5\u05d6\u05e8\u05d9\u05dd \u05db\u05de\u05d4 \u05e4\u05e2\u05de\u05d9\u05dd \u05de\u05e7\u05d1\u05dc\u05d9\u05dd \u05d1\u05dc\u05d5\u05df \u05d0\u05d7\u05d3, \u05d5\u05d4\u05db\u05de\u05d5\u05ea \u05db\u05ea\u05d5\u05d1\u05d4 \u05d1\u05e8\u05e9\u05d9\u05de\u05d4."],[174.0,"\u05d5\u05dc\u05de\u05e2\u05e8\u05db\u05d5\u05ea \u05d7\u05d9\u05d1\u05d5\u05e8, \u05db\u05de\u05d5 \u05d1\u05d5\u05e8\u05d2, \u05d3\u05d9\u05e1\u05e7\u05d9\u05ea \u05d5\u05d0\u05d5\u05dd, \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05dc\u05e2\u05d9\u05ea\u05d9\u05dd \u05d1\u05e2\u05e8\u05d9\u05de\u05d4 \u05e9\u05dc \u05d1\u05dc\u05d5\u05e0\u05d9\u05dd \u05e2\u05dc \u05e7\u05d5 \u05de\u05d5\u05d1\u05d9\u05dc \u05d0\u05d7\u05d3."],[183.0,"\u05db\u05e9\u05d9\u05e9 \u05d1\u05dc\u05d5\u05df \u05d1\u05dc\u05d9 \u05e9\u05d5\u05e8\u05d4 \u05d1\u05e8\u05e9\u05d9\u05de\u05d4, \u05d0\u05d5 \u05e9\u05d5\u05e8\u05d4 \u05d1\u05dc\u05d9 \u05d1\u05dc\u05d5\u05df, \u05d6\u05d5 \u05d8\u05e2\u05d5\u05ea \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8, \u05d5\u05e6\u05e8\u05d9\u05da \u05dc\u05e9\u05d0\u05d5\u05dc."],[192.0,"\u05e8\u05d5\u05d1 \u05d4\u05de\u05d9\u05d3\u05e2 \u05e9\u05dc \u05d4\u05d4\u05e8\u05db\u05d1\u05d4 \u05e0\u05de\u05e6\u05d0 \u05d1\u05d4\u05e2\u05e8\u05d5\u05ea."],[195.0,"\u05de\u05d5\u05de\u05e0\u05d8 \u05d4\u05d9\u05d3\u05d5\u05e7, \u05dc\u05de\u05e9\u05dc \u05e2\u05e9\u05e8\u05d9\u05dd \u05d5\u05d7\u05de\u05d9\u05e9\u05d4 \u05e0\u05d9\u05d5\u05d8\u05d5\u05df \u05de\u05d8\u05e8, \u05de\u05d5\u05e4\u05d9\u05e2 \u05dc\u05d9\u05d3 \u05d4\u05d1\u05d5\u05e8\u05d2 \u05d0\u05d5 \u05d1\u05d4\u05e2\u05e8\u05d4 \u05db\u05dc\u05dc\u05d9\u05ea."],[203.0,"\u05d5\u05d4\u05d5\u05d0 \u05ea\u05de\u05d9\u05d3 \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d2\u05d9\u05e2 \u05e2\u05dd \u05ea\u05e0\u05d0\u05d9: \u05d4\u05d0\u05dd \u05d4\u05d4\u05d1\u05e8\u05d2\u05d4 \u05d9\u05d1\u05e9\u05d4 \u05d0\u05d5 \u05de\u05e9\u05d5\u05de\u05e0\u05ea."],[209.0,"\u05d0\u05d5\u05ea\u05d5 \u05de\u05d5\u05de\u05e0\u05d8 \u05e2\u05dc \u05d4\u05d1\u05e8\u05d2\u05d4 \u05de\u05e9\u05d5\u05d5\u05de\u05e0\u05ea \u05de\u05d9\u05d9\u05e6\u05e8 \u05db\u05d5\u05d7 \u05d4\u05d9\u05d3\u05d5\u05e7 \u05d2\u05d3\u05d5\u05dc \u05d1\u05d4\u05e8\u05d1\u05d4."],[216.0,"\u05d1\u05d7\u05d9\u05d1\u05d5\u05e8 \u05e9\u05dc \u05db\u05de\u05d4 \u05d1\u05e8\u05d2\u05d9\u05dd, \u05de\u05d5\u05e4\u05d9\u05e2 \u05dc\u05e2\u05d9\u05ea\u05d9\u05dd \u05d2\u05dd \u05e1\u05d3\u05e8 \u05d4\u05d9\u05d3\u05d5\u05e7, \u05dc\u05de\u05e9\u05dc \u05d1\u05e6\u05d5\u05e8\u05ea \u05e6\u05dc\u05d1, \u05d5\u05d1\u05db\u05de\u05d4 \u05e9\u05dc\u05d1\u05d9\u05dd."],[224.0,"\u05d4\u05e2\u05e8\u05d5\u05ea \u05e0\u05d5\u05e1\u05e4\u05d5\u05ea \u05de\u05d2\u05d3\u05d9\u05e8\u05d5\u05ea \u05d7\u05d5\u05de\u05e8 \u05e0\u05e2\u05d9\u05dc\u05d4 \u05dc\u05d4\u05d1\u05e8\u05d2\u05d4, \u05e9\u05d9\u05de\u05d5\u05df, \u05d0\u05d5 \u05d7\u05d5\u05de\u05e8 \u05d0\u05d9\u05d8\u05d5\u05dd, \u05dc\u05e4\u05d9 \u05de\u05e4\u05e8\u05d8."],[232.0,"\u05de\u05d9 \u05e9\u05de\u05d4\u05d3\u05e7 \u05d1\u05dc\u05d9 \u05dc\u05e7\u05e8\u05d5\u05d0 \u05d0\u05ea \u05d4\u05ea\u05e0\u05d0\u05d9, \u05e2\u05dc\u05d5\u05dc \u05dc\u05d4\u05d3\u05e7 \u05e4\u05d7\u05d5\u05ea \u05de\u05d4\u05e0\u05d3\u05e8\u05e9, \u05d0\u05d5 \u05dc\u05de\u05ea\u05d5\u05d7 \u05d0\u05ea \u05d4\u05d1\u05d5\u05e8\u05d2 \u05e2\u05d3 \u05db\u05e9\u05dc."],[241.0,"\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d4\u05d4\u05e8\u05db\u05d1\u05d4 \u05de\u05e8\u05d0\u05d4 \u05dc\u05e2\u05d9\u05ea\u05d9\u05dd \u05e7\u05e8\u05d5\u05d1\u05d5\u05ea \u05d0\u05ea \u05d4\u05d4\u05ea\u05d0\u05de\u05d5\u05ea \u05d1\u05d9\u05df \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd, \u05dc\u05de\u05e9\u05dc 7/06\u05d4 \u05dc\u05d9\u05d3 \u05e6\u05d9\u05e8 \u05d1\u05ea\u05d5\u05da \u05ea\u05d5\u05ea\u05d1."],[251.0,"\u05d1\u05d4\u05ea\u05d0\u05de\u05ea \u05dc\u05d7\u05e5, \u05d4\u05d4\u05e2\u05e8\u05d4 \u05de\u05d2\u05d3\u05d9\u05e8\u05d4 \u05d2\u05dd \u05d0\u05ea \u05e9\u05d9\u05d8\u05ea \u05d4\u05d4\u05e8\u05db\u05d1\u05d4: \u05dc\u05d7\u05d9\u05e6\u05d4, \u05d7\u05d9\u05de\u05d5\u05dd \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7 \u05d4\u05d7\u05d9\u05e6\u05d5\u05e0\u05d9, \u05d0\u05d5 \u05e7\u05d9\u05e8\u05d5\u05e8 \u05e9\u05dc \u05d4\u05e6\u05d9\u05e8."],[261.0,"\u05d5\u05db\u05e9\u05d4\u05d4\u05e8\u05db\u05d1\u05d4 \u05db\u05d5\u05dc\u05dc\u05ea \u05db\u05d5\u05d5\u05e0\u05d5\u05df, \u05db\u05de\u05d5 \u05e4\u05d7\u05d9\u05d5\u05ea \u05de\u05d9\u05dc\u05d5\u05d9 \u05e9\u05e1\u05d5\u05d2\u05e8\u05d5\u05ea \u05de\u05e8\u05d5\u05d5\u05d7,"],[267.0,"\u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05de\u05d2\u05d3\u05d9\u05e8 \u05d0\u05ea \u05d4\u05de\u05d9\u05d3\u05d4 \u05d4\u05e1\u05d5\u05e4\u05d9\u05ea \u05e9\u05e6\u05e8\u05d9\u05da \u05dc\u05e7\u05d1\u05dc, \u05d5\u05dc\u05d0 \u05d0\u05ea \u05e2\u05d5\u05d1\u05d9 \u05d4\u05e4\u05d7\u05d9\u05ea."],[273.0,"\u05d6\u05d4 \u05d1\u05d3\u05d9\u05d5\u05e7 \u05d4\u05e4\u05ea\u05e8\u05d5\u05df \u05de\u05e9\u05e8\u05e9\u05d5\u05e8\u05ea \u05d4\u05e1\u05d1\u05d5\u05dc\u05d5\u05ea \u05d1\u05e4\u05e8\u05e7 \u05e9\u05de\u05d5\u05e0\u05d4: \u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05d1\u05d4\u05e8\u05db\u05d1\u05d4, \u05d5\u05d1\u05d5\u05d7\u05e8\u05d9\u05dd \u05d0\u05ea \u05d4\u05e4\u05d7\u05d9\u05ea \u05d4\u05de\u05ea\u05d0\u05d9\u05de\u05d4."],[282.0,"\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d7\u05dc\u05e7 \u05dc\u05d0 \u05de\u05e2\u05d5\u05d1\u05d3 \u05e2\u05d3 \u05d4\u05e1\u05d5\u05e3 \u05dc\u05e4\u05e0\u05d9 \u05d4\u05d4\u05e8\u05db\u05d1\u05d4."],[286.0,"\u05e7\u05d3\u05d7 \u05dc\u05e4\u05d9\u05df \u05de\u05e8\u05db\u05d5\u05d6, \u05dc\u05de\u05e9\u05dc, \u05e0\u05e7\u05d3\u05d7 \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d3\u05e8\u05da \u05e9\u05e0\u05d9 \u05d7\u05dc\u05e7\u05d9\u05dd \u05d9\u05d7\u05d3, \u05d0\u05d7\u05e8\u05d9 \u05e9\u05d4\u05dd \u05d4\u05d5\u05e8\u05db\u05d1\u05d5, \u05db\u05d3\u05d9 \u05e9\u05d9\u05d4\u05d9\u05d5 \u05d1\u05d3\u05d9\u05d5\u05e7 \u05d1\u05d0\u05d5\u05ea\u05d5 \u05de\u05e7\u05d5\u05dd."],[296.0,"\u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d4\u05d7\u05dc\u05e7 \u05d6\u05d4 \u05de\u05d5\u05e4\u05d9\u05e2 \u05db\u05d4\u05e2\u05e8\u05d4 \u05dc\u05db\u05de\u05d5 \u05dc\u05e7\u05d3\u05d5\u05d7 \u05d1\u05d4\u05e8\u05db\u05d1\u05d4, \u05d5\u05d1\u05e0\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d4\u05d4\u05e8\u05db\u05d1\u05d4 \u05de\u05d5\u05e4\u05d9\u05e2\u05d5\u05ea \u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05e9\u05dc \u05d4\u05e7\u05d3\u05d7."],[305.0,"\u05de\u05d9 \u05e9\u05e7\u05d5\u05d3\u05d7 \u05d0\u05ea \u05d4\u05d7\u05d5\u05e8 \u05de\u05e8\u05d0\u05e9\u05d5 \u05d1\u05d7\u05dc\u05e7 \u05d4\u05d1\u05d5\u05d3\u05d3, \u05dc\u05e4\u05d9 \u05de\u05d9\u05d3\u05d4, \u05de\u05d0\u05d1\u05d3 \u05d0\u05ea \u05d4\u05d4\u05ea\u05d0\u05de\u05d4 \u05e9\u05d4\u05e7\u05d9\u05d3\u05d5\u05d7 \u05d4\u05de\u05e9\u05d5\u05ea\u05e3 \u05e0\u05d5\u05e2\u05d3 \u05dc\u05ea\u05ea."],[314.0,"\u05d5\u05d9\u05e9 \u05d2\u05dd \u05de\u05d9\u05d3\u05d5\u05ea \u05e9\u05de\u05d5\u05e4\u05d9\u05e2\u05d5\u05ea \u05d1\u05d4\u05e8\u05db\u05d1\u05d4 \u05db\u05de\u05d9\u05d3\u05d5\u05ea \u05d9\u05d9\u05d7\u05d5\u05e1, \u05d1\u05e1\u05d5\u05d2\u05e8\u05d9\u05d9\u05dd, \u05e8\u05e7 \u05db\u05d3\u05d9 \u05dc\u05ea\u05ea \u05ea\u05de\u05d5\u05e0\u05d4, \u05d1\u05dc\u05d9 \u05dc\u05d7\u05d9\u05d9\u05d1 \u05d1\u05d3\u05d9\u05e7\u05d4."],[323.0,"\u05de\u05d5\u05e6\u05e8 \u05d2\u05d3\u05d5\u05dc \u05d1\u05e0\u05d5\u05d9 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05db\u05e2\u05e5: \u05de\u05db\u05dc\u05d5\u05dc \u05e2\u05dc\u05d9\u05d5\u05df, \u05ea\u05ea\u05d9 \u05de\u05db\u05dc\u05d5\u05dc\u05d9\u05dd, \u05d5\u05d7\u05dc\u05e7\u05d9\u05dd."],[330.0,"\u05dc\u05db\u05dc \u05e8\u05de\u05d4 \u05d9\u05e9 \u05e9\u05e8\u05d8\u05d5\u05d8 \u05d5\u05e8\u05e9\u05d9\u05de\u05ea \u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05e9\u05dc\u05d4, \u05d5\u05ea\u05ea \u05de\u05db\u05dc\u05d5\u05dc \u05de\u05d5\u05e4\u05d9\u05e2 \u05d1\u05de\u05db\u05dc\u05d5\u05dc \u05d4\u05e2\u05dc\u05d9\u05d5\u05df \u05db\u05e4\u05e8\u05d9\u05d8 \u05d0\u05d7\u05d3."],[339.0,"\u05dc\u05db\u05df \u05db\u05e9\u05de\u05d7\u05e4\u05e9\u05d9\u05dd \u05d7\u05dc\u05e7 \u05de\u05e1\u05d5\u05d9\u05dd, \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05e6\u05e8\u05d9\u05da \u05dc\u05e8\u05d3\u05ea \u05db\u05de\u05d4 \u05e8\u05de\u05d5\u05ea."],[345.0,"\u05de\u05d1\u05d8 \u05de\u05e4\u05d5\u05e8\u05e7, \u05e9\u05d1\u05d5 \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05e6\u05d5\u05d9\u05e8\u05d9\u05dd \u05de\u05d5\u05e4\u05e8\u05d3\u05d9\u05dd \u05dc\u05d0\u05d5\u05e8\u05da \u05e7\u05d5 \u05d4\u05d4\u05e8\u05db\u05d1\u05d4,"],[350.0,"\u05e2\u05d5\u05d6\u05e8 \u05dc\u05d4\u05d1\u05d9\u05df \u05d0\u05ea \u05d4\u05e1\u05d3\u05e8, \u05d0\u05d1\u05dc \u05d4\u05d5\u05d0 \u05dc\u05d0 \u05de\u05d7\u05dc\u05d9\u05e3 \u05d0\u05ea \u05e8\u05e9\u05d9\u05de\u05ea \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd."],[355.0,"\u05d5\u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05e9\u05de\u05d2\u05d9\u05e2\u05d9\u05dd \u05d1\u05d6\u05d5\u05d2, \u05d9\u05de\u05e0\u05d9 \u05d5\u05e9\u05de\u05d0\u05dc\u05d9, \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05de\u05e8\u05d0\u05d4 \u05dc\u05e2\u05d9\u05ea\u05d9\u05dd \u05e8\u05e7 \u05d0\u05d7\u05d3 \u05de\u05d4\u05dd, \u05d5\u05db\u05d5\u05ea\u05d1 \u05e9\u05d4\u05e9\u05e0\u05d9 \u05d4\u05d5\u05d0 \u05ea\u05de\u05d5\u05e0\u05ea \u05de\u05e8\u05d0\u05d4."],[366.0,"\u05e8\u05d9\u05db\u05d5\u05d6 \u05d4\u05de\u05dc\u05db\u05d5\u05d3\u05d5\u05ea \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d4\u05e8\u05db\u05d1\u05d4."],[369.0,"\u05d1\u05dc\u05d5\u05df \u05d1\u05dc\u05d9 \u05e9\u05d5\u05e8\u05d4 \u05d1\u05e8\u05e9\u05d9\u05de\u05d4, \u05d0\u05d5 \u05db\u05de\u05d5\u05ea \u05e9\u05dc\u05d0 \u05ea\u05d5\u05d0\u05de\u05ea."],[373.0,"\u05d1\u05d5\u05e8\u05d2 \u05e1\u05d8\u05e0\u05d3\u05e8\u05d8\u05d9 \u05e9\u05d4\u05d5\u05d7\u05dc\u05e3 \u05d1\u05d3\u05e8\u05d2\u05ea \u05d7\u05d5\u05d6\u05e7 \u05d0\u05d7\u05e8\u05ea."],[377.0,"\u05de\u05d5\u05de\u05e0\u05d8 \u05d1\u05dc\u05d9 \u05ea\u05e0\u05d0\u05d9 \u05e9\u05dc \u05d4\u05d1\u05e8\u05d2\u05d4 \u05d9\u05d1\u05e9\u05d4 \u05d0\u05d5 \u05de\u05e9\u05d5\u05de\u05e0\u05ea."],[382.0,"\u05d7\u05dc\u05e7 \u05e9\u05de\u05e1\u05d5\u05de\u05df \u05dc\u05e7\u05d9\u05d3\u05d5\u05d7 \u05d1\u05d4\u05e8\u05db\u05d1\u05d4, \u05e9\u05e0\u05e7\u05d3\u05d7 \u05de\u05e8\u05d0\u05e9."],[387.0,"\u05d5\u05e4\u05d7\u05d9\u05ea \u05de\u05d9\u05dc\u05d5\u05d9 \u05e9\u05e2\u05d5\u05d1\u05d9\u05d4 \u05e0\u05e7\u05d1\u05e2 \u05de\u05e8\u05d0\u05e9, \u05d1\u05de\u05e7\u05d5\u05dd \u05dc\u05e4\u05d9 \u05de\u05d3\u05d9\u05d3\u05d4."],[392.0,"\u05db\u05d3\u05d9 \u05dc\u05e7\u05e8\u05d5\u05d0 \u05e9\u05e8\u05d8\u05d5\u05d8 \u05d4\u05e8\u05db\u05d1\u05d4, \u05de\u05ea\u05d7\u05d9\u05dc\u05d9\u05dd \u05de\u05d0\u05d6\u05d5\u05e8 \u05d4\u05db\u05d5\u05ea\u05e8\u05ea \u05d5\u05de\u05e8\u05e9\u05d9\u05de\u05ea \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd."],[398.0,"\u05d0\u05d7\u05e8 \u05db\u05da \u05e2\u05d5\u05d1\u05e8\u05d9\u05dd \u05e2\u05dc \u05db\u05dc \u05d1\u05dc\u05d5\u05df, \u05d5\u05de\u05d5\u05d5\u05d3\u05d0\u05d9\u05dd \u05e9\u05d4\u05d5\u05d0 \u05de\u05d5\u05e4\u05d9\u05e2 \u05d1\u05e8\u05e9\u05d9\u05de\u05d4 \u05d5\u05e9\u05d4\u05db\u05de\u05d5\u05ea \u05e0\u05db\u05d5\u05e0\u05d4."],[405.0,"\u05d0\u05d7\u05e8 \u05db\u05da \u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05d0\u05ea \u05d4\u05e2\u05e8\u05d5\u05ea \u05d4\u05d4\u05e8\u05db\u05d1\u05d4: \u05de\u05d5\u05de\u05e0\u05d8\u05d9\u05dd, \u05ea\u05e0\u05d0\u05d9\u05dd, \u05e1\u05d3\u05e8 \u05d7\u05d5\u05de\u05e8\u05d9 \u05e2\u05d6\u05e8."],[413.0,"\u05d5\u05dc\u05d1\u05e1\u05d5\u05e3 \u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05d5\u05d4\u05d4\u05ea\u05d0\u05de\u05d5\u05ea \u05e9\u05e6\u05e8\u05d9\u05da \u05dc\u05e7\u05d1\u05dc \u05d0\u05d7\u05e8\u05d9 \u05d4\u05d4\u05e8\u05db\u05d1\u05d4, \u05d5\u05d4\u05d0\u05dd \u05d9\u05e9 \u05e7\u05d9\u05d3\u05d5\u05d7 \u05d0\u05d5 \u05e2\u05d9\u05d1\u05d5\u05d3 \u05de\u05e9\u05d5\u05ea\u05e3."],[421.0,"\u05de\u05d9 \u05e9\u05de\u05ea\u05d7\u05d9\u05dc \u05dc\u05d4\u05e8\u05db\u05d9\u05d1 \u05dc\u05e4\u05e0\u05d9 \u05e9\u05e7\u05e8\u05d0 \u05d0\u05ea \u05d4\u05d4\u05e2\u05e8\u05d5\u05ea, \u05e2\u05dc\u05d5\u05dc \u05dc\u05d2\u05dc\u05d5\u05ea \u05d1\u05e1\u05d5\u05e3 \u05e9\u05e1\u05d3\u05e8 \u05d4\u05d4\u05e8\u05db\u05d1\u05d4 \u05d4\u05d9\u05d4 \u05d7\u05dc\u05e7 \u05de\u05d4\u05d3\u05e8\u05d9\u05e9\u05d4."],[430.0,"\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d4\u05e8\u05db\u05d1\u05d4 \u05de\u05d2\u05d3\u05d9\u05e8 \u05de\u05d4, \u05db\u05de\u05d4, \u05d1\u05d0\u05d9\u05d6\u05d4 \u05e1\u05d3\u05e8 \u05d5\u05d1\u05d0\u05d9\u05d6\u05d4 \u05db\u05d5\u05d7, \u05d5\u05dc\u05d0 \u05d0\u05ea \u05d4\u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05d4 \u05e9\u05dc \u05db\u05dc \u05d7\u05dc\u05e7."],[438.0,"\u05e8\u05e9\u05d9\u05de\u05ea \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05d5\u05d4\u05d1\u05dc\u05d5\u05e0\u05d9\u05dd \u05d7\u05d9\u05d9\u05d1\u05d9\u05dd \u05dc\u05d4\u05ea\u05d0\u05d9\u05dd \u05d6\u05d4 \u05dc\u05d6\u05d4, \u05e4\u05e8\u05d9\u05d8 \u05d0\u05d7\u05e8\u05d9 \u05e4\u05e8\u05d9\u05d8."],[445.0,"\u05de\u05d5\u05de\u05e0\u05d8 \u05d4\u05d9\u05d3\u05d5\u05e7 \u05ea\u05de\u05d9\u05d3 \u05de\u05d2\u05d9\u05e2 \u05e2\u05dd \u05ea\u05e0\u05d0\u05d9, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05e2\u05dd \u05e1\u05d3\u05e8."],[450.0,"\u05db\u05d5\u05d5\u05e0\u05d5\u05df \u05d5\u05e4\u05d7\u05d9\u05d5\u05ea \u05de\u05d9\u05dc\u05d5\u05d9 \u05de\u05d5\u05d2\u05d3\u05e8\u05d9\u05dd \u05dc\u05e4\u05d9 \u05d4\u05de\u05d9\u05d3\u05d4 \u05d4\u05e1\u05d5\u05e4\u05d9\u05ea, \u05d5\u05dc\u05d0 \u05dc\u05e4\u05d9 \u05e2\u05d5\u05d1\u05d9."],[456.0,"\u05d5\u05e7\u05d9\u05d3\u05d5\u05d7 \u05d1\u05d4\u05e8\u05db\u05d1\u05d4 \u05e0\u05e2\u05e9\u05d4 \u05e8\u05e7 \u05d0\u05d7\u05e8\u05d9 \u05e9\u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05d4\u05d5\u05e8\u05db\u05d1\u05d5."],[460.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05db\u05d9\u05e8 \u05e9\u05e8\u05d8\u05d5\u05d8\u05d9\u05dd \u05dc\u05ea\u05d4\u05dc\u05d9\u05db\u05d9\u05dd \u05d0\u05d7\u05e8\u05d9\u05dd: \u05d9\u05e6\u05d9\u05e7\u05d4, \u05d7\u05d9\u05e9\u05d5\u05dc, \u05e4\u05d7 \u05d5\u05e4\u05dc\u05e1\u05d8\u05d9\u05e7. \u05e0\u05ea\u05e8\u05d0\u05d4 \u05d1\u05e4\u05e8\u05e7 \u05e9\u05de\u05d5\u05e0\u05d4 \u05e2\u05e9\u05e8\u05d4."]]};
window.MH_TR["ch18"]={"t":"\u05d9\u05e6\u05d9\u05e7\u05d4, \u05d7\u05d9\u05e9\u05d5\u05dc, \u05e4\u05d7 \u05d5\u05e4\u05dc\u05e1\u05d8\u05d9\u05e7","l":[[1.0,"\u05e2\u05d3 \u05e2\u05db\u05e9\u05d9\u05d5 \u05e7\u05e8\u05d0\u05e0\u05d5 \u05d1\u05e2\u05d9\u05e7\u05e8 \u05e9\u05e8\u05d8\u05d5\u05d8\u05d9\u05dd \u05dc\u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05e2\u05d5\u05d1\u05d3\u05d9\u05dd. \u05d0\u05d1\u05dc \u05d4\u05e8\u05d1\u05d4 \u05d7\u05dc\u05e7\u05d9\u05dd \u05dc\u05d0 \u05e0\u05d5\u05dc\u05d3\u05d9\u05dd \u05d1\u05de\u05db\u05d5\u05e0\u05ea \u05e2\u05d9\u05d1\u05d5\u05d3."],[8.0,"\u05d9\u05e6\u05d9\u05e7\u05d4, \u05d7\u05d9\u05e9\u05d5\u05dc, \u05db\u05d9\u05e4\u05d5\u05e3 \u05e4\u05d7 \u05d5\u05d4\u05d6\u05e8\u05e7\u05ea \u05e4\u05dc\u05e1\u05d8\u05d9\u05e7 \u05d9\u05d5\u05e6\u05e8\u05d9\u05dd \u05d0\u05ea \u05d4\u05e6\u05d5\u05e8\u05d4 \u05d1\u05ea\u05d1\u05e0\u05d9\u05ea, \u05d5\u05dc\u05d0 \u05d1\u05db\u05dc\u05d9 \u05d7\u05d9\u05ea\u05d5\u05da."],[17.0,"\u05d5\u05dc\u05db\u05df \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05e9\u05dc\u05d4\u05dd \u05db\u05d5\u05dc\u05dc \u05de\u05d9\u05d3\u05e2 \u05e9\u05dc\u05d0 \u05e7\u05d9\u05d9\u05dd \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05e2\u05d9\u05d1\u05d5\u05d3:"],[23.0,"\u05e9\u05d9\u05e4\u05d5\u05e2\u05d9 \u05e4\u05d9\u05e8\u05d5\u05e7, \u05e7\u05d5 \u05d7\u05dc\u05d5\u05e7\u05d4, \u05e8\u05d3\u05d9\u05d5\u05e1\u05d9\u05dd, \u05db\u05d9\u05d5\u05d5\u05e5 \u05d5\u05ea\u05d5\u05e1\u05e4\u05d5\u05ea \u05e2\u05d9\u05d1\u05d5\u05d3."],[29.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05dc\u05de\u05d3 \u05dc\u05e7\u05e8\u05d5\u05d0 \u05d0\u05ea \u05d4\u05de\u05d9\u05d3\u05e2 \u05d4\u05d6\u05d4, \u05d5\u05de\u05d4 \u05d4\u05d5\u05d0 \u05d0\u05d5\u05de\u05e8 \u05dc\u05de\u05d9 \u05e9\u05de\u05d9\u05d9\u05e6\u05e8 \u05d0\u05ea \u05d4\u05ea\u05d1\u05e0\u05d9\u05ea \u05d5\u05dc\u05de\u05d9 \u05e9\u05de\u05e2\u05d1\u05d3 \u05d0\u05d7\u05e8\u05d9\u05d4."],[38.0,"\u05d1\u05d7\u05dc\u05e7 \u05d9\u05e6\u05d5\u05e7, \u05db\u05dc \u05d3\u05d5\u05e4\u05df \u05e9\u05de\u05e7\u05d1\u05d9\u05dc\u05d4 \u05dc\u05db\u05d9\u05d5\u05d5\u05df \u05d4\u05e4\u05d9\u05e8\u05d5\u05e7 \u05de\u05d4\u05ea\u05d1\u05e0\u05d9\u05ea \u05e6\u05e8\u05d9\u05db\u05d4 \u05e9\u05d9\u05e4\u05d5\u05e2 \u05e7\u05d8\u05df, \u05db\u05d3\u05d9 \u05e9\u05d4\u05d7\u05dc\u05e7 \u05d9\u05d9\u05e6\u05d0."],[47.0,"\u05d4\u05e9\u05d9\u05e4\u05d5\u05e2 \u05de\u05d5\u05e4\u05d9\u05e2 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05d4\u05e2\u05e8\u05d4 \u05db\u05dc\u05dc\u05d9\u05ea, \u05dc\u05de\u05e9\u05dc \u05e9\u05d9\u05e4\u05d5\u05e2 \u05e9\u05dc \u05d0\u05d7\u05ea \u05e2\u05d3 \u05e9\u05dc\u05d5\u05e9 \u05de\u05e2\u05dc\u05d5\u05ea \u05d1\u05db\u05dc \u05d4\u05d3\u05e1\u05e0\u05d5\u05ea, \u05d5\u05dc\u05d0 \u05d1\u05db\u05dc \u05de\u05d1\u05d8."],[57.0,"\u05e7\u05d5 \u05d4\u05d7\u05dc\u05d5\u05e7\u05d4, \u05d4\u05de\u05e7\u05d5\u05dd \u05e9\u05d1\u05d5 \u05e9\u05e0\u05d9 \u05d7\u05e6\u05d0\u05d9 \u05d4\u05ea\u05d1\u05e0\u05d9\u05ea \u05e0\u05e4\u05d2\u05e9\u05d9\u05dd, \u05de\u05e1\u05d5\u05de\u05df \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8, \u05db\u05d9 \u05dc\u05d0\u05d5\u05e8\u05db\u05d5 \u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05d9\u05e9\u05d0\u05e8 \u05ea\u05e4\u05e8."],[66.0,"\u05d5\u05d2\u05dd \u05d4\u05e8\u05d3\u05d9\u05d5\u05e1\u05d9\u05dd \u05de\u05d5\u05e4\u05d9\u05e2\u05d9\u05dd \u05dc\u05e8\u05d5\u05d1 \u05d1\u05d4\u05e2\u05e8\u05d4, \u05dc\u05de\u05e9\u05dc \u05db\u05dc \u05d4\u05e8\u05d3\u05d9\u05d5\u05e1\u05d9\u05dd \u05e9\u05dc\u05d0 \u05e1\u05d5\u05de\u05e0\u05d5, \u05e9\u05dc\u05d5\u05e9\u05d4 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8."],[74.0,"\u05de\u05e9\u05d8\u05d7 \u05e9\u05d9\u05e2\u05d5\u05d1\u05d3 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05d9\u05e6\u05d9\u05e7\u05d4 \u05de\u05e7\u05d1\u05dc \u05ea\u05d5\u05e1\u05e4\u05ea \u05e2\u05d9\u05d1\u05d5\u05d3,"],[80.0,"\u05d5\u05d4\u05ea\u05e7\u05df 8062-3 ISO \u05de\u05d2\u05d3\u05d9\u05e8 \u05d2\u05dd \u05d0\u05d5\u05ea\u05d4 \u05d5\u05d2\u05dd \u05d0\u05ea \u05d3\u05e8\u05d2\u05d5\u05ea \u05d4\u05e1\u05d1\u05d5\u05dc\u05ea \u05e9\u05dc \u05d4\u05d9\u05e6\u05d9\u05e7\u05d4."],[88.0,"\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d9\u05e9 \u05e9\u05e0\u05d9 \u05e9\u05e8\u05d8\u05d5\u05d8\u05d9\u05dd: \u05d0\u05d7\u05d3 \u05e9\u05dc \u05d4\u05d9\u05e6\u05d9\u05e7\u05d4 \u05d4\u05d2\u05d5\u05dc\u05de\u05d9\u05ea \u05d5\u05d0\u05d7\u05d3 \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7 \u05d4\u05de\u05e2\u05d5\u05d1\u05d3."],[94.0,"\u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05e9\u05e8\u05d8\u05d5\u05d8 \u05d0\u05d7\u05d3, \u05e9\u05d1\u05d5 \u05d4\u05d7\u05d5\u05de\u05e8 \u05e9\u05d9\u05d5\u05e1\u05e8 \u05de\u05e6\u05d5\u05d9\u05e8 \u05d1\u05e7\u05d5 phantom."],[101.0,"\u05d5\u05d0\u05ea \u05d4\u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05d4\u05d2\u05d5\u05dc\u05de\u05d9\u05d9\u05dd \u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05de\u05e0\u05e7\u05d5\u05d3\u05d5\u05ea \u05d9\u05d9\u05d7\u05d5\u05e1,"],[104.0,"\u05db\u05de\u05d5 \u05e9\u05dc\u05de\u05d3\u05e0\u05d5 \u05d1\u05e4\u05e8\u05e7 \u05ea\u05e9\u05e2, \u05db\u05d9 \u05d4\u05dd \u05dc\u05d0 \u05d9\u05e9\u05e8\u05d9\u05dd \u05de\u05e1\u05e4\u05d9\u05e7 \u05dc\u05e9\u05de\u05e9 \u05de\u05e9\u05d8\u05d7 \u05e9\u05dc\u05dd."],[111.0,"\u05d2\u05dd \u05d1\u05d7\u05d9\u05e9\u05d5\u05dc \u05d9\u05e9 \u05e9\u05d9\u05e4\u05d5\u05e2\u05d9\u05dd \u05d5\u05e7\u05d5 \u05d7\u05dc\u05d5\u05e7\u05d4, \u05d0\u05d1\u05dc \u05d2\u05dd \u05e9\u05e0\u05d9 \u05d3\u05d1\u05e8\u05d9\u05dd \u05e0\u05d5\u05e1\u05e4\u05d9\u05dd."],[116.0,"\u05d4\u05e8\u05d0\u05e9\u05d5\u05df \u05d4\u05d5\u05d0 \u05d4\u05e4\u05dc\u05d0\u05e9: \u05d4\u05d7\u05d5\u05de\u05e8 \u05d4\u05e2\u05d5\u05d3\u05e3 \u05e9\u05e0\u05d3\u05d7\u05e7 \u05d1\u05d9\u05df \u05e9\u05e0\u05d9 \u05d7\u05e6\u05d0\u05d9 \u05d4\u05ea\u05d1\u05e0\u05d9\u05ea."],[122.0,"\u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05de\u05d2\u05d3\u05d9\u05e8 \u05db\u05de\u05d4 \u05de\u05de\u05e0\u05d5 \u05de\u05d5\u05ea\u05e8 \u05dc\u05d4\u05e9\u05d0\u05d9\u05e8 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e7\u05d9\u05e6\u05d5\u05e5."],[128.0,"\u05d4\u05e9\u05e0\u05d9 \u05d4\u05d5\u05d0 \u05d4\u05e1\u05d8\u05d4: \u05d4\u05de\u05e8\u05d7\u05e7 \u05e9\u05d1\u05d5 \u05d7\u05e6\u05d9 \u05d0\u05d7\u05d3 \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7 \u05d6\u05d6 \u05d1\u05d9\u05d7\u05e1 \u05dc\u05d7\u05e6\u05d9 \u05d4\u05e9\u05e0\u05d9, \u05dc\u05d0\u05d5\u05e8\u05da \u05e7\u05d5 \u05d4\u05d7\u05dc\u05d5\u05e7\u05d4."],[137.0,"\u05dc\u05e9\u05e0\u05d9\u05d4\u05dd \u05d9\u05e9 \u05e1\u05d1\u05d5\u05dc\u05d5\u05ea \u05de\u05ea\u05e7\u05e0\u05d9\u05dd \u05db\u05de\u05d5 10243-1 \u05d0\u05dd, \u05d5\u05d4\u05dd \u05de\u05d5\u05e4\u05d9\u05e2\u05d9\u05dd \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05d4\u05e2\u05e8\u05d4."],[147.0,"\u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05de\u05e1\u05d5\u05de\u05df \u05d2\u05dd \u05db\u05d9\u05d5\u05d5\u05df \u05d4\u05e1\u05d9\u05d1\u05d9\u05dd \u05d1\u05d7\u05d5\u05de\u05e8, \u05db\u05d9 \u05d7\u05d9\u05e9\u05d5\u05dc \u05de\u05db\u05d5\u05d5\u05df \u05d0\u05ea \u05d4\u05e1\u05d9\u05d1\u05d9\u05dd, \u05d5\u05d6\u05d4 \u05de\u05e9\u05e4\u05d9\u05e2 \u05e2\u05dc \u05d4\u05d7\u05d5\u05d6\u05e7."],[156.0,"\u05de\u05d9 \u05e9\u05de\u05e2\u05d1\u05d3 \u05d7\u05dc\u05e7 \u05de\u05d7\u05d5\u05e9\u05dc \u05d1\u05dc\u05d9 \u05dc\u05d3\u05e2\u05ea \u05d0\u05d9\u05e4\u05d4 \u05e2\u05d5\u05d1\u05e8 \u05e7\u05d5 \u05d4\u05d7\u05dc\u05d5\u05e7\u05d4,"],[160.0,"\u05e2\u05dc\u05d5\u05dc \u05dc\u05e7\u05d1\u05e2 \u05d0\u05d5\u05ea\u05d5 \u05e2\u05dc \u05d4\u05ea\u05e4\u05e8, \u05d5\u05dc\u05e7\u05d1\u05dc \u05de\u05d9\u05e7\u05d5\u05dd \u05dc\u05d0 \u05d9\u05e6\u05d9\u05d1."],[166.0,"\u05d1\u05d7\u05dc\u05e7 \u05e4\u05d7, \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05de\u05e8\u05d0\u05d4 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05d4\u05de\u05db\u05d5\u05e4\u05e1\u05e3, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d2\u05dd \u05d0\u05ea \u05d4\u05e4\u05e8\u05d9\u05e1\u05d4 \u05d4\u05e9\u05d5\u05d8\u05d5\u05d7\u05d4."],[174.0,"\u05e8\u05d3\u05d9\u05d5\u05e1 \u05d4\u05db\u05d9\u05e4\u05d5\u05e3 \u05db\u05ea\u05d5\u05d1 \u05d1\u05de\u05e4\u05d5\u05e8\u05e9, \u05db\u05d9 \u05d4\u05d5\u05d0 \u05e7\u05d5\u05d1\u05e2 \u05d0\u05ea \u05d0\u05d5\u05e8\u05da \u05d4\u05e4\u05e8\u05d9\u05e1\u05d4 \u05d5\u05d0\u05ea \u05d4\u05e1\u05d9\u05db\u05d5\u05d9 \u05dc\u05e1\u05d3\u05e7."],[181.0,"\u05d7\u05e9\u05d5\u05d1 \u05dc\u05d1\u05d3\u05d5\u05e7 \u05dc\u05d0\u05d9\u05d6\u05d4 \u05e6\u05d3 \u05e9\u05dc \u05d4\u05db\u05d9\u05e4\u05d5\u05e3 \u05d4\u05de\u05d9\u05d3\u05d4 \u05de\u05de\u05d5\u05d3\u05d3\u05ea: \u05dc\u05d3\u05d5\u05e4\u05df \u05d4\u05e4\u05e0\u05d9\u05de\u05d9\u05ea \u05d0\u05d5 \u05d4\u05d7\u05d9\u05e6\u05d5\u05e0\u05d9\u05ea. \u05d4\u05d4\u05d1\u05d3\u05dc \u05d4\u05d5\u05d0 \u05e2\u05d5\u05d1\u05d9 \u05d4\u05d7\u05d5\u05de\u05e8."],[191.0,"\u05d1\u05e4\u05e8\u05d9\u05e1\u05d4 \u05d4\u05e9\u05d8\u05d5\u05d7\u05d4, \u05e7\u05d5\u05d5\u05d9 \u05d4\u05db\u05d9\u05e4\u05d5\u05e3 \u05de\u05e1\u05d5\u05de\u05e0\u05d9\u05dd, \u05d5\u05dc\u05d9\u05d3\u05dd \u05d4\u05db\u05d9\u05d5\u05d5\u05df: \u05db\u05d9\u05e4\u05d5\u05e3 \u05dc\u05de\u05e2\u05dc\u05d4 \u05d0\u05d5 \u05dc\u05de\u05d8\u05d4."],[199.0,"\u05db\u05d9\u05d5\u05d5\u05df \u05d4\u05d2\u05dc\u05d2\u05d5\u05dc \u05e9\u05dc \u05d4\u05e4\u05d7 \u05de\u05e1\u05d5\u05de\u05df \u05dc\u05e4\u05e2\u05de\u05d9\u05dd, \u05db\u05d9 \u05db\u05d9\u05e4\u05d5\u05e3 \u05d1\u05de\u05e7\u05d1\u05d9\u05dc \u05dc\u05db\u05d9\u05d5\u05d5\u05df \u05d4\u05d2\u05dc\u05d2\u05d5\u05dc \u05e2\u05dc\u05d5\u05dc \u05dc\u05d2\u05e8\u05d5\u05dd \u05dc\u05e1\u05d3\u05e7\u05d9\u05dd."],[207.0,"\u05d5\u05e7\u05d3\u05d7 \u05e7\u05e8\u05d5\u05d1 \u05de\u05d3\u05d9 \u05dc\u05e7\u05d5 \u05db\u05d9\u05e4\u05d5\u05e3 \u05e2\u05dc\u05d5\u05dc \u05dc\u05d4\u05ea\u05e2\u05d5\u05d5\u05ea."],[212.0,"\u05dc\u05db\u05df \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05de\u05d2\u05d3\u05d9\u05e8 \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05de\u05e8\u05d7\u05e7 \u05de\u05d9\u05e0\u05d9\u05de\u05dc\u05d9, \u05d0\u05d5 \u05e9\u05d4\u05e7\u05d3\u05d7 \u05e0\u05e2\u05e9\u05d4 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05db\u05d9\u05e4\u05d5\u05e3."],[219.0,"\u05d4\u05e1\u05d1\u05d5\u05dc\u05d5\u05ea \u05d1\u05e4\u05d7 \u05e8\u05d7\u05d1\u05d5\u05ea \u05d9\u05d5\u05ea\u05e8 \u05de\u05d1\u05e2\u05d9\u05d1\u05d5\u05d3, \u05d5\u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05de\u05d5\u05d2\u05d3\u05e8\u05d5\u05ea \u05d1\u05d4\u05e2\u05e8\u05d4 \u05db\u05dc\u05dc\u05d9\u05ea,"],[227.0,"\u05dc\u05e4\u05d9 \u05ea\u05e7\u05df \u05db\u05de\u05d5 2768 ISO \u05d0\u05d5 \u05ea\u05e7\u05df \u05d9\u05d9\u05e2\u05d5\u05d3\u05d9 \u05dc\u05d7\u05dc\u05e7\u05d9 \u05e4\u05d7."],[233.0,"\u05d1\u05d7\u05dc\u05e7 \u05e4\u05dc\u05e1\u05d8\u05d9\u05e7 \u05de\u05d5\u05d6\u05e8\u05e7, \u05d4\u05e8\u05d1\u05d4 \u05de\u05d4\u05d4\u05d2\u05d3\u05e8\u05d4 \u05de\u05db\u05d5\u05d5\u05e0\u05ea \u05dc\u05ea\u05d1\u05e0\u05d9\u05ea."],[239.0,"\u05d2\u05dd \u05db\u05d0\u05df ;\u05d9\u05e9 \u05e9\u05d9\u05e4\u05d5\u05e2\u05d9 \u05e4\u05d9\u05e8\u05d5\u05e7 \u05d5\u05e7\u05d5 \u05d7\u05dc\u05d5\u05e7\u05d4, \u05d5\u05d1\u05e0\u05d5\u05e1\u05e3 \u05d3\u05e8\u05d9\u05e9\u05d4 \u05dc\u05e2\u05d5\u05d1\u05d9 \u05d3\u05d5\u05e4\u05df \u05d0\u05d7\u05d9\u05d3, \u05db\u05d3\u05d9 \u05e9\u05d4\u05d7\u05dc\u05e7 \u05d9\u05ea\u05e7\u05e8\u05e8 \u05d1\u05dc\u05d9 \u05e2\u05d9\u05d5\u05d5\u05ea\u05d9\u05dd."],[249.0,"\u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05de\u05d2\u05d3\u05d9\u05e8 \u05dc\u05e2\u05d9\u05ea\u05d9\u05dd \u05d0\u05ea \u05de\u05d9\u05e7\u05d5\u05dd \u05e9\u05e2\u05e8 \u05d4\u05d4\u05d6\u05e8\u05e7\u05d4, \u05d0\u05d5 \u05d0\u05d6\u05d5\u05e8 \u05e9\u05d1\u05d5 \u05de\u05d5\u05ea\u05e8 \u05dc\u05de\u05e7\u05dd \u05d0\u05d5\u05ea\u05d5."],[255.0,"\u05d5\u05d2\u05dd \u05d0\u05d6\u05d5\u05e8\u05d9\u05dd \u05e9\u05d1\u05d4\u05dd \u05de\u05d5\u05ea\u05e8\u05d9\u05dd \u05e1\u05d9\u05de\u05e0\u05d9 \u05e4\u05d9\u05e0\u05d9 \u05e4\u05dc\u05d9\u05d8\u05d4, \u05db\u05d9 \u05d4\u05dd \u05de\u05e9\u05d0\u05d9\u05e8\u05d9\u05dd \u05e2\u05d9\u05d2\u05d5\u05dc\u05d9\u05dd \u05e7\u05d8\u05e0\u05d9\u05dd \u05e2\u05dc \u05d4\u05e4\u05e0\u05d9\u05dd."],[262.0,"\u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d4\u05df \u05de\u05d9\u05d3\u05d5\u05ea \u05d4\u05d7\u05dc\u05e7 \u05d4\u05e1\u05d5\u05e4\u05d9. \u05d0\u05ea \u05d4\u05db\u05d9\u05d5\u05d5\u05e5 \u05e9\u05dc \u05d4\u05e4\u05dc\u05e1\u05d8\u05d9\u05e7 \u05d1\u05d4\u05ea\u05e7\u05e8\u05e8\u05d5\u05ea, \u05d9\u05e6\u05e8\u05df \u05d4\u05ea\u05d1\u05e0\u05d9\u05ea \u05de\u05d5\u05e1\u05d9\u05e3 \u05d1\u05e2\u05e6\u05de\u05d5."],[272.0,"\u05d4\u05e1\u05d1\u05d5\u05dc\u05d5\u05ea \u05dc\u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05d5\u05d6\u05e8\u05e7\u05d9\u05dd \u05de\u05d5\u05d2\u05d3\u05e8\u05d5\u05ea \u05d1\u05ea\u05e7\u05df 20457 ISO \u05e9\u05d4\u05d7\u05dc\u05d9\u05e3 \u05d0\u05ea \u05d4\u05ea\u05e7\u05df \u05d4\u05d2\u05e8\u05de\u05e0\u05d9 16742 \u05d0\u05d5\u05dd."],[285.0,"\u05d5\u05de\u05e8\u05e7\u05dd \u05d4\u05e4\u05e0\u05d9\u05dd \u05de\u05d5\u05d2\u05d3\u05e8 \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d1\u05e1\u05d8\u05e0\u05d3\u05e8\u05d8 \u05e9\u05dc \u05d2\u05d9\u05de\u05d5\u05e8 \u05ea\u05d1\u05e0\u05d9\u05ea, \u05db\u05de\u05d5 \u05d558 \u05d0\u05d5 3400 \u05d5\u05e1\"."],[295.0,"\u05d9\u05e9 \u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05e4\u05dc\u05e1\u05d8\u05d9\u05d9\u05dd \u05e9\u05e7\u05d5\u05dc\u05d8\u05d9\u05dd \u05dc\u05d7\u05d5\u05ea, \u05db\u05de\u05d5 \u05e0\u05d9\u05d9\u05dc\u05d5\u05df."],[299.0,"\u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05e9\u05dc\u05d4\u05dd \u05de\u05e9\u05ea\u05e0\u05d5\u05ea \u05dc\u05e4\u05d9 \u05d4\u05dc\u05d7\u05d5\u05ea, \u05d5\u05dc\u05db\u05df \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05de\u05d2\u05d3\u05d9\u05e8 \u05de\u05ea\u05d9 \u05d5\u05d1\u05d0\u05d9\u05d6\u05d4 \u05de\u05e6\u05d1 \u05de\u05d5\u05d3\u05d3\u05d9\u05dd."],[307.0,"\u05d4\u05e2\u05e8\u05d4 \u05db\u05de\u05d5 \u05de\u05d3\u05d9\u05d3\u05d4 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05ea\u05e0\u05d9\u05d4 \u05e9\u05dc \u05e2\u05e9\u05e8\u05d9\u05dd \u05d5\u05d0\u05e8\u05d1\u05e2 \u05e9\u05e2\u05d5\u05ea, \u05d1\u05e2\u05e9\u05e8\u05d9\u05dd \u05d5\u05e9\u05dc\u05d5\u05e9 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d4\u05d9\u05d0 \u05d7\u05dc\u05e7 \u05de\u05d4\u05d3\u05e8\u05d9\u05e9\u05d4."],[316.0,"\u05de\u05d9 \u05e9\u05de\u05d5\u05d3\u05d3 \u05d7\u05dc\u05e7 \u05de\u05d9\u05d3 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05d4\u05d6\u05e8\u05e7\u05d4, \u05d9\u05e7\u05d1\u05dc \u05de\u05d9\u05d3\u05d5\u05ea \u05d0\u05d7\u05e8\u05d5\u05ea, \u05d5\u05e2\u05dc\u05d5\u05dc \u05dc\u05e4\u05e1\u05d5\u05dc \u05d7\u05dc\u05e7 \u05ea\u05e7\u05d9\u05df \u05d0\u05d5 \u05dc\u05e7\u05d1\u05dc \u05d7\u05dc\u05e7 \u05e4\u05e1\u05d5\u05dc."],[326.0,"\u05d9\u05e9 \u05db\u05de\u05d4 \u05d3\u05d1\u05e8\u05d9\u05dd \u05e9\u05de\u05e9\u05d5\u05ea\u05e4\u05d9\u05dd \u05dc\u05db\u05dc \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8\u05d9\u05dd \u05d4\u05d0\u05dc\u05d4."],[330.0,"\u05de\u05e9\u05d8\u05d7 \u05e9\u05e0\u05e9\u05d0\u05e8 \u05db\u05e4\u05d9 \u05e9\u05d9\u05e6\u05d0 \u05de\u05d4\u05ea\u05d1\u05e0\u05d9\u05ea \u05de\u05e1\u05d5\u05de\u05df \u05dc\u05e2\u05d9\u05ea\u05d9\u05dd \u05d1\u05e1\u05d9\u05de\u05d5\u05df \u05e4\u05e0\u05d9 \u05e9\u05d8\u05d7 \u05e2\u05dd \u05e2\u05d9\u05d2\u05d5\u05dc: \u05d0\u05e1\u05d5\u05e8 \u05dc\u05d4\u05e1\u05d9\u05e8 \u05d7\u05d5\u05de\u05e8."],[339.0,"\u05de\u05d9\u05d3\u05d5\u05ea \u05e9\u05dc \u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05d2\u05d5\u05dc\u05de\u05d9\u05d9\u05dd \u05de\u05e7\u05d1\u05dc\u05d5\u05ea \u05e1\u05d1\u05d5\u05dc\u05d5\u05ea \u05e8\u05d7\u05d1\u05d5\u05ea,"],[343.0,"\u05d5\u05de\u05d9\u05d3\u05d5\u05ea \u05e9\u05dc \u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05de\u05e2\u05d5\u05d1\u05d3\u05d9\u05dd \u05de\u05e7\u05d1\u05dc\u05d5\u05ea \u05e1\u05d1\u05d5\u05dc\u05d5\u05ea \u05e9\u05dc \u05e2\u05d9\u05d1\u05d5\u05d3."],[348.0,"\u05d5\u05dc\u05db\u05df \u05d7\u05e9\u05d5\u05d1 \u05dc\u05d6\u05d4\u05d5\u05ea \u05dc\u05db\u05dc \u05de\u05d9\u05d3\u05d4 \u05d0\u05dd \u05d4\u05d9\u05d0 \u05d1\u05d9\u05df \u05e9\u05e0\u05d9 \u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05d2\u05d5\u05dc\u05de\u05d9\u05d9\u05dd, \u05d1\u05d9\u05df \u05d2\u05d5\u05dc\u05de\u05d9 \u05dc\u05de\u05e2\u05d5\u05d1\u05d3, \u05d0\u05d5 \u05d1\u05d9\u05df \u05e9\u05e0\u05d9 \u05de\u05e2\u05d5\u05d1\u05d3\u05d9\u05dd."],[357.0,"\u05de\u05d9\u05d3\u05d4 \u05d1\u05d9\u05df \u05de\u05e9\u05d8\u05d7 \u05d2\u05d5\u05dc\u05de\u05d9 \u05dc\u05de\u05e2\u05d5\u05d1\u05d3 \u05d4\u05d9\u05d0 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d6\u05d5 \u05e9\u05e7\u05d5\u05d1\u05e2\u05ea \u05db\u05de\u05d4 \u05d7\u05d5\u05de\u05e8 \u05d9\u05d5\u05e1\u05e8, \u05d5\u05d0\u05d9\u05e4\u05d4 \u05d4\u05d7\u05dc\u05e7 \u05d9\u05e7\u05d5\u05d1\u05e2."],[366.0,"\u05e8\u05d9\u05db\u05d5\u05d6 \u05d4\u05de\u05dc\u05db\u05d5\u05d3\u05d5\u05ea \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8\u05d9\u05dd \u05dc\u05ea\u05d4\u05dc\u05d9\u05db\u05d9\u05dd \u05d4\u05d0\u05dc\u05d4."],[370.0,"\u05e9\u05d9\u05e4\u05d5\u05e2 \u05e4\u05d9\u05e8\u05d5\u05e7 \u05e9\u05dc\u05d0 \u05e0\u05dc\u05e7\u05d7 \u05d1\u05d7\u05e9\u05d1\u05d5\u05df: \u05de\u05d9\u05d3\u05d4 \u05e9\u05e0\u05de\u05d3\u05d3\u05ea \u05d1\u05e7\u05e6\u05d4 \u05d4\u05dc\u05d0 \u05e0\u05db\u05d5\u05df \u05e9\u05dc \u05d4\u05d3\u05d5\u05e4\u05df \u05d4\u05de\u05e9\u05d5\u05e4\u05e2\u05ea."],[378.0,"\u05e7\u05d5 \u05d7\u05dc\u05d5\u05e7\u05d4 \u05d0\u05d5 \u05e4\u05dc\u05d0\u05e9 \u05e9\u05dc\u05d0 \u05d6\u05d5\u05d4\u05d5, \u05d5\u05e7\u05d9\u05d1\u05d5\u05e2 \u05e2\u05dc \u05d4\u05ea\u05e4\u05e8."],[383.0,"\u05de\u05d9\u05d3\u05ea \u05e4\u05d7 \u05e9\u05e0\u05de\u05d3\u05d3\u05d4 \u05dc\u05e6\u05d3 \u05d4\u05dc\u05d0 \u05e0\u05db\u05d5\u05df \u05e9\u05dc \u05d4\u05db\u05d9\u05e4\u05d5\u05e3."],[388.0,"\u05db\u05d9\u05e4\u05d5\u05e3 \u05d1\u05de\u05e7\u05d1\u05d9\u05dc \u05dc\u05db\u05d9\u05d5\u05d5\u05df \u05d4\u05d2\u05dc\u05d2\u05d5\u05dc, \u05dc\u05de\u05e8\u05d5\u05ea \u05e9\u05d4\u05e9\u05d5\u05e8\u05d8\u05d5\u05d8 \u05e1\u05d9\u05de\u05df \u05d0\u05ea \u05d4\u05db\u05d9\u05d5\u05d5\u05df."],[393.0,"\u05d5\u05de\u05d3\u05d9\u05d3\u05ea \u05e4\u05dc\u05e1\u05d8\u05d9\u05e7 \u05dc\u05e4\u05e0\u05d9 \u05d4\u05d4\u05ea\u05e0\u05d9\u05d4 \u05d4\u05e0\u05d3\u05e8\u05e2\u05d5\u05ea."],[397.0,"\u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05db\u05d6\u05d4, \u05de\u05ea\u05d7\u05d9\u05dc\u05d9\u05dd \u05de\u05d6\u05d9\u05d4\u05d5\u05d9 \u05d4\u05ea\u05d4\u05dc\u05d9\u05da \u05d5\u05de\u05d4\u05d4\u05e2\u05e8\u05d5\u05ea \u05d4\u05db\u05dc\u05dc\u05d9\u05d5\u05ea \u05e9\u05dc\u05d5."],[403.0,"\u05d0\u05d7\u05e8 \u05db\u05da \u05de\u05d6\u05d4\u05d9\u05dd \u05d0\u05ea \u05e7\u05d5 \u05d4\u05d7\u05dc\u05d5\u05e7\u05d4, \u05d0\u05ea \u05db\u05d9\u05d5\u05d5\u05df \u05d4\u05e4\u05d9\u05e8\u05d5\u05e7, \u05d5\u05d0\u05ea \u05d4\u05e9\u05d9\u05e4\u05d5\u05e2\u05d9\u05dd."],[409.0,"\u05d0\u05d7\u05e8 \u05db\u05da \u05de\u05d6\u05d4\u05d9\u05dd \u05d0\u05d9\u05dc\u05d5 \u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05d2\u05d5\u05dc\u05de\u05d9\u05d9\u05dd \u05d5\u05d0\u05d9\u05dc\u05d5 \u05de\u05e2\u05d5\u05d1\u05d3\u05d9\u05dd, \u05d5\u05de\u05d0\u05d9\u05dc\u05d5 \u05e0\u05e7\u05d5\u05d3\u05d5\u05ea \u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05d0\u05ea \u05d4\u05d2\u05d5\u05dc\u05de\u05d9\u05d9\u05dd."],[417.0,"\u05d5\u05e8\u05e7 \u05d0\u05d7\u05e8 \u05db\u05da \u05e2\u05d5\u05d1\u05e8\u05d9\u05dd \u05dc\u05de\u05d9\u05d3\u05d5\u05ea, \u05db\u05e9\u05dc\u05db\u05dc \u05de\u05d9\u05d3\u05d4 \u05d1\u05e8\u05d5\u05e8 \u05dc\u05d0\u05d9\u05d6\u05d4 \u05e1\u05d5\u05d2 \u05de\u05e9\u05d8\u05d7 \u05d4\u05d9\u05d0 \u05e9\u05d9\u05d9\u05db\u05ea."],[424.0,"\u05de\u05d9 \u05e9\u05e7\u05d5\u05e8\u05d0 \u05e9\u05e8\u05d8\u05d5\u05d8 \u05d9\u05e6\u05d9\u05e7\u05d4 \u05db\u05de\u05d5 \u05e9\u05e8\u05d8\u05d5\u05d8 \u05e2\u05d9\u05d1\u05d5\u05d3,"],[428.0,"\u05d9\u05d3\u05e8\u05d5\u05e9 \u05d3\u05d9\u05d5\u05e7 \u05e9\u05d4\u05ea\u05d1\u05e0\u05d9\u05ea \u05dc\u05d0 \u05d9\u05db\u05d5\u05dc\u05d4 \u05dc\u05ea\u05ea, \u05d0\u05d5 \u05d9\u05e4\u05e1\u05e4\u05e1 \u05d3\u05e8\u05d9\u05e9\u05d4 \u05e9\u05e7\u05d9\u05d9\u05de\u05ea \u05e8\u05e7 \u05d1\u05d4\u05e2\u05e8\u05d5\u05ea."],[435.0,"\u05d1\u05e9\u05e8\u05d8\u05d5\u05d8\u05d9\u05dd \u05dc\u05ea\u05d1\u05e0\u05d9\u05d5\u05ea, \u05d4\u05e6\u05d5\u05e8\u05d4 \u05e0\u05d5\u05e6\u05e8\u05ea \u05d1\u05ea\u05d1\u05e0\u05d9\u05ea, \u05d5\u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05de\u05d5\u05e1\u05d9\u05e3 \u05e9\u05d9\u05e4\u05d5\u05e2\u05d9\u05dd, \u05e7\u05d5 \u05d7\u05dc\u05d5\u05e7\u05d4, \u05e8\u05d3\u05d9\u05d5\u05e1\u05d9\u05dd \u05d5\u05ea\u05d5\u05e1\u05e4\u05d5\u05ea \u05e2\u05d9\u05d1\u05d5\u05d3."],[446.0,"\u05d1\u05d7\u05d9\u05e9\u05d5\u05dc \u05de\u05d2\u05d3\u05d9\u05e8\u05d9\u05dd \u05d2\u05dd \u05e4\u05dc\u05d0\u05e9 \u05d5\u05d4\u05e1\u05d8\u05d4, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05db\u05d9\u05d5\u05d5\u05df \u05e1\u05d9\u05d1\u05d9\u05dd."],[452.0,"\u05d1\u05e4\u05d7, \u05e8\u05d3\u05d9\u05d5\u05e1 \u05d4\u05db\u05d9\u05e4\u05d5\u05e3, \u05d4\u05e6\u05d3 \u05e9\u05d0\u05dc\u05d9\u05d5 \u05de\u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05d5\u05db\u05d9\u05d5\u05d5\u05df \u05d4\u05d2\u05dc\u05d2\u05d5\u05dc \u05d4\u05dd \u05d7\u05dc\u05e7 \u05de\u05d4\u05d3\u05e8\u05d9\u05e9\u05d4."],[460.0,"\u05d1\u05e4\u05dc\u05e1\u05d8\u05d9\u05e7, \u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05d4\u05df \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7 \u05d4\u05e1\u05d5\u05e4\u05d9, \u05d5\u05d4\u05ea\u05e7\u05df \u05d4\u05d5\u05d0 50! 7. \u05d1\u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05e9\u05e7\u05d5\u05dc\u05d8\u05d9\u05dd \u05dc\u05d7\u05d5\u05ea, \u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05d0\u05d7\u05e8\u05d9 \u05d4\u05ea\u05e0\u05d9\u05d4."],[473.0,"\u05d5\u05d1\u05db\u05dc \u05d4\u05ea\u05d4\u05dc\u05d9\u05db\u05d9\u05dd, \u05de\u05d6\u05d4\u05d9\u05dd \u05dc\u05db\u05dc \u05de\u05d9\u05d3\u05d4 \u05d0\u05dd \u05d4\u05d9\u05d0 \u05d2\u05d5\u05dc\u05de\u05d9\u05ea \u05d0\u05d5 \u05de\u05e2\u05d5\u05d1\u05d3\u05ea."],[478.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05e2\u05e1\u05d5\u05e7 \u05d1\u05de\u05d0\u05e4\u05d9\u05d9\u05e0\u05d9\u05dd \u05e7\u05e8\u05d9\u05d8\u05d9\u05d9\u05dd \u05d5\u05d1\u05d1\u05d3\u05d9\u05e7\u05d4: \u05de\u05d4 \u05d6\u05d4 KC, \u05d5\u05de\u05d4 \u05d6\u05d5 \u05d1\u05d3\u05d9\u05e7\u05ea \u05e4\u05e8\u05d9\u05d8 \u05e8\u05d0\u05e9\u05d5\u05df."],[487.0,"\u05e0\u05ea\u05e8\u05d0\u05d4 \u05d1\u05e4\u05e8\u05e7 \u05ea\u05e9\u05e2 \u05e2\u05e9\u05e8\u05d4."]]};
window.MH_TR["ch19"]={"t":"\u05de\u05d0\u05e4\u05d9\u05d9\u05e0\u05d9\u05dd \u05e7\u05e8\u05d9\u05d8\u05d9\u05d9\u05dd \u05d5\u05d1\u05d3\u05d9\u05e7\u05d4","l":[[1.0,"\u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d9\u05e9 \u05e2\u05e9\u05e8\u05d5\u05ea \u05de\u05d9\u05d3\u05d5\u05ea, \u05d5\u05dc\u05d0 \u05db\u05d5\u05dc\u05df \u05d7\u05e9\u05d5\u05d1\u05d5\u05ea \u05d1\u05d0\u05d5\u05ea\u05d4 \u05de\u05d9\u05d3\u05d4."],[6.0,"\u05d9\u05e9 \u05de\u05d9\u05d3\u05d5\u05ea \u05e9\u05d0\u05dd \u05d4\u05df \u05d7\u05d5\u05e8\u05d2\u05d5\u05ea, \u05d4\u05d7\u05dc\u05e7 \u05e2\u05d3\u05d9\u05d9\u05df \u05e2\u05d5\u05d1\u05d3. \u05d5\u05d9\u05e9 \u05de\u05d9\u05d3\u05d5\u05ea \u05e9\u05d0\u05dd \u05d4\u05df \u05d7\u05d5\u05e8\u05d2\u05d5\u05ea, \u05d4\u05d7\u05dc\u05e7 \u05e0\u05db\u05e9\u05d5\u05dc, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05de\u05e1\u05db\u05df \u05d0\u05e0\u05e9\u05d9\u05dd."],[17.0,"\u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05de\u05e1\u05de\u05df \u05d0\u05ea \u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05d4\u05d0\u05dc\u05d4, \u05d5\u05d0\u05d5\u05ea\u05d5 \u05e1\u05d9\u05de\u05d5\u05df \u05e7\u05d5\u05d1\u05e2 \u05d0\u05d9\u05da \u05de\u05d9\u05d9\u05e6\u05e8\u05d9\u05dd \u05d0\u05d5\u05ea\u05df, \u05d0\u05d9\u05da \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d0\u05d5\u05ea\u05df, \u05d5\u05de\u05d4 \u05de\u05ea\u05e2\u05d3\u05d9\u05dd."],[25.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05dc\u05de\u05d3 \u05dc\u05e7\u05e8\u05d5\u05d0 \u05de\u05d0\u05e4\u05d9\u05d9\u05e0\u05d9\u05dd \u05e7\u05e8\u05d9\u05d8\u05d9\u05d9\u05dd, \u05d5\u05dc\u05d4\u05d1\u05d9\u05df \u05de\u05d4 \u05d3\u05d5\u05e8\u05e9\u05d5\u05ea \u05d1\u05d3\u05d9\u05e7\u05ea \u05e4\u05e8\u05d9\u05d8 \u05e8\u05d0\u05e9\u05d5\u05df \u05d5\u05de\u05d3\u05d9\u05d3\u05d4 \u05d1\u05de\u05db\u05d5\u05e0\u05ea \u05de\u05d3\u05d9\u05d3\u05d4."],[35.0,"\u05de\u05d0\u05e4\u05d9\u05d9\u05df \u05de\u05e4\u05ea\u05d7, KC \u05d4\u05d5\u05d0 \u05de\u05d9\u05d3\u05d4 \u05d0\u05d5 \u05d3\u05e8\u05d9\u05e9\u05d4 \u05e9\u05d4\u05e9\u05d5\u05e0\u05d5\u05ea \u05e9\u05dc\u05d4"],[40.0,"\u05de\u05e9\u05e4\u05d9\u05e2\u05d4 \u05de\u05d0\u05d5\u05d3 \u05e2\u05dc \u05d4\u05e4\u05d5\u05e0\u05e7\u05e6\u05d9\u05d4, \u05e2\u05dc \u05d4\u05d1\u05d8\u05d9\u05d7\u05d5\u05ea \u05d0\u05d5 \u05e2\u05dc \u05d4\u05d4\u05e8\u05db\u05d1\u05d4."],[45.0,"\u05d4\u05e1\u05d9\u05de\u05d5\u05df \u05e9\u05dc\u05d5 \u05de\u05e9\u05ea\u05e0\u05d4 \u05d1\u05d9\u05df \u05d0\u05e8\u05d2\u05d5\u05e0\u05d9\u05dd: \u05de\u05e2\u05d5\u05d9\u05df, \u05de\u05e9\u05d5\u05e9\u05d4, \u05d0\u05d5\u05ea \u05d1\u05ea\u05d5\u05da \u05de\u05e1\u05d2\u05e8\u05ea, \u05d0\u05d5 \u05e1\u05de\u05dc \u05d0\u05d7\u05e8."],[54.0,"\u05d5\u05dc\u05db\u05df \u05d4\u05de\u05e9\u05de\u05e2\u05d5\u05ea \u05e9\u05dc \u05d4\u05e1\u05de\u05dc \u05ea\u05de\u05d9\u05d3 \u05de\u05d5\u05d2\u05d3\u05e8\u05ea \u05d1\u05d4\u05e2\u05e8\u05d5\u05ea \u05e9\u05dc \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8, \u05d0\u05d5 \u05d1\u05de\u05e4\u05e8\u05d8 \u05e9\u05dc \u05d4\u05dc\u05e7\u05d5\u05d7."],[61.0,"\u05d1\u05d4\u05e8\u05d1\u05d4 \u05d0\u05e8\u05d2\u05d5\u05e0\u05d9\u05dd \u05d9\u05e9 \u05d2\u05dd \u05e1\u05d9\u05d5\u05d5\u05d2 \u05dc\u05e4\u05d2\u05de\u05d9\u05dd: \u05e7\u05e8\u05d9\u05d8\u05d9, \u05e2\u05d9\u05e7\u05e8\u05d9 \u05d5\u05de\u05e9\u05e0\u05d9."],[67.0,"\u05e4\u05d2\u05dd \u05e7\u05e8\u05d9\u05d8\u05d9 \u05e2\u05dc\u05d5\u05dc \u05dc\u05d2\u05e8\u05d5\u05dd \u05dc\u05e1\u05db\u05e0\u05d4, \u05e4\u05d2\u05dd \u05e2\u05d9\u05e7\u05e8\u05d9 \u05e4\u05d5\u05d2\u05e2 \u05d1\u05e4\u05d5\u05e0\u05e7\u05e6\u05d9\u05d4, \u05d5\u05e4\u05d2\u05dd \u05de\u05e9\u05e0\u05d9 \u05dc\u05d0 \u05de\u05e9\u05e4\u05d9\u05e2 \u05e2\u05dc \u05d4\u05e9\u05d9\u05de\u05d5\u05e9."],[76.0,"\u05de\u05d9 \u05e9\u05dc\u05d0 \u05de\u05db\u05d9\u05e8 \u05d0\u05ea \u05d4\u05e1\u05de\u05dc, \u05e7\u05d5\u05e8\u05d0 \u05de\u05d0\u05e4\u05d9\u05d9\u05df \u05e7\u05e8\u05d9\u05d8\u05d9 \u05db\u05de\u05d5 \u05db\u05dc \u05de\u05d9\u05d3\u05d4 \u05d0\u05d7\u05e8\u05ea."],[82.0,"\u05de\u05d0\u05e4\u05d9\u05d9\u05df \u05e7\u05e8\u05d9\u05d8\u05d9 \u05d4\u05d5\u05d0 \u05dc\u05d0 \u05e8\u05e7 \u05de\u05d9\u05d3\u05d4 \u05e2\u05dd \u05e1\u05d1\u05d5\u05dc\u05ea. \u05d4\u05d5\u05d0 \u05d3\u05e8\u05d9\u05e9\u05d4 \u05dc\u05e0\u05d9\u05d4\u05d5\u05dc \u05d4\u05ea\u05d4\u05dc\u05d9\u05da."],[88.0,"\u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d4\u05d5\u05d0 \u05de\u05d7\u05d9\u05d9\u05d1 \u05d1\u05e7\u05e8\u05d4 \u05e1\u05d8\u05d8\u05d9\u05e1\u05d8\u05d9\u05ea \u05d1\u05d9\u05d9\u05e6\u05d5\u05e8, \u05d5\u05dc\u05d0 \u05e8\u05e7 \u05d1\u05d3\u05d9\u05e7\u05d4 \u05d1\u05e1\u05d5\u05e3."],[94.0,"\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d4\u05d5\u05d0 \u05de\u05d7\u05d9\u05d9\u05d1 \u05d1\u05d3\u05d9\u05e7\u05d4 \u05e9\u05dc \u05de\u05d0\u05d4 \u05d0\u05d7\u05d5\u05d6 \u05de\u05d4\u05d7\u05dc\u05e7\u05d9\u05dd, \u05d5\u05dc\u05d0 \u05de\u05d3\u05d2\u05dd."],[99.0,"\u05d5\u05d4\u05d5\u05d0 \u05de\u05d7\u05d9\u05d9\u05d1 \u05ea\u05d9\u05e2\u05d5\u05d3: \u05de\u05d9 \u05de\u05d3\u05d3, \u05d1\u05de\u05d4, \u05d5\u05de\u05d4 \u05d4\u05ea\u05d5\u05e6\u05d0\u05d4, \u05dc\u05db\u05dc \u05d7\u05dc\u05e7 \u05d0\u05d5 \u05dc\u05db\u05dc \u05e1\u05d3\u05e8\u05d4."],[107.0,"\u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d0\u05e1\u05d5\u05e8 \u05dc\u05e9\u05e0\u05d5\u05ea \u05d0\u05ea \u05d4\u05ea\u05d4\u05dc\u05d9\u05da \u05e9\u05de\u05d9\u05d9\u05e6\u05e8 \u05d0\u05d5\u05ea\u05d5 \u05d1\u05dc\u05d9 \u05d0\u05d9\u05e9\u05d5\u05e8, \u05d2\u05dd \u05d0\u05dd \u05d4\u05e9\u05d9\u05e0\u05d5\u05d9 \u05e0\u05e8\u05d0\u05d4 \u05e7\u05d8\u05df."],[114.0,"\u05de\u05d0\u05e4\u05d9\u05d9\u05df \u05e7\u05e8\u05d9\u05d8\u05d9 \u05e9\u05e2\u05d5\u05d1\u05e8 \u05d1\u05d1\u05d3\u05d9\u05e7\u05d4 \u05d0\u05d1\u05dc \u05dc\u05d0 \u05e0\u05de\u05d3\u05d3 \u05dc\u05e4\u05d9 \u05d4\u05e0\u05d5\u05d4\u05dc, \u05d4\u05d5\u05d0 \u05de\u05d1\u05d7\u05d9\u05e0\u05ea \u05d4\u05dc\u05e7\u05d5\u05d7 \u05dc\u05d0 \u05e0\u05d1\u05d3\u05e7."],[122.0,"\u05db\u05d3\u05d9 \u05dc\u05d3\u05e2\u05ea \u05d0\u05dd \u05ea\u05d4\u05dc\u05d9\u05da \u05de\u05e1\u05d5\u05d2\u05dc \u05dc\u05d9\u05d9\u05e6\u05e8 \u05de\u05d0\u05e4\u05d9\u05d9\u05df \u05e7\u05e8\u05d9\u05d8\u05d9, \u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05d0\u05ea \u05d4\u05d9\u05db\u05d5\u05dc\u05ea \u05e9\u05dc\u05d5."],[128.0,"\u05dd0 \u05de\u05e9\u05d5\u05d5\u05d4 \u05d0\u05ea \u05e8\u05d5\u05d7\u05d1 \u05d4\u05e1\u05d1\u05d5\u05dc\u05ea \u05dc\u05e4\u05d9\u05d6\u05d5\u05e8 \u05e9\u05dc \u05d4\u05ea\u05d4\u05dc\u05d9\u05da: \u05e8\u05d5\u05d7\u05d1 \u05d4\u05e1\u05d1\u05d5\u05dc\u05ea, \u05d7\u05dc\u05e7\u05d9 \u05e9\u05e9 \u05e1\u05d8\u05d9\u05d5\u05ea \u05ea\u05e7\u05df."],[137.0,"Cpk \u05de\u05d5\u05e1\u05d9\u05e3 \u05d0\u05ea \u05de\u05d9\u05e7\u05d5\u05dd \u05d4\u05ea\u05d4\u05dc\u05d9\u05da: \u05d4\u05de\u05e8\u05d7\u05e7 \u05de\u05d4\u05de\u05de\u05d5\u05e6\u05e2 \u05dc\u05d2\u05d1\u05d5\u05dc \u05d4\u05e7\u05e8\u05d5\u05d1, \u05d7\u05dc\u05e7\u05d9 \u05e9\u05dc\u05d5\u05e9 \u05e1\u05d8\u05d9\u05d5\u05ea \u05ea\u05e7\u05df."],[146.0,"\u05ea\u05d4\u05dc\u05d9\u05da \u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05d9\u05d5\u05ea \u05e6\u05e8 \u05de\u05e1\u05e4\u05d9\u05e7, \u05d0\u05d1\u05dc \u05e7\u05e8\u05d5\u05d1 \u05de\u05d3\u05d9 \u05dc\u05d2\u05d1\u05d5\u05dc, \u05d5\u05d0\u05d6 \u05e1\u05e7\u05e1 \u05d8\u05d5\u05d1 \u05d5-\u05d0\u05e7\u05e1 \u05e0\u05de\u05d5\u05da."],[154.0,"\u05d3\u05e8\u05d9\u05e9\u05d4 \u05e0\u05e4\u05d5\u05e6\u05d4 \u05d4\u05d9\u05d0 Cpk \u05e9\u05dc 1.33 \u05dc\u05e4\u05d7\u05d5\u05ea, \u05d5\u05d1\u05de\u05d0\u05e4\u05d9\u05d9\u05e0\u05d9\u05dd \u05e7\u05e8\u05d9\u05d8\u05d9\u05d9\u05dd \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8."],[163.0,"\u05d5\u05dc\u05db\u05df \u05de\u05d9 \u05e9\u05de\u05db\u05d5\u05d5\u05df \u05dc\u05e7\u05e6\u05d4 \u05d4\u05e1\u05d1\u05d5\u05dc\u05ea \u05db\u05d3\u05d9 \u05dc\u05d4\u05e9\u05d0\u05d9\u05e8 \u05d7\u05d5\u05de\u05e8 \u05dc\u05ea\u05d9\u05e7\u05d5\u05df, \u05de\u05d5\u05e8\u05d9\u05d3 \u05d0\u05ea \u05d4-%\u05d0\u05e7\u05e1, \u05d2\u05dd \u05db\u05e9\u05db\u05dc \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05d1\u05e1\u05d1\u05d5\u05dc\u05ea."],[173.0,"\u05d1\u05d3\u05d9\u05e7\u05ea \u05e4\u05e8\u05d9\u05d8 \u05e8\u05d0\u05e9\u05d5\u05df, \u2026, \u05de\u05d5\u05db\u05d9\u05d7\u05d4 \u05e9\u05d4\u05ea\u05d4\u05dc\u05d9\u05da \u05de\u05e1\u05d5\u05d2\u05dc \u05dc\u05d9\u05d9\u05e6\u05e8 \u05d7\u05dc\u05e7 \u05e9\u05e2\u05d5\u05de\u05d3 \u05d1\u05db\u05dc \u05d3\u05e8\u05d9\u05e9\u05d5\u05ea \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8."],[182.0,"\u05d1\u05ea\u05e2\u05d5\u05e4\u05d4 \u05d5\u05d1\u05d7\u05dc\u05dc \u05d4\u05d9\u05d0 \u05de\u05d5\u05d2\u05d3\u05e8\u05ea \u05d1\u05ea\u05e7\u05df AS9102."],[189.0,"\u05d4\u05ea\u05e7\u05df \u05de\u05d2\u05d3\u05d9\u05e8 \u05e9\u05dc\u05d5\u05e9\u05d4 \u05d8\u05e4\u05e1\u05d9\u05dd: \u05d4\u05e8\u05d0\u05e9\u05d5\u05d5\u05df \u05de\u05d6\u05d4\u05d4 \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05d5\u05d0\u05ea \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8, \u05d4\u05e9\u05e0\u05d9 \u05de\u05ea\u05e2\u05d3 \u05d7\u05d5\u05de\u05e8\u05d9\u05dd,"],[197.0,"\u05ea\u05d4\u05dc\u05d9\u05db\u05d9\u05dd \u05de\u05d9\u05d5\u05d7\u05d3\u05d9\u05dd \u05d5\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05e4\u05d5\u05e0\u05e7\u05e6\u05d9\u05d5\u05e0\u05dc\u05d9\u05d5\u05ea, \u05d5\u05d4\u05e9\u05dc\u05d9\u05e9\u05e9\u05d9 \u05de\u05ea\u05e2\u05d3 \u05db\u05dc \u05de\u05d0\u05e4\u05d9\u05d9\u05df \u05d5\u05de\u05d0\u05e4\u05d9\u05d9\u05df."],[206.0,"\u05d1\u05d8\u05d5\u05e4\u05e1 \u05d4\u05e9\u05dc\u05d9\u05e9\u05d9, \u05db\u05dc \u05de\u05d9\u05d3\u05d4, \u05db\u05dc \u05e1\u05d1\u05d5\u05dc\u05ea \u05d5\u05db\u05dc \u05d4\u05e2\u05e8\u05d4 \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05de\u05e7\u05d1\u05dc\u05d5\u05ea \u05e9\u05d5\u05e8\u05d4, \u05e2\u05dd \u05d4\u05ea\u05d5\u05e6\u05d0\u05d4 \u05e9\u05e0\u05de\u05d3\u05d3\u05d4."],[215.0,"\u05d5\u05d1\u05d3\u05d9\u05e7\u05d4 \u05db\u05d6\u05d5 \u05d7\u05d5\u05d6\u05e8\u05ea \u05e2\u05dc \u05e2\u05e6\u05de\u05d4 \u05d0\u05d7\u05e8\u05d9 \u05e9\u05d9\u05e0\u05d5\u05d9 \u05d1\u05ea\u05db\u05e0\u05d5\u05df, \u05e9\u05d9\u05e0\u05d5\u05d9 \u05d1\u05ea\u05d4\u05dc\u05d9\u05da, \u05de\u05e2\u05d1\u05e8 \u05dc\u05d0\u05ea\u05e8 \u05d0\u05d7\u05e8, \u05d0\u05d5 \u05d4\u05e4\u05e1\u05e7\u05d4 \u05d0\u05e8\u05d5\u05db\u05d4 \u05d1\u05d9\u05d9\u05e6\u05d5\u05e8."],[225.0,"\u05de\u05d9 \u05e9\u05de\u05e9\u05e0\u05d4 \u05d0\u05ea \u05ea\u05d4\u05dc\u05d9\u05da \u05d4\u05d9\u05d9\u05e6\u05d5\u05e8 \u05d5\u05dc\u05d0 \u05d7\u05d5\u05d6\u05e8 \u05e2\u05dc \u05d4\u05d1\u05d3\u05d9\u05e7\u05d4, \u05de\u05e1\u05e4\u05e7 \u05d7\u05dc\u05e7 \u05e9\u05dc\u05d0 \u05d4\u05d5\u05db\u05d7 \u05e9\u05d4\u05d5\u05d0 \u05e2\u05d5\u05de\u05d3 \u05d1\u05d3\u05e8\u05d9\u05e9\u05d5\u05ea."],[233.0,"\u05db\u05d3\u05d9 \u05e9\u05d1\u05d3\u05d9\u05e7\u05ea \u05e4\u05e8\u05d9\u05d8 \u05e8\u05d0\u05e9\u05d5\u05df \u05ea\u05d4\u05d9\u05d4 \u05de\u05dc\u05d0\u05d4, \u05de\u05de\u05e1\u05e4\u05e8\u05d9\u05dd \u05d0\u05ea \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8."],[238.0,"\u05db\u05dc \u05d3\u05e8\u05d9\u05e9\u05d4 \u05de\u05e7\u05d1\u05dc\u05ea \u05d1\u05dc\u05d5\u05df \u05e2\u05dd \u05de\u05e1\u05e4\u05e8: \u05de\u05d9\u05d3\u05d4, \u05e1\u05d1\u05d5\u05dc\u05ea \u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05ea, \u05d7\u05e1\u05e4\u05d5\u05e1, \u05d5\u05d0\u05e4\u05d9\u05dc\u05d5 \u05d4\u05e2\u05e8\u05d4 \u05db\u05dc\u05dc\u05d9\u05ea."],[247.0,"\u05db\u05dc \u05de\u05e1\u05e4\u05e8 \u05d4\u05d5\u05d0 \u05e9\u05d5\u05e8\u05d4 \u05d1\u05d3\u05d5\u05d7 \u05d4\u05d1\u05d3\u05d9\u05e7\u05d4, \u05d5\u05dc\u05db\u05df \u05d0\u05d9 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05e4\u05e1\u05e4\u05e1 \u05d3\u05e8\u05d9\u05e9\u05d4 \u05d1\u05dc\u05d9 \u05e9\u05d4\u05e9\u05d5\u05e8\u05d4 \u05ea\u05d9\u05e9\u05d0\u05e8 \u05e8\u05d9\u05e7\u05d4."],[254.0,"\u05d4\u05e2\u05e8\u05d5\u05ea \u05db\u05de\u05d5 \u05e9\u05d1\u05d9\u05e8\u05ea \u05e4\u05d9\u05e0\u05d5\u05ea, \u05e1\u05d9\u05de\u05d5\u05df \u05d4\u05d7\u05dc\u05e7 \u05d0\u05d5 \u05e6\u05d9\u05e4\u05d5\u05d9 \u05de\u05e7\u05d1\u05dc\u05d5\u05ea \u05d2\u05dd \u05d4\u05df \u05de\u05e1\u05e4\u05e8, \u05d5\u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d0\u05d5\u05ea\u05df \u05db\u05de\u05d5 \u05db\u05dc \u05de\u05d9\u05d3\u05d4."],[264.0,"\u05d5\u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05e2\u05dd \u05db\u05de\u05d4 \u05d2\u05d9\u05dc\u05d9\u05d5\u05e0\u05d5\u05ea, \u05d4\u05de\u05e1\u05e4\u05d5\u05e8 \u05e2\u05d5\u05d1\u05e8 \u05e2\u05dc \u05db\u05dc \u05d4\u05d2\u05d9\u05dc\u05d9\u05d5\u05e0\u05d5\u05ea, \u05d5\u05dc\u05d0 \u05e8\u05e7 \u05e2\u05dc \u05d4\u05e8\u05d0\u05e9\u05d5\u05df."],[271.0,"\u05de\u05db\u05d5\u05e0\u05ea \u05de\u05d3\u05d9\u05d3\u05d4, CMM, \u05de\u05d5\u05d3\u05d3\u05ea \u05e0\u05e7\u05d5\u05d3\u05d5\u05ea \u05e2\u05dc \u05d4\u05d7\u05dc\u05e7 \u05d5\u05de\u05d7\u05e9\u05d1\u05ea \u05de\u05d4\u05df \u05d0\u05ea \u05d4\u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05d4."],[279.0,"\u05d4\u05ea\u05d5\u05db\u05e0\u05d9\u05ea \u05e9\u05dc\u05d4 \u05e6\u05e8\u05d9\u05db\u05d4 \u05dc\u05d4\u05d9\u05d1\u05e0\u05d5\u05ea \u05dc\u05e4\u05d9 \u05de\u05e2\u05e8\u05db\u05ea \u05d4\u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05e9\u05d1\u05e9\u05e8\u05d8\u05d5\u05d8: \u05d0\u05d5\u05ea\u05dd \u05de\u05e9\u05d8\u05d7\u05d9\u05dd, \u05d1\u05d0\u05d5\u05ea\u05d5 \u05e1\u05d3\u05e8."],[287.0,"\u05ea\u05d5\u05db\u05e0\u05d9\u05ea \u05e9\u05d1\u05d5\u05e0\u05d4 \u05e6\u05d9\u05e8\u05d9\u05dd \u05de\u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05d0\u05d7\u05e8\u05d9\u05dd, \u05e0\u05d5\u05ea\u05e0\u05ea \u05de\u05e1\u05e4\u05e8\u05d9\u05dd \u05e9\u05e0\u05e8\u05d0\u05d9\u05dd \u05de\u05d3\u05d5\u05d9\u05e7\u05d9\u05dd, \u05d0\u05d1\u05dc \u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05de\u05e9\u05d4\u05d5 \u05d0\u05d7\u05e8."],[294.0,"\u05d5\u05d2\u05dd \u05e9\u05d9\u05d8\u05ea \u05d4\u05d7\u05d9\u05e9\u05d5\u05d1 \u05de\u05e9\u05e0\u05d4: \u05e8\u05d9\u05d1\u05d5\u05e2\u05d9\u05dd \u05e7\u05d8\u05e0\u05d9\u05dd, \u05d2\u05dc\u05d9\u05dc \u05de\u05e7\u05d9\u05e3 \u05d0\u05d5 \u05d2\u05dc\u05d9\u05dc \u05e4\u05e0\u05d9\u05de\u05d9, \u05db\u05de\u05d5 \u05e9\u05e8\u05d0\u05d9\u05e0\u05d5 \u05d1\u05e4\u05e8\u05e7 \u05e9\u05e9."],[303.0,"\u05dc\u05db\u05df \u05d3\u05d5\u05d7 \u05de\u05db\u05d5\u05e0\u05ea \u05de\u05d3\u05d9\u05d3\u05d4 \u05e6\u05e8\u05d9\u05da \u05dc\u05e6\u05d9\u05d9\u05df \u05d0\u05ea \u05de\u05e2\u05e8\u05db\u05ea \u05d4\u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05d5\u05d0\u05ea \u05e9\u05d9\u05d8\u05ea \u05d4\u05d7\u05d9\u05e9\u05d5\u05d1, \u05d5\u05dc\u05d0 \u05e8\u05e7 \u05d0\u05ea \u05d4\u05de\u05e1\u05e4\u05e8."],[312.0,"\u05d2\u05dd \u05d4\u05db\u05dc\u05d9 \u05e9\u05de\u05d5\u05d3\u05d3 \u05d4\u05d5\u05d0 \u05d7\u05dc\u05e7 \u05de\u05d4\u05ea\u05d5\u05e6\u05d0\u05d4."],[315.0,"\u05db\u05dc\u05dc \u05de\u05e7\u05d5\u05d1\u05dc \u05d0\u05d5\u05de\u05e8 \u05e9\u05db\u05d5\u05e9\u05e8 \u05d4\u05d4\u05e4\u05e8\u05d3\u05d4 \u05e9\u05dc \u05d4\u05db\u05dc\u05d9 \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d9\u05d5\u05ea \u05dc\u05e4\u05d7\u05d5\u05ea \u05e2\u05e9\u05d9\u05e8\u05d9\u05ea \u05de\u05e8\u05d5\u05d7\u05d1 \u05d4\u05e1\u05d1\u05d5\u05dc\u05ea."],[323.0,"\u05d5\u05d1\u05d3\u05d9\u05e7\u05ea \u05d7\u05d6\u05e8\u05ea\u05d9\u05d5\u05ea \u05d5\u05e9\u05d7\u05d6\u05d5\u05e8\u05d9\u05d5\u05ea, 88\u05d7 6806, \u05d1\u05d5\u05d3\u05e7\u05ea \u05db\u05de\u05d4 \u05de\u05d4\u05e4\u05d9\u05d6\u05d5\u05e8 \u05d1\u05de\u05d3\u05d9\u05d3\u05d5\u05ea \u05e0\u05d5\u05d1\u05e2 \u05de\u05d4\u05db\u05dc\u05d9 \u05d5\u05de\u05d4\u05de\u05d5\u05d3\u05d3, \u05d5\u05dc\u05d0 \u05de\u05d4\u05d7\u05dc\u05e7\u05d9\u05dd."],[334.0,"\u05db\u05dc\u05d9 \u05e9\u05d4\u05e4\u05d9\u05d6\u05d5\u05e8 \u05e9\u05dc\u05d5 \u05d2\u05d3\u05d5\u05dc, \u05d9\u05db\u05d5\u05dc \u05dc\u05e4\u05e1\u05d5\u05dc \u05d7\u05dc\u05e7\u05d9\u05dd \u05ea\u05e7\u05d9\u05e0\u05d9\u05dd \u05d5\u05dc\u05e7\u05d1\u05dc \u05d7\u05dc\u05e7\u05d9\u05dd \u05e4\u05e1\u05d5\u05dc\u05d9\u05dd, \u05d5\u05d0\u05e3 \u05d0\u05d7\u05d3 \u05dc\u05d0 \u05d9\u05e9\u05d9\u05dd \u05dc\u05d1."],[342.0,"\u05d5\u05d4\u05db\u05dc\u05d9\u05dd \u05e6\u05e8\u05d9\u05db\u05d9\u05dd \u05dc\u05d4\u05d9\u05d5\u05ea \u05de\u05db\u05d5\u05d9\u05dc\u05d9\u05dd, \u05e2\u05dd \u05e2\u05e7\u05d9\u05d1\u05d5\u05ea \u05dc\u05ea\u05e7\u05df \u05de\u05d3\u05d9\u05d3\u05d4 \u05de\u05d5\u05db\u05e8."],[348.0,"\u05db\u05dc \u05de\u05d3\u05d9\u05d3\u05d4 \u05db\u05d5\u05dc\u05dc\u05ea \u05d0\u05d9 \u05d5\u05d3\u05d0\u05d5\u05ea. \u05db\u05e9\u05ea\u05d5\u05e6\u05d0\u05d4 \u05e0\u05de\u05e6\u05d0\u05ea \u05e7\u05e8\u05d5\u05d1 \u05dc\u05d2\u05d1\u05d5\u05dc \u05d4\u05e1\u05d1\u05d5\u05dc\u05ea,"],[354.0,"\u05e7\u05e9\u05d4 \u05dc\u05d3\u05e2\u05ea \u05d1\u05d5\u05d5\u05d3\u05d0\u05d5\u05ea \u05d1\u05e6\u05d3 \u05d0\u05d9\u05d6\u05d4 \u05de\u05d4\u05dd \u05d4\u05d7\u05dc\u05e7 \u05e0\u05de\u05e6\u05d0."],[359.0,"\u05d4\u05ea\u05e7\u05df 14253-1 ISO \u05de\u05d2\u05d3\u05d9\u05e8 \u05db\u05dc\u05dc \u05d4\u05d7\u05dc\u05d8\u05d4: \u05db\u05d3\u05d9 \u05dc\u05d4\u05d5\u05db\u05d9\u05d7 \u05e9\u05d7\u05dc\u05e7 \u05ea\u05e7\u05d9\u05df,"],[367.0,"\u05d4\u05ea\u05d5\u05e6\u05d0\u05d4 \u05e6\u05e8\u05d9\u05db\u05d4 \u05dc\u05d4\u05d9\u05d5\u05ea \u05d1\u05ea\u05d5\u05da \u05d4\u05e1\u05d1\u05d5\u05dc\u05ea, \u05e4\u05d7\u05d5\u05ea \u05d0\u05d9 \u05d4\u05d5\u05d5\u05d3\u05d0\u05d5\u05ea."],[374.0,"\u05db\u05dc\u05d5\u05de\u05e8, \u05d0\u05d6\u05d5\u05e8 \u05d4\u05e7\u05d1\u05dc\u05d4 \u05e6\u05e8 \u05d9\u05d5\u05ea\u05e8 \u05de\u05d4\u05e1\u05d1\u05d5\u05dc\u05ea \u05e9\u05d1\u05e9\u05e8\u05d8\u05d5\u05d8."],[379.0,"\u05d1\u05d7\u05dc\u05e7 \u05de\u05d4\u05d0\u05e8\u05d2\u05d5\u05e0\u05d9\u05dd \u05db\u05dc\u05dc \u05d4\u05d4\u05d7\u05dc\u05d8\u05d4 \u05de\u05d5\u05d2\u05d3\u05e8 \u05d1\u05d7\u05d5\u05d6\u05d4 \u05d0\u05d5 \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8,"],[384.0,"\u05d5\u05d1\u05d0\u05d7\u05e8\u05d9\u05dd \u05dc\u05d0. \u05d5\u05db\u05e9\u05d4\u05d5\u05d0 \u05dc\u05d0 \u05de\u05d5\u05d2\u05d3\u05e8, \u05db\u05d3\u05d0\u05d9 \u05dc\u05e1\u05db\u05dd \u05d0\u05d5\u05ea\u05d5 \u05de\u05e8\u05d0\u05e9."],[389.0,"\u05d5\u05d2\u05dd \u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d4\u05d9\u05d0 \u05d7\u05dc\u05e7 \u05de\u05d4\u05de\u05d3\u05d9\u05d3\u05d4: \u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d7\u05dc\u05d5\u05ea \u05d1\u05e2\u05e9\u05d5\u05e8\u05d9\u05dd \u05de\u05e2\u05dc\u05d5\u05ea, \u05db\u05de\u05d5 \u05e9\u05e8\u05d0\u05d9\u05e0\u05d5 \u05d1\u05e4\u05e8\u05e7 \u05d0\u05e4\u05e1."],[398.0,"\u05e8\u05d9\u05db\u05d5\u05d6\u05d7 \u05d4\u05de\u05dc\u05db\u05d5\u05d3\u05d5\u05ea \u05d1\u05d1\u05d3\u05d9\u05e7\u05d4."],[401.0,"\u05de\u05d0\u05e4\u05d9\u05d9\u05df \u05e7\u05e8\u05d9\u05d8\u05d9 \u05e9\u05e0\u05de\u05d3\u05d3 \u05db\u05de\u05d5 \u05db\u05dc \u05de\u05d9\u05d3\u05d4 \u05d0\u05d7\u05e8\u05ea, \u05d1\u05dc\u05d9 \u05d1\u05e7\u05e8\u05d4 \u05d5\u05d1\u05dc\u05d9 \u05ea\u05d9\u05e2\u05d5\u05d3."],[407.0,"\u05d1\u05d3\u05d9\u05e7\u05ea \u05e4\u05e8\u05d9\u05d8 \u05e8\u05d0\u05e9\u05d5\u05df \u05e9\u05dc\u05d0 \u05d7\u05d5\u05d6\u05e8\u05ea \u05d0\u05d7\u05e8\u05d9 \u05e9\u05d9\u05e0\u05d5\u05d9 \u05d1\u05ea\u05d4\u05dc\u05d9\u05da."],[411.0,"\u05ea\u05d5\u05db\u05e0\u05d9\u05ea \u05de\u05d3\u05d9\u05d3\u05d4 \u05e9\u05d1\u05e0\u05d5\u05d9\u05d4 \u05de\u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05d0\u05d7\u05e8\u05d9\u05dd \u05de\u05d0\u05dc\u05d4 \u05e9\u05d1\u05e9\u05e8\u05d8\u05d5\u05d8."],[416.0,"\u05db\u05dc\u05d9 \u05e9\u05db\u05d5\u05e9\u05e8 \u05d4\u05d4\u05e4\u05e8\u05d3\u05d4 \u05e9\u05dc\u05d5 \u05e7\u05e8\u05d5\u05d1 \u05dc\u05e8\u05d5\u05d7\u05d1 \u05d4\u05e1\u05d1\u05d5\u05dc\u05ea."],[421.0,"\u05d5\u05ea\u05d5\u05e6\u05d0\u05d4 \u05de\u05de\u05e9 \u05d1\u05d2\u05d1\u05d5\u05dc, \u05e9\u05d4\u05ea\u05e7\u05d1\u05dc\u05d4 \u05d1\u05dc\u05d9 \u05dc\u05e7\u05d7\u05ea \u05d1\u05d7\u05e9\u05d1\u05d5\u05df \u05d0\u05d9 \u05d5\u05d3\u05d0\u05d5\u05ea."],[427.0,"\u05de\u05d0\u05e4\u05d9\u05d9\u05e0\u05d9\u05dd \u05e7\u05e8\u05d9\u05d8\u05d9\u05d9\u05dd \u05de\u05e1\u05d5\u05de\u05e0\u05d9\u05dd \u05d1\u05e1\u05de\u05dc \u05e9\u05de\u05d5\u05d2\u05d3\u05e8 \u05d1\u05d4\u05e2\u05e8\u05d5\u05ea, \u05d5\u05d4\u05dd \u05d3\u05d5\u05e8\u05e9\u05d9\u05dd \u05d1\u05e7\u05e8\u05d4, \u05ea\u05d9\u05e2\u05d5\u05d3 \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d1\u05d3\u05d9\u05e7\u05d4 \u05de\u05dc\u05d0\u05d4."],[435.0,"Cpk \u05de\u05d5\u05d3\u05d3 \u05d2\u05dd \u05e4\u05d9\u05d6\u05d5\u05e8 \u05d5\u05d2\u05dd \u05de\u05d9\u05e7\u05d5\u05dd, \u05d5\u05d3\u05e8\u05d9\u05e9\u05d4 \u05e0\u05e4\u05d5\u05e6\u05d4 \u05d4\u05d9\u05d0 3."],[443.0,"\u05d1\u05d3\u05d9\u05e7\u05ea \u05e4\u05e8\u05d9\u05d8 \u05e8\u05d0\u05e9\u05d5\u05df \u05dc\u05e4\u05d9 AS9102 \u05d1\u05d5\u05d3\u05e7\u05ea \u05db\u05dc \u05d3\u05e8\u05d9\u05e9\u05d4 \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d4\u05de\u05de\u05d5\u05e1\u05e4\u05e8, \u05d5\u05d7\u05d5\u05d6\u05e8\u05ea \u05d0\u05d7\u05e8\u05d9 \u05db\u05dc \u05e9\u05d9\u05e0\u05d5\u05d9 \u05de\u05d4\u05d5\u05ea\u05d9."],[454.0,"\u05d5\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05db\u05d9\u05e8 \u05d0\u05ea \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05e9\u05d0\u05d9\u05df \u05dc\u05d5 \u05d2\u05d9\u05dc\u05d9\u05d5\u05df: \u05d4\u05d2\u05d3\u05e8\u05d4 \u05de\u05d1\u05d5\u05e1\u05e1\u05ea \u05de\u05d5\u05d3\u05dc, \u05e1\u05dd\u05d5\u05d0\u05d5. \u05e0\u05ea\u05e8\u05d0\u05d4 \u05d1\u05e4\u05e8\u05e7 \u05e2\u05e9\u05e8\u05d9\u05dd."]]};
window.MH_TR["ch20"]={"t":"\u05d4\u05d2\u05d3\u05e8\u05d4 \u05de\u05d1\u05d5\u05e1\u05e1\u05ea \u05de\u05d5\u05d3\u05dc \u00b7 MBD","l":[[1.0,"\u05d1\u05db\u05dc \u05d4\u05e4\u05e8\u05e7\u05d9\u05dd \u05e2\u05d3 \u05e2\u05db\u05e9\u05d9\u05d5, \u05d4\u05d4\u05d2\u05d3\u05e8\u05d4 \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7 \u05d4\u05d9\u05d9\u05ea\u05d4 \u05d2\u05d9\u05dc\u05d9\u05d5\u05df: \u05de\u05d1\u05d8\u05d9\u05dd, \u05de\u05d9\u05d3\u05d5\u05ea \u05d5\u05d4\u05e2\u05e8\u05d5\u05ea."],[9.0,"\u05d1\u05d4\u05e8\u05d1\u05d4 \u05d0\u05e8\u05d2\u05d5\u05e0\u05d9\u05dd \u05d6\u05d4 \u05de\u05e9\u05ea\u05e0\u05d4. \u05d4\u05d4\u05d2\u05d3\u05e8\u05d4 \u05e2\u05d5\u05d1\u05e8\u05ea \u05dc\u05de\u05d5\u05d3\u05dc \u05d4\u05ea\u05dc\u05ea \u05de\u05de\u05d3\u05d9 \u05e2\u05e6\u05de\u05d5,"],[16.0,"\u05d5\u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d4\u05d3\u05d5 \u05de\u05de\u05d3\u05d9 \u05e0\u05e2\u05dc\u05dd \u05d0\u05d5 \u05d4\u05d5\u05e4\u05da \u05dc\u05de\u05e9\u05e0\u05d9."],[21.0,"\u05d6\u05d4 \u05e0\u05e7\u05e8\u05d0 \u05d4\u05d2\u05d3\u05e8\u05d4 \u05de\u05d1\u05d5\u05e1\u05e1\u05ea \u05de\u05d5\u05d3\u05dc, \u2026)."],[25.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05dc\u05de\u05d3 \u05dc\u05e7\u05e8\u05d5\u05d0 \u05de\u05d5\u05d3\u05dc \u05db\u05d6\u05d4, \u05d5\u05de\u05d4 \u05de\u05e9\u05ea\u05e0\u05d4 \u05d1\u05db\u05dc\u05dc\u05d9\u05dd \u05e9\u05dc\u05de\u05d3\u05e0\u05d5, \u05db\u05e9\u05d4\u05de\u05d5\u05d3\u05dc \u05d4\u05d5\u05d0 \u05d4\u05d7\u05d5\u05d6\u05d4."],[34.0,"\u05d1\u05de\u05d5\u05d3\u05dc \u05e1\u05e4\u05d5\u05d0, \u05db\u05dc \u05d4\u05de\u05d9\u05d3\u05e2 \u05e9\u05d4\u05d9\u05d4 \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05de\u05d5\u05e6\u05de\u05d3 \u05dc\u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05d4 \u05e2\u05e6\u05de\u05d4."],[40.0,"\u05de\u05d9\u05d3\u05d5\u05ea, \u05e1\u05d1\u05d5\u05dc\u05d5\u05ea \u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05d5\u05ea, \u05de\u05e9\u05d8\u05d7\u05d9\u05dd, \u05d7\u05e1\u05e4\u05d5\u05e1 \u05d5\u05d4\u05e2\u05e8\u05d5\u05ea \u05e0\u05e7\u05e8\u05d0\u05d9\u05dd \u05d9\u05d7\u05d3 \u05d5\u05d5\u05d0\u05e1: \u05de\u05d9\u05d3\u05e2 \u05de\u05d5\u05e6\u05e8 \u05d5\u05d9\u05d9\u05e6\u05d5\u05e8."],[51.0,"\u05d9\u05e9 \u05e9\u05e0\u05d9 \u05e1\u05d5\u05d2\u05d9\u05dd \u05e9\u05dc \u05d5\u05d5\u05d0\u05e1. \u05d4\u05e1\u05d5\u05d2 \u05d4\u05d2\u05e8\u05e4\u05d9 \u05e0\u05e8\u05d0\u05d4 \u05db\u05de\u05d5 \u05d8\u05e7\u05e1\u05d8 \u05d1\u05de\u05e1\u05da, \u05d0\u05d1\u05dc \u05d4\u05de\u05d7\u05e9\u05d1 \u05dc\u05d0 \u05d9\u05d5\u05d3\u05e2 \u05dc\u05d0\u05d9\u05d6\u05d4 \u05de\u05e9\u05d8\u05d7 \u05d4\u05d5\u05d0 \u05e9\u05d9\u05d9\u05da."],[60.0,"\u05d0\u05d9\u05d6\u05d5 \u05e1\u05d1\u05d5\u05dc\u05ea \u05d7\u05dc\u05d4 \u05e2\u05dc \u05d0\u05d9\u05d6\u05d4 \u05de\u05e9\u05d8\u05d7, \u05d1\u05d9\u05d7\u05e1 \u05dc\u05d0\u05d9\u05dc\u05d5 \u05de\u05e9\u05d8\u05d7\u05d9 \u05d9\u05d9\u05d7\u05d5\u05e1."],[71.0,"\u05e8\u05e7 \u05d5\u05d0\u05e1 \u05e1\u05de\u05e0\u05d8\u05d9 \u05de\u05d0\u05e4\u05e9\u05e8 \u05dc\u05ea\u05d5\u05db\u05e0\u05ea \u05e2\u05d9\u05d1\u05d5\u05d3 \u05d0\u05d5 \u05dc\u05de\u05db\u05d5\u05e0\u05ea \u05de\u05d3\u05d9\u05d3\u05d4 \u05dc\u05e7\u05e8\u05d5\u05d0 \u05d0\u05ea \u05d4\u05d3\u05e8\u05d9\u05e9\u05d5\u05ea \u05d0\u05d5\u05d8\u05d5\u05de\u05d8\u05d9\u05ea."],[80.0,"\u05d4\u05db\u05dc\u05dc\u05d9\u05dd \u05dc\u05de\u05d5\u05d3\u05dc \u05db\u05d6\u05d4 \u05de\u05d5\u05d2\u05d3\u05e8\u05d9\u05dd \u05d1\u05ea\u05e7\u05df ASME Y14.41, \u05d5\u05d1\u05e6\u05d3 \u05d4\u05d1\u05d9\u05e0\u05dc\u05d0\u05d5\u05de\u05d9 \u05d1\u05ea\u05e7\u05df 16792 50!."],[94.0,"\u05d4\u05e1\u05de\u05dc\u05d9\u05dd \u05e2\u05e6\u05de\u05dd \u05dc\u05d0 \u05d4\u05e9\u05ea\u05e0\u05d5: \u05d0\u05d5\u05ea\u05dd \u05e1\u05de\u05dc\u05d9 GD&T, \u05d0\u05d5\u05ea\u05df \u05de\u05e1\u05d2\u05e8\u05d5\u05ea \u05d5\u05d0\u05d5\u05ea\u05dd \u05de\u05e9\u05d8\u05d7\u05d9 \u05d9\u05d9\u05d7\u05d5\u05e1, \u05e8\u05e7 \u05d1\u05de\u05e8\u05d7\u05d1 \u05ea\u05dc\u05ea \u05de\u05de\u05d3\u05d9."],[105.0,"\u05dc\u05d4\u05e2\u05d1\u05e8\u05ea \u05de\u05d5\u05d3\u05dc \u05e2\u05dd \u05d5\u05d5\u05d0\u05e1\u05dd \u05d1\u05d9\u05df \u05de\u05e2\u05e8\u05db\u05d5\u05ea \u05e9\u05d5\u05e0\u05d5\u05ea, \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05e4\u05d5\u05e8\u05de\u05d8 AP242 5\u05dd515."],[113.0,"\u05d5\u05dc\u05ea\u05d5\u05e6\u05d0\u05d5\u05ea \u05d1\u05d3\u05d9\u05e7\u05d4 \u05d5\u05ea\u05d5\u05db\u05e0\u05d9\u05d5\u05ea \u05de\u05d3\u05d9\u05d3\u05d4, \u05e7\u05d9\u05d9\u05dd \u05e4\u05d5\u05e8\u05de\u05d8 \u05d6\u05d50,"],[118.0,"\u05e9\u05de\u05d0\u05e4\u05e9\u05e8 \u05dc\u05d7\u05d1\u05e8 \u05d1\u05d9\u05df \u05d4\u05d3\u05e8\u05d9\u05e9\u05d4 \u05d1\u05de\u05d5\u05d3\u05dc \u05dc\u05d1\u05d9\u05df \u05d4\u05ea\u05d5\u05e6\u05d0\u05d4 \u05e9\u05e0\u05de\u05d3\u05d3\u05d4."],[124.0,"\u05de\u05d5\u05d3\u05dc \u05e1\u05dd\u05d5\u05d0 \u05db\u05d5\u05dc\u05dc \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05ea\u05e6\u05d5\u05d2\u05d5\u05ea \u05e9\u05de\u05d5\u05e8\u05d5\u05ea, \u05e9\u05de\u05e7\u05d1\u05d9\u05dc\u05d5\u05ea \u05dc\u05de\u05d1\u05d8\u05d9\u05dd \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8."],[131.0,"\u05db\u05dc \u05ea\u05e6\u05d5\u05d2\u05d4 \u05de\u05e8\u05d0\u05d4 \u05db\u05d9\u05d5\u05d5\u05df \u05de\u05d1\u05d8 \u05de\u05e1\u05d5\u05d9\u05dd, \u05d5\u05e8\u05e7 \u05d0\u05ea \u05d4-\u05d5\u05d5\u05d0\u05d5\u05e1 \u05e9\u05e9\u05d9\u05d9\u05da \u05dc\u05d5, \u05db\u05d3\u05d9 \u05e9\u05dc\u05d0 \u05d4\u05db\u05d5\u05dc \u05d9\u05d5\u05e4\u05d9\u05e2 \u05e2\u05dc \u05d4\u05de\u05e1\u05da \u05d1\u05d1\u05ea \u05d0\u05d7\u05ea."],[141.0,"\u05db\u05e9\u05d1\u05d5\u05d7\u05e8\u05d9\u05dd \u05e1\u05d1\u05d5\u05dc\u05ea, \u05d4\u05de\u05e2\u05e8\u05db\u05ea \u05de\u05d3\u05d2\u05d9\u05e9\u05d4 \u05d0\u05ea \u05d4\u05de\u05e9\u05d8\u05d7 \u05e9\u05d4\u05d9\u05d0 \u05d7\u05dc\u05d4 \u05e2\u05dc\u05d9\u05d5 \u05d5\u05d0\u05ea \u05de\u05e9\u05d8\u05d7\u05d9 \u05d4\u05d9\u05d9\u05d7\u05d5\u05e1 \u05e9\u05dc\u05d4."],[148.0,"\u05d5\u05dc\u05db\u05df \u05d1\u05de\u05d5\u05d3\u05dc \u05d8\u05d5\u05d1 \u05d0\u05d9\u05df \u05e9\u05d0\u05dc\u05d4 \u05dc\u05d0\u05d9\u05d6\u05d4 \u05de\u05e9\u05d8\u05d7 \u05e9\u05d9\u05d9\u05db\u05ea \u05d4\u05e2\u05e8\u05d4, \u05db\u05de\u05d5 \u05e9\u05d9\u05e9 \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05e6\u05e4\u05d5\u05e3."],[156.0,"\u05de\u05d9 \u05e9\u05e7\u05d5\u05e8\u05d0 \u05de\u05d5\u05d3\u05dc \u05e8\u05e7 \u05d3\u05e8\u05da \u05ea\u05de\u05d5\u05e0\u05d4 \u05e9\u05dc\u05d5, \u05de\u05d0\u05d1\u05d3 \u05d0\u05ea \u05db\u05dc \u05d4\u05de\u05d9\u05d3\u05e2 \u05d4\u05d6\u05d4."],[162.0,"\u05db\u05d0\u05df \u05d9\u05e9 \u05e9\u05d9\u05e0\u05d5\u05d9 \u05de\u05d4\u05d5\u05ea\u05d9 \u05dc\u05e2\u05d5\u05de\u05ea \u05e9\u05e8\u05d8\u05d5\u05d8."],[165.0,"\u05d1\u05e4\u05e8\u05e7 \u05d0\u05e4\u05e1 \u05dc\u05de\u05d3\u05e0\u05d5 \u05e9\u05dc\u05d0 \u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05de\u05d4\u05e6\u05d9\u05d5\u05e8. \u05d1\u05de\u05d5\u05d3\u05dc \u05e1\u05dd\u05d5), \u05d4\u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05d4 \u05d4\u05d9\u05d0 \u05d4\u05d4\u05d2\u05d3\u05e8\u05d4, \u05d5\u05d4\u05d9\u05d0 \u05de\u05d3\u05d5\u05d9\u05e7\u05ea."],[175.0,"\u05de\u05d9\u05d3\u05d4 \u05e9\u05dc\u05d0 \u05db\u05ea\u05d5\u05d1\u05d4 \u05d1\u05de\u05e4\u05d5\u05e8\u05e9 \u05e0\u05dc\u05e7\u05d7\u05ea \u05de\u05d4\u05de\u05d5\u05d3\u05dc, \u05db\u05de\u05d9\u05d3\u05d4 \u05ea\u05d0\u05d5\u05e8\u05d8\u05d9\u05ea \u05de\u05d3\u05d5\u05d9\u05e7\u05ea."],[181.0,"\u05e4\u05e8\u05d5\u05e4\u05d9\u05dc \u05de\u05e9\u05d8\u05d7 \u05dc\u05db\u05dc \u05d4\u05de\u05e9\u05d8\u05d7\u05d9\u05dd, \u05d1\u05d9\u05d7\u05e1 \u05dc\u05de\u05e2\u05e8\u05db\u05ea \u05de\u05e9\u05d8\u05d7\u05d9\u05dd."],[191.0,"\u05dc\u05de\u05e9\u05dc: \u05db\u05dc \u05d4\u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05e9\u05dc\u05d0 \u05e1\u05d5\u05de\u05e0\u05d5, \u05e4\u05e8\u05d5\u05e4\u05d9\u05dc \u05e9\u05dc \u05d7\u05de\u05e9\u05d5 \u05e2\u05e9\u05d9\u05e8\u05d9\u05d5\u05ea \u05d1\u05d9\u05d7\u05e1 C-1A, B-7."],[199.0,"\u05db\u05dc\u05d5\u05de\u05e8, \u05d1\u05de\u05d5\u05d3\u05dc \u2026 \u05db\u05dc \u05de\u05e9\u05d8\u05d7 \u05de\u05d5\u05d2\u05d3\u05e8, \u05d2\u05dd \u05d0\u05dd \u05d0\u05d9\u05df \u05dc\u05d9\u05d3\u05d5 \u05de\u05e1\u05e4\u05e8."],[206.0,"\u05db\u05e9\u05d4\u05de\u05d5\u05d3\u05dc \u05d4\u05d5\u05d0 \u05d4\u05d7\u05d5\u05d6\u05d4, \u05d4\u05d2\u05e8\u05e1\u05d4 \u05e9\u05dc\u05d5 \u05d7\u05e9\u05d5\u05d1\u05d4 \u05d1\u05d3\u05d9\u05d5\u05e7 \u05db\u05de\u05d5 \u05e8\u05d5\u05d5\u05d9\u05d6\u05d9\u05d4 \u05e9\u05dc \u05e9\u05e8\u05d8\u05d5\u05d8."],[213.0,"\u05d4\u05e7\u05d5\u05d1\u05e5 \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d9\u05d5\u05ea \u05de\u05d6\u05d5\u05d4\u05d4 \u05e2\u05dd \u05de\u05e1\u05e4\u05e8 \u05d5\u05d2\u05e8\u05e1\u05d4, \u05d5\u05dc\u05e2\u05d9\u05ea\u05d9\u05dd \u05e7\u05e8\u05d5\u05d1\u05d5\u05ea \u05d2\u05dd \u05e2\u05dd \u05d1\u05d3\u05d9\u05e7\u05d4 \u05e9\u05dc \u05e9\u05dc\u05de\u05d5\u05ea \u05d4\u05e7\u05d5\u05d1\u05e5."],[221.0,"\u05d0\u05e8\u05d2\u05d5\u05e0\u05d9\u05dd \u05e8\u05d1\u05d9\u05dd \u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05e9\u05e8\u05d8\u05d5\u05d8 \u05de\u05d5\u05e7\u05d8\u05df: \u05d2\u05d9\u05dc\u05d9\u05d5\u05df \u05d3\u05d5 \u05de\u05de\u05d3\u05d9 \u05e2\u05dd \u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05d4\u05d7\u05e9\u05d5\u05d1\u05d5\u05ea, \u05d4\u05d7\u05d5\u05de\u05e8 \u05d5\u05d4\u05d4\u05e2\u05e8\u05d5\u05ea, \u05dc\u05e0\u05d5\u05d7\u05d5\u05ea \u05d1\u05e8\u05e6\u05e4\u05d4."],[231.0,"\u05d0\u05d1\u05dc \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d4\u05de\u05d5\u05e7\u05d8\u05df \u05d4\u05d5\u05d0 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05dc\u05e2\u05d9\u05d5\u05df \u05d1\u05dc\u05d1\u05d3, \u05d5\u05d4\u05de\u05d5\u05d3\u05dc \u05d4\u05d5\u05d0 \u05e9\u05e7\u05d5\u05d1\u05e2."],[237.0,"\u05d5\u05dc\u05db\u05df \u05d7\u05e9\u05d5\u05d1 \u05dc\u05d1\u05d3\u05d5\u05e7 \u05de\u05d4 \u05db\u05ea\u05d5\u05d1 \u05e2\u05dc \u05d4\u05d9\u05d7\u05e1 \u05d1\u05d9\u05e0\u05d9\u05d4\u05dd, \u05d5\u05de\u05d4 \u05d2\u05d5\u05d1\u05e8 \u05db\u05e9\u05d4\u05dd \u05e1\u05d5\u05ea\u05e8\u05d9\u05dd."],[244.0,"\u05dc\u05d0 \u05db\u05dc \u05e7\u05d5\u05d1\u05e5 \u05ea\u05dc\u05ea \u05de\u05de\u05d3\u05d9 \u05e0\u05d5\u05e9\u05d0 \u05d0\u05ea \u05d0\u05d5\u05ea\u05d5 \u05de\u05d9\u05d3\u05e2."],[248.0,"\u05e7\u05d5\u05d1\u05e5 CAD \u05de\u05e7\u05d5\u05e8\u05d9 \u05e0\u05d5\u05e9\u05d0 \u05d4\u05db\u05d5\u05dc, \u05d0\u05d1\u05dc \u05d3\u05d5\u05e8\u05e9 \u05d0\u05ea \u05d0\u05d5\u05ea\u05d4 \u05de\u05e2\u05e8\u05db\u05dc\u05ea."],[253.0,"STEP AP242 \u05e0\u05d5\u05e9\u05d0 \u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05d4 \u05de\u05d3\u05d5\u05d9\u05e7\u05ea \u05d5\u05d2\u05dd \u05d5\u05d5\u05d0\u05e1 \u05e1\u05de\u05e0\u05d8\u05d9."],[261.0,"\u05d2\u05e8\u05e1\u05d0\u05d5\u05ea \u05d9\u05e9\u05e0\u05d5\u05ea \u05e9\u05dc \u05e1516, \u05db\u05de\u05d5 AP203 \u05d0\u05d5 AP214, \u05e0\u05d5\u05e9\u05d0\u05d5\u05ea \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05e8\u05e7 \u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05d4, \u05d1\u05dc\u05d9 \u05d4\u05d3\u05e8\u05d9\u05e9\u05d5\u05ea."],[271.0,"\u05d5\u05e7\u05d1\u05e6\u05d9 \u05e8\u05e9\u05ea \u05de\u05e9\u05d5\u05dc\u05e9\u05d9\u05dd, \u05db\u05de\u05d5 |51, \u05d4\u05dd \u05e7\u05d9\u05e8\u05d5\u05d1 \u05e9\u05dc \u05d4\u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05d4, \u05d5\u05dc\u05d0 \u05d4\u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05d4 \u05e2\u05e6\u05de\u05d4."],[279.0,"\u05de\u05d9 \u05e9\u05de\u05e7\u05d1\u05dc \u05de\u05d5\u05d3\u05dc \u05d1\u05e4\u05d5\u05e8\u05de\u05d8 \u05e9\u05dc\u05d0 \u05e0\u05d5\u05e9\u05d0 \u05d5\u05d5\u05d0\u05e1, \u05de\u05e7\u05d1\u05dc \u05e6\u05d5\u05e8\u05d4 \u05d1\u05dc\u05d9 \u05e1\u05d1\u05d5\u05dc\u05d5\u05ea, \u05d5\u05d6\u05d4 \u05dc\u05d0 \u05de\u05e1\u05e4\u05d9\u05e7 \u05dc\u05d9\u05d9\u05e6\u05d5\u05e8."],[288.0,"\u05d4\u05d9\u05ea\u05e8\u05d5\u05df \u05d4\u05d2\u05d3\u05d5\u05dc \u05e9\u05dc \u05e1\u05e4\u05d5\u05d0 \u05d4\u05d5\u05d0 \u05e9\u05d0\u05e4\u05e9\u05e8 \u05dc\u05d4\u05e9\u05ea\u05de\u05e2\u05e9\u05d5 \u05d1\u05d0\u05d5\u05ea\u05d5 \u05de\u05d5\u05d3\u05dc \u05dc\u05d0\u05d5\u05e8\u05da \u05db\u05dc \u05d4\u05d3\u05e8\u05da."],[294.0,"\u05ea\u05d5\u05db\u05e0\u05ea \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d1\u05d5\u05e0\u05d4 \u05de\u05e1\u05dc\u05d5\u05dc\u05d9\u05dd \u05d9\u05e9\u05d9\u05e8\u05d5\u05ea \u05de\u05d4\u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05d4."],[298.0,"\u05de\u05db\u05d5\u05e0\u05ea \u05d4\u05de\u05d3\u05d9\u05d3\u05d4 \u05d9\u05db\u05d5\u05dc\u05d4 \u05dc\u05e7\u05e8\u05d5\u05d0 \u05d0\u05ea PMI-A \u05d4\u05e1\u05de\u05e0\u05d8\u05d9 \u05d5\u05dc\u05d1\u05e0\u05d5\u05ea \u05de\u05de\u05e0\u05d5 \u05ea\u05d5\u05db\u05e0\u05d9\u05ea \u05de\u05d3\u05d9\u05d3\u05d4."],[305.0,"\u05d5\u05d1\u05d3\u05d9\u05e7\u05ea \u05e4\u05e8\u05d9\u05d8 \u05e8\u05d0\u05e9\u05d5\u05df \u05d9\u05db\u05d5\u05dc\u05d4 \u05dc\u05d4\u05d9\u05d1\u05e0\u05d5\u05ea \u05d9\u05e9\u05d9\u05e8\u05d5\u05ea \u05de\u05e8\u05e9\u05d9\u05de\u05ea \u05d4\u05d3\u05e8\u05d9\u05e9\u05d5\u05ea \u05d1\u05de\u05d5\u05d3\u05dc, \u05d1\u05de\u05e7\u05d5\u05dd \u05de\u05de\u05e1\u05e4\u05d5\u05e8 \u05d9\u05d3\u05e0\u05d9 \u05e9\u05dc \u05e9\u05e8\u05d8\u05d5\u05d8."],[313.0,"\u05d0\u05d1\u05dc \u05d6\u05d4 \u05d3\u05d5\u05e8\u05e9 \u05e9\u05d1\u05db\u05dc \u05de\u05e7\u05d5\u05dd \u05d9\u05d4\u05d9\u05d4 \u05db\u05dc\u05d9 \u05e9\u05de\u05e1\u05d5\u05d2\u05dc \u05dc\u05d4\u05e6\u05d9\u05d2 \u05d0\u05ea \u05d4\u05de\u05d5\u05d3\u05dc \u05d5\u05d0\u05ea \u05d4-\u05d5\u05d5\u05d0\u05e1 \u05e9\u05dc\u05d5."],[321.0,"\u05e2\u05d5\u05d1\u05d3 \u05e9\u05d9\u05e9 \u05dc\u05d5 \u05e8\u05e7 \u05ea\u05de\u05d5\u05e0\u05d4 \u05d0\u05d5 \u05e9\u05e8\u05d8\u05d5\u05d8 \u05de\u05d5\u05e7\u05d8\u05df, \u05dc\u05d0 \u05e8\u05d5\u05d0\u05d4 \u05d7\u05dc\u05e7 \u05de\u05d4\u05d3\u05e8\u05d9\u05e9\u05d5\u05ea."],[327.0,"\u05e8\u05d9\u05db\u05d5\u05d6 \u05d4\u05de\u05dc\u05db\u05d5\u05d3\u05d5\u05ea \u05d1\u05de\u05d5\u05d3\u05dc \u05e1\u05dd\u05d5)."],[330.0,"\u05de\u05d3\u05d9\u05d3\u05d4 \u05de\u05d4\u05de\u05d5\u05d3\u05dc \u05e9\u05dc \u05de\u05e9\u05d8\u05d7 \u05e9\u05d4\u05e1\u05d1\u05d5\u05dc\u05ea \u05e9\u05dc\u05d5 \u05de\u05d5\u05d2\u05d3\u05e8\u05ea \u05d1\u05de\u05e7\u05d5\u05dd \u05d0\u05d7\u05e8, \u05d1\u05dc\u05d9 \u05dc\u05d1\u05d3\u05d5\u05e7 \u05d0\u05ea \u05d4\u05d4\u05e2\u05e8\u05d4 \u05d4\u05db\u05dc\u05dc\u05d9\u05ea."],[339.0,"\u05e2\u05d1\u05d5\u05d3\u05d4 \u05dc\u05e4\u05d9 \u05d2\u05e8\u05e1\u05d4 \u05d9\u05e9\u05e0\u05d4 \u05e9\u05dc \u05d4\u05de\u05d5\u05d3\u05dc, \u05db\u05d9 \u05d4\u05e7\u05d5\u05d1\u05e5 \u05e0\u05e9\u05de\u05e8 \u05d1\u05de\u05d7\u05e9\u05d1 \u05de\u05e7\u05d5\u05de\u05d9."],[345.0,"\u05e9\u05de\u05d9\u05e8\u05d4 \u05d1\u05e4\u05d5\u05e8\u05de\u05d8 \u05e9\u05dc\u05d0 \u05e0\u05d5\u05e9\u05d0 \u05d5\u05d0\u05e1, \u05d5\u05d0\u05d5\u05d1\u05d3\u05df \u05db\u05dc \u05d4\u05e1\u05d1\u05d5\u05dc\u05d5\u05ea."],[350.0,"\u05e9\u05e8\u05d8\u05d5\u05d8 \u05de\u05d5\u05e7\u05d8\u05df \u05e9\u05dc\u05d0 \u05e2\u05d5\u05d3\u05db\u05df \u05d0\u05d7\u05e8\u05d9 \u05e9\u05d9\u05e0\u05d5\u05d9 \u05d1\u05de\u05d5\u05d3\u05dc."],[354.0,"\u05d5\u05d9\u05d7\u05d9\u05d3\u05d5\u05ea: \u05de\u05d5\u05d3\u05dc \u05e9\u05e0\u05d1\u05e0\u05d4 \u05d1\u05d0\u05d9\u05e0\u05e6'\u05d9\u05dd \u05d5\u05e0\u05e4\u05ea\u05d7 \u05db\u05d0\u05d9\u05dc\u05d5 \u05d4\u05d9\u05d4 \u05d1\u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8\u05d9\u05dd."],[361.0,"\u05de\u05ea\u05d7\u05d9\u05dc\u05d9\u05dd \u05de\u05d6\u05d9\u05d4\u05d5\u05d9 \u05d4\u05de\u05d5\u05d3\u05dc: \u05de\u05e1\u05e4\u05e8, \u05d2\u05e8\u05e1\u05d4, \u05d5\u05de\u05d4 \u05d4\u05de\u05e2\u05de\u05d3 \u05e9\u05dc \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d4\u05de\u05d5\u05e7\u05d8\u05df."],[368.0,"\u05d0\u05d7\u05e8 \u05db\u05da \u05d4\u05d4\u05e2\u05e8\u05d5\u05ea \u05d4\u05db\u05dc\u05dc\u05d9\u05d5\u05ea: \u05d9\u05d7\u05d9\u05d3\u05d5\u05ea, \u05ea\u05e7\u05df, \u05d5\u05e1\u05d1\u05d5\u05dc\u05ea \u05d4\u05e4\u05e8\u05d5\u05e4\u05d9\u05dc \u05d4\u05db\u05dc\u05dc\u05d9\u05ea."],[376.0,"\u05d0\u05d7\u05e8 \u05db\u05da \u05d4\u05ea\u05e6\u05d5\u05d2\u05d5\u05ea \u05d4\u05e9\u05de\u05d5\u05e8\u05d5\u05ea, \u05d0\u05d7\u05ea \u05d0\u05d7\u05ea, \u05e2\u05dd \u05d4-\u05d5\u05d5\u05d0\u05e1\u05dd \u05e9\u05dc \u05db\u05dc \u05d0\u05d7\u05ea."],[382.0,"\u05d5\u05e8\u05e7 \u05d0\u05d7\u05e8 \u05db\u05da \u05e9\u05d0\u05d9\u05dc\u05ea\u05d5\u05ea \u05e2\u05dc \u05d4\u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05d4, \u05dc\u05de\u05d9\u05d3\u05d5\u05ea \u05e9\u05dc\u05d0 \u05db\u05ea\u05d5\u05d1\u05d5\u05ea \u05d1\u05de\u05e4\u05d5\u05e8\u05e9\u05e9."],[388.0,"\u05de\u05d9 \u05e9\u05de\u05ea\u05d7\u05d9\u05dc \u05de\u05de\u05d3\u05d9\u05d3\u05d4 \u05e9\u05dc \u05d4\u05de\u05d5\u05d3\u05dc, \u05d1\u05dc\u05d9 \u05dc\u05e7\u05e8\u05d5\u05d0 \u05d0\u05ea \u05d4\u05d4\u05e2\u05e8\u05d5\u05ea, \u05dc\u05d0 \u05d9\u05d5\u05d3\u05e2 \u05d0\u05d9\u05d6\u05d5 \u05e1\u05d1\u05d5\u05dc\u05ea \u05d7\u05dc\u05d4 \u05e2\u05dc \u05de\u05d4 \u05e9\u05de\u05d3\u05d3."],[397.0,"\u05d1-\u05e1\u05e4\u05d5\u05d0, \u05d4\u05de\u05d5\u05d3\u05dc \u05d4\u05ea\u05dc\u05ea \u05de\u05de\u05d3\u05d9 \u05d4\u05d5\u05d0 \u05d4\u05d4\u05d2\u05d3\u05e8\u05d4, \u05d5\u05d4-\u05d5\u05d5\u05d0\u05d5\u05e1 \u05de\u05d7\u05d5\u05d1\u05e8 \u05dc\u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05d4."],[404.0,"\u05d5\u05d5\u05d0\u05dd \u05e1\u05de\u05e0\u05d8\u05d9 \u05de\u05d0\u05e4\u05e9\u05e8 \u05dc\u05ea\u05d5\u05db\u05e0\u05d5\u05ea \u05dc\u05e7\u05e8\u05d5\u05d0 \u05d0\u05ea \u05d4\u05d3\u05e8\u05d9\u05e9\u05d5\u05ea, \u05d5- STEP AP242 \u05de\u05e2\u05d1\u05d9\u05e8 \u05d0\u05d5\u05ea\u05d5 \u05d1\u05d9\u05df \u05de\u05e2\u05e8\u05db\u05d5\u05ea."],[414.0,"\u05de\u05d9\u05d3\u05d5\u05ea \u05e9\u05dc\u05d0 \u05db\u05ea\u05d5\u05d1\u05d5\u05ea \u05e0\u05dc\u05e7\u05d7\u05d5\u05ea \u05de\u05d4\u05de\u05d5\u05d3\u05dc, \u05d5\u05d4\u05e1\u05d1\u05d5\u05dc\u05ea \u05e9\u05dc\u05d4\u05df \u05de\u05d2\u05d9\u05e2\u05d4 \u05de\u05d4\u05e2\u05e8\u05d4 \u05db\u05dc\u05dc\u05d9\u05ea."],[421.0,"\u05d5\u05d2\u05e8\u05e1\u05ea \u05d4\u05de\u05d5\u05d3\u05dc \u05d7\u05e9\u05d5\u05d1\u05d4 \u05dc\u05db\u05de\u05d5 \u05e8\u05d5\u05d5\u05d9\u05d6\u05d9\u05d4, \u05d5\u05d4\u05de\u05d5\u05d3\u05dc \u05d2\u05d5\u05d1\u05e8 \u05e2\u05dc \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d4\u05de\u05d5\u05e7\u05d8\u05df."],[428.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05e2\u05e1\u05d5\u05e7 \u05d1\u05e0\u05d9\u05d4\u05d5\u05dc \u05e9\u05d9\u05e0\u05d5\u05d9\u05d9\u05dd: \u05e8\u05d5\u05d5\u05d9\u05d6\u05d9\u05d5\u05ea, \u05d4\u05d5\u05e8\u05d0\u05d5\u05ea \u05e9\u05d9\u05e0\u05d5\u05d9, \u05d5\u05d7\u05e8\u05d9\u05d2\u05d5\u05ea."],[434.0,"\u05e0\u05ea\u05e8\u05d0\u05d4 \u05d1\u05e4\u05e8\u05e7 \u05e2\u05e9\u05e8\u05d9\u05dd \u05d5\u05d0\u05d7\u05ea."]]};
window.MH_TR["ch21"]={"t":"\u05e0\u05d9\u05d4\u05d5\u05dc \u05e9\u05d9\u05e0\u05d5\u05d9\u05d9\u05dd","l":[[1.0,"\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d4\u05d5\u05d0 \u05dc\u05d0 \u05de\u05e1\u05de\u05da \u05e7\u05d1\u05d5\u05e2. \u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05e9\u05d5\u05ea\u05e4\u05e8\u05d9\u05dd, \u05d8\u05e2\u05d5\u05d9\u05d5\u05ea \u05de\u05ea\u05d2\u05dc\u05d5\u05ea, \u05d5\u05d3\u05e8\u05d9\u05e9\u05d5\u05ea \u05de\u05e9\u05ea\u05e0\u05d5\u05ea."],[8.0,"\u05d5\u05d1\u05db\u05dc \u05e9\u05d9\u05e0\u05d5\u05d9, \u05d4\u05e9\u05d0\u05dc\u05d4 \u05d4\u05d7\u05e9\u05d5\u05d1\u05d4 \u05d4\u05d9\u05d0 \u05dc\u05d0 \u05e8\u05e7 \u05de\u05d4 \u05d4\u05e9\u05ea\u05e0\u05d4, \u05d0\u05dc\u05d0 \u05d4\u05d0\u05dd \u05db\u05d5\u05dc\u05dd \u05e2\u05d5\u05d1\u05d3\u05d9\u05dd \u05dc\u05e4\u05d9 \u05d0\u05d5\u05ea\u05d4 \u05d4\u05d2\u05d3\u05e8\u05d4."],[16.0,"\u05e0\u05d9\u05d4\u05d5\u05dc \u05e9\u05d9\u05e0\u05d5\u05d9\u05d9\u05dd \u05d4\u05d5\u05d0 \u05d4\u05de\u05e2\u05e8\u05db\u05ea \u05e9\u05de\u05d1\u05d8\u05d9\u05d7\u05d4 \u05d0\u05ea \u05d6\u05d4: \u05de\u05d9 \u05de\u05d1\u05e7\u05e9\u05d5,"],[22.0,"\u05de\u05d9\u05de\u05d0\u05e9\u05e8, \u05de\u05de\u05ea\u05d9 \u05d4\u05e9\u05d9\u05e0\u05d5\u05d9 \u05d7\u05dc, \u05d5\u05de\u05d4 \u05e2\u05d5\u05e9\u05d9\u05dd \u05e2\u05dd \u05de\u05d4 \u05e9\u05db\u05d1\u05e8 \u05d9\u05d5\u05e6\u05e8."],[27.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05dc\u05de\u05d3 \u05dc\u05e7\u05e8\u05d5\u05d0 \u05e9\u05e8\u05d8\u05d5\u05d8 \u05e9\u05d4\u05e9\u05ea\u05e0\u05d4, \u05d5\u05dc\u05d4\u05d1\u05d7\u05d9\u05df \u05d1\u05d9\u05df \u05e8\u05d5\u05d5\u05d9\u05d6\u05d9\u05d4, \u05d7\u05e8\u05d9\u05d2\u05d4 \u05d5\u05d5\u05d9\u05ea\u05d5\u05e8."],[36.0,"\u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05e9\u05d4\u05e9\u05ea\u05e0\u05d4 \u05de\u05d5\u05e4\u05d9\u05e2\u05d4 \u05d8\u05d1\u05dc\u05ea \u05e8\u05d5\u05d5\u05d9\u05d6\u05d9\u05d5\u05ea, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05e4\u05d9\u05e0\u05d4 \u05d4\u05e2\u05dc\u05d9\u05d5\u05e0\u05d4."],[42.0,"\u05dc\u05db\u05dc \u05e9\u05d5\u05e8\u05d4 \u05d9\u05e9 \u05d0\u05d5\u05ea \u05d0\u05d5 \u05de\u05e1\u05e4\u05e8 \u05e9\u05dc \u05e8\u05d5\u05d5\u05d9\u05d6\u05d9\u05d4, \u05ea\u05d9\u05d0\u05d5\u05e8 \u05e7\u05e6\u05e8 \u05e9\u05dc \u05d4\u05e9\u05d9\u05e0\u05d5\u05d9, \u05ea\u05d0\u05e8\u05d9\u05da, \u05d5\u05de\u05d9 \u05d0\u05d9\u05e9\u05e8."],[50.0,"\u05d4\u05db\u05dc\u05dc\u05d9\u05dd \u05dc\u05db\u05da \u05de\u05d5\u05d2\u05d3\u05e8\u05d9\u05dd \u05d1\u05ea\u05e7\u05df 14.35\" ASME"],[58.0,"\u05de\u05e9\u05d5\u05dc\u05e9 \u05e7\u05d8\u05df \u05e2\u05dd \u05d0\u05d5\u05ea \u05d4\u05e8\u05d5\u05d5\u05d9\u05d6\u05d9\u05d4, \u05db\u05d3\u05d9 \u05e9\u05d9\u05d4\u05d9\u05d4 \u05e7\u05dc \u05dc\u05de\u05e6\u05d5\u05d0 \u05d0\u05d5\u05ea\u05d5."],[67.0,"\u05d1\u05de\u05e4\u05d4. \u05d1\u05d8\u05d1\u05dc\u05ea \u05d4\u05e8\u05d5\u05d5\u05d9\u05d6\u05d9\u05d5\u05ea \u05db\u05ea\u05d5\u05d1 \u05d1\u05d0\u05d9\u05d6\u05d4 \u05d0\u05d6\u05d5\u05e8 \u05d4\u05e9\u05ea\u05e0\u05d4 \u05db\u05dc \u05d3\u05d1\u05e8."],[77.0,"\u05de\u05d9 \u05e9\u05e7\u05d5\u05e8\u05d0 \u05e8\u05e7 \u05d0\u05ea \u05d4\u05e8\u05d5\u05d5\u05d9\u05d6\u05d9\u05d4 \u05d4\u05d0\u05d7\u05e8\u05d5\u05e0\u05d4 \u05d1\u05d8\u05d1\u05dc\u05d4, \u05d5\u05dc\u05d0 \u05de\u05d7\u05e4\u05e2\u05d5 \u05d0\u05ea \u05d4\u05e1\u05d9\u05de\u05e0\u05d9\u05dd \u05d1\u05e6\u05d9\u05d5\u05e8, \u05e2\u05dc\u05d5\u05dc \u05dc\u05e4\u05e1\u05e4\u05e1 \u05e9\u05d9\u05e0\u05d5\u05d9 \u05e9\u05e0\u05e8\u05d0\u05d4 \u05e7\u05d8\u05df."],[87.0,"\u05dc\u05d0 \u05db\u05dc \u05e9\u05d9\u05e0\u05d5\u05d9 \u05de\u05e7\u05d1\u05dc \u05e8\u05d5\u05d5\u05d9\u05d6\u05d9\u05d4 \u05d7\u05d3\u05e9\u05d4. \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d4\u05d5\u05d0 \u05de\u05e7\u05d1\u05dc \u05de\u05e7\"\u05d8 \u05d7\u05d3\u05e9\u05d5."],[93.0,"\u05d4\u05db\u05dc\u05dc \u05d4\u05d5\u05d0 \u05d4\u05d7\u05dc\u05e4\u05d4 \u05d4\u05d3\u05d3\u05d9\u05ea: \u05d4\u05d0\u05dd \u05d7\u05dc\u05e7 \u05d9\u05e9\u05df \u05d5\u05d7\u05dc\u05e7 \u05d7\u05d3\u05e2\u05d5 \u05d9\u05db\u05d5\u05dc\u05d9\u05dd \u05dc\u05d4\u05d7\u05dc\u05d9\u05e3 \u05d6\u05d4 \u05d0\u05ea \u05d6\u05d4 \u05d1\u05db\u05dc \u05de\u05e7\u05d5\u05dd?"],[102.0,"\u05d0\u05dd \u05d4\u05e9\u05d9\u05e0\u05d5\u05d9 \u05dc\u05d0 \u05de\u05e9\u05e0\u05d4 \u05e6\u05d5\u05e8\u05d4, \u05d4\u05ea\u05d0\u05de\u05d4 \u05d0\u05d5 \u05e4\u05d5\u05e0\u05e7\u05e6\u05d9\u05d4, \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05ea\u05d7\u05dc\u05e4\u05d9\u05dd, \u05d5\u05de\u05e1\u05e4\u05d9\u05e7\u05d4 \u05e8\u05d5\u05d5\u05d9\u05d6\u05d9\u05d4."],[109.0,"\u05d0\u05dd \u05d4\u05e9\u05d9\u05e0\u05d5\u05d9 \u05de\u05e9\u05e0\u05d4 \u05d0\u05d7\u05d3 \u05de\u05d4\u05dd, \u05dc\u05de\u05e9\u05dc \u05e7\u05d3\u05d7 \u05e9\u05d6\u05d6 \u05d5\u05dc\u05d0 \u05d9\u05ea\u05d0\u05d9\u05dd \u05dc\u05d4\u05e8\u05db\u05d1\u05d4 \u05d9\u05e9\u05e0\u05d4, \u05d4\u05d7\u05dc\u05e7 \u05d4\u05d7\u05d3\u05e9\u05d5 \u05de\u05e7\u05d1\u05dc \u05de\u05e7\"\u05d8 \u05d7\u05d3\u05e9\u05d5."],[120.0,"\u05d0\u05d7\u05e8\u05ea, \u05d1\u05de\u05d7\u05e1\u05df \u05d9\u05e2\u05de\u05d3\u05d5 \u05e9\u05e0\u05d9 \u05d7\u05dc\u05e7\u05d9\u05dd \u05e9\u05d5\u05e0\u05d9\u05dd \u05e2\u05dd \u05d0\u05d5\u05ea\u05d5 \u05de\u05e1\u05e4\u05e8, \u05d5\u05de\u05d9\u05e9\u05d4\u05d5 \u05d9\u05e8\u05db\u05d9\u05d1 \u05d0\u05ea \u05d4\u05dc\u05d0 \u05e0\u05db\u05d5\u05df."],[128.0,"\u05e9\u05d9\u05e0\u05d5\u05d9 \u05de\u05ea\u05d7\u05d9\u05dc \u05d1\u05d1\u05e7\u05e9\u05d4 \u05dc\u05e9\u05d9\u05e0\u05d5\u05d9 \u05d4\u05e0\u05d3\u05e1\u05d9, \u05d7\u05e1\u05dd, \u05e9\u05de\u05e1\u05d1\u05d9\u05e8\u05d4 \u05de\u05d4 \u05d4\u05d1\u05e2\u05d9\u05d4 \u05d5\u05de\u05d4 \u05d4\u05d4\u05e6\u05e2\u05d4."],[135.0,"\u05d0\u05d7\u05e8\u05d9 \u05d0\u05d9\u05e9\u05d5\u05e8, \u05d9\u05d5\u05e6\u05d0\u05ea \u05d4\u05d5\u05e8\u05d0\u05ea \u05e9\u05d9\u05e0\u05d5\u05d9 \u05d4\u05e0\u05d3\u05e1\u05d9, 00], \u05e9\u05de\u05d2\u05d3\u05d9\u05e8\u05d4 \u05d1\u05d3\u05d9\u05d5\u05e7 \u05de\u05d4 \u05de\u05e9\u05ea\u05e0\u05d4 \u05d5\u05d1\u05d0\u05d9\u05dc\u05d5 \u05de\u05e1\u05de\u05db\u05d9\u05dd."],[144.0,"\u05d4\u05d4\u05d5\u05e8\u05d0\u05d4 \u05de\u05d2\u05d3\u05d9\u05e8\u05d4 \u05d2\u05dd \u05ea\u05d7\u05d5\u05dc\u05d4: \u05de\u05de\u05ea\u05d9 \u05d4\u05e9\u05d9\u05e0\u05d5\u05d9 \u05d7\u05dc. \u05dc\u05de\u05e9\u05dc \u05de\u05de\u05e1\u05e4\u05e8 \u05e1\u05d9\u05d3\u05d5\u05e8\u05d9 \u05de\u05e1\u05d5\u05d9\u05dd, \u05de\u05ea\u05d0\u05e8\u05d9\u05da, \u05d0\u05d5 \u05de\u05e1\u05d3\u05e8\u05ea \u05d9\u05d9\u05e6\u05d5\u05e8."],[155.0,"\u05d5\u05d4\u05d9\u05d0 \u05de\u05d2\u05d3\u05d9\u05e8\u05d4 \u05de\u05d4 \u05e2\u05d5\u05e9\u05d9\u05dd \u05e2\u05dd \u05de\u05d4 \u05e9\u05db\u05d1\u05e8 \u05e7\u05d9\u05d9\u05dd: \u05d7\u05dc\u05e7\u05d9\u05dd \u05d1\u05de\u05dc\u05d0\u05d9, \u05d7\u05dc\u05e7\u05d9\u05dd \u05d1\u05d9\u05d9\u05e6\u05d5\u05e8, \u05d5\u05d7\u05dc\u05e7\u05d9\u05dd \u05d0\u05e6\u05dc \u05d4\u05dc\u05e7\u05d5\u05d7."],[164.0,"\u05d4\u05d0\u05e4\u05e9\u05e8\u05d5\u05d9\u05d5\u05ea \u05d4\u05df \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc: \u05dc\u05d4\u05e9\u05ea\u05de\u05e9 \u05db\u05e4\u05d9 \u05e9\u05d4\u05dd, \u05dc\u05e2\u05d1\u05d3 \u05de\u05d7\u05d3\u05e9, \u05d0\u05d5 \u05dc\u05d2\u05e8\u05d5\u05d8."],[171.0,"\u05de\u05d9 \u05e9\u05de\u05e7\u05d1\u05dc \u05e9\u05e8\u05d8\u05d5\u05d8 \u05d1\u05e8\u05d5\u05d5\u05d9\u05d6\u05d9\u05d4 \u05d7\u05d3\u05e9\u05d4 \u05d1\u05dc\u05d9 \u05dc\u05d1\u05d3\u05d5\u05e7 \u05d0\u05ea \u05d4\u05ea\u05d7\u05d5\u05dc\u05d4,"],[176.0,"\u05e2\u05dc\u05d5\u05dc \u05dc\u05e2\u05e6\u05d5\u05e8 \u05d9\u05d9\u05e6\u05d5\u05e8 \u05e9\u05e2\u05d5\u05d3 \u05de\u05d5\u05ea\u05e8, \u05d0\u05d5 \u05dc\u05d4\u05de\u05e9\u05d9\u05da \u05d9\u05d9\u05e6\u05d5\u05e8 \u05e9\u05db\u05d1\u05e8 \u05d0\u05e1\u05d5\u05e8."],[182.0,"\u05d9\u05e9 \u05de\u05e6\u05d1\u05d9\u05dd \u05e9\u05d1\u05d4\u05dd \u05dc\u05d0 \u05de\u05e9\u05e0\u05d9\u05dd \u05d0\u05ea \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8, \u05d0\u05d1\u05dc \u05d1\u05db\u05dc \u05d6\u05d0\u05ea \u05dc\u05d0 \u05e2\u05d5\u05de\u05d3\u05d9\u05dd \u05d1\u05d5."],[188.0,"\u05d7\u05e8\u05d9\u05d2\u05d4 \u05d4\u05d9\u05d0 \u05d0\u05d9\u05e9\u05d5\u05e8 \u05de\u05e8\u05d0\u05e9 \u05dc\u05d9\u05d9\u05e6\u05e8 \u05d0\u05d7\u05e8\u05ea \u05de\u05d4\u05e9\u05d5\u05e8\u05d8\u05d5\u05d8, \u05dc\u05db\u05de\u05d5\u05ea \u05de\u05d5\u05d2\u05d1\u05dc\u05ea \u05d0\u05d5 \u05dc\u05d6\u05de\u05df \u05de\u05d5\u05d2\u05d1\u05dc."],[195.0,"\u05dc\u05de\u05e9\u05dc, \u05d7\u05d5\u05de\u05e8 \u05d0\u05d7\u05e8 \u05db\u05d9 \u05d4\u05d7\u05d5\u05de\u05e8 \u05e9\u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05dc\u05d0 \u05d6\u05de\u05d9\u05df, \u05dc\u05de\u05d0\u05d4 \u05d7\u05dc\u05e7\u05d9\u05dd \u05d1\u05dc\u05d1\u05d3."],[202.0,"\u05d5\u05d9\u05ea\u05d5\u05e8 \u05d4\u05d5\u05d0 \u05d0\u05d9\u05e9\u05d5\u05e8 \u05d1\u05d3\u05d9\u05e2\u05d1\u05d3 \u05dc\u05e7\u05d1\u05dc \u05d7\u05dc\u05e7 \u05e9\u05db\u05d1\u05e8 \u05d9\u05d5\u05e6\u05e8, \u05d5\u05dc\u05d0 \u05e2\u05d5\u05de\u05d3 \u05d1\u05d3\u05e8\u05d9\u05e9\u05d4."],[208.0,"\u05d1\u05ea\u05e7\u05e0\u05d9\u05dd \u05de\u05e1\u05d5\u05d9\u05de\u05d9\u05dd \u05d4\u05d5\u05d0 \u05e0\u05e7\u05e8\u05d0 \u05d2\u05dd \u05d4\u05d9\u05ea\u05e8."],[212.0,"\u05d1\u05e9\u05e0\u05d9 \u05d4\u05de\u05e7\u05e8\u05d9\u05dd, \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05dc\u05d0 \u05de\u05e9\u05ea\u05e0\u05d4. \u05d4\u05d0\u05d9\u05e9\u05d5\u05e8 \u05d7\u05dc \u05e8\u05e7 \u05e2\u05dc \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05d0\u05d5 \u05e2\u05dc \u05d4\u05ea\u05e7\u05d5\u05e4\u05d4 \u05e9\u05d4\u05d5\u05d2\u05d3\u05e8\u05d5 \u05d1\u05d5."],[220.0,"\u05de\u05d9 \u05e9\u05de\u05de\u05e9\u05d9\u05da \u05dc\u05d9\u05d9\u05e6\u05e8 \u05dc\u05e4\u05d9 \u05d7\u05e8\u05d9\u05d2\u05d4 \u05d0\u05d7\u05e8\u05d9 \u05e9\u05d4\u05db\u05de\u05d5\u05ea \u05e0\u05d2\u05de\u05e8\u05d4, \u05de\u05d9\u05d9\u05e6\u05e8 \u05d7\u05dc\u05e7\u05d9\u05dd \u05dc\u05d0 \u05ea\u05e7\u05d9\u05e0\u05d9\u05dd."],[227.0,"\u05db\u05e9\u05d7\u05dc\u05e7 \u05dc\u05d0 \u05e2\u05d5\u05de\u05d3 \u05d1\u05d3\u05e8\u05d9\u05e9\u05d4, \u05d5\u05e2\u05d3\u05ea \u05d7\u05d5\u05de\u05e8 \u05e4\u05d2\u05d5\u05dd \u05de\u05d7\u05dc\u05d9\u05d8\u05d4 \u05de\u05d4 \u05dc\u05e2\u05e9\u05d5\u05ea \u05d1\u05d5."],[233.0,"\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d7\u05d5\u05d6\u05e8 \u05de\u05d1\u05d9\u05d0 \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05dc\u05d4\u05ea\u05d0\u05de\u05d4 \u05de\u05dc\u05d0\u05d4 \u05dc\u05e9\u05e8\u05d8\u05d5\u05d8. \u05d0\u05d7\u05e8\u05d9 \u05e2\u05d9\u05d1\u05d5\u05d3 \u05d7\u05d5\u05d6\u05e8, \u05d4\u05d7\u05dc\u05e7 \u05ea\u05e7\u05d9\u05df."],[241.0,"\u05ea\u05d9\u05e7\u05d5\u05df \u05de\u05e9\u05d0\u05d9\u05e8 \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05e9\u05d5\u05e0\u05d4 \u05de\u05d4\u05e9\u05e8\u05d8\u05d5\u05d8, \u05d0\u05d1\u05dc \u05e9\u05de\u05d9\u05e9."],[246.0,"\u05d5\u05dc\u05db\u05df \u05ea\u05d9\u05e7\u05d5\u05df \u05d3\u05d5\u05e8\u05e9 \u05d0\u05d9\u05e9\u05d5\u05e8 \u05d4\u05e0\u05d3\u05e1\u05d9, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d2\u05dd \u05d0\u05d9\u05e9\u05d5\u05e8 \u05e9\u05dc \u05d4\u05dc\u05e7\u05d5\u05d7."],[252.0,"\u05de\u05d9 \u05e9\u05e7\u05d5\u05e8\u05d0 \u05dc\u05ea\u05d9\u05e7\u05d5\u05df \u05e2\u05d9\u05d1\u05d5\u05d3 \u05d7\u05d5\u05d6\u05e8, \u05de\u05e1\u05ea\u05d9\u05e8 \u05e9\u05d4\u05d7\u05dc\u05e7 \u05dc\u05d0 \u05e2\u05d5\u05de\u05d3 \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8."],[259.0,"\u05d1\u05e2\u05d1\u05d5\u05d3\u05d4 \u05de\u05d5\u05dc \u05dc\u05e7\u05d5\u05d7, \u05d9\u05e9 \u05e9\u05d9\u05e0\u05d5\u05d9\u05d9\u05dd \u05e9\u05d4\u05dc\u05e7\u05d5\u05d7 \u05d7\u05d9\u05d9\u05d1 \u05dc\u05d0\u05e9\u05e8."],[264.0,"\u05e9\u05d9\u05e0\u05d5\u05d9 \u05e9\u05de\u05e9\u05e4\u05d9\u05e2 \u05e2\u05dc \u05e6\u05d5\u05e8\u05d4, \u05d4\u05ea\u05d0\u05de\u05d4, \u05e4\u05d5\u05e0\u05e7\u05e6\u05d9\u05d4, \u05d1\u05d8\u05d9\u05d7\u05d5\u05ea \u05d0\u05d5 \u05e2\u05dc\u05d5\u05ea \u05e0\u05d7\u05e9\u05d1 \u05e9\u05d9\u05e0\u05d5\u05d9 \u05de\u05e1\u05d5\u05d2 \u05e8\u05d0\u05e9\u05d5\u05df, \u05d5\u05e6\u05e8\u05d9\u05da \u05d0\u05d9\u05e9\u05d5\u05e8 \u05dc\u05e7\u05d5\u05d7."],[273.0,"\u05e9\u05d9\u05e0\u05d5\u05d9 \u05e7\u05d8\u05df, \u05db\u05de\u05d5 \u05ea\u05d9\u05e7\u05d5\u05df \u05d8\u05e2\u05d5\u05ea \u05db\u05ea\u05d9\u05d1, \u05e0\u05d7\u05e9\u05d1 \u05e9\u05d9\u05e0\u05d5\u05d9 \u05de\u05e1\u05d5\u05d2 \u05e9\u05e0\u05d9, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05de\u05e1\u05e4\u05d9\u05e7\u05d4 \u05d4\u05d5\u05d3\u05e2\u05d4."],[281.0,"\u05d0\u05d9\u05e9\u05d5\u05d4 \u05db\u05de\u05d5 \u05e9\u05e8\u05d0\u05d9\u05e0\u05d5 \u05d1\u05d1\u05d3\u05d9\u05e7\u05ea \u05e4\u05e8\u05d9\u05d8 \u05e8\u05d0\u05e9\u05d5\u05df \u05d1\u05e4\u05e8\u05e7 \u05ea\u05e9\u05e2 \u05e2\u05e9\u05e8\u05d4."],[290.0,"\u05d1\u05e8\u05e6\u05e4\u05d4, \u05d4\u05e9\u05d0\u05dc\u05d4 \u05d4\u05d7\u05e9\u05d5\u05d1\u05d4 \u05d4\u05d9\u05d0 \u05d0\u05d9\u05d6\u05d4 \u05e2\u05d5\u05ea\u05e7 \u05e0\u05de\u05e6\u05d0 \u05d1\u05d9\u05d3\u05d9\u05d9\u05dd."],[296.0,"\u05e2\u05d5\u05ea\u05e7 \u05de\u05d5\u05d3\u05e4\u05e1 \u05d9\u05e9\u05df \u05d4\u05d5\u05d0 \u05d0\u05d7\u05d3 \u05d4\u05de\u05e7\u05d5\u05e8\u05d5\u05ea \u05d4\u05e0\u05e4\u05d5\u05e6\u05d9\u05dd \u05dc\u05d8\u05e2\u05d5\u05d9\u05d5\u05ea. \u05dc\u05db\u05df \u05e2\u05d5\u05ea\u05e7\u05d9\u05dd \u05de\u05d5\u05d3\u05e4\u05e1\u05d9\u05dd"],[303.0,"\u05de\u05e1\u05d5\u05de\u05e0\u05d9\u05dd \u05dc\u05e2\u05d9\u05ea\u05d9\u05dd \u05db\u05e2\u05d5\u05ea\u05e7 \u05dc\u05d0 \u05de\u05d1\u05d5\u05e7\u05e8, \u05d0\u05d5 \u05e0\u05d0\u05e1\u05e4\u05d9\u05dd \u05db\u05e9\u05d9\u05d5\u05e6\u05d0\u05ea \u05e8\u05d5\u05d5\u05d9\u05d6\u05d9\u05d4 \u05d7\u05d3\u05e9\u05d4."],[310.0,"\u05ea\u05d9\u05e7\u05d5\u05df \u05d1\u05db\u05ea\u05d1 \u05d9\u05d3 \u05e2\u05dc \u05e9\u05e8\u05d8\u05d5\u05d8, \u05d1\u05dc\u05d9 \u05d4\u05d5\u05e8\u05d0\u05ea \u05e9\u05d9\u05e0\u05d5\u05d9, \u05d4\u05d5\u05d0 \u05dc\u05d0 \u05e9\u05d9\u05e0\u05d5\u05d9. \u05d4\u05d5\u05d0 \u05e8\u05e7 \u05d4\u05e2\u05e8\u05d4."],[316.0,"\u05d5\u05dc\u05db\u05df \u05dc\u05e4\u05e0\u05d9 \u05e9\u05de\u05ea\u05d7\u05d9\u05dc\u05d9\u05dd \u05e2\u05d1\u05d5\u05d3\u05d4, \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d0\u05ea \u05d4\u05e8\u05d5\u05d5\u05d9\u05d6\u05d9\u05d4 \u05de\u05d5\u05dc \u05d4\u05de\u05e2\u05e8\u05db\u05ea, \u05d5\u05dc\u05d0 \u05e8\u05e7 \u05de\u05d5\u05dc \u05d4\u05d3\u05e3 \u05e9\u05d1\u05d9\u05d3\u05d9\u05d9\u05dd."],[325.0,"\u05e8\u05d9\u05db\u05d5\u05d6 \u05d4\u05de\u05dc\u05db\u05d5\u05d3\u05d5\u05ea \u05d1\u05e0\u05d9\u05d4\u05d5\u05dc \u05e9\u05d9\u05e0\u05d5\u05d9\u05d9\u05dd."],[327.0,"\u05e2\u05d1\u05d5\u05d3\u05d4 \u05dc\u05e4\u05d9 \u05e2\u05d5\u05ea\u05e7 \u05d9\u05e9\u05df, \u05db\u05d9 \u05d4\u05d5\u05d0 \u05d4\u05d9\u05d4 \u05d6\u05de\u05d9\u05df \u05dc\u05d9\u05d3 \u05d4\u05de\u05db\u05d5\u05e0\u05d4."],[332.0,"\u05ea\u05d9\u05e7\u05d5\u05df \u05d1\u05db\u05ea\u05d1 \u05d9\u05d3 \u05e9\u05e0\u05d7\u05e9\u05d1 \u05dc\u05e9\u05d9\u05e0\u05d5\u05d9 \u05de\u05d0\u05d5\u05e9\u05e8."],[336.0,"\u05d7\u05e8\u05d9\u05d2\u05d4 \u05e9\u05de\u05e9\u05de\u05e9\u05ea \u05d0\u05d7\u05e8\u05d9 \u05e9\u05d4\u05db\u05de\u05d5\u05ea \u05d0\u05d5 \u05d4\u05ea\u05e7\u05d5\u05e4\u05d4 \u05e9\u05dc\u05d4 \u05e0\u05d2\u05de\u05e8\u05d5."],[341.0,"\u05e8\u05d5\u05d5\u05d9\u05d6\u05d9\u05d4 \u05d7\u05d3\u05e9\u05d4, \u05d1\u05de\u05e7\u05d5\u05dd \u05e9\u05d4\u05d9\u05d4 \u05e6\u05e8\u05d9\u05da \u05de\u05e7\"\u05d8 \u05d7\u05d3\u05e9."],[345.0,"\u05de\u05dc\u05d0\u05d9\u05d9\u05e9\u05df \u05e9\u05dc\u05d0 \u05d8\u05d5\u05e4\u05dc, \u05db\u05d9 \u05dc\u05d0 \u05e7\u05e8\u05d0\u05d5 \u05d0\u05ea \u05d4\u05d4\u05e0\u05d7\u05d9\u05d4 \u05dc\u05de\u05d4 \u05e9\u05db\u05d1\u05e8 \u05e7\u05d9\u05d9\u05dd."],[351.0,"\u05d5\u05e9\u05d9\u05e0\u05d5\u05d9 \u05d1\u05ea\u05d4\u05dc\u05d9\u05da, \u05d1\u05dc\u05d9 \u05dc\u05d7\u05d6\u05d5\u05e8 \u05e2\u05dc \u05d1\u05d3\u05d9\u05e7\u05ea \u05e4\u05e8\u05d9\u05d8 \u05e8\u05d0\u05e9\u05d5\u05df."],[356.0,"\u05db\u05e9\u05de\u05e7\u05d1\u05dc\u05d9\u05dd \u05e9\u05e8\u05d8\u05d5\u05d8 \u05e9\u05d4\u05e9\u05ea\u05e0\u05d4, \u05de\u05ea\u05d7\u05d9\u05dc\u05d9\u05dd \u05de\u05d8\u05d1\u05dc\u05ea \u05d4\u05e8\u05d5\u05d5\u05d9\u05d6\u05d9\u05d5\u05ea: \u05de\u05d4 \u05d4\u05e9\u05ea\u05e0\u05d4, \u05d5\u05d1\u05d0\u05d9\u05d6\u05d4 \u05d0\u05d6\u05d5\u05e8."],[364.0,"\u05d0\u05d7\u05e8 \u05db\u05da \u05de\u05d7\u05e4\u05e9\u05d9\u05dd \u05d1\u05e6\u05d9\u05d5\u05e8 \u05d0\u05ea \u05e1\u05d9\u05de\u05e0\u05d9 \u05d4\u05e8\u05d5\u05d5\u05d7\u05d6\u05d9\u05d4, \u05d5\u05de\u05e9\u05d5\u05d5\u05d9\u05dd \u05dc\u05e8\u05d5\u05d5\u05d9\u05d6\u05d9\u05d4 \u05d4\u05e7\u05d5\u05d3\u05de\u05ea."],[370.0,"\u05d0\u05d7\u05e8 \u05db\u05da \u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05d0\u05ea \u05d4\u05d5\u05e8\u05d0\u05ea \u05d4\u05e9\u05d9\u05e0\u05d5\u05d9: \u05ea\u05d7\u05d5\u05dc\u05d4, \u05d5\u05d4\u05e0\u05d7\u05d9\u05d4 \u05dc\u05de\u05d4 \u05e9\u05db\u05d1\u05e8 \u05e7\u05d9\u05d9\u05dd."],[377.0,"\u05d5\u05dc\u05d1\u05e1\u05d5\u05e3 \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05e9\u05d2\u05dd \u05d4\u05de\u05e1\u05de\u05db\u05d9\u05dd \u05d4\u05e7\u05e9\u05d5\u05e8\u05d9\u05dd \u05e2\u05d5\u05d3\u05db\u05e0\u05d5: \u05d4\u05d5\u05e8\u05d0\u05d5\u05ea \u05e2\u05d1\u05d5\u05d3\u05d4, \u05ea\u05d5\u05db\u05e0\u05d9\u05d5\u05ea \u05d1\u05d3\u05d9\u05e7\u05d4 \u05d5\u05ea\u05d5\u05db\u05e0\u05d9\u05d5\u05ea \u05e2\u05d9\u05d1\u05d5\u05d3."],[386.0,"\u05de\u05d9\u05e9\u05de\u05e2\u05d3\u05db\u05df \u05e8\u05e7 \u05d0\u05ea \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8, \u05d5\u05de\u05e9\u05d0\u05d9\u05e8 \u05d0\u05ea \u05ea\u05d5\u05db\u05e0\u05d9\u05ea \u05d4\u05de\u05d3\u05d9\u05d3\u05d4 \u05d4\u05d9\u05e9\u05e0\u05d4, \u05d9\u05de\u05d3\u05d5\u05d3 \u05d7\u05dc\u05e7 \u05d7\u05d3\u05e9\u05d5 \u05dc\u05e4\u05d9 \u05d3\u05e8\u05d9\u05e9\u05d5\u05ea \u05d9\u05e9\u05e0\u05d5\u05ea."],[394.0,"\u05d8\u05d1\u05dc\u05ea \u05d4\u05e8\u05d5\u05d5\u05d9\u05d6\u05d9\u05d5\u05ea, \u05d4\u05e1\u05d9\u05de\u05e0\u05d9\u05dd \u05d1\u05e6\u05d9\u05d5\u05e8 \u05d5\u05d4\u05d0\u05d6\u05d5\u05e8\u05d9\u05dd \u05d1\u05e9\u05d5\u05dc\u05d9\u05d9\u05dd \u05de\u05e8\u05d0\u05d9\u05dd \u05de\u05d4 \u05d4\u05e9\u05ea\u05e0\u05d4 \u05d5\u05d0\u05d9\u05e4\u05d4."],[402.0,"\u05e9\u05d9\u05e0\u05d5\u05d9 \u05e9\u05e4\u05d5\u05d2\u05e2 \u05d1\u05d4\u05d7\u05dc\u05e4\u05d4 \u05d4\u05d4\u05d3\u05d3\u05d9\u05ea \u05de\u05e7\u05d1\u05dc \u05de\u05e7\"\u05d8 \u05d7\u05d3\u05e9,, \u05d5\u05dc\u05d0 \u05e8\u05e7 \u05e8\u05d5\u05d5\u05d9\u05d6\u05d9\u05d4."],[408.0,"\u05d7\u05e8\u05d9\u05d2\u05d4 \u05d4\u05d9\u05d0 \u05d0\u05d9\u05e9\u05d5\u05e8 \u05de\u05e8\u05d0\u05e9, \u05d5\u05d9\u05ea\u05d5\u05e8 \u05d4\u05d5\u05d0 \u05d0\u05d9\u05e9\u05d5\u05e8 \u05d1\u05d3\u05d9\u05e2\u05d1\u05d3, \u05d5\u05e9\u05e0\u05d9\u05d4\u05dd \u05d7\u05dc\u05d9\u05dd \u05e8\u05e7 \u05e2\u05dc \u05de\u05d4 \u05e9\u05d4\u05d5\u05d2\u05d3\u05e8 \u05d1\u05d4\u05dd."],[417.0,"\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d7\u05d5\u05d6\u05e8 \u05de\u05d1\u05d9\u05d0 \u05dc\u05e9\u05e8\u05d8\u05d5\u05d8, \u05d5\u05ea\u05d9\u05e7\u05d5\u05df \u05de\u05e9\u05d0\u05d9\u05e8 \u05e9\u05d5\u05e0\u05d4 \u05d5\u05d3\u05d5\u05e8\u05e9 \u05d0\u05d9\u05e9\u05d5\u05e8."],[423.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05e2\u05d1\u05d5\u05e8 \u05dc\u05d7\u05dc\u05e7 \u05d4\u05d0\u05d7\u05e8\u05d5\u05df \u05e9\u05dc \u05d4\u05e7\u05d5\u05e8\u05e1, \u05d5\u05e0\u05e7\u05e8\u05d0 \u05e9\u05e8\u05d8\u05d5\u05d8 \u05de\u05e2\u05d9\u05e0\u05d9 \u05d4\u05d9\u05e6\u05e8\u05df. \u05e0\u05ea\u05e8\u05d0\u05d4 \u05d1\u05e4\u05e8\u05e7 \u05e2\u05e9\u05e8\u05d9\u05dd \u05d5\u05e9\u05ea\u05d9\u05d9\u05dd."]]};
window.MH_TR["ch22"]={"t":"\u05e7\u05e8\u05d9\u05d0\u05d4 \u05de\u05e2\u05d9\u05e0\u05d9 \u05d4\u05d9\u05e6\u05e8\u05df","l":[[1.0,"\u05e2\u05d3 \u05e2\u05db\u05e9\u05d9\u05d5 \u05e7\u05e8\u05d0\u05e0\u05d5 \u05e9\u05e8\u05d8\u05d5\u05d8\u05d9\u05dd \u05db\u05d3\u05d9 \u05dc\u05d4\u05d1\u05d9\u05df \u05de\u05d4 \u05d4\u05de\u05ea\u05db\u05e0\u05df \u05d3\u05d5\u05e8\u05e9\u05e9."],[6.0,"\u05d4\u05d9\u05e6\u05e8\u05df \u05e7\u05d5\u05e8\u05d0 \u05d0\u05ea \u05d0\u05d5\u05ea\u05d5 \u05e9\u05e8\u05d8\u05d5\u05d8 \u05e2\u05dd \u05e9\u05d0\u05dc\u05d4 \u05d0\u05d7\u05e8\u05ea: \u05d0\u05d9\u05da \u05de\u05d9\u05d9\u05e6\u05e8\u05d9\u05dd \u05d0\u05ea \u05d6\u05d4, \u05db\u05de\u05d4 \u05d6\u05d4 \u05d9\u05e2\u05dc\u05d4, \u05d5\u05de\u05d4 \u05e2\u05dc\u05d5\u05dc \u05dc\u05d4\u05e9\u05d5\u05ea\u05d1\u05e9."],[14.0,"\u05e7\u05e8\u05d9\u05d0\u05d4 \u05db\u05d6\u05d5 \u05e0\u05e2\u05e9\u05d9\u05ea \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e6\u05e2\u05ea \u05d4\u05de\u05d7\u05d9\u05e8 \u05d5\u05dc\u05e4\u05e0\u05d9 \u05e9\u05de\u05ea\u05d7\u05d9\u05dc\u05d9\u05dd \u05dc\u05e2\u05d1\u05d5\u05d3, \u05d5\u05dc\u05d0 \u05d0\u05d7\u05e8\u05d9 \u05e9\u05d4\u05d7\u05dc\u05e7 \u05db\u05d1\u05e8 \u05e2\u05dc \u05d4\u05de\u05db\u05d5\u05e0\u05d4."],[22.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05e2\u05d1\u05d5\u05e8 \u05e2\u05dc \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d1\u05e1\u05d3\u05e8 \u05e9\u05d1\u05d5 \u05d9\u05e6\u05e8\u05df \u05de\u05e0\u05d5\u05e1\u05d4 \u05e7\u05d5\u05e8\u05d0 \u05d0\u05d5\u05ea\u05d5, \u05d5\u05e0\u05e8\u05d0\u05d4 \u05de\u05d4 \u05de\u05d7\u05e4\u05e9\u05d9\u05dd \u05d1\u05db\u05dc \u05e9\u05dc\u05d1."],[31.0,"\u05d4\u05de\u05e2\u05d1\u05e8 \u05d4\u05e8\u05d0\u05e9\u05d5\u05df \u05d4\u05d5\u05d0 \u05d0\u05d6\u05d5\u05e8 \u05d4\u05db\u05d5\u05ea\u05e8\u05ea: \u05d7\u05d5\u05de\u05e8, \u05de\u05e6\u05d1, \u05db\u05de\u05d5\u05ea, \u05e8\u05d5\u05d5\u05d9\u05d6\u05d9\u05d4, \u05d5\u05ea\u05e7\u05df."],[40.0,"\u05de\u05d4\u05d7\u05d5\u05de\u05e8 \u05d5\u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05d4\u05db\u05d5\u05dc\u05dc\u05d5\u05ea \u05e0\u05e7\u05d1\u05e2 \u05d4\u05d2\u05dc\u05dd: \u05d0\u05d9\u05d6\u05d4 \u05e7\u05d5\u05d8\u05e8 \u05e9\u05dc \u05de\u05d5\u05d8, \u05d0\u05d9\u05d6\u05d4 \u05e2\u05d5\u05d1\u05d9 \u05e9\u05dc \u05dc\u05d5\u05d7, \u05d5\u05d0\u05d9\u05d6\u05d4 \u05de\u05e8\u05d5\u05d5\u05d7 \u05dc\u05e2\u05d9\u05d1\u05d5\u05d3."],[49.0,"\u05d7\u05d5\u05de\u05e8 \u05e9\u05dc\u05d0 \u05d6\u05de\u05d9\u05df \u05d1\u05de\u05d9\u05d3\u05d4 \u05d4\u05de\u05ea\u05d0\u05d9\u05de\u05d4 \u05de\u05e9\u05d5\u05e0\u05d4 \u05d0\u05ea \u05d4\u05de\u05d7\u05d9\u05e8 \u05d5\u05d0\u05ea \u05d6\u05de\u05df \u05d4\u05d0\u05e1\u05e4\u05e7\u05d4 \u05e2\u05d5\u05d3 \u05dc\u05e4\u05e0\u05d9 \u05e9\u05de\u05ea\u05d7\u05d9\u05dc\u05d9\u05dd."],[57.0,"\u05d0\u05d7\u05e8 \u05db\u05da \u05e2\u05d5\u05d1\u05e8\u05d9\u05dd \u05e2\u05dc \u05d4\u05d4\u05e2\u05e8\u05d5\u05ea: \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd, \u05e6\u05d9\u05e4\u05d5\u05d9, \u05e1\u05d9\u05de\u05d5\u05df, \u05d5\u05de\u05e1\u05de\u05db\u05d9\u05dd \u05e9\u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05de\u05e4\u05e0\u05d4 \u05d0\u05dc\u05d9\u05d4\u05dd."],[65.0,"\u05db\u05dc \u05d4\u05e4\u05e0\u05d9\u05d4 \u05db\u05d6\u05d5 \u05d4\u05d9\u05d0 \u05e2\u05d1\u05d5\u05d3\u05d4 \u05e0\u05d5\u05e1\u05e4\u05ea, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05e1\u05e4\u05e7 \u05d7\u05d9\u05e6\u05d5\u05e0\u05d9 \u05d4\u05de\u05df \u05d4\u05de\u05ea\u05e0\u05d4."],[72.0,"\u05d4\u05e9\u05d0\u05dc\u05d4 \u05d4\u05d1\u05d0\u05d4 \u05d4\u05d9\u05d0 \u05db\u05de\u05d4 \u05d3\u05e4\u05d9\u05e0\u05d5\u05ea \u05d9\u05d9\u05d3\u05e8\u05e9\u05d5."],[75.0,"\u05db\u05dc \u05e6\u05d3 \u05e9\u05dc \u05d5 \u05d4\u05d7\u05dc\u05e7 \u05e9\u05d9\u05e9 \u05d1\u05d5 \u05d0\u05dc\u05de\u05e0\u05d8\u05d9\u05dd \u05de\u05e2\u05d5\u05d1\u05d3\u05d9\u05dd \u05d5 \u05d4\u05d5\u05d0 \u05d1\u05d3\u05e8 \u05db\u05dc\u05dc \u05d3\u05e4\u05d9\u05e0\u05d4 \u05e0\u05d5\u05e1\u05e4\u05ea, \u05d5\u05dc\u05db\u05dc \u05d3\u05e4\u05d9\u05e0\u05d4 \u05d9\u05e9 \u05d6\u05de\u05df \u05db\u05d9\u05d5\u05d5\u05df."],[84.0,"\u05d4\u05e8\u05d0\u05e9\u05d9 \u05de\u05e2\u05d5\u05d1\u05d3 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05e8\u05d0\u05e9\u05d5\u05d5\u05df, \u05d5\u05de\u05e9\u05de\u05e9 \u05d1\u05e1\u05d9\u05e1 \u05dc\u05db\u05dc \u05d4\u05e9\u05d0\u05e8."],[94.0,"\u05d0\u05dc\u05de\u05e0\u05d8\u05d9\u05dd \u05e2\u05dd \u05e1\u05d1\u05d5\u05dc\u05ea \u05d4\u05d3\u05d5\u05e7\u05d4 \u05d1\u05d9\u05e0\u05d9\u05d4\u05dd \u05e2\u05d3\u05d9\u05e3 \u05dc\u05e2\u05d1\u05d3 \u05d1\u05d0\u05d5\u05ea\u05d4 \u05d3\u05e4\u05d9\u05e0\u05d4, \u05db\u05d3\u05d9 \u05dc\u05d0 \u05dc\u05d4\u05db\u05e0\u05d9\u05e1 \u05e9\u05d2\u05d9\u05d0\u05ea \u05d4\u05e2\u05d1\u05e8\u05d4."],[102.0,"\u05db\u05e9\u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d3\u05d5\u05e8\u05e9 \u05e7\u05e9\u05e8 \u05d4\u05d3\u05d5\u05e7 \u05d1\u05d9\u05df \u05e9\u05e0\u05d9 \u05e6\u05d3\u05d3\u05d9\u05dd \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7, \u05e6\u05e8\u05d9\u05da \u05dc\u05ea\u05db\u05e0\u05df \u05d0\u05d9\u05da \u05de\u05e2\u05d1\u05d9\u05e8\u05d9\u05dd \u05d0\u05ea \u05d4\u05d9\u05d9\u05d7\u05d5\u05e1 \u05d1\u05d9\u05df \u05d4\u05d3\u05e4\u05d9\u05e0\u05d5\u05ea."],[111.0,"\u05d0\u05d7\u05e8\u05d9 \u05d6\u05d4 \u05de\u05d7\u05e4\u05e9\u05d5\u05d9\u05dd \u05d0\u05ea \u05de\u05d4 \u05e9\u05e7\u05d5\u05d1\u05e2 \u05d0\u05ea \u05d4\u05ea\u05d4\u05dc\u05d9\u05da \u05d5\u05d0\u05ea \u05d4\u05e2\u05dc\u05d5\u05ea."],[116.0,"\u05d4\u05e1\u05d1\u05d5\u05dc\u05ea \u05d4\u05d4\u05d3\u05d5\u05e7\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05e7\u05d5\u05d1\u05e2\u05ea \u05dc\u05e2\u05d9\u05ea\u05d9\u05dd \u05d0\u05ea \u05db\u05dc \u05d4\u05ea\u05d4\u05dc\u05d9\u05da: \u05d4\u05e9\u05d7\u05d6\u05d4, \u05e8\u05d9\u05de\u05e8, \u05d0\u05d5 \u05e2\u05d9\u05d1\u05d5\u05d3 \u05d2\u05de\u05e8 \u05e0\u05e4\u05e8\u05d3."],[126.0,"\u05d2\u05dd \u05d7\u05e1\u05e4\u05d5\u05e1 \u05e0\u05de\u05d5\u05da, \u05d0\u05d5 \u05e1\u05d1\u05d5\u05dc\u05ea \u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05ea \u05e7\u05d8\u05e0\u05d4 \u05de\u05d0\u05d5\u05d3, \u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05e4\u05e2\u05d5\u05dc\u05d4."],[132.0,"\u05e4\u05d9\u05e0\u05d4 \u05e4\u05e0\u05d9\u05de\u05d9\u05ea \u05d7\u05d3\u05d4 \u05d1\u05db\u05d9\u05e1 \u05d4\u05d9\u05d0 \u05de\u05dc\u05db\u05d5\u05d3\u05ea \u05de\u05d5\u05db\u05e8\u05ea."],[136.0,"\u05db\u05e8\u05e1\u05d5\u05de\u05ea \u05ea\u05de\u05d9\u05d3 \u05de\u05e9\u05d0\u05d9\u05e8\u05d4 \u05e8\u05d3\u05d9\u05d5\u05e1, \u05d5\u05e4\u05d9\u05e0\u05d4 \u05d7\u05d3\u05d4 \u05d1\u05d0\u05de\u05ea \u05d3\u05d5\u05e8\u05e9\u05d5\u05ea \u05d2\u05d9\u05dc\u05d5\u05e3 \u05d7\u05e9\u05de\u05dc\u05d9."],[142.0,"\u05d5\u05dc\u05db\u05df \u05db\u05e9\u05d0\u05d9\u05df \u05e8\u05d3\u05d9\u05d5\u05e1 \u05e4\u05e0\u05d9\u05de\u05d9 \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8, \u05e9\u05d5\u05d0\u05dc\u05d9\u05dd \u05d0\u05d9\u05d6\u05d4 \u05e8\u05d3\u05d9\u05d5\u05e1 \u05de\u05d5\u05ea\u05e8, \u05dc\u05e4\u05e0\u05d9 \u05e9\u05de\u05ea\u05de\u05d7\u05e8\u05d9\u05dd."],[150.0,"\u05e7\u05d3\u05d7 \u05e2\u05de\u05d5\u05e7 \u05d5\u05e6\u05e8, \u05d1\u05d9\u05d7\u05e1 \u05e9\u05dc \u05d9\u05d5\u05ea\u05e8 \u05de\u05e2\u05e9\u05e8 \u05e4\u05e2\u05de\u05d9\u05dd \u05d4\u05e7\u05d5\u05d8\u05e8,"],[155.0,"\u05d3\u05d5\u05e8\u05e9 \u05de\u05e7\u05d3\u05d7 \u05de\u05d9\u05d5\u05d7\u05d3 \u05dc\u05e7\u05d9\u05d3\u05d5\u05d7 \u05e2\u05de\u05d5\u05e7, \u05e2\u05dd \u05e7\u05d9\u05e8\u05d5\u05e8 \u05d3\u05e8\u05da \u05d4\u05db\u05dc\u05d9, \u05d5\u05d6\u05de\u05df \u05e8\u05d1."],[161.0,"\u05d5\u05d3\u05e4\u05e0\u05d5\u05ea \u05d3\u05e7\u05d5\u05ea \u05de\u05ea\u05e2\u05d5\u05d5\u05ea\u05d5\u05ea \u05d1\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d5\u05d1\u05d3\u05e4\u05d9\u05e0\u05d4, \u05d5\u05e6\u05e8\u05d9\u05da \u05dc\u05ea\u05db\u05e0\u05df \u05d0\u05d5\u05ea\u05df \u05de\u05e8\u05d0\u05e9."],[168.0,"\u05e6\u05d9\u05e8 \u05d0\u05e8\u05d5\u05da \u05d5\u05d3\u05e7, \u05d1\u05d9\u05d7\u05e1 \u05e9\u05dc \u05d9\u05d5\u05ea\u05e8 \u05de\u05d0\u05e8\u05d1\u05e2 \u05e4\u05e2\u05de\u05d9\u05dd \u05d4\u05e7\u05d5\u05d8\u05e8, \u05d9\u05ea\u05db\u05d5\u05e4\u05e3 \u05d1\u05d7\u05e8\u05d9\u05d8\u05d4 \u05d1\u05dc\u05d9 \u05ea\u05de\u05d9\u05db\u05d4."],[175.0,"\u05d4\u05d5\u05d0 \u05d3\u05d5\u05e8\u05e9 \u05d7\u05d5\u05d3 \u05de\u05e8\u05db\u05d6 \u05d0\u05d5 \u05de\u05e9\u05e2\u05e0\u05ea, \u05d5\u05d6\u05d4 \u05de\u05e9\u05e4\u05d9\u05e2 \u05e2\u05dc \u05d4\u05d3\u05e4\u05d9\u05e0\u05d4 \u05d5\u05e2\u05dc \u05d4\u05d6\u05de\u05df."],[182.0,"\u05db\u05d9\u05e1 \u05e2\u05de\u05d5\u05e7 \u05d3\u05d5\u05e8\u05e9 \u05db\u05dc\u05d9 \u05d0\u05e8\u05d5\u05da, \u05d5\u05db\u05dc\u05d9 \u05d0\u05e8\u05d5\u05da \u05e8\u05d5\u05e2\u05d3 \u05d5\u05de\u05d2\u05d1\u05d9\u05dc \u05d0\u05ea \u05d4\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d5\u05d0\u05ea \u05d4\u05d7\u05e1\u05e4\u05d5\u05e1."],[189.0,"\u05d4\u05d1\u05e8\u05d2\u05d4 \u05e4\u05e0\u05d9\u05de\u05d9\u05ea \u05e2\u05de\u05d5\u05e7\u05d4 \u05d1\u05e7\u05d3\u05d7 \u05e2\u05d9\u05d5\u05d5\u05e8, \u05ea\u05e2\u05dc\u05d4 \u05e6\u05e8\u05d4, \u05d0\u05d5 \u05e8\u05d3\u05d9\u05d5\u05e1 \u05e7\u05d8\u05df \u05de\u05d0\u05d5\u05d3, \u05db\u05dc \u05d0\u05d7\u05d3 \u05de\u05d4\u05dd \u05d3\u05d5\u05e8\u05e9\u05d5 \u05db\u05dc\u05d9 \u05de\u05d9\u05d5\u05d7\u05d3."],[199.0,"\u05d9\u05e6\u05e8\u05df \u05e9\u05de\u05d6\u05d4\u05d4 \u05d0\u05ea \u05db\u05dc \u05d0\u05dc\u05d4 \u05de\u05e8\u05d0\u05e9\u05d5, \u05de\u05ea\u05de\u05d7\u05e8 \u05e0\u05db\u05d5\u05df \u05d5\u05de\u05ea\u05db\u05e0\u05df \u05e0\u05db\u05d5\u05df. \u05d9\u05e6\u05e8\u05df \u05e9\u05de\u05d2\u05dc\u05d4 \u05d0\u05d5\u05ea\u05dd \u05e2\u05dc \u05d4\u05de\u05db\u05d5\u05e0\u05d4, \u05de\u05e4\u05e1\u05d9\u05d3."],[209.0,"\u05db\u05de\u05d5 \u05e9\u05e8\u05d0\u05d9\u05e0\u05d5 \u05d1\u05e4\u05e8\u05e7 \u05e9\u05dc\u05d5\u05e9 \u05e2\u05e9\u05e8\u05d4, \u05d4\u05d4\u05e2\u05e8\u05d5\u05ea \u05de\u05d2\u05d3\u05d9\u05e8\u05d5\u05ea \u05e1\u05d3\u05e8 \u05e4\u05e2\u05d5\u05dc\u05d5\u05ea."],[214.0,"\u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05d1\u05d0\u05de\u05e6\u05e2 \u05d4\u05ea\u05d4\u05dc\u05d9\u05da \u05de\u05d7\u05d9\u05d9\u05d1 \u05dc\u05d4\u05e9\u05d0\u05d9\u05e8 \u05ea\u05d5\u05e1\u05e4\u05ea \u05e2\u05d9\u05d1\u05d5\u05d3, \u05d5\u05dc\u05ea\u05db\u05e0\u05df \u05e2\u05d9\u05d1\u05d5\u05d3 \u05d2\u05de\u05e8 \u05d0\u05d7\u05e8\u05d9\u05d5."],[221.0,"\u05e6\u05d9\u05e4\u05d5\u05d9 \u05d1\u05e1\u05d5\u05e3 \u05d4\u05ea\u05d4\u05dc\u05d9\u05da \u05de\u05d7\u05d9\u05d9\u05d1 \u05dc\u05d3\u05e2\u05ea \u05d0\u05dd \u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e6\u05d9\u05e4\u05d5\u05d9 \u05d0\u05d5 \u05d0\u05d7\u05e8\u05d9\u05d5, \u05d5\u05dc\u05d4\u05d2\u05df \u05e2\u05dc \u05d0\u05d6\u05d5\u05e8\u05d9\u05dd \u05e9\u05d0\u05e1\u05d5\u05e8 \u05dc\u05e6\u05e4\u05d5\u05ea."],[230.0,"\u05db\u05dc \u05e9\u05dc\u05d1 \u05d7\u05d9\u05e6\u05d5\u05e0\u05d9 \u05db\u05d6\u05d4 \u05de\u05d5\u05e1\u05d9\u05e3 \u05d6\u05de\u05df \u05d0\u05e1\u05e4\u05e7\u05d4, \u05d5\u05dc\u05db\u05df \u05d4\u05d5\u05d0 \u05d7\u05dc\u05e7 \u05de\u05d4\u05ea\u05db\u05e0\u05d5\u05df \u05d5\u05de\u05d4\u05de\u05d7\u05d9\u05e8."],[237.0,"\u05d9\u05e6\u05e8\u05df \u05de\u05e0\u05d5\u05e1\u05d4 \u05d1\u05d5\u05d3\u05e7 \u05d2\u05dd \u05d0\u05d9\u05da \u05d9\u05de\u05d3\u05d5\u05d3 \u05db\u05dc \u05de\u05d9\u05d3\u05d4, \u05e2\u05d5\u05d3 \u05dc\u05e4\u05e0\u05d9 \u05e9\u05d4\u05d5\u05d0 \u05de\u05d9\u05d9\u05e6\u05e8."],[243.0,"\u05d4\u05d0\u05dd \u05d9\u05e9 \u05dc\u05d5 \u05db\u05dc\u05d9 \u05e2\u05dd \u05db\u05d5\u05e9\u05e8 \u05d4\u05e4\u05e8\u05d3\u05d4 \u05de\u05e1\u05e4\u05d9\u05e7 \u05dc\u05e1\u05d1\u05d5\u05dc\u05ea \u05d4\u05d4\u05d3\u05d5\u05e7\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8?"],[248.0,"\u05d4\u05d0\u05dd \u05d9\u05e9 \u05de\u05d0\u05e4\u05d9\u05d9\u05e0\u05d9\u05dd \u05e7\u05e8\u05d9\u05d8\u05d9\u05d9\u05dd \u05e9\u05d3\u05d5\u05e8\u05e9\u05d9\u05dd \u05d1\u05e7\u05e8\u05d4 \u05e1\u05d8\u05d8\u05d9\u05e1\u05d8\u05d9\u05ea \u05d0\u05d5 \u05d1\u05d3\u05d9\u05e7\u05d4 \u05e9\u05dc \u05db\u05dc \u05d7\u05dc\u05e7?"],[254.0,"\u05d4\u05d0\u05dd \u05e0\u05d3\u05e8\u05e9\u05ea \u05d1\u05d3\u05d9\u05e7\u05ea \u05e4\u05e8\u05d9\u05d8 \u05e8\u05d0\u05e9\u05d5\u05df, \u05d5\u05de\u05d4 \u05d4\u05d9\u05d0 \u05db\u05d5\u05dc\u05dc\u05ea?"],[258.0,"\u05d5\u05db\u05e9\u05d4\u05d1\u05d3\u05d9\u05e7\u05d4 \u05d3\u05d5\u05e8\u05e9\u05d5\u05ea \u05e6\u05d9\u05d5\u05d3 \u05e9\u05d0\u05d9\u05df \u05dc\u05d5, \u05d4\u05d5\u05d0 \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d7\u05dc\u05d9\u05d8 \u05de\u05e8\u05d0\u05e9 \u05d0\u05dd \u05dc\u05e9\u05dc\u05d5\u05d7 \u05dc\u05d1\u05d3\u05d9\u05e7\u05d4 \u05d7\u05d9\u05e6\u05d5\u05e0\u05d9\u05ea, \u05d0\u05d5 \u05dc\u05e9\u05d0\u05d5\u05dc."],[267.0,"\u05de\u05db\u05dc \u05d4\u05de\u05e2\u05d1\u05e8 \u05d4\u05d6\u05d4 \u05e0\u05d1\u05e0\u05d9\u05ea \u05e8\u05e9\u05d9\u05de\u05ea \u05e9\u05d0\u05dc\u05d5\u05ea \u05dc\u05de\u05ea\u05db\u05e0\u05df."],[271.0,"\u05de\u05d9\u05d3\u05d5\u05ea \u05e9\u05e1\u05d5\u05ea\u05e8\u05d5\u05ea \u05d6\u05d5 \u05d0\u05ea \u05d6\u05d5, \u05e1\u05d1\u05d5\u05dc\u05d5\u05ea \u05d7\u05e1\u05e8\u05d5\u05ea, \u05de\u05e9\u05d8\u05d7 \u05d9\u05d9\u05d7\u05d5\u05e1 \u05e9\u05dc\u05d0 \u05de\u05d5\u05d2\u05d3\u05e8, \u05d0\u05d5 \u05e6\u05d9\u05e4\u05d5\u05d9 \u05d1\u05dc\u05d9 \u05e2\u05d5\u05d1\u05d9."],[279.0,"\u05d0\u05dc\u05de\u05e0\u05d8\u05d9\u05dd \u05e9\u05d0\u05d9 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d9\u05d9\u05e6\u05e8 \u05db\u05e4\u05d9 \u05e9\u05d4\u05dd \u05de\u05e6\u05d5\u05d9\u05e8\u05d9\u05dd, \u05db\u05de\u05d5 \u05e4\u05d9\u05e0\u05d4 \u05e4\u05e0\u05d9\u05de\u05d9\u05ea \u05d7\u05d3\u05d4."],[285.0,"\u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d2\u05dd \u05d4\u05e6\u05e2\u05d5\u05ea: \u05e8\u05d3\u05d9\u05d5\u05e1 \u05d2\u05d3\u05d5\u05dc \u05d9\u05d5\u05ea\u05e8, \u05e1\u05d1\u05d5\u05dc\u05ea \u05e8\u05d7\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05e9\u05dc\u05d0 \u05e4\u05d5\u05d2\u05e2\u05ea \u05d1\u05e4\u05d5\u05e0\u05e7\u05e6\u05d9\u05d4, \u05d0\u05d5 \u05d7\u05d5\u05de\u05e8 \u05d6\u05de\u05d9\u05df \u05d9\u05d5\u05ea\u05e8."],[294.0,"\u05d0\u05d1\u05dc \u05d4\u05d4\u05e6\u05e2\u05d4 \u05d4\u05d9\u05d0 \u05e9\u05d0\u05dc\u05d4, \u05dc\u05d0 \u05d4\u05d7\u05dc\u05d8\u05d4. \u05db\u05de\u05d5 \u05e9\u05e8\u05d0\u05d9\u05e0\u05d5 \u05d1\u05e4\u05e8\u05e7 \u05d0\u05e4\u05e1, \u05d9\u05e6\u05e8\u05df \u05dc\u05d0 \u05de\u05e9\u05e0\u05d4 \u05d0\u05ea \u05d4\u05e9\u05d5\u05e8\u05d8\u05d5\u05d8 \u05e2\u05dc \u05d3\u05e2\u05ea \u05e2\u05e6\u05de\u05d5."],[303.0,"\u05d5\u05e9\u05d0\u05dc\u05d4 \u05e9\u05e0\u05e9\u05d0\u05dc\u05ea \u05dc\u05e4\u05e0\u05d9 \u05d4\u05d9\u05d9\u05e6\u05d5\u05e8 \u05e2\u05d5\u05dc\u05d4 \u05d4\u05e8\u05d1\u05d4 \u05e4\u05d7\u05d5\u05ea \u05de\u05e9\u05d0\u05dc\u05d4 \u05e9\u05de\u05ea\u05d2\u05dc\u05d4 \u05d0\u05d7\u05e8\u05d9 \u05e9\u05d4\u05d7\u05dc\u05e7 \u05e0\u05e4\u05e1\u05dc."],[311.0,"\u05d1\u05d4\u05e6\u05e2\u05ea \u05de\u05d7\u05d9\u05e8, \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05de\u05ea\u05d5\u05e8\u05d2\u05dd \u05dc\u05d6\u05de\u05df \u05d5\u05dc\u05d7\u05d5\u05de\u05e8."],[316.0,"\u05d6\u05de\u05df \u05db\u05d9\u05d5\u05d5\u05df \u05dc\u05db\u05dc \u05d3\u05e4\u05d9\u05e0\u05d4 \u05de\u05ea\u05d7\u05dc\u05e7 \u05e2\u05dc \u05db\u05dc \u05d4\u05db\u05de\u05d5\u05ea, \u05d5\u05dc\u05db\u05df \u05d1\u05db\u05de\u05d5\u05ea \u05e7\u05d8\u05e0\u05d4 \u05d4\u05d5\u05d0 \u05d7\u05dc\u05e7 \u05d2\u05d3\u05d5\u05dc \u05de\u05d4\u05de\u05d7\u05d9\u05e8."],[324.0,"\u05d6\u05de\u05df \u05d4\u05de\u05d7\u05d6\u05d5\u05e8 \u05dc\u05db\u05dc \u05d7\u05dc\u05e7 \u05e0\u05e7\u05d1\u05e2 \u05d1\u05e2\u05d9\u05e7\u05e8 \u05de\u05d4\u05e1\u05d1\u05d5\u05dc\u05d5\u05ea, \u05de\u05d4\u05d7\u05e1\u05e4\u05d5\u05e1 \u05d5\u05de\u05db\u05de\u05d5\u05ea \u05d4\u05d7\u05d5\u05de\u05e8 \u05e9\u05de\u05d5\u05e1\u05e8."],[332.0,"\u05d5\u05ea\u05d4\u05dc\u05d9\u05db\u05d9\u05dd \u05de\u05d9\u05d5\u05d7\u05d3\u05d9\u05dd, \u05db\u05de\u05d5 \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd, \u05e6\u05d9\u05e4\u05d5\u05d9 \u05d5\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea, \u05de\u05d2\u05d9\u05e2\u05d9\u05dd \u05e2\u05dd \u05de\u05d7\u05d9\u05e8 \u05d5\u05d6\u05de\u05df \u05d0\u05e1\u05e4\u05e7\u05d4 \u05de\u05e9\u05dc\u05d4\u05dd."],[340.0,"\u05de\u05d9 \u05e9\u05de\u05ea\u05de\u05d7\u05e8 \u05e8\u05e7 \u05dc\u05e4\u05d9 \u05d4\u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05d4, \u05d1\u05dc\u05d9 \u05d4\u05d4\u05e2\u05e8\u05d5\u05ea, \u05de\u05e4\u05e1\u05d9\u05d3 \u05d1\u05db\u05dc \u05d7\u05dc\u05e7."],[347.0,"\u05e8\u05d9\u05db\u05d5\u05d6 \u05d4\u05de\u05dc\u05db\u05d5\u05d3\u05d5\u05ea \u05d1\u05e7\u05e8\u05d9\u05d0\u05d4 \u05de\u05e2\u05d9\u05e0\u05d9 \u05d4\u05d9\u05e6\u05e8\u05df."],[351.0,"\u05d4\u05e6\u05e2\u05ea \u05de\u05d7\u05d9\u05e8 \u05d1\u05dc\u05d9 \u05dc\u05e7\u05e8\u05d5\u05d0 \u05d0\u05ea \u05d4\u05d4\u05e2\u05e8\u05d5\u05ea \u05d5\u05d4\u05de\u05e1\u05de\u05db\u05d9\u05dd \u05d4\u05de\u05d5\u05e4\u05e0\u05d9\u05dd."],[355.0,"\u05d4\u05e0\u05d7\u05d4 \u05e9\u05d4\u05e1\u05d1\u05d5\u05dc\u05ea \u05d4\u05db\u05dc\u05dc\u05d9\u05ea \u05e8\u05d7\u05d1\u05d4, \u05d1\u05dc\u05d9 \u05dc\u05d1\u05d3\u05d5\u05e7 \u05d0\u05ea \u05d0\u05d6\u05d5\u05e8 \u05d4\u05db\u05d5\u05ea\u05e8\u05ea."],[361.0,"\u05e4\u05d9\u05e0\u05d4 \u05e4\u05e0\u05d9\u05de\u05d9\u05ea \u05d7\u05d3\u05d4, \u05d0\u05d5 \u05e7\u05d3\u05d7 \u05e2\u05de\u05d5\u05e7, \u05e9\u05d4\u05ea\u05d2\u05dc\u05d5 \u05e8\u05e7 \u05e2\u05dc \u05d4\u05de\u05db\u05d5\u05e0\u05d4."],[366.0,"\u05d5\u05e9\u05d0\u05dc\u05d5\u05ea \u05e9\u05dc\u05d0 \u05e0\u05e9\u05d0\u05dc\u05d5 \u05de\u05e8\u05d0\u05e9,, \u05d5\u05e0\u05e9\u05d0\u05dc\u05d5\u05ea \u05e8\u05e7 \u05d0\u05d7\u05e8\u05d9 \u05e9\u05d4\u05d7\u05dc\u05e7 \u05e0\u05e4\u05e1\u05dc."],[372.0,"\u05d4\u05d9\u05e6\u05e8\u05df \u05e7\u05d5\u05e8\u05d0 \u05e7\u05d5\u05d3\u05dd \u05d0\u05ea \u05d0\u05d6\u05d5\u05e8 \u05d4\u05db\u05d5\u05ea\u05e8\u05ea \u05d5\u05d4\u05d4\u05e2\u05e8\u05d5\u05ea, \u05d5\u05e7\u05d5\u05d1\u05e2 \u05d2\u05dc\u05dd, \u05d7\u05d5\u05de\u05e8 \u05d5\u05ea\u05d4\u05dc\u05d9\u05db\u05d9\u05dd \u05d7\u05d9\u05e6\u05d5\u05e0\u05d9\u05d9\u05dd."],[381.0,"\u05de\u05e2\u05e8\u05db\u05ea \u05d4\u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05e7\u05d5\u05d1\u05e2\u05ea \u05d0\u05ea \u05d4\u05d3\u05e4\u05d9\u05e0\u05d5\u05ea, \u05d5\u05e7\u05e9\u05e8\u05d9\u05dd \u05d4\u05d3\u05d5\u05e7\u05d9\u05dd \u05de\u05e2\u05d1\u05d3\u05d9\u05dd \u05d1\u05d0\u05d5\u05ea\u05d4 \u05d3\u05e4\u05d9\u05e0\u05d4."],[388.0,"\u05d4\u05e1\u05d1\u05d5\u05dc\u05ea \u05d4\u05d4\u05d3\u05d5\u05e7\u05d4, \u05d4\u05d7\u05e1\u05e4\u05d5\u05e1 \u05d5\u05d4\u05d0\u05dc\u05de\u05e0\u05d8\u05d9\u05dd \u05d4\u05e7\u05e9\u05d9\u05dd \u05e7\u05d5\u05d1\u05e2\u05d9\u05dd \u05d0\u05ea \u05d4\u05ea\u05d4\u05dc\u05d9\u05da \u05d5\u05d0\u05ea \u05d4\u05e2\u05dc\u05d5\u05ea."],[395.0,"\u05d5\u05db\u05dc \u05d0\u05d9 \u05d1\u05d4\u05d9\u05e8\u05d5\u05ea \u05d4\u05d5\u05e4\u05db\u05ea \u05dc\u05e9\u05d0\u05dc\u05d4 \u05dc\u05de\u05ea\u05db\u05e0\u05df, \u05dc\u05e4\u05e0\u05d9 \u05d4\u05d9\u05d9\u05e6\u05d5\u05e8 \u05d5\u05dc\u05d0 \u05d0\u05d7\u05e8\u05d9\u05d5."],[402.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05ea\u05e8\u05d2\u05dc \u05d0\u05ea \u05db\u05dc \u05de\u05d4 \u05e9\u05dc\u05de\u05d3\u05e0\u05d5 \u05d1\u05e1\u05d3\u05e0\u05ea \u05d0\u05d1\u05d7\u05d5\u05df: \u05e9\u05e8\u05d8\u05d5\u05d8\u05d9\u05dd \u05e2\u05dd \u05e9\u05d2\u05d9\u05d0\u05d5\u05ea, \u05d5\u05e0\u05d7\u05e4\u05e9 \u05d0\u05d5\u05ea\u05df \u05d9\u05d7\u05d3."],[410.0,"\u05e0\u05ea\u05e8\u05d0\u05d4 \u05d1\u05e4\u05e8\u05e7 \u05e2\u05e9\u05e8\u05d9\u05dd \u05d5\u05e9\u05dc\u05d5\u05e9."]]};
window.MH_TR["ch23"]={"t":"\u05e1\u05d3\u05e0\u05ea \u05d0\u05d1\u05d7\u05d5\u05df","l":[[1.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05dc\u05d0 \u05e0\u05dc\u05de\u05d3 \u05e9\u05d5\u05dd \u05d3\u05d1\u05e8 \u05d7\u05d3\u05e9. \u05e0\u05e9\u05ea\u05de\u05e9 \u05d1\u05de\u05d4 \u05e9\u05dc\u05de\u05d3\u05e0\u05d5."],[6.0,"\u05e0\u05e8\u05d0\u05d4 \u05e9\u05d9\u05e9\u05d4 \u05e9\u05e8\u05d8\u05d5\u05d8\u05d9\u05dd, \u05d5\u05d1\u05db\u05dc \u05d0\u05d7\u05d3 \u05de\u05d4\u05dd \u05d9\u05e9 \u05e9\u05d2\u05d9\u05d0\u05d4 \u05d0\u05d7\u05ea."],[12.0,"\u05d0\u05d7\u05e8\u05d9 \u05db\u05dc \u05e9\u05e8\u05d8\u05d5\u05d8 \u05e0\u05e2\u05e6\u05d5\u05e8 \u05dc\u05e8\u05d2\u05e2. \u05e0\u05e1\u05d5 \u05dc\u05de\u05e6\u05d5\u05d0 \u05d0\u05ea \u05d4\u05e9\u05d2\u05d9\u05d0\u05d4 \u05dc\u05d1\u05d3, \u05dc\u05e4\u05e0\u05d9 \u05e9\u05e0\u05d2\u05dc\u05d4 \u05d0\u05d5\u05ea\u05d4."],[18.0,"\u05d5\u05dc\u05db\u05dc \u05e9\u05d2\u05d9\u05d0\u05d4 \u05e0\u05e9\u05d0\u05dc \u05e9\u05dc\u05d5\u05e9 \u05e9\u05d0\u05dc\u05d5\u05ea: \u05de\u05d4 \u05dc\u05d0 \u05ea\u05e7\u05d9\u05df, \u05de\u05d4 \u05d9\u05d9\u05e6\u05d0 \u05de\u05d6\u05d4 \u05d1\u05d9\u05d9\u05e6\u05d5\u05e8, \u05d5\u05de\u05d4 \u05e9\u05d5\u05d0\u05dc\u05d9\u05dd \u05d0\u05ea \u05d4\u05de\u05ea\u05db\u05e0\u05df."],[28.0,"\u05dc\u05e4\u05e0\u05d9\u05db\u05dd \u05dc\u05d5\u05d7 \u05e2\u05dd \u05e9\u05dc\u05d5\u05e9 \u05de\u05d9\u05d3\u05d5\u05ea: \u05d0\u05e8\u05d1\u05e2\u05d9\u05dd, \u05e9\u05de\u05d5\u05e0\u05d9\u05dd, \u05d5\u05de\u05d0\u05d4 \u05e2\u05e9\u05e8\u05d9\u05dd \u05dc\u05db\u05dc \u05d4\u05d0\u05d5\u05e8\u05da."],[35.0,"\u05dc\u05db\u05dc \u05d0\u05d7\u05ea \u05de\u05d4\u05df \u05d9\u05e9 \u05e1\u05d1\u05d5\u05dc\u05ea \u05e9\u05dc \u05e4\u05dc\u05d5\u05e1 \u05de\u05d9\u05e0\u05d5\u05e1 \u05e2\u05e9\u05d9\u05e8\u05d9\u05ea. \u05de\u05d4 \u05dc\u05d0 \u05ea\u05e7\u05d9\u05df?"],[41.0,"\u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05e1\u05d5\u05d2\u05e8\u05d5\u05ea \u05e9\u05e8\u05e9\u05e8\u05ea. \u05d4\u05d0\u05d5\u05e8\u05da \u05d4\u05db\u05d5\u05dc\u05dc \u05de\u05d5\u05d2\u05d3\u05e8 \u05e4\u05e2\u05de\u05d9\u05d9\u05dd: \u05e4\u05e2\u05dd \u05d9\u05e9\u05d9\u05e8\u05d5\u05ea, \u05d5\u05e4\u05e2\u05dd \u05db\u05e1\u05db\u05d5\u05dd \u05e9\u05dc \u05e9\u05ea\u05d9 \u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05d4\u05d0\u05d7\u05e8\u05d5\u05ea."],[51.0,"\u05d0\u05dd \u05e9\u05ea\u05d9 \u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05d4\u05e7\u05d8\u05e0\u05d5\u05ea \u05d1\u05d2\u05d1\u05d5\u05dc \u05d4\u05e2\u05dc\u05d9\u05d5\u05df,"],[54.0,"\u05d4\u05e1\u05db\u05d5\u05dd \u05d4\u05d5\u05d0 \u05de\u05d0\u05d4 \u05e2\u05e9\u05e8\u05d9\u05dd | \u05e0\u05e7\u05d5\u05d3\u05d4 \u05e9\u05ea\u05d9\u05d9\u05dd, \u05d5\u05d6\u05d4 \u05db\u05d1\u05e8 \u05de\u05d7\u05d5 \u05dc\u05e1\u05d1\u05d5\u05dc\u05ea \u05e9\u05dc \u05d4\u05db\u05d5\u05dc\u05dc\u05ea."],[60.0,"\u05d4\u05d9\u05e6\u05e8\u05df \u05dc\u05d0 \u05d9\u05d5\u05d3\u05e2 \u05d0\u05d9\u05d6\u05d5 \u05de\u05d9\u05d3\u05d4 \u05dc\u05db\u05d1\u05d3. \u05d5\u05dc\u05db\u05df \u05e9\u05d5\u05d0\u05dc\u05d9\u05dd \u05d0\u05ea \u05d4\u05de\u05ea\u05db\u05e0\u05df \u05d0\u05d9\u05d6\u05d5 \u05de\u05d4\u05df \u05d4\u05d9\u05d0 \u05de\u05d9\u05d3\u05ea \u05d9\u05d9\u05d7\u05d5\u05e1, \u05d1\u05e1\u05d5\u05d2\u05e8\u05d9\u05d9\u05dd."],[70.0,"\u05dc\u05e4\u05e0\u05d9\u05db\u05dd \u05de\u05e1\u05d2\u05e8\u05ea \u05e1\u05d1\u05d5\u05dc\u05ea \u05de\u05d9\u05e7\u05d5\u05dd, \u05e2\u05dd \u05d4\u05e4\u05e0\u05d9\u05d4 \u05dc\u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05d0 \u05d5- 8."],[76.0,"\u05d1\u05e6\u05d9\u05d5\u05e8 \u05de\u05e1\u05d5\u05de\u05df \u05e8\u05e7 \u05de\u05e9\u05d8\u05d7 ). \u05de\u05d4 \u05dc\u05d0 \u05ea\u05e7\u05d9\u05df?"],[80.0,"\u05de\u05e9\u05d8\u05d7 \u20aa \u05dc\u05d0 \u05de\u05d5\u05d2\u05d3\u05e8 \u05d1\u05e9\u05d5\u05dd \u05de\u05e7\u05d5\u05dd \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8, \u05d5\u05dc\u05db\u05df \u05d4\u05e1\u05d1\u05d5\u05dc\u05ea \u05dc\u05d0 \u05e9\u05dc\u05de\u05d4."],[86.0,"\u05db\u05dc \u05d9\u05e6\u05e8\u05df \u05d9\u05d1\u05d7\u05e8 \u05de\u05e9\u05d8\u05d7 \u05d0\u05d7\u05e8, \u05d5\u05db\u05dc \u05de\u05db\u05d5\u05e0\u05ea \u05de\u05d3\u05d9\u05d3\u05d4 \u05ea\u05d1\u05e0\u05d4 \u05de\u05e2\u05e8\u05db\u05ea \u05d0\u05d7\u05e8\u05ea. \u05d4\u05ea\u05d5\u05e6\u05d0\u05d5\u05ea \u05dc\u05d0 \u05d9\u05d4\u05d9\u05d5 \u05e0\u05d9\u05ea\u05e0\u05d5\u05ea \u05dc\u05d4\u05e9\u05d5\u05d5\u05d0\u05d4."],[96.0,"\u05d4\u05e9\u05d0\u05dc\u05d4 \u05dc\u05de\u05ea\u05db\u05e0\u05df \u05e4\u05e9\u05d5\u05d8\u05d4: \u05d0\u05d9\u05d6\u05d4 \u05de\u05e9\u05d8\u05d7 \u05d4\u05d5\u05d0 8."],[101.0,"\u05dc\u05e4\u05e0\u05d9\u05db\u05dd \u05e7\u05d3\u05d7 \u05e2\u05dd \u05e1\u05d1\u05d5\u05dc\u05ea \u05de\u05d9\u05e7\u05d5\u05dd \u05e9\u05dc \u05e2\u05e9\u05d9\u05e8\u05d9\u05ea, \u05d1\u05d9\u05d7\u05e1 \u05dc-,/ C-1B."],[107.0,"\u05d4\u05de\u05d9\u05e7\u05d5\u05dd \u05e9\u05dc\u05d5 \u05de\u05d5\u05d2\u05d3\u05e8 \u05d1\u05de\u05d9\u05d3\u05d5\u05ea \u05e9\u05dc \u05e9\u05dc\u05d5\u05e9\u05d9\u05dd \u05d5\u05e2\u05e9\u05e8\u05d9\u05dd, \u05e2\u05dd \u05e1\u05d1\u05d5\u05dc\u05ea \u05e9\u05dc \u05e4\u05dc\u05d5\u05e1 \u05de\u05d9\u05e0\u05d5\u05e1 \u05d7\u05de\u05e9 \u05de\u05d0\u05d9\u05d5\u05ea. \u05de\u05d4 \u05dc\u05d0 \u05ea\u05e7\u05d9\u05df?"],[116.0,"\u05d1\u05e1\u05d1\u05d5\u05dc\u05ea \u05de\u05d9\u05e7\u05d5\u05dd, \u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05e9\u05de\u05d2\u05d3\u05d9\u05e8\u05d5\u05ea \u05d0\u05ea \u05d4\u05de\u05e7\u05d5\u05dd \u05e6\u05e8\u05d9\u05db\u05d5\u05ea \u05dc\u05d4\u05d9\u05d5\u05ea \u05de\u05d9\u05d3\u05d5\u05ea \u05ea\u05d0\u05d5\u05e8\u05d8\u05d9\u05d5\u05ea \u05de\u05d3\u05d5\u05d9\u05e7\u05d5\u05ea, \u05d1\u05de\u05e1\u05d2\u05e8\u05ea, \u05d1\u05dc\u05d9 \u05e1\u05d1\u05d5\u05dc\u05ea."],[126.0,"\u05db\u05d0\u05df \u05d9\u05e9 \u05e9\u05ea\u05d9 \u05d4\u05d2\u05d3\u05e8\u05d5\u05ea \u05e9\u05e1\u05d5\u05ea\u05e8\u05d5\u05ea: \u05d0\u05d6\u05d5\u05e8 \u05e8\u05d9\u05d1\u05d5\u05e2\u05d9 \u05de\u05d4\u05de\u05d9\u05d3\u05d5\u05ea, \u05d5\u05d0\u05d6\u05d5\u05e8 \u05e2\u05d2\u05d5\u05dc \u05de\u05d4\u05e1\u05d1\u05d5\u05dc\u05ea \u05d4\u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05ea."],[134.0,"\u05d4\u05d9\u05e6\u05e8\u05df \u05dc\u05d0 \u05d9\u05d5\u05d3\u05e2 \u05d0\u05d9\u05d6\u05d5 \u05dc\u05d1\u05d3\u05d5\u05e7. \u05d4\u05e9\u05d0\u05dc\u05d4 \u05dc\u05de\u05ea\u05db\u05e0\u05df: \u05d4\u05d0\u05dd \u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05d0\u05de\u05d5\u05e8\u05d5\u05ea \u05dc\u05d4\u05d9\u05d5\u05ea \u05de\u05d9\u05d3\u05d5\u05ea \u05ea\u05d0\u05d5\u05e8\u05d8\u05d9\u05d5\u05ea."],[143.0,"\u05dc\u05e4\u05e0\u05d9\u05db\u05dd \u05e7\u05d3\u05d7 \u05d1\u05d4\u05ea\u05d0\u05de\u05d4 H7, \u05d5\u05d1\u05d4\u05e2\u05e8\u05d4: \u05e6\u05d9\u05e4\u05d5\u05d9 \u05d0\u05d1\u05e5, \u05e9\u05de\u05d5\u05e0\u05d4 \u05de\u05d9\u05e7\u05e8\u05d5\u05df."],[150.0,"\u05d0\u05d9\u05df \u05e9\u05d5\u05dd \u05d4\u05e2\u05e8\u05d4 \u05e2\u05dc \u05d0\u05d6\u05d5\u05e8 \u05de\u05d5\u05d2\u05df, \u05d5\u05d0\u05d9\u05df \u05d4\u05e2\u05e8\u05d4 \u05d0\u05dd \u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e6\u05d9\u05e4\u05d5\u05d9 \u05d0\u05d5 \u05d0\u05d7\u05e8\u05d9\u05d5. \u05de\u05d4 \u05dc\u05d0 \u05ea\u05e7\u05d9\u05df?"],[158.0,"\u05e6\u05d9\u05e4\u05d5\u05d9 \u05e9\u05dc \u05e9\u05de\u05d5\u05e0\u05d4 \u05de\u05d9\u05e7\u05e8\u05d5\u05df \u05d1\u05db\u05dc \u05e6\u05d3 \u05de\u05e7\u05d8\u05d9\u05df \u05d0\u05ea \u05d4\u05e7\u05d3\u05d7 \u05d1\u05e9\u05e9 \u05e2\u05e9\u05e8\u05d4 \u05de\u05d9\u05e7\u05e8\u05d5\u05df,"],[164.0,"\u05d5\u05d7\u05d4 \u05db\u05de\u05e2\u05d8 \u05db\u05dc \u05e8\u05d5\u05d7\u05d1 \u05d4\u05e1\u05d1\u05d5\u05dc\u05ea \u05e9\u05dc H7 \u05d1\u05e7\u05d5\u05d8\u05e8 \u05db\u05d6\u05d4."],[168.0,"\u05d0\u05dd \u05de\u05e2\u05d1\u05d3\u05d9\u05dd \u05dc\u05e4\u05d9 \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d5\u05de\u05e6\u05e4\u05d9\u05dd, \u05d4\u05e7\u05d3\u05d7 \u05d9\u05d9\u05e6\u05d0 \u05de\u05d7\u05d5\u05e5 \u05dc\u05e1\u05d1\u05d5\u05dc\u05ea."],[174.0,"\u05d4\u05e9\u05d0\u05dc\u05d4 \u05dc\u05de\u05ea\u05db\u05e0\u05df: \u05d4\u05d0\u05dd \u05dc\u05d4\u05d2\u05df \u05e2\u05dc \u05d4\u05e7\u05d3\u05d7 \u05d1\u05d6\u05de\u05df \u05d4\u05e6\u05d9\u05e4\u05d5\u05d9, \u05d0\u05d5 \u05e9\u05d4\u05de\u05d9\u05d3\u05d4 \u05d7\u05dc\u05d4 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e6\u05d9\u05e4\u05d5\u05d9."],[182.0,"\u05dc\u05e4\u05e0\u05d9\u05db\u05dd \u05d4\u05d1\u05e8\u05d2\u05d4 8\u05d5\u05d0, \u05d1\u05e2\u05d5\u05de\u05e7 \u05e9\u05e9 \u05e2\u05e9\u05e8\u05d4, \u05d1\u05e7\u05d3\u05d7 \u05e2\u05d9\u05d5\u05d5\u05e8."],[188.0,"\u05e2\u05d5\u05de\u05e7 \u05d4\u05e7\u05d3\u05d7 \u05d4\u05de\u05e7\u05d3\u05d9\u05dd \u05de\u05d5\u05d2\u05d3\u05e8 \u05d2\u05dd \u05d4\u05d5\u05d0 \u05e9\u05e9\u05d5 \u05e2\u05e9\u05e8\u05d4. \u05de\u05d4 \u05dc\u05d0 \u05ea\u05e7\u05d9\u05df?"],[193.0,"\u05d4\u05e7\u05d3\u05d7 \u05d4\u05de\u05e7\u05d3\u05d9\u05dd \u05d7\u05d9\u05d9\u05d1 \u05dc\u05d4\u05d9\u05d5\u05ea \u05d0\u05e8\u05d5\u05da \u05d9\u05d5\u05ea\u05e8 \u05de\u05e2\u05d5\u05de\u05e7 \u05d4\u05d4\u05d1\u05e8\u05d2\u05d4, \u05db\u05d3\u05d9 \u05dc\u05d4\u05e9\u05d0\u05d9\u05e8 \u05de\u05e7\u05d5\u05dd \u05dc\u05e7\u05e6\u05d4 \u05d4\u05de\u05d1\u05e8\u05d6."],[201.0,"\u05d1\u05e2\u05d5\u05de\u05e7 \u05e9\u05d5\u05d5\u05d4, \u05d4\u05d4\u05d1\u05e8\u05d2\u05d4 \u05dc\u05d0 \u05ea\u05d4\u05d9\u05d4 \u05de\u05dc\u05d0\u05d4 \u05e2\u05d3 \u05d4\u05e1\u05d5\u05e3, \u05d0\u05d5 \u05e9\u05d4\u05de\u05d1\u05e8\u05d6 \u05d9\u05d9\u05d2\u05e2 \u05d1\u05ea\u05d7\u05ea\u05d9\u05ea \u05d5\u05d9\u05e9\u05d1\u05e8."],[209.0,"\u05d4\u05e9\u05d0\u05dc\u05d4 \u05dc\u05de\u05ea\u05db\u05e0\u05df: \u05de\u05d4 \u05e2\u05d5\u05de\u05e7 \u05d4\u05e7\u05d3\u05d7 \u05d4\u05de\u05e7\u05d3\u05d9\u05dd, \u05d0\u05d5 \u05de\u05d4 \u05e2\u05d5\u05de\u05e7 \u05d4\u05d4\u05d1\u05e8\u05d2\u05d4 \u05d4\u05de\u05dc\u05d0\u05d4 \u05e9\u05e0\u05d3\u05e8\u05e2\u05d5 \u05d1\u05d0\u05de\u05ea."],[218.0,"\u05dc\u05e4\u05e0\u05d9\u05db\u05dd \u05e1\u05d9\u05de\u05d5\u05df \u05e8\u05d9\u05ea\u05d5\u05da \u05e4\u05d9\u05e0\u05d4 \u05dc\u05e4\u05d9 50\u05d5, \u05e2\u05dd \u05e7\u05d5 \u05d9\u05d9\u05d7\u05d5\u05e1 \u05db\u05e4\u05d5\u05dc, \u05d5\u05d4\u05de\u05e1\u05e4\u05e8 \u05d7\u05de\u05e9 \u05de\u05e9\u05de\u05d0\u05dc \u05dc\u05de\u05e9\u05d5\u05dc\u05e9."],[226.0,"\u05de\u05d4 \u05dc\u05d0 \u05ea\u05e7\u05d9\u05df?"],[227.0,"\u05d1\u05ea\u05e7\u05df 50\u05d5, \u05dc\u05e4\u05e0\u05d9 \u05d4\u05de\u05e1\u05e4\u05e8 \u05d7\u05d9\u05d9\u05d1\u05ea \u05dc\u05d4\u05d5\u05e4\u05d9\u05e2 \u05d0\u05d5\u05ea: 8 \u05dc\u05e2\u05d5\u05d1\u05d9 \u05d4\u05d2\u05e8\u05d5\u05df, \u05d0\u05d5 ? \u05dc\u05d0\u05d5\u05e8\u05da \u05d4\u05e8\u05d2\u05dc."],[237.0,"\u05d1\u05dc\u05d9 \u05d0\u05d5\u05ea, \u05d7\u05de\u05e9 \u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05d9\u05d5\u05ea \u05e2\u05d5\u05d1\u05d9 \u05d2\u05e8\u05d5\u05df \u05e9\u05dc \u05d7\u05de\u05d9\u05e9\u05d4, \u05db\u05dc\u05d5\u05de\u05e8 \u05e8\u05d2\u05dc \u05e9\u05dc \u05d1\u05e2\u05e8\u05da \u05e9\u05d1\u05e2\u05d4, \u05d0\u05d5 \u05e8\u05d2\u05dc \u05e9\u05dc \u05d7\u05de\u05d9\u05e9\u05d4."],[247.0,"\u05d4\u05d4\u05d1\u05d3\u05dc \u05d4\u05d5\u05d0 \u05db\u05e9\u05dc\u05d5\u05e9\u05d9\u05dd \u05d0\u05d7\u05d5\u05d6 \u05d1\u05d7\u05d5\u05d6\u05e7. \u05d4\u05e9\u05d0\u05dc\u05d4 \u05dc\u05de\u05ea\u05db\u05e0\u05df: 4 \u05d0\u05d5 7."],[255.0,"\u05d1\u05db\u05dc \u05d0\u05d7\u05d3 \u05de\u05d4\u05de\u05e7\u05e8\u05d9\u05dd, \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05e0\u05e8\u05d0\u05d4 \u05e9\u05dc\u05dd \u05d1\u05de\u05d1\u05d8 \u05e8\u05d0\u05e9\u05d5\u05df."],[260.0,"\u05d4\u05e9\u05d2\u05d9\u05d0\u05d4 \u05dc\u05d0 \u05d4\u05d9\u05d9\u05ea\u05d4 \u05d1\u05e6\u05d9\u05d5\u05e8, \u05d0\u05dc\u05d0 \u05d1\u05e7\u05e9\u05e8 \u05d1\u05d9\u05df \u05e9\u05e0\u05d9 \u05e4\u05e8\u05d8\u05d9\u05dd: \u05de\u05d9\u05d3\u05d4 \u05d5\u05de\u05d9\u05d3\u05d4, \u05e1\u05d1\u05d5\u05dc\u05ea \u05d5\u05de\u05e9\u05d8\u05d7, \u05d4\u05ea\u05d0\u05de\u05d4 \u05d5\u05e6\u05d9\u05e4\u05d5\u05d9."],[270.0,"\u05d5\u05dc\u05db\u05df \u05e7\u05e8\u05d9\u05d0\u05d4 \u05d8\u05d5\u05d1\u05d4 \u05d4\u05d9\u05d0 \u05dc\u05d0 \u05e8\u05e7 \u05e7\u05e8\u05d9\u05d0\u05d4 \u05e9\u05dc \u05db\u05dc \u05e4\u05e8\u05d8, \u05d0\u05dc\u05d0 \u05d1\u05d3\u05d9\u05e7\u05d4 \u05e9\u05d4\u05e4\u05e8\u05d8\u05d9\u05dd \u05de\u05ea\u05d0\u05d9\u05de\u05d9\u05dd \u05d6\u05d4 \u05dc\u05d6\u05d4."],[277.0,"\u05d1\u05db\u05dc \u05d4\u05de\u05e7\u05e8\u05d9\u05dd, \u05d4\u05e4\u05ea\u05e8\u05d5\u05df \u05dc\u05d0 \u05d4\u05d9\u05d4 \u05dc\u05d1\u05d7\u05d5\u05e8 \u05e4\u05e8\u05e9\u05e0\u05d5\u05ea, \u05d0\u05dc\u05d0 \u05dc\u05e9\u05d0\u05d5\u05dc."],[283.0,"\u05d9\u05e6\u05e8\u05df \u05e9\u05d1\u05d5\u05d7\u05e8 \u05e4\u05e8\u05e9\u05d5\u05e0\u05d5\u05ea \u05d1\u05e2\u05e6\u05de\u05d5, \u05dc\u05d5\u05e7\u05d7 \u05e2\u05dc \u05e2\u05e6\u05de\u05d5 \u05d0\u05ea \u05d4\u05d0\u05d7\u05e8\u05d9\u05d5\u05ea \u05dc\u05ea\u05d5\u05e6\u05d0\u05d4."],[289.0,"\u05e9\u05d0\u05dc\u05d4 \u05d8\u05d5\u05d1\u05d4 \u05dc\u05de\u05ea\u05db\u05e0\u05df \u05d4\u05d9\u05d0 \u05e7\u05e6\u05e8\u05d4 \u05d5\u05d7\u05d3 \u05de\u05e9\u05de\u05e2\u05d9\u05ea."],[293.0,"\u05d4\u05d9\u05d0 \u05de\u05e6\u05d9\u05d9\u05e0\u05ea \u05d0\u05ea \u05de\u05e1\u05e4\u05e8 \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8, \u05d0\u05ea \u05d4\u05e8\u05d5\u05d5\u05d9\u05d6\u05d9\u05d4, \u05d5\u05d0\u05ea \u05d4\u05de\u05e7\u05d5\u05dd \u05d1\u05d2\u05d9\u05dc\u05d9\u05d5\u05df, \u05dc\u05e4\u05d9 \u05d4\u05d0\u05d6\u05d5\u05e8 \u05d1\u05e9\u05d5\u05dc\u05d9\u05d9\u05dd."],[301.0,"\u05d4\u05d9\u05d0 \u05de\u05ea\u05d0\u05e8\u05ea \u05d0\u05ea \u05d4\u05d1\u05e2\u05d9\u05d4 \u05d1\u05de\u05e9\u05e4\u05d8 \u05d0\u05d7\u05d3, \u05d5\u05de\u05e6\u05d9\u05e2\u05d4 \u05d0\u05e4\u05e9\u05e8\u05d5\u05ea \u05d0\u05d7\u05ea \u05d0\u05d5 \u05e9\u05ea\u05d9\u05d9\u05dd."],[307.0,"\u05dc\u05de\u05e9\u05dc: \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05de\u05e1\u05e4\u05e8 \u05db\u05d6\u05d4, \u05d1\u05e8\u05d5\u05d5\u05d9\u05d6\u05d9\u05d4 \u05e1, \u05d1\u05d0\u05d6\u05d5\u05e8 83, \u05de\u05e9\u05d8\u05d7 \u20aa \u05dc\u05d0 \u05de\u05d5\u05d2\u05d3\u05e8. \u05d4\u05d0\u05dd \u05d4\u05db\u05d5\u05d5\u05e0\u05d4 \u05dc\u05de\u05e9\u05d8\u05d7 \u05d4\u05ea\u05d7\u05ea\u05d5\u05df?"],[318.0,"\u05e9\u05d0\u05dc\u05d4 \u05db\u05d6\u05d5 \u05e0\u05e2\u05e0\u05d9\u05ea \u05de\u05d4\u05e8, \u05d5\u05d0\u05d9\u05df \u05d1\u05d4 \u05de\u05e7\u05d5\u05dd \u05dc\u05e4\u05e8\u05e9\u05e0\u05d5\u05ea."],[322.0,"\u05d5\u05e9\u05d0\u05dc\u05d4 \u05e9\u05e0\u05e9\u05d0\u05dc\u05d4 \u05d5\u05e0\u05e2\u05e0\u05ea\u05d4 \u05d1\u05db\u05ea\u05d1, \u05e0\u05e9\u05de\u05e8\u05ea \u05e2\u05dd \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8, \u05db\u05d3\u05d9 \u05e9\u05d2\u05dd \u05d4\u05d9\u05d9\u05e6\u05d5\u05e8 \u05d4\u05d1\u05d0 \u05d9\u05d3\u05e2."],[332.0,"\u05e8\u05d9\u05db\u05d5\u05d6 \u05d4\u05de\u05dc\u05db\u05d5\u05d3\u05d5\u05ea \u05d1\u05e1\u05d3\u05e0\u05d4."],[334.0,"\u05dc\u05e7\u05e8\u05d5\u05d0 \u05db\u05dc \u05e4\u05e8\u05d8 \u05d1\u05e0\u05e4\u05e8\u05d3, \u05d5\u05dc\u05d0 \u05dc\u05d1\u05d3\u05d5\u05e7 \u05d0\u05ea \u05d4\u05e7\u05e9\u05e8 \u05d1\u05d9\u05e0\u05d9\u05d4\u05dd."],[339.0,"\u05dc\u05d1\u05d7\u05d5\u05e8 \u05e4\u05e8\u05e9\u05e0\u05d5\u05ea \u05e0\u05d5\u05d7\u05d4, \u05d1\u05de\u05e7\u05d5\u05dd \u05dc\u05e9\u05d0\u05d5\u05dc."],[342.0,"\u05dc\u05e9\u05d0\u05d5\u05dc \u05d1\u05e2\u05dc \u05e4\u05d4, \u05d1\u05dc\u05d9 \u05dc\u05ea\u05e2\u05d3."],[345.0,"\u05d5\u05dc\u05ea\u05e7\u05df \u05d0\u05ea \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d1\u05e2\u05e6\u05de\u05e0\u05d5, \u05d1\u05db\u05ea\u05d1 \u05d9\u05d3, \u05db\u05d0\u05d9\u05dc\u05d5 \u05d6\u05d4 \u05e9\u05d9\u05e0\u05d5\u05d9 \u05de\u05d0\u05d5\u05e9\u05e8."],[351.0,"\u05e8\u05d0\u05d9\u05e0\u05d5 \u05e9\u05e9 \u05e9\u05d2\u05d9\u05d0\u05d5\u05ea: \u05e9\u05e8\u05e9\u05e8\u05ea \u05e1\u05d2\u05d5\u05e8\u05d4, \u05de\u05e9\u05d8\u05d7 \u05d9\u05d9\u05d7\u05d5\u05e1 \u05d7\u05e1\u05e8,"],[356.0,"\u05de\u05d9\u05e7\u05d5\u05dd \u05e2\u05dd \u05de\u05d9\u05d3\u05d5\u05ea \u05e8\u05d2\u05d9\u05dc\u05d5\u05ea, \u05e6\u05d9\u05e4\u05d5\u05d9 \u05d1\u05d4\u05ea\u05d0\u05de\u05d4, \u05e7\u05d3\u05d7 \u05de\u05e7\u05d3\u05d9\u05dd \u05e7\u05e6\u05e8, \u05d5\u05e8\u05d9\u05ea\u05d5\u05da \u05d1\u05dc\u05d9 \u05d0\u05d5\u05ea."],[365.0,"\u05d1\u05db\u05d5\u05dc\u05df \u05d4\u05e9\u05d2\u05d9\u05d0\u05d4 \u05d4\u05d9\u05d9\u05ea\u05d4 \u05d1\u05e7\u05e9\u05e8 \u05d1\u05d9\u05df \u05e4\u05e8\u05d8\u05d9\u05dd, \u05d5\u05d1\u05db\u05d5\u05dc\u05df \u05d4\u05e4\u05ea\u05e8\u05d5\u05df \u05d4\u05d9\u05d4 \u05e9\u05d0\u05dc\u05d4."],[372.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0, \u05d4\u05d0\u05d7\u05e8\u05d5\u05df \u05d1\u05e7\u05d5\u05e8\u05e1, \u05e0\u05d7\u05d1\u05e8 \u05d0\u05ea \u05db\u05dc \u05de\u05d4 \u05e9\u05dc\u05de\u05d3\u05e0\u05d5 \u05dc\u05e4\u05e8\u05d5\u05d8\u05d5\u05e7\u05d5\u05dc \u05e7\u05e8\u05d9\u05d0\u05d4 \u05de\u05dc\u05d0, \u05e6\u05e2\u05d3 \u05d0\u05d7\u05e8\u05d9 \u05e6\u05e2\u05d3."],[380.0,"\u05e0\u05ea\u05e8\u05d0\u05d4 \u05d1\u05e4\u05e8\u05e7 \u05e2\u05e9\u05e8\u05d9\u05dd \u05d5\u05d0\u05e8\u05d1\u05e2."]]};
window.MH_TR["ch24"]={"t":"\u05e4\u05e8\u05d5\u05d8\u05d5\u05e7\u05d5\u05dc \u05e7\u05e8\u05d9\u05d0\u05d4 \u05de\u05dc\u05d0","l":[[1.0,"\u05d6\u05d4 \u05d4\u05e4\u05e8\u05e7 \u05d4\u05d0\u05d7\u05e8\u05d5\u05df \u05d1\u05e7\u05d5\u05e8\u05e1."],[3.0,"\u05dc\u05d0\u05d5\u05e8\u05da \u05d4\u05e7\u05d5\u05e8\u05e1 \u05dc\u05de\u05d3\u05e0\u05d5 \u05db\u05dc \u05d7\u05dc\u05e7 \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d1\u05e0\u05e4\u05e8\u05d3: \u05de\u05d1\u05d8\u05d9\u05dd, \u05de\u05d9\u05d3\u05d5\u05ea, \u05e1\u05d1\u05d5\u05dc\u05d5\u05ea, \u05de\u05e9\u05d8\u05d7\u05d9\u05dd, \u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05d5\u05de\u05e1\u05de\u05db\u05d9\u05dd."],[14.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05d7\u05d1\u05e8 \u05d0\u05ea \u05db\u05dc \u05d6\u05d4 \u05dc\u05e4\u05e8\u05d5\u05d8\u05d5\u05e7\u05d5\u05dc \u05d0\u05d7\u05d3, \u05e2\u05e9\u05e8\u05d4 \u05e6\u05e2\u05d3\u05d9\u05dd, \u05e9\u05de\u05ea\u05d0\u05d9\u05dd \u05dc\u05db\u05dc \u05e9\u05e8\u05d8\u05d5\u05d8."],[22.0,"\u05d4\u05de\u05d8\u05e8\u05d4 \u05d4\u05d9\u05d0 \u05e9\u05dc\u05d0 \u05e0\u05d3\u05dc\u05d2 \u05e2\u05dc \u05d0\u05e3 \u05e6\u05e2\u05d3, \u05d5\u05e9\u05dc\u05d0 \u05e0\u05d2\u05dc\u05d4 \u05d1\u05e2\u05d9\u05d4 \u05e8\u05e7 \u05db\u05e9\u05d4\u05d7\u05dc\u05e7 \u05db\u05d1\u05e8 \u05e2\u05dc \u05d4\u05de\u05db\u05d5\u05e0\u05d4."],[30.0,"\u05d4\u05e6\u05e2\u05d3 \u05d4\u05e8\u05d0\u05e9\u05d5\u05df \u05d4\u05d5\u05d0 \u05dc\u05d1\u05d3\u05d5\u05e7 \u05de\u05d4 \u05d1\u05d9\u05d3\u05d9\u05d9\u05dd."],[33.0,"\u05de\u05e1\u05e4\u05e8 \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8, \u05d4\u05e8\u05d5\u05d5\u05d9\u05d6\u05d9\u05d4, \u05d5\u05de\u05e1\u05e4\u05e8 \u05d4\u05d2\u05d9\u05dc\u05d9\u05d5\u05e0\u05d5\u05ea. \u05d4\u05e8\u05d5\u05d5\u05d9\u05d6\u05d9\u05d4 \u05e6\u05e8\u05d9\u05db\u05d4 \u05dc\u05d4\u05d9\u05d5\u05ea \u05d6\u05d4\u05d4 \u05dc\u05d6\u05d5 \u05e9\u05d1\u05d4\u05d6\u05de\u05e0\u05d4."],[42.0,"\u05d5\u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d2\u05dd \u05d0\u05ea \u05de\u05e2\u05de\u05d3 \u05d4\u05de\u05e1\u05de\u05da \u05d5\u05d0\u05ea \u05d4\u05d0\u05d9\u05e9\u05d5\u05e8\u05d9\u05dd: \u05e9\u05e8\u05d8\u05d5\u05d8 \u05e9\u05dc\u05d0 \u05e9\u05d5\u05d7\u05e8\u05e8 \u05d4\u05d5\u05d0 \u05e2\u05d3\u05d9\u05d9\u05df \u05d8\u05d9\u05d5\u05d8\u05d4."],[49.0,"\u05d4\u05e6\u05e2\u05d3 \u05d4\u05e9\u05e0\u05d9 \u05d4\u05d5\u05d0 \u05dc\u05e7\u05e8\u05d5\u05d0 \u05d0\u05ea \u05d4\u05db\u05dc\u05dc\u05d9\u05dd \u05e9\u05dc\u05e4\u05d9\u05d4\u05dd \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05e0\u05db\u05ea\u05d1."],[54.0,"\u05d9\u05d7\u05d9\u05d3\u05d5\u05ea \u05d4\u05de\u05d9\u05d3\u05d4, \u05e1\u05de\u05dc \u05d4\u05d4\u05d9\u05d8\u05dc, \u05d5\u05ea\u05e7\u05df \u05d4\u05e1\u05d1\u05d5\u05dc\u05d5\u05ea, \u05e9\u05e7\u05d5\u05d1\u05e2 \u05d0\u05dd \u05d7\u05dc \u05e2\u05e7\u05e8\u05d5\u05df \u05d4\u05de\u05e2\u05d8\u05e4\u05ea \u05d0\u05d5 \u05e2\u05e7\u05e8\u05d5\u05df \u05d4\u05e2\u05e6\u05de\u05d0\u05d5\u05ea."],[64.0,"\u05d5\u05d0\u05d7\u05e8 \u05db\u05da \u05d4\u05e1\u05d1\u05d5\u05dc\u05d5\u05ea \u05d4\u05db\u05dc\u05dc\u05d9\u05d5\u05ea \u05d5\u05d4\u05d4\u05e2\u05e8\u05d5\u05ea \u05d4\u05db\u05dc\u05dc\u05d9\u05d5\u05ea. \u05d4\u05df \u05d7\u05dc\u05d5\u05ea \u05e2\u05dc \u05db\u05dc \u05de\u05d9\u05d3\u05d4 \u05e9\u05d0\u05d9\u05df \u05dc\u05d9\u05d3\u05d4 \u05e1\u05d1\u05d5\u05dc\u05ea \u05de\u05e9\u05dc\u05d4."],[73.0,"\u05d4\u05e6\u05e2\u05d3 \u05d4\u05e9\u05dc\u05d9\u05e9\u05d9 \u05d4\u05d5\u05d0 \u05d4\u05d7\u05d5\u05de\u05e8 \u05d5\u05d4\u05de\u05e6\u05d1 \u05e9\u05dc\u05d5, \u05d8\u05d9\u05e4\u05d5\u05dc \u05d4\u05d7\u05d5\u05dd, \u05d5\u05d4\u05e6\u05d9\u05e4\u05d5\u05d9."],[79.0,"\u05d5\u05d0\u05d9\u05ea\u05dd, \u05db\u05dc \u05d4\u05de\u05e1\u05de\u05db\u05d9\u05dd \u05e9\u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05de\u05e4\u05e0\u05d4 \u05d0\u05dc\u05d9\u05d4\u05dd: \u05de\u05e4\u05e8\u05d8\u05d9 \u05d7\u05d5\u05de\u05e8, \u05de\u05e4\u05e8\u05d8\u05d9 \u05ea\u05d4\u05dc\u05d9\u05da \u05d5\u05ea\u05e7\u05e0\u05d9 \u05d1\u05d3\u05d9\u05e7\u05d4."],[87.0,"\u05de\u05db\u05d0\u05df \u05db\u05d1\u05e8 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d3\u05e2\u05ea \u05de\u05d4 \u05d4\u05d2\u05dc\u05dd, \u05d0\u05d9\u05dc\u05d5 \u05ea\u05d4\u05dc\u05d9\u05db\u05d9\u05dd \u05d7\u05d9\u05e6\u05d5\u05e0\u05d9\u05d9\u05dd \u05d9\u05d9\u05d3\u05e8\u05e9\u05d5, \u05d5\u05d1\u05d0\u05d9\u05d6\u05d4 \u05e1\u05d3\u05e8."],[95.0,"\u05d4\u05e6\u05e2\u05d3 \u05d4\u05e8\u05d1\u05d9\u05e2\u05d9 \u05d4\u05d5\u05d0 \u05dc\u05d4\u05d1\u05d9\u05df \u05d0\u05ea \u05d4\u05e6\u05d5\u05e8\u05d4."],[98.0,"\u05e2\u05d5\u05d1\u05e8\u05d9\u05dd \u05e2\u05dc \u05d4\u05de\u05d1\u05d8\u05d9\u05dd \u05d5\u05d4\u05d7\u05ea\u05db\u05d9\u05dd, \u05d5\u05d1\u05d5\u05e0\u05d9\u05dd \u05d1\u05e8\u05d0\u05e9 \u05ea\u05de\u05d5\u05e0\u05d4 \u05ea\u05dc\u05ea \u05de\u05de\u05d3\u05d9\u05ea \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7."],[104.0,"\u05d5\u05e9\u05de\u05d9\u05dd \u05dc\u05d1 \u05dc\u05de\u05d5\u05e1\u05db\u05de\u05d5\u05ea \u05d5\u05dc\u05e4\u05d9\u05e9\u05d5\u05d8\u05d9\u05dd, \u05db\u05de\u05d5 \u05d4\u05d1\u05e8\u05d2\u05d5\u05ea,"],[108.0,"\u05d7\u05dc\u05e7\u05d9\u05dd \u05e1\u05d9\u05de\u05d8\u05e8\u05d9\u05d9\u05dd \u05d5\u05e7\u05d5\u05d5\u05d9\u05dd \u05de\u05d5\u05e1\u05ea\u05e8\u05d9\u05dd, \u05db\u05d3\u05d9 \u05dc\u05d0 \u05dc\u05e7\u05e8\u05d5\u05d0 \u05d0\u05d5\u05ea\u05dd \u05db\u05de\u05d5 \u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05d4 \u05e8\u05d2\u05d9\u05dc\u05d4."],[115.0,"\u05d4\u05e6\u05e2\u05d3 \u05d4\u05d7\u05de\u05d9\u05e9\u05d9 \u05d4\u05d5\u05d0 \u05de\u05e2\u05e8\u05db\u05ea \u05d4\u05de\u05e9\u05d8\u05d7\u05d9\u05dd."],[118.0,"\u05de\u05d6\u05d4\u05d9\u05dd \u05d0\u05ea \u05d4\u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05d4\u05e8\u05d0\u05e9\u05d9, \u05d4\u05e9\u05e0\u05d9 \u05d5\u05d4\u05e9\u05dc\u05d9\u05e9\u05d9, \u05d5\u05d0\u05ea \u05d4\u05e1\u05d3\u05e8 \u05d1\u05d9\u05e0\u05d9\u05d4\u05dd."],[125.0,"\u05de\u05e2\u05e8\u05db\u05ea \u05d4\u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05e7\u05d5\u05d1\u05e2\u05ea \u05d0\u05d9\u05da \u05d3\u05d5\u05e4\u05e0\u05d9\u05dd \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05d1\u05d9\u05d9\u05e6\u05d5\u05e8, \u05d5\u05d0\u05d9\u05da \u05de\u05e7\u05d1\u05e2\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05d1\u05de\u05d3\u05d9\u05d3\u05d4."],[132.0,"\u05d4\u05e6\u05e2\u05d3 \u05d4\u05e9\u05d9\u05e9\u05d9 \u05d4\u05d5\u05d0 \u05dc\u05e2\u05d1\u05d5\u05e8 \u05e2\u05dc \u05db\u05dc \u05de\u05d9\u05d3\u05d4."],[135.0,"\u05dc\u05db\u05dc \u05de\u05d9\u05d3\u05d4 \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d0\u05d9\u05d6\u05d4 \u05e1\u05d5\u05d2 \u05d4\u05d9\u05d0: \u05de\u05d9\u05d3\u05d4 \u05e2\u05dd \u05e1\u05d1\u05d5\u05dc\u05ea, \u05de\u05d9\u05d3\u05d4 \u05ea\u05d0\u05d5\u05e8\u05d8\u05d9\u05ea \u05de\u05d3\u05d5\u05d9\u05e7\u05ea, \u05d0\u05d5 \u05de\u05d9\u05d3\u05ea \u05d9\u05d9\u05d7\u05d5\u05e1."],[144.0,"\u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05e9\u05e8\u05e9\u05e8\u05d0\u05d5\u05ea \u05de\u05d9\u05d3\u05d5\u05ea, \u05d5\u05e9\u05d0\u05d9\u05df \u05de\u05d9\u05d3\u05d4 \u05e9\u05de\u05d5\u05d2\u05d3\u05e8\u05ea \u05e4\u05e2\u05de\u05d9\u05d9\u05dd."],[149.0,"\u05d5\u05d1\u05d4\u05ea\u05d0\u05de\u05d5\u05ea, \u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05d0\u05ea \u05d4\u05e7\u05d5\u05d3, \u05d5\u05de\u05d1\u05d9\u05e0\u05d9\u05dd \u05d0\u05dd \u05d6\u05d4 \u05de\u05e8\u05d5\u05d5\u05d7, \u05de\u05e2\u05d1\u05e8 \u05d0\u05d5 \u05d7\u05e4\u05d9\u05e4\u05d4."],[156.0,"\u05d4\u05e6\u05e2\u05d3 \u05d4\u05e9\u05d1\u05d9\u05e2\u05d9 \u05d4\u05d5\u05d0 \u05dc\u05e2\u05d1\u05d5\u05e8 \u05e2\u05dc \u05db\u05dc \u05de\u05e1\u05d2\u05e8\u05ea \u05e1\u05d1\u05d5\u05dc\u05ea."],[160.0,"\u05d1\u05db\u05dc \u05de\u05e1\u05d2\u05e8\u05ea \u05e9\u05d5\u05d0\u05dc\u05d9\u05dd: \u05e2\u05dc \u05de\u05d4 \u05d4\u05d9\u05d0 \u05d7\u05dc\u05d4, \u05de\u05d4 \u05e6\u05d5\u05e8\u05ea \u05d4\u05d0\u05d6\u05d5\u05e8, \u05d1\u05d9\u05d7\u05e1 \u05dc\u05d0\u05d9\u05dc\u05d5 \u05de\u05e9\u05d8\u05d7\u05d9\u05dd, \u05d5\u05d0\u05dd \u05d9\u05e9 \u05e1\u05d9\u05de\u05df MMC \u05d0\u05d5 LMC."],[171.0,"\u05d5\u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05e9\u05db\u05dc \u05de\u05e9\u05d8\u05d7 \u05d9\u05d9\u05d7\u05d5\u05e1 \u05e9\u05de\u05d5\u05e4\u05d9\u05e2 \u05d1\u05de\u05e1\u05d2\u05e8\u05ea \u05d0\u05db\u05df \u05de\u05e1\u05d5\u05de\u05df \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8."],[178.0,"\u05d4\u05e6\u05e2\u05d3 \u05d4\u05e9\u05de\u05d9\u05e0\u05d9 \u05d4\u05d5\u05d0 \u05db\u05dc \u05de\u05d4 \u05e9\u05de\u05d5\u05d2\u05d3\u05e8 \u05d1\u05e1\u05d9\u05de\u05e0\u05d9\u05dd \u05d5\u05d1\u05d4\u05e4\u05e0\u05d9\u05d5\u05ea."],[183.0,"\u05d7\u05e1\u05e4\u05d5\u05e1 \u05d5\u05e1\u05d9\u05de\u05e0\u05d9 \u05e4\u05e0\u05d9 \u05e9\u05d8\u05d7, \u05d4\u05d1\u05e8\u05d2\u05d5\u05ea \u05d5\u05e7\u05d3\u05d7\u05d9\u05dd \u05de\u05e7\u05d3\u05d9\u05de\u05d9\u05dd, \u05e8\u05d9\u05ea\u05d5\u05db\u05d9\u05dd, \u05e4\u05d9\u05e0\u05d5\u05ea, \u05ea\u05e2\u05dc\u05d5\u05ea \u05d5\u05e1\u05e4\u05dc\u05d9\u05d9\u05e0\u05d9\u05dd."],[192.0,"\u05db\u05d0\u05df \u05e0\u05de\u05e6\u05d0\u05d5\u05ea \u05d4\u05e8\u05d1\u05d4 \u05de\u05d4\u05e9\u05d2\u05d9\u05d0\u05d5\u05ea \u05e9\u05e8\u05d0\u05d9\u05e0\u05d5 \u05d1\u05e1\u05d3\u05e0\u05ea \u05d4\u05d0\u05d1\u05d7\u05d5\u05df, \u05db\u05d9 \u05d4\u05df\u05e0\u05e8\u05d0\u05d5\u05ea \u05e7\u05d8\u05e0\u05d5\u05ea."],[198.0,"\u05d4\u05e6\u05e2\u05d3 \u05d4\u05ea\u05e9\u05d9\u05e2\u05d9 \u05d4\u05d5\u05d0 \u05dc\u05d6\u05d4\u05d5\u05ea \u05de\u05d0\u05e4\u05d9\u05d9\u05e0\u05d9\u05dd \u05e7\u05e8\u05d9\u05d8\u05d9\u05d9\u05dd, \u05d5\u05dc\u05ea\u05db\u05e0\u05df \u05d0\u05ea \u05d4\u05d1\u05d3\u05d9\u05e7\u05d4."],[203.0,"\u05d0\u05d9\u05dc\u05d5 \u05de\u05d9\u05d3\u05d5\u05ea \u05de\u05e1\u05d5\u05de\u05e0\u05d5\u05ea \u05db\u05e7\u05e8\u05d9\u05d8\u05d9\u05d5\u05ea, \u05d5\u05de\u05d4 \u05d4\u05df \u05d3\u05d5\u05e8\u05e9\u05d5\u05ea: \u05d1\u05e7\u05e8\u05d4, \u05ea\u05d9\u05e2\u05d5\u05d3, \u05d0\u05d5 \u05d1\u05d3\u05d9\u05e7\u05d4 \u05e9\u05dc \u05db\u05dc \u05d7\u05dc\u05e7."],[211.0,"\u05d4\u05d0\u05dd \u05e0\u05d3\u05e8\u05e9\u05ea \u05d1\u05d3\u05d9\u05e7\u05ea \u05e4\u05e8\u05d9\u05d8 \u05e8\u05d0\u05e9\u05d5\u05df, \u05d5\u05d4\u05d0\u05dd \u05d9\u05e9 \u05db\u05dc\u05d9 \u05de\u05d3\u05d9\u05d3\u05d4 \u05de\u05ea\u05d0\u05d9\u05dd \u05dc\u05db\u05dc \u05e1\u05d1\u05d5\u05dc\u05ea."],[218.0,"\u05d4\u05e6\u05e2\u05d3 \u05d4\u05e2\u05e9\u05d9\u05e8\u05d9 \u05d4\u05d5\u05d0 \u05dc\u05d0\u05e1\u05d5\u05e3 \u05d0\u05ea \u05db\u05dc \u05de\u05d4 \u05e9\u05dc\u05d0 \u05d1\u05e8\u05d5\u05e8."],[222.0,"\u05db\u05dc \u05e1\u05ea\u05d9\u05e8\u05d4, \u05db\u05dc \u05e1\u05d1\u05d5\u05dc\u05ea \u05d7\u05e1\u05e8\u05d4, \u05d5\u05db\u05dc \u05d0\u05dc\u05de\u05e0\u05d8 \u05e9\u05d0\u05d9 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d9\u05d9\u05e6\u05e8 \u05db\u05e1\u05d9 \u05e9\u05d4\u05d5\u05d0 \u05de\u05e6\u05d5\u05d9\u05e8, \u05d4\u05d5\u05e4\u05db\u05d9\u05dd \u05dc\u05e9\u05d0\u05dc\u05d4."],[230.0,"\u05d4\u05e9\u05d0\u05dc\u05d4 \u05db\u05d5\u05dc\u05dc\u05ea \u05de\u05e1\u05e4\u05e8 \u05e9\u05e8\u05d8\u05d5\u05d8, \u05e8\u05d5\u05d5\u05d9\u05d6\u05d9\u05d4 \u05d5\u05d0\u05d6\u05d5\u05e8, \u05d5\u05e0\u05e9\u05dc\u05d7\u05ea \u05dc\u05de\u05ea\u05db\u05e0\u05df \u05dc\u05e4\u05e0\u05d9 \u05e9\u05de\u05ea\u05d7\u05d9\u05dc\u05d9\u05dd."],[238.0,"\u05d5\u05d4\u05ea\u05e9\u05d5\u05d1\u05d5\u05ea \u05e0\u05e9\u05de\u05e8\u05d5\u05ea \u05d1\u05db\u05ea\u05d1, \u05e2\u05dd \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8."],[242.0,"\u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d4\u05e8\u05db\u05d1\u05d4, \u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05dc\u05e4\u05e8\u05d5\u05d8\u05d5\u05e7\u05d5\u05dc \u05d0\u05ea \u05e8\u05e9\u05d9\u05de\u05ea \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd, \u05d4\u05d1\u05dc\u05d5\u05e0\u05d9\u05dd, \u05d4\u05e2\u05e8\u05d5\u05ea \u05d4\u05d4\u05e8\u05db\u05d1\u05d4 \u05d5\u05d4\u05de\u05d5\u05de\u05e0\u05d8\u05d9\u05dd."],[251.0,"\u05d1\u05de\u05d5\u05d3\u05dc \u05e18\u05d5\u05d0, \u05d4\u05e6\u05e2\u05d3\u05d9\u05dd \u05d6\u05d4\u05d9\u05dd, \u05d0\u05d1\u05dc \u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05d0\u05d5\u05ea\u05dd \u05de\u05d4\u05ea\u05e6\u05d5\u05d2\u05d5\u05ea \u05d5\u05de\u05d4-\u05d5\u05d5\u05d0\u05e1, \u05d5\u05dc\u05d0 \u05de\u05d2\u05d9\u05dc\u05d9\u05d5\u05df."],[260.0,"\u05d5\u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05e9\u05d4\u05e9\u05ea\u05e0\u05d4, \u05de\u05ea\u05d7\u05d9\u05dc\u05d9\u05dd \u05de\u05d8\u05d1\u05dc\u05ea \u05d4\u05e8\u05d5\u05d5\u05d9\u05d6\u05d9\u05d5\u05ea, \u05d5\u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05de\u05d4 \u05d4\u05e9\u05ea\u05e0\u05d4 \u05d5\u05de\u05d4 \u05d4\u05ea\u05d7\u05d5\u05dc\u05d4."],[269.0,"\u05d0\u05e4\u05e9\u05e8 \u05dc\u05e9\u05d0\u05d5\u05dc \u05dc\u05de\u05d4 \u05e6\u05e8\u05d9\u05da \u05e4\u05e8\u05d5\u05d8\u05d5\u05e7\u05d5\u05dc, \u05d0\u05dd \u05d9\u05d5\u05d3\u05e2\u05d9\u05dd \u05dc\u05e7\u05e8\u05d5\u05d0 \u05e9\u05e8\u05d8\u05d5\u05d8."],[273.0,"\u05d4\u05ea\u05e9\u05d5\u05d1\u05d4 \u05d4\u05d9\u05d0 \u05e9\u05e8\u05d5\u05d1 \u05d4\u05d8\u05e2\u05d5\u05d9\u05d5\u05ea \u05e9\u05e8\u05d0\u05d9\u05e0\u05d5 \u05d1\u05e7\u05d5\u05e8\u05e1 \u05dc\u05d0 \u05e0\u05d1\u05e2\u05d5 \u05de\u05d7\u05d5\u05e1\u05e8 \u05d9\u05d3\u05e2, \u05d0\u05dc\u05d0 \u05de\u05e6\u05e2\u05d3 \u05e9\u05d3\u05d9\u05dc\u05d2\u05d5 \u05e2\u05dc\u05d9\u05d5."],[281.0,"\u05e8\u05d5\u05d5\u05d9\u05d6\u05d9\u05d4 \u05e9\u05dc\u05d0 \u05e0\u05d1\u05d3\u05e7\u05d4, \u05d4\u05e2\u05e8\u05d4 \u05db\u05dc\u05dc\u05d9\u05ea \u05e9\u05dc\u05d0 \u05e0\u05e7\u05e8\u05d0\u05d4, \u05d0\u05d5 \u05de\u05e9\u05d8\u05d7 \u05d9\u05d9\u05d7\u05d5\u05e1 \u05e9\u05d0\u05e3 \u05d0\u05d7\u05d3 \u05dc\u05d0 \u05e9\u05dd \u05dc\u05d1 \u05e9\u05d7\u05e1\u05e8."],[289.0,"\u05e4\u05e8\u05d5\u05d8\u05d5\u05e7\u05d5\u05dc \u05e7\u05d1\u05d5\u05e2 \u05d4\u05d5\u05e4\u05da \u05d0\u05ea \u05d4\u05e7\u05e8\u05d9\u05d0\u05d4 \u05dc\u05e9\u05d2\u05e8\u05d4, \u05d5\u05e9\u05d2\u05e8\u05d4 \u05d4\u05d9\u05d0 \u05de\u05d4 \u05e9\u05de\u05d5\u05e0\u05e2 \u05d8\u05e2\u05d5\u05d9\u05d5\u05ea."],[296.0,"\u05d1\u05e7\u05d5\u05e8\u05e1 \u05d4\u05d6\u05d4 \u05d4\u05ea\u05d7\u05dc\u05e0\u05d5 \u05de\u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05db\u05d7\u05d5\u05d6\u05d4, \u05d5\u05e2\u05d1\u05e8\u05e0\u05d5 \u05d3\u05e8\u05da \u05db\u05dc \u05d4\u05e9\u05e4\u05d4 \u05e9\u05dc\u05d5."],[302.0,"\u05de\u05d1\u05d8\u05d9\u05dd \u05d5\u05d7\u05ea\u05db\u05d9\u05dd, \u05de\u05d9\u05d3\u05d5\u05ea \u05d5\u05e1\u05d1\u05d5\u05dc\u05d5\u05ea, \u05d4\u05ea\u05d0\u05de\u05d5\u05ea \u05d5\u05e9\u05e8\u05e9\u05e8\u05d0\u05d5\u05ea, \u05de\u05e2\u05e8\u05db\u05d5\u05ea \u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05d5\u05e1\u05d1\u05d5\u05dc\u05d5\u05ea \u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05d5\u05ea."],[311.0,"\u05e4\u05e0\u05d9 \u05e9\u05d8\u05d7, \u05e8\u05d9\u05ea\u05d5\u05db\u05d9\u05dd, \u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05d5\u05d4\u05d1\u05e8\u05d2\u05d5\u05ea, \u05d5\u05d0\u05d7\u05e8 \u05db\u05da \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05db\u05de\u05e1\u05de\u05da:"],[318.0,"\u05db\u05d5\u05ea\u05e8\u05ea, \u05d4\u05e8\u05db\u05d1\u05d4, \u05ea\u05d4\u05dc\u05d9\u05db\u05d9\u05dd, \u05d1\u05d3\u05d9\u05e7\u05d4, \u05de\u05d5\u05d3\u05dc \u05d5\u05e9\u05d9\u05e0\u05d5\u05d9\u05d9\u05dd."],[324.0,"\u05d5\u05d1\u05e1\u05d5\u05e3, \u05e7\u05e8\u05d9\u05d0\u05d4 \u05de\u05e2\u05d9\u05e0\u05d9 \u05d4\u05d9\u05e6\u05e8\u05df, \u05e1\u05d3\u05e0\u05ea \u05d0\u05d1\u05d7\u05d5\u05df, \u05d5\u05e4\u05e8\u05d5\u05d8\u05d5\u05e7\u05d5\u05dc \u05d0\u05d7\u05d3 \u05e9\u05de\u05d7\u05d1\u05e8 \u05d0\u05ea \u05d4\u05db\u05d5\u05dc."],[332.0,"\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d4\u05d5\u05d0 \u05d7\u05d5\u05d6\u05d4. \u05de\u05d9 \u05e9\u05e7\u05d5\u05e8\u05d0 \u05d0\u05d5\u05ea\u05d5 \u05d1\u05e9\u05dc\u05de\u05d5\u05ea, \u05de\u05d9\u05d9\u05e6\u05e8 \u05d0\u05ea \u05de\u05d4 \u05e9\u05e0\u05d3\u05e8\u05e2\u05e9\u05d5, \u05d5\u05e9\u05d5\u05d0\u05dc \u05dc\u05e4\u05e0\u05d9 \u05e9\u05d4\u05d5\u05d0 \u05d8\u05d5\u05e2\u05d4."],[340.0,"\u05ea\u05d5\u05d3\u05d4 \u05e9\u05dc\u05de\u05d3\u05ea\u05dd \u05d0\u05d9\u05ea\u05e0\u05d5."],[342.0,"\u05d0\u05ea \u05db\u05dc \u05e4\u05e8\u05e7\u05d9 \u05d4\u05e7\u05d5\u05e8\u05e1, \u05d5\u05e2\u05d5\u05d3 \u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05d1\u05d4\u05e0\u05d3\u05e1\u05ea \u05de\u05db\u05d5\u05e0\u05d5\u05ea, \u05d0\u05e4\u05e9\u05e8 \u05dc\u05de\u05e6\u05d5\u05d0 HUB-2 \u05d36\u05d5\u05d0."],[349.0,"\u05d1\u05d4\u05e6\u05dc\u05d7\u05d4 \u05d1\u05e7\u05e8\u05d9\u05d0\u05ea \u05d4\u05e9\u05d5\u05e8\u05d8\u05d5\u05d8 \u05d4\u05d1\u05d0."],[351.0,"\u05dc\u05d4\u05ea\u05e8\u05d0\u05d5\u05ea."]]};
